#!/usr/bin/env python3
"""Release one window's labels only after its causal Agent state freeze.

This script does not evaluate performance.  It creates the minimum governed
label artifact required for legally visible evidence to enter later windows.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import sys
from pathlib import Path
from typing import Any, Iterable
from zoneinfo import ZoneInfo

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from experiments.audit_jsac_unified_chronological_split import timing_projection
from experiments.freeze_jsac_phase4b_policy_decisions import assert_no_forbidden_target_fields
from pipeline.common import io as cio
from pipeline.evaluation.jsac_phase4_layer2 import execution_class, primary_risk_eligible, ticket_outcome


DEFAULT_CONFIG = ROOT / "experiments/config/jsac_two_timescale/phase5_unified_continual_replay.v2_1.json"


def read_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def read_jsonl(path: Path) -> list[dict[str, Any]]:
    return list(cio.read_jsonl(path))


def sha256_path(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def source_ref(path: Path) -> dict[str, Any]:
    return {"path": str(path.relative_to(ROOT)), "size_bytes": path.stat().st_size, "sha256": sha256_path(path)}


def verify_ref(item: dict[str, Any]) -> Path:
    path = ROOT / item["path"]
    if not path.exists() or sha256_path(path) != item["sha256"]:
        raise ValueError(f"frozen artifact hash failed: {item['path']}")
    return path


def write_json(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def write_jsonl(path: Path, rows: Iterable[dict[str, Any]]) -> dict[str, Any]:
    path.parent.mkdir(parents=True, exist_ok=True)
    count = 0
    with path.open("w", encoding="utf-8") as handle:
        for row in rows:
            handle.write(json.dumps(row, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n")
            count += 1
    return source_ref(path) | {"rows": count}


def id_hash(values: Iterable[str]) -> str:
    return hashlib.sha256("\n".join(sorted(str(value) for value in values)).encode()).hexdigest()


def verify_existing_reveal(path: Path, window_id: str) -> dict[str, Any]:
    manifest = read_json(path)
    if manifest.get("window_id") != window_id or not all((manifest.get("integrity") or {}).values()):
        raise ValueError("existing causal reveal manifest failed integrity")
    verify_ref(manifest["artifacts"]["revealed_labels"])
    return manifest


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--config", type=Path, default=DEFAULT_CONFIG)
    parser.add_argument("--window-id", required=True)
    args = parser.parse_args()
    config_path = args.config if args.config.is_absolute() else ROOT / args.config
    config = read_json(config_path)
    split_path = ROOT / config["outputs"]["split_audit"]
    split = read_json(split_path)
    window = next((row for row in split["replay"]["windows"] if row["window_id"] == args.window_id), None)
    if window is None:
        raise ValueError(f"unknown Replay window: {args.window_id}")
    result_root = ROOT / config["outputs"]["result_root"]
    prepare_root = result_root / "windows" / args.window_id / "prepare"
    reveal_root = result_root / "windows" / args.window_id / "reveal"
    reveal_manifest_path = reveal_root / "manifest.json"
    if reveal_manifest_path.exists():
        existing = verify_existing_reveal(reveal_manifest_path, args.window_id)
        print(json.dumps({
            "status": "EXISTING_WINDOW_REVEAL_REVERIFIED",
            "window_id": args.window_id,
            "schema_version": existing["schema_version"],
            "manifest": str(reveal_manifest_path.relative_to(ROOT)),
        }, ensure_ascii=False, indent=2))
        return
    if reveal_root.exists() and any(reveal_root.iterdir()):
        raise ValueError(f"partial reveal directory exists without manifest: {reveal_root}")

    prepare_manifest_path = prepare_root / "manifest.json"
    prepare = read_json(prepare_manifest_path)
    if prepare.get("window_id") != args.window_id or not all(prepare["integrity"].values()):
        raise ValueError("window preparation did not pass")
    for item in prepare["artifacts"].values():
        verify_ref(item)
    deterministic_path = verify_ref(prepare["artifacts"]["deterministic_decisions"])
    decisions = read_jsonl(deterministic_path)
    for row in decisions:
        assert_no_forbidden_target_fields(row)
    target_ids = sorted(str(row["trace_id"]) for row in decisions)
    if len(target_ids) != int(window["target_count"]) or id_hash(target_ids) != window["target_id_sha256"]:
        raise ValueError("frozen deterministic target population changed")

    state_freeze_path = prepare_root / "agent_state_freeze_manifest_v2_1.json"
    state_freeze = read_json(state_freeze_path)
    if state_freeze.get("window_id") != args.window_id or not all(state_freeze["integrity"].values()):
        raise ValueError("causal Agent-visible state freeze did not pass")
    for item in state_freeze["artifacts"].values():
        verify_ref(item)
    if int(state_freeze["counts"]["logical_agent_decisions"]) != int(prepare["population"]["logical_agent_decisions"]):
        raise ValueError("Agent state freeze does not cover every logical call")

    pre_reveal_audit = {
        "schema_version": "jsac.unified_state_freeze_pre_reveal_audit.v2_1",
        "status": "PASSED — WINDOW OUTCOME MAY ENTER CAUSAL UPDATE STREAM; GPT POLICY READOUT REMAINS PENDING",
        "window_id": args.window_id,
        "checks": {
            "prepare_manifest_and_artifacts_verified": True,
            "all_deterministic_targets_frozen_before_outcome_access": True,
            "deterministic_decisions_contain_no_target_outcome": True,
            "all_agent_visible_states_frozen_before_outcome_access": True,
            "agent_state_freeze_protocol_equals_v2_prompt": True,
            "gpt_choice_has_no_causal_effect_on_future_memory_or_observed_outcome": bool(config["agent_secondary"]["policy_choice_affects_future_memory_or_candidates"] is False),
            "performance_not_evaluated_during_causal_advance": True,
        },
        "sources": {
            "config": source_ref(config_path),
            "split_audit": source_ref(split_path),
            "prepare_manifest": source_ref(prepare_manifest_path),
            "agent_state_freeze_manifest": source_ref(state_freeze_path),
        },
    }
    if not all(pre_reveal_audit["checks"].values()):
        raise ValueError("causal pre-reveal audit failed")
    reveal_root.mkdir(parents=True, exist_ok=True)
    audit_path = reveal_root / "state_freeze_pre_reveal_audit.json"
    write_json(audit_path, pre_reveal_audit)

    # Target outcome access begins only after every freeze above has passed.
    target_set = set(target_ids)
    targets: dict[str, dict[str, Any]] = {}
    for spec in config["source"]["canonical_partitions"]:
        for trace in cio.read_jsonl(ROOT / spec["path"]):
            trace_id = str(trace.get("trace_id") or "")
            if trace_id in target_set:
                targets[trace_id] = trace
    if set(targets) != target_set:
        raise ValueError("window targets cannot be reconstructed for causal outcome release")

    timezone = ZoneInfo(str(config["time_contract"]["timezone"]))
    delay_days = int(config["time_contract"]["visibility_delay_days"])
    label_rows: list[dict[str, Any]] = []
    for trace_id in target_ids:
        trace = targets[trace_id]
        timing = timing_projection(trace, timezone, delay_days)
        label_rows.append({
            "trace_id": trace_id,
            "window_id": args.window_id,
            "target_outcome": ticket_outcome(trace),
            "execution_class": execution_class(trace),
            "primary_risk_eligible": primary_risk_eligible(trace),
            "site_name": str((trace.get("ticket") or {}).get("site_name") or trace_id),
            "visible_at": timing["visible_at"].isoformat() if timing["visible_at"] is not None else None,
        })
    labels_ref = write_jsonl(reveal_root / "revealed_labels.jsonl", label_rows)
    reveal_manifest = {
        "schema_version": "jsac.unified_replay_window_causal_reveal.v2_1",
        "status": "WINDOW_CAUSAL_OUTCOME_RELEASED_AFTER_AGENT_STATE_FREEZE; POLICY_READOUT_AND_EVALUATION_PENDING",
        "window_id": args.window_id,
        "artifacts": {
            "revealed_labels": labels_ref,
            "state_freeze_pre_reveal_audit": source_ref(audit_path),
        },
        "sources": {
            "prepare_manifest": source_ref(prepare_manifest_path),
            "agent_state_freeze_manifest": source_ref(state_freeze_path),
        },
        "integrity": {
            "all_deterministic_decisions_precede_outcome_release": True,
            "all_agent_visible_states_precede_outcome_release": True,
            "all_window_targets_released_once": len(label_rows) == len(target_ids),
            "future_memory_admission_still_requires_strict_seven_day_visibility": True,
            "no_performance_result_computed_during_causal_advance": True,
            "gpt_policy_readout_pending": True,
        },
        "next_gate": "prepare the next chronological window; after W29 globally exact-deduplicate immutable states and collect the delayed GPT policy readout",
    }
    write_json(reveal_manifest_path, reveal_manifest)
    print(json.dumps({
        "status": reveal_manifest["status"],
        "window_id": args.window_id,
        "released_target_count": len(label_rows),
        "performance_disclosed": False,
        "manifest": str(reveal_manifest_path.relative_to(ROOT)),
    }, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Gold-blind audit of Agent-visible candidate fields versus binary evaluator identity."""
from __future__ import annotations

import argparse
import hashlib
import json
from collections import Counter
from pathlib import Path
from typing import Any


ROOT = Path(__file__).resolve().parents[1]
DEFAULT_RESULT_ROOT = ROOT / "experiments/results/jsac_unified_continual_replay_20260824"


def read_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def read_jsonl(path: Path) -> list[dict[str, Any]]:
    return [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]


def sha256_path(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def source_ref(path: Path) -> dict[str, Any]:
    return {"path": str(path.relative_to(ROOT)), "size_bytes": path.stat().st_size, "sha256": sha256_path(path)}


def norm(value: Any) -> str:
    return str(value if value is not None else "").strip().lower()


def evaluator_binary_signature(action: dict[str, Any]) -> tuple[str, str, str]:
    """Fields that can change strong/weak hit versus contradictory/unverifiable.

    `best_action_equivalence` counts both strongly_verifiable and
    weakly_verifiable as a hit. Exact value/boundary agreement can upgrade weak
    to strong but cannot independently change the binary endpoint.
    """
    parameter = norm(
        action.get("parameter_semantic_id")
        or action.get("parameter_semantic_key")
        or action.get("param_cn_name")
        or action.get("parameter_name")
    )
    return norm(action.get("scheme_id")), parameter, norm(action.get("direction"))


def visible_action_signature(candidate: dict[str, Any]) -> tuple[str, ...]:
    """Model-visible semantic fields, excluding alias/rank and Memory evidence."""
    return tuple(
        norm(candidate.get(key))
        for key in ("scheme", "parameter", "semantic", "object", "direction", "transition", "scope", "companions")
    )


def pair_identifiability(
    local_candidates: list[dict[str, Any]],
    visible_candidates: list[dict[str, Any]],
) -> dict[str, Any]:
    local_by_alias = {str(row["alias"]): row for row in local_candidates}
    visible_by_alias = {str(row["alias"]): row for row in visible_candidates}
    if set(local_by_alias) != set(visible_by_alias):
        raise ValueError("local and visible candidate aliases differ")
    aliases = sorted(local_by_alias)
    violations: list[dict[str, Any]] = []
    evaluator_equivalent_strong_unique_pairs = 0
    pair_count = 0
    for left_index, left_alias in enumerate(aliases):
        for right_alias in aliases[left_index + 1 :]:
            pair_count += 1
            left_local = local_by_alias[left_alias]
            right_local = local_by_alias[right_alias]
            left_eval = evaluator_binary_signature(left_local.get("action") or {})
            right_eval = evaluator_binary_signature(right_local.get("action") or {})
            left_visible = visible_action_signature(visible_by_alias[left_alias])
            right_visible = visible_action_signature(visible_by_alias[right_alias])
            if left_eval != right_eval and left_visible == right_visible:
                violations.append({
                    "left_alias": left_alias,
                    "right_alias": right_alias,
                    "left_evaluator_signature": left_eval,
                    "right_evaluator_signature": right_eval,
                    "shared_visible_signature": left_visible,
                })
            if (
                left_eval == right_eval
                and str(left_local.get("candidate_action_id")) != str(right_local.get("candidate_action_id"))
            ):
                evaluator_equivalent_strong_unique_pairs += 1
    return {
        "pair_count": pair_count,
        "unidentifiable_binary_evaluator_pair_count": len(violations),
        "evaluator_equivalent_but_strong_unique_pair_count": evaluator_equivalent_strong_unique_pairs,
        "violations": violations,
    }


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--window-id", default="W00")
    parser.add_argument("--result-root", type=Path, default=DEFAULT_RESULT_ROOT)
    args = parser.parse_args()
    result_root = args.result_root if args.result_root.is_absolute() else ROOT / args.result_root
    prepare_root = result_root / "windows" / args.window_id / "prepare"
    manifest_path = prepare_root / "manifest.json"
    manifest = read_json(manifest_path)
    logical_ref = manifest["artifacts"]["agent_logical_calls"]
    mapping_ref = manifest["artifacts"]["agent_local_mapping"]
    logical_path = ROOT / logical_ref["path"]
    mapping_path = ROOT / mapping_ref["path"]
    if sha256_path(logical_path) != logical_ref["sha256"] or sha256_path(mapping_path) != mapping_ref["sha256"]:
        raise ValueError("frozen W00 Agent input hashes changed")
    logical = {str(row["logical_call_id"]): row for row in read_jsonl(logical_path)}
    mapping = {str(row["logical_call_id"]): row for row in read_jsonl(mapping_path)}
    if set(logical) != set(mapping):
        raise ValueError("logical calls and local mappings differ")

    totals: Counter[str] = Counter()
    violations: list[dict[str, Any]] = []
    per_call: list[dict[str, Any]] = []
    for logical_id in sorted(logical):
        call = logical[logical_id]
        local = mapping[logical_id]
        result = pair_identifiability(local["candidate_pool"], call["candidates"])
        totals["logical_calls"] += 1
        totals["candidate_rows"] += len(call["candidates"])
        totals["candidate_pairs"] += int(result["pair_count"])
        totals["unidentifiable_binary_evaluator_pairs"] += int(
            result["unidentifiable_binary_evaluator_pair_count"]
        )
        totals["evaluator_equivalent_but_strong_unique_pairs"] += int(
            result["evaluator_equivalent_but_strong_unique_pair_count"]
        )
        if result["violations"]:
            violations.extend({"logical_call_id": logical_id, **row} for row in result["violations"])
        per_call.append({
            "logical_call_id_sha256": hashlib.sha256(logical_id.encode()).hexdigest(),
            "memory_branch": str(local["memory_branch"]),
            "pair_count": result["pair_count"],
            "unidentifiable_binary_evaluator_pair_count": result["unidentifiable_binary_evaluator_pair_count"],
            "evaluator_equivalent_but_strong_unique_pair_count": result[
                "evaluator_equivalent_but_strong_unique_pair_count"
            ],
        })

    output = {
        "schema_version": "jsac.agent_candidate_identifiability_audit.v1",
        "status": (
            "PASSED — ALL BINARY EVALUATOR DISTINCTIONS HAVE MODEL-VISIBLE ACTION FIELDS"
            if not violations
            else "FAILED — UNIDENTIFIABLE BINARY EVALUATOR DISTINCTIONS"
        ),
        "window_id": args.window_id,
        "gold_blind_contract": {
            "target_outcome_read": False,
            "target_historical_action_read": False,
            "gold_action_read": False,
            "candidate_hit_read": False,
            "inputs": "frozen candidate actions, model-visible candidate projections, and evaluator field contract only",
        },
        "binary_endpoint_contract": {
            "hit_levels": ["strongly_verifiable", "weakly_verifiable"],
            "distinguishing_fields": ["scheme_id", "parameter_semantic_or_name", "direction/opposition"],
            "visible_field_lineage": {
                "scheme_id": "candidate scheme",
                "parameter_semantic_or_name": "candidate semantic/param",
                "direction/opposition": "candidate dir",
            },
            "non_binary_distinguishers": {
                "exact_value_or_delta": "may upgrade weak to strong; both levels count as hit",
                "boundary_conditions": "may upgrade weak to strong; both levels count as hit",
                "parameter_group": "not read by the frozen binary action-equivalence evaluator",
            },
        },
        "counts": dict(totals),
        "violations": violations,
        "checks": {
            "all_input_hashes_verified": True,
            "every_logical_call_has_k10": totals["candidate_rows"] == totals["logical_calls"] * 10,
            "all_binary_evaluator_distinctions_model_visible": not violations,
            "no_gold_or_target_outcome_access": True,
        },
        "sources": {
            "prepare_manifest": source_ref(manifest_path),
            "agent_logical_calls": source_ref(logical_path),
            "agent_local_mapping": source_ref(mapping_path),
            "evaluator_contract": source_ref(ROOT / "pipeline/evaluation/action_equivalence.py"),
            "audit_script": source_ref(Path(__file__).resolve()),
        },
        "per_logical_call": per_call,
    }
    output_path = prepare_root / "agent_candidate_identifiability_audit.json"
    output_path.write_text(json.dumps(output, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps({
        "status": output["status"],
        "window_id": args.window_id,
        "logical_calls": totals["logical_calls"],
        "candidate_pairs": totals["candidate_pairs"],
        "unidentifiable_pairs": totals["unidentifiable_binary_evaluator_pairs"],
        "evaluator_equivalent_strong_unique_pairs": totals["evaluator_equivalent_but_strong_unique_pairs"],
        "artifact": str(output_path.relative_to(ROOT)),
    }, ensure_ascii=False, indent=2))
    if violations:
        raise SystemExit(1)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
from __future__ import annotations

import hashlib
import json
import sys
from collections import Counter, defaultdict
from pathlib import Path
from typing import Any, Iterable


ROOT = Path(__file__).resolve().parents[1]
AUDIT_ROOT = ROOT / "experiments/results/jsac_continual_replay_temporal_extension_audit_20260902"
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from experiments.evaluate_jsac_phase4b_policy_development import (  # noqa: E402
    bootstrap_comparison,
    holm_adjust as holm_outcome,
    operating_point,
    paired_contrast,
    permutation_test,
)
from experiments.evaluate_jsac_unified_agent_v4_rank_neutral import (  # noqa: E402
    holm_adjust as holm_structural,
    paired_statistics,
)
from experiments.freeze_jsac_phase4b_policy_decisions import METHODS, rank_and_queue  # noqa: E402
from pipeline.common import io as cio  # noqa: E402
from pipeline.evaluation.jsac_agent_candidate_family import evaluator_action_family_signature  # noqa: E402
from pipeline.evaluation.retrieval_baselines import _case_action  # noqa: E402


OUTCOME_ROOT = ROOT / "experiments/results/jsac_unified_continual_replay_temporal_extension_20260902"
OUTCOME_EVAL = OUTCOME_ROOT / "final_deterministic_primary_v2_1"
STRUCTURAL_ROOT = ROOT / "experiments/results/jsac_temporal_table2a_positive_reuse_temporal_extension_20260902"
INIT_ROOT = ROOT / "experiments/results/jsac_unified_continual_replay_20260824/initialization"
CONFIG_PATH = ROOT / "experiments/results/jsac_unified_continual_replay_temporal_extension_20260902/runtime_config.json"
THROUGH = "W36"
WINDOWS = [f"W{index:02d}" for index in range(37)]
EXTENSION_WINDOWS = [f"W{index:02d}" for index in range(30, 37)]
COMPARISONS = (
    ("echo_adaptive_minus_echo_static", "echo_adaptive", "echo_static", 0.1, 0, 0),
    ("echo_adaptive_minus_echo_static", "echo_adaptive", "echo_static", 0.2, 0, 1),
    ("echo_adaptive_minus_raw_adaptive", "echo_adaptive", "raw_history_adaptive", 0.1, 1, 0),
    ("echo_adaptive_minus_raw_adaptive", "echo_adaptive", "raw_history_adaptive", 0.2, 1, 1),
)


def read_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def read_jsonl(path: Path) -> list[dict[str, Any]]:
    return list(cio.read_jsonl(path))


def write_json(path: Path, value: Any) -> None:
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def family(action: dict[str, Any] | None) -> tuple[str, ...]:
    return tuple(str(value) for value in evaluator_action_family_signature(action or {}))


def top_counts(values: Counter[str], limit: int = 20) -> list[dict[str, Any]]:
    return [{"value": key, "count": count} for key, count in values.most_common(limit)]


def outcome_w36() -> dict[str, Any]:
    config = read_json(CONFIG_PATH)
    stats = config["statistics"]
    all_rows = read_jsonl(OUTCOME_EVAL / "primary_evaluation_targets.jsonl")
    rows = [row for row in all_rows if row["window_id"] in WINDOWS]
    rows_by_window: dict[str, list[dict[str, Any]]] = {
        window: [row for row in rows if row["window_id"] == window]
        for window in WINDOWS
    }
    outcomes = {row["trace_id"]: row["target_outcome"] for row in rows}
    budgets = [float(value) for value in config["primary_consumer"]["review_budgets"]]
    selected: dict[str, dict[str, dict[str, set[str]]]] = {
        method: {str(budget): {} for budget in budgets} for method in METHODS
    }
    for window in WINDOWS:
        current = rows_by_window[window]
        ids = [row["trace_id"] for row in current]
        for method in METHODS:
            scores = {row["trace_id"]: float(row["scores"][method]) for row in current}
            _, method_selected, _ = rank_and_queue(ids, scores, budgets)
            for budget in budgets:
                selected[method][str(budget)][window] = method_selected[str(budget)]
    aggregate_selected = {
        method: {
            str(budget): set().union(*(selected[method][str(budget)][window] for window in WINDOWS))
            for budget in budgets
        }
        for method in METHODS
    }
    aggregate = {
        method: {
            str(budget): operating_point(aggregate_selected[method][str(budget)], outcomes)
            for budget in budgets
        }
        for method in METHODS
    }
    comparisons: list[dict[str, Any]] = []
    for comparison_id, left, right, budget, comparison_index, budget_index in COMPARISONS:
        key = str(budget)
        seed = int(stats["base_seed"]) + 1000 * comparison_index + 100 * budget_index
        print(f"W00-W36 statistics {comparison_id}@{budget}: ticket bootstrap", flush=True)
        ticket = bootstrap_comparison(
            rows_by_window=rows_by_window,
            left_method=left,
            right_method=right,
            budget=budget,
            replicates=int(stats["bootstrap_replicates"]),
            seed=seed + 11,
            cluster=False,
        )
        print(f"W00-W36 statistics {comparison_id}@{budget}: site bootstrap", flush=True)
        cluster = bootstrap_comparison(
            rows_by_window=rows_by_window,
            left_method=left,
            right_method=right,
            budget=budget,
            replicates=int(stats["bootstrap_replicates"]),
            seed=seed + 29,
            cluster=True,
        )
        comparisons.append({
            "comparison_id": comparison_id,
            "left_method": left,
            "right_method": right,
            "budget": budget,
            "point": paired_contrast(aggregate_selected[left][key], aggregate_selected[right][key], outcomes)
            | {"right_method": right},
            "ticket_bootstrap": ticket,
            "site_cluster_bootstrap": cluster,
            "permutation": permutation_test(
                left=aggregate_selected[left][key],
                right=aggregate_selected[right][key],
                outcomes=outcomes,
                replicates=int(stats["permutation_replicates"]),
                seed=seed + 47,
            ),
        })
    comparisons = holm_outcome(comparisons)
    return {
        "scope": "W00-W36; W37 excluded because its labels are right-censored",
        "population": {
            "primary_eligible": len(rows),
            "pass": sum(value == "long_eval_pass" for value in outcomes.values()),
            "fail": sum(value == "long_eval_fail" for value in outcomes.values()),
            "window_count": len(WINDOWS),
        },
        "aggregate_operating_points": aggregate,
        "comparisons": comparisons,
    }


def structural_w36(rows: list[dict[str, Any]]) -> dict[str, Any]:
    selected = [row for row in rows if row["window_id"] in WINDOWS]
    by_cohort = {
        cohort: [row for row in selected if row["cohort"] == cohort]
        for cohort in ("strict_single", "multi_bundle")
    }
    stats = {
        cohort: paired_statistics(current, seed=20260825 + index * 100)
        for index, (cohort, current) in enumerate(by_cohort.items())
    }
    adjusted = holm_structural({
        cohort: float(value["adaptive_minus_static"]["paired_sign_flip_raw_p"])
        for cohort, value in stats.items()
    })
    output: dict[str, Any] = {}
    for cohort, current in by_cohort.items():
        item = stats[cohort]
        item["adaptive_minus_static"]["holm_adjusted_p"] = adjusted[cohort]
        item["adaptive_minus_static"]["improvement_claim_permitted"] = (
            item["adaptive_minus_static"]["rate_difference"] > 0
            and adjusted[cohort] < 0.05
            and item["adaptive_minus_static"]["ticket_bootstrap"]["ci_95"][0] > 0
            and item["adaptive_minus_static"]["site_cluster_bootstrap"]["ci_95"][0] > 0
        )
        output[cohort] = item
    return {
        "scope": "W00-W36; W37 excluded because its labels are right-censored",
        "pass_readout_targets": len(selected),
        "cohorts": output,
    }


def composition(rows: list[dict[str, Any]], metadata: dict[str, dict[str, str]], dimension: str) -> dict[str, Any]:
    periods = {
        "original_W00_W29": [row for row in rows if row["window_id"] <= "W29"],
        "extension_W30_W36": [row for row in rows if row["window_id"] in EXTENSION_WINDOWS],
    }
    counts: dict[str, Counter[str]] = {}
    group_metrics: dict[str, dict[str, dict[str, Any]]] = {}
    for period, current in periods.items():
        counts[period] = Counter(metadata[row["trace_id"]].get(dimension) or "<missing>" for row in current)
        group_rows: dict[str, list[dict[str, Any]]] = defaultdict(list)
        for row in current:
            group_rows[metadata[row["trace_id"]].get(dimension) or "<missing>"].append(row)
        group_metrics[period] = {
            group: {
                "n": len(values),
                "static_hits": sum(int(row["static_hit"]) for row in values),
                "adaptive_hits": sum(int(row["adaptive_hit"]) for row in values),
                "net_hits": sum(int(row["adaptive_hit"]) - int(row["static_hit"]) for row in values),
                "difference_pp": 100 * sum(int(row["adaptive_hit"]) - int(row["static_hit"]) for row in values) / len(values),
            }
            for group, values in group_rows.items()
        }
    left_n = sum(counts["original_W00_W29"].values())
    right_n = sum(counts["extension_W30_W36"].values())
    values = set(counts["original_W00_W29"]) | set(counts["extension_W30_W36"])
    tvd = 0.5 * sum(
        abs(counts["original_W00_W29"][value] / left_n - counts["extension_W30_W36"][value] / right_n)
        for value in values
    )
    extension_groups = []
    for value in values:
        current = counts["extension_W30_W36"][value]
        if not current:
            continue
        original_metric = group_metrics["original_W00_W29"].get(value)
        extension_metric = group_metrics["extension_W30_W36"][value]
        extension_groups.append({
            "value": value,
            "n": current,
            "share": current / right_n,
            "original_share": counts["original_W00_W29"][value] / left_n,
            "adaptive_minus_static_hits": extension_metric["net_hits"],
            "adaptive_minus_static_pp": extension_metric["difference_pp"],
            "original_adaptive_minus_static_pp": original_metric["difference_pp"] if original_metric else None,
        })
    extension_groups.sort(key=lambda item: (-abs(item["adaptive_minus_static_hits"]), -item["n"], item["value"]))
    original_weight_covered = sum(
        counts["original_W00_W29"][value] / left_n
        for value in values
        if value in group_metrics["extension_W30_W36"]
    )
    standardized_to_original_mix = sum(
        counts["original_W00_W29"][value] / left_n
        * group_metrics["extension_W30_W36"][value]["difference_pp"]
        for value in values
        if value in group_metrics["extension_W30_W36"]
    ) / original_weight_covered
    observed_extension_pp = 100 * sum(
        int(row["adaptive_hit"]) - int(row["static_hit"])
        for row in periods["extension_W30_W36"]
    ) / right_n
    return {
        "total_variation_distance": tvd,
        "original_n": left_n,
        "extension_n": right_n,
        "observed_extension_adaptive_minus_static_pp": observed_extension_pp,
        "extension_within_group_effect_standardized_to_original_mix_pp": standardized_to_original_mix,
        "original_mix_weight_covered_by_extension_groups": original_weight_covered,
        "extension_groups_sorted_by_absolute_net_contribution": extension_groups,
    }


def structural_jump(rows: list[dict[str, Any]]) -> dict[str, Any]:
    multi_all = [row for row in rows if row["cohort"] == "multi_bundle" and row["window_id"] in WINDOWS]
    multi_ext = [row for row in multi_all if row["window_id"] in EXTENSION_WINDOWS]
    needed_ids = {row["trace_id"] for row in multi_all}
    config = read_json(CONFIG_PATH)
    metadata: dict[str, dict[str, str]] = {}
    for spec in config["source"]["canonical_partitions"]:
        for trace in cio.read_jsonl(ROOT / spec["path"]):
            trace_id = str(trace.get("trace_id") or "")
            if trace_id not in needed_ids:
                continue
            ticket = trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}
            metadata[trace_id] = {
                "primary_issue_type": str(ticket.get("primary_issue_type") or "<missing>"),
                "vendor": str(ticket.get("vendor") or "<missing>"),
                "region": str(ticket.get("region") or "<missing>"),
                "system": str(ticket.get("system") or "<missing>"),
                "band": str(ticket.get("band") or "<missing>"),
            }
    if set(metadata) != needed_ids:
        raise ValueError(f"missing structural metadata for {len(needed_ids - set(metadata))} traces")

    p0_ids: set[str] = set()
    p0_families: set[tuple[str, ...]] = set()
    for memory in cio.read_jsonl(INIT_ROOT / "memory_objects.jsonl"):
        memory_id = str(memory.get("memory_id") or "")
        if memory_id:
            p0_ids.add(memory_id)
        action = _case_action(memory)
        signature = family(action)
        if signature and any(signature):
            p0_families.add(signature)

    decisions: dict[str, dict[str, Any]] = {}
    for window in EXTENSION_WINDOWS:
        path = STRUCTURAL_ROOT / "freeze/windows" / window / "decisions.jsonl"
        for row in cio.read_jsonl(path):
            if row["trace_id"] in needed_ids:
                decisions[row["trace_id"]] = row
    missing = {row["trace_id"] for row in multi_ext} - set(decisions)
    if missing:
        raise ValueError(f"missing frozen decisions for {len(missing)} extension multi rows")

    channel_counts: Counter[str] = Counter()
    object_counts: Counter[str] = Counter()
    signature_counts: Counter[str] = Counter()
    top5_object_counts: Counter[str] = Counter()
    per_window: dict[str, dict[str, Any]] = {}
    selected_object_rows: list[dict[str, Any]] = []
    for window in EXTENSION_WINDOWS:
        current = [row for row in multi_ext if row["window_id"] == window]
        for row in current:
            if row["adaptive_hit"] and not row["static_hit"]:
                if not row["static_ceiling_at_5"] and row["adaptive_ceiling_at_5"]:
                    channel_counts["adaptive_only_hit_with_new_candidate_coverage"] += 1
                elif row["static_ceiling_at_5"] and row["adaptive_ceiling_at_5"]:
                    channel_counts["adaptive_only_hit_with_both_candidate_ceilings"] += 1
                else:
                    channel_counts["adaptive_only_hit_other_ceiling_pattern"] += 1
            decision = decisions[row["trace_id"]]
            selected_candidate = decision["adaptive"]["candidates"][0] if decision["adaptive"]["candidates"] else {}
            selected_id = str(selected_candidate.get("memory_id") or "")
            selected_family = tuple(str(value) for value in decision["adaptive"]["selected_action_family"])
            object_class = "selected_object_present_in_P0" if selected_id in p0_ids else "selected_object_new_after_P0"
            signature_class = "selected_signature_present_in_P0" if selected_family in p0_families else "selected_signature_new_after_P0"
            object_counts[object_class] += 1
            signature_counts[signature_class] += 1
            for candidate in decision["adaptive"]["candidates"][:5]:
                top5_object_counts["top5_object_present_in_P0" if str(candidate.get("memory_id") or "") in p0_ids else "top5_object_new_after_P0"] += 1
            if row["adaptive_hit"] and not row["static_hit"]:
                selected_object_rows.append({
                    "trace_id": row["trace_id"],
                    "window_id": window,
                    "object_class": object_class,
                    "signature_class": signature_class,
                    "static_ceiling_at_5": row["static_ceiling_at_5"],
                    "adaptive_ceiling_at_5": row["adaptive_ceiling_at_5"],
                })
        static_hits = sum(row["static_hit"] for row in current)
        adaptive_hits = sum(row["adaptive_hit"] for row in current)
        per_window[window] = {
            "n": len(current),
            "static_hits": static_hits,
            "adaptive_hits": adaptive_hits,
            "net_additional_hits": adaptive_hits - static_hits,
            "difference_pp": 100 * (adaptive_hits - static_hits) / len(current) if current else None,
            "adaptive_only_hits": sum(row["adaptive_hit"] and not row["static_hit"] for row in current),
            "static_only_hits": sum(row["static_hit"] and not row["adaptive_hit"] for row in current),
        }

    adaptive_only_object = Counter(row["object_class"] for row in selected_object_rows)
    adaptive_only_signature = Counter(row["signature_class"] for row in selected_object_rows)
    original_net = sum(int(row["adaptive_hit"]) - int(row["static_hit"]) for row in multi_all if row["window_id"] <= "W29")
    extension_net = sum(int(row["adaptive_hit"]) - int(row["static_hit"]) for row in multi_ext)
    return {
        "multi_action_scale": {
            "original_W00_W29_n": sum(row["window_id"] <= "W29" for row in multi_all),
            "extension_W30_W36_n": len(multi_ext),
            "extension_share_of_W00_W36": len(multi_ext) / len(multi_all),
            "original_net_additional_hits": original_net,
            "extension_net_additional_hits": extension_net,
            "extension_share_of_positive_net_hits": extension_net / (original_net + extension_net),
            "per_window": per_window,
            "leave_one_extension_window_out_net": {
                window: original_net + extension_net - per_window[window]["net_additional_hits"]
                for window in EXTENSION_WINDOWS
            },
        },
        "composition": {
            dimension: composition(multi_all, metadata, dimension)
            for dimension in ("primary_issue_type", "vendor", "region", "system", "band")
        },
        "later_history_channel": {
            "p0_memory_object_count": len(p0_ids),
            "p0_action_family_count": len(p0_families),
            "adaptive_only_hit_ceiling_decomposition": dict(channel_counts),
            "all_extension_multi_selected_object_origin": dict(object_counts),
            "all_extension_multi_selected_signature_origin": dict(signature_counts),
            "all_extension_multi_top5_object_origin": dict(top5_object_counts),
            "adaptive_only_hit_selected_object_origin": dict(adaptive_only_object),
            "adaptive_only_hit_selected_signature_origin": dict(adaptive_only_signature),
            "interpretation_guardrail": "Object/signature and ceiling decompositions are descriptive pathways, not causal mediation estimates.",
        },
    }


def summarize_markdown(result: dict[str, Any]) -> str:
    outcome = result["w00_w36"]["outcome"]
    structural = result["w00_w36"]["structural"]
    jump = result["structural_jump_audit"]
    lines = [
        "# W00-W36 Primary Estimates and Structural-Jump Audit",
        "",
        "W37 is excluded from primary extended estimates because its outcomes are right-censored; it remains available as a 38-window available-case sensitivity.",
        "",
        "## Outcome-side Table 2 estimates",
        "",
        "| Method | HFC@10% | HFC@20% |",
        "|---|---:|---:|",
    ]
    for method in METHODS:
        p10 = outcome["aggregate_operating_points"][method]["0.1"]["historical_failure_capture"]
        p20 = outcome["aggregate_operating_points"][method]["0.2"]["historical_failure_capture"]
        lines.append(f"| {method} | {p10['value']:.4%} ({p10['numerator']}/{p10['denominator']}) | {p20['value']:.4%} ({p20['numerator']}/{p20['denominator']}) |")
    lines += ["", "| Comparison | Budget | Net Fail | Difference | Ticket 95% CI | Site 95% CI | Holm p |", "|---|---:|---:|---:|---:|---:|---:|"]
    for row in outcome["comparisons"]:
        t = row["ticket_bootstrap"]["delta_95ci"]["hfc_difference"]
        s = row["site_cluster_bootstrap"]["delta_95ci"]["hfc_difference"]
        lines.append(
            f"| {row['comparison_id']} | {row['budget']:.0%} | {row['point']['net_additional_captured_fail']:+d} | "
            f"{100 * row['point']['hfc_difference']:+.4f} pp | [{100*t['low']:+.4f}, {100*t['high']:+.4f}] | "
            f"[{100*s['low']:+.4f}, {100*s['high']:+.4f}] | {row['permutation']['holm_adjusted_p']:.6g} |"
        )
    lines += ["", "## Structural-side Table 2 estimates", "", "| Cohort | Static | Adaptive | Net / difference | Ticket 95% CI | Site 95% CI | State 95% CI | Holm p |", "|---|---:|---:|---:|---:|---:|---:|---:|"]
    for cohort in ("strict_single", "multi_bundle"):
        item = structural["cohorts"][cohort]
        diff = item["adaptive_minus_static"]
        lines.append(
            f"| {cohort} | {item['static']['rate']:.4%} ({item['static']['hits']}/{item['target_count']}) | "
            f"{item['adaptive']['rate']:.4%} ({item['adaptive']['hits']}/{item['target_count']}) | "
            f"{diff['net_additional_hits']:+d} / {diff['percentage_points']:+.4f} pp | "
            f"[{100*diff['ticket_bootstrap']['ci_95'][0]:+.4f}, {100*diff['ticket_bootstrap']['ci_95'][1]:+.4f}] | "
            f"[{100*diff['site_cluster_bootstrap']['ci_95'][0]:+.4f}, {100*diff['site_cluster_bootstrap']['ci_95'][1]:+.4f}] | "
            f"[{100*diff['paired_state_cluster_sensitivity']['ci_95'][0]:+.4f}, {100*diff['paired_state_cluster_sensitivity']['ci_95'][1]:+.4f}] | "
            f"{diff['holm_adjusted_p']:.6g} |"
        )
    scale = jump["multi_action_scale"]
    channel = jump["later_history_channel"]
    lines += [
        "",
        "## Structural-jump checks",
        "",
        f"- W30-W36 contributes {scale['extension_net_additional_hits']:+d} of the W00-W36 net multi-action hits; all leave-one-extension-window-out totals remain positive.",
        f"- Extension multi-action population: {scale['extension_W30_W36_n']:,} ({scale['extension_share_of_W00_W36']:.2%} of W00-W36).",
        f"- Adaptive-only hits by ceiling pathway: `{json.dumps(channel['adaptive_only_hit_ceiling_decomposition'], ensure_ascii=False, sort_keys=True)}`.",
        f"- Adaptive-only selected object origin: `{json.dumps(channel['adaptive_only_hit_selected_object_origin'], ensure_ascii=False, sort_keys=True)}`.",
        f"- Adaptive-only selected signature origin: `{json.dumps(channel['adaptive_only_hit_selected_signature_origin'], ensure_ascii=False, sort_keys=True)}`.",
        "- Composition tables and total-variation distances are in the JSON artifact; these checks are descriptive and do not establish causal mediation.",
    ]
    return "\n".join(lines) + "\n"


def main() -> None:
    structural_rows = read_jsonl(STRUCTURAL_ROOT / "evaluation/pass_readout_rows.jsonl")
    result = {
        "schema_version": "echo_mem.w36_extension_and_jump_audit.v1",
        "through_window": THROUGH,
        "w37_policy": "right-censored; exclude from primary W00-W36 estimates and retain as available-case sensitivity",
        "w00_w36": {
            "outcome": outcome_w36(),
            "structural": structural_w36(structural_rows),
        },
        "structural_jump_audit": structural_jump(structural_rows),
        "sources": {
            "outcome_targets": {"path": str(OUTCOME_EVAL / "primary_evaluation_targets.jsonl"), "sha256": sha256(OUTCOME_EVAL / "primary_evaluation_targets.jsonl")},
            "structural_rows": {"path": str(STRUCTURAL_ROOT / "evaluation/pass_readout_rows.jsonl"), "sha256": sha256(STRUCTURAL_ROOT / "evaluation/pass_readout_rows.jsonl")},
            "p0_memory_objects": {"path": str(INIT_ROOT / "memory_objects.jsonl"), "sha256": sha256(INIT_ROOT / "memory_objects.jsonl")},
            "analysis_script": {"path": str(Path(__file__)), "sha256": sha256(Path(__file__))},
        },
    }
    AUDIT_ROOT.mkdir(parents=True, exist_ok=True)
    json_path = AUDIT_ROOT / "result.json"
    md_path = AUDIT_ROOT / "report.md"
    write_json(json_path, result)
    md_path.write_text(summarize_markdown(result), encoding="utf-8")
    print(json.dumps({"result": str(json_path), "report": str(md_path)}, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

