DEFAULT_SENSITIVITY_CONTRACT = ROOT / "experiments/config/jsac_two_timescale/agent_rank_neutral_static_search_sensitivity.v1.json"
DEFAULT_STATS_CONFIG = ROOT / "experiments/config/jsac_two_timescale/agent_facing_one_shot_action_readout.v1.json"
DEFAULT_REPLAY_CONFIG = ROOT / "experiments/config/jsac_two_timescale/phase5_unified_continual_replay.v2_1.json"
REPLICATES = 10_000
BASE_SEED = 20260824


def read_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def read_jsonl(path: Path) -> Iterable[dict[str, Any]]:
    return cio.read_jsonl(path)


def sha256_path(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def source_ref(path: Path, *, rows: int | None = None) -> dict[str, Any]:
    result: dict[str, Any] = {
        "path": str(path.resolve().relative_to(ROOT)),
        "size_bytes": path.stat().st_size,
        "sha256": sha256_path(path),
    }
    if rows is not None:
        result["rows"] = rows
    return result


def verify_ref(item: dict[str, Any]) -> Path:
    path = (ROOT / str(item["path"])).resolve()
    if not path.exists() or sha256_path(path) != item["sha256"]:
        raise ValueError(f"frozen source hash failed: {item['path']}")
    return path


def write_json(path: Path, value: Any) -> dict[str, Any]:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    return source_ref(path)


def write_jsonl(path: Path, rows: Iterable[dict[str, Any]]) -> dict[str, Any]:
    values = list(rows)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8") as handle:
        for row in values:
            handle.write(json.dumps(row, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n")
    return source_ref(path, rows=len(values))


def family_action(signature: tuple[str, str, str]) -> dict[str, str]:
    return {
        "scheme_id": signature[0],
        "parameter_semantic_id": signature[1],
        "direction": signature[2],
    }


def aggregate_outcome(trace: dict[str, Any]) -> str:
    return str((trace.get("aggregate") or {}).get("ticket_outcome") or "")


def percentile_interval(values: np.ndarray) -> list[float]:
    low, high = np.quantile(values, [0.025, 0.975])
    return [float(low), float(high)]


def ticket_bootstrap(differences: np.ndarray, *, seed: int) -> dict[str, Any]:
    rng = np.random.default_rng(seed)
    sampled: list[np.ndarray] = []
    remaining = REPLICATES
    while remaining:
        batch = min(128, remaining)
        indices = rng.integers(0, len(differences), size=(batch, len(differences)))
        sampled.append(differences[indices].mean(axis=1))
        remaining -= batch
    values = np.concatenate(sampled)
    return {"replicates": REPLICATES, "seed": seed, "ci_95": percentile_interval(values)}


def cluster_bootstrap(
    differences: np.ndarray,
    cluster_labels: list[str],
    *,
    seed: int,
) -> dict[str, Any]:
    grouped: dict[str, list[int]] = defaultdict(list)
    for index, label in enumerate(cluster_labels):
        grouped[label].append(index)
    clusters = list(grouped.values())
    sums = np.asarray([differences[indices].sum() for indices in clusters], dtype=float)
    counts = np.asarray([len(indices) for indices in clusters], dtype=float)
    rng = np.random.default_rng(seed)
    sampled: list[np.ndarray] = []
    remaining = REPLICATES
    while remaining:
        batch = min(128, remaining)
        drawn = rng.integers(0, len(clusters), size=(batch, len(clusters)))
        sampled.append(sums[drawn].sum(axis=1) / counts[drawn].sum(axis=1))
        remaining -= batch
    values = np.concatenate(sampled)
    return {
        "replicates": REPLICATES,
        "seed": seed,
        "cluster_count": len(clusters),
        "ci_95": percentile_interval(values),
    }


def sign_flip_p(differences: np.ndarray, *, seed: int) -> float:
    discordant = differences[differences != 0]
    if not len(discordant):
        return 1.0
    observed = abs(int(discordant.sum()))
    rng = np.random.default_rng(seed)
    exceed = 0
    remaining = REPLICATES
    while remaining:
        batch = min(1000, remaining)
        permuted = rng.choice(np.asarray([-1, 1], dtype=int), size=(batch, len(discordant))).sum(axis=1)
        exceed += int(np.sum(np.abs(permuted) >= observed))
        remaining -= batch
    return (exceed + 1) / (REPLICATES + 1)


def exact_mcnemar_p(adaptive_only: int, static_only: int) -> float:
    n = adaptive_only + static_only
    if not n:
        return 1.0
    return float(binomtest(adaptive_only, n=n, p=0.5, alternative="two-sided").pvalue)


def holm_adjust(raw: dict[str, float]) -> dict[str, float]:
    ordered = sorted(raw, key=raw.get)
    adjusted: dict[str, float] = {}
    running = 0.0
    total = len(ordered)
    for rank, key in enumerate(ordered):
        value = min(1.0, raw[key] * (total - rank))
        running = max(running, value)
        adjusted[key] = running
    return adjusted


def paired_statistics(rows: list[dict[str, Any]], *, seed: int) -> dict[str, Any]:
    static = np.asarray([int(row["static_hit"]) for row in rows], dtype=int)
    adaptive = np.asarray([int(row["adaptive_hit"]) for row in rows], dtype=int)
    differences = adaptive - static
    adaptive_only = int(np.sum(differences == 1))
    static_only = int(np.sum(differences == -1))
    return {
        "target_count": len(rows),
        "static": {
            "hits": int(static.sum()),
            "rate": float(static.mean()),
        },
        "adaptive": {
            "hits": int(adaptive.sum()),
            "rate": float(adaptive.mean()),
        },
        "adaptive_minus_static": {
            "net_additional_hits": int(differences.sum()),
            "rate_difference": float(differences.mean()),
            "percentage_points": float(differences.mean() * 100.0),
            "adaptive_only_hits": adaptive_only,
            "static_only_hits": static_only,
            "discordant_targets": adaptive_only + static_only,
            "ticket_bootstrap": ticket_bootstrap(differences, seed=seed),
            "site_cluster_bootstrap": cluster_bootstrap(
                differences,
                [str(row["site_name"]) for row in rows],
                seed=seed + 1,
            ),
            "paired_state_cluster_sensitivity": cluster_bootstrap(
                differences,
                [str(row["paired_state_cluster_id"]) for row in rows],
                seed=seed + 2,
            ),
            "paired_sign_flip_raw_p": sign_flip_p(differences, seed=seed + 3),
            "exact_mcnemar_raw_p": exact_mcnemar_p(adaptive_only, static_only),
        },
    }


def current_static_curve(rows: list[dict[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for n_value in range(1, 11):
        hits = sum(
            row["frozen_static_first_hit_rank"] is not None
            and int(row["frozen_static_first_hit_rank"]) <= n_value
            for row in rows
        )
        result[str(n_value)] = {"hits": hits, "rate": hits / len(rows) if rows else None}
    return result


def canonical_family_payload(signature: list[str] | tuple[str, str, str]) -> str:
    return json.dumps(
        {"scheme_id": signature[0], "parameter_semantic_or_name": signature[1], "direction": signature[2]},
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )


def random_static_sensitivity(
    rows_by_cohort: dict[str, list[dict[str, Any]]],
    contract: dict[str, Any],
) -> dict[str, Any]:
    master = str(contract["master_salt"])
    start = int(contract["replicate_indices"]["start_inclusive"])
    stop = int(contract["replicate_indices"]["stop_exclusive"])
    width = int(contract["replicate_indices"]["zero_pad_width"])
    replicates: dict[str, list[list[float]]] = {cohort: [] for cohort in rows_by_cohort}
    for replicate in range(start, stop):
        replicate_salt = hashlib.sha256(f"{master}|{replicate:0{width}d}".encode()).hexdigest()
        for cohort, rows in rows_by_cohort.items():
            cumulative = np.zeros(10, dtype=int)
            for row in rows:
                target_key = f"{row['window_id']}|{row['trace_id']}"
                ordered = sorted(
                    row["pool_families"],
                    key=lambda signature: (
                        hashlib.sha256(
                            f"{replicate_salt}|{target_key}|{canonical_family_payload(signature)}".encode()
                        ).hexdigest(),
                        canonical_family_payload(signature),
                    ),
                )
                gold = {tuple(value) for value in row["gold_families"]}
                first_hit = next((index for index, signature in enumerate(ordered) if tuple(signature) in gold), None)
                if first_hit is not None:
                    cumulative[first_hit:] += 1
            replicates[cohort].append((cumulative / len(rows)).tolist())

    output: dict[str, Any] = {}
    for cohort, values in replicates.items():
        matrix = np.asarray(values, dtype=float)
        summary: dict[str, Any] = {}
        for index in range(10):
            column = matrix[:, index]
            summary[str(index + 1)] = {
                "mean": float(column.mean()),
                "median": float(np.median(column)),
                "percentile_2_5": float(np.quantile(column, 0.025)),
                "percentile_97_5": float(np.quantile(column, 0.975)),
            }
        output[cohort] = {"summary_by_n": summary, "replicate_rates_by_n": values}
    return {
        "schema_version": "jsac.agent_rank_neutral_static_search_sensitivity_result.v1",
        "status": "COMPLETED UNDER THE PRE-RESPONSE 200-SALT CONTRACT",
        "replicates": stop - start,
        "cohorts": output,
        "claim_boundary": "No-LLM random-order sensitivity only; not a GPT method and not a tunable seed search.",
    }


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--selections", type=Path, default=DEFAULT_SELECTIONS)
    parser.add_argument("--global-manifest", type=Path, default=DEFAULT_GLOBAL_MANIFEST)
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    parser.add_argument("--details", type=Path, default=DEFAULT_DETAILS)
    parser.add_argument("--sensitivity", type=Path, default=DEFAULT_SENSITIVITY)
    parser.add_argument("--evaluator-contract", type=Path, default=DEFAULT_EVALUATOR_CONTRACT)
    parser.add_argument("--sensitivity-contract", type=Path, default=DEFAULT_SENSITIVITY_CONTRACT)
    parser.add_argument("--stats-config", type=Path, default=DEFAULT_STATS_CONFIG)
    parser.add_argument("--replay-config", type=Path, default=DEFAULT_REPLAY_CONFIG)
    args = parser.parse_args()

    selections_path = args.selections.resolve()
    global_manifest_path = args.global_manifest.resolve()
    evaluator_contract_path = args.evaluator_contract.resolve()
    sensitivity_contract_path = args.sensitivity_contract.resolve()
    stats_config_path = args.stats_config.resolve()
    replay_config_path = args.replay_config.resolve()
    selections = read_json(selections_path)
    global_manifest = read_json(global_manifest_path)
    evaluator_contract = read_json(evaluator_contract_path)
    sensitivity_contract = read_json(sensitivity_contract_path)
    stats_config = read_json(stats_config_path)
    replay_config = read_json(replay_config_path)
    if not all(selections["checks"].values()):
        raise ValueError("v4 GPT return import integrity failed")
    if selections["protocol_hash"] != global_manifest["protocol_hash"]:
        raise ValueError("selection and global protocol hashes differ")
    if stats_config["evaluation_contract"]["resamples"] != REPLICATES:
        raise ValueError("frozen Agent statistical replicate count changed")
    if evaluator_contract["binary_identity"]["version"] != "agent_action_family.v1":
        raise ValueError("unexpected local evaluator identity")

    selected_by_hash = {
        str(row["state_hash"]): str(row["selected_candidate_id"])
        for row in selections["selections"]
    }
    if len(selected_by_hash) != int(global_manifest["counts"]["global_unique_prompt_states"]):
        raise ValueError("selection-state coverage changed")

    logical_mapping_path = verify_ref(global_manifest["artifacts"]["global_logical_mapping"])
    local_mapping_path = verify_ref(global_manifest["artifacts"]["global_local_evaluation_mapping"])
    logical_mapping = {str(row["logical_call_id"]): row for row in read_jsonl(logical_mapping_path)}
    if len(logical_mapping) != int(global_manifest["counts"]["logical_agent_decisions"]):
        raise ValueError("logical mapping count changed")

    decisions: dict[str, dict[str, Any]] = {}
    for row in read_jsonl(local_mapping_path):
        logical_id = str(row["logical_call_id"])
        mapping = logical_mapping.get(logical_id)
        if mapping is None:
            raise ValueError(f"local decision missing from logical mapping: {logical_id}")
        state_hash = str(mapping["state_hash"])
        alias = selected_by_hash.get(state_hash)
        if alias is None:
            raise ValueError(f"logical decision has no frozen GPT choice: {logical_id}")
        pool = row["candidate_pool"]
        if len(pool) != 10 or [item["alias"] for item in pool] != [f"C{rank:02d}" for rank in range(1, 11)]:
            raise ValueError("v4 local pool is not the frozen C01..C10 mapping")
        selected = next((item for item in pool if item["alias"] == alias), None)
        if selected is None:
            raise ValueError("frozen alias absent from local pool")
        pool_families = [
            [
                str(item["family_signature"]["scheme_id"]),
                str(item["family_signature"]["parameter_semantic_or_name"]),
                str(item["family_signature"]["direction"]),
            ]
            for item in pool
        ]
        selected_signature = tuple(pool_families[int(alias[1:]) - 1])
        decisions[logical_id] = {
            "logical_call_id": logical_id,
            "window_id": str(row["window_id"]),
            "trace_id": str(row["trace_id"]),
            "memory_branch": str(row["memory_branch"]),
            "prompt_state_id": str(mapping["prompt_state_id"]),
            "state_hash": state_hash,
            "selected_candidate_id": alias,
            "selected_family": selected_signature,
            "pool_families": pool_families,
        }
    if len(decisions) != int(global_manifest["counts"]["logical_agent_decisions"]):
        raise ValueError("not every logical decision was projected")

    paired: dict[tuple[str, str], dict[str, dict[str, Any]]] = defaultdict(dict)
    for row in decisions.values():
        paired[(row["window_id"], row["trace_id"])][row["memory_branch"]] = row
    if len(paired) != int(global_manifest["counts"]["paired_targets"]):
        raise ValueError("paired target count changed")
    if any(set(value) != {"static", "adaptive"} for value in paired.values()):
        raise ValueError("Static/Adaptive target pairs are incomplete")

    target_ids = {trace_id for _, trace_id in paired}
    traces: dict[str, dict[str, Any]] = {}
    source_refs: list[dict[str, Any]] = []
    for spec in replay_config["source"]["canonical_partitions"]:
        path = ROOT / spec["path"]
        row_count = 0
        for trace in read_jsonl(path):
            row_count += 1
            trace_id = str(trace.get("trace_id") or "")
            if trace_id in target_ids:
                if trace_id in traces:
                    raise ValueError(f"duplicate target trace across canonical partitions: {trace_id}")
                traces[trace_id] = trace
        if row_count != int(spec["expected_count"]):
            raise ValueError(f"canonical source count changed: {path}")
        source_refs.append(source_ref(path, rows=row_count))
    if set(traces) != target_ids:
        raise ValueError("not every sampled target trace was reconstructed")

    outcome_counts: Counter[str] = Counter()
    exclusions: Counter[str] = Counter()
    details: list[dict[str, Any]] = []
    all_pair_sensitivity: Counter[str] = Counter()
    for (window_id, trace_id), branches in sorted(paired.items()):
        trace = traces[trace_id]
        outcome = aggregate_outcome(trace)
        outcome_counts[outcome or "missing"] += 1
        static = branches["static"]
        adaptive = branches["adaptive"]
        if static["pool_families"] != adaptive["pool_families"]:
            raise ValueError("Static/Adaptive candidate identity order differs")
        state_changed = static["state_hash"] != adaptive["state_hash"]
        selection_changed = static["selected_candidate_id"] != adaptive["selected_candidate_id"]
        all_pair_sensitivity["targets"] += 1
        all_pair_sensitivity["model_visible_state_changed"] += int(state_changed)
        all_pair_sensitivity["selection_changed"] += int(selection_changed)
        all_pair_sensitivity["selection_changed_given_state_changed"] += int(state_changed and selection_changed)
        if outcome != "long_eval_pass":
            exclusions[f"target_outcome:{outcome or 'missing'}"] += 1
            continue
        gold_actions = eligible_gold_actions(trace)
        if not gold_actions:
            exclusions["pass_without_eligible_observed_action"] += 1
            continue
        cohort = "strict_single" if len(gold_actions) == 1 else "multi_bundle"
        static_evaluation = evaluate_action_family_readout(
            family_action(static["selected_family"]), gold_actions, cohort=cohort,
        )
        adaptive_evaluation = evaluate_action_family_readout(
            family_action(adaptive["selected_family"]), gold_actions, cohort=cohort,
        )
        gold_families = [list(evaluator_action_family_signature(action)) for action in gold_actions]
        gold_family_set = {tuple(value) for value in gold_families}
        first_hit_rank = next(
            (index for index, family in enumerate(static["pool_families"], start=1) if tuple(family) in gold_family_set),
            None,
        )
        ticket = trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}
        details.append({
            "window_id": window_id,
            "trace_id": trace_id,
            "site_name": str(ticket.get("site_name") or trace_id),
            "cohort": cohort,
            "gold_action_count": len(gold_actions),
            "gold_families": gold_families,
            "pool_families": static["pool_families"],
            "frozen_static_first_hit_rank": first_hit_rank,
            "static_prompt_state_id": static["prompt_state_id"],
            "adaptive_prompt_state_id": adaptive["prompt_state_id"],
            "static_state_hash": static["state_hash"],
            "adaptive_state_hash": adaptive["state_hash"],
            "paired_state_cluster_id": hashlib.sha256(
                f"{static['state_hash']}|{adaptive['state_hash']}".encode()
            ).hexdigest(),
            "model_visible_state_changed": state_changed,
            "static_selected_candidate_id": static["selected_candidate_id"],
            "adaptive_selected_candidate_id": adaptive["selected_candidate_id"],
            "selection_changed": selection_changed,
            "static_selected_family": list(static["selected_family"]),
            "adaptive_selected_family": list(adaptive["selected_family"]),
            "static_hit": bool(static_evaluation["hit"]),
            "adaptive_hit": bool(adaptive_evaluation["hit"]),
        })

    rows_by_cohort = {
        cohort: [row for row in details if row["cohort"] == cohort]
        for cohort in ("strict_single", "multi_bundle")
    }
    if any(not rows for rows in rows_by_cohort.values()):
        raise ValueError("one Agent evaluation cohort is empty")
    comparisons = {
        cohort: paired_statistics(rows, seed=BASE_SEED + index * 100)
        for index, (cohort, rows) in enumerate(rows_by_cohort.items())
    }
    raw_p = {
        cohort: float(result["adaptive_minus_static"]["paired_sign_flip_raw_p"])
        for cohort, result in comparisons.items()
    }
    adjusted = holm_adjust(raw_p)
    for cohort, result in comparisons.items():
        contrast = result["adaptive_minus_static"]
        contrast["holm_adjusted_p"] = adjusted[cohort]
        contrast["improvement_claim_permitted"] = (
            contrast["rate_difference"] > 0
            and adjusted[cohort] < 0.05
            and contrast["ticket_bootstrap"]["ci_95"][0] > 0
            and contrast["site_cluster_bootstrap"]["ci_95"][0] > 0
        )

    per_window: dict[str, dict[str, Any]] = {}
    for cohort, rows in rows_by_cohort.items():
        grouped: dict[str, list[dict[str, Any]]] = defaultdict(list)
        for row in rows:
            grouped[str(row["window_id"])].append(row)
        per_window[cohort] = {
            window_id: {
                "target_count": len(window_rows),
                "static_hits": sum(row["static_hit"] for row in window_rows),
                "adaptive_hits": sum(row["adaptive_hit"] for row in window_rows),
                "net_additional_hits": sum(int(row["adaptive_hit"]) - int(row["static_hit"]) for row in window_rows),
            }
            for window_id, window_rows in sorted(grouped.items())
        }

    decision_sensitivity: dict[str, Any] = {
        "all_outcome_independent_targets": dict(all_pair_sensitivity),
        "all_targets_state_change_rate": (
            all_pair_sensitivity["model_visible_state_changed"] / all_pair_sensitivity["targets"]
        ),
        "all_targets_selection_change_rate": all_pair_sensitivity["selection_changed"] / all_pair_sensitivity["targets"],
        "selection_change_given_state_change_rate": (
            all_pair_sensitivity["selection_changed_given_state_changed"]
            / all_pair_sensitivity["model_visible_state_changed"]
            if all_pair_sensitivity["model_visible_state_changed"] else None
        ),
        "by_evaluation_cohort": {},
    }
    for cohort, rows in rows_by_cohort.items():
        changed_states = [row for row in rows if row["model_visible_state_changed"]]
        changed_selections = [row for row in rows if row["selection_changed"]]
        decision_sensitivity["by_evaluation_cohort"][cohort] = {
            "targets": len(rows),
            "state_changed": len(changed_states),
            "selection_changed": len(changed_selections),
            "selection_change_given_state_change_rate": (
                sum(row["selection_changed"] for row in changed_states) / len(changed_states)
                if changed_states else None
            ),
            "adaptive_helped": sum(row["adaptive_hit"] and not row["static_hit"] for row in rows),
            "adaptive_hurt": sum(row["static_hit"] and not row["adaptive_hit"] for row in rows),
        }

    sensitivity = random_static_sensitivity(rows_by_cohort, sensitivity_contract)
    sensitivity_ref = write_json(args.sensitivity.resolve(), sensitivity)
    details_ref = write_jsonl(args.details.resolve(), details)
    result = {
        "schema_version": "jsac.unified_agent_v4_rank_neutral_evaluation.v1",
        "status": "V4 GPT CHOICES VALIDATED, MAPPED AND EVALUATED AT THE FROZEN ACTION-FAMILY ENDPOINT",
        "scientific_role": "protocol-corrected Agent-facing secondary; deterministic Table-2B-aligned Layer-2 primary remains separate",
        "population": {
            "logical_agent_decisions_frozen": len(decisions),
            "paired_outcome_independent_targets": len(paired),
            "target_outcome_counts_after_choice_freeze": dict(sorted(outcome_counts.items())),
            "evaluation_targets": len(details),
            "evaluation_cohorts": {cohort: len(rows) for cohort, rows in rows_by_cohort.items()},
            "exclusions_after_choice_freeze": dict(sorted(exclusions.items())),
        },
        "gpt_unique_state_alias_distribution": selections["counts"]["selected_alias_distribution"],
        "decision_sensitivity": decision_sensitivity,
        "cohort_comparisons": comparisons,
        "frozen_order_static_sequential_search": {
            cohort: current_static_curve(rows)
            for cohort, rows in rows_by_cohort.items()
        },
        "random_order_static_search_sensitivity_summary": {
            cohort: value["summary_by_n"]
            for cohort, value in sensitivity["cohorts"].items()
        },
        "per_window": per_window,
        "checks": {
            "all_four_workbooks_imported_without_repair": True,
            "all_1802_unique_states_frozen_once": len(selected_by_hash) == 1802,
            "all_20456_logical_decisions_mapped_once": len(decisions) == 20456,
            "all_10228_targets_have_static_adaptive_pair": len(paired) == 10228,
            "static_adaptive_candidate_order_identical": True,
            "pass_subset_constructed_only_after_gpt_choice_freeze": True,
            "binary_hit_uses_only_agent_action_family_v1": True,
            "hidden_exact_value_and_companion_fields_not_used_for_hit": True,
            "strict_and_multi_reported_separately": True,
            "combined_accuracy_not_reported": True,
            "two_hundred_salt_sensitivity_executed_without_gpt": sensitivity["replicates"] == 200,
        },
        "sources": {
            "gpt_return_import": source_ref(selections_path),
            "global_registry_manifest": source_ref(global_manifest_path),
            "global_logical_mapping": source_ref(logical_mapping_path, rows=len(logical_mapping)),
            "global_local_evaluation_mapping": source_ref(local_mapping_path, rows=len(decisions)),
            "evaluator_contract": source_ref(evaluator_contract_path),
            "static_sensitivity_contract": source_ref(sensitivity_contract_path),
            "frozen_agent_statistics_config": source_ref(stats_config_path),
            "unified_replay_config": source_ref(replay_config_path),
            "canonical_partitions": source_refs,
            "evaluator": source_ref(Path(__file__).resolve()),
        },
        "artifacts": {
            "evaluation_rows": details_ref,
            "static_search_sensitivity": sensitivity_ref,
        },
        "claim_boundary": (
            "Historical-action family readout only. SSAPS and MHCM@1 remain separate; neither is action success, "
            "causal effectiveness, execution safety, KPI gain, global optimality or online benefit. The v4 "
            "permutation is gold-blind by construction but was physically generated after deterministic-primary reveal."
        ),
    }
    if not all(result["checks"].values()):
        raise ValueError("v4 Agent evaluation integrity failed")
    write_json(args.output.resolve(), result)
    print(json.dumps({
        "status": result["status"],
        "population": result["population"],
        "decision_sensitivity": result["decision_sensitivity"],
        "cohort_comparisons": result["cohort_comparisons"],
        "output": str(args.output.resolve().relative_to(ROOT)),
    }, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Evaluate the final Unified Replay deterministic primary after W29 closes."""
from __future__ import annotations

import argparse
import hashlib
import json
import sys
from collections import Counter, defaultdict
from pathlib import Path
from typing import Any, Iterable

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from experiments.evaluate_jsac_phase4b_policy_development import (
    bootstrap_comparison,
    holm_adjust,
    operating_point,
    paired_contrast,
    permutation_test,
)
from experiments.freeze_jsac_phase4b_policy_decisions import METHODS, assert_no_forbidden_target_fields, rank_and_queue
from pipeline.common import io as cio
from pipeline.evaluation.jsac_phase4_layer2 import FAIL, PASS


DEFAULT_CONFIG = ROOT / "experiments/config/jsac_two_timescale/phase5_unified_continual_replay.v2_1.json"
COMPARISONS = (
    ("echo_adaptive_minus_echo_static", "echo_adaptive", "echo_static", 0.1, 0, 0),
    ("echo_adaptive_minus_echo_static", "echo_adaptive", "echo_static", 0.2, 0, 1),
    ("echo_adaptive_minus_raw_adaptive", "echo_adaptive", "raw_history_adaptive", 0.1, 1, 0),
    ("echo_adaptive_minus_raw_adaptive", "echo_adaptive", "raw_history_adaptive", 0.2, 1, 1),
)


def read_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def read_jsonl(path: Path) -> list[dict[str, Any]]:
    return list(cio.read_jsonl(path))


def sha256_path(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def source_ref(path: Path) -> dict[str, Any]:
    return {"path": str(path.relative_to(ROOT)), "size_bytes": path.stat().st_size, "sha256": sha256_path(path)}


def verify_ref(item: dict[str, Any]) -> Path:
    path = ROOT / item["path"]
    if not path.exists() or sha256_path(path) != item["sha256"]:
        raise ValueError(f"frozen artifact hash failed: {item['path']}")
    return path


def write_json(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def write_jsonl(path: Path, rows: Iterable[dict[str, Any]]) -> dict[str, Any]:
    path.parent.mkdir(parents=True, exist_ok=True)
    count = 0
    with path.open("w", encoding="utf-8") as handle:
        for row in rows:
            handle.write(json.dumps(row, ensure_ascii=False, separators=(",", ":")) + "\n")
            count += 1
    return source_ref(path) | {"rows": count}


def id_hash(values: Iterable[str]) -> str:
    return hashlib.sha256("\n".join(sorted(str(value) for value in values)).encode()).hexdigest()


def block_contrast(
    windows: list[str],
    *,
    right_method: str,
    selected: dict[str, dict[str, dict[str, set[str]]]],
    rows_by_window: dict[str, list[dict[str, Any]]],
) -> dict[str, Any]:
    if not windows:
        return {"window_ids": [], "right_method": right_method, "hfc_difference": None}
    outcomes = {
        row["trace_id"]: row["target_outcome"]
        for window_id in windows
        for row in rows_by_window[window_id]
    }
    left = set().union(*(selected["echo_adaptive"]["0.1"][window_id] for window_id in windows))
    right = set().union(*(selected[right_method]["0.1"][window_id] for window_id in windows))
    return {"window_ids": windows, **paired_contrast(left, right, outcomes), "right_method": right_method}


def thirds(values: list[str]) -> tuple[list[str], list[str], list[str]]:
    base, remainder = divmod(len(values), 3)
    sizes = [base + (index < remainder) for index in range(3)]
    first = sizes[0]
    second = first + sizes[1]
    return values[:first], values[first:second], values[second:]


def percent(value: float | None) -> str:
    return "N/A" if value is None else f"{100.0 * value:.2f}%"


def report_markdown(result: dict[str, Any]) -> str:
    points = result["aggregate_operating_points"]
    rows = [
        "# JSAC Unified Continual Replay — Deterministic Layer-2 Primary",
        "",
        "> Every weekly score/ranking and Agent-visible state was frozen before that week's outcome entered the causal update stream. GPT choices are not used by this primary endpoint.",
