def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--config", type=Path, default=DEFAULT_CONFIG)
    args = parser.parse_args()
    config_path = args.config if args.config.is_absolute() else ROOT / args.config
    config = read_json(config_path)
    split_path = ROOT / config["outputs"]["split_audit"]
    split = read_json(split_path)
    result_root = ROOT / config["outputs"]["result_root"]
    output_root = result_root / "final_deterministic_primary_v2_1"
    result_path = output_root / "result.json"
    if result_path.exists():
        existing = read_json(result_path)
        for item in existing["artifacts"].values():
            verify_ref(item)
        print(json.dumps({"status": "EXISTING_DETERMINISTIC_PRIMARY_REVERIFIED", "result": str(result_path.relative_to(ROOT))}, indent=2))
        return
    if output_root.exists() and any(output_root.iterdir()):
        raise ValueError(f"deterministic output directory is non-empty: {output_root}")

    rows_by_window: dict[str, list[dict[str, Any]]] = defaultdict(list)
    window_sources: dict[str, Any] = {}
    memory_by_window: dict[str, dict[str, Any]] = {}
    all_target_count = 0
    exclusion_counts: Counter[str] = Counter()
    all_ids: set[str] = set()
    for window in split["replay"]["windows"]:
        window_id = str(window["window_id"])
        prepare_root = result_root / "windows" / window_id / "prepare"
        reveal_root = result_root / "windows" / window_id / "reveal"
        prepare_path = prepare_root / "manifest.json"
        reveal_path = reveal_root / "manifest.json"
        state_freeze_path = prepare_root / "agent_state_freeze_manifest_v2_1.json"
        prepare = read_json(prepare_path)
        reveal = read_json(reveal_path)
        state_freeze = read_json(state_freeze_path)
        if not all(prepare["integrity"].values()) or not all(reveal["integrity"].values()) or not all(state_freeze["integrity"].values()):
            raise ValueError(f"window freeze/reveal integrity failed: {window_id}")
        decisions_path = verify_ref(prepare["artifacts"]["deterministic_decisions"])
        labels_path = verify_ref(reveal["artifacts"]["revealed_labels"])
        decisions = read_jsonl(decisions_path)
        labels = {str(row["trace_id"]): row for row in read_jsonl(labels_path)}
        if len(decisions) != int(window["target_count"]) or id_hash(row["trace_id"] for row in decisions) != window["target_id_sha256"]:
            raise ValueError(f"window decision population changed: {window_id}")
        if set(labels) != {str(row["trace_id"]) for row in decisions}:
            raise ValueError(f"window labels do not cover decisions: {window_id}")
        for decision in decisions:
            assert_no_forbidden_target_fields(decision)
            trace_id = str(decision["trace_id"])
