            all_ids.add(trace_id)
            label = labels[trace_id]
            if not bool(label["primary_risk_eligible"]):
                exclusion_counts[f"execution::{label['execution_class']}"] += 1
                exclusion_counts[f"outcome::{label['target_outcome']}"] += 1
                continue
            rows_by_window[window_id].append({
                "trace_id": trace_id,
                "window_id": window_id,
                "target_outcome": str(label["target_outcome"]),
                "execution_class": str(label["execution_class"]),
                "site_name": str(label["site_name"] or trace_id),
                "scores": decision["scores"],
                "tie_score": int(decision["tie_score"]),
                "memory": decision["memory"],
            })
        all_target_count += len(decisions)
        memory_by_window[window_id] = prepare["memory"]
        window_sources[window_id] = {
            "prepare_manifest": source_ref(prepare_path),
            "agent_state_freeze_manifest": source_ref(state_freeze_path),
            "reveal_manifest": source_ref(reveal_path),
        }

    window_ids = [str(row["window_id"]) for row in split["replay"]["windows"]]
    outcomes = {row["trace_id"]: row["target_outcome"] for rows in rows_by_window.values() for row in rows}
    pass_count = sum(value == PASS for value in outcomes.values())
    fail_count = sum(value == FAIL for value in outcomes.values())
    budgets = [float(value) for value in config["primary_consumer"]["review_budgets"]]
    selected: dict[str, dict[str, dict[str, set[str]]]] = {
        method: {str(budget): {} for budget in budgets} for method in METHODS
    }
    evaluated_queues: list[dict[str, Any]] = []
    score_to_queue: dict[str, Any] = {}
    weekly: dict[str, Any] = {}
    for window_id in window_ids:
        rows = rows_by_window[window_id]
        row_by_id = {row["trace_id"]: row for row in rows}
        ids = sorted(row_by_id)
        ranks: dict[str, dict[str, int]] = {}
        for method in METHODS:
            scores = {trace_id: float(row_by_id[trace_id]["scores"][method]) for trace_id in ids}
            method_ranks, method_selected, ordered = rank_and_queue(ids, scores, budgets)
            ranks[method] = method_ranks
            for budget in budgets:
                key = str(budget)
                selected[method][key][window_id] = method_selected[key]
                evaluated_queues.append({
                    "window_id": window_id,
                    "method": method,
                    "budget": budget,
                    "eligible_target_count": len(ids),
                    "ordered_trace_ids": ordered[key],
                    "ordered_trace_id_sha256": id_hash(ordered[key]),
                })
        window_outcomes = {trace_id: outcomes[trace_id] for trace_id in ids}
        weekly[window_id] = {
            "population": {
                "target_count": len(ids),
                "pass_count": sum(value == PASS for value in window_outcomes.values()),
                "fail_count": sum(value == FAIL for value in window_outcomes.values()),
            },
            "memory": memory_by_window[window_id],
            "operating_points": {
                method: {
                    str(budget): operating_point(selected[method][str(budget)][window_id], window_outcomes)
                    for budget in budgets
                }
                for method in METHODS
            },
            "contrasts": {},
        }
        for comparison_id, left, right, budget, _, _ in COMPARISONS:
            weekly[window_id]["contrasts"][f"{comparison_id}@{budget}"] = paired_contrast(
                selected[left][str(budget)][window_id], selected[right][str(budget)][window_id], window_outcomes
            ) | {"right_method": right}
        static_scores = {trace_id: float(row_by_id[trace_id]["scores"]["echo_static"]) for trace_id in ids}
        adaptive_scores = {trace_id: float(row_by_id[trace_id]["scores"]["echo_adaptive"]) for trace_id in ids}
        score_to_queue[window_id] = {
            "cumulative_added_visible_history": int(memory_by_window[window_id]["adaptive_history_count"]) - int(memory_by_window[window_id]["static_history_count"]),
            "score_changed_count": sum(abs(static_scores[x] - adaptive_scores[x]) > 1e-15 for x in ids),
            "rank_changed_count": sum(ranks["echo_static"][x] != ranks["echo_adaptive"][x] for x in ids),
            "queue_crossing_count": {
                str(budget): len(selected["echo_static"][str(budget)][window_id] ^ selected["echo_adaptive"][str(budget)][window_id])
                for budget in budgets
            },
        }

    aggregate_selected = {
        method: {
            str(budget): set().union(*(selected[method][str(budget)][window_id] for window_id in window_ids))
            for budget in budgets
        }
        for method in METHODS
    }
    aggregate_points = {
        method: {
            str(budget): operating_point(aggregate_selected[method][str(budget)], outcomes)
            for budget in budgets
        }
        for method in METHODS
    }
    stats = config["statistics"]
    comparisons: list[dict[str, Any]] = []
    for comparison_id, left, right, budget, comparison_index, budget_index in COMPARISONS:
        key = str(budget)
        seed = int(stats["base_seed"]) + 1000 * comparison_index + 100 * budget_index
        print(f"statistics {comparison_id}@{budget}: ticket bootstrap", flush=True)
        ticket = bootstrap_comparison(
            rows_by_window=rows_by_window,
            left_method=left,
            right_method=right,
            budget=budget,
            replicates=int(stats["bootstrap_replicates"]),
            seed=seed + 11,
            cluster=False,
        )
        print(f"statistics {comparison_id}@{budget}: site-cluster bootstrap", flush=True)
        cluster = bootstrap_comparison(
            rows_by_window=rows_by_window,
            left_method=left,
            right_method=right,
            budget=budget,
            replicates=int(stats["bootstrap_replicates"]),
            seed=seed + 29,
            cluster=True,
        )
        comparisons.append({
            "comparison_id": comparison_id,
            "left_method": left,
            "right_method": right,
            "budget": budget,
            "point": paired_contrast(aggregate_selected[left][key], aggregate_selected[right][key], outcomes) | {"right_method": right},
            "ticket_bootstrap": ticket,
            "site_cluster_bootstrap": cluster,
            "permutation": permutation_test(
                left=aggregate_selected[left][key],
                right=aggregate_selected[right][key],
                outcomes=outcomes,
                replicates=int(stats["permutation_replicates"]),
                seed=seed + 47,
            ),
        })
    comparisons = holm_adjust(comparisons)

    updated_windows = [
        window_id for window_id in window_ids
        if memory_by_window[window_id]["adaptive_history_id_sha256"] != memory_by_window[window_id]["static_history_id_sha256"]
    ]
    primary_net = {
        window_id: weekly[window_id]["contrasts"]["echo_adaptive_minus_echo_static@0.1"]["net_additional_captured_fail"]
        for window_id in updated_windows
    }
    positive = [value for value in primary_net.values() if value > 0]
    lowo: dict[str, Any] = {}
    for dropped in updated_windows:
        kept = [window_id for window_id in window_ids if window_id != dropped]
        kept_outcomes = {row["trace_id"]: row["target_outcome"] for window_id in kept for row in rows_by_window[window_id]}
        left = set().union(*(selected["echo_adaptive"]["0.1"][window_id] for window_id in kept))
        right = set().union(*(selected["echo_static"]["0.1"][window_id] for window_id in kept))
        lowo[dropped] = paired_contrast(left, right, kept_outcomes)
    early, middle, late = thirds(updated_windows)
    cumulative: dict[str, Any] = {}
    for index, window_id in enumerate(window_ids):
        included = window_ids[: index + 1]
        included_outcomes = {row["trace_id"]: row["target_outcome"] for value in included for row in rows_by_window[value]}
        left = set().union(*(selected["echo_adaptive"]["0.1"][value] for value in included))
        right = set().union(*(selected["echo_static"]["0.1"][value] for value in included))
        cumulative[window_id] = paired_contrast(left, right, included_outcomes)
    temporal = {
        "updated_windows": updated_windows,
        "primary_net_fail_by_updated_window": primary_net,
        "positive_updated_window_count": sum(value > 0 for value in primary_net.values()),
        "positive_contribution_concentration": max(positive) / sum(positive) if positive else None,
        "leave_one_updated_window_out": lowo,
        "early_middle_late": {
            "early_adaptive_minus_static": block_contrast(early, right_method="echo_static", selected=selected, rows_by_window=rows_by_window),
            "middle_adaptive_minus_static": block_contrast(middle, right_method="echo_static", selected=selected, rows_by_window=rows_by_window),
            "late_adaptive_minus_static": block_contrast(late, right_method="echo_static", selected=selected, rows_by_window=rows_by_window),
            "early_adaptive_minus_raw": block_contrast(early, right_method="raw_history_adaptive", selected=selected, rows_by_window=rows_by_window),
            "middle_adaptive_minus_raw": block_contrast(middle, right_method="raw_history_adaptive", selected=selected, rows_by_window=rows_by_window),
            "late_adaptive_minus_raw": block_contrast(late, right_method="raw_history_adaptive", selected=selected, rows_by_window=rows_by_window),
        },
        "cumulative_primary": cumulative,
    }

    output_root.mkdir(parents=True, exist_ok=True)
    target_ref = write_jsonl(output_root / "primary_evaluation_targets.jsonl", [row for value in window_ids for row in rows_by_window[value]])
    queues_path = output_root / "evaluated_review_queues.json"
    write_json(queues_path, {"schema_version": "jsac.unified_evaluated_queues.v2_1", "queues": evaluated_queues})
    result = {
        "schema_version": "jsac.unified_continual_replay_deterministic_primary.v2_1",
        "status": "COMPLETED_AFTER_ALL_WEEK_CAUSAL_DECISION_AND_AGENT_STATE_FREEZES",
        "population": {
            "all_scored_before_reveal": all_target_count,
            "primary_eligible": len(outcomes),
            "pass_count": pass_count,
            "fail_count": fail_count,
            "excluded_after_reveal": all_target_count - len(outcomes),
            "exclusion_counts": dict(sorted(exclusion_counts.items())),
            "window_count": len(window_ids),
        },
        "aggregate_operating_points": aggregate_points,
        "comparisons": comparisons,
        "weekly": weekly,
        "temporal_distribution": temporal,
        "score_to_queue": score_to_queue,
        "primary_interpretation": "ECHO-Adaptive minus ECHO-Static at weekly 10% Review is the prespecified primary endpoint; other comparisons are secondary.",
        "claim_boundary": "Retrospective fixed-budget historical-failure capture on executed bundles; not recommendation success, causal effect, KPI improvement, or online benefit.",
        "freeze_reveal_integrity": {
            "all_windows_prepared_before_their_outcome_release": True,
            "all_agent_visible_states_frozen_before_their_outcome_release": True,
            "strict_seven_day_future_admission": True,
            "ranker_retrained_during_replay": False,
            "reference_or_consumer_changed": False,
            "gpt_choices_used_by_primary": False,
        },
        "statistics_execution": {
            "bootstrap_replicates": int(stats["bootstrap_replicates"]),
            "permutation_replicates": int(stats["permutation_replicates"]),
            "base_seed": int(stats["base_seed"]),
            "multiple_testing": "Holm over four prespecified comparisons",
        },
        "artifacts": {
            "primary_evaluation_targets": target_ref,
            "evaluated_review_queues": source_ref(queues_path),
        },
        "sources": {
            "config": source_ref(config_path),
            "split_audit": source_ref(split_path),
            "windows": window_sources,
            "evaluator": source_ref(Path(__file__).resolve()),
        },
    }
    report_path = output_root / "report.md"
    report_path.write_text(report_markdown(result), encoding="utf-8")
    result["artifacts"]["report"] = source_ref(report_path)
    write_json(result_path, result)
    print(json.dumps({
        "status": result["status"],
        "population": result["population"],
        "primary": next(row for row in comparisons if row["comparison_id"] == "echo_adaptive_minus_echo_static" and row["budget"] == 0.1),
        "result": str(result_path.relative_to(ROOT)),
        "report": str(report_path.relative_to(ROOT)),
    }, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Compile attribution-safe action risk profiles and audit them on dev."""
from __future__ import annotations

import json
import hashlib
from collections import Counter, defaultdict
from pathlib import Path
from typing import Any, Callable

ROOT = Path(__file__).resolve().parents[1]
SRC = ROOT / "experiments/results/plan_certification_o0_o1_audit_20260712"
OUT = ROOT / "experiments/results/calibrated_specific_plan_risk_dev_20260712"
PRIOR_STRENGTH = 5.0


def read(name: str) -> list[dict[str, Any]]:
    return [json.loads(line) for line in (SRC / name).open(encoding="utf-8") if line.strip()]


def norm(value: Any) -> str:
    return str(value or "").strip().lower()


def direction(action: dict[str, Any]) -> str:
    rule = norm(action.get("adjustment_rule"))
    if rule.startswith("+"):
        return "increase"
    if rule.startswith("-"):
        return "decrease"
    before, after = action.get("before_value"), action.get("after_value")
    try:
        return "increase" if float(after) > float(before) else "decrease" if float(after) < float(before) else "keep"
    except (TypeError, ValueError):
        return rule or "unknown"


def context(row: dict[str, Any]) -> tuple[str, ...]:
    ticket = row["runtime_input"]["ticket_context"]
    return (norm(ticket.get("primary_issue_type")), norm(ticket.get("vendor")), norm(ticket.get("system")))


def action_identity(action: dict[str, Any]) -> tuple[str, ...]:
    return (norm(action.get("scheme_id")), norm(action.get("param_object")), norm(action.get("param_en_name") or action.get("param_cn_name")))


def exact_key(row: dict[str, Any], action: dict[str, Any]) -> tuple[str, ...]:
    return context(row) + action_identity(action) + (norm(action.get("before_value")), norm(action.get("after_value")))


def core_key(row: dict[str, Any], action: dict[str, Any]) -> tuple[str, ...]:
    return context(row) + action_identity(action) + (direction(action),)


def broad_key(row: dict[str, Any], action: dict[str, Any]) -> tuple[str, ...]:
    return context(row) + (norm(action.get("scheme_group")), norm(action.get("param_object")), direction(action))


def bundle_shape(row: dict[str, Any]) -> tuple[tuple[str, ...], ...]:
    return tuple(sorted(action_identity(action) + (direction(action),) for action in row["runtime_input"]["proposed_plan_bundle"]))


def group(rows: list[dict[str, Any]], key: Callable[[dict[str, Any]], Any]) -> dict[Any, Counter]:
    out: dict[Any, Counter] = defaultdict(Counter)
    for row in rows:
        out[key(row)][row["evaluator_only"]["long_eval_outcome"]] += 1
    return out


def posterior(counts: Counter, prior_rate: float, prior_strength: float) -> float:
    passed = int(counts.get("long_eval_pass", 0))
    failed = int(counts.get("long_eval_fail", 0))
    return (failed + prior_rate * prior_strength) / (passed + failed + prior_strength)


def auc(rows: list[tuple[float, int]]) -> float | None:
    positive = sum(label for _, label in rows)
    negative = len(rows) - positive
    if not positive or not negative:
        return None
    ordered = sorted(rows, key=lambda item: item[0])
    rank_sum = 0.0
    index = 0
    while index < len(ordered):
        end = index + 1
        while end < len(ordered) and ordered[end][0] == ordered[index][0]:
            end += 1
        average_rank = ((index + 1) + end) / 2.0
        rank_sum += average_rank * sum(label for _, label in ordered[index:end])
        index = end
    return (rank_sum - positive * (positive + 1) / 2.0) / (positive * negative)


def calibration(rows: list[tuple[float, int]]) -> dict[str, Any]:
    if not rows:
        return {"count": 0}
    prevalence = sum(label for _, label in rows) / len(rows)
    brier = sum((score - label) ** 2 for score, label in rows) / len(rows)
    bins = []
    ece = 0.0
    for bucket in range(10):
        selected = [(score, label) for score, label in rows if min(9, int(score * 10)) == bucket]
        if not selected:
            continue
        mean_score = sum(score for score, _ in selected) / len(selected)
        observed = sum(label for _, label in selected) / len(selected)
        ece += len(selected) / len(rows) * abs(mean_score - observed)
        bins.append({"bucket": bucket, "count": len(selected), "mean_score": mean_score, "observed_fail_rate": observed})
    return {"count": len(rows), "fail_prevalence": prevalence, "auc": auc(rows), "brier": brier, "prevalence_brier": prevalence * (1 - prevalence), "ece_10": ece, "bins": bins}


def frontier(rows: list[dict[str, Any]], score_key: str) -> dict[str, Any]:
    thresholds = sorted({float(row[score_key]) for row in rows} | {0.0, 1.000001})
    points = []
    for threshold in thresholds:
        counts = Counter()
        for row in rows:
            route = "deferred" if row[score_key] >= threshold else "certified"
            counts[f"{row['outcome']}::{route}"] += 1
        pc, pd = counts["long_eval_pass::certified"], counts["long_eval_pass::deferred"]
        fd, fc = counts["long_eval_fail::deferred"], counts["long_eval_fail::certified"]
        points.append({"threshold": threshold, "pass_retention": pc / (pc + pd), "fail_deflection": fd / (fd + fc)})
    roc = sorted((1 - point["pass_retention"], point["fail_deflection"]) for point in points)
    curve_auc = sum((x2 - x1) * (y1 + y2) / 2 for (x1, y1), (x2, y2) in zip(roc, roc[1:]))
    best = lambda target: max((point for point in points if point["pass_retention"] >= target), key=lambda point: (point["fail_deflection"], point["pass_retention"]))
    return {"auc": curve_auc, "retention_90": best(0.90), "retention_95": best(0.95), "points": points}


def main() -> None:
    train = [row for row in read("train_bundles.jsonl") if row["evaluator_only"].get("primary_pilot_eligible")]
    dev = [row for row in read("dev_bundles.jsonl") if row["evaluator_only"].get("primary_pilot_eligible")]
    direct_train = [row for row in train if row["runtime_input"]["action_count"] == 1]
    broad_counts: dict[tuple[str, ...], Counter] = defaultdict(Counter)
    exact_counts: dict[tuple[str, ...], Counter] = defaultdict(Counter)
    core_counts: dict[tuple[str, ...], Counter] = defaultdict(Counter)
    exact_parent: dict[tuple[str, ...], tuple[str, ...]] = {}
    core_parent: dict[tuple[str, ...], tuple[str, ...]] = {}
    for row in direct_train:
        action = row["runtime_input"]["proposed_plan_bundle"][0]
        outcome = row["evaluator_only"]["long_eval_outcome"]
        broad_counts[broad_key(row, action)][outcome] += 1
        exact_counts[exact_key(row, action)][outcome] += 1
        core_counts[core_key(row, action)][outcome] += 1
        exact_parent[exact_key(row, action)] = broad_key(row, action)
        core_parent[core_key(row, action)] = broad_key(row, action)

    train_bundle_exact = group(train, lambda row: row["runtime_input"]["bundle_hash"])
    train_bundle_context = group(train, lambda row: context(row) + (bundle_shape(row),))
    train_bundle_shape = group(train, bundle_shape)

    def raw_bundle_risk(row: dict[str, Any]) -> float:
        for counts in (train_bundle_exact.get(row["runtime_input"]["bundle_hash"]), train_bundle_context.get(context(row) + (bundle_shape(row),)), train_bundle_shape.get(bundle_shape(row))):
            if counts and sum(counts.values()):
                return posterior(counts, 0.5, 2.0)
        return 0.0

    profile_rows = []
    for family, rows_by_key, parents, min_support in (
        ("direct_single_action_exact", exact_counts, exact_parent, 2),
        ("direct_single_action_core", core_counts, core_parent, 5),
    ):
        for key, counts in rows_by_key.items():
            parent_key = parents[key]
            parent_counts = broad_counts[parent_key]
            parent_rate = posterior(parent_counts, 0.5, 2.0)
            encoded = json.dumps([family, *key], ensure_ascii=False, separators=(",", ":"))
            profile_rows.append({
                "profile_id": "pcr_" + hashlib.sha256(encoded.encode("utf-8")).hexdigest()[:12],
                "schema_version": "plan_certification_action_risk_profile.v1",
                "key_family": family,
                "key_values": list(key),
                "attribution": "mature_single_action_only",
                "support_count": sum(counts.values()),
                "long_eval_pass_count": int(counts.get("long_eval_pass", 0)),
                "long_eval_fail_count": int(counts.get("long_eval_fail", 0)),
                "broad_prior_key": list(parent_key),
                "broad_prior_failure_rate": parent_rate,
                "broad_prior_strength": PRIOR_STRENGTH,
                "failure_posterior_mean": posterior(counts, parent_rate, PRIOR_STRENGTH),
                "routing_eligible": sum(counts.values()) >= min_support,
                "multi_action_outcome_broadcast": False,
            })

    scored = []
    strict = []
    coverage = Counter()
    for row in dev:
        action_scores = []
        layers = []
        for action in row["runtime_input"]["proposed_plan_bundle"]:
            broad = broad_counts.get(broad_key(row, action), Counter())
            broad_rate = posterior(broad, 0.5, 2.0) if sum(broad.values()) else 0.5
            exact = exact_counts.get(exact_key(row, action), Counter())
            core = core_counts.get(core_key(row, action), Counter())
            if sum(exact.values()) >= 2:
                risk, layer, count = posterior(exact, broad_rate, PRIOR_STRENGTH), "direct_exact", sum(exact.values())
            elif sum(core.values()) >= 5:
                risk, layer, count = posterior(core, broad_rate, PRIOR_STRENGTH), "direct_core", sum(core.values())
            else:
                risk, layer, count = None, "unseen", 0
            layers.append(layer)
            if risk is not None:
                action_scores.append(risk)
                coverage[layer] += 1
            coverage[f"action::{layer}"] += 1
        raw = raw_bundle_risk(row)
        specific = max(action_scores) if action_scores else None
        specific_mean = sum(action_scores) / len(action_scores) if action_scores else None
        specific_top2 = sum(sorted(action_scores, reverse=True)[:2]) / min(2, len(action_scores)) if action_scores else None
        specific_coverage = len(action_scores) / row["runtime_input"]["action_count"]
        override = specific if specific is not None else raw
        mean_fallback = specific_mean if specific_mean is not None else raw
        top2_fallback = specific_top2 if specific_top2 is not None else raw
        mean_blend = (raw + specific_mean) / 2 if specific_mean is not None else raw
        coverage_blend = specific_coverage * specific_mean + (1 - specific_coverage) * raw if specific_mean is not None else raw
        outcome = row["evaluator_only"]["long_eval_outcome"]
        scored.append({"trace_id": row["trace_id"], "outcome": outcome, "raw_bundle_risk": raw, "specific_override_risk": override, "specific_mean_fallback_risk": mean_fallback, "specific_top2_fallback_risk": top2_fallback, "bundle_specific_mean_blend_risk": mean_blend, "coverage_weighted_specific_blend_risk": coverage_blend, "specific_risk": specific, "specific_coverage": specific_coverage, "layers": layers})
        if row["runtime_input"]["action_count"] == 1 and specific is not None:
            strict.append((specific, int(outcome == "long_eval_fail")))

    payload = {
        "schema_version": "calibrated_specific_plan_risk.dev.v1",
        "status": "completed_dev_only",
        "contract": {
            "holdout_accessed": False,
            "direct_evidence_source": "train mature single-action bundles only",
            "multi_action_outcome_broadcast": False,
            "broad_prior_strength": PRIOR_STRENGTH,
            "broad_prior_hard_route": False,
            "dev_outcomes_evaluator_only": True,
        },
        "counts": {"train_primary": len(train), "train_direct_single_action": len(direct_train), "dev_primary": len(dev), "strict_dev_scored": len(strict)},
        "coverage": dict(coverage),
        "strict_single_action_calibration": calibration(strict),
        "bundle_frontiers": {
            "raw_bundle_reference": frontier(scored, "raw_bundle_risk"),
            "specific_override_then_bundle_fallback": frontier(scored, "specific_override_risk"),
            "specific_mean_then_bundle_fallback": frontier(scored, "specific_mean_fallback_risk"),
            "specific_top2_then_bundle_fallback": frontier(scored, "specific_top2_fallback_risk"),
            "bundle_specific_mean_equal_blend": frontier(scored, "bundle_specific_mean_blend_risk"),
            "coverage_weighted_specific_blend": frontier(scored, "coverage_weighted_specific_blend_risk"),
        },
    }
    OUT.mkdir(parents=True, exist_ok=True)
    (OUT / "summary.json").write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    with (OUT / "action_risk_profiles.jsonl").open("w", encoding="utf-8") as handle:
        for profile in profile_rows:
            handle.write(json.dumps(profile, ensure_ascii=False) + "\n")
    with (OUT / "bundle_risk_profiles.jsonl").open("w", encoding="utf-8") as handle:
        for family, groups in (
            ("bundle_exact", train_bundle_exact),
            ("bundle_context_shape", train_bundle_context),
            ("bundle_shape", train_bundle_shape),
        ):
            for key, counts in groups.items():
                encoded = json.dumps([family, key], ensure_ascii=False, separators=(",", ":"))
                handle.write(json.dumps({
                    "profile_id": "pbr_" + hashlib.sha256(encoded.encode("utf-8")).hexdigest()[:12],
                    "schema_version": "plan_certification_bundle_risk_profile.v1",
                    "key_family": family,
                    "key_values": key,
                    "support_count": sum(counts.values()),
                    "long_eval_pass_count": int(counts.get("long_eval_pass", 0)),
                    "long_eval_fail_count": int(counts.get("long_eval_fail", 0)),
                    "failure_posterior_mean": posterior(counts, 0.5, 2.0),
                    "attribution": "executed_plan_bundle",
                    "component_action_outcome_broadcast": False,
                }, ensure_ascii=False) + "\n")
    with (OUT / "samples.jsonl").open("w", encoding="utf-8") as handle:
        for row in scored:
            handle.write(json.dumps(row, ensure_ascii=False) + "\n")
    print(json.dumps({"counts": payload["counts"], "coverage": payload["coverage"], "strict": payload["strict_single_action_calibration"], "frontiers": {key: {k: value[k] for k in ("auc", "retention_90", "retention_95")} for key, value in payload["bundle_frontiers"].items()}}, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

