def read_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def write_json(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def read_jsonl(path: Path) -> Iterable[dict[str, Any]]:
    with path.open(encoding="utf-8") as handle:
        for line in handle:
            if line.strip():
                yield json.loads(line)


def rel(path: Path) -> str:
    return path.resolve().relative_to(PROJECT_ROOT).as_posix()


def ref(path: Path) -> dict[str, str]:
    return {"path": rel(path), "sha256": path_sha256(path)}


def resolve_project_path(value: str | Path | None) -> Path | None:
    if value is None:
        return None
    path = Path(value)
    return path if path.is_absolute() else PROJECT_ROOT / path


def rate(num: int | float, den: int | float) -> float | None:
    return round(float(num) / float(den), 6) if den else None


def metric(num: int | float, den: int | float) -> dict[str, int | float | None]:
    return {"numerator": num, "denominator": den, "value": rate(num, den)}


def table2_method_roster(method_ids: list[str]) -> list[dict[str, Any]]:
    available = set(method_ids)
    out: list[dict[str, Any]] = []
    for item in TABLE2_METHOD_ROSTER:
        row = dict(item)
        method_id = str(row.get("method_id") or "")
        if method_id == MAIN_ECHO_METHOD and VALUE_REBASE_METHOD in available:
            method_id = VALUE_REBASE_METHOD
            row["method_id"] = method_id
            row["source_contract"] = (
                "Compiled C8 case-memory candidate adapter plus train-only ECHO-Mem evidence assembly, "
                "compiled rank/rerank, support/counter routing, safety arbitration, and leak-safe train-only "
                "pre-decision parameter snapshot value rebasing. The source candidate set is not the same "
                "raw-train set as Structured Case Retrieval."
            )
        default_status = str(row.pop("default_status", "planned"))
        row["result_status"] = "completed_dev_only" if method_id in available else default_status
        row["holdout_status"] = "holdout_locked"
        out.append(row)
    return out


def normalize_table2_method_roster_for_dataset(roster: list[dict[str, Any]], dataset_role: str) -> list[dict[str, Any]]:
    if dataset_role != "holdout":
        return roster
    out: list[dict[str, Any]] = []
    for item in roster:
        row = dict(item)
        if row.get("result_status") == "completed_dev_only":
            row["result_status"] = "completed_holdout_frozen"
            row["holdout_status"] = "completed_no_tuning"
        elif row.get("result_status") == "planned_current_artifact":
            row["result_status"] = "pending_holdout"
            row["holdout_status"] = "pending_holdout_run"
        else:
            row["holdout_status"] = "pending_holdout_run"
        out.append(row)
    return out


def pct(value: float | None) -> str:
    return "n/a" if value is None else f"{value * 100:.1f}%"


def signed_pp(value: float | None) -> str:
    return "n/a" if value is None else f"{value * 100:+.1f}pp"


def latest_run_dir(pattern: str) -> Path:
    candidates = sorted(
        (path for path in RESULTS.glob(pattern) if path.is_dir()),
        key=lambda path: path.stat().st_mtime,
        reverse=True,
    )
    if not candidates:
        raise FileNotFoundError(f"no RunArtifact found under experiments/results/{pattern}")
    return candidates[0]


def is_failed_observed_action(action: dict[str, Any]) -> bool:
    return (
        action.get("exec_state") == "exec_success"
        and action.get("long_eval_result") == "long_eval_fail"
        and bool(action.get("scheme_id"))
    )


def trace_meta(dataset_role: str) -> dict[str, dict[str, Any]]:
    out: dict[str, dict[str, Any]] = {}
    for trace in load_dataset_traces(dataset_role):
        trace_id = str(trace.get("trace_id") or "")
        outcome = str((trace.get("aggregate") or {}).get("ticket_outcome") or "long_eval_unknown")
        failed_actions = [
            action_to_gold(action, trace)
            for action in trace.get("actions") or []
            if isinstance(action, dict) and is_failed_observed_action(action)
        ]
        out[trace_id] = {
            "trace": trace,
            "ticket_outcome": outcome,
            "failed_actions": failed_actions,
            "failed_action_count": len(failed_actions),
        }
    return out


def decision_bucket(row: dict[str, Any]) -> str:
    gate = str(row.get("gate_decision") or "")
    if gate in ACCEPTED_GATES or bool(row.get("auto_eligible")):
        return "auto"
    if gate == "reject" or bool(row.get("rejected")):
        return "reject"
    return "review"


def is_auto(row: dict[str, Any]) -> bool:
    return decision_bucket(row) == "auto"


def gate_reason(row: dict[str, Any]) -> str:
    decision = row.get("decision") if isinstance(row.get("decision"), dict) else {}
    diagnostics = decision.get("gate_diagnostics") if isinstance(decision.get("gate_diagnostics"), dict) else {}
    return str(row.get("gate_reason") or diagnostics.get("gate_reason") or "")


def is_similarity_abstention(row: dict[str, Any]) -> bool:
    return gate_reason(row) == "low_similarity_abstention"


def action_supported(row: dict[str, Any]) -> bool:
    return str(row.get("action_equivalence_level") or "") in {
        "strongly_verifiable",
        "weakly_verifiable",
    }


def recommended_actions(sample: dict[str, Any]) -> list[dict[str, Any]]:
    decision = sample.get("decision") if isinstance(sample.get("decision"), dict) else {}
    action_set = decision.get("recommended_action_set")
    if isinstance(action_set, list):
        actions = [item for item in action_set if isinstance(item, dict) and item]
        if actions:
            return actions
    rec = decision.get("recommended_action")
    return [rec] if isinstance(rec, dict) and rec else []


def load_run_samples(run_dir: Path) -> tuple[dict[str, list[dict[str, Any]]], dict[str, Any], dict[str, dict[str, Any]]]:
    spec = read_json(run_dir / "spec.json")
    manifest = read_json(run_dir / "artifact_manifest.json")
    dataset_role = str(spec.get("dataset_role") or "dev")
    meta = trace_meta(dataset_role)

    rows_by_method: dict[str, list[dict[str, Any]]] = defaultdict(list)
    outcome_counts_by_method: dict[str, Counter[str]] = defaultdict(Counter)

    for sample in read_jsonl(run_dir / "samples.jsonl"):
        method_id = str(sample.get("method_id") or "")
        trace_id = str(sample.get("trace_id") or "")
        info = meta.get(trace_id, {})
        outcome = str(info.get("ticket_outcome") or "long_eval_unknown")
        classification = dict(sample.get("classification") or {})
        classification.setdefault("method_id", method_id)
        classification.setdefault("trace_id", trace_id)
        classification["ticket_outcome"] = outcome
        classification["decision"] = sample.get("decision") if isinstance(sample.get("decision"), dict) else {}
        classification["eval"] = sample.get("eval") if isinstance(sample.get("eval"), dict) else {}
        classification["recommended_actions"] = recommended_actions(sample)
        classification["failed_actions"] = list(info.get("failed_actions") or [])
        classification["failed_action_count"] = int(info.get("failed_action_count") or 0)
        rows_by_method[method_id].append(classification)
        outcome_counts_by_method[method_id][outcome] += 1

    source_meta = {
        "dataset_role": dataset_role,
        "run_artifact": {
            "run_id": manifest.get("run_id"),
            "path": rel(run_dir),
            "experiment_spec_hash": manifest.get("experiment_spec_hash"),
        },
        "sources": {
            "samples": ref(run_dir / "samples.jsonl"),
            "summary": ref(run_dir / "summary.json"),
            "spec": ref(run_dir / "spec.json"),
            "artifact_manifest": ref(run_dir / "artifact_manifest.json"),
        },
        "source_outcome_distribution_by_method": {
            method: dict(sorted(counts.items()))
            for method, counts in sorted(outcome_counts_by_method.items())
        },
    }
    return dict(rows_by_method), source_meta, meta


def load_run_samples_many(run_dirs: list[Path]) -> tuple[dict[str, list[dict[str, Any]]], dict[str, Any], dict[str, dict[str, Any]]]:
    if not run_dirs:
        raise ValueError("at least one RunArtifact directory is required")
    merged_rows: dict[str, list[dict[str, Any]]] = {}
    dataset_role: str | None = None
    traces_by_id: dict[str, dict[str, Any]] | None = None
    source_metas: list[dict[str, Any]] = []
    outcome_distributions: dict[str, dict[str, int]] = {}

    for run_dir in run_dirs:
        rows_by_method, meta, traces = load_run_samples(run_dir)
        role = str(meta.get("dataset_role") or "")
        if dataset_role is None:
            dataset_role = role
            traces_by_id = traces
        elif role != dataset_role:
            raise ValueError(f"cannot merge RunArtifacts with different dataset_role: {dataset_role!r} vs {role!r}")
        for method_id, rows in rows_by_method.items():
            if method_id in merged_rows:
                raise ValueError(f"duplicate method_id across RunArtifacts: {method_id}")
            merged_rows[method_id] = rows
        source_metas.append(meta)
        for method_id, counts in (meta.get("source_outcome_distribution_by_method") or {}).items():
            outcome_distributions[str(method_id)] = {str(k): int(v) for k, v in dict(counts).items()}

    run_artifacts = [meta.get("run_artifact") or {} for meta in source_metas]
    primary_meta = source_metas[0]
    source_meta = {
        "dataset_role": dataset_role or "dev",
        "run_artifact": {
            "run_id": "+".join(str(item.get("run_id") or "") for item in run_artifacts if item.get("run_id")),
            "path": ";".join(str(item.get("path") or "") for item in run_artifacts if item.get("path")),
            "experiment_spec_hash": "+".join(
                str(item.get("experiment_spec_hash") or "")
                for item in run_artifacts
                if item.get("experiment_spec_hash")
            ),
        },
        "run_artifacts": run_artifacts,
        "sources": {
            **(primary_meta.get("sources") or {}),
            "merged_run_artifacts": run_artifacts,
        },
        "source_outcome_distribution_by_method": outcome_distributions,
    }
    return merged_rows, source_meta, traces_by_id or {}


def summarize_positive_plan_selection(method_id: str, rows: list[dict[str, Any]]) -> dict[str, Any]:
    pass_rows = [row for row in rows if row.get("ticket_outcome") == "long_eval_pass"]
    total = len(pass_rows)
    auto_rows = [row for row in pass_rows if is_auto(row)]
    review_rows = [row for row in pass_rows if decision_bucket(row) == "review"]
    reject_rows = [row for row in pass_rows if decision_bucket(row) == "reject"]
    non_auto_rows = [row for row in pass_rows if not is_auto(row)]
    action_rows = [row for row in pass_rows if action_supported(row)]
    plan_rows = [row for row in pass_rows if bool(row.get("plan_match"))]
    auto_action_rows = [row for row in auto_rows if action_supported(row)]
    review_action_rows = [row for row in review_rows if action_supported(row)]
    reject_action_rows = [row for row in reject_rows if action_supported(row)]
    auto_plan_rows = [row for row in auto_rows if bool(row.get("plan_match"))]
    withheld_action_rows = [row for row in non_auto_rows if action_supported(row)]
    unsupported_auto_rows = [row for row in auto_rows if not action_supported(row)]
    unsupported_review_rows = [row for row in review_rows if not action_supported(row)]
    unsupported_reject_rows = [row for row in reject_rows if not action_supported(row)]

    return {
        "method_id": method_id,
        "method_label": METHOD_LABELS.get(method_id, method_id),
        "sample_scope": "long_eval_pass",
        "counts": {
            "pass_ticket_count": total,
            "auto_count": len(auto_rows),
            "review_count": len(review_rows),
            "reject_count": len(reject_rows),
            "review_or_reject_count": len(non_auto_rows),
            "top1_plan_supported": len(plan_rows),
            "top1_action_supported": len(action_rows),
            "auto_plan_supported": len(auto_plan_rows),
            "auto_action_supported": len(auto_action_rows),
            "review_action_supported": len(review_action_rows),
            "reject_action_supported": len(reject_action_rows),
            "auto_not_action_supported": len(unsupported_auto_rows),
            "review_not_action_supported": len(unsupported_review_rows),
            "reject_not_action_supported": len(unsupported_reject_rows),
            "withheld_action_supported": len(withheld_action_rows),
        },
        "metrics": {
            "top1_plan_match_rate": metric(len(plan_rows), total),
            "top1_action_support_rate": metric(len(action_rows), total),
            "auto_release_rate_on_pass_gold": metric(len(auto_rows), total),
            "review_rate_on_pass_gold": metric(len(review_rows), total),
            "reject_rate_on_pass_gold": metric(len(reject_rows), total),
            "auto_plan_precision_on_pass_gold": metric(len(auto_plan_rows), len(auto_rows)),
            "auto_action_precision_on_pass_gold": metric(len(auto_action_rows), len(auto_rows)),
            "verified_supported_auto_rate_on_pass_gold": metric(len(auto_action_rows), total),
            "verified_supported_review_rate_on_pass_gold": metric(len(review_action_rows), total),
            "verified_supported_reject_rate_on_pass_gold": metric(len(reject_action_rows), total),
            "withheld_supported_action_rate_on_pass_gold": metric(len(withheld_action_rows), total),
            "auto_not_action_supported_rate_on_pass_gold": metric(len(unsupported_auto_rows), total),
            "review_not_action_supported_rate_on_pass_gold": metric(len(unsupported_review_rows), total),
            "reject_not_action_supported_rate_on_pass_gold": metric(len(unsupported_reject_rows), total),
        },
    }


def action_set_overlap(recommended: list[dict[str, Any]], observed_failed: list[dict[str, Any]]) -> dict[str, Any]:
    if not recommended or not observed_failed:
        return {
            "has_failed_action_overlap": False,
            "has_failed_direction_overlap": False,
            "has_failed_value_overlap": False,
            "matched_pair_count": 0,
            "direction_match_count": 0,
            "value_match_count": 0,
            "score": score_action_sets(recommended, observed_failed),
        }
    scored = score_action_sets(recommended, observed_failed)
    pairs = scored.get("matched_pairs") if isinstance(scored.get("matched_pairs"), list) else []
    direction_matches = [pair for pair in pairs if pair.get("direction_match")]
    value_matches = [pair for pair in pairs if pair.get("value_match")]
    return {
        "has_failed_action_overlap": bool(pairs),
        "has_failed_direction_overlap": bool(direction_matches),
        "has_failed_value_overlap": bool(value_matches),
        "matched_pair_count": len(pairs),
        "direction_match_count": len(direction_matches),
        "value_match_count": len(value_matches),
        "score": scored,
    }


def summarize_known_failure_overlap(method_id: str, rows: list[dict[str, Any]]) -> dict[str, Any]:
    fail_rows = [
        row for row in rows
        if row.get("ticket_outcome") == "long_eval_fail" and row.get("failed_actions")
    ]
    total = len(fail_rows)
    auto_total = 0
    review_total = 0
    reject_total = 0
    non_auto_total = 0
    action_overlap = 0
    direction_overlap = 0
    value_overlap = 0
    auto_direction_overlap = 0
    review_direction_overlap = 0
    reject_direction_overlap = 0
    non_auto_direction_overlap = 0
    auto_value_overlap = 0
    review_value_overlap = 0
    reject_value_overlap = 0
    non_auto_value_overlap = 0
    direction_only_overlap = 0
    auto_direction_only_overlap = 0
    review_direction_only_overlap = 0
    reject_direction_only_overlap = 0
    non_auto_direction_only_overlap = 0
    auto_without_direction_overlap = 0
    review_without_direction_overlap = 0
    reject_without_direction_overlap = 0
    auto_action_overlap = 0
    rows_with_recommendation = 0
    similarity_abstention_total = 0
    similarity_abstention_direction_overlap = 0
    counter_evidence_direction_overlap = 0
    similarity_abstention_value_overlap = 0
    counter_evidence_value_overlap = 0

    for row in fail_rows:
        auto = is_auto(row)
        bucket = decision_bucket(row)
        similarity_abstain = is_similarity_abstention(row)
        auto_total += int(auto)
        review_total += int(bucket == "review")
        reject_total += int(bucket == "reject")
        similarity_abstention_total += int(similarity_abstain)
        non_auto_total += int(not auto)
        rec_actions = row.get("recommended_actions") if isinstance(row.get("recommended_actions"), list) else []
        if rec_actions:
            rows_with_recommendation += 1
        overlap = action_set_overlap(rec_actions, row.get("failed_actions") or [])
        has_action = bool(overlap["has_failed_action_overlap"])
        has_direction = bool(overlap["has_failed_direction_overlap"])
        has_value = bool(overlap["has_failed_value_overlap"])
        has_direction_only = has_direction and not has_value
        action_overlap += int(has_action)
        direction_overlap += int(has_direction)
        value_overlap += int(has_value)
        direction_only_overlap += int(has_direction_only)
        auto_action_overlap += int(auto and has_action)
        auto_direction_overlap += int(auto and has_direction)
        review_direction_overlap += int(bucket == "review" and has_direction)
        reject_direction_overlap += int(bucket == "reject" and has_direction)
        non_auto_direction_overlap += int((not auto) and has_direction)
        similarity_abstention_direction_overlap += int(similarity_abstain and has_direction)
        counter_evidence_direction_overlap += int((not auto) and (not similarity_abstain) and has_direction)
        auto_value_overlap += int(auto and has_value)
        review_value_overlap += int(bucket == "review" and has_value)
        reject_value_overlap += int(bucket == "reject" and has_value)
        non_auto_value_overlap += int((not auto) and has_value)
        similarity_abstention_value_overlap += int(similarity_abstain and has_value)
        counter_evidence_value_overlap += int((not auto) and (not similarity_abstain) and has_value)
        auto_direction_only_overlap += int(auto and has_direction_only)
        review_direction_only_overlap += int(bucket == "review" and has_direction_only)
        reject_direction_only_overlap += int(bucket == "reject" and has_direction_only)
        non_auto_direction_only_overlap += int((not auto) and has_direction_only)
        auto_without_direction_overlap += int(auto and not has_direction)
        review_without_direction_overlap += int(bucket == "review" and not has_direction)
        reject_without_direction_overlap += int(bucket == "reject" and not has_direction)

    return {
        "method_id": method_id,
        "method_label": METHOD_LABELS.get(method_id, method_id),
        "sample_scope": "long_eval_fail",
        "counts": {
            "fail_ticket_count": total,
            "rows_with_recommendation": rows_with_recommendation,
            "auto_count": auto_total,
            "review_count": review_total,
            "reject_count": reject_total,
            "review_or_reject_count": non_auto_total,
            "failed_action_overlap_count": action_overlap,
            "failed_direction_overlap_count": direction_overlap,
            "failed_value_overlap_count": value_overlap,
            "failed_direction_only_overlap_count": direction_only_overlap,
            "auto_failed_action_overlap_count": auto_action_overlap,
            "legacy_direction_failed_action_auto_escape_count": auto_direction_overlap,
            "legacy_direction_failed_action_caught_count": non_auto_direction_overlap,
            "known_failed_action_auto_escape_count": auto_value_overlap,
            "known_failed_action_review_caught_count": review_value_overlap,
            "known_failed_action_reject_caught_count": reject_value_overlap,
            "known_failed_action_similarity_abstention_caught_count": similarity_abstention_value_overlap,
            "known_failed_action_counter_evidence_caught_count": counter_evidence_value_overlap,
            "known_failed_action_caught_count": non_auto_value_overlap,
            "direction_risk_unknown_auto_count": auto_direction_only_overlap,
            "direction_risk_unknown_review_count": review_direction_only_overlap,
            "direction_risk_unknown_reject_count": reject_direction_only_overlap,
            "direction_risk_unknown_caught_count": non_auto_direction_only_overlap,
            "counterfactual_unknown_auto_count": auto_without_direction_overlap,
            "counterfactual_unknown_review_count": review_without_direction_overlap,
            "counterfactual_unknown_reject_count": reject_without_direction_overlap,
            "similarity_abstention_count": similarity_abstention_total,
        },
        "metrics": {
            "auto_release_rate_on_failed_ticket": metric(auto_total, total),
            "review_rate_on_failed_ticket": metric(review_total, total),
            "reject_rate_on_failed_ticket": metric(reject_total, total),
            "similarity_abstention_rate_on_failed_ticket": metric(similarity_abstention_total, total),
            "failed_action_overlap_rate": metric(action_overlap, total),
            "failed_direction_overlap_rate": metric(direction_overlap, total),
            "failed_value_overlap_rate": metric(value_overlap, total),
            "failed_direction_only_overlap_rate": metric(direction_only_overlap, total),
            "legacy_direction_failed_action_auto_escape_rate": metric(auto_direction_overlap, total),
            "legacy_direction_failed_action_catch_rate_given_overlap": metric(non_auto_direction_overlap, direction_overlap),
            "known_failed_action_auto_escape_rate": metric(auto_value_overlap, total),
            "known_failed_action_review_catch_rate": metric(review_value_overlap, value_overlap),
            "known_failed_action_reject_catch_rate": metric(reject_value_overlap, value_overlap),
            "known_failed_action_similarity_abstention_catch_rate": metric(similarity_abstention_value_overlap, value_overlap),
            "known_failed_action_counter_evidence_catch_rate": metric(counter_evidence_value_overlap, value_overlap),
            "known_failed_action_catch_rate_given_overlap": metric(non_auto_value_overlap, value_overlap),
            "direction_risk_unknown_auto_rate_on_failed_ticket": metric(auto_direction_only_overlap, total),
            "direction_risk_unknown_review_rate_on_failed_ticket": metric(review_direction_only_overlap, total),
            "direction_risk_unknown_reject_rate_on_failed_ticket": metric(reject_direction_only_overlap, total),
            "direction_risk_unknown_withheld_rate_given_overlap": metric(non_auto_direction_only_overlap, direction_only_overlap),
            "counterfactual_unknown_auto_rate_on_failed_ticket": metric(auto_without_direction_overlap, total),
            "counterfactual_unknown_review_rate_on_failed_ticket": metric(review_without_direction_overlap, total),
            "counterfactual_unknown_reject_rate_on_failed_ticket": metric(reject_without_direction_overlap, total),
            "counterfactual_unknown_share_of_failed_auto": metric(auto_without_direction_overlap, auto_total),
        },
    }


def issue_veto_candidates(trace: dict[str, Any], artifacts: dict[str, Any]) -> list[dict[str, Any]]:
    query = trace_query(trace)
    navigation_map = artifacts.get("navigation_map") if isinstance(artifacts.get("navigation_map"), dict) else {}
    issue = next(
        (
            item for item in navigation_map.get("issues") or []
            if str(item.get("issue_type") or "") == str(query.get("issue_type") or "")
        ),
        None,
    )
    memories_by_id = artifacts.get("memories_by_id") if isinstance(artifacts.get("memories_by_id"), dict) else {}
    return [
        memories_by_id.get(node.get("memory_id") or node.get("id"), node)
        for node in ((issue or {}).get("vetoes") or [])
    ]


def summarize_oracle_failed_action_veto(
    traces_by_id: dict[str, dict[str, Any]],
    *,
    artifacts: dict[str, Any],
    gate_config: dict[str, Any],
) -> dict[str, Any]:
    decision_counts: Counter[str] = Counter()
    threshold_bands: Counter[str] = Counter()
    gate_reasons: Counter[str] = Counter()
    specificity_tiers: Counter[str] = Counter()
    action_count = 0
    trace_ids: set[str] = set()
    veto_hit = 0
    strong_action_veto = 0
    action_specific_hit = 0
    blocked = 0
    rejected = 0
    total_top_score = 0.0
    total_action_specific_score = 0.0
    no_issue_veto_candidates = 0

    for trace_id, info in traces_by_id.items():
        trace = info.get("trace") if isinstance(info.get("trace"), dict) else {}
        if info.get("ticket_outcome") != "long_eval_fail":
            continue
        failed_actions = info.get("failed_actions") if isinstance(info.get("failed_actions"), list) else []
        if not failed_actions:
            continue
        trace_ids.add(trace_id)
        candidates = issue_veto_candidates(trace, artifacts)
        if not candidates:
            no_issue_veto_candidates += len(failed_actions)
        query = trace_query(trace)
        for action in failed_actions:
            action_count += 1
            decision = apply_veto_gate(
                recommended=action,
                veto_candidates=candidates,
                family={"scheme_group": action.get("scheme_group")},
                base_risk_level="low",
                base_needs_review=False,
                recommendation_confidence=1.0,
                gate_config=gate_config,
                query={**query, "veto_issue_routed": bool(candidates)},
            )
            gate = str(decision.get("gate_decision") or "")
            decision_counts[gate] += 1
            threshold_bands[str(decision.get("threshold_band") or "")] += 1
            gate_reasons[str(decision.get("gate_reason") or "")] += 1
            veto_hit += int(bool(decision.get("veto_hit")))
            strong_action_veto += int(bool(decision.get("strong_action_veto_match")))
            blocked += int(gate in NON_AUTO_GATES)
            rejected += int(gate == "reject")
            matches = decision.get("failcohort_matches") if isinstance(decision.get("failcohort_matches"), list) else []
            if matches:
                top = matches[0] if isinstance(matches[0], dict) else {}
                specificity_tiers[str(top.get("specificity_tier") or "")] += 1
                total_top_score += float(top.get("score") or 0.0)
                action_specific_score = max(
                    float(item.get("action_specific_score") or 0.0)
                    for item in matches
                    if isinstance(item, dict)
                )
                total_action_specific_score += action_specific_score
                action_specific_hit += int(action_specific_score >= float(gate_config.get("tau_low", 0.55)))

    return {
        "scope": "oracle_failed_action_veto_detection",
        "sample_policy": (
            "Each observed long_eval_fail executed action is directly supplied as the candidate action "
            "to the same frozen fail-cohort gate. This tests veto detection, not recommendation quality."
        ),
        "counts": {
            "failed_action_count": action_count,
            "failed_ticket_count": len(trace_ids),
            "blocked_review_or_reject_count": blocked,
            "reject_count": rejected,
            "veto_hit_count": veto_hit,
            "strong_action_veto_match_count": strong_action_veto,
            "action_specific_hit_count": action_specific_hit,
            "no_issue_veto_candidate_action_count": no_issue_veto_candidates,
            "gate_decision_counts": dict(sorted(decision_counts.items())),
            "threshold_band_counts": dict(sorted(threshold_bands.items())),
            "top_specificity_tier_counts": dict(sorted(specificity_tiers.items())),
            "top_gate_reason_counts": dict(gate_reasons.most_common(12)),
        },
        "metrics": {
            "failed_action_block_rate": metric(blocked, action_count),
            "failed_action_reject_rate": metric(rejected, action_count),
            "veto_hit_rate": metric(veto_hit, action_count),
            "strong_action_veto_match_rate": metric(strong_action_veto, action_count),
            "action_specific_hit_rate": metric(action_specific_hit, action_count),
            "mean_top_veto_score": rate(total_top_score, action_count),
            "mean_action_specific_score": rate(total_action_specific_score, action_count),
            "no_issue_veto_candidate_rate": metric(no_issue_veto_candidates, action_count),
        },
    }


def summarize_method_failed_action_oracle_rows(
    method_ids: list[str],
    rows_by_method: dict[str, list[dict[str, Any]]],
    oracle: dict[str, Any],
    traces_by_id: dict[str, dict[str, Any]],
) -> list[dict[str, Any]]:
    """Build Table 2b rows, including method-specific abstention/manual fallback."""
    oracle_counts = oracle.get("counts") if isinstance(oracle.get("counts"), dict) else {}
    oracle_metrics = oracle.get("metrics") if isinstance(oracle.get("metrics"), dict) else {}
    failed_action_count = int(oracle_counts.get("failed_action_count") or 0)
    failed_ticket_count = int(oracle_counts.get("failed_ticket_count") or 0)
    blocked_count = int(oracle_counts.get("blocked_review_or_reject_count") or 0)
    reject_count = int(oracle_counts.get("reject_count") or 0)
    echo_method_ids = {GATE_ONLY_METHOD, PRIMARY_METHOD, MAIN_ECHO_METHOD, VALUE_REBASE_METHOD}
    supervised_cases = None
    supervised_config = None
    if "supervised_ltr_selective_ranker_no_echo" in method_ids:
        supervised_cases = load_traditional_case_memories()
        supervised_config = read_json(
            PROJECT_ROOT / "experiments/config/ranker.supervised-ltr-selective-no-echo.json"
        )
    out: list[dict[str, Any]] = []
    for method_id in method_ids:
        if method_id in echo_method_ids:
            auto_escape = max(failed_action_count - blocked_count, 0)
            out.append({
                "method_id": method_id,
                "method_label": PAPER_TABLE2_METHOD_LABELS.get(method_id) or METHOD_LABELS.get(method_id, method_id),
                "failed_ticket_count": failed_ticket_count,
                "given_failed_action_count": failed_action_count,
                "auto_escape_count": auto_escape,
                "catch_count": blocked_count,
                "review_catch_count": max(blocked_count - reject_count, 0),
                "reject_catch_count": reject_count,
                "catch_rate": oracle_metrics.get("failed_action_block_rate") or metric(blocked_count, failed_action_count),
                "auto_escape_rate": metric(auto_escape, failed_action_count),
                "review_catch_rate": metric(max(blocked_count - reject_count, 0), failed_action_count),
                "reject_catch_rate": metric(reject_count, failed_action_count),
                "veto_hit_rate": oracle_metrics.get("veto_hit_rate"),
                "action_specific_hit_rate": oracle_metrics.get("action_specific_hit_rate"),
                "oracle_policy": "echo_mem_frozen_failcohort_gate_on_given_failed_action",
            })
            continue

        if method_id == "supervised_ltr_selective_ranker_no_echo":
            raise ValueError("non-ECHO supervised comparator is a frozen reference only")

        rows = rows_by_method.get(method_id) or []
        total_actions = 0
        review_actions = 0
        reject_actions = 0
        abstained_tickets = 0
        for row in rows:
            if row.get("ticket_outcome") != "long_eval_fail":
                continue
            failed_actions = row.get("failed_actions") if isinstance(row.get("failed_actions"), list) else []
            action_count = len(failed_actions)
            total_actions += action_count
            bucket = decision_bucket(row)
            if bucket == "review":
                review_actions += action_count
                abstained_tickets += 1
            elif bucket == "reject":
                reject_actions += action_count
                abstained_tickets += 1
        total_actions = total_actions or failed_action_count
        catch_count = review_actions + reject_actions
        auto_escape = max(total_actions - catch_count, 0)
        out.append({
            "method_id": method_id,
            "method_label": METHOD_LABELS.get(method_id, method_id),
            "failed_ticket_count": failed_ticket_count,
            "given_failed_action_count": total_actions,
            "auto_escape_count": auto_escape,
            "catch_count": catch_count,
            "review_catch_count": review_actions,
            "reject_catch_count": reject_actions,
            "abstained_failed_ticket_count": abstained_tickets,
            "catch_rate": metric(catch_count, total_actions),
            "auto_escape_rate": metric(auto_escape, total_actions),
            "review_catch_rate": metric(review_actions, total_actions),
            "reject_catch_rate": metric(reject_actions, total_actions),
            "veto_hit_rate": None,
            "action_specific_hit_rate": None,
            "oracle_policy": "method_abstention_or_manual_fallback_on_failed_ticket",
        })
    return out


def summarize_partially_observed_e2e(method_id: str, rows: list[dict[str, Any]]) -> dict[str, Any]:
    pass_rows = [row for row in rows if row.get("ticket_outcome") == "long_eval_pass"]
    fail_rows = [
        row for row in rows
        if row.get("ticket_outcome") == "long_eval_fail" and row.get("failed_actions")
    ]

    pass_auto = 0
    pass_verified_supported_auto = 0
    pass_auto_not_action_supported = 0
    pass_non_auto = 0
    pass_supported_non_auto = 0
    pass_verified_supported_review = 0
    pass_verified_supported_reject = 0
    pass_not_action_supported_review = 0
    pass_not_action_supported_reject = 0
    for row in pass_rows:
        auto = is_auto(row)
        bucket = decision_bucket(row)
        supported = action_supported(row)
        pass_auto += int(auto)
        pass_verified_supported_auto += int(auto and supported)
        pass_auto_not_action_supported += int(auto and not supported)
        pass_non_auto += int(not auto)
        pass_supported_non_auto += int((not auto) and supported)
        pass_verified_supported_review += int(bucket == "review" and supported)
        pass_verified_supported_reject += int(bucket == "reject" and supported)
        pass_not_action_supported_review += int(bucket == "review" and not supported)
        pass_not_action_supported_reject += int(bucket == "reject" and not supported)

    fail_auto = 0
    fail_non_auto = 0
    fail_review = 0
    fail_reject = 0
    fail_known_escape = 0
    fail_known_caught = 0
    fail_counterfactual_unknown_auto = 0
    fail_counterfactual_unknown_non_auto = 0
    fail_known_review_caught = 0
    fail_known_reject_caught = 0
    fail_counterfactual_unknown_review = 0
    fail_counterfactual_unknown_reject = 0
    fail_direction_overlap = 0
    fail_value_overlap = 0
    fail_direction_only_overlap = 0
    fail_direction_risk_unknown_auto = 0
    fail_direction_risk_unknown_non_auto = 0
    fail_direction_risk_unknown_review = 0
    fail_direction_risk_unknown_reject = 0
    for row in fail_rows:
        auto = is_auto(row)
        bucket = decision_bucket(row)
        fail_auto += int(auto)
        fail_non_auto += int(not auto)
        fail_review += int(bucket == "review")
        fail_reject += int(bucket == "reject")
        overlap = action_set_overlap(row.get("recommended_actions") or [], row.get("failed_actions") or [])
        direction_overlap = bool(overlap["has_failed_direction_overlap"])
        known_overlap = bool(overlap["has_failed_value_overlap"])
        direction_only = direction_overlap and not known_overlap
        fail_direction_overlap += int(direction_overlap)
        fail_value_overlap += int(known_overlap)
        fail_direction_only_overlap += int(direction_only)
        fail_known_escape += int(auto and known_overlap)
        fail_known_caught += int((not auto) and known_overlap)
        fail_direction_risk_unknown_auto += int(auto and direction_only)
        fail_direction_risk_unknown_non_auto += int((not auto) and direction_only)
        fail_counterfactual_unknown_auto += int(auto and not direction_overlap)
        fail_counterfactual_unknown_non_auto += int((not auto) and not direction_overlap)
        fail_known_review_caught += int(bucket == "review" and known_overlap)
        fail_known_reject_caught += int(bucket == "reject" and known_overlap)
        fail_direction_risk_unknown_review += int(bucket == "review" and direction_only)
        fail_direction_risk_unknown_reject += int(bucket == "reject" and direction_only)
        fail_counterfactual_unknown_review += int(bucket == "review" and not direction_overlap)
        fail_counterfactual_unknown_reject += int(bucket == "reject" and not direction_overlap)

    total_observed = len(pass_rows) + len(fail_rows)
    flow_counts = {
        "long_eval_pass": {
            "verified_supported": {
                "auto": pass_verified_supported_auto,
                "review": pass_verified_supported_review,
                "reject": pass_verified_supported_reject,
                "total": pass_verified_supported_auto + pass_verified_supported_review + pass_verified_supported_reject,
            },
            "not_verified_supported": {
                "auto": pass_auto_not_action_supported,
                "review": pass_not_action_supported_review,
                "reject": pass_not_action_supported_reject,
                "total": pass_auto_not_action_supported + pass_not_action_supported_review + pass_not_action_supported_reject,
            },
        },
        "long_eval_fail": {
            "known_failure_overlap": {
                "auto": fail_known_escape,
                "review": fail_known_review_caught,
                "reject": fail_known_reject_caught,
                "total": fail_value_overlap,
            },
            "exact_known_failure_repeat": {
                "auto": fail_known_escape,
                "review": fail_known_review_caught,
                "reject": fail_known_reject_caught,
                "total": fail_value_overlap,
            },
            "direction_risk_unknown": {
                "auto": fail_direction_risk_unknown_auto,
                "review": fail_direction_risk_unknown_review,
                "reject": fail_direction_risk_unknown_reject,
                "total": fail_direction_only_overlap,
            },
            "counterfactual_unknown": {
                "auto": fail_counterfactual_unknown_auto,
                "review": fail_counterfactual_unknown_review,
                "reject": fail_counterfactual_unknown_reject,
                "total": fail_counterfactual_unknown_auto
                + fail_counterfactual_unknown_review
                + fail_counterfactual_unknown_reject,
            },
        },
    }
    return {
        "method_id": method_id,
        "method_label": METHOD_LABELS.get(method_id, method_id),
        "sample_scope": "long_eval_pass plus long_eval_fail, interpreted as observed action outcomes",
        "counts": {
            "observed_ticket_count": total_observed,
            "pass_ticket_count": len(pass_rows),
            "fail_ticket_count": len(fail_rows),
            "pass_auto": pass_auto,
            "pass_verified_supported_auto": pass_verified_supported_auto,
            "pass_auto_not_action_supported": pass_auto_not_action_supported,
            "pass_review_or_reject": pass_non_auto,
            "pass_review": pass_verified_supported_review + pass_not_action_supported_review,
            "pass_reject": pass_verified_supported_reject + pass_not_action_supported_reject,
            "pass_supported_review_or_reject": pass_supported_non_auto,
            "pass_verified_supported_review": pass_verified_supported_review,
            "pass_verified_supported_reject": pass_verified_supported_reject,
            "pass_not_action_supported_review": pass_not_action_supported_review,
            "pass_not_action_supported_reject": pass_not_action_supported_reject,
            "fail_auto": fail_auto,
            "fail_review_or_reject": fail_non_auto,
            "fail_review": fail_review,
            "fail_reject": fail_reject,
            "fail_direction_overlap": fail_direction_overlap,
            "fail_known_failed_action_overlap": fail_value_overlap,
            "fail_known_failed_action_auto_escape": fail_known_escape,
            "fail_known_failed_action_caught": fail_known_caught,
            "fail_known_failed_action_review_caught": fail_known_review_caught,
            "fail_known_failed_action_reject_caught": fail_known_reject_caught,
            "fail_direction_risk_unknown_overlap": fail_direction_only_overlap,
            "fail_direction_risk_unknown_auto": fail_direction_risk_unknown_auto,
            "fail_direction_risk_unknown_review_or_reject": fail_direction_risk_unknown_non_auto,
            "fail_direction_risk_unknown_review": fail_direction_risk_unknown_review,
            "fail_direction_risk_unknown_reject": fail_direction_risk_unknown_reject,
            "fail_counterfactual_unknown_auto": fail_counterfactual_unknown_auto,
            "fail_counterfactual_unknown_review_or_reject": fail_counterfactual_unknown_non_auto,
            "fail_counterfactual_unknown_review": fail_counterfactual_unknown_review,
            "fail_counterfactual_unknown_reject": fail_counterfactual_unknown_reject,
        },
        "flow_counts": flow_counts,
        "metrics": {
            "verified_supported_auto_rate_on_all_observed": metric(pass_verified_supported_auto, total_observed),
            "verified_supported_auto_rate_on_pass_gold": metric(pass_verified_supported_auto, len(pass_rows)),
            "pass_auto_action_precision": metric(pass_verified_supported_auto, pass_auto),
            "pass_supported_review_or_reject_rate": metric(pass_supported_non_auto, len(pass_rows)),
            "known_failure_auto_escape_rate_on_fail": metric(fail_known_escape, len(fail_rows)),
            "known_failure_catch_rate_given_overlap": metric(fail_known_caught, fail_value_overlap),
            "direction_risk_unknown_auto_rate_on_fail": metric(fail_direction_risk_unknown_auto, len(fail_rows)),
            "direction_risk_unknown_withheld_rate_given_overlap": metric(fail_direction_risk_unknown_non_auto, fail_direction_only_overlap),
            "counterfactual_unknown_auto_rate_on_fail": metric(fail_counterfactual_unknown_auto, len(fail_rows)),
            "counterfactual_unknown_share_of_fail_auto": metric(fail_counterfactual_unknown_auto, fail_auto),
        },
    }


def delta_metrics(method: dict[str, Any], baseline: dict[str, Any]) -> dict[str, float | None]:
    out: dict[str, float | None] = {}
    for key, value in (method.get("metrics") or {}).items():
        if not isinstance(value, dict):
            continue
        left = value.get("value")
        right = ((baseline.get("metrics") or {}).get(key) or {}).get("value")
        out[key] = round(float(left) - float(right), 6) if isinstance(left, (int, float)) and isinstance(right, (int, float)) else None
    return out


def parse_method_ids(raw: str) -> list[str] | None:
    if not raw:
        return None
    if raw.strip().lower() in {"all", "*"}:
        return ["*"]
    return [item.strip() for item in raw.split(",") if item.strip()]


def build_payload(run_dir: Path | list[Path], *, requested_method_ids: list[str] | None = None) -> dict[str, Any]:
    run_dirs = run_dir if isinstance(run_dir, list) else [run_dir]
    rows_by_method, meta, traces_by_id = load_run_samples_many(run_dirs)
    run_dir = run_dirs[0]
    spec = read_json(run_dir / "spec.json")
    dataset_role = str(meta.get("dataset_role") or spec.get("dataset_role") or "dev")
    if requested_method_ids == ["*"]:
        default_order = [method for method in METHOD_ORDER if method in rows_by_method]
        rest = sorted(method for method in rows_by_method if method not in default_order)
        method_ids = default_order + rest
    elif requested_method_ids:
        method_ids = [method for method in requested_method_ids if method in rows_by_method]
        missing = [method for method in requested_method_ids if method not in rows_by_method]
        if missing:
            raise ValueError(f"requested method(s) not found in run samples: {missing}")
    else:
        method_ids = [method for method in METHOD_ORDER if method in rows_by_method]
    if not method_ids:
        method_ids = sorted(rows_by_method)

    positive = [summarize_positive_plan_selection(method, rows_by_method[method]) for method in method_ids]
    known_failure = [summarize_known_failure_overlap(method, rows_by_method[method]) for method in method_ids]
    partially_observed = [summarize_partially_observed_e2e(method, rows_by_method[method]) for method in method_ids]

    positive_by_id = {row["method_id"]: row for row in positive}
    partially_by_id = {row["method_id"]: row for row in partially_observed}
    positive_deltas = []
    partially_deltas = []
    if PAPER_TABLE2_BASELINE_METHOD in positive_by_id:
        positive_deltas = [
            {
                "baseline_method_id": PAPER_TABLE2_BASELINE_METHOD,
                "method_id": row["method_id"],
                "deltas": delta_metrics(row, positive_by_id[PAPER_TABLE2_BASELINE_METHOD]),
            }
            for row in positive
            if row["method_id"] != PAPER_TABLE2_BASELINE_METHOD
        ]
    if PAPER_TABLE2_BASELINE_METHOD in partially_by_id:
        partially_deltas = [
            {
                "baseline_method_id": PAPER_TABLE2_BASELINE_METHOD,
                "method_id": row["method_id"],
                "deltas": delta_metrics(row, partially_by_id[PAPER_TABLE2_BASELINE_METHOD]),
            }
            for row in partially_observed
            if row["method_id"] != PAPER_TABLE2_BASELINE_METHOD
        ]

    package_ref = ((spec.get("artifacts") or {}).get("memory_package") or {})
    gate_ref = ((spec.get("configs") or {}).get("gate") or {})
    package_path = resolve_project_path(package_ref.get("path"))
    gate_path = resolve_project_path(gate_ref.get("path"))
    if package_path is None or not package_path.exists():
        raise FileNotFoundError(f"memory package not found in run spec: {package_ref}")
    if gate_path is None or not gate_path.exists():
        raise FileNotFoundError(f"gate config not found in run spec: {gate_ref}")
    artifacts = load_shadow_artifacts(package_path)
    gate_config = read_json(gate_path)
    oracle = summarize_oracle_failed_action_veto(
        traces_by_id,
        artifacts=artifacts,
        gate_config=gate_config,
    )
    oracle_rows = summarize_method_failed_action_oracle_rows(method_ids, rows_by_method, oracle, traces_by_id)

    purpose = (
        "Approved frozen holdout export: evaluate successful observed actions as positive recommendation gold, "
        "evaluate failed observed actions as counter-evidence/veto evidence, and treat different recommendations "
        "on failed tickets as counterfactual unknown rather than automatic errors. This export must not be used "
        "for post-holdout tuning."
        if dataset_role == "holdout"
        else
        "Dev-only protocol correction: evaluate successful observed actions as positive recommendation gold, "
        "evaluate failed observed actions as counter-evidence/veto evidence, and treat different recommendations "
        "on failed tickets as counterfactual unknown rather than automatic errors."
    )
    run_policy = (
        "Approved frozen holdout RunArtifact export. No post-holdout threshold, selector, gate, ranker, or method tuning is allowed."
        if dataset_role == "holdout"
        else
        "Existing dev RunArtifact export; no holdout. Thresholds must be selected on dev before any holdout request."
    )

    gate_only_integrity_path = RESULTS / "table2_gate_only_paired_integrity_audit_20260710.json"
    integrity_audits = {}
    if gate_only_integrity_path.exists():
        integrity_audits["gate_only_same_candidate_contract"] = {
            **ref(gate_only_integrity_path),
            "integrity_passed": False,
            "resolution": "renamed_to_echo_candidate_adapter_gate_runtime_variant",
        }
    main_integrity_path = RESULTS / "table2_main_integrity_audit_20260710.json"
    if main_integrity_path.exists():
        main_integrity = read_json(main_integrity_path)
        integrity_audits["main_table2_matcher_scope_and_r14_provenance"] = {
            **ref(main_integrity_path),
            "integrity_summary": main_integrity.get("integrity_summary"),
            "resolution": "split_full_vs_same_subset_and_rename_r14_primary_consumer",
        }

    return {
        "schema_version": "observed_action_outcome_protocol.v1",
        "generated_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "purpose": purpose,
        "run_policy": run_policy,
        "denominator_policy": {
            "observed_action_label": "(ticket context, historical executed action) -> long_eval outcome",
            "positive_plan_selection": "Use long_eval_pass tickets/actions as successful gold for recommendation-quality metrics.",
            "counter_evidence_veto": "Use long_eval_fail executed actions as observed failed action evidence for veto detection.",
            "partially_observed_e2e": (
                "Only two end-to-end events are directly verifiable: auto recommendation matching pass gold, "
                "and auto recommendation overlapping the observed failed action. Other failed-ticket autos are counterfactual unknown."
            ),
            "downgraded_prior_metrics": [
                "bad_auto_escape",
                "negative_catch_rate",
                "fail-ticket-as-negative confusion matrix",
            ],
        },
        "method_ids": method_ids,
        "table_2_method_roster": normalize_table2_method_roster_for_dataset(
            table2_method_roster(method_ids),
            dataset_role,
        ),
        "table_1_positive_plan_selection": {
            "rows": positive,
            "paired_deltas_vs_pure_case_retrieval": positive_deltas,
        },
        "table_2_failed_action_veto_detection": {
            "oracle_failed_action_veto": oracle,
            "oracle_failed_action_veto_rows": oracle_rows,
            "end_to_end_known_failure_overlap_rows": known_failure,
        },
        "table_3_partially_observed_end_to_end": {
            "rows": partially_observed,
            "paired_deltas_vs_pure_case_retrieval": partially_deltas,
        },
        "memory_package": {
            **package_ref,
            "path": rel(package_path),
            "sha256": path_sha256(package_path),
        },
        "gate_config": {
            **gate_ref,
            "path": rel(gate_path),
            "sha256": path_sha256(gate_path),
        },
        "integrity_audits": integrity_audits,
        **meta,
    }


def flatten_metric_rows(payload: dict[str, Any]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []

    def add_metrics(table: str, method_id: str, method_label: str, counts: dict[str, Any], metrics: dict[str, Any]) -> None:
        for key, value in counts.items():
            if isinstance(value, (int, float)):
                rows.append({
                    "table": table,
                    "method_id": method_id,
                    "method_label": method_label,
                    "metric": key,
                    "value": value,
                    "numerator": "",
                    "denominator": "",
                })
        for key, entry in metrics.items():
            if isinstance(entry, dict) and {"value", "numerator", "denominator"} <= set(entry):
                rows.append({
                    "table": table,
                    "method_id": method_id,
                    "method_label": method_label,
                    "metric": key,
                    "value": entry.get("value"),
                    "numerator": entry.get("numerator"),
                    "denominator": entry.get("denominator"),
                })
            else:
                rows.append({
                    "table": table,
                    "method_id": method_id,
                    "method_label": method_label,
                    "metric": key,
                    "value": entry,
                    "numerator": "",
                    "denominator": "",
                })

    for row in payload["table_1_positive_plan_selection"]["rows"]:
        add_metrics(
            "positive_plan_selection",
            row["method_id"],
            row["method_label"],
            row.get("counts") or {},
            row.get("metrics") or {},
        )
    oracle = payload["table_2_failed_action_veto_detection"]["oracle_failed_action_veto"]
    add_metrics(
        "oracle_failed_action_veto",
        "oracle_failed_action_as_candidate",
        "Oracle: observed failed action supplied to ECHO gate",
        oracle.get("counts") or {},
        oracle.get("metrics") or {},
    )
    for row in payload["table_2_failed_action_veto_detection"]["end_to_end_known_failure_overlap_rows"]:
        add_metrics(
            "end_to_end_known_failure_overlap",
            row["method_id"],
            row["method_label"],
            row.get("counts") or {},
            row.get("metrics") or {},
        )
    for row in payload["table_3_partially_observed_end_to_end"]["rows"]:
        add_metrics(
            "partially_observed_end_to_end",
            row["method_id"],
            row["method_label"],
            row.get("counts") or {},
            row.get("metrics") or {},
        )
        for group, group_payload in (row.get("flow_counts") or {}).items():
            if not isinstance(group_payload, dict):
                continue
            for cls, class_payload in group_payload.items():
                if not isinstance(class_payload, dict):
                    continue
                for bucket in ("auto", "review", "reject", "total"):
                    rows.append({
                        "table": "partially_observed_flow",
                        "method_id": row["method_id"],
                        "method_label": row["method_label"],
                        "metric": f"{group}.{cls}.{bucket}",
                        "value": class_payload.get(bucket),
                        "numerator": "",
                        "denominator": "",
                    })
    return rows


def write_csv(path: Path, payload: dict[str, Any]) -> None:
    fields = ["table", "method_id", "method_label", "metric", "value", "numerator", "denominator"]
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=fields)
        writer.writeheader()
        for row in flatten_metric_rows(payload):
            writer.writerow({field: row.get(field, "") for field in fields})


def metric_value(row: dict[str, Any], metric_name: str) -> float | None:
    entry = ((row.get("metrics") or {}).get(metric_name) or {})
    value = entry.get("value") if isinstance(entry, dict) else entry
    return float(value) if isinstance(value, (int, float)) else None


def metric_fraction(row: dict[str, Any], metric_name: str) -> str:
    entry = ((row.get("metrics") or {}).get(metric_name) or {})
    if isinstance(entry, dict):
        value = entry.get("value")
        num = entry.get("numerator")
        den = entry.get("denominator")
        if isinstance(value, (int, float)) and isinstance(num, (int, float)) and isinstance(den, (int, float)):
            return f"{pct(float(value))} ({int(num)}/{int(den)})"
    return pct(metric_value(row, metric_name))


def write_doc(path: Path, payload: dict[str, Any], out_json: Path, out_csv: Path) -> None:
    positive_rows = payload["table_1_positive_plan_selection"]["rows"]
    known_rows = payload["table_2_failed_action_veto_detection"]["end_to_end_known_failure_overlap_rows"]
    partial_rows = payload["table_3_partially_observed_end_to_end"]["rows"]
    oracle = payload["table_2_failed_action_veto_detection"]["oracle_failed_action_veto"]
    oracle_method_rows = (
        payload["table_2_failed_action_veto_detection"].get("oracle_failed_action_veto_rows")
        if isinstance(payload["table_2_failed_action_veto_detection"].get("oracle_failed_action_veto_rows"), list)
        else []
    )
    generated_date = str(payload.get("generated_at") or "").split("T", 1)[0] or datetime.now(timezone.utc).date().isoformat()
    roster = payload.get("table_2_method_roster") if isinstance(payload.get("table_2_method_roster"), list) else []
    dataset_role = str(payload.get("dataset_role") or "dev")
    dataset_title = "Holdout" if dataset_role == "holdout" else "Dev"

    def paper_main_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
        by_method = {str(row.get("method_id") or ""): row for row in rows}
        selected = [by_method[method_id] for method_id in PAPER_TABLE2_MAIN_METHODS if method_id in by_method]
        return selected if len(selected) == len(PAPER_TABLE2_MAIN_METHODS) else rows

    def roster_rows(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
        if not roster:
            return paper_main_rows(rows)
        by_method = {str(row.get("method_id") or ""): row for row in rows}
        out: list[dict[str, Any]] = []
        for item in roster:
            method_id = str(item.get("method_id") or "")
            row = dict(by_method.get(method_id) or {})
            row.setdefault("method_id", method_id)
            row["method_label"] = item.get("method_label") or row.get("method_label") or method_id
            row["method_group"] = item.get("method_group")
            row["result_status"] = item.get("result_status")
            row["source_contract"] = item.get("source_contract")
            row["paper_method_planned"] = method_id not in by_method
            out.append(row)
        return out

    def paper_label(row: dict[str, Any]) -> str:
        method_id = str(row.get("method_id") or "")
        return str(row.get("method_label") or PAPER_TABLE2_METHOD_LABELS.get(method_id, method_id))

    positive_rows = roster_rows(positive_rows)
    known_rows = roster_rows(known_rows)
    partial_rows = roster_rows(partial_rows)
    oracle_method_rows = roster_rows(oracle_method_rows)

    def count_fraction(count: int | float, total: int | float) -> str:
        value = rate(count, total)
        return f"{pct(value)} ({int(count)}/{int(total)})" if value is not None else f"n/a ({int(count)}/{int(total)})"

    def count_value(row: dict[str, Any], key: str) -> int:
        return int(((row.get("counts") or {}).get(key) or 0))

    def status_text(row: dict[str, Any]) -> str:
        status = str(row.get("result_status") or "")
        return status.replace("_", " ") if status else "completed dev only"

    def group_text(row: dict[str, Any]) -> str:
        return str(row.get("method_group") or "-")

    def planned_cells(cell_count: int) -> str:
        return " | ".join(["-"] * cell_count)

    def positive_line(row: dict[str, Any]) -> str:
        if row.get("paper_method_planned"):
            return f"| {paper_label(row)} | {group_text(row)} | {status_text(row)} | {planned_cells(6)} |"
        total = count_value(row, "pass_ticket_count")
        action_supported = count_value(row, "top1_action_supported")
        auto_count = count_value(row, "auto_count")
        auto_action_supported = count_value(row, "auto_action_supported")
        return (
            f"| {paper_label(row)} | {group_text(row)} | {status_text(row)} | {total} | "
            f"{count_fraction(action_supported, total)} | "
            f"{count_fraction(auto_count, total)} | "
            f"{count_fraction(auto_action_supported, total)} | "
            f"{count_fraction(count_value(row, 'withheld_action_supported'), total)} | "
            f"{count_fraction(auto_action_supported, auto_count)} |"
        )

    def known_failure_line(row: dict[str, Any]) -> str:
        if row.get("paper_method_planned"):
            return f"| {paper_label(row)} | {group_text(row)} | {status_text(row)} | {planned_cells(6)} |"
        total = count_value(row, "fail_ticket_count")
        overlap = count_value(row, "failed_value_overlap_count")
        return (
            f"| {paper_label(row)} | {group_text(row)} | {status_text(row)} | {total} | "
            f"{count_fraction(count_value(row, 'known_failed_action_auto_escape_count'), total)} | "
            f"{count_fraction(count_value(row, 'known_failed_action_caught_count'), overlap)} | "
            f"{count_fraction(count_value(row, 'direction_risk_unknown_auto_count'), total)} | "
            f"{count_fraction(count_value(row, 'counterfactual_unknown_auto_count'), total)} | "
            f"{count_fraction(count_value(row, 'review_or_reject_count'), total)} |"
        )

    def oracle_line(row: dict[str, Any]) -> str:
        if row.get("paper_method_planned"):
            return f"| {paper_label(row)} | {group_text(row)} | {status_text(row)} | {planned_cells(6)} |"
        total = int(row.get("given_failed_action_count") or failed_action_count)
        failed_tickets = int(row.get("failed_ticket_count") or oracle_counts["failed_ticket_count"])
        auto = int(row.get("auto_escape_count") or 0)
        caught = int(row.get("catch_count") or 0)
        veto_metric = row.get("veto_hit_rate") if isinstance(row.get("veto_hit_rate"), dict) else None
        action_specific_metric = (
            row.get("action_specific_hit_rate")
            if isinstance(row.get("action_specific_hit_rate"), dict)
            else None
        )
        veto = pct(veto_metric.get("value")) if veto_metric else "n/a"
        action_specific = pct(action_specific_metric.get("value")) if action_specific_metric else "n/a"
        return (
            f"| {paper_label(row)} | {group_text(row)} | {status_text(row)} | "
            f"{failed_tickets} | {total} | "
            f"{count_fraction(auto, total)} | "
            f"{count_fraction(caught, total)} | "
            f"{veto} | {action_specific} |"
        )

    def partial_summary_line(row: dict[str, Any]) -> str:
        if row.get("paper_method_planned"):
            return f"| {paper_label(row)} | {group_text(row)} | {status_text(row)} | {planned_cells(11)} |"
        counts = row.get("counts") if isinstance(row.get("counts"), dict) else {}
        metrics = row.get("metrics") if isinstance(row.get("metrics"), dict) else {}
        observed = int(counts.get("observed_ticket_count") or 0)
        auto = int(counts.get("pass_auto") or 0) + int(counts.get("fail_auto") or 0)
        review = (
            int(counts.get("pass_verified_supported_review") or 0)
            + int(counts.get("pass_not_action_supported_review") or 0)
            + int(counts.get("fail_known_failed_action_review_caught") or 0)
            + int(counts.get("fail_direction_risk_unknown_review") or 0)
            + int(counts.get("fail_counterfactual_unknown_review") or 0)
        )
        reject = (
            int(counts.get("pass_verified_supported_reject") or 0)
            + int(counts.get("pass_not_action_supported_reject") or 0)
            + int(counts.get("fail_known_failed_action_reject_caught") or 0)
            + int(counts.get("fail_direction_risk_unknown_reject") or 0)
            + int(counts.get("fail_counterfactual_unknown_reject") or 0)
        )
        return (
            f"| {paper_label(row)} | {group_text(row)} | {status_text(row)} | "
            f"{count_value(row, 'pass_ticket_count')} | {count_value(row, 'fail_ticket_count')} | "
            f"{count_fraction(auto, observed)} | "
            f"{count_fraction(count_value(row, 'pass_verified_supported_auto'), count_value(row, 'pass_ticket_count'))} | "
            f"{count_fraction(count_value(row, 'pass_supported_review_or_reject'), count_value(row, 'pass_ticket_count'))} | "
            f"{count_fraction(count_value(row, 'fail_known_failed_action_auto_escape'), count_value(row, 'fail_ticket_count'))} | "
            f"{pct((metrics.get('known_failure_catch_rate_given_overlap') or {}).get('value'))} | "
            f"{count_fraction(count_value(row, 'fail_direction_risk_unknown_auto'), count_value(row, 'fail_ticket_count'))} | "
            f"{count_fraction(count_value(row, 'fail_counterfactual_unknown_auto'), count_value(row, 'fail_ticket_count'))} | "
            f"{count_fraction(review, observed)} | "
            f"{count_fraction(reject, observed)} |"
        )

    def flow_line(row: dict[str, Any], group: str, cls: str, label: str) -> str:
        if row.get("paper_method_planned"):
            return ""
        flow = (((row.get("flow_counts") or {}).get(group) or {}).get(cls) or {})
        auto = int(flow.get("auto") or 0)
        review = int(flow.get("review") or 0)
        reject = int(flow.get("reject") or 0)
        total = int(flow.get("total") or auto + review + reject)
        return f"| {paper_label(row)} | {group} | {label} | {auto} | {review} | {reject} | {total} |"

    oracle_metrics = oracle["metrics"]
    oracle_counts = oracle["counts"]
    failed_action_count = int(oracle_counts["failed_action_count"])
    blocked_count = int(oracle_counts["blocked_review_or_reject_count"])
    rejected_count = int(oracle_counts["reject_count"])
    review_count = blocked_count - rejected_count
    run_id = str((payload.get("run_artifact") or {}).get("run_id") or "")
    out_stem = out_json.stem
    uses_traditional_case_baseline = (
        "traditional_baseline" in run_id
        or "traditional_case_baseline" in out_stem
        or "traditional_baseline" in out_stem
    )
    purpose_text = (
        "This export is computed from a rerun where Pure Case Retrieval is rebuilt "
        "from raw train traces with historical actions only; it does not read long_eval outcome, "
        "ECHO-Mem memory packages, compiled case memories, profiles, counter evidence, or gates. "
