def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--run-dir",
        action="append",
        default=None,
        help="Existing RunArtifact directory. May be provided multiple times to merge method rows from the same dataset_role.",
    )
    parser.add_argument("--run-glob", default=DEFAULT_RUN_GLOB, help="RunArtifact glob used when --run-dir is omitted.")
    parser.add_argument(
        "--method-ids",
        default="",
        help="Comma-separated method ids to export, or 'all'. Defaults to the legacy clean-v1 Table 2 method order.",
    )
    parser.add_argument("--out-json", default=str(OUT_JSON))
    parser.add_argument("--out-csv", default=str(OUT_CSV))
    parser.add_argument("--doc", default=str(DOC))
    args = parser.parse_args()

    run_dirs = [resolve_project_path(item) for item in args.run_dir] if args.run_dir else [latest_run_dir(args.run_glob)]
    if any(path is None or not path.exists() for path in run_dirs):
        raise FileNotFoundError(run_dirs)
    payload = build_payload([path for path in run_dirs if path is not None], requested_method_ids=parse_method_ids(args.method_ids))
    out_json = resolve_project_path(args.out_json) or OUT_JSON
    out_csv = resolve_project_path(args.out_csv) or OUT_CSV
    doc = resolve_project_path(args.doc) or DOC
    write_json(out_json, payload)
    write_csv(out_csv, payload)
    write_doc(doc, payload, out_json, out_csv)
    print(json.dumps({
        "run_dirs": [rel(path) for path in run_dirs if path is not None],
        "json": rel(out_json),
        "csv": rel(out_csv),
        "doc": rel(doc),
        "schema_version": payload["schema_version"],
    }, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Export the frozen JSAC Evidence Authority dev-only mechanism ablation.

The exporter is read-only.  It never loads holdout and fails closed when the
Authority and Naive arms do not preserve the same outcome-free Top-1 candidate
identity on all dev traces.
"""
from __future__ import annotations

import csv
import hashlib
import json
import math
import sys
from collections import Counter
from decimal import Decimal, localcontext
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from experiments.export_clean_v1_dev_observed_action_protocol import (  # noqa: E402
    load_run_samples,
)
from experiments.export_table3_stage27_structural_plane_dev import (  # noqa: E402
    candidate_identity,
    metric_bundle,
    selection_readset_audit,
)

WORK = ROOT / "runs/jsac_evidence_authority_execution_mix_corrected_20260907"
CONSTRUCTION = WORK / "construction_profile_summary.json"
REPLAY = WORK / "construction_replay_summary.json"
RUNS = WORK / "construction_replay_runs"
DEV = ROOT / "data/staged/splits/dev_trace_records.jsonl"
OUT = WORK / "evidence_authority_ablation.json"
OUT_CSV = WORK / "evidence_authority_ablation.csv"
REPORT = WORK / "evidence_authority_ablation.md"

METHOD = "pipeline_case_recall_echo_evidence_rank_no_outcome_counts_echo_gate"
AUTHORITY = "EA_authority_bundle_direct"
NAIVE = "EA_naive_component_broadcast"
STRUCTURAL = "EA_structural_association_only"
PROFILES = (AUTHORITY, NAIVE, STRUCTURAL)
LABELS = {
    AUTHORITY: "ECHO Authority",
    NAIVE: "Naive Broadcast",
    STRUCTURAL: "Structural Association Only",
}
AUTO_STATES = {"validated", "reusable"}


def read_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def iter_jsonl(path: Path):
    with path.open(encoding="utf-8") as handle:
        for line in handle:
            if line.strip():
                yield json.loads(line)


def ratio(numerator: int, denominator: int) -> dict[str, Any]:
    value = numerator / denominator if denominator else None
    return {
        "numerator": numerator,
        "denominator": denominator,
        "rate": value,
        "value": value,
    }


def stable_hash(values: list[str]) -> str:
    payload = json.dumps(values, ensure_ascii=False, separators=(",", ":"))
    return hashlib.sha256(payload.encode()).hexdigest()


def run_dir(profile: str) -> Path:
    matches = sorted(RUNS.glob(f"*{profile}*"))
    if len(matches) != 1:
        raise RuntimeError(f"expected one final run for {profile}, found {matches}")
    return matches[0]


def state_eligibility(state: str) -> str:
    if state in AUTO_STATES:
        return "auto_eligible"
    if state == "deprecated":
        return "ineligible"
    return "review_routed"


def sign_test_two_sided(left_only: int, right_only: int) -> float:
    n = left_only + right_only
    if not n:
        return 1.0
    tail = sum(math.comb(n, k) for k in range(min(left_only, right_only) + 1))
    with localcontext() as context:
        context.prec = 50
        probability = Decimal(2 * tail) / (Decimal(2) ** n)
    return min(1.0, float(probability))


def construction_audit() -> dict[str, Any]:
    summaries = {row["compiler_profile_id"]: row for row in read_json(CONSTRUCTION)}
    if set(summaries) != set(PROFILES):
        raise RuntimeError(f"unexpected construction profiles: {sorted(summaries)}")

    ids_by_profile: dict[str, dict[str, set[str]]] = {}
    strategies: dict[str, dict[str, dict[str, Any]]] = {}
    trace_hashes: dict[str, str] = {}
    channel_counts: dict[str, dict[str, int]] = {}
    invalid_rows = Counter()
    invalid_trace_ids: set[str] = set()

    for profile in PROFILES:
        profile_dir = WORK / profile
        ids_by_type: dict[str, set[str]] = {}
        strategy_rows: dict[str, dict[str, Any]] = {}
        for memory in iter_jsonl(profile_dir / "memory_objects.jsonl"):
            memory_type = str(memory.get("memory_type") or "unknown")
            memory_id = str(memory.get("memory_id") or "")
            ids_by_type.setdefault(memory_type, set()).add(memory_id)
            if memory_type == "strategy_memory":
                strategy_rows[memory_id] = memory
        ids_by_profile[profile] = ids_by_type
        strategies[profile] = strategy_rows

        trace_ids = []
        for trace in iter_jsonl(profile_dir / "trace_records.jsonl"):
            trace_ids.append(str(trace.get("trace_id") or ""))
            if profile != NAIVE:
                continue
            for action in trace.get("actions") or []:
                if (
                    isinstance(action, dict)
                    and action.get("evidence_authority_basis")
                    == "intentional_multi_action_bundle_broadcast_negative_control"
                ):
                    invalid_rows[str(action.get("outcome_role") or "unknown")] += 1
                    invalid_trace_ids.add(str(trace.get("trace_id") or ""))
        trace_hashes[profile] = stable_hash(sorted(trace_ids))

        channel_counts[profile] = {
            "action_memory_count": len(strategy_rows),
            "action_direct_source_unique_count": sum(
                int((row.get("metrics") or {}).get("action_direct_evidence_count") or 0)
                for row in strategy_rows.values()
            ),
            "component_of_bundle_source_unique_count": sum(
                int((row.get("metrics") or {}).get("component_associated_count") or 0)
                for row in strategy_rows.values()
            ),
            "support_source_unique_count": sum(
                int((row.get("metrics") or {}).get("long_eval_pass_count") or 0)
                for row in strategy_rows.values()
            ),
            "counter_source_unique_count": sum(
                int((row.get("metrics") or {}).get("long_eval_fail_count") or 0)
                for row in strategy_rows.values()
            ),
        }

    authority_strategy = strategies[AUTHORITY]
    naive_strategy = strategies[NAIVE]
    if set(authority_strategy) != set(naive_strategy):
        raise RuntimeError("Authority and Naive Action Memory ID sets differ")

    pass_deltas: dict[str, int] = {}
    fail_deltas: dict[str, int] = {}
    state_transitions = Counter()
    role_transitions = Counter()
    eligibility_transitions = Counter()
    for memory_id, authority_row in authority_strategy.items():
        naive_row = naive_strategy[memory_id]
        authority_content = authority_row.get("content") or {}
        naive_content = naive_row.get("content") or {}
        pass_delta = int(naive_content.get("long_eval_pass_count") or 0) - int(
            authority_content.get("long_eval_pass_count") or 0
        )
        fail_delta = int(naive_content.get("long_eval_fail_count") or 0) - int(
            authority_content.get("long_eval_fail_count") or 0
        )
        pass_deltas[memory_id] = pass_delta
        fail_deltas[memory_id] = fail_delta
        authority_state = str(authority_row.get("state") or "unknown")
        naive_state = str(naive_row.get("state") or "unknown")
        state_transitions[(authority_state, naive_state)] += 1
        role_transitions[(
            str(authority_content.get("action_memory_role") or "unknown"),
            str(naive_content.get("action_memory_role") or "unknown"),
        )] += 1
        eligibility_transitions[(
            state_eligibility(authority_state),
            state_eligibility(naive_state),
        )] += 1

    invalid_support = sum(pass_deltas.values())
    invalid_counter = sum(fail_deltas.values())
    invalid_total = invalid_support + invalid_counter
    affected = {
        memory_id
        for memory_id in authority_strategy
        if pass_deltas[memory_id] or fail_deltas[memory_id]
    }
    affected_support = {memory_id for memory_id, value in pass_deltas.items() if value}
    affected_counter = {memory_id for memory_id, value in fail_deltas.items() if value}
    naive_channels = channel_counts[NAIVE]

    if invalid_total != sum(invalid_rows.values()):
        raise RuntimeError(
            "source-unique pollution did not close to invalid component rows: "
            f"compiled={invalid_total}, rows={sum(invalid_rows.values())}"
        )
    if len(set(trace_hashes.values())) != 1:
        raise RuntimeError(f"train trace hashes differ: {trace_hashes}")
    relation_counts = {
        profile: values["component_of_bundle_source_unique_count"]
        for profile, values in channel_counts.items()
    }
    if len(set(relation_counts.values())) != 1:
        raise RuntimeError(f"component-of-bundle structure differs: {relation_counts}")

    id_integrity: dict[str, Any] = {}
    all_types = sorted({key for value in ids_by_profile.values() for key in value})
    for memory_type in all_types:
        authority_ids = ids_by_profile[AUTHORITY].get(memory_type, set())
        id_integrity[memory_type] = {
            "authority_count": len(authority_ids),
            "authority_id_sha256": stable_hash(sorted(authority_ids)),
            "naive_missing": len(authority_ids - ids_by_profile[NAIVE].get(memory_type, set())),
            "naive_extra": len(ids_by_profile[NAIVE].get(memory_type, set()) - authority_ids),
            "structural_only_missing": len(
                authority_ids - ids_by_profile[STRUCTURAL].get(memory_type, set())
            ),
            "structural_only_extra": len(
                ids_by_profile[STRUCTURAL].get(memory_type, set()) - authority_ids
            ),
        }

    def transition_rows(counter: Counter[tuple[str, str]]) -> list[dict[str, Any]]:
        return [
            {"from": left, "to": right, "count": count}
            for (left, right), count in sorted(counter.items())
        ]

    return {
        "construction_summary": str(CONSTRUCTION.relative_to(ROOT)),
        "train_trace_count": int(summaries[AUTHORITY]["train_trace_count"]),
        "train_trace_id_sha256": trace_hashes[AUTHORITY],
        "train_trace_hashes_equal": len(set(trace_hashes.values())) == 1,
        "memory_id_integrity": id_integrity,
        "channel_counts": channel_counts,
        "invalid_component_rows": {
            "binary_multi_action_bundle_count": len(invalid_trace_ids),
            "support": invalid_rows["support"],
            "counter": invalid_rows["counter"],
            "total": sum(invalid_rows.values()),
        },
        "source_unique_pollution": {
            "invalid_support_contributions": invalid_support,
            "invalid_counter_contributions": invalid_counter,
            "invalid_total_contributions": invalid_total,
            "naive_total_action_direct_contributions": naive_channels[
                "action_direct_source_unique_count"
            ],
            "overall_pollution_ratio": ratio(
                invalid_total,
                naive_channels["action_direct_source_unique_count"],
            ),
            "support_pollution_ratio": ratio(
                invalid_support,
                naive_channels["support_source_unique_count"],
            ),
            "counter_pollution_ratio": ratio(
                invalid_counter,
                naive_channels["counter_source_unique_count"],
            ),
            "affected_action_memories": len(affected),
            "affected_by_support": len(affected_support),
            "affected_by_counter": len(affected_counter),
            "affected_by_both": len(affected_support & affected_counter),
            "action_memory_count": len(authority_strategy),
            "affected_action_memory_ratio": ratio(len(affected), len(authority_strategy)),
        },
        "action_memory_state": {
            "authority_distribution": dict(sorted(Counter(
                str(row.get("state") or "unknown")
                for row in authority_strategy.values()
            ).items())),
            "naive_distribution": dict(sorted(Counter(
                str(row.get("state") or "unknown")
                for row in naive_strategy.values()
            ).items())),
            "changed_count": sum(
                count for (left, right), count in state_transitions.items() if left != right
            ),
            "transitions": transition_rows(state_transitions),
            "role_transitions": transition_rows(role_transitions),
            "state_derived_use_eligibility_contract": (
                "validated/reusable=auto_eligible; deprecated=ineligible; "
                "all other states=review_routed; this is a compiler-side summary, "
                "not the full runtime gate"
            ),
            "state_derived_use_eligibility_transitions": transition_rows(
                eligibility_transitions
            ),
        },
        "structural_integrity": {
            "component_of_bundle_counts_equal": len(set(relation_counts.values())) == 1,
            "component_of_bundle_counts": relation_counts,
            "authority_naive_all_memory_ids_equal": all(
                not row["naive_missing"] and not row["naive_extra"]
                for row in id_integrity.values()
            ),
            "structural_only_difference": (
                "90 counter_evidence_memory objects are absent; all case, strategy, "
                "playbook, RCA, and risk Memory IDs are unchanged"
            ),
        },
    }


def runtime_audit() -> dict[str, Any]:
    replay = read_json(REPLAY)
    replay_rows = {row["compiler_profile_id"]: row for row in replay["rows"]}
    dev_outcomes = {
        str(trace.get("trace_id") or ""): str(
            (trace.get("aggregate") or {}).get("ticket_outcome") or "unknown"
        )
        for trace in iter_jsonl(DEV)
    }
    metrics: dict[str, Any] = {}
    identity_hashes: dict[str, str] = {}
    identities: dict[str, dict[str, str]] = {}
    route_rows: dict[str, dict[str, dict[str, Any]]] = {}
    readset: dict[str, Any] = {}

    for profile in PROFILES:
        current_run = run_dir(profile)
        metrics[profile] = metric_bundle(current_run, METHOD)
        identity_hashes[profile], identities[profile] = candidate_identity(
            current_run, METHOD
        )
        readset[profile] = selection_readset_audit(
            current_run, METHOD, relation_read=True
        )
        rows_by_method, source_meta, _ = load_run_samples(current_run)
        if source_meta.get("dataset_role") != "dev":
            raise RuntimeError(f"non-dev replay for {profile}")
        route_rows[profile] = {
            str(row.get("trace_id") or ""): row
            for row in rows_by_method[METHOD]
        }

    authority_hash = identity_hashes[AUTHORITY]
    changed_candidates = {
        profile: sum(
            identities[profile].get(trace_id) != identity
            for trace_id, identity in identities[AUTHORITY].items()
        )
        for profile in PROFILES
    }
    if identity_hashes[NAIVE] != authority_hash or changed_candidates[NAIVE] != 0:
        raise RuntimeError(
            "Authority and Naive Top-1 identity differ; consumer interpretation invalid"
        )
    if not all(item.get("all_passed") for item in readset.values()):
        raise RuntimeError(f"outcome-free selector read-set audit failed: {readset}")

    route_comparisons: dict[str, Any] = {}
    authority_rows = route_rows[AUTHORITY]
    for profile in (NAIVE, STRUCTURAL):
        transitions = Counter()
        changed = []
        for trace_id, authority_row in authority_rows.items():
            comparison_row = route_rows[profile][trace_id]
            authority_gate = str(
                (authority_row.get("decision") or {}).get("gate_decision") or "unknown"
            )
            comparison_gate = str(
                (comparison_row.get("decision") or {}).get("gate_decision") or "unknown"
            )
            transitions[(authority_gate, comparison_gate)] += 1
            if authority_gate != comparison_gate:
                classification = authority_row.get("classification") or {}
                changed.append({
                    "trace_id": trace_id,
                    "from": authority_gate,
                    "to": comparison_gate,
                    "dev_ticket_outcome": dev_outcomes.get(trace_id, "unknown"),
                    "authority_safety_label": classification.get("safety_label"),
                    "authority_outcome_class": classification.get("outcome_class"),
                })
        accept_to_review = transitions[("accept", "require_review")]
        review_to_accept = transitions[("require_review", "accept")]
        route_comparisons[profile] = {
            "changed_count": len(changed),
            "transitions": [
                {"from": left, "to": right, "count": count}
                for (left, right), count in sorted(transitions.items())
            ],
            "changed_dev_outcome_distribution": dict(sorted(Counter(
                row["dev_ticket_outcome"] for row in changed
            ).items())),
            "changed_rows": changed if len(changed) <= 20 else changed[:20],
            "changed_rows_truncated": len(changed) > 20,
            "paired_exact_sign_p": sign_test_two_sided(
                accept_to_review, review_to_accept
            ),
        }

    integrity = {}
    for profile in PROFILES:
        current_run = run_dir(profile)
        spec = read_json(current_run / "spec.json")
        readiness = read_json(current_run / "readiness.json")
        integrity[profile] = {
            "run_dir": str(current_run.relative_to(ROOT)),
            "trace_count": len(route_rows[profile]),
            "code_commit": (spec.get("reproducibility") or {}).get("code_commit"),
            "code_dirty": (spec.get("reproducibility") or {}).get("code_dirty"),
            "code_tree_hash": (spec.get("reproducibility") or {}).get("code_tree_hash"),
            "readiness_ok": readiness.get("ok"),
            "readiness_checks": readiness.get("checks"),
            "leakage_overlap_counts": (readiness.get("leakage") or {}).get(
                "overlap_counts"
            ),
            "metric_contracts_passed": metrics[profile]["integrity"],
            "selection_readset_passed": readset[profile]["all_passed"],
        }

    return {
        "replay_summary": str(REPLAY.relative_to(ROOT)),
        "fixed_consumer": replay.get("fixed_consumer"),
        "metrics": metrics,
        "candidate_identity": {
            "hashes": identity_hashes,
            "changed_counts_vs_authority": changed_candidates,
            "authority_naive_exactly_equal": (
                identity_hashes[NAIVE] == authority_hash
                and changed_candidates[NAIVE] == 0
            ),
            "dev_trace_count": len(identities[AUTHORITY]),
        },
        "route_comparisons_vs_authority": route_comparisons,
        "integrity": integrity,
        "holdout_loaded": False,
    }


def pct(metric: dict[str, Any]) -> str:
    value = metric.get("rate")
    return "n/a" if value is None else f"{100 * float(value):.2f}%"


def write_csv(payload: dict[str, Any]) -> None:
    construction = payload["construction"]
    runtime = payload["runtime"]
    OUT_CSV.parent.mkdir(parents=True, exist_ok=True)
    with OUT_CSV.open("w", encoding="utf-8", newline="") as handle:
