#!/usr/bin/env python3
"""Export the JSAC Evidence Authority violation-propagation audit.

This is a read-only dev-only 2x2 mechanism audit.  It reuses the frozen
Authority/Naive packages and candidate decisions from Table 4, then compares
direct consumption of the selected Action Memory's published Use Eligibility
with a monotone intersection of that eligibility and the frozen conservative
gate.  The Frozen Candidate-Locked Governance Consumer reported in Table 4
remains a separate bridge diagnostic.  Holdout is never loaded.
"""
from __future__ import annotations

import csv
import json
import math
import sys
from collections import Counter
from datetime import datetime, timezone
from decimal import Decimal, localcontext
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from experiments.export_attribution_safe_dev_audit import (  # noqa: E402
    observed_actions,
    strict_given_negative_audit,
)
from experiments.export_clean_v1_dev_observed_action_protocol import (  # noqa: E402
    action_supported,
    load_run_samples,
)
from pipeline.evaluation.retrieval_baselines import (  # noqa: E402
    _candidate_strategy_evidence,
)

WORK = ROOT / "runs/jsac_evidence_authority_execution_mix_corrected_20260907"
RUNS = WORK / "construction_replay_runs"
BASE_RETAINED = WORK / "evidence_authority_ablation.json"
OUT = WORK / "evidence_authority_propagation.json"
OUT_CSV = WORK / "evidence_authority_propagation.csv"
REPORT = WORK / "evidence_authority_propagation.md"

METHOD = "pipeline_case_recall_echo_evidence_rank_no_outcome_counts_echo_gate"
AUTHORITY = "EA_authority_bundle_direct"
NAIVE = "EA_naive_component_broadcast"
PROFILES = (AUTHORITY, NAIVE)
LABELS = {AUTHORITY: "ECHO Authority", NAIVE: "Naive Broadcast"}
AUTO_STATES = {"validated", "reusable"}
REVIEW_STATES = {"unverified", "restricted", "counter_evidence"}
EXPECTED_COMMIT: str | None = None
EXPECTED_CODE_DIRTY: bool | None = None


def read_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def iter_jsonl(path: Path):
    with path.open(encoding="utf-8") as handle:
        for line in handle:
            if line.strip():
                yield json.loads(line)


def ratio(numerator: int, denominator: int) -> dict[str, Any]:
    value = numerator / denominator if denominator else None
    return {
        "numerator": numerator,
        "denominator": denominator,
        "rate": value,
        "value": value,
    }


def lifecycle_route(state: str) -> str:
    """Map the frozen Lifecycle State through the published Policy Interface."""
    normalized = str(state or "").strip().lower()
    if normalized in AUTO_STATES:
        return "auto"
    if normalized in REVIEW_STATES:
        return "review"
    if normalized == "deprecated":
        return "reject"
    raise ValueError(f"unknown Lifecycle State: {state!r}")


def gate_decision_route(gate: str) -> str:
    gate = str(gate or "")
    if gate in {"accept", "downgrade"}:
        return "auto"
    if gate == "require_review":
        return "review"
    if gate == "reject":
        return "reject"
    raise ValueError(f"unknown gate decision: {gate!r}")


def gate_route(row: dict[str, Any]) -> str:
    decision = row.get("decision") if isinstance(row.get("decision"), dict) else {}
    gate = str(decision.get("gate_decision") or row.get("gate_decision") or "")
    return gate_decision_route(gate)


def conservative_intersection(eligibility_route: str, frozen_gate_route: str) -> str:
    severity = {"auto": 0, "review": 1, "reject": 2}
    if eligibility_route not in severity or frozen_gate_route not in severity:
        raise ValueError(
            f"unknown route pair: {eligibility_route!r}, {frozen_gate_route!r}"
        )
    return max((eligibility_route, frozen_gate_route), key=severity.__getitem__)


def sign_test_two_sided(left_only: int, right_only: int) -> float:
    n = left_only + right_only
    if not n:
        return 1.0
    tail = sum(math.comb(n, k) for k in range(min(left_only, right_only) + 1))
    with localcontext() as context:
        context.prec = 60
        probability = Decimal(2 * tail) / (Decimal(2) ** n)
    return min(1.0, float(probability))


def route_comparison(
    authority_routes: dict[str, str],
    naive_routes: dict[str, str],
    outcomes: dict[str, str],
) -> dict[str, Any]:
    if set(authority_routes) != set(naive_routes):
        raise RuntimeError("Authority/Naive route target sets differ")
    transitions = Counter()
    changed_ids: set[str] = set()
    changed_outcomes = Counter()
    toward_auto = 0
    away_from_auto = 0
    for trace_id, authority_route in authority_routes.items():
        naive_route = naive_routes[trace_id]
        transitions[(authority_route, naive_route)] += 1
        if authority_route == naive_route:
            continue
        changed_ids.add(trace_id)
        changed_outcomes[outcomes.get(trace_id, "unknown")] += 1
        toward_auto += int(authority_route != "auto" and naive_route == "auto")
        away_from_auto += int(authority_route == "auto" and naive_route != "auto")
    return {
        "changed_count": len(changed_ids),
        "changed_trace_ids": sorted(changed_ids),
        "transitions": [
            {"from": left, "to": right, "count": count}
            for (left, right), count in sorted(transitions.items())
        ],
        "toward_auto": toward_auto,
        "away_from_auto": away_from_auto,
        "other_changed": len(changed_ids) - toward_auto - away_from_auto,
        "changed_target_outcome_distribution": dict(sorted(changed_outcomes.items())),
        "paired_exact_sign_p": sign_test_two_sided(toward_auto, away_from_auto),
    }


def run_dir(profile: str) -> Path:
    matches = sorted(RUNS.glob(f"*{profile}*"))
    if len(matches) != 1:
        raise RuntimeError(f"expected one final run for {profile}, found {matches}")
    return matches[0]


def load_profile(profile: str) -> dict[str, Any]:
    current_run = run_dir(profile)
    rows_by_method, source_meta, traces = load_run_samples(current_run)
    if source_meta.get("dataset_role") != "dev":
        raise RuntimeError(f"non-dev run for {profile}")
    if set(rows_by_method) != {METHOD}:
        raise RuntimeError(f"unexpected methods for {profile}: {sorted(rows_by_method)}")
    rows = {
        str(row.get("trace_id") or ""): row
        for row in rows_by_method[METHOD]
    }
    if len(rows) != 3247:
        raise RuntimeError(f"expected 3,247 rows for {profile}, got {len(rows)}")

    memories = list(iter_jsonl(WORK / profile / "memory_objects.jsonl"))
    memory_by_id = {
        str(row.get("memory_id") or ""): row
        for row in memories
    }
    strategies = {
        memory_id: row
        for memory_id, row in memory_by_id.items()
        if row.get("memory_type") == "strategy_memory"
    }
    if len(strategies) != 599:
        raise RuntimeError(f"expected 599 Action Memories for {profile}")
    return {
        "run_dir": current_run,
        "rows": rows,
        "traces": traces,
        "memories": memories,
        "memory_by_id": memory_by_id,
        "strategies": strategies,
        "source_meta": source_meta,
    }


def selected_primary_memory(row: dict[str, Any]) -> tuple[str, str]:
    decision = row.get("decision") if isinstance(row.get("decision"), dict) else {}
    rank = (
        decision.get("selected_score_breakdown")
        if isinstance(decision.get("selected_score_breakdown"), dict)
        else {}
    )
    evidence = rank.get("strategy_evidence") or []
    if not evidence or not isinstance(evidence[0], dict):
        raise RuntimeError(f"missing selected Action Memory for {row.get('trace_id')}")
    primary = evidence[0]
    return str(primary.get("memory_id") or ""), str(primary.get("memory_type") or "")


def selected_readout(profile_data: dict[str, Any]) -> dict[str, Any]:
    routes: dict[str, str] = {}
    memory_ids: dict[str, str] = {}
    states: dict[str, str] = {}
    gated_routes: dict[str, str] = {}
    unique_memories = Counter()
    review_count = 0
    reject_count = 0
    strict_pass_hit_count = 0
    strict_pass_auto_count = 0

    for trace_id, row in profile_data["rows"].items():
        memory_id, memory_type = selected_primary_memory(row)
        if memory_type != "strategy_memory":
            raise RuntimeError(f"non-Action primary Memory for {trace_id}: {memory_type}")
        memory = profile_data["strategies"].get(memory_id)
        if memory is None:
            raise RuntimeError(f"selected Action Memory absent from package: {memory_id}")
        state = str(memory.get("state") or "")
        route = lifecycle_route(state)
        routes[trace_id] = route
        memory_ids[trace_id] = memory_id
        states[trace_id] = state
        gated_routes[trace_id] = gate_route(row)
        unique_memories[memory_id] += 1
        review_count += int(route == "review")
        reject_count += int(route == "reject")

        info = profile_data["traces"].get(trace_id) or {}
        if info.get("ticket_outcome") != "long_eval_pass":
            continue
        trace = info.get("trace") if isinstance(info.get("trace"), dict) else {}
        actions = observed_actions(trace, "long_eval_pass")
        if len(actions) != 1 or not action_supported(row):
            continue
        strict_pass_hit_count += 1
        strict_pass_auto_count += int(route == "auto")

    return {
        "routes": routes,
        "gated_routes": gated_routes,
        "memory_ids": memory_ids,
        "states": states,
        "unique_memory_reach": len(unique_memories),
        "memory_target_counts": dict(sorted(unique_memories.items())),
        "review_burden": ratio(review_count + reject_count, len(routes)),
        "review_count": review_count,
        "reject_count": reject_count,
        "supported_action_auto_retention": ratio(
            strict_pass_auto_count, strict_pass_hit_count
        ),
    }


def selected_route_metrics(
    profile_data: dict[str, Any], routes: dict[str, str]
) -> dict[str, Any]:
    if set(routes) != set(profile_data["rows"]):
        raise RuntimeError("selected route metric target set mismatch")
    review_or_reject = sum(route != "auto" for route in routes.values())
    strict_pass_hit_count = 0
    strict_pass_auto_count = 0
    for trace_id, row in profile_data["rows"].items():
        info = profile_data["traces"].get(trace_id) or {}
        if info.get("ticket_outcome") != "long_eval_pass":
            continue
        trace = info.get("trace") if isinstance(info.get("trace"), dict) else {}
        actions = observed_actions(trace, "long_eval_pass")
        if len(actions) != 1 or not action_supported(row):
            continue
        strict_pass_hit_count += 1
        strict_pass_auto_count += int(routes[trace_id] == "auto")
    return {
        "review_burden": ratio(review_or_reject, len(routes)),
        "supported_action_auto_retention": ratio(
            strict_pass_auto_count, strict_pass_hit_count
        ),
    }


def given_fail_readout(profile_data: dict[str, Any]) -> dict[str, Any]:
    routes: dict[str, str] = {}
    memory_ids: dict[str, str] = {}
    states: dict[str, str] = {}
    for trace_id, info in profile_data["traces"].items():
        if info.get("ticket_outcome") != "long_eval_fail":
            continue
        trace = info.get("trace") if isinstance(info.get("trace"), dict) else {}
        actions = observed_actions(trace, "long_eval_fail")
        if len(actions) != 1:
            continue
        evidence = _candidate_strategy_evidence(
            actions[0],
            trace,
            profile_data["memories"],
            selection_policy="structural_relation_v1",
        )
        if not evidence or evidence[0].get("memory_type") != "strategy_memory":
            raise RuntimeError(f"failed action did not resolve to Action Memory: {trace_id}")
        memory_id = str(evidence[0].get("memory_id") or "")
        memory = profile_data["strategies"].get(memory_id)
        if memory is None:
            raise RuntimeError(f"given-fail Action Memory absent: {memory_id}")
        state = str(memory.get("state") or "")
        memory_ids[trace_id] = memory_id
        states[trace_id] = state
        routes[trace_id] = lifecycle_route(state)
    if len(routes) != 447:
        raise RuntimeError(f"expected 447 strict Fail actions, got {len(routes)}")
    withheld = sum(route != "auto" for route in routes.values())
    return {
        "routes": routes,
        "memory_ids": memory_ids,
        "states": states,
        "strict_failed_action_withholding": ratio(withheld, len(routes)),
    }


def given_fail_gate_readout(profile_data: dict[str, Any]) -> dict[str, Any]:
    summary, decisions = strict_given_negative_audit(profile_data["run_dir"])
    routes = {
        str(row.get("trace_id") or ""): gate_decision_route(
            str(row.get("gate_decision") or "")
        )
        for row in decisions
    }
    if len(routes) != 447 or not summary["integrity"]["all_passed"]:
        raise RuntimeError("frozen given-Fail gate replay failed")
    return {
        "routes": routes,
        "strict_failed_action_withholding": summary[
            "strict_given_failed_action_withholding"
        ],
    }


def metric_row(
    profile: str,
    mode: str,
    selected: dict[str, Any],
    given_fail: dict[str, Any],
    route_changes: int,
) -> dict[str, Any]:
    return {
        "evidence_policy": profile,
        "evidence_policy_label": LABELS[profile],
        "consumer_mode": mode,
        "consumer_mode_label": (
            "Direct Eligibility"
            if mode == "direct_eligibility"
            else (
                "Post-Eligibility Conservative Gate"
                if mode == "post_eligibility_conservative_gate"
                else "Frozen Candidate-Locked Governance Consumer"
            )
        ),
        "strict_failed_action_withholding": given_fail[
            "strict_failed_action_withholding"
        ],
        "supported_action_auto_retention": selected[
            "supported_action_auto_retention"
        ],
        "review_burden": selected["review_burden"],
        "route_changes_vs_authority_same_mode": route_changes,
    }


def pct(metric: dict[str, Any]) -> str:
    value = metric.get("rate")
    return "n/a" if value is None else f"{100 * float(value):.2f}%"


def main() -> None:
    base = read_json(BASE_RETAINED)
    if base.get("schema_version") != "jsac_evidence_authority_ablation.v1":
        raise RuntimeError("unexpected Table 4 retained artifact")
    profile_data = {profile: load_profile(profile) for profile in PROFILES}
    selected = {profile: selected_readout(profile_data[profile]) for profile in PROFILES}
    given_fail = {profile: given_fail_readout(profile_data[profile]) for profile in PROFILES}
    given_fail_gate = {
        profile: given_fail_gate_readout(profile_data[profile]) for profile in PROFILES
    }

    combined_selected: dict[str, dict[str, Any]] = {}
    combined_given_fail: dict[str, dict[str, Any]] = {}
    candidate_locked_selected: dict[str, dict[str, Any]] = {}
    for profile in PROFILES:
        combined_selected_routes = {
            trace_id: conservative_intersection(
                selected[profile]["routes"][trace_id],
                selected[profile]["gated_routes"][trace_id],
            )
            for trace_id in selected[profile]["routes"]
        }
        selected_metrics = selected_route_metrics(
            profile_data[profile], combined_selected_routes
        )
        combined_selected[profile] = {
            "routes": combined_selected_routes,
            **selected_metrics,
        }
        combined_given_routes = {
            trace_id: conservative_intersection(
                given_fail[profile]["routes"][trace_id],
                given_fail_gate[profile]["routes"][trace_id],
            )
            for trace_id in given_fail[profile]["routes"]
        }
        combined_given_fail[profile] = {
            "routes": combined_given_routes,
            "strict_failed_action_withholding": ratio(
                sum(route != "auto" for route in combined_given_routes.values()),
                len(combined_given_routes),
            ),
        }
        candidate_locked_selected[profile] = {
            "routes": selected[profile]["gated_routes"],
            **selected_route_metrics(
                profile_data[profile], selected[profile]["gated_routes"]
            ),
        }

        severity = {"auto": 0, "review": 1, "reject": 2}
        if any(
            severity[combined_selected_routes[trace_id]]
            < severity[selected[profile]["routes"][trace_id]]
            for trace_id in combined_selected_routes
        ):
            raise RuntimeError(f"selected gate released a direct route for {profile}")
        if any(
            severity[combined_given_routes[trace_id]]
            < severity[given_fail[profile]["routes"][trace_id]]
            for trace_id in combined_given_routes
        ):
            raise RuntimeError(f"given-Fail gate released a direct route for {profile}")

        if not (
            combined_given_fail[profile]["strict_failed_action_withholding"][
                "numerator"
            ]
            >= given_fail[profile]["strict_failed_action_withholding"]["numerator"]
            and combined_selected[profile]["supported_action_auto_retention"][
                "numerator"
            ]
            <= selected[profile]["supported_action_auto_retention"]["numerator"]
            and combined_selected[profile]["review_burden"]["numerator"]
            >= selected[profile]["review_burden"]["numerator"]
        ):
            raise RuntimeError(f"aggregate gate monotonicity failed for {profile}")

    trace_sets = {profile: set(selected[profile]["routes"]) for profile in PROFILES}
    if len({frozenset(value) for value in trace_sets.values()}) != 1:
        raise RuntimeError("selected target sets differ")
    outcomes = {
        trace_id: str(info.get("ticket_outcome") or "unknown")
        for trace_id, info in profile_data[AUTHORITY]["traces"].items()
    }
    selected_memory_changes = sum(
        selected[AUTHORITY]["memory_ids"][trace_id]
        != selected[NAIVE]["memory_ids"][trace_id]
        for trace_id in selected[AUTHORITY]["memory_ids"]
    )
    given_fail_memory_changes = sum(
        given_fail[AUTHORITY]["memory_ids"][trace_id]
        != given_fail[NAIVE]["memory_ids"][trace_id]
        for trace_id in given_fail[AUTHORITY]["memory_ids"]
    )
    if selected_memory_changes or given_fail_memory_changes:
        raise RuntimeError(
            "Authority/Naive Action Memory identity changed: "
            f"selected={selected_memory_changes}, given_fail={given_fail_memory_changes}"
        )

    direct_comparison = route_comparison(
        selected[AUTHORITY]["routes"], selected[NAIVE]["routes"], outcomes
    )
    gated_comparison = route_comparison(
        selected[AUTHORITY]["gated_routes"],
        selected[NAIVE]["gated_routes"],
        outcomes,
    )
    combined_comparison = route_comparison(
        combined_selected[AUTHORITY]["routes"],
        combined_selected[NAIVE]["routes"],
        outcomes,
    )
    direct_changed = set(direct_comparison["changed_trace_ids"])

    authority_memory_counts = Counter(selected[AUTHORITY]["memory_ids"].values())
    reached_memory_transitions = Counter()
    weighted_memory_transitions = Counter()
    flipped_reached_memories: set[str] = set()
    for memory_id, target_count in authority_memory_counts.items():
        authority_state = str(profile_data[AUTHORITY]["strategies"][memory_id].get("state") or "")
        naive_state = str(profile_data[NAIVE]["strategies"][memory_id].get("state") or "")
        left = lifecycle_route(authority_state)
        right = lifecycle_route(naive_state)
        reached_memory_transitions[(left, right)] += 1
        weighted_memory_transitions[(left, right)] += target_count
        if left != right:
            flipped_reached_memories.add(memory_id)

    base_metrics = base["runtime"]["metrics"]
    table_rows = []
    for mode, comparison in (
        ("direct_eligibility", direct_comparison),
        ("post_eligibility_conservative_gate", combined_comparison),
    ):
        for profile in PROFILES:
            selected_readout_for_mode = (
                selected[profile]
                if mode == "direct_eligibility"
                else combined_selected[profile]
            )
            given_fail_for_mode = (
                given_fail[profile]
                if mode == "direct_eligibility"
                else combined_given_fail[profile]
            )
            table_rows.append(metric_row(
                profile,
                mode,
                selected_readout_for_mode,
                given_fail_for_mode,
                0 if profile == AUTHORITY else comparison["changed_count"],
            ))
    bridge_rows = [
        metric_row(
            profile,
            "candidate_locked_governance_consumer",
            candidate_locked_selected[profile],
            given_fail_gate[profile],
            0 if profile == AUTHORITY else gated_comparison["changed_count"],
        )
        for profile in PROFILES
    ]

    for profile in PROFILES:
        integrity = base["runtime"]["integrity"][profile]
        if (
            (EXPECTED_COMMIT is not None and integrity.get("code_commit") != EXPECTED_COMMIT)
            or (EXPECTED_CODE_DIRTY is not None and integrity.get("code_dirty") is not EXPECTED_CODE_DIRTY)
            or integrity.get("readiness_ok") is not True
            or integrity.get("selection_readset_passed") is not True
            or any((integrity.get("leakage_overlap_counts") or {}).values())
        ):
            raise RuntimeError(f"formal replay integrity failed for {profile}: {integrity}")

    for profile in PROFILES:
        gated = next(
            row for row in bridge_rows
            if row["evidence_policy"] == profile
            and row["consumer_mode"] == "candidate_locked_governance_consumer"
        )
        retained = base_metrics[profile]
        if (
            gated["strict_failed_action_withholding"] != retained["strict_failed_action_withholding"]
            or gated["supported_action_auto_retention"] != retained["supported_action_auto_retention"]
            or gated["review_burden"] != retained["native_candidate_review_rate"]
        ):
            raise RuntimeError(
                f"Candidate-Locked Governance Consumer drifted from Table 4 for {profile}"
            )

    pollution = base["construction"]["source_unique_pollution"]
    state = base["construction"]["action_memory_state"]
    eligibility_flip_count = sum(
        int(row["count"])
        for row in state["state_derived_use_eligibility_transitions"]
        if row["from"] != row["to"]
    )
    payload = {
        "schema_version": "jsac_evidence_authority_propagation.v1",
        "generated_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "status": "retained_dev_exploratory_mechanism_audit",
        "protocol": "docs/protocols/evidence_authority_propagation.md",
        "scientific_question": (
            "How far authority-blind Action Memory state changes propagate under "
            "direct eligibility consumption, and how much a monotone intersection "
            "with the Post-Eligibility Conservative Gate attenuates that propagation."
        ),
        "two_by_two": table_rows,
        "table4_candidate_locked_governance_consumer_bridge": bridge_rows,
        "propagation_funnel": {
            "unauthorized_action_direct_contributions": pollution[
                "invalid_total_contributions"
            ],
            "polluted_action_memories": pollution["affected_action_memories"],
            "lifecycle_state_changes": state["changed_count"],
            "use_eligibility_flips_all_action_memories": eligibility_flip_count,
            "unique_selected_action_memories": selected[AUTHORITY]["unique_memory_reach"],
            "selected_action_memories_with_eligibility_flip": len(
                flipped_reached_memories
            ),
            "dev_route_changes_direct_eligibility": direct_comparison["changed_count"],
            "dev_route_changes_post_eligibility_conservative_gate": combined_comparison[
                "changed_count"
            ],
            "dev_route_changes_candidate_locked_governance_consumer": gated_comparison[
                "changed_count"
            ],
        },
        "selected_action_memory_reach": {
            "authority_unique_count": selected[AUTHORITY]["unique_memory_reach"],
            "naive_unique_count": selected[NAIVE]["unique_memory_reach"],
            "identity_changes": selected_memory_changes,
            "flipped_memory_count": len(flipped_reached_memories),
            "flipped_memory_ids": sorted(flipped_reached_memories),
            "memory_level_route_transitions": [
                {"from": left, "to": right, "count": count}
                for (left, right), count in sorted(reached_memory_transitions.items())
            ],
            "target_weighted_route_transitions": [
                {"from": left, "to": right, "count": count}
                for (left, right), count in sorted(weighted_memory_transitions.items())
            ],
        },
        "paired_route_comparisons": {
            "direct_eligibility": direct_comparison,
            "post_eligibility_conservative_gate": combined_comparison,
            "candidate_locked_governance_consumer": gated_comparison,
            "direct_vs_combined_changed_set_overlap": len(
                direct_changed & set(combined_comparison["changed_trace_ids"])
            ),
            "direct_changed_rows_still_divergent_after_gate": sum(
                combined_selected[AUTHORITY]["routes"][trace_id]
                != combined_selected[NAIVE]["routes"][trace_id]
                for trace_id in direct_changed
            ),
            "observed_divergence_count_reduction_after_gate": ratio(
                direct_comparison["changed_count"] - combined_comparison["changed_count"],
                direct_comparison["changed_count"],
            ),
        },
        "integrity": {
            "dataset_role": "dev",
            "dev_trace_count": 3247,
            "strict_fail_count": len(given_fail[AUTHORITY]["routes"]),
            "selected_primary_memory_type_all_strategy": True,
            "selected_primary_memory_identity_changes": selected_memory_changes,
            "given_fail_primary_memory_identity_changes": given_fail_memory_changes,
            "post_eligibility_gate_is_monotone_conservative_intersection": all(
                combined_selected[profile]["routes"][trace_id]
                == conservative_intersection(
                    selected[profile]["routes"][trace_id],
                    selected[profile]["gated_routes"][trace_id],
                )
                for profile in PROFILES
                for trace_id in selected[profile]["routes"]
            ),
            "post_eligibility_gate_aggregate_monotonicity": all(
                combined_given_fail[profile]["strict_failed_action_withholding"][
                    "numerator"
                ]
                >= given_fail[profile]["strict_failed_action_withholding"][
                    "numerator"
                ]
                and combined_selected[profile][
                    "supported_action_auto_retention"
                ]["numerator"]
                <= selected[profile]["supported_action_auto_retention"][
                    "numerator"
                ]
                and combined_selected[profile]["review_burden"]["numerator"]
                >= selected[profile]["review_burden"]["numerator"]
                for profile in PROFILES
            ),
            "candidate_locked_consumer_exactly_reuses_table4": True,
            "outcome_free_selector_readset_passed": True,
            "code_commit": base["runtime"]["integrity"][AUTHORITY].get("code_commit"),
            "code_dirty": base["runtime"]["integrity"][AUTHORITY].get("code_dirty"),
            "leakage_overlap_counts": {"dev": 0, "holdout": 0, "eval_set_a": 0},
            "holdout_loaded": False,
            "all_passed": True,
        },
        "interpretation": {
            "allowed": (
                "Adding the Post-Eligibility Conservative Gate attenuates "
                "the observed propagation of authority-blind Action Memory eligibility "
                "changes in this dev audit."
            ),
            "boundary": (
                "Direct Eligibility is a mechanism probe, not a deployable consumer; "
                "the audit does not show online safety or universal gate protection."
            ),
        },
    }

    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    with OUT_CSV.open("w", encoding="utf-8", newline="") as handle:
        fields = [
            "evidence_policy",
            "consumer_mode",
            "sfw_numerator",
            "sfw_denominator",
            "saar_numerator",
            "saar_denominator",
            "review_numerator",
            "review_denominator",
            "route_changes_vs_authority_same_mode",
        ]
        writer = csv.DictWriter(handle, fieldnames=fields, lineterminator="\n")
        writer.writeheader()
        for row in table_rows:
            writer.writerow({
                "evidence_policy": row["evidence_policy"],
                "consumer_mode": row["consumer_mode"],
                "sfw_numerator": row["strict_failed_action_withholding"]["numerator"],
                "sfw_denominator": row["strict_failed_action_withholding"]["denominator"],
                "saar_numerator": row["supported_action_auto_retention"]["numerator"],
                "saar_denominator": row["supported_action_auto_retention"]["denominator"],
                "review_numerator": row["review_burden"]["numerator"],
                "review_denominator": row["review_burden"]["denominator"],
                "route_changes_vs_authority_same_mode": row[
                    "route_changes_vs_authority_same_mode"
                ],
            })

    funnel = payload["propagation_funnel"]
    direct = payload["paired_route_comparisons"]["direct_eligibility"]
    combined = payload["paired_route_comparisons"][
        "post_eligibility_conservative_gate"
    ]
    candidate_locked = payload["paired_route_comparisons"][
        "candidate_locked_governance_consumer"
    ]
    direct_transitions = {
        (row["from"], row["to"]): int(row["count"])
        for row in direct["transitions"]
    }
    combined_transitions = {
        (row["from"], row["to"]): int(row["count"])
        for row in combined["transitions"]
    }
    lines = [
        "# JSAC Evidence Authority Violation Propagation Audit（dev-only）",
        "",
        f"- 状态：retained exploratory mechanism audit；生成时间 `{payload['generated_at']}`。",
        "- 设计：ECHO Authority / Naive Broadcast × Direct Eligibility / Post-Eligibility Conservative Gate。",
        "- 数据：train 72,369；dev 3,247；holdout未加载。",
        f"- 回放代码快照：`{payload['integrity']['code_commit']}`（dirty={str(payload['integrity']['code_dirty']).lower()}）；readset/readiness/leakage全部通过。",
        "",
        "## 1. 2×2结果",
        "",
        "| Evidence policy | Consumer | SFW | SAAR | Review burden | Route changes vs Authority |",
        "|---|---|---:|---:|---:|---:|",
    ]
    for row in table_rows:
        sfw = row["strict_failed_action_withholding"]
        saar = row["supported_action_auto_retention"]
        review = row["review_burden"]
        lines.append(
            f"| {row['evidence_policy_label']} | {row['consumer_mode_label']} | "
            f"{sfw['numerator']}/{sfw['denominator']} ({pct(sfw)}) | "
            f"{saar['numerator']}/{saar['denominator']} ({pct(saar)}) | "
            f"{review['numerator']}/{review['denominator']} ({pct(review)}) | "
            f"{row['route_changes_vs_authority_same_mode']:,} |"
        )
    lines.extend([
        "",
        "Direct Eligibility严格按Lifecycle State→Use Eligibility映射处置，不读取Negative Memory、适用性veto或其他consumer-side保守检查；它不是生产策略。Post-Eligibility Conservative Gate在逐目标/逐给定Fail动作上把Direct Eligibility与冻结gate处置取较保守者，因而不能把Review/Reject重新释放为Auto。",
        "",
        "Table 4的Frozen Candidate-Locked Governance Consumer遵循另一冻结决策合同，不是上述单调组合，单列对账如下：",
        "",
        "| Evidence policy | Candidate-locked SFW | Candidate-locked SAAR | Candidate-locked Review | Route changes |",
        "|---|---:|---:|---:|---:|",
    ])
    for row in bridge_rows:
        sfw = row["strict_failed_action_withholding"]
        saar = row["supported_action_auto_retention"]
        review = row["review_burden"]
        lines.append(
            f"| {row['evidence_policy_label']} | {sfw['numerator']}/{sfw['denominator']} ({pct(sfw)}) | "
            f"{saar['numerator']}/{saar['denominator']} ({pct(saar)}) | "
            f"{review['numerator']}/{review['denominator']} ({pct(review)}) | "
            f"{row['route_changes_vs_authority_same_mode']:,} |"
        )
    lines.extend([
        "",
        "## 2. Violation propagation funnel",
        "",
        "```text",
        f"{funnel['unauthorized_action_direct_contributions']:,} unauthorized action-direct contributions",
        "        ↓",
        f"{funnel['polluted_action_memories']} / 599 Action Memories polluted",
        "        ↓",
        f"{funnel['lifecycle_state_changes']} / 599 Lifecycle States changed",
        "        ↓",
        f"{funnel['use_eligibility_flips_all_action_memories']} / 599 Use Eligibility boundaries crossed",
        "        ↓",
        f"{funnel['selected_action_memories_with_eligibility_flip']} / {funnel['unique_selected_action_memories']} selected Action Memories crossed eligibility",
        "        ↓",
        f"{funnel['dev_route_changes_direct_eligibility']} / 3,247 routes differ under Direct Eligibility",
        "        ↓",
        f"{funnel['dev_route_changes_post_eligibility_conservative_gate']} / 3,247 routes differ under Post-Eligibility Conservative Gate",
        "```",
        "",
        f"Direct Eligibility下Naive相对Authority有{direct['toward_auto']}条向Auto变化、{direct['away_from_auto']}条离开Auto，exact sign test `p={direct['paired_exact_sign_p']:.3g}`。变化目标结果构成为`{json.dumps(direct['changed_target_outcome_distribution'], ensure_ascii=False, sort_keys=True)}`。",
