        "| Consumer readout | Authority Auto→Naive Review | Authority Review→Naive Auto | Total changes |",
        "|---|---:|---:|---:|",
        f"| Direct Eligibility | {direct_transitions.get(('auto', 'review'), 0)} | {direct_transitions.get(('review', 'auto'), 0)} | {direct['changed_count']} |",
        f"| Post-Eligibility Conservative Gate | {combined_transitions.get(('auto', 'review'), 0)} | {combined_transitions.get(('review', 'auto'), 0)} | {combined['changed_count']} |",
