def read_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def read_jsonl(path: Path) -> list[dict[str, Any]]:
    return [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]


def write_json(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def write_jsonl(path: Path, rows: Iterable[dict[str, Any]]) -> dict[str, Any]:
    path.parent.mkdir(parents=True, exist_ok=True)
    count = 0
    with path.open("w", encoding="utf-8") as handle:
        for row in rows:
            handle.write(json.dumps(row, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n")
            count += 1
    return source_ref(path) | {"rows": count}


def source_ref(path: Path) -> dict[str, Any]:
    return {
        "path": str(path.relative_to(ROOT)),
        "size_bytes": path.stat().st_size,
        "sha256": sha256_path(path),
    }


def project_path(value: str) -> Path:
    path = Path(value)
    return path if path.is_absolute() else ROOT / path


def git_head() -> str | None:
    try:
        return subprocess.run(
            ["git", "rev-parse", "HEAD"],
            cwd=ROOT,
            check=True,
            capture_output=True,
            text=True,
        ).stdout.strip()
    except (OSError, subprocess.CalledProcessError):
        return None


def phase2_inputs(config: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any], Path]:
    phase2_summary_path = project_path(config["sources"]["phase2_summary"])
    phase2 = read_json(phase2_summary_path)
    phase2_config = read_json(PHASE2_CONFIG)
    train_path = project_path(config["sources"]["train_trace_records"])
    if any(token in str(train_path).lower() for token in ("dev", "holdout", "test")):
        raise ValueError(f"Phase 4 refuses non-train source: {train_path}")
    if phase2["sources"]["train_trace_records"]["sha256"] != sha256_path(train_path):
        raise ValueError("train source changed after Phase 2 freeze")
    if phase2["sources"]["config"]["sha256"] != sha256_path(PHASE2_CONFIG):
        raise ValueError("Phase 2 config changed after freeze")
    if config["dataset_role"] != "train_policy_development":
        raise ValueError("Phase 4 dry-run must remain train-policy-development")
    return phase2, phase2_config, train_path


def load_base_indexes(result_dir: Path) -> dict[str, dict[str, dict[str, Any]]]:
    indexes: dict[str, dict[str, dict[str, Any]]] = {}
    base = result_dir / "base"
    manifest = read_json(base / "manifest.json")
    for name, id_field in ARTIFACT_SPECS.items():
        rows = index_rows(cio.read_jsonl(base / f"{name}.jsonl"), id_field=id_field)
        actual = artifact_semantic_hash(hash_index(rows))
        expected = manifest["artifacts"][name]["semantic_hash"]
        if actual != expected:
            raise ValueError(f"base semantic hash mismatch: {name}")
        indexes[name] = rows
    actual_package = package_semantic_hash({
        name: artifact_semantic_hash(hash_index(rows)) for name, rows in indexes.items()
    })
    if actual_package != manifest["package_semantic_hash"]:
        raise ValueError("base package semantic hash mismatch")
    return indexes


def apply_version(
    indexes: dict[str, dict[str, dict[str, Any]]],
    version_dir: Path,
) -> dict[str, Any]:
    manifest = read_json(version_dir / "manifest.json")
    for name, id_field in ARTIFACT_SPECS.items():
        deletes = read_json(version_dir / f"{name}.deletes.json")["ids"]
        for row_id in deletes:
            indexes[name].pop(str(row_id), None)
        for row_id, row in index_rows(
            cio.read_jsonl(version_dir / f"{name}.upserts.jsonl"),
            id_field=id_field,
        ).items():
            indexes[name][row_id] = row
        actual = artifact_semantic_hash(hash_index(indexes[name]))
        if actual != manifest["artifacts"][name]["semantic_hash"]:
            raise ValueError(f"version semantic hash mismatch: {manifest['version_id']} {name}")
    package_hash = package_semantic_hash({
        name: artifact_semantic_hash(hash_index(rows)) for name, rows in indexes.items()
    })
    if package_hash != manifest["reconstructed_package_semantic_hash"]:
        raise ValueError(f"reconstructed package hash mismatch: {manifest['version_id']}")
    return manifest


def artifacts_view(indexes: dict[str, dict[str, dict[str, Any]]]) -> dict[str, Any]:
    return {
        "memories": list(indexes["memory_objects"].values()),
        "memory_evidence_profiles": list(indexes["memory_evidence_profiles"].values()),
        "support_routing_profiles": list(indexes["support_routing_profiles"].values()),
    }


def governance_by_memory(indexes: dict[str, dict[str, dict[str, Any]]]) -> dict[str, str]:
    profiles = {
        str(profile.get("parent_memory_id") or ""): profile
        for profile in indexes["memory_evidence_profiles"].values()
        if profile.get("parent_memory_id")
    }
    out: dict[str, str] = {}
    for memory_id, memory in indexes["memory_objects"].items():
        state = str(memory.get("state") or "draft")
        eligibility = {
            "validated": "Auto-eligible",
            "reusable": "Auto-eligible",
            "deprecated": "Ineligible",
        }.get(state, "Review-eligible")
        if memory_id in profiles and str(profiles[memory_id].get("profile_type") or "") == "counter_profile":
            eligibility = "Review-eligible"
        out[memory_id] = eligibility
    return out


def enrich_profile_action(action: dict[str, Any], ticket: dict[str, Any]) -> dict[str, Any]:
    out = dict(action)
    trace = {"ticket": ticket}
    pattern = _value_pattern(out, ticket)
    out.update({
        "parameter_semantic_id": _semantic_param_id(out, ticket),
        "value_type": pattern.get("value_type"),
        "direction": pattern.get("direction"),
        "delta_bucket": pattern.get("delta_bucket"),
        "value_pattern_id": pattern.get("pattern_id"),
        "value_shape": pattern.get("pattern_id"),
        "change": f"{out.get('before_value')}→{out.get('after_value')}",
    })
    del trace
    return out


def echo_auxiliary_risk(
    *,
    trace_id: str,
    bundle: dict[str, Any],
    artifacts: dict[str, Any],
    eligibility: dict[str, str],
) -> dict[str, Any]:
    ticket = bundle["ticket_context"]
    decision_trace = {"trace_id": trace_id, "ticket": ticket}
    action_rows: list[dict[str, Any]] = []
    for raw_action in bundle["proposed_plan_bundle"]:
        action = enrich_profile_action(raw_action, ticket)
        evidence = _candidate_strategy_evidence(
            action,
            decision_trace,
            artifacts["memories"],
            selection_policy="structural_relation_v1",
        )
        profile = _memory_evidence_profile_consumption(
            action,
            decision_trace,
            evidence,
            artifacts,
            policy=PROFILE_POLICY,
        )
        hits = profile.get("hits") if isinstance(profile.get("hits"), list) else []
        specific = [
            hit for hit in hits
            if hit.get("action_specific_match") or hit.get("matched_from") == "matched_child_profile"
        ]
        selected = specific or hits
        risk = max((float(hit.get("failure_lcb") or 0.0) for hit in selected), default=0.0)
        parent_ids = sorted({str(hit.get("parent_memory_id") or "") for hit in selected if hit.get("parent_memory_id")})
        action_rows.append({
            "risk": risk,
            "profile_hit_count": len(hits),
            "specific_hit_count": len(specific),
            "parent_memory_ids": parent_ids,
            "use_eligibility": sorted({eligibility.get(memory_id, "Unknown") for memory_id in parent_ids}),
        })
    parent_ids = sorted({memory_id for row in action_rows for memory_id in row["parent_memory_ids"]})
    return {
        "risk_score": max((row["risk"] for row in action_rows), default=0.0),
        "profile_hit_count": sum(row["profile_hit_count"] for row in action_rows),
        "specific_hit_count": sum(row["specific_hit_count"] for row in action_rows),
        "matched_parent_memory_ids": parent_ids,
        "use_eligibility": sorted({eligibility.get(memory_id, "Unknown") for memory_id in parent_ids}),
    }


def candidate_catalog(
    *,
    memories: list[dict[str, Any]],
    histories: list[dict[str, Any]],
    needed_ids: set[str],
) -> dict[str, dict[str, Any]]:
    cases = [memory for memory in memories if memory.get("memory_type") == "case_memory"]
    authority, _ = materialize_evidence_authority(histories)
    by_trace = {str(trace.get("trace_id") or ""): trace for trace in authority}
    actions = {
        (str(trace.get("trace_id") or ""), str(action.get("action_id") or "")): action
        for trace in authority
        for action in trace.get("actions") or []
        if isinstance(action, dict)
    }
    records, _, _ = precompute_cases(cases, by_trace, actions)
    out: dict[str, dict[str, Any]] = {}
    for record in sorted(records, key=lambda item: str(item.get("case_id") or "")):
        action_id = str(record.get("candidate_action_id") or "")
        if action_id in needed_ids and record.get("valid") and action_id not in out:
            out[action_id] = record["action"]
    missing = sorted(needed_ids - set(out))
    if missing:
        raise ValueError(f"candidate catalog unresolved IDs: {missing[:5]} ({len(missing)})")
    return out


def fit_base_ranker(base_histories: list[dict[str, Any]]) -> tuple[DictVectorizer, LogisticRegression, dict[str, Any]]:
    rows = []
    labels = []
    for trace in base_histories:
        if not primary_risk_eligible(trace):
            continue
        rows.append({"runtime_input": decision_bundle(trace)})
        labels.append(int(ticket_outcome(trace) == FAIL))
    vectorizer = DictVectorizer(sparse=True)
    matrix = vectorizer.fit_transform([ranker_features(row) for row in rows])
    model = LogisticRegression(
        solver="lbfgs",
        C=1.0,
        max_iter=500,
        class_weight=None,
        random_state=20260823,
    )
    model.fit(matrix, np.asarray(labels, dtype=int))
    return vectorizer, model, {
        "training_count": len(rows),
        "pass_count": len(rows) - sum(labels),
        "fail_count": sum(labels),
        "feature_count": len(vectorizer.feature_names_),
    }


def predict_ranker(
    vectorizer: DictVectorizer,
    model: LogisticRegression,
    bundles: dict[str, dict[str, Any]],
) -> dict[str, float]:
    trace_ids = sorted(bundles)
    matrix = vectorizer.transform([
        ranker_features({"runtime_input": bundles[trace_id]}) for trace_id in trace_ids
    ])
    probabilities = model.predict_proba(matrix)[:, 1]
    return {trace_id: float(probabilities[index]) for index, trace_id in enumerate(trace_ids)}


def raw_index_for_history(
    histories: list[dict[str, Any]],
    row_by_id: dict[str, dict[str, Any]],
) -> tuple[RawHistoryIndex, dict[str, Any]]:
    records = [
        make_raw_record(trace, visible_at=row_by_id[str(trace.get("trace_id") or "")]["visible_at"])
        for trace in histories
        if primary_risk_eligible(trace)
    ]
    return RawHistoryIndex(records), {
        "visible_history_count": len(histories),
        "raw_eligible_case_count": len(records),
        "raw_pass_case_count": sum(record.outcome == PASS for record in records),
        "raw_fail_case_count": sum(record.outcome == FAIL for record in records),
    }


def verify_no_target_label_fields(row: dict[str, Any]) -> None:
    forbidden = {
        "target_outcome",
        "target_long_eval",
        "gold_action",
        "candidate_hit",
        "primary_risk_eligible",
        "execution_class",
    }
    found: list[str] = []

    def walk(value: Any) -> None:
        if isinstance(value, dict):
            for key, item in value.items():
                if key in forbidden:
                    found.append(key)
                walk(item)
        elif isinstance(value, list):
            for item in value:
                walk(item)

    walk(row)
    if found:
        raise ValueError(f"decision row contains forbidden evaluator fields: {sorted(set(found))}")


def freeze_decisions(config_path: Path) -> dict[str, Any]:
    config = read_json(config_path)
    phase2, phase2_config, train_path = phase2_inputs(config)
    traces = list(cio.read_jsonl(train_path))
    trace_by_id = {str(trace.get("trace_id") or ""): trace for trace in traces}
    time_index = build_time_index(traces, phase2_config)
    if time_index["counts"]["policy_target_count"] != 11582:
        raise ValueError("unexpected Phase-4 target count")
    policy_ids = time_index["policy_target_ids"]
    bundles = {trace_id: decision_bundle(trace_by_id[trace_id]) for trace_id in policy_ids}
    window_by_trace = {
        trace_id: time_index["windows"][index]
        for index, ids in enumerate(time_index["targets_by_window"])
        for trace_id in ids
    }

    output_dir = project_path(config["outputs"]["result_dir"])
    output_dir.mkdir(parents=True, exist_ok=True)
    result_dir = project_path(config["sources"]["phase2_result_dir"])
    consumer_rows = read_jsonl(project_path(config["sources"]["phase2_consumer_reach"]))
    consumer_by_id = {str(row["trace_id"]): row for row in consumer_rows}
    if set(consumer_by_id) != set(policy_ids):
        raise ValueError("Phase-2 consumer target set differs from Phase 4")
    needed_static = {action_id for row in consumer_rows for action_id in row["static_candidate_action_ids"]}
    needed_adaptive: dict[str, set[str]] = defaultdict(set)
    for row in consumer_rows:
        needed_adaptive[str(row["adaptive_version_id"])].update(row["adaptive_candidate_action_ids"])

    base_ids = time_index["base_trace_ids"]
    base_histories = [trace_by_id[trace_id] for trace_id in base_ids]
    indexes = load_base_indexes(result_dir)
    static_artifacts = artifacts_view(indexes)
    static_eligibility = governance_by_memory(indexes)
    static_catalog = candidate_catalog(
        memories=static_artifacts["memories"],
        histories=base_histories,
        needed_ids=needed_static,
    )
    catalog_rows = [
        {"version_id": "P00_BASE", "candidate_action_id": action_id, "action": action}
        for action_id, action in sorted(static_catalog.items())
    ]

    print(f"fitting frozen base risk ranker on {len(base_histories):,} visible histories", flush=True)
    vectorizer, model, model_summary = fit_base_ranker(base_histories)
    model_path = output_dir / "frozen_no_memory_risk_ranker.joblib"
    joblib.dump({"vectorizer": vectorizer, "model": model}, model_path, compress=3)
    ranker_scores = predict_ranker(vectorizer, model, bundles)

    print(f"scoring ECHO-Static for {len(policy_ids):,} target bundles", flush=True)
    static_started = time.perf_counter()
    static_aux: dict[str, dict[str, Any]] = {}
    for index, trace_id in enumerate(policy_ids, start=1):
        static_aux[trace_id] = echo_auxiliary_risk(
            trace_id=trace_id,
            bundle=bundles[trace_id],
            artifacts=static_artifacts,
            eligibility=static_eligibility,
        )
        if index % 1000 == 0:
            print(f"  static ECHO scored {index:,}/{len(policy_ids):,}", flush=True)
    static_seconds = time.perf_counter() - static_started

    decisions: dict[str, dict[str, Any]] = {}
    window_freezes: list[dict[str, Any]] = []
    phase2_core_ids = set(base_ids)
    version_dirs = sorted((result_dir / "versions").iterdir())
    for version_dir in version_dirs:
        manifest = apply_version(indexes, version_dir)
        version_id = str(manifest["version_id"])
        core_rows = read_jsonl(version_dir / "core_delta.jsonl")
        phase2_core_ids.update(str(row["trace_id"]) for row in core_rows)
        window_ids = sorted(
            trace_id for trace_id in policy_ids
            if str(consumer_by_id[trace_id]["adaptive_version_id"]) == version_id
        )
        if not window_ids:
            continue
        boundary = str(manifest["evidence_cutoff"])
        visible_ids = {
            row["trace_id"]
            for row in time_index["valid_rows"]
            if row["visible_at_dt"].isoformat() < boundary
        }
        if visible_ids != phase2_core_ids:
            raise ValueError(f"Raw/ECHO visible history IDs differ at {version_id}")
        histories = [trace_by_id[trace_id] for trace_id in sorted(visible_ids)]
        version_same_as_base = (
            manifest["reconstructed_package_semantic_hash"]
            == phase2["base"]["package_semantic_hash"]
        )
        if version_same_as_base:
            adaptive_aux = {trace_id: static_aux[trace_id] for trace_id in window_ids}
            adaptive_catalog = {
                action_id: static_catalog[action_id]
                for action_id in needed_adaptive[version_id]
            }
            adaptive_seconds = 0.0
        else:
            adaptive_artifacts = artifacts_view(indexes)
            adaptive_eligibility = governance_by_memory(indexes)
            adaptive_started = time.perf_counter()
            adaptive_aux = {
                trace_id: echo_auxiliary_risk(
                    trace_id=trace_id,
                    bundle=bundles[trace_id],
                    artifacts=adaptive_artifacts,
                    eligibility=adaptive_eligibility,
                )
                for trace_id in window_ids
            }
            adaptive_seconds = time.perf_counter() - adaptive_started
            adaptive_catalog = candidate_catalog(
                memories=adaptive_artifacts["memories"],
                histories=histories,
                needed_ids=needed_adaptive[version_id],
            )
            del adaptive_artifacts, adaptive_eligibility
        catalog_rows.extend(
            {"version_id": version_id, "candidate_action_id": action_id, "action": action}
            for action_id, action in sorted(adaptive_catalog.items())
        )

        raw_started = time.perf_counter()
        raw_index, raw_manifest = raw_index_for_history(histories, time_index["row_by_id"])
        raw_config = config["methods"]["raw_history_adaptive"]
        raw_aux = {
            trace_id: raw_index.query(
                bundles[trace_id],
                m=int(raw_config["m"]),
                max_candidate_scan=int(raw_config["max_candidate_scan"]),
            )
            for trace_id in window_ids
        }
        raw_seconds = time.perf_counter() - raw_started
        base_scores = {trace_id: ranker_scores[trace_id] for trace_id in window_ids}
        base_weight = float(config["fusion"]["base_ranker_weight"])
        echo_static_scores = fuse_scores(
            base_scores,
            {trace_id: static_aux[trace_id]["risk_score"] for trace_id in window_ids},
            base_weight=base_weight,
        )
        echo_adaptive_scores = fuse_scores(
            base_scores,
            {trace_id: adaptive_aux[trace_id]["risk_score"] for trace_id in window_ids},
            base_weight=base_weight,
        )
        raw_scores = fuse_scores(
            base_scores,
            {trace_id: raw_aux[trace_id]["risk_score"] for trace_id in window_ids},
            base_weight=base_weight,
        )
        for trace_id in window_ids:
            consumer = consumer_by_id[trace_id]
            row = {
                "trace_id": trace_id,
                "window_id": str(consumer["window_id"]),
                "adaptive_version_id": version_id,
                "bundle_hash": bundles[trace_id]["bundle_hash"],
                "action_count": bundles[trace_id]["action_count"],
                "scores": {
                    "frozen_no_memory_risk_ranker": base_scores[trace_id],
                    "echo_static": echo_static_scores[trace_id],
                    "echo_adaptive": echo_adaptive_scores[trace_id],
                    "raw_history_adaptive": raw_scores[trace_id],
                },
                "echo_static_view": static_aux[trace_id],
                "echo_adaptive_view": adaptive_aux[trace_id],
                "raw_history_view": raw_aux[trace_id],
                "candidate_action_ids": {
                    "static": consumer["static_candidate_action_ids"],
                    "adaptive": consumer["adaptive_candidate_action_ids"],
                },
                "consumer_change": {
                    "candidate_order_changed": bool(consumer["candidate_order_changed"]),
                    "candidate_set_changed": bool(consumer["candidate_set_changed"]),
                    "feedback_changed": bool(consumer["feedback_changed"]),
                    "risk_score_changed": abs(echo_adaptive_scores[trace_id] - echo_static_scores[trace_id]) > 1e-15,
                },
            }
            verify_no_target_label_fields(row)
            decisions[trace_id] = row
        window = window_by_trace[window_ids[0]]
        window_freezes.append({
            "window_id": window["window_id"],
            "window_start": window["start"],
            "window_end": window["end"],
            "role": window["role"],
            "target_count": len(window_ids),
            "adaptive_version_id": version_id,
            "visible_history_count": len(visible_ids),
            "visible_history_id_sha256": hashlib.sha256("\n".join(sorted(visible_ids)).encode()).hexdigest(),
            "phase2_package_semantic_hash": manifest["reconstructed_package_semantic_hash"],
            "phase2_semantic_equivalence": bool(manifest["semantic_equivalence"]),
            "raw_history": raw_manifest,
            "scoring_seconds": {
                "echo_adaptive": adaptive_seconds,
                "raw_history_index_and_queries": raw_seconds,
            },
        })
        print(
            f"froze {window['window_id']} {version_id}: targets={len(window_ids):,} "
            f"history={len(visible_ids):,} raw_cases={raw_manifest['raw_eligible_case_count']:,}",
            flush=True,
        )
        del raw_index, raw_aux, adaptive_aux, adaptive_catalog
        gc.collect()
        if len(decisions) == len(policy_ids):
            break

    if set(decisions) != set(policy_ids):
        raise ValueError("not all policy targets received frozen decisions")
    decision_path = output_dir / "frozen_decisions.jsonl"
    decision_ref = write_jsonl(decision_path, (decisions[trace_id] for trace_id in sorted(decisions)))
    catalog_path = output_dir / "candidate_action_catalog.jsonl"
    catalog_ref = write_jsonl(catalog_path, catalog_rows)
    window_path = output_dir / "window_freeze.json"
    write_json(window_path, {"windows": window_freezes})
    manifest = {
        "schema_version": "jsac.phase4_layer2_decision_freeze.v1",
        "status": "all_train_policy_development_decisions_frozen_before_target_label_reveal",
        "protocol": source_ref(config_path),
        "git_head": git_head(),
        "sources": {
            "train_trace_records": source_ref(train_path),
            "phase2_summary": source_ref(project_path(config["sources"]["phase2_summary"])),
            "phase2_consumer_reach": source_ref(project_path(config["sources"]["phase2_consumer_reach"])),
        },
        "target_count": len(decisions),
        "window_count": len(window_freezes),
        "frozen_no_memory_ranker": source_ref(model_path) | model_summary,
        "artifacts": {
            "decisions": decision_ref,
            "candidate_action_catalog": catalog_ref,
            "window_freeze": source_ref(window_path),
        },
        "cost": {
            "echo_static_scoring_seconds": static_seconds,
            "window_scoring_seconds": {
                row["window_id"]: row["scoring_seconds"] for row in window_freezes
            },
        },
        "checks": {
            "all_11582_targets_frozen": len(decisions) == 11582,
            "target_outcome_or_gold_in_decision_rows": False,
            "raw_echo_visible_history_ids_identical": True,
            "phase2_semantic_hashes_verified": True,
            "replay_a_b_read": False,
            "gold_read_for_target_ranking": False,
        },
        "next_gate": "Evaluator may read target execution/outcome and Phase-1 gold actions only after re-verifying every frozen artifact hash.",
    }
    manifest_path = output_dir / "decision_freeze_manifest.json"
    write_json(manifest_path, manifest)
    print(json.dumps({
        "manifest": str(manifest_path.relative_to(ROOT)),
        "target_count": len(decisions),
        "windows": len(window_freezes),
        "gold_read": False,
    }, ensure_ascii=False, indent=2))
    return manifest


def verify_freeze_manifest(manifest_path: Path) -> dict[str, Any]:
    manifest = read_json(manifest_path)
    if manifest.get("status") != "all_train_policy_development_decisions_frozen_before_target_label_reveal":
        raise ValueError("Phase-4 decision freeze gate is not closed")
    checks = manifest.get("checks") or {}
    if checks.get("target_outcome_or_gold_in_decision_rows") is not False:
        raise ValueError("decision manifest does not prove target-label isolation")
    if checks.get("replay_a_b_read") is not False:
        raise ValueError("decision manifest indicates Replay access")
    for ref in (manifest.get("artifacts") or {}).values():
        path = ROOT / ref["path"]
        if path.stat().st_size != ref["size_bytes"] or sha256_path(path) != ref["sha256"]:
            raise ValueError(f"frozen artifact changed: {path}")
    return manifest


def action_hit(action: dict[str, Any], gold: list[dict[str, Any]], ticket: dict[str, Any]) -> bool:
    result = best_action_equivalence(action, gold, ticket=ticket)
    return str((result or {}).get("level") or "unverifiable") in {
        "strongly_verifiable",
        "weakly_verifiable",
    }


def aggregate_action_readout(rows: list[dict[str, Any]]) -> dict[str, Any]:
    out: dict[str, Any] = {}
    for cohort in ("strict_single", "multi_bundle"):
        subset = [row for row in rows if row["cohort"] == cohort]
        methods: dict[str, Any] = {}
        for method in ("static", "adaptive"):
            n1 = sum(row[f"{method}_hit_at_1"] for row in subset)
            n3 = sum(row[f"{method}_hit_at_3"] for row in subset)
            methods[method] = {
                "target_count": len(subset),
                "at_1": {"hits": n1, "rate": n1 / len(subset) if subset else None},
                "at_3": {"hits": n3, "rate": n3 / len(subset) if subset else None},
            }
        out[cohort] = methods
    return out


def evaluate(config_path: Path) -> dict[str, Any]:
    config = read_json(config_path)
    output_dir = project_path(config["outputs"]["result_dir"])
    freeze_manifest_path = output_dir / "decision_freeze_manifest.json"
    freeze_manifest = verify_freeze_manifest(freeze_manifest_path)
    decisions = read_jsonl(ROOT / freeze_manifest["artifacts"]["decisions"]["path"])
    decision_by_id = {str(row["trace_id"]): row for row in decisions}
    catalog_rows = read_jsonl(ROOT / freeze_manifest["artifacts"]["candidate_action_catalog"]["path"])
    catalog = {
        (str(row["version_id"]), str(row["candidate_action_id"])): row["action"]
        for row in catalog_rows
    }

    _, phase2_config, train_path = phase2_inputs(config)
    traces = list(cio.read_jsonl(train_path))
    trace_by_id = {str(trace.get("trace_id") or ""): trace for trace in traces}
    time_index = build_time_index(traces, phase2_config)
    if set(decision_by_id) != set(time_index["policy_target_ids"]):
        raise ValueError("frozen decision target set changed before reveal")

    # Target execution/outcome is read only after the complete freeze verification above.
    labels = {
        trace_id: {
            "execution_class": execution_class(trace_by_id[trace_id]),
            "target_outcome": ticket_outcome(trace_by_id[trace_id]),
            "primary_risk_eligible": primary_risk_eligible(trace_by_id[trace_id]),
        }
        for trace_id in decision_by_id
    }
    exclusion_counts = Counter()
    for label in labels.values():
        if not label["primary_risk_eligible"]:
            exclusion_counts[f"execution::{label['execution_class']}"] += 1
            exclusion_counts[f"outcome::{label['target_outcome']}"] += 1

    methods = (
        "frozen_no_memory_risk_ranker",
        "echo_static",
        "echo_adaptive",
        "raw_history_adaptive",
    )
    budgets = [float(value) for value in config["review"]["budgets"]]
    window_results: list[dict[str, Any]] = []
    per_target: dict[str, dict[str, Any]] = {}
    aggregate_outcomes: dict[str, str] = {}
    aggregate_selected: dict[str, dict[float, set[str]]] = {
        method: {budget: set() for budget in budgets} for method in methods
    }
    for window in sorted({row["window_id"] for row in decisions}):
        ids = sorted(
            row["trace_id"]
            for row in decisions
            if row["window_id"] == window and labels[row["trace_id"]]["primary_risk_eligible"]
        )
        outcomes = {trace_id: labels[trace_id]["target_outcome"] for trace_id in ids}
        aggregate_outcomes.update(outcomes)
        points: dict[str, dict[str, Any]] = {method: {} for method in methods}
        selections: dict[str, dict[float, set[str]]] = {method: {} for method in methods}
        for method in methods:
            scores = {trace_id: float(decision_by_id[trace_id]["scores"][method]) for trace_id in ids}
            for budget in budgets:
                point = operating_point(scores=scores, outcomes=outcomes, budget=budget)
                selected = set(point.pop("selected_ids"))
                selections[method][budget] = selected
                aggregate_selected[method][budget].update(selected)
                points[method][str(budget)] = point
        contrasts = {
            "echo_adaptive_minus_echo_static": {
                str(budget): paired_review_contrast(
                    left_selected=selections["echo_adaptive"][budget],
                    right_selected=selections["echo_static"][budget],
                    outcomes=outcomes,
                )
                for budget in budgets
            },
            "echo_adaptive_minus_raw_history": {
                str(budget): paired_review_contrast(
                    left_selected=selections["echo_adaptive"][budget],
                    right_selected=selections["raw_history_adaptive"][budget],
                    outcomes=outcomes,
                )
                for budget in budgets
            },
        }
        window_results.append({
            "window_id": window,
            "target_count": len(ids),
            "pass_count": sum(value == PASS for value in outcomes.values()),
            "fail_count": sum(value == FAIL for value in outcomes.values()),
            "methods": points,
            "paired_contrasts": contrasts,
        })
        for trace_id in ids:
            row = decision_by_id[trace_id]
            per_target[trace_id] = {
                "trace_id": trace_id,
                "window_id": window,
                "target_outcome": outcomes[trace_id],
                "scores": row["scores"],
                "review": {
                    method: {
                        str(budget): trace_id in selections[method][budget] for budget in budgets
                    }
                    for method in methods
                },
                "consumer_change": row["consumer_change"],
            }

    aggregate_methods: dict[str, Any] = {}
    for method in methods:
        aggregate_methods[method] = {}
        for budget in budgets:
            selected = aggregate_selected[method][budget]
            fail_total = sum(value == FAIL for value in aggregate_outcomes.values())
            pass_total = sum(value == PASS for value in aggregate_outcomes.values())
            reviewed_fail = sum(aggregate_outcomes[trace_id] == FAIL for trace_id in selected)
            reviewed_pass = len(selected) - reviewed_fail
            aggregate_methods[method][str(budget)] = {
                "target_count": len(aggregate_outcomes),
                "review_count": len(selected),
                "historical_failure_capture": {
                    "numerator": reviewed_fail,
                    "denominator": fail_total,
                    "value": reviewed_fail / fail_total,
                },
                "review_yield": {
                    "numerator": reviewed_fail,
                    "denominator": len(selected),
                    "value": reviewed_fail / len(selected),
                },
                "pass_to_review": {
                    "numerator": reviewed_pass,
                    "denominator": pass_total,
                    "value": reviewed_pass / pass_total,
                },
                "review_set_hash": hashlib.sha256("\n".join(sorted(selected)).encode()).hexdigest(),
            }
    aggregate_contrasts = {
        contrast: {
            str(budget): paired_review_contrast(
                left_selected=aggregate_selected["echo_adaptive"][budget],
                right_selected=aggregate_selected[right][budget],
                outcomes=aggregate_outcomes,
            )
            for budget in budgets
        }
        for contrast, right in (
            ("echo_adaptive_minus_echo_static", "echo_static"),
            ("echo_adaptive_minus_raw_history", "raw_history_adaptive"),
        )
    }

    phase1_target_rows = read_jsonl(project_path(config["sources"]["phase1_target_audit"]))
    phase1_target_ids = {str(row["trace_id"]) for row in phase1_target_rows}
    policy_traces = [trace_by_id[trace_id] for trace_id in time_index["policy_target_ids"]]
    targets, _ = build_targets(policy_traces)
    if {str(target["trace"].get("trace_id") or "") for target in targets} != phase1_target_ids:
        raise ValueError("Phase-1 Pass target manifest changed")
    action_rows: list[dict[str, Any]] = []
    for target in targets:
        trace = target["trace"]
        trace_id = str(trace.get("trace_id") or "")
        decision = decision_by_id[trace_id]
        version_id = str(decision["adaptive_version_id"])
        static_ids = decision["candidate_action_ids"]["static"]
        adaptive_ids = decision["candidate_action_ids"]["adaptive"]
        static_actions = [catalog[("P00_BASE", action_id)] for action_id in static_ids]
        adaptive_actions = [catalog[(version_id, action_id)] for action_id in adaptive_ids]
        static_hits = [action_hit(action, target["gold_actions"], trace.get("ticket") or {}) for action in static_actions]
        adaptive_hits = [action_hit(action, target["gold_actions"], trace.get("ticket") or {}) for action in adaptive_actions]
        action_rows.append({
            "trace_id": trace_id,
            "window_id": decision["window_id"],
            "cohort": target["cohort"],
            "static_hit_at_1": any(static_hits[:1]),
            "static_hit_at_3": any(static_hits[:3]),
            "adaptive_hit_at_1": any(adaptive_hits[:1]),
            "adaptive_hit_at_3": any(adaptive_hits[:3]),
        })
    action_readout = aggregate_action_readout(action_rows)

    risk_reach = {
        "primary_target_count": len(per_target),
        "echo_risk_score_changed": sum(
            row["consumer_change"]["risk_score_changed"] for row in per_target.values()
        ),
        "review_disposition_changed": {
            str(budget): sum(
                row["review"]["echo_adaptive"][str(budget)]
                != row["review"]["echo_static"][str(budget)]
                for row in per_target.values()
            )
            for budget in budgets
        },
    }
    gate_assessment = {
        "phase4_integrity_gate": "passed",
        "layer2_utility_gate": "not_passed",
        "jsac_overall_gate": "no_go_return_to_tnsm_baseline",
        "primary_endpoint": "echo_adaptive_minus_echo_static_hfc_at_10_percent_review",
        "primary_result": aggregate_contrasts["echo_adaptive_minus_echo_static"]["0.1"],
        "raw_history_check": aggregate_contrasts["echo_adaptive_minus_raw_history"]["0.1"],
        "reason": (
            "The required positive Adaptive-minus-Static direction is absent at the primary "
            "10% review endpoint and Raw-History Adaptive captures more failures than ECHO-Adaptive."
        ),
        "next_action": "Do not start Replay-A/B under this JSAC protocol; preserve the TNSM baseline.",
    }
    per_target_path = output_dir / "phase4_per_target_results.jsonl"
    per_target_ref = write_jsonl(per_target_path, (per_target[trace_id] for trace_id in sorted(per_target)))
    action_path = output_dir / "phase4_action_readout_results.jsonl"
    action_ref = write_jsonl(action_path, action_rows)
    result = {
        "schema_version": "jsac.phase4_layer2_dev_dry_run_result.v1",
        "status": "complete_train_policy_development_layer2_dry_run",
        "decision_freeze": source_ref(freeze_manifest_path),
        "gold_reveal_gate": {
            "all_frozen_artifact_hashes_verified_before_target_label_read": True,
            "target_outcome_revealed_after_decision_freeze": True,
            "replay_a_b_read": False,
        },
        "population": {
            "all_scored_before_reveal": len(decisions),
            "primary_risk_eligible": len(per_target),
            "pass_count": sum(value == PASS for value in aggregate_outcomes.values()),
            "fail_count": sum(value == FAIL for value in aggregate_outcomes.values()),
            "excluded_counts": dict(sorted(exclusion_counts.items())),
        },
        "window_results": window_results,
        "aggregate_results": aggregate_methods,
        "paired_contrasts": aggregate_contrasts,
        "risk_review_disposition_reach": risk_reach,
        "action_readout": action_readout,
        "gate_assessment": gate_assessment,
        "measured_cost": freeze_manifest["cost"],
        "artifacts": {
            "per_target": per_target_ref,
            "action_readout_per_target": action_ref,
        },
        "claim_boundary": "Train-policy-development retrospective plan-risk and historical-action recovery only. HFC/Review Yield do not establish causal safety or online KPI value; action-prefix gains are fixed rank-order diagnostics after the Layer-1 Agent gate did not pass.",
    }
    result_path = output_dir / "phase4_layer2_results.json"
    write_json(result_path, result)
    retained = {
        "schema_version": "jsac.phase4_layer2_dev_dry_run_retained.v1",
        "date": "2026-08-23",
        "status": result["status"],
        "protocol": source_ref(config_path),
        "source_result": source_ref(result_path),
        "decision_freeze": source_ref(freeze_manifest_path),
        "population": result["population"],
        "window_results": window_results,
        "aggregate_results": aggregate_methods,
        "paired_contrasts": aggregate_contrasts,
        "risk_review_disposition_reach": risk_reach,
        "action_readout": action_readout,
        "gate_assessment": gate_assessment,
        "measured_cost": freeze_manifest["cost"],
        "artifacts": result["artifacts"],
        "claim_boundary": result["claim_boundary"],
    }
    retained_path = project_path(config["outputs"]["retained_summary"])
    write_json(retained_path, retained)
    report_path = project_path(config["outputs"]["report"])
    report_path.parent.mkdir(parents=True, exist_ok=True)
    report_path.write_text(report_markdown(retained), encoding="utf-8")
    print(json.dumps({
        "result": str(result_path.relative_to(ROOT)),
        "retained": str(retained_path.relative_to(ROOT)),
        "population": result["population"],
        "paired_contrasts": aggregate_contrasts,
    }, ensure_ascii=False, indent=2))
    return retained


def percent(value: float | None) -> str:
    return "N/A" if value is None else f"{100.0 * value:.2f}%"


def report_markdown(retained: dict[str, Any]) -> str:
    lines = [
        "# JSAC Phase 4 Layer-2 Train-Policy-Development Dry-Run",
        "",
        "> Status: complete deterministic weekly dry-run; Replay-A/B not read.",
        "",
        "## Population and reveal gate",
        "",
        f"All {retained['population']['all_scored_before_reveal']:,} policy-development targets were scored and frozen before target execution/outcome reveal. The labeled complete-bundle audit contains {retained['population']['primary_risk_eligible']:,} targets: {retained['population']['pass_count']:,} Pass and {retained['population']['fail_count']:,} Fail.",
        "",
        "## Aggregate fixed-review results",
        "",
        "| Method | HFC@10% | Review Yield@10% | HFC@20% | Review Yield@20% |",
        "|---|---:|---:|---:|---:|",
    ]
    labels = {
        "frozen_no_memory_risk_ranker": "Frozen No-Memory Risk Ranker",
        "echo_static": "ECHO-Static",
        "echo_adaptive": "ECHO-Adaptive",
        "raw_history_adaptive": "Raw-History Adaptive",
    }
    for method, label in labels.items():
        r10 = retained["aggregate_results"][method]["0.1"]
        r20 = retained["aggregate_results"][method]["0.2"]
        lines.append(
            f"| {label} | {percent(r10['historical_failure_capture']['value'])} | {percent(r10['review_yield']['value'])} | {percent(r20['historical_failure_capture']['value'])} | {percent(r20['review_yield']['value'])} |"
        )
    lines.extend(["", "## Same-window adaptive contrasts", ""])
    for contrast, rows in retained["paired_contrasts"].items():
        for budget, row in rows.items():
            lines.append(
                f"- `{contrast}` at {float(budget):.0%}: net additional captured Fail={row['net_additional_captured_fail']:+d}, HFC difference={percent(row['hfc_difference'])}, Review-set symmetric difference={row['review_set_symmetric_difference']:,}."
            )
    lines.extend([
        "",
        "### Per-window ECHO Adaptive minus Static",
        "",
        "| Window | Eligible | Fail | Net Fail@10% | Queue Δ@10% | Net Fail@20% | Queue Δ@20% |",
        "|---|---:|---:|---:|---:|---:|---:|",
    ])
    for window in retained["window_results"]:
        contrasts = window["paired_contrasts"]["echo_adaptive_minus_echo_static"]
        lines.append(
            f"| {window['window_id']} | {window['target_count']:,} | {window['fail_count']:,} | "
            f"{contrasts['0.1']['net_additional_captured_fail']:+d} | "
            f"{contrasts['0.1']['review_set_symmetric_difference']:,} | "
            f"{contrasts['0.2']['net_additional_captured_fail']:+d} | "
            f"{contrasts['0.2']['review_set_symmetric_difference']:,} |"
        )
    lines.extend([
        "",
        "## Consumer reach and action readout",
        "",
        f"- ECHO risk score changed on {retained['risk_review_disposition_reach']['echo_risk_score_changed']:,}/{retained['risk_review_disposition_reach']['primary_target_count']:,} labeled targets.",
        f"- ECHO Adaptive versus Static disposition changed on {retained['risk_review_disposition_reach']['review_disposition_changed']['0.1']:,} targets at 10% and {retained['risk_review_disposition_reach']['review_disposition_changed']['0.2']:,} at 20% Review.",
    ])
    for cohort, methods in retained["action_readout"].items():
        lines.append(
            f"- {cohort}: Static@1/@3={percent(methods['static']['at_1']['rate'])}/{percent(methods['static']['at_3']['rate'])}; Adaptive@1/@3={percent(methods['adaptive']['at_1']['rate'])}/{percent(methods['adaptive']['at_3']['rate'])}."
        )
    adaptive_seconds = sum(
        row["echo_adaptive"]
        for row in retained["measured_cost"]["window_scoring_seconds"].values()
    )
    raw_seconds = sum(
        row["raw_history_index_and_queries"]
        for row in retained["measured_cost"]["window_scoring_seconds"].values()
    )
    lines.extend([
        "",
        "## Measured deterministic scoring cost",
        "",
        f"- ECHO-Static auxiliary scoring: {retained['measured_cost']['echo_static_scoring_seconds']:.2f} s.",
        f"- ECHO-Adaptive auxiliary scoring across eight windows: {adaptive_seconds:.2f} s.",
        f"- Raw-History index construction and M=4 queries across eight windows: {raw_seconds:.2f} s.",
        "- These are host-side measured components, not end-to-end deployment latency.",
        "",
        "## Gate decision",
        "",
        "- Phase-4 integrity gate: **passed**.",
        "- Layer-2 utility gate: **not passed**.",
        "- JSAC protocol decision: **No-Go / return to the preserved TNSM baseline**; do not start Replay-A/B.",
        "- Reason: the primary Adaptive-minus-Static HFC direction is negative, and Raw-History Adaptive explains more than the observed ECHO result.",
    ])
    lines.extend([
        "",
        "## Claim boundary",
        "",
        retained["claim_boundary"],
        "",
    ])
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser()
