def read_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def read_jsonl(path: Path) -> list[dict[str, Any]]:
    rows = []
    with path.open(encoding="utf-8") as handle:
        for line in handle:
            if line.strip():
                rows.append(json.loads(line))
    return rows


def ratio(numerator: int, denominator: int) -> dict[str, Any]:
    value = numerator / denominator if denominator else None
    return {
        "numerator": numerator,
        "denominator": denominator,
        "rate": value,
        "value": value,
    }


def metric_bundle(run_dir: Path, method_id: str) -> dict[str, Any]:
    positive, _ = audit(run_dir, method_id)
    negative, _ = strict_given_negative_audit(run_dir)
    metrics = positive["positive_metrics"]
    strict_pass = metrics["attribution_safe_top1_support_direct_only"]
    auto_pass = metrics["attribution_safe_auto_support_direct_only"]
    return {
        "strict_single_action_pass_support": strict_pass,
        "multi_action_pass_component_match": metrics[
            "multi_action_successful_bundle_component_match"
        ],
        "strict_failed_action_withholding": negative[
            "strict_given_failed_action_withholding"
        ],
        "supported_action_auto_retention": ratio(
            int(auto_pass["numerator"]),
            int(strict_pass["numerator"]),
        ),
        "native_candidate_review_rate": positive["operating_burden"][
            "review_or_reject_rate"
        ],
        "integrity": {
            "positive_contract": bool(positive["integrity"]["all_passed"]),
            "strict_negative_contract": bool(negative["integrity"]["all_passed"]),
        },
    }


def candidate_identity(
    run_dir: Path,
    method_id: str,
) -> tuple[str, dict[str, str]]:
    rows_by_method, source_meta, _ = load_run_samples(run_dir)
    if source_meta.get("dataset_role") != "dev":
        raise ValueError(f"non-dev run: {run_dir}")
    rows = rows_by_method[method_id]
    identities: dict[str, str] = {}
    sequence = []
    for row in rows:
        actions = (
            row.get("recommended_actions")
            if isinstance(row.get("recommended_actions"), list)
            else []
        )
        identity = [
            {
                key: action.get(key)
                for key in (
                    "scheme_id",
                    "parameter_semantic_id",
                    "direction",
                    "before_value",
                    "after_value",
                )
            }
            for action in actions
        ]
        trace_id = str(row.get("trace_id") or "")
        encoded = json.dumps(
            identity,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
        identities[trace_id] = encoded
        sequence.append({"trace_id": trace_id, "actions": identity})
    digest = hashlib.sha256(
        json.dumps(
            sequence,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ).encode()
    ).hexdigest()
    return digest, identities


def selection_readset_audit(
    run_dir: Path,
    method_id: str,
    *,
    relation_read: bool,
) -> dict[str, Any]:
    rows = [
        row
        for row in read_jsonl(run_dir / "samples.jsonl")
        if row.get("method_id") == method_id
    ]
    violations = Counter()
    evidence_count = 0
    expected_policy = (
        "structural_relation_v1" if relation_read else "structural_identity_v1"
    )
    expected_tie = (
        "equal_rank_component_of_bundle_count_then_"
        "source_trace_count_then_case_id_v1"
        if relation_read
        else "equal_rank_memory_id_v1"
    )
    for row in rows:
        decision = (
            row.get("decision")
            if isinstance(row.get("decision"), dict)
            else {}
        )
        rank = (
            decision.get("selected_score_breakdown")
            if isinstance(decision.get("selected_score_breakdown"), dict)
            else {}
        )
        weights = rank.get("weights") if isinstance(rank.get("weights"), dict) else {}
        if rank.get("strategy_evidence_selection_policy") != expected_policy:
            violations["selection_policy"] += 1
        if float(rank.get("case_outcome_pass_rate") or 0.0) != 0.0:
            violations["case_outcome_nonzero"] += 1
        for key in (
            "strategy_lcb",
            "strategy_pass_rate",
            "strategy_support",
            "related_case",
            "memory_state",
        ):
            if float(weights.get(key) or 0.0) != 0.0:
                violations[f"weight:{key}"] += 1
        tie = (
            rank.get("structural_relation_tie_break")
            if isinstance(rank.get("structural_relation_tie_break"), dict)
            else {}
        )
        if tie.get("policy") != expected_tie:
            violations["tie_policy"] += 1
        if not relation_read and (
            int(tie.get("component_of_bundle_count") or 0) != 0
            or int(tie.get("source_trace_count") or 0) != 0
        ):
            violations["identity_tie_relation_nonzero"] += 1
        for item in rank.get("strategy_evidence") or []:
            if not isinstance(item, dict):
                continue
            evidence_count += 1
            if any(
                float(item.get(key) or 0.0) != 0.0
                for key in ("support_count", "pass_rate", "lcb", "state_term")
            ):
                violations["strategy_result_field_nonzero"] += 1
            if item.get("state") not in {None, ""}:
                violations["strategy_state_visible"] += 1
            structural = (
                item.get("structural_match")
                if isinstance(item.get("structural_match"), dict)
                else {}
            )
            if not relation_read and (
                bool(structural.get("component_of_relation_available"))
                or int(structural.get("component_of_bundle_count") or 0) != 0
                or int(structural.get("component_of_playbook_count") or 0) != 0
                or int(structural.get("source_trace_count") or 0) != 0
            ):
                violations["identity_evidence_relation_nonzero"] += 1
    return {
        "trace_count": len(rows),
        "strategy_evidence_count": evidence_count,
        "expected_selection_policy": expected_policy,
        "expected_tie_policy": expected_tie,
        "violations": dict(violations),
        "all_passed": not violations,
    }


def package_structural_audit(
    construction: dict[str, dict[str, Any]],
) -> dict[str, Any]:
    full_dir = ROOT / construction["C8_full"]["package_path"]
    off_dir = ROOT / construction["C8_minus_structural_action_memory"][
        "package_path"
    ]
    full = read_jsonl(full_dir / "memory_objects.jsonl")
    off = read_jsonl(off_dir / "memory_objects.jsonl")
    full_by_id = {str(row.get("memory_id")): row for row in full}
    off_by_id = {str(row.get("memory_id")): row for row in off}
    removed_ids = set(full_by_id) - set(off_by_id)
    added_ids = set(off_by_id) - set(full_by_id)

    def strategy_roles(rows: list[dict[str, Any]]) -> Counter[str]:
        return Counter(
            str((row.get("content") or {}).get("action_memory_role") or "missing")
            for row in rows
            if row.get("memory_type") == "strategy_memory"
        )

    removed = [full_by_id[memory_id] for memory_id in sorted(removed_ids)]
    full_profiles = read_jsonl(full_dir / "memory_evidence_profiles.jsonl")
    off_profiles = read_jsonl(off_dir / "memory_evidence_profiles.jsonl")
    dangling = [
        row.get("profile_id")
        for row in off_profiles
        if str(row.get("parent_memory_id") or "") not in off_by_id
    ]
    non_strategy_full = {
        memory_id
        for memory_id, row in full_by_id.items()
        if row.get("memory_type") != "strategy_memory"
    }
    non_strategy_off = {
        memory_id
        for memory_id, row in off_by_id.items()
        if row.get("memory_type") != "strategy_memory"
    }
    return {
        "full_package": str(full_dir.relative_to(ROOT)),
        "structural_off_package": str(off_dir.relative_to(ROOT)),
        "full_strategy_roles": dict(strategy_roles(full)),
        "structural_off_strategy_roles": dict(strategy_roles(off)),
        "removed_memory_count": len(removed_ids),
        "added_memory_count": len(added_ids),
        "removed_all_structural_only_strategy": bool(removed)
        and all(
            row.get("memory_type") == "strategy_memory"
            and (row.get("content") or {}).get("action_memory_role")
            == "structural_only"
            for row in removed
        ),
        "non_strategy_memory_ids_identical": non_strategy_full
        == non_strategy_off,
        "full_profile_count": len(full_profiles),
        "structural_off_profile_count": len(off_profiles),
        "structural_off_dangling_parent_count": len(dangling),
        "structural_off_dangling_parent_examples": dangling[:10],
        "manifest_sha256": {
            "full": path_sha256(full_dir / "manifest.json"),
            "structural_off": path_sha256(off_dir / "manifest.json"),
        },
        "all_passed": (
            len(removed_ids) == 350
            and not added_ids
            and bool(removed)
            and all(
                row.get("memory_type") == "strategy_memory"
                and (row.get("content") or {}).get("action_memory_role")
                == "structural_only"
                for row in removed
            )
            and non_strategy_full == non_strategy_off
            and not dangling
        ),
    }


def main() -> None:
    construction_rows = read_json(CONSTRUCTION)
    construction = {
        str(row["compiler_profile_id"]): row for row in construction_rows
    }
    replay_payloads = {
        "relation_on": read_json(RELATION_ON),
        "relation_off": read_json(RELATION_OFF),
    }
    replay = {
        mode: {
            str(row["compiler_profile_id"]): row
            for row in payload["rows"]
        }
        for mode, payload in replay_payloads.items()
    }
    methods = {
        "relation_on": RELATION_METHOD,
        "relation_off": IDENTITY_METHOD,
    }

    cache: dict[tuple[str, str], dict[str, Any]] = {}
    full_hash = ""
    full_candidates: dict[str, str] = {}
    required_runs = {
        (profile_id, mode) for profile_id, mode, *_ in MAIN_ROWS
    } | {
        (profile_id, mode) for profile_id, mode, *_ in STRUCTURAL_MATRIX
    }
    for profile_id, mode in sorted(required_runs):
        replay_row = replay[mode][profile_id]
        run_dir = ROOT / replay_row["run_artifact_path"]
        method_id = methods[mode]
        digest, identities = candidate_identity(run_dir, method_id)
        cache[(profile_id, mode)] = {
            "run_dir": run_dir,
            "method_id": method_id,
            "metrics": metric_bundle(run_dir, method_id),
            "candidate_sha256": digest,
            "candidate_identities": identities,
            "readset": selection_readset_audit(
                run_dir,
                method_id,
                relation_read=mode == "relation_on",
            ),
            "spec": read_json(run_dir / "spec.json"),
        }
        if profile_id == "C8_full" and mode == "relation_on":
            full_hash, full_candidates = digest, identities

    rows = []
    for profile_id, mode, panel, label in MAIN_ROWS:
        item = cache[(profile_id, mode)]
        identities = item["candidate_identities"]
        compared_ids = set(identities) | set(full_candidates)
        mismatch = sum(
            identities.get(trace_id) != full_candidates.get(trace_id)
            for trace_id in compared_ids
        )
        construction_row = construction[profile_id]
        spec = item["spec"]
        rows.append(
            {
                "profile_id": profile_id,
                "consumer_mode": mode,
                "panel": panel,
                "label": label,
                "metrics": item["metrics"],
                "candidate_identity": {
                    "sha256": item["candidate_sha256"],
                    "full_sha256": full_hash,
                    "mismatch_count_vs_full": mismatch,
                    "population_count": len(compared_ids),
                },
                "selection_readset_audit": item["readset"],
                "package_path": construction_row["package_path"],
                "run_artifact_path": str(item["run_dir"].relative_to(ROOT)),
                "integrity": {
                    "dataset_role": spec.get("dataset_role"),
                    "sample_count": replay[mode][profile_id]["trace_count"],
                    "holdout_allowed": (spec.get("holdout") or {}).get("allowed"),
                    "compile_train_only": bool(
                        (
                            construction_row.get(
                                "compile_batch_train_only_check"
                            )
                            or {}
                        ).get("ok")
                    ),
                    "package_holdout_leakage_free": bool(
                        (
                            construction_row.get(
                                "holdout_trace_leakage_check"
                            )
                            or {}
                        ).get("ok")
                    ),
                },
            }
        )

    structural_2x2 = []
    for profile_id, mode, materialize, relation_read, cell in STRUCTURAL_MATRIX:
        item = cache[(profile_id, mode)]
        structural_2x2.append(
            {
                "cell": cell,
                "structural_action_memory": materialize,
                "structural_relation_read": relation_read,
                "profile_id": profile_id,
                "consumer_mode": mode,
                "metrics": item["metrics"],
                "candidate_sha256": item["candidate_sha256"],
                "run_artifact_path": str(item["run_dir"].relative_to(ROOT)),
            }
        )

    package_audit = package_structural_audit(construction)
    main_specs = [cache[(profile, mode)]["spec"] for profile, mode, *_ in MAIN_ROWS]
    payload = {
        "schema_version": "echo_compile.table3.stage27.dev.v1",
        "status": "completed_dev_only_outcome_free_structural_2x2",
        "dataset_role": "dev",
        "population_count": 3247,
        "holdout_accessed": False,
        "method_contract": {
            "structural_plane": (
                "candidate selection reads structural identity, value shape, "
                "boundary and optional component/source relations; it does "
                "not read Case or Strategy outcomes, LCB, Lifecycle or "
                "result-bearing support aggregates"
            ),
            "outcome_plane": (
                "given-action withholding and Auto eligibility remain on the "
                "separate attribution-checked evidence interface"
            ),
            "relation_on_method_id": RELATION_METHOD,
            "relation_off_method_id": IDENTITY_METHOD,
        },
        "rows": rows,
        "structural_2x2": structural_2x2,
        "package_structural_audit": package_audit,
        "integrity": {
            "row_count": len(rows),
            "all_dev_3247": all(
                row["integrity"]["dataset_role"] == "dev"
                and row["integrity"]["sample_count"] == 3247
                for row in rows
            ),
            "all_holdout_forbidden": all(
                row["integrity"]["holdout_allowed"] is False for row in rows
            ),
            "all_train_only_and_leakage_free": all(
                row["integrity"]["compile_train_only"]
                and row["integrity"]["package_holdout_leakage_free"]
                for row in rows
            ),
            "all_metric_contracts_pass": all(
                all(row["metrics"]["integrity"].values()) for row in rows
            ),
            "all_selection_readsets_pass": all(
                row["selection_readset_audit"]["all_passed"] for row in rows
            ),
            "package_structural_audit_pass": package_audit["all_passed"],
            "same_dev_trace_ids_hash": len(
                {
                    (spec.get("sample") or {}).get("trace_ids_hash")
                    for spec in main_specs
                }
            )
            == 1,
            "same_ranker_config_hash": len(
                {
                    ((spec.get("configs") or {}).get("ranker") or {}).get(
                        "sha256"
                    )
                    for spec in main_specs
                }
            )
            == 1,
            "same_gate_config_hash": len(
                {
                    ((spec.get("configs") or {}).get("gate") or {}).get(
                        "sha256"
                    )
                    for spec in main_specs
                }
            )
            == 1,
        },
        "source_artifacts": {
            "construction_summary": str(CONSTRUCTION.relative_to(ROOT)),
            "relation_on_replay": str(RELATION_ON.relative_to(ROOT)),
            "relation_off_replay": str(RELATION_OFF.relative_to(ROOT)),
        },
    }
    OUT.parent.mkdir(parents=True, exist_ok=True)
    OUT.write_text(
        json.dumps(payload, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )

    with OUT_CSV.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(
            handle,
            fieldnames=[
                "panel",
                "label",
                "profile_id",
                "consumer_mode",
                "strict_single_action_pass_support",
                "multi_action_pass_component_match",
                "strict_failed_action_withholding",
                "supported_action_auto_retention",
                "candidate_mismatch_count_vs_full",
            ],
        )
        writer.writeheader()
        for row in rows:
            metrics = row["metrics"]
            writer.writerow(
                {
                    "panel": row["panel"],
                    "label": row["label"],
                    "profile_id": row["profile_id"],
                    "consumer_mode": row["consumer_mode"],
                    "strict_single_action_pass_support": metrics[
                        "strict_single_action_pass_support"
                    ]["value"],
                    "multi_action_pass_component_match": metrics[
                        "multi_action_pass_component_match"
                    ]["value"],
                    "strict_failed_action_withholding": metrics[
                        "strict_failed_action_withholding"
                    ]["value"],
                    "supported_action_auto_retention": metrics[
                        "supported_action_auto_retention"
                    ]["value"],
                    "candidate_mismatch_count_vs_full": row[
                        "candidate_identity"
                    ]["mismatch_count_vs_full"],
                }
            )

    print(
        json.dumps(
            {
                "ok": all(payload["integrity"].values()),
                "rows": len(rows),
                "out": str(OUT.relative_to(ROOT)),
                "csv": str(OUT_CSV.relative_to(ROOT)),
            },
            ensure_ascii=False,
            indent=2,
        )
    )


if __name__ == "__main__":
    main()

