TABLE2B_VIEW_SOURCE = ROOT / "experiments/export_calibrated_specific_plan_risk_dev.py"
TABLE2B_RANKER_SOURCE = ROOT / "experiments/export_table2_gate_only_bundle_qualification.py"
METHODS = (
    "no_memory_ranker",
    "echo_static",
    "echo_adaptive",
    "raw_history_adaptive",
)
FORBIDDEN_TARGET_KEYS = {
    "aggregate",
    "candidate_hit",
    "execution_class",
    "gold",
    "gold_action",
    "gold_actions",
    "label",
    "target_long_eval",
    "target_outcome",
    "ticket_outcome",
}


def read_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def read_jsonl(path: Path) -> list[dict[str, Any]]:
    return [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]


def sha256_path(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def source_ref(path: Path) -> dict[str, Any]:
    return {
        "path": str(path.relative_to(ROOT)),
        "sha256": sha256_path(path),
        "size_bytes": path.stat().st_size,
    }


def write_json(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def write_jsonl(path: Path, rows: Iterable[dict[str, Any]]) -> dict[str, Any]:
    path.parent.mkdir(parents=True, exist_ok=True)
    count = 0
    with path.open("w", encoding="utf-8") as handle:
        for row in rows:
            handle.write(json.dumps(row, ensure_ascii=False, sort_keys=True, separators=(",", ":")) + "\n")
            count += 1
    return source_ref(path) | {"rows": count}


def canonical_hash(value: Any) -> str:
    encoded = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def id_hash(ids: Iterable[str]) -> str:
    return hashlib.sha256("\n".join(sorted(ids)).encode()).hexdigest()


def git_head() -> str | None:
    try:
        return subprocess.run(
            ["git", "rev-parse", "HEAD"],
            cwd=ROOT,
            check=True,
            capture_output=True,
            text=True,
        ).stdout.strip()
    except (OSError, subprocess.CalledProcessError):
        return None


def tie_score(trace_id: str) -> int:
    digest = hashlib.sha256(f"table2c-gate-only-tie-v1|{trace_id}".encode()).digest()
    return int.from_bytes(digest[:8], "big")


def rank_and_queue(
    ids: list[str],
    scores: dict[str, float],
    budgets: list[float],
) -> tuple[dict[str, int], dict[str, set[str]], dict[str, list[str]]]:
    if set(ids) != set(scores):
        raise ValueError("ranking IDs and score IDs differ")
    ordered = sorted(ids, key=lambda trace_id: (float(scores[trace_id]), tie_score(trace_id)), reverse=True)
    ranks = {trace_id: index for index, trace_id in enumerate(ordered, start=1)}
    selected: dict[str, set[str]] = {}
    ordered_queues: dict[str, list[str]] = {}
    for budget in budgets:
        key = str(budget)
        k = review_count(len(ids), budget)
        ordered_queues[key] = ordered[:k]
        selected[key] = set(ordered[:k])
    return ranks, selected, ordered_queues


def assert_no_forbidden_target_fields(row: dict[str, Any]) -> None:
    found: set[str] = set()

    def walk(value: Any) -> None:
        if isinstance(value, dict):
            for key, item in value.items():
                lowered = str(key).lower()
                if lowered in FORBIDDEN_TARGET_KEYS or lowered.startswith("target_outcome"):
                    found.add(str(key))
                walk(item)
        elif isinstance(value, list):
            for item in value:
                walk(item)

    walk(row)
    if found:
        raise ValueError(f"decision row contains forbidden target fields: {sorted(found)}")


def load_reference_values(manifest: dict[str, Any], name: str) -> tuple[list[float], dict[str, Any]]:
    ref = manifest["references"][name]["artifact"]
    path = ROOT / ref["path"]
    if sha256_path(path) != ref["sha256"]:
        raise ValueError(f"{name} reference hash changed")
    payload = read_json(path)
    values = [float(value) for value in payload["values"]]
    if values != sorted(values) or len(values) != int(manifest["references"][name]["count"]):
        raise ValueError(f"{name} reference is not the frozen sorted array")
    return values, source_ref(path)


def view_semantic_hash(view: Table2BBundleRiskView) -> str:
    def rows(mapping: dict[Any, Counter[str]]) -> list[Any]:
        return sorted(
            ([repr(key), sorted((str(label), int(count)) for label, count in counts.items())]
             for key, counts in mapping.items()),
            key=lambda item: item[0],
        )

    return canonical_hash({
        "broad_counts": rows(view.broad_counts),
        "exact_counts": rows(view.exact_counts),
        "core_counts": rows(view.core_counts),
        "bundle_exact": rows(view.bundle_exact),
        "bundle_context": rows(view.bundle_context),
        "bundle_shape": rows(view.bundle_shape),
    })


def verify_frozen_inputs(config_path: Path, config: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any]]:
    reference = read_json(REFERENCE_MANIFEST)
    if reference.get("status") != "completed_reference_freeze_no_policy_target_scoring":
        raise ValueError("P00 reference gate has not passed")
    frozen_config = reference["sources"]["config"]
    if str(config_path.relative_to(ROOT)) != frozen_config["path"] or sha256_path(config_path) != frozen_config["sha256"]:
        raise ValueError("Phase-4B config changed after reference freeze")
    for key in ("exact_consumer_contract", "statistics_gate"):
        item = reference["sources"][key]
        if sha256_path(ROOT / item["path"]) != item["sha256"]:
            raise ValueError(f"{key} changed after reference freeze")
    ranker = reference["ranker"]["artifact"]
    if sha256_path(ROOT / ranker["path"]) != ranker["sha256"]:
        raise ValueError("P00 Risk Ranker changed after reference freeze")
    phase2 = read_json(PHASE2_SUMMARY)
    train_path = ROOT / config["sources"]["train_trace_records"]
    if phase2["sources"]["train_trace_records"]["sha256"] != sha256_path(train_path):
        raise ValueError("canonical train changed after Phase 2")
    if config["dataset_role"] != "train_policy_development":
        raise ValueError("decision freeze is restricted to Train-policy-development")
    return reference, phase2


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--config", type=Path, default=DEFAULT_CONFIG)
    args = parser.parse_args()
    config_path = args.config if args.config.is_absolute() else ROOT / args.config
    config = read_json(config_path)
    reference, phase2 = verify_frozen_inputs(config_path, config)
    phase2_config_path = ROOT / config["sources"]["phase2_config"]
    phase2_config = read_json(phase2_config_path)
    train_path = ROOT / config["sources"]["train_trace_records"]
    phase2_result_dir = ROOT / config["sources"]["phase2_result_dir"]
    consumer_path = ROOT / config["sources"]["phase2_consumer_reach"]
    output_dir = ROOT / config["outputs"]["phase4b_result_dir"]
    output_dir.mkdir(parents=True, exist_ok=True)

    print("loading canonical train and reconstructing the frozen temporal index", flush=True)
    traces = list(cio.read_jsonl(train_path))
    trace_by_id = {str(trace.get("trace_id") or ""): trace for trace in traces}
    time_index = build_time_index(traces, phase2_config)
    policy_ids = sorted(time_index["policy_target_ids"])
    if len(policy_ids) != 11582 or len(set(policy_ids)) != 11582:
        raise ValueError("expected exactly 11,582 unique policy targets")
    consumer_rows = read_jsonl(consumer_path)
    consumer_by_id = {str(row["trace_id"]): row for row in consumer_rows}
    if set(consumer_by_id) != set(policy_ids):
        raise ValueError("Phase-2 consumer target set differs from Phase 4B")
    bundles = {trace_id: decision_bundle(trace_by_id[trace_id]) for trace_id in policy_ids}
    visible_input_hashes = {trace_id: canonical_hash(bundles[trace_id]) for trace_id in policy_ids}

    ranker_reference, ranker_reference_ref = load_reference_values(reference, "ranker")
    echo_reference, echo_reference_ref = load_reference_values(reference, "echo")
    raw_reference, raw_reference_ref = load_reference_values(reference, "raw")
    ranker_artifact = ROOT / reference["ranker"]["artifact"]["path"]
    frozen_ranker = joblib.load(ranker_artifact)
    print(f"scoring the frozen P00 Ranker on {len(policy_ids):,} target-visible bundles", flush=True)
    ranker_probability = predict_ranker(frozen_ranker["vectorizer"], frozen_ranker["model"], bundles)
    ranker_percentile = {
        trace_id: right_percentile(score, ranker_reference)
        for trace_id, score in ranker_probability.items()
    }

    base_ids = set(time_index["base_trace_ids"])
    if id_hash(base_ids) != reference["initialization"]["initial_history_id_sha256"]:
        raise ValueError("P00 history IDs differ from the reference freeze")
    base_histories = [trace_by_id[trace_id] for trace_id in sorted(base_ids)]
    print("materializing P00 Table-2B Bundle-Risk view and scoring ECHO-Static", flush=True)
    static_view = Table2BBundleRiskView(base_histories)
    static_view_hash = view_semantic_hash(static_view)
    static_raw: dict[str, dict[str, Any]] = {}
    static_started = time.perf_counter()
    for index, trace_id in enumerate(policy_ids, start=1):
        static_raw[trace_id] = static_view.score(bundles[trace_id])
        if index % 2000 == 0:
            print(f"  ECHO-Static {index:,}/{len(policy_ids):,}", flush=True)
    static_seconds = time.perf_counter() - static_started

    decisions: dict[str, dict[str, Any]] = {}
    window_freezes: list[dict[str, Any]] = []
    maturity_rows: list[dict[str, Any]] = []
    phase2_core_ids = set(base_ids)
    version_summaries = {str(row["version_id"]): row for row in phase2["versions"]}
    targets_by_version: dict[str, list[str]] = {}
    for trace_id in policy_ids:
        targets_by_version.setdefault(str(consumer_by_id[trace_id]["adaptive_version_id"]), []).append(trace_id)
    last_target_version = max(targets_by_version)
    budgets = [float(value) for value in config["review"]["budgets"]]
    ranker_weight = float(config["fusion"]["ranker_weight"])

    for version_dir in sorted((phase2_result_dir / "versions").iterdir()):
        if not version_dir.is_dir():
            continue
        version_manifest_path = version_dir / "manifest.json"
        version_manifest = read_json(version_manifest_path)
        version_id = str(version_manifest["version_id"])
        if version_id > last_target_version:
            break
        core_delta_path = version_dir / "core_delta.jsonl"
        core_rows = read_jsonl(core_delta_path)
        expected_core_ref = version_manifest["core_delta"]
        if sha256_path(core_delta_path) != expected_core_ref["sha256"] or len(core_rows) != int(expected_core_ref["rows"]):
            raise ValueError(f"Phase-2 core delta changed at {version_id}")
        cutoff = str(version_manifest["evidence_cutoff"])
        cutoff_dt = datetime.fromisoformat(cutoff)
        new_ids: set[str] = set()
        for row in core_rows:
            trace_id = str(row["trace_id"])
            visible_at = str(row["visible_at"])
            if datetime.fromisoformat(visible_at) >= cutoff_dt:
                raise ValueError(f"7-day visibility violation at {version_id}: {trace_id}")
            if trace_id in phase2_core_ids or trace_id in new_ids:
                raise ValueError(f"duplicate matured source at {version_id}: {trace_id}")
            new_ids.add(trace_id)
            maturity_rows.append({
                "version_id": version_id,
                "history_cutoff": cutoff,
                "source_trace_id": trace_id,
                "last_successful_exec_at": row["last_successful_exec_at"],
                "visible_at": visible_at,
                "visibility_delay_days": 7,
                "strictly_before_cutoff": True,
            })
        phase2_core_ids.update(new_ids)
        if version_id not in targets_by_version:
            continue
        window_ids = sorted(targets_by_version[version_id])
        visible_ids = {
            str(row["trace_id"])
            for row in time_index["valid_rows"]
            if row["visible_at_dt"] < cutoff_dt
        }
        if visible_ids != phase2_core_ids:
            raise ValueError(f"ECHO/Raw visible history set differs from Phase-2 core at {version_id}")
        if visible_ids & set(window_ids):
            raise ValueError(f"current-window target leaked into adaptive history at {version_id}")
        if len(visible_ids) != int(version_manifest["history_trace_count"]):
            raise ValueError(f"visible history count mismatch at {version_id}")
        phase2_summary_row = version_summaries[version_id]
        if str(phase2_summary_row["version_hash"]) != str(version_manifest["version_hash"]):
            raise ValueError(f"Phase-2 version hash mismatch at {version_id}")
        if not bool(version_manifest["semantic_equivalence"]):
            raise ValueError(f"Phase-2 semantic equivalence failed at {version_id}")

        histories = [trace_by_id[trace_id] for trace_id in sorted(visible_ids)]
        print(f"materializing {version_id}: targets={len(window_ids):,}, visible history={len(histories):,}", flush=True)
        adaptive_started = time.perf_counter()
        adaptive_view = Table2BBundleRiskView(histories)
        adaptive_view_hash = view_semantic_hash(adaptive_view)
        raw_index, raw_manifest = raw_index_for_history(histories, time_index["row_by_id"])
        raw_config = config["raw_history"]
        for trace_id in window_ids:
            adaptive = adaptive_view.score(bundles[trace_id])
            raw = raw_index.query(
                bundles[trace_id],
                m=int(raw_config["m"]),
                max_candidate_scan=int(raw_config["max_candidate_scan"]),
            )
            static = static_raw[trace_id]
            score_row = {
                "no_memory_ranker": ranker_percentile[trace_id],
                "echo_static": fuse_fixed_reference(
                    ranker_score=ranker_probability[trace_id],
                    auxiliary_score=float(static["risk_score"]),
                    ranker_reference=ranker_reference,
                    auxiliary_reference=echo_reference,
                    ranker_weight=ranker_weight,
                ),
                "echo_adaptive": fuse_fixed_reference(
                    ranker_score=ranker_probability[trace_id],
                    auxiliary_score=float(adaptive["risk_score"]),
                    ranker_reference=ranker_reference,
                    auxiliary_reference=echo_reference,
                    ranker_weight=ranker_weight,
                ),
                "raw_history_adaptive": fuse_fixed_reference(
                    ranker_score=ranker_probability[trace_id],
                    auxiliary_score=float(raw["risk_score"]),
                    ranker_reference=ranker_reference,
                    auxiliary_reference=raw_reference,
                    ranker_weight=ranker_weight,
                ),
            }
            row = {
                "trace_id": trace_id,
                "window_id": str(consumer_by_id[trace_id]["window_id"]),
                "target_visible_input_sha256": visible_input_hashes[trace_id],
                "bundle_hash": bundles[trace_id]["bundle_hash"],
                "action_count": int(bundles[trace_id]["action_count"]),
                "tie_score": tie_score(trace_id),
                "memory": {
                    "static_version_id": "P00_BASE",
                    "adaptive_version_id": version_id,
                    "adaptive_history_cutoff": cutoff,
                    "adaptive_visible_history_count": len(visible_ids),
                    "adaptive_visible_history_id_sha256": id_hash(visible_ids),
                    "phase2_package_semantic_sha256": version_manifest["reconstructed_package_semantic_hash"],
                    "static_consumer_view_sha256": static_view_hash,
                    "adaptive_consumer_view_sha256": adaptive_view_hash,
                },
                "components": {
                    "ranker_probability": ranker_probability[trace_id],
                    "ranker_percentile": ranker_percentile[trace_id],
                    "echo_static_raw": static,
                    "echo_adaptive_raw": adaptive,
                    "raw_history_raw": {
                        "risk_score": raw["risk_score"],
                        "selected_trace_ids": raw["selected_trace_ids"],
                        "source_pass_count": raw["pass_count"],
                        "source_fail_count": raw["fail_count"],
                        "selected_count": raw["selected_count"],
                        "candidate_scan_count": raw["candidate_scan_count"],
                        "matching_source_count": raw["matching_source_count"],
                    },
                    "echo_static_percentile": right_percentile(float(static["risk_score"]), echo_reference),
                    "echo_adaptive_percentile": right_percentile(float(adaptive["risk_score"]), echo_reference),
                    "raw_history_percentile": right_percentile(float(raw["risk_score"]), raw_reference),
                },
                "scores": score_row,
            }
            assert_no_forbidden_target_fields(row)
            decisions[trace_id] = row
        elapsed = time.perf_counter() - adaptive_started
        window_id = str(consumer_by_id[window_ids[0]]["window_id"])
        if any(str(consumer_by_id[trace_id]["window_id"]) != window_id for trace_id in window_ids):
            raise ValueError(f"version {version_id} spans multiple target windows")
        window_freezes.append({
            "window_id": window_id,
            "target_count": len(window_ids),
            "target_id_sha256": id_hash(window_ids),
            "adaptive_version_id": version_id,
            "history_cutoff": cutoff,
            "visible_history_count": len(visible_ids),
            "visible_history_id_sha256": id_hash(visible_ids),
            "new_matured_history_count": len(new_ids),
            "new_matured_history_id_sha256": id_hash(new_ids),
            "max_new_visible_at": max((str(row["visible_at"]) for row in core_rows), default=None),
            "strict_visibility_passed": all(datetime.fromisoformat(str(row["visible_at"])) < cutoff_dt for row in core_rows),
            "current_window_target_history_overlap_count": 0,
            "phase2_version_hash": version_manifest["version_hash"],
            "phase2_package_semantic_sha256": version_manifest["reconstructed_package_semantic_hash"],
            "phase2_semantic_equivalence": True,
            "phase2_manifest": source_ref(version_manifest_path),
            "phase2_core_delta": source_ref(core_delta_path) | {"rows": len(core_rows)},
            "echo_consumer_view": adaptive_view.manifest | {"semantic_sha256": adaptive_view_hash},
            "raw_history_view": raw_manifest,
            "scoring_seconds": elapsed,
        })
        del histories, adaptive_view, raw_index
        gc.collect()

    if set(decisions) != set(policy_ids):
        missing = sorted(set(policy_ids) - set(decisions))
        raise ValueError(f"not all policy targets received decisions: {missing[:5]}")

    queues: list[dict[str, Any]] = []
    ranking_rows: list[dict[str, Any]] = []
    for window in sorted(window_freezes, key=lambda item: item["window_id"]):
        window_id = str(window["window_id"])
        ids = sorted(trace_id for trace_id, row in decisions.items() if row["window_id"] == window_id)
        for method in METHODS:
            method_scores = {trace_id: float(decisions[trace_id]["scores"][method]) for trace_id in ids}
            ranks, selected, ordered_queues = rank_and_queue(ids, method_scores, budgets)
            for trace_id in ids:
                decisions[trace_id].setdefault("rank", {})[method] = ranks[trace_id]
                decisions[trace_id].setdefault("review_selected", {})[method] = {
                    str(budget): trace_id in selected[str(budget)] for budget in budgets
                }
                ranking_rows.append({
                    "window_id": window_id,
                    "trace_id": trace_id,
                    "method": method,
                    "score": method_scores[trace_id],
                    "tie_score": tie_score(trace_id),
                    "rank": ranks[trace_id],
                    "review_selected": decisions[trace_id]["review_selected"][method],
                })
            for budget in budgets:
                key = str(budget)
                ordered_ids = ordered_queues[key]
                queues.append({
                    "window_id": window_id,
                    "method": method,
                    "budget": budget,
                    "target_count": len(ids),
                    "review_count": len(ordered_ids),
                    "ordered_trace_ids": ordered_ids,
                    "ordered_trace_id_sha256": hashlib.sha256("\n".join(ordered_ids).encode()).hexdigest(),
                    "unordered_trace_id_sha256": id_hash(ordered_ids),
                })

    for row in decisions.values():
        assert_no_forbidden_target_fields(row)
    decision_path = output_dir / "frozen_policy_decisions.jsonl"
    ranking_path = output_dir / "frozen_rankings.jsonl"
    queue_path = output_dir / "frozen_review_queues.json"
    window_path = output_dir / "window_freeze.json"
    maturity_path = output_dir / "matured_source_visibility.jsonl"
    decision_ref = write_jsonl(decision_path, (decisions[trace_id] for trace_id in sorted(decisions)))
    ranking_ref = write_jsonl(
        ranking_path,
        sorted(ranking_rows, key=lambda row: (row["window_id"], row["method"], row["rank"])),
    )
    write_json(queue_path, {"schema_version": "jsac.phase4b_review_queues.v1", "queues": queues})
    write_json(window_path, {"schema_version": "jsac.phase4b_window_freeze.v1", "windows": window_freezes})
    maturity_ref = write_jsonl(
        maturity_path,
        sorted(maturity_rows, key=lambda row: (row["version_id"], row["source_trace_id"])),
    )

    phase4a_manifest_path = ROOT / config["sources"]["phase4a_decision_freeze"]
    method_contracts = {
        "common": {
            "target_representation": "pipeline.evaluation.jsac_phase4_layer2.decision_bundle",
            "target_visible_input_hash_per_row": True,
            "ranker_artifact_sha256": reference["ranker"]["artifact"]["sha256"],
            "ranker_reference_sha256": ranker_reference_ref["sha256"],
            "ranker_weight": ranker_weight,
            "auxiliary_weight": 1.0 - ranker_weight,
            "right_percentile": "bisect_right(sorted_reference, score) / len(sorted_reference)",
            "budgets": budgets,
            "review_count": "floor(N_window * budget + 0.5)",
            "tie_break": "sha256(table2c-gate-only-tie-v1|trace_id) first 8 bytes big-endian descending",
        },
        "echo_static": {
            "consumer": config["echo_bundle_risk"]["consumer"],
            "memory_version": "P00_BASE",
            "auxiliary_reference_sha256": echo_reference_ref["sha256"],
        },
        "echo_adaptive": {
            "consumer": config["echo_bundle_risk"]["consumer"],
            "memory_version": "version at target window start",
            "auxiliary_reference_sha256": echo_reference_ref["sha256"],
        },
        "raw_history_adaptive": {
            "consumer": "outcome-blind rare-posting M=4 Beta(1,1)",
            "history_version": "same trace-ID set as ECHO-Adaptive",
            "auxiliary_reference_sha256": raw_reference_ref["sha256"],
        },
    }
    if {key: value for key, value in method_contracts["echo_static"].items() if key != "memory_version"} != {
        key: value for key, value in method_contracts["echo_adaptive"].items() if key != "memory_version"
    }:
        raise ValueError("Static and Adaptive contracts differ by more than Memory version")

    manifest = {
        "schema_version": "jsac.phase4b_policy_decision_freeze.v1",
        "status": "all_11582_policy_decisions_rankings_and_queues_frozen_before_target_outcome_reveal",
        "protocol_version": config["protocol_version"],
        "consumer_contract": config["consumer_contract"],
        "statistics_contract": config["statistics_contract"],
        "git_head": git_head(),
        "population": {
            "dataset_role": "train_policy_development",
            "target_count": len(decisions),
            "target_id_sha256": id_hash(decisions),
            "window_count": len(window_freezes),
            "methods": list(METHODS),
            "budgets": budgets,
        },
        "method_contracts": method_contracts,
        "references": {
            "ranker": ranker_reference_ref,
            "echo": echo_reference_ref,
            "raw": raw_reference_ref,
            "cohort_id_sha256": reference["reference_cohort"]["id_sha256"],
        },
        "static_memory": {
            "version_id": "P00_BASE",
            "history_count": len(base_ids),
