#!/usr/bin/env python3
"""Freeze one window's exact Agent-visible states before reading its outcomes.

This is the causal gate for delayed batched policy readout.  The script reads
only the result-blind logical-call projection, verifies the existing prepare
and identifiability artifacts, then persists exact model-visible states and a
local-only logical-call mapping.  No GPT choice or target label is required.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import sys
from pathlib import Path
from typing import Any, Iterable

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from pipeline.common import io as cio
from pipeline.evaluation.jsac_agent_facing_one_shot import (
    canonical_json,
    exact_states,
    sha256_text,
    task_row,
)


DEFAULT_LAYER2_CONFIG = ROOT / "experiments/config/jsac_two_timescale/phase5_unified_continual_replay.v2_1.json"
DEFAULT_AGENT_CONFIG = ROOT / "experiments/config/jsac_two_timescale/agent_facing_one_shot_action_readout.v2_1.json"
V2_AGENT_CONFIG = ROOT / "experiments/config/jsac_two_timescale/agent_facing_one_shot_action_readout.v2.json"


def read_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def read_jsonl(path: Path) -> list[dict[str, Any]]:
    return list(cio.read_jsonl(path))


def sha256_path(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def source_ref(path: Path) -> dict[str, Any]:
    return {
        "path": str(path.relative_to(ROOT)),
        "size_bytes": path.stat().st_size,
        "sha256": sha256_path(path),
    }


def verify_ref(item: dict[str, Any]) -> Path:
    path = ROOT / item["path"]
    if not path.exists() or sha256_path(path) != item["sha256"]:
        raise ValueError(f"frozen artifact hash failed: {item['path']}")
    return path


def write_json(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def write_jsonl(path: Path, rows: Iterable[dict[str, Any]]) -> dict[str, Any]:
    path.parent.mkdir(parents=True, exist_ok=True)
    count = 0
    with path.open("w", encoding="utf-8") as handle:
        for row in rows:
            handle.write(json.dumps(row, ensure_ascii=False, separators=(",", ":")) + "\n")
            count += 1
    return source_ref(path) | {"rows": count}


def verify_existing_manifest(path: Path) -> dict[str, Any]:
    manifest = read_json(path)
    if not all((manifest.get("integrity") or {}).values()):
        raise ValueError("existing Agent state-freeze manifest failed integrity")
    for item in (manifest.get("artifacts") or {}).values():
        verify_ref(item)
    return manifest


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--window-id", required=True)
    parser.add_argument("--layer2-config", type=Path, default=DEFAULT_LAYER2_CONFIG)
    parser.add_argument("--agent-config", type=Path, default=DEFAULT_AGENT_CONFIG)
    args = parser.parse_args()

    layer2_path = args.layer2_config if args.layer2_config.is_absolute() else ROOT / args.layer2_config
    agent_path = args.agent_config if args.agent_config.is_absolute() else ROOT / args.agent_config
    layer2 = read_json(layer2_path)
    agent = read_json(agent_path)
    v2_agent = read_json(V2_AGENT_CONFIG)
    protocol_hash = sha256_text(canonical_json(agent["model_visible_protocol"]))
    v2_protocol_hash = sha256_text(canonical_json(v2_agent["model_visible_protocol"]))
    if protocol_hash != v2_protocol_hash:
        raise ValueError("v2.1 model-visible protocol differs from the frozen v2 protocol")

    result_root = ROOT / layer2["outputs"]["result_root"]
    prepare_root = result_root / "windows" / args.window_id / "prepare"
    manifest_path = prepare_root / "agent_state_freeze_manifest_v2_1.json"
    if manifest_path.exists():
        existing = verify_existing_manifest(manifest_path)
        if existing.get("window_id") != args.window_id or existing.get("protocol_hash") != protocol_hash:
            raise ValueError("existing Agent state freeze belongs to another window or protocol")
        print(json.dumps({
            "status": "EXISTING_CAUSAL_AGENT_STATE_FREEZE_REVERIFIED",
            "window_id": args.window_id,
            "unique_prompt_states": existing["counts"]["unique_prompt_states"],
            "manifest": str(manifest_path.relative_to(ROOT)),
        }, ensure_ascii=False, indent=2))
        return

    prepare_manifest_path = prepare_root / "manifest.json"
    prepare = read_json(prepare_manifest_path)
    if prepare.get("window_id") != args.window_id or not all(prepare["integrity"].values()):
        raise ValueError("window preparation did not pass")
    for item in prepare["artifacts"].values():
        verify_ref(item)

    identifiability_path = prepare_root / "agent_candidate_identifiability_audit.json"
    identifiability = read_json(identifiability_path)
    if identifiability.get("window_id") != args.window_id or not all(identifiability["checks"].values()):
        raise ValueError("Agent candidate identifiability audit did not pass")
    for item in identifiability["sources"].values():
        verify_ref(item)

    logical_path = verify_ref(prepare["artifacts"]["agent_logical_calls"])
    logical_calls = read_jsonl(logical_path)
    states = exact_states(logical_calls, protocol_hash=protocol_hash)
    registry_rows: list[dict[str, Any]] = []
    mapping_rows: list[dict[str, Any]] = []
    for state in states:
        registry_rows.append({
            "prompt_state_id": state["prompt_state_id"],
            "state_hash": state["state_hash"],
            **task_row(state),
        })
        for call in state["logical_calls"]:
            mapping_rows.append({
                **call,
                "prompt_state_id": state["prompt_state_id"],
                "state_hash": state["state_hash"],
            })
    mapping_rows.sort(key=lambda row: str(row["logical_call_id"]))

    freeze_root = prepare_root / "agent" / "state_freeze_v2_1"
    registry_ref = write_jsonl(freeze_root / "prompt_state_registry.jsonl", registry_rows)
    mapping_ref = write_jsonl(freeze_root / "logical_to_prompt_state_mapping.jsonl", mapping_rows)
    branch_counts = {
        branch: sum(str(row["memory_branch"]) == branch for row in mapping_rows)
        for branch in ("static", "adaptive")
    }
    calls_by_state: dict[str, list[dict[str, Any]]] = {}
    for row in mapping_rows:
        calls_by_state.setdefault(str(row["state_hash"]), []).append(row)
    cross_branch = sum(
        len({str(row["memory_branch"]) for row in rows}) > 1
        for rows in calls_by_state.values()
    )
    logical_count = len(logical_calls)
    unique_count = len(states)
    freeze_manifest = {
        "schema_version": "jsac.unified_agent_visible_state_freeze.v2_1",
        "status": "CAUSAL_AGENT_VISIBLE_STATES_FROZEN_BEFORE_WINDOW_OUTCOME_ACCESS; GPT POLICY READOUT MAY BE DELAYED",
        "window_id": args.window_id,
        "protocol_hash": protocol_hash,
        "counts": {
            "logical_agent_decisions": logical_count,
            "logical_decisions_by_branch": branch_counts,
            "unique_prompt_states": unique_count,
            "exact_state_reuses": logical_count - unique_count,
            "exact_state_reuse_rate": (logical_count - unique_count) / logical_count if logical_count else None,
            "cross_static_adaptive_shared_states": cross_branch,
        },
        "artifacts": {
            "prompt_state_registry": registry_ref,
            "logical_to_prompt_state_mapping": mapping_ref,
        },
        "sources": {
            "layer2_config": source_ref(layer2_path),
            "agent_config": source_ref(agent_path),
            "agent_v2_config": source_ref(V2_AGENT_CONFIG),
            "prepare_manifest": source_ref(prepare_manifest_path),
            "agent_candidate_identifiability_audit": source_ref(identifiability_path),
            "logical_calls": source_ref(logical_path),
            "freezer": source_ref(Path(__file__).resolve()),
        },
        "integrity": {
            "prepare_and_all_prepare_artifacts_verified": True,
            "gold_blind_candidate_identifiability_verified": True,
            "v2_1_model_visible_protocol_byte_semantically_equal_to_v2": protocol_hash == v2_protocol_hash,
            "all_logical_calls_mapped_once": len(mapping_rows) == logical_count == len({row["logical_call_id"] for row in mapping_rows}),
            "all_unique_states_have_one_registry_row": len(registry_rows) == unique_count == len({row["state_hash"] for row in registry_rows}),
            "selected_candidate_cells_blank": all(row["selected_candidate_id"] == "" for row in registry_rows),
            "target_outcome_or_gold_not_read": True,
            "gpt_choice_not_required_for_window_advance": True,
        },
        "next_gate": "after this manifest is hash-frozen, this window outcome may be released only to the causal memory-update stream; GPT choices remain pending",
    }
    if not all(freeze_manifest["integrity"].values()):
        raise ValueError("Agent visible-state freeze integrity failed")
    write_json(manifest_path, freeze_manifest)
    print(json.dumps({
        "status": freeze_manifest["status"],
        "window_id": args.window_id,
        **freeze_manifest["counts"],
        "manifest": str(manifest_path.relative_to(ROOT)),
    }, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Reconstruct JSAC Supplementary Table S6 from frozen decision-time scores."""

from __future__ import annotations

import argparse
from collections import defaultdict
import hashlib
import json
import math
from pathlib import Path
from typing import Any, Iterable


PASS = "long_eval_pass"
FAIL = "long_eval_fail"
BUDGETS = (0.1, 0.2)
METHODS = ("ranker", "static", "adaptive")


def read_jsonl(path: Path) -> Iterable[dict[str, Any]]:
    with path.open(encoding="utf-8") as handle:
        for line in handle:
            if line.strip():
                yield json.loads(line)


def tie_score(trace_id: str) -> int:
    digest = hashlib.sha256(f"table2c-gate-only-tie-v1|{trace_id}".encode()).digest()
    return int.from_bytes(digest[:8], "big")


def review_count(n: int, budget: float) -> int:
    return int(math.floor(n * budget + 0.5))


def outcome(trace: dict[str, Any]) -> str:
    value = str((trace.get("aggregate") or {}).get("ticket_outcome") or "")
    return value if value in {PASS, FAIL} else ""


def load_outcomes(paths: list[Path]) -> dict[str, str]:
    result: dict[str, str] = {}
    for path in paths:
        for trace in read_jsonl(path):
            trace_id = str(trace.get("trace_id") or "")
            label = outcome(trace)
            if trace_id and label:
                if trace_id in result and result[trace_id] != label:
                    raise ValueError(f"conflicting outcomes for {trace_id}")
                result[trace_id] = label
    return result


def reconstruct(scores_path: Path, trace_paths: list[Path]) -> dict[str, Any]:
    labels = load_outcomes(trace_paths)
    rows_by_window: dict[str, list[dict[str, Any]]] = defaultdict(list)
    seen: set[str] = set()
    match_counts = {"static": 0, "adaptive": 0}
    exact_counts = {"static": 0, "adaptive": 0}

    for source in read_jsonl(scores_path):
        window = str(source.get("window_id") or "")
        if not ("W24" <= window <= "W36"):
            continue
        trace_id = str(source.get("trace_id") or "")
        if not trace_id or trace_id in seen:
            raise ValueError(f"missing or duplicate trace_id: {trace_id!r}")
        if trace_id not in labels:
            raise ValueError(f"outcome missing for {trace_id}")
        seen.add(trace_id)
        ranker = float((source.get("scores") or {})["Ranker"])
        method_scores = {"ranker": ranker}
        for method in ("static", "adaptive"):
            feature = source[method]
            matched = not bool(feature["bundle_missing"])
            exact = matched and math.isclose(float(feature["bundle_exact"]), 1.0)
            match_counts[method] += int(matched)
            exact_counts[method] += int(exact)
            method_scores[method] = (
                0.5 * ranker + 0.5 * float(feature["bundle_lcb"])
                if matched
                else ranker
            )
        rows_by_window[window].append(
            {"trace_id": trace_id, "outcome": labels[trace_id], "scores": method_scores}
        )

    rows = [row for window_rows in rows_by_window.values() for row in window_rows]
    fail_count = sum(row["outcome"] == FAIL for row in rows)
    selected: dict[str, dict[str, set[str]]] = {
        method: {str(budget): set() for budget in BUDGETS} for method in METHODS
    }
    for method in METHODS:
        for window_rows in rows_by_window.values():
            ordered = sorted(
                window_rows,
                key=lambda row: (float(row["scores"][method]), tie_score(row["trace_id"])),
                reverse=True,
            )
            for budget in BUDGETS:
                selected[method][str(budget)].update(
                    row["trace_id"] for row in ordered[: review_count(len(ordered), budget)]
                )

    label_by_id = {row["trace_id"]: row["outcome"] for row in rows}
    metrics: dict[str, Any] = {}
    for method in METHODS:
        method_metrics: dict[str, Any] = {}
        for budget in BUDGETS:
            reviewed = selected[method][str(budget)]
            captured = sum(label_by_id[trace_id] == FAIL for trace_id in reviewed)
            method_metrics[f"hfc_{int(budget * 100)}pct"] = [captured, fail_count]
        metrics[method] = method_metrics

    return {
        "schema_version": "echo-mem-governed-publication-readout.v1",
        "reconstruction_level": "exact_from_frozen_decision_time_score_ledger",
        "window_range": "W24-W36",
        "population": len(rows),
        "fail_population": fail_count,
        "published_bundle_match": match_counts,
        "exact_match": exact_counts,
        "metrics": metrics,
        "adaptive_minus_static": {
            f"hfc_{int(budget * 100)}pct": [
                metrics["adaptive"][f"hfc_{int(budget * 100)}pct"][0]
                - metrics["static"][f"hfc_{int(budget * 100)}pct"][0],
                fail_count,
            ]
            for budget in BUDGETS
        },
    }


def expected_projection(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))["q3_governed_publication_readout"]


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--scores", type=Path, required=True)
    parser.add_argument("--traces", type=Path, action="append", required=True)
    parser.add_argument("--expected", type=Path)
    parser.add_argument("--out", type=Path)
    args = parser.parse_args()

    actual = reconstruct(args.scores, args.traces)
    actual["matches_expected"] = (
        actual == expected_projection(args.expected) if args.expected else None
    )
    encoded = json.dumps(actual, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
    if args.out:
        args.out.parent.mkdir(parents=True, exist_ok=True)
        args.out.write_text(encoded, encoding="utf-8")
    print(encoded, end="")
    return 0 if actual["matches_expected"] is not False else 2


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Run a causal multi-window, Table-2A-isomorphic positive-reuse replay.

Stage ``freeze`` produces Static/Adaptive structural selections for every
target without reading target actions or outcomes.  Stage ``evaluate`` first
verifies the immutable selection freeze, then reveals Pass outcomes and reports
SSAPS/MHCM@1.  The two stages intentionally write separate artifacts.
"""
from __future__ import annotations

import argparse
import gc
import hashlib
import json
import sys
import time
from collections import Counter, defaultdict
from pathlib import Path
from typing import Any, Iterable
from zoneinfo import ZoneInfo

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from experiments.audit_jsac_unified_chronological_split import timing_projection
from experiments.evaluate_jsac_unified_agent_v4_rank_neutral import holm_adjust, paired_statistics
from experiments.export_jsac_phase1_candidate_pool_audit import (
    candidate_hit,
    observed_pass_actions,
)
from experiments.export_jsac_phase2_weekly_maturity_consumer_reach import compile_version
from pipeline.common import io as cio
from pipeline.evaluation.jsac_agent_candidate_family import evaluator_action_family_signature
from pipeline.evaluation.retrieval_baselines import (
    _STRUCTURAL_ACTION_ADMISSION_POLICY,
    _case_action,
    case_retrieval_compiled_knowledge_gate_decide,
)


DEFAULT_CONFIG = ROOT / "experiments/config/jsac_two_timescale/phase5b_temporal_table2a_positive_reuse.v1.json"
FORBIDDEN_FREEZE_KEYS = {
    "actions",
    "aggregate",
    "gold",
    "gold_action",
    "gold_actions",
    "long_eval_result",
    "target_outcome",
    "ticket_outcome",
    "pass",
    "fail",
    "hit",
}
ACTION_FIELDS = (
    "scheme_group",
    "scheme_id",
    "parameter_semantic_id",
    "param_object",
    "site_param_object",
    "param_en_name",
    "site_param_en_name",
    "param_cn_name",
    "parameter_group",
    "value_type",
    "direction",
    "suggested_delta",
    "delta_bucket",
    "value_pattern_id",
    "canonical_action_id",
    "before_value",
    "after_value",
    "change",
    "adjustment_rule",
    "value_rule",
    "final_ratio",
    "plan_companion_parameters",
)


def read_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text(encoding="utf-8"))


def write_json(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def write_jsonl(path: Path, rows: Iterable[dict[str, Any]]) -> dict[str, Any]:
    path.parent.mkdir(parents=True, exist_ok=True)
    count = 0
    with path.open("w", encoding="utf-8") as handle:
        for row in rows:
            handle.write(json.dumps(row, ensure_ascii=False, separators=(",", ":")) + "\n")
            count += 1
    return source_ref(path) | {"rows": count}


def sha256_path(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def source_ref(path: Path) -> dict[str, Any]:
    return {
        "path": str(path.relative_to(ROOT)),
        "size_bytes": path.stat().st_size,
        "sha256": sha256_path(path),
    }


def canonical_hash(value: Any) -> str:
    payload = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def id_hash(values: Iterable[str]) -> str:
    return hashlib.sha256("\n".join(sorted(str(value) for value in values)).encode()).hexdigest()


def ratio(numerator: int, denominator: int) -> dict[str, Any]:
    return {
        "numerator": int(numerator),
        "denominator": int(denominator),
        "value": numerator / denominator if denominator else None,
    }


def assert_outcome_blind(value: Any, *, path: str = "root") -> None:
    if isinstance(value, dict):
        for key, item in value.items():
            token = str(key).strip().lower()
            if token in FORBIDDEN_FREEZE_KEYS:
                raise ValueError(f"outcome/gold key in decision freeze: {path}.{key}")
            assert_outcome_blind(item, path=f"{path}.{key}")
    elif isinstance(value, list):
        for index, item in enumerate(value):
            assert_outcome_blind(item, path=f"{path}[{index}]")


def action_projection(action: dict[str, Any] | None) -> dict[str, Any]:
    raw = action if isinstance(action, dict) else {}
    return {key: raw.get(key) for key in ACTION_FIELDS if raw.get(key) not in (None, "", [], {})}


def family(action: dict[str, Any]) -> list[str]:
    return [str(value) for value in evaluator_action_family_signature(action)]


def structural_context(trace: dict[str, Any]) -> dict[str, Any]:
    ticket = trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}
    return {
        "primary_issue_type": ticket.get("primary_issue_type"),
        "vendor": ticket.get("vendor"),
        "system": ticket.get("system"),
        "region": ticket.get("region"),
        "band": ticket.get("band"),
    }


def context_key(context: dict[str, Any]) -> str:
    return canonical_hash(context)


def decision_trace(context: dict[str, Any], trace_id: str) -> dict[str, Any]:
    return {"trace_id": trace_id, "ticket": dict(context)}


def selector_artifacts(memories: list[dict[str, Any]]) -> dict[str, Any]:
    return {
        "memories": memories,
        "memories_by_id": {
            str(memory.get("memory_id") or ""): memory
            for memory in memories
            if memory.get("memory_id")
        },
        "memory_evidence_profiles": [],
        "support_routing_profiles": [],
        "navigation_map": {},
    }


def select_structural(
    *,
    context: dict[str, Any],
    memories: list[dict[str, Any]],
    artifacts: dict[str, Any],
    limit: int,
) -> dict[str, Any]:
    trace = decision_trace(context, f"CTX-{context_key(context)[:16]}")
    decision = case_retrieval_compiled_knowledge_gate_decide(
        trace,
        memories,
        artifacts=artifacts,
        limit=limit,
        method_id="temporal_table2a_selection_projection_v1",
        rank_variant="no_outcome_counts",
        profile_consumption_policy="off",
        use_action_value_selector=False,
        temporal_action_selection_policy="",
        apply_safety_arbitration=False,
    )
    by_id = artifacts["memories_by_id"]
    candidates: list[dict[str, Any]] = []
    for rank, score in enumerate((decision.get("supporting_knowledge") or {}).get("candidate_scores") or [], start=1):
        memory_id = str(score.get("memory_id") or "")
        memory = by_id.get(memory_id) or {}
        candidate_action = _case_action(
            memory,
            action_admission_policy=_STRUCTURAL_ACTION_ADMISSION_POLICY,
        )
        projected = action_projection(candidate_action)
        if not projected:
            continue
        candidates.append({
            "rank": rank,
            "memory_id": memory_id,
            "action": projected,
            "action_family": family(projected),
        })
    selected = action_projection(decision.get("recommended_action") or {})
    if bool(selected) != bool(candidates):
        raise ValueError("selected action and candidate list availability differ")
    if selected and family(selected) != candidates[0]["action_family"]:
        raise ValueError("selected action does not match ranked candidate 1")
    return {
        "selected_action": selected,
        "selected_action_family": family(selected) if selected else [],
        "candidates": candidates,
        "candidate_count": len(candidates),
    }


def verify_ref(item: dict[str, Any]) -> Path:
    path = ROOT / item["path"]
    if not path.exists() or sha256_path(path) != item["sha256"]:
        raise ValueError(f"frozen source changed: {item['path']}")
    return path


def load_contract(config_path: Path) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any], dict[str, Any], Path]:
    config = read_json(config_path)
    unified_path = ROOT / config["dependencies"]["unified_replay_config"]
    unified = read_json(unified_path)
    split_path = ROOT / unified["outputs"]["split_audit"]
    init_path = ROOT / unified["outputs"]["initialization_manifest"]
    split = read_json(split_path)
    init = read_json(init_path)
    if not all(split["integrity"].values()) or not all(init["integrity"].values()):
        raise ValueError("unified split/initialization integrity is not fully passed")
    return config, unified, split, init, unified_path


def frozen_target_ids(unified: dict[str, Any], split: dict[str, Any]) -> tuple[dict[str, list[str]], dict[str, str]]:
    root = ROOT / unified["outputs"]["result_root"]
    target_ids: dict[str, list[str]] = {}
    target_to_window: dict[str, str] = {}
    for window in split["replay"]["windows"]:
        window_id = str(window["window_id"])
        manifest_path = root / "windows" / window_id / "prepare" / "manifest.json"
        manifest = read_json(manifest_path)
        decision_path = verify_ref(manifest["artifacts"]["deterministic_decisions"])
        ids = [str(row["trace_id"]) for row in cio.read_jsonl(decision_path)]
        if len(ids) != int(window["target_count"]) or id_hash(ids) != window["target_id_sha256"]:
            raise ValueError(f"target freeze mismatch: {window_id}")
        for trace_id in ids:
            if trace_id in target_to_window:
                raise ValueError(f"target appears in multiple windows: {trace_id}")
            target_to_window[trace_id] = window_id
        target_ids[window_id] = sorted(ids)
    return target_ids, target_to_window


def collect_target_contexts(
    unified: dict[str, Any],
    target_to_window: dict[str, str],
) -> tuple[dict[str, dict[str, Any]], dict[str, dict[str, Any]]]:
    target_contexts: dict[str, dict[str, Any]] = {}
    contexts: dict[str, dict[str, Any]] = {}
    for spec in unified["source"]["canonical_partitions"]:
        path = ROOT / spec["path"]
        count = 0
        for trace in cio.read_jsonl(path):
            count += 1
            trace_id = str(trace.get("trace_id") or "")
            if trace_id not in target_to_window:
                continue
            context = structural_context(trace)
            target_contexts[trace_id] = context
            contexts.setdefault(context_key(context), context)
        if count != int(spec["expected_count"]):
            raise ValueError(f"source count changed: {path}")
    if set(target_contexts) != set(target_to_window):
        raise ValueError("not every replay target has an outcome-blind context")
    return target_contexts, contexts


def load_initial_memories(init: dict[str, Any]) -> list[dict[str, Any]]:
    item = init["memory"]["artifacts"]["memory_objects"]
    path = verify_ref(item)
    return list(cio.read_jsonl(path))


def reconstruct_window_histories(
    *,
    unified: dict[str, Any],
    split: dict[str, Any],
    init: dict[str, Any],
    window_index: int,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    window = split["replay"]["windows"][window_index]
    window_start = str(window["start"])
    replay_start = str(split["cutoffs"]["T50"])
    p0_path = verify_ref(init["initialization"]["history_artifact"])
    p0_ids = {str(row["trace_id"]) for row in cio.read_jsonl(p0_path)}
    prior_ids: set[str] = set()
    result_root = ROOT / unified["outputs"]["result_root"]
    for prior in split["replay"]["windows"][:window_index]:
        reveal_path = result_root / "windows" / prior["window_id"] / "reveal" / "revealed_labels.jsonl"
        prior_ids.update(str(row["trace_id"]) for row in cio.read_jsonl(reveal_path))
    timezone = ZoneInfo(str(unified["time_contract"]["timezone"]))
    delay_days = int(unified["time_contract"]["visibility_delay_days"])
    histories: dict[str, dict[str, Any]] = {}
    late_pre_cutoff = 0
    prior_replay = 0
    for spec in unified["source"]["canonical_partitions"]:
        path = ROOT / spec["path"]
        count = 0
        for trace in cio.read_jsonl(path):
            count += 1
            timing = timing_projection(trace, timezone, delay_days)
            trace_id = timing["trace_id"]
            issued = timing["issued_at"].isoformat() if timing["issued_at"] is not None else None
            visible = timing["visible_at"].isoformat() if timing["visible_at"] is not None else None
            if trace_id in p0_ids:
                histories[trace_id] = trace
                continue
            admitted = False
            if issued is not None and issued < replay_start and visible is not None and replay_start <= visible < window_start:
                admitted = True
                late_pre_cutoff += 1
            if trace_id in prior_ids and visible is not None and visible < window_start:
                admitted = True
                prior_replay += 1
            if admitted:
                histories[trace_id] = trace
        if count != int(spec["expected_count"]):
            raise ValueError(f"source count changed: {path}")
    if not p0_ids.issubset(histories):
        raise ValueError("P0 history could not be reconstructed")
    ids = sorted(histories)
    return [histories[trace_id] for trace_id in ids], {
        "history_count": len(ids),
        "history_id_sha256": id_hash(ids),
        "late_pre_cutoff_admitted": late_pre_cutoff,
        "prior_replay_admitted": prior_replay,
        "history_cutoff": window_start,
    }


def freeze(config_path: Path) -> None:
    config, unified, split, init, unified_path = load_contract(config_path)
    result_root = ROOT / config["outputs"]["result_root"]
    freeze_root = result_root / "freeze"
    if (freeze_root / "manifest.json").exists():
        raise ValueError("selection freeze already completed; refusing to overwrite")
    target_ids, target_to_window = frozen_target_ids(unified, split)
    target_contexts, all_contexts = collect_target_contexts(unified, target_to_window)
    limit = int(config["selection"]["candidate_limit"])

    print(f"Static P0: selecting {len(all_contexts):,} unique structural contexts", flush=True)
    static_memories = load_initial_memories(init)
    static_artifacts = selector_artifacts(static_memories)
    static_by_context = {
        key: select_structural(context=context, memories=static_memories, artifacts=static_artifacts, limit=limit)
        for key, context in sorted(all_contexts.items())
    }
    del static_artifacts, static_memories
    gc.collect()

    window_refs: list[dict[str, Any]] = []
    all_decision_rows = 0
    all_family_changes = 0
    all_exact_changes = 0
    all_missing = 0
    compile_seconds = 0.0
    for index, window in enumerate(split["replay"]["windows"]):
        window_id = str(window["window_id"])
        output_path = freeze_root / "windows" / window_id / "decisions.jsonl"
        window_manifest_path = freeze_root / "windows" / window_id / "manifest.json"
        if output_path.exists() and window_manifest_path.exists():
            manifest = read_json(window_manifest_path)
            verify_ref(manifest["artifacts"]["decisions"])
            window_refs.append(source_ref(window_manifest_path))
            all_decision_rows += int(manifest["population"]["target_count"])
            all_family_changes += int(manifest["outcome_blind_audit"]["top1_family_changed"])
            all_exact_changes += int(manifest["outcome_blind_audit"]["top1_exact_changed"])
            all_missing += int(manifest["outcome_blind_audit"]["either_branch_missing"])
            compile_seconds += float(manifest["runtime"]["compile_seconds"])
            print(f"{window_id}: verified existing partial freeze", flush=True)
            continue

        window_contexts = {
            context_key(target_contexts[trace_id]): target_contexts[trace_id]
            for trace_id in target_ids[window_id]
        }
        if index == 0:
            adaptive_by_context = {key: static_by_context[key] for key in window_contexts}
            p0_item = init["initialization"]["history_artifact"]
            history_meta = {
                "history_count": int(p0_item["rows"]),
                "history_id_sha256": str(init["initialization"]["history_id_sha256"]),
                "late_pre_cutoff_admitted": 0,
                "prior_replay_admitted": 0,
                "history_cutoff": str(window["start"]),
            }
            this_compile_seconds = 0.0
        else:
            print(f"{window_id}: reconstructing causal history", flush=True)
            histories, history_meta = reconstruct_window_histories(
                unified=unified,
                split=split,
                init=init,
                window_index=index,
            )
            expected_manifest = read_json(
                ROOT / unified["outputs"]["result_root"] / "windows" / window_id / "prepare" / "manifest.json"
            )
            if history_meta["history_count"] != int(expected_manifest["memory"]["adaptive_history_count"]):
                raise ValueError(f"adaptive history count mismatch: {window_id}")
            if history_meta["history_id_sha256"] != str(expected_manifest["memory"]["adaptive_history_id_sha256"]):
                raise ValueError(f"adaptive history hash mismatch: {window_id}")
            print(
                f"{window_id}: compiling {len(histories):,} legally visible histories; "
                f"contexts={len(window_contexts):,}",
                flush=True,
            )
            compiled = compile_version(histories, read_json(ROOT / unified["dependencies"]["phase2_compilation_config"]))
            this_compile_seconds = float(compiled["compile_seconds"])
            adaptive_memories = list(compiled["memories"])
            adaptive_artifacts = selector_artifacts(adaptive_memories)
            adaptive_by_context = {
                key: select_structural(
                    context=context,
                    memories=adaptive_memories,
                    artifacts=adaptive_artifacts,
                    limit=limit,
                )
                for key, context in sorted(window_contexts.items())
            }
            del adaptive_artifacts, adaptive_memories, compiled, histories
            gc.collect()

        rows: list[dict[str, Any]] = []
        family_changed = 0
        exact_changed = 0
        missing = 0
        for trace_id in target_ids[window_id]:
            key = context_key(target_contexts[trace_id])
            static = static_by_context[key]
            adaptive = adaptive_by_context[key]
            family_changed += int(static["selected_action_family"] != adaptive["selected_action_family"])
            exact_changed += int(static["selected_action"] != adaptive["selected_action"])
            missing += int(not static["selected_action"] or not adaptive["selected_action"])
            row = {
                "trace_id": trace_id,
                "window_id": window_id,
                "structural_context_hash": key,
                "memory": {
                    "static_version": "P0_unified",
                    "adaptive_version": f"P_unified_{window_id}_START",
                    "adaptive_history_count": history_meta["history_count"],
                    "adaptive_history_id_sha256": history_meta["history_id_sha256"],
                    "history_cutoff": history_meta["history_cutoff"],
                },
                "static": static,
                "adaptive": adaptive,
            }
            assert_outcome_blind(row)
            rows.append(row)
        decision_ref = write_jsonl(output_path, rows)
        window_manifest = {
            "schema_version": "jsac.temporal_table2a_window_freeze.v1",
            "status": "OUTCOME_BLIND_SELECTIONS_FROZEN",
            "window_id": window_id,
            "population": {
                "target_count": len(rows),
                "target_id_sha256": id_hash(row["trace_id"] for row in rows),
                "unique_structural_context_count": len(window_contexts),
            },
            "memory": history_meta,
            "outcome_blind_audit": {
                "top1_family_changed": family_changed,
                "top1_exact_changed": exact_changed,
                "either_branch_missing": missing,
                "all_rows_contain_no_target_action_outcome_or_gold": True,
            },
            "runtime": {"compile_seconds": this_compile_seconds},
            "artifacts": {"decisions": decision_ref},
        }
        write_json(window_manifest_path, window_manifest)
        window_refs.append(source_ref(window_manifest_path))
        all_decision_rows += len(rows)
        all_family_changes += family_changed
        all_exact_changes += exact_changed
        all_missing += missing
        compile_seconds += this_compile_seconds
        print(
            f"{window_id}: frozen targets={len(rows):,}; family changes={family_changed:,}; "
            f"compile={this_compile_seconds:.1f}s",
            flush=True,
        )

    manifest = {
        "schema_version": "jsac.temporal_table2a_selection_freeze.v1",
        "status": f"ALL_{len(split['replay']['windows'])}_WINDOWS_OUTCOME_BLIND_SELECTIONS_FROZEN; EVALUATION_AUTHORIZED",
        "scientific_role": config["scientific_role"],
        "method": {
            "source_method_id": config["dependencies"]["table2a_method_id"],
            "selection_projection": "same no_outcome_counts structural Top-1; downstream gate omitted because it cannot mutate selection",
            "candidate_limit": limit,
        },
        "population": {
            "window_count": len(split["replay"]["windows"]),
            "target_count": all_decision_rows,
            "expected_target_count": int(split["replay"]["target_count"]),
            "unique_structural_context_count": len(all_contexts),
        },
        "outcome_blind_audit": {
            "top1_family_changed": all_family_changes,
            "top1_family_change_rate": all_family_changes / all_decision_rows,
            "top1_exact_changed": all_exact_changes,
            "either_branch_missing": all_missing,
            "all_targets_selected_before_pass_only_evaluation": True,
            "target_actions_outcomes_and_gold_absent": True,
            "all_replay_windows_frozen_before_evaluation": True,
        },
        "runtime": {"cumulative_compile_seconds": compile_seconds},
        "sources": {
            "config": source_ref(config_path),
            "unified_replay_config": source_ref(unified_path),
            "split_audit": source_ref(ROOT / unified["outputs"]["split_audit"]),
            "initialization_manifest": source_ref(ROOT / unified["outputs"]["initialization_manifest"]),
            "window_manifests": window_refs,
            "runner": source_ref(Path(__file__).resolve()),
        },
    }
    if all_decision_rows != int(split["replay"]["target_count"]):
        raise ValueError("selection freeze target coverage is incomplete")
    write_json(freeze_root / "manifest.json", manifest)
    print(json.dumps(manifest["population"] | manifest["outcome_blind_audit"], ensure_ascii=False, indent=2), flush=True)


def evaluate(config_path: Path) -> None:
    config, unified, split, init, unified_path = load_contract(config_path)
    del init, unified_path
    result_root = ROOT / config["outputs"]["result_root"]
    freeze_root = result_root / "freeze"
    freeze_manifest_path = freeze_root / "manifest.json"
    freeze_manifest = read_json(freeze_manifest_path)
    expected_status = (
        f"ALL_{freeze_manifest['population']['window_count']}_WINDOWS_"
        "OUTCOME_BLIND_SELECTIONS_FROZEN; EVALUATION_AUTHORIZED"
    )
    if freeze_manifest["status"] != expected_status:
        raise ValueError("complete outcome-blind selection freeze is missing")
    target_ids, target_to_window = frozen_target_ids(unified, split)
    decisions: dict[str, dict[str, Any]] = {}
    decision_sources: list[dict[str, Any]] = []
    for window in split["replay"]["windows"]:
        window_id = str(window["window_id"])
        manifest_path = freeze_root / "windows" / window_id / "manifest.json"
        manifest = read_json(manifest_path)
        path = verify_ref(manifest["artifacts"]["decisions"])
        ids: list[str] = []
        for row in cio.read_jsonl(path):
            assert_outcome_blind(row)
            trace_id = str(row["trace_id"])
            if trace_id in decisions:
                raise ValueError(f"duplicate frozen decision: {trace_id}")
            decisions[trace_id] = row
            ids.append(trace_id)
        if sorted(ids) != target_ids[window_id]:
            raise ValueError(f"frozen decision population changed: {window_id}")
        decision_sources.append(source_ref(path))
    if set(decisions) != set(target_to_window):
        raise ValueError("frozen decision population is incomplete")

    details: list[dict[str, Any]] = []
    exclusions: Counter[str] = Counter()
    for spec in unified["source"]["canonical_partitions"]:
        path = ROOT / spec["path"]
        count = 0
        for trace in cio.read_jsonl(path):
            count += 1
            trace_id = str(trace.get("trace_id") or "")
            decision = decisions.get(trace_id)
            if decision is None:
                continue
            outcome = str((trace.get("aggregate") or {}).get("ticket_outcome") or "")
            if outcome != "long_eval_pass":
                exclusions[f"target_outcome:{outcome or 'missing'}"] += 1
                continue
            gold_actions = observed_pass_actions(trace)
            if not gold_actions:
                exclusions["pass_without_eligible_observed_action"] += 1
                continue
            cohort = "strict_single" if len(gold_actions) == 1 else "multi_bundle"
            static_hit, static_level = candidate_hit(
                {"action": decision["static"]["selected_action"]}, trace, gold_actions
            )
            adaptive_hit, adaptive_level = candidate_hit(
                {"action": decision["adaptive"]["selected_action"]}, trace, gold_actions
            )
            k = int(config["evaluation"]["candidate_ceiling_k"])
            static_candidates = decision["static"]["candidates"][:k]
            adaptive_candidates = decision["adaptive"]["candidates"][:k]
            static_ceiling = any(candidate_hit(item, trace, gold_actions)[0] for item in static_candidates)
            adaptive_ceiling = any(candidate_hit(item, trace, gold_actions)[0] for item in adaptive_candidates)
            ticket = trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}
            details.append({
                "trace_id": trace_id,
                "window_id": decision["window_id"],
                "site_name": str(ticket.get("site_name") or trace_id),
                "cohort": cohort,
                "paired_state_cluster_id": canonical_hash({
                    "static": decision["static"]["selected_action_family"],
                    "adaptive": decision["adaptive"]["selected_action_family"],
                }),
                "gold_action_count": len(gold_actions),
                "selection_family_changed": decision["static"]["selected_action_family"] != decision["adaptive"]["selected_action_family"],
                "static_selected_family": decision["static"]["selected_action_family"],
                "adaptive_selected_family": decision["adaptive"]["selected_action_family"],
                "static_hit": bool(static_hit),
                "adaptive_hit": bool(adaptive_hit),
                "static_match_level": static_level,
                "adaptive_match_level": adaptive_level,
                "static_ceiling_at_5": bool(static_ceiling),
                "adaptive_ceiling_at_5": bool(adaptive_ceiling),
            })
        if count != int(spec["expected_count"]):
            raise ValueError(f"source count changed: {path}")

    detail_path = result_root / "evaluation" / "pass_readout_rows.jsonl"
    detail_ref = write_jsonl(detail_path, details)
    rows_by_cohort = {
        cohort: [row for row in details if row["cohort"] == cohort]
        for cohort in ("strict_single", "multi_bundle")
    }
    comparisons = {
        cohort: paired_statistics(rows, seed=20260825 + index * 100)
        for index, (cohort, rows) in enumerate(rows_by_cohort.items())
    }
    raw_p = {
        cohort: float(result["adaptive_minus_static"]["paired_sign_flip_raw_p"])
        for cohort, result in comparisons.items()
    }
    adjusted = holm_adjust(raw_p)
    cohort_results: dict[str, Any] = {}
    per_window: dict[str, Any] = {}
    for cohort, rows in rows_by_cohort.items():
        n = len(rows)
        static_hits = sum(row["static_hit"] for row in rows)
        adaptive_hits = sum(row["adaptive_hit"] for row in rows)
        contrast = comparisons[cohort]["adaptive_minus_static"]
        contrast["holm_adjusted_p"] = adjusted[cohort]
        contrast["improvement_claim_permitted"] = (
            contrast["rate_difference"] > 0
            and adjusted[cohort] < 0.05
            and contrast["ticket_bootstrap"]["ci_95"][0] > 0
            and contrast["site_cluster_bootstrap"]["ci_95"][0] > 0
        )
        cohort_results[cohort] = {
            "metric": "SSAPS" if cohort == "strict_single" else "MHCM@1",
            "target_count": n,
            "static": ratio(static_hits, n),
            "adaptive": ratio(adaptive_hits, n),
            "adaptive_minus_static": contrast,
            "net_additional_hits": adaptive_hits - static_hits,
            "adaptive_only_hits": sum(row["adaptive_hit"] and not row["static_hit"] for row in rows),
            "static_only_hits": sum(row["static_hit"] and not row["adaptive_hit"] for row in rows),
            "selection_family_changed": ratio(sum(row["selection_family_changed"] for row in rows), n),
            "static_ceiling_at_5": ratio(sum(row["static_ceiling_at_5"] for row in rows), n),
            "adaptive_ceiling_at_5": ratio(sum(row["adaptive_ceiling_at_5"] for row in rows), n),
        }
        grouped: dict[str, list[dict[str, Any]]] = defaultdict(list)
        for row in rows:
            grouped[row["window_id"]].append(row)
        cumulative_n = cumulative_static = cumulative_adaptive = 0
        window_rows: list[dict[str, Any]] = []
        for window in split["replay"]["windows"]:
            window_id = str(window["window_id"])
            current = grouped.get(window_id, [])
            current_static = sum(row["static_hit"] for row in current)
            current_adaptive = sum(row["adaptive_hit"] for row in current)
            cumulative_n += len(current)
            cumulative_static += current_static
            cumulative_adaptive += current_adaptive
            window_rows.append({
                "window_id": window_id,
                "target_count": len(current),
                "static_hits": current_static,
                "adaptive_hits": current_adaptive,
                "net_additional_hits": current_adaptive - current_static,
                "static_rate": current_static / len(current) if current else None,
                "adaptive_rate": current_adaptive / len(current) if current else None,
                "cumulative_target_count": cumulative_n,
                "cumulative_static_rate": cumulative_static / cumulative_n if cumulative_n else None,
                "cumulative_adaptive_rate": cumulative_adaptive / cumulative_n if cumulative_n else None,
                "cumulative_net_additional_hits": cumulative_adaptive - cumulative_static,
            })
        per_window[cohort] = window_rows

    result = {
        "schema_version": "jsac.temporal_table2a_positive_reuse_result.v1",
        "status": "COMPLETED_AFTER_OUTCOME_BLIND_SELECTION_FREEZE",
        "scientific_role": config["scientific_role"],
        "population": {
            "all_targets_selected_before_reveal": len(decisions),
            "pass_readout_targets": len(details),
            "cohorts": {key: len(value) for key, value in rows_by_cohort.items()},
            "post_reveal_exclusions": dict(sorted(exclusions.items())),
        },
        "outcome_blind_selection_audit": freeze_manifest["outcome_blind_audit"],
        "cohort_results": cohort_results,
        "per_window": per_window,
        "claim_boundary": config["evaluation"]["claim_boundary"],
        "integrity": {
            "all_replay_windows_frozen_before_evaluation": True,
            "all_replay_targets_have_paired_static_adaptive_choices": len(decisions) == int(split["replay"]["target_count"]),
            "static_adaptive_target_sets_identical": True,
            "target_outcomes_not_used_by_selector": True,
            "pass_subset_created_only_in_evaluator": True,
            "candidate_equivalence_matches_table2a": True,
        },
        "artifacts": {
            "selection_freeze_manifest": source_ref(freeze_manifest_path),
            "evaluation_runner": source_ref(Path(__file__).resolve()),
            "evaluation_config": source_ref(config_path),
            "decision_sources": decision_sources,
            "pass_readout_rows": detail_ref,
        },
    }
    retained_path = ROOT / config["outputs"]["retained_result"]
    write_json(retained_path, result)
    write_json(result_root / "evaluation" / "result.json", result)
    write_report(ROOT / config["outputs"]["report"], result)
    print(json.dumps({"population": result["population"], "cohorts": cohort_results}, ensure_ascii=False, indent=2), flush=True)


def write_report(path: Path, result: dict[str, Any]) -> None:
    strict = result["cohort_results"]["strict_single"]
    multi = result["cohort_results"]["multi_bundle"]
    strict_diff = strict["adaptive_minus_static"]
    multi_diff = multi["adaptive_minus_static"]
    strict_state_ci = strict_diff["paired_state_cluster_sensitivity"]["ci_95"]
    strict_state_note = (
        "crosses zero"
        if strict_state_ci[0] <= 0 <= strict_state_ci[1]
        else "excludes zero"
    )
    def pp_interval(values: list[float]) -> str:
        return f"[{values[0] * 100:+.3f}, {values[1] * 100:+.3f}] pp"
    lines = [
        "# Temporal Table 2A Positive-Reuse Replay",
        "",
        f"Status: **{result['status']}**. Scientific role: `{result['scientific_role']}`.",
        "",
        "All replay targets received paired Static/Adaptive selections before the evaluator created the Pass-only cohorts.",
        "",
        f"All-target freeze: {result['population']['all_targets_selected_before_reveal']:,}. Post-freeze Pass readout population: {result['population']['pass_readout_targets']:,}.",
        "",
        "| Cohort | Metric | Static | Adaptive | Net hits / difference | Ticket 95% CI | Site 95% CI |",
        "|---|---:|---:|---:|---:|---:|---:|",
        f"| strict single | SSAPS | {strict['static']['value']:.2%} ({strict['static']['numerator']}/{strict['static']['denominator']}) | {strict['adaptive']['value']:.2%} ({strict['adaptive']['numerator']}/{strict['adaptive']['denominator']}) | {strict['net_additional_hits']:+d} / {strict_diff['percentage_points']:+.3f} pp | {pp_interval(strict_diff['ticket_bootstrap']['ci_95'])} | {pp_interval(strict_diff['site_cluster_bootstrap']['ci_95'])} |",
        f"| multi action | MHCM@1 | {multi['static']['value']:.2%} ({multi['static']['numerator']}/{multi['static']['denominator']}) | {multi['adaptive']['value']:.2%} ({multi['adaptive']['numerator']}/{multi['adaptive']['denominator']}) | {multi['net_additional_hits']:+d} / {multi_diff['percentage_points']:+.3f} pp | {pp_interval(multi_diff['ticket_bootstrap']['ci_95'])} | {pp_interval(multi_diff['site_cluster_bootstrap']['ci_95'])} |",
        "",
        f"Paired-state-cluster sensitivity: strict {pp_interval(strict_state_ci)}; multi {pp_interval(multi_diff['paired_state_cluster_sensitivity']['ci_95'])}. The strict interval {strict_state_note} under this coarser repeated-state resampling.",
        "",
        "This is historical successful-action readout, not recommendation success or a counterfactual claim about an unexecuted action.",
    ]
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--config", type=Path, default=DEFAULT_CONFIG)
    parser.add_argument("--stage", choices=("freeze", "evaluate", "all"), default="all")
    args = parser.parse_args()
    config_path = args.config if args.config.is_absolute() else ROOT / args.config
    started = time.perf_counter()
    if args.stage in {"freeze", "all"}:
        freeze(config_path)
    if args.stage in {"evaluate", "all"}:
        evaluate(config_path)
    print(f"elapsed_seconds={time.perf_counter() - started:.1f}", flush=True)


if __name__ == "__main__":
    main()

"""Reviewed action ontology labels for compiler-side semantic tagging.

These labels are not executable action templates. They are semantic tags over
train-only action signatures and must preserve the original vendor/RAT/scheme/
parameter/value/boundary identity for any final decision.
"""

from __future__ import annotations

import csv
import hashlib
import json
import math
import re
from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path
from typing import Any

from . import paths as P
from .parameter_range import to_number


LABEL_ROLE = "semantic_label_not_executable_template"
SOURCE_VERSION = "reviewed_label_ontology_v2"
SIGNATURE_ALGORITHM_VERSION = "action_signature_hash_v1_1"


def _norm(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, float) and math.isnan(value):
        return ""
    text = str(value).strip()
    if text.lower() in {"nan", "nat", "none", "null"}:
        return ""
    return text


def _compact(value: Any, limit: int = 120) -> str:
    text = re.sub(r"\s+", " ", _norm(value))
    if len(text) <= limit:
        return text
    return text[: limit - 3].rstrip() + "..."


def _signature_hash(parts: list[str]) -> str:
    raw = json.dumps(parts, ensure_ascii=False, separators=(",", ":"))
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()[:14]


def _seed_value_shape(before: Any, after: Any) -> dict[str, Any]:
    """Match scripts/export_action_ontology_llm_seed.py signature grouping."""
    before_text = _norm(before)
    after_text = _norm(after)
    before_num = to_number(before_text)
    after_num = to_number(after_text)
    if before_num is not None and after_num is not None:
        delta = round(after_num - before_num, 6)
        if delta > 0:
            direction = "increase"
        elif delta < 0:
            direction = "decrease"
        else:
            direction = "unchanged"
        return {"value_type": "numeric", "numeric_direction": direction}

    before_lower = before_text.lower()
    after_lower = after_text.lower()
    off_tokens = ("-0", "_0", "off", "false", "disable", "disabled", "guan", "关")
    on_tokens = ("-1", "_1", "on", "true", "enable", "enabled", "kai", "开")
    if any(token in before_lower for token in off_tokens) and any(token in after_lower for token in on_tokens):
        return {"value_type": "bool_or_switch", "numeric_direction": "enable"}
    if any(token in before_lower for token in on_tokens) and any(token in after_lower for token in off_tokens):
        return {"value_type": "bool_or_switch", "numeric_direction": "disable"}
    return {"value_type": "enum_or_text", "numeric_direction": "switch_enum"}


def action_ontology_signature_id(ticket: dict[str, Any], action: dict[str, Any]) -> str:
    """Return the train-only action ontology signature id for one trace action."""
    shape = _seed_value_shape(action.get("before_value"), action.get("after_value"))
    key_parts = [
        _compact(ticket.get("vendor"), 60),
        _compact(ticket.get("system"), 40),
        _compact(action.get("scheme_id"), 80),
        _compact(action.get("root_cause_l2") or action.get("scheme_group"), 100),
        _compact(action.get("root_cause_l1") or action.get("param_kind"), 80),
        _compact(action.get("root_cause_l2") or action.get("scheme_group"), 100),
        _compact(action.get("scheme_type3"), 140),
        _compact(action.get("param_object"), 100),
        _compact(action.get("param_en_name"), 100),
        _compact(action.get("param_cn_name"), 100),
        _compact(action.get("operation_summary"), 100),
        _compact(action.get("operation_detail"), 140),
        _compact(action.get("operation_delta_hint"), 140),
        _compact(action.get("parameter_group"), 80),
        shape["value_type"],
        shape["numeric_direction"],
    ]
    return _signature_hash(key_parts)


def _boolish(value: Any) -> bool:
    return str(value or "").strip().lower() in {"true", "1", "yes", "y"}


@dataclass(frozen=True)
class ActionOntologyStore:
    candidates_by_signature: dict[str, dict[str, Any]]
    policy_by_signature: dict[str, dict[str, Any]]
    source_available: bool
    source_paths: dict[str, str]

    def label_for(self, ticket: dict[str, Any], action: dict[str, Any]) -> dict[str, Any]:
        signature_id = action_ontology_signature_id(ticket, action)
        candidate = self.candidates_by_signature.get(signature_id)
        policy = self.policy_by_signature.get(signature_id, {})
        if not candidate:
            return {
                "source_version": SOURCE_VERSION,
                "signature_algorithm_version": SIGNATURE_ALGORITHM_VERSION,
                "label_role": LABEL_ROLE,
                "ontology_status": "unmapped",
                "ontology_signature_id": signature_id,
                "hard_aggregation_policy": "blocked",
                "policy_reason": "signature not covered by reviewed action ontology",
            }

        return {
            "source_version": SOURCE_VERSION,
            "signature_algorithm_version": SIGNATURE_ALGORITHM_VERSION,
            "label_role": LABEL_ROLE,
            "ontology_status": "mapped",
            "ontology_signature_id": signature_id,
            "canonical_action_id": candidate.get("canonical_action_id"),
            "parameter_concept_id": candidate.get("parameter_concept_id"),
            "operation_family": candidate.get("operation_family"),
            "object_scope": candidate.get("object_scope"),
            "label_value_type": candidate.get("value_type"),
            "label_numeric_direction": candidate.get("numeric_direction"),
            "effect_direction": candidate.get("effect_direction"),
            "equivalence_level": candidate.get("equivalence_level"),
            "confidence": candidate.get("confidence"),
            "hard_aggregation_policy": policy.get("hard_aggregation_policy") or "allowed",
            "normalization_confidence": policy.get("normalization_confidence") or "",
            "parent_only": _boolish(policy.get("parent_only")),
            "requires_vendor_semantics_confirmation": _boolish(policy.get("requires_vendor_semantics_confirmation")),
            "normalized_set_change": policy.get("normalized_set_change") or "",
            "policy_bundle_id": policy.get("bundle_id") or "",
            "policy_patch_action": policy.get("patch_action") or "",
            "policy_notes": policy.get("notes") or "",
        }

    def artifact_summary(self) -> dict[str, Any]:
        policies = [row.get("hard_aggregation_policy") or "allowed" for row in self.policy_by_signature.values()]
        return {
            "source_version": SOURCE_VERSION,
            "signature_algorithm_version": SIGNATURE_ALGORITHM_VERSION,
            "source_available": self.source_available,
            "source_paths": self.source_paths,
            "candidate_count": len(self.candidates_by_signature),
            "policy_count": len(self.policy_by_signature),
            "hard_aggregation_policy_distribution": {
                key: policies.count(key)
                for key in sorted(set(policies))
            },
        }


def _read_csv(path: Path) -> list[dict[str, str]]:
    with path.open(encoding="utf-8-sig", newline="") as f:
        return list(csv.DictReader(f))


@lru_cache(maxsize=1)
def load_action_ontology_store() -> ActionOntologyStore:
    draft_path = P.ACTION_ONTOLOGY_REVIEWED_DRAFT_JSON
    policy_path = P.ACTION_ONTOLOGY_SIGNATURE_POLICY_CSV
    source_paths = {
        "reviewed_draft": str(draft_path),
        "signature_policy": str(policy_path),
        "link_policy": str(P.ACTION_ONTOLOGY_LINK_POLICY_CSV),
    }
    if not draft_path.exists() or not policy_path.exists():
        return ActionOntologyStore({}, {}, False, source_paths)

    draft = json.loads(draft_path.read_text(encoding="utf-8"))
    candidates = {
        str(row["signature_id"]): row
        for row in draft.get("ontology_candidates", [])
        if row.get("signature_id")
    }
    policies = {
        str(row["signature_id"]): row
        for row in _read_csv(policy_path)
        if row.get("signature_id")
    }
    return ActionOntologyStore(candidates, policies, True, source_paths)

"""JSONL 读写、安全序列化、去重落盘。"""

from __future__ import annotations

import json
import os
from datetime import datetime
from pathlib import Path
from typing import Any, Iterable, Iterator


def now_iso() -> str:
    return datetime.now().astimezone().isoformat(timespec="seconds")


def read_jsonl(path: Path | str) -> Iterator[dict]:
    path = Path(path)
    if not path.exists():
        return
    with path.open("r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            yield json.loads(line)


def write_jsonl(path: Path | str, records: Iterable[dict]) -> int:
    """原子写入：先写 .tmp 再 replace，避免读端在半写入时解码失败。"""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(f"{path.name}.{os.getpid()}.tmp")
    count = 0
    try:
        with tmp.open("w", encoding="utf-8") as f:
            for r in records:
                f.write(json.dumps(r, ensure_ascii=False, default=_json_fallback) + "\n")
                count += 1
        tmp.replace(path)
    except Exception:
        if tmp.exists():
            tmp.unlink(missing_ok=True)
        raise
    return count


def append_jsonl(path: Path | str, records: Iterable[dict]) -> int:
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    count = 0
    with path.open("a", encoding="utf-8") as f:
        for r in records:
            f.write(json.dumps(r, ensure_ascii=False, default=_json_fallback) + "\n")
            count += 1
    return count


def _json_fallback(o: Any):
    if isinstance(o, datetime):
        return o.isoformat()
    if hasattr(o, "isoformat"):
        return o.isoformat()
    return str(o)


def safe_get(d: dict, *keys, default=None):
    cur: Any = d
    for k in keys:
        if not isinstance(cur, dict) or k not in cur:
            return default
        cur = cur[k]
    return cur

"""参数取值域解析与全量数据范围修复（effective / range_repair）。

厂商 Excel 常只给出半边界（如 ``<= -120``）。编译时用全量 trace 上同方案+参数的
before/after 数值 min/max 补缺失侧，生成 ``effective_parameter_range``，不覆盖原始
``parameter_range``。
"""

from __future__ import annotations

import re
from collections import defaultdict
from typing import Any

REPAIR_INDEX_VERSION = 1


def slug(s: object) -> str:
    text = str(s or "unknown").strip().lower()
    text = re.sub(r"\s+", "_", text)
    text = re.sub(r"[^0-9a-zA-Z_\-\u4e00-\u9fff]+", "_", text)
    return text.strip("_") or "unknown"


def to_number(v: object) -> float | None:
    if v is None:
        return None
    text = str(v).strip()
    if not text or text.lower() in {"nan", "nat", "none", "null"}:
        return None
    if not re.fullmatch(r"[+-]?\d+(?:\.\d+)?", text):
        return None
    try:
        return float(text)
    except ValueError:
        return None


def parse_parameter_range(value_rule: object) -> dict | None:
    """Parse vendor scheme_desc / value_rule into explicit or partial range."""
    if value_rule is None:
        return None
    raw = str(value_rule).strip()
    if not raw or raw.lower() in {"nan", "none", "null"}:
        return None

    normalized = raw.replace("～", "~").replace("—", "~").replace("–", "~")

    # 中兴等方案描述：[-140..-44];step 2 或 [0..62];step 2
    bracket_step = re.fullmatch(
        r"\s*\[\s*([+-]?\d+(?:\.\d+)?)\s*\.\.\s*([+-]?\d+(?:\.\d+)?)\s*\]\s*;\s*step\s*([+-]?\d+(?:\.\d+)?)\s*",
        normalized,
        flags=re.IGNORECASE,
    )
    if bracket_step:
        lo = float(bracket_step.group(1))
        hi = float(bracket_step.group(2))
        step = float(bracket_step.group(3))
        if lo > hi:
            lo, hi = hi, lo
        return {
            "raw": raw,
            "min": lo,
            "max": hi,
            "step": step,
            "operator": "between",
            "limit": None,
            "source": "value_rule",
            "confidence": "parsed",
            "complete": True,
        }

    bracket_only = re.fullmatch(
        r"\s*\[\s*([+-]?\d+(?:\.\d+)?)\s*\.\.\s*([+-]?\d+(?:\.\d+)?)\s*\]\s*",
        normalized,
    )
    if bracket_only:
        lo = float(bracket_only.group(1))
        hi = float(bracket_only.group(2))
        if lo > hi:
            lo, hi = hi, lo
        return {
            "raw": raw,
            "min": lo,
            "max": hi,
            "step": None,
            "operator": "between",
            "limit": None,
            "source": "value_rule",
            "confidence": "parsed",
            "complete": True,
        }

    range_match = re.fullmatch(
        r"\s*([+-]?\d+(?:\.\d+)?)\s*[~]\s*([+-]?\d+(?:\.\d+)?)\s*",
        normalized,
    )
    if not range_match:
        range_match = re.fullmatch(
            r"\s*(\d+(?:\.\d+)?)\s*-\s*(\d+(?:\.\d+)?)\s*",
            normalized,
        )
    if range_match:
        lo = float(range_match.group(1))
        hi = float(range_match.group(2))
        if lo > hi:
            lo, hi = hi, lo
        return {
            "raw": raw,
            "min": lo,
            "max": hi,
            "operator": "between",
            "limit": None,
            "source": "value_rule",
            "confidence": "parsed",
            "complete": True,
        }

    bound_match = re.fullmatch(r"\s*(<=|<|>=|>)\s*([+-]?\d+(?:\.\d+)?)\s*", normalized)
    if bound_match:
        op = bound_match.group(1)
        val = float(bound_match.group(2))
        return {
            "raw": raw,
            "min": val if op in {">", ">="} else None,
            "max": val if op in {"<", "<="} else None,
            "operator": op,
            "limit": val,
            "source": "value_rule",
            "confidence": "partial",
            "complete": False,
        }

    return {
        "raw": raw,
        "min": None,
        "max": None,
        "operator": None,
        "limit": None,
        "source": "value_rule",
        "confidence": "unparsed",
        "complete": False,
    }


def action_vendor_parameter_range(action: dict) -> dict | None:
    """Prefer scheme_desc; use value_rule when scheme_desc missing or unparsed."""
    scheme_range = parse_parameter_range(action.get("scheme_desc"))
    value_range = parse_parameter_range(action.get("value_rule"))
    if scheme_range:
        scheme_range = {**scheme_range, "source": "scheme_desc"}
    if value_range:
        value_range = {**value_range, "source": "value_rule"}
    if scheme_range and scheme_range.get("complete"):
        return scheme_range
    if scheme_range:
        return scheme_range
    return value_range


def semantic_param_id(action: dict, ticket: dict | None) -> str:
    ticket = ticket or {}
    vendor = slug(ticket.get("vendor"))
    system = slug(ticket.get("system"))
    param_object = slug(action.get("param_object"))
    param_name = slug(action.get("param_en_name") or action.get("param_cn_name"))
    return ".".join([vendor, system, param_object, param_name])


def range_repair_key(action: dict, ticket: dict | None = None) -> str:
    ticket = ticket or {}
    return "|".join([
        slug(ticket.get("vendor")),
        slug(ticket.get("system")),
        slug(action.get("scheme_id")),
        semantic_param_id(action, ticket),
    ])


def numeric_position(value: float | None, param_range: dict | None) -> float | None:
    if value is None or not param_range or not param_range.get("complete"):
        return None
    lo = param_range.get("min")
    hi = param_range.get("max")
    if lo is None or hi is None or hi == lo:
        return None
    return round((value - lo) / (hi - lo), 4)


def range_ratio(delta: float | None, param_range: dict | None) -> float | None:
    if delta is None or not param_range or not param_range.get("complete"):
        return None
    lo = param_range.get("min")
    hi = param_range.get("max")
    if lo is None or hi is None or hi == lo:
        return None
    return round(abs(delta) / abs(hi - lo), 4)


def build_range_repair_index(traces: list[dict]) -> dict[str, dict]:
    """Scan all traces; per scheme+param collect numeric before/after min/max."""
    buckets: dict[str, list[float]] = defaultdict(list)
    for trace in traces:
        ticket = trace.get("ticket") or {}
        for action in trace.get("actions") or []:
            key = range_repair_key(action, ticket)
            for field in ("before_value", "after_value"):
                num = to_number(action.get(field))
                if num is not None:
                    buckets[key].append(num)

    index: dict[str, dict] = {}
    for key, values in buckets.items():
        if len(values) < 2:
            continue
        lo = min(values)
        hi = max(values)
        if lo >= hi:
            continue
        index[key] = {
            "min": lo,
            "max": hi,
            "sample_count": len(values),
            "value_count": len(values),
        }
    return index


def build_effective_parameter_range(
    vendor_range: dict | None,
    repair_stats: dict | None,
) -> dict | None:
    """Merge dataset min/max with vendor partial bounds; skip if vendor already complete."""
    if vendor_range and vendor_range.get("complete"):
        return None
    if not repair_stats:
        return None

    observed_min = float(repair_stats["min"])
    observed_max = float(repair_stats["max"])
    if observed_min >= observed_max:
        return None

    eff_min = observed_min
    eff_max = observed_max
    filled: list[str] = []

    vendor_min = vendor_range.get("min") if vendor_range else None
    vendor_max = vendor_range.get("max") if vendor_range else None

    if vendor_min is not None:
        eff_min = max(eff_min, float(vendor_min))
    else:
        filled.append("min")

    if vendor_max is not None:
        eff_max = min(eff_max, float(vendor_max))
    else:
        filled.append("max")

    if eff_min >= eff_max:
        # 观测簇与半边界可能数值交叉（如 <=-120 但历史调到 -98）；用观测+厂商边界共同定端点
        endpoints = [observed_min, observed_max]
        if vendor_min is not None:
            endpoints.append(float(vendor_min))
        if vendor_max is not None:
            endpoints.append(float(vendor_max))
        eff_min = min(endpoints)
        eff_max = max(endpoints)
        if eff_min >= eff_max:
            return None

    raw_vendor = (vendor_range or {}).get("raw")
    return {
        "raw": f"{eff_min:g}~{eff_max:g}",
        "min": eff_min,
        "max": eff_max,
        "operator": "between",
        "limit": None,
        "source": "range_repair",
        "confidence": "dataset_inferred",
        "complete": True,
        "repair": {
            "filled": filled,
            "vendor_range": vendor_range,
            "observed_min": observed_min,
            "observed_max": observed_max,
            "sample_count": repair_stats.get("sample_count"),
            "index_version": REPAIR_INDEX_VERSION,
        },
    }


def resolve_action_ranges(
    action: dict,
    ticket: dict | None,
    repair_index: dict[str, dict] | None,
) -> tuple[dict | None, dict | None, dict | None]:
    """Return (vendor_parameter_range, effective_parameter_range, range_for_position)."""
    vendor = action_vendor_parameter_range(action)
    effective = None
    if repair_index is not None:
        stats = repair_index.get(range_repair_key(action, ticket))
        effective = build_effective_parameter_range(vendor, stats)

    position_range = vendor if vendor and vendor.get("complete") else effective
    return vendor, effective, position_range


def enrich_action_range_fields(
    action: dict,
    ticket: dict | None,
    repair_index: dict[str, dict] | None,
    *,
    include_positions: bool = True,
) -> dict[str, Any]:
    """Fields to merge onto trace actions or value_pattern dicts."""
    vendor, effective, position_range = resolve_action_ranges(action, ticket, repair_index)
    out: dict[str, Any] = {
        "parameter_range": vendor,
        "effective_parameter_range": effective,
    }
    if not include_positions:
        return out

    before_num = to_number(action.get("before_value"))
    after_num = to_number(action.get("after_value"))
    delta = (
        round(after_num - before_num, 6)
        if before_num is not None and after_num is not None
        else None
    )
    out.update({
        "before_position": numeric_position(before_num, position_range),
        "after_position": numeric_position(after_num, position_range),
        "delta_ratio": range_ratio(delta, position_range),
        "range_position_basis": (
            "vendor" if vendor and vendor.get("complete") else "effective" if effective else None
        ),
    })
    return out

"""Build Memory Evidence State sidecars for Phase-1 ECHO-Mem packages.

This stage is intentionally non-invasive: it reads compiled MemoryObject
records after state transition and scoring, then writes sidecars that make
support/counter/conflict/sparse evidence explicit for runtime consumers and
construction-time audits.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import sys
from collections import Counter
from pathlib import Path
from typing import Any

from ..common import io as cio
from ..common import paths as P
from ..common.schema_check import validate
