PRODUCER = "rule_v1.memory_evidence_profiles"
SCHEMA_VERSION = "memory_evidence_profile.v1"
MIXED_CONFLICT_MIN_COUNT = 3
MIXED_CONFLICT_RATE = 0.20
CHILD_MIN_EFFECTIVE_EVIDENCE = 3
CHILD_MIN_DIMENSION_COVERAGE = 1.0


def _profile_id(*parts: Any) -> str:
    raw = "|".join(str(part) for part in parts if part is not None)
    digest = hashlib.md5(raw.encode("utf-8")).hexdigest()[:12]
    return f"mep_{digest}"


def _safe_int(value: Any) -> int:
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return int(value)
    try:
        return int(value)
    except (TypeError, ValueError):
        return 0


def _safe_float(value: Any) -> float:
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return float(value)
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0


def _top_list(values: Any, limit: int = 8) -> list[Any]:
    if not isinstance(values, list):
        return []
    return values[:limit]


def _first(values: Any) -> Any:
    items = _top_list(values, 1)
    return items[0] if items else None


def _outcome_statistics(memory: dict[str, Any]) -> dict[str, Any]:
    metrics = memory.get("metrics") or {}
    pass_n = _safe_int(metrics.get("long_eval_pass_count"))
    fail_n = _safe_int(metrics.get("long_eval_fail_count"))
    mixed_n = _safe_int(metrics.get("long_eval_mixed_count"))
    unknown_n = _safe_int(metrics.get("long_eval_unknown_count"))
    support = _safe_int(metrics.get("support_count"))
    evaluated = pass_n + fail_n
    effective = evaluated + mixed_n
    pass_rate = pass_n / evaluated if evaluated else 0.0
    fail_rate = fail_n / evaluated if evaluated else 0.0
    mixed_rate = mixed_n / effective if effective else 0.0
    pass_cred = credibility_from_counts(pass_n, fail_n)
    fail_cred = credibility_from_counts(fail_n, pass_n)
    return {
        "support_count": support,
        "evaluated_count": evaluated,
        "effective_evidence_count": effective,
        "long_eval_pass_count": pass_n,
        "long_eval_fail_count": fail_n,
        "long_eval_mixed_count": mixed_n,
        "long_eval_unknown_count": unknown_n,
        "pass_rate": round(pass_rate, 6),
        "fail_rate": round(fail_rate, 6),
        "mixed_rate": round(mixed_rate, 6),
        "pass_posterior_mean": round(_safe_float(pass_cred.get("posterior_mean")), 6),
        "pass_lcb": round(_safe_float(pass_cred.get("credibility_lcb")), 6),
        "failure_posterior_mean": round(_safe_float(fail_cred.get("posterior_mean")), 6),
        "failure_lcb": round(_safe_float(fail_cred.get("credibility_lcb")), 6),
        "lcb_quantile": pass_cred.get("lcb_quantile"),
    }


def _support_profiles(memory: dict[str, Any]) -> list[dict[str, Any]]:
    content = memory.get("content") or {}
    profiles = content.get("support_profiles")
    return profiles if isinstance(profiles, list) else []


def _counter_action_profiles(memory: dict[str, Any]) -> list[dict[str, Any]]:
    content = memory.get("content") or {}
    profiles = content.get("action_profiles")
    return profiles if isinstance(profiles, list) else []


def _profile_type(memory: dict[str, Any], stats: dict[str, Any]) -> tuple[str, str, str]:
    memory_type = str(memory.get("memory_type") or "")
    state = str(memory.get("state") or "")
    pass_n = _safe_int(stats.get("long_eval_pass_count"))
    fail_n = _safe_int(stats.get("long_eval_fail_count"))
    mixed_n = _safe_int(stats.get("long_eval_mixed_count"))
    support = _safe_int(stats.get("support_count"))
    evaluated = _safe_int(stats.get("evaluated_count"))
    effective = _safe_int(stats.get("effective_evidence_count"))
    pass_lcb = _safe_float(stats.get("pass_lcb"))
    fail_lcb = _safe_float(stats.get("failure_lcb"))
    pass_rate = _safe_float(stats.get("pass_rate"))
    fail_rate = _safe_float(stats.get("fail_rate"))
    has_support = bool(_support_profiles(memory))

    if memory_type == "counter_evidence_memory" or state == "counter_evidence":
        return "counter_profile", "compiled_counter_evidence", "review_or_reject_by_specificity"

    if effective < 3 or support < 3:
        return "sparse_profile", "insufficient_evaluated_evidence", "rank_only_or_review"

    if (
        mixed_n >= MIXED_CONFLICT_MIN_COUNT
        and _safe_float(stats.get("mixed_rate")) >= MIXED_CONFLICT_RATE
    ):
        return "conflict_profile", "bundle_mixed_outcome_evidence", "review"

    if pass_n > 0 and fail_n > 0 and (
        state == "restricted"
        or (pass_lcb >= 0.25 and fail_lcb >= 0.20)
        or (0.30 <= pass_rate <= 0.70 and fail_rate >= 0.20)
    ):
        return "conflict_profile", "positive_and_negative_evidence_compete", "review"

    if has_support and fail_rate <= 0.20 and pass_lcb >= 0.35:
        return "support_profile", "embedded_hard_support_profile", "support_rank_if_no_counter"

    if pass_lcb >= 0.45 and pass_rate >= 0.70 and fail_rate <= 0.20:
        return "support_profile", "positive_lcb_with_low_failure_pollution", "support_rank_if_no_counter"

    if fail_n >= 3 and fail_rate >= 0.60:
        return "counter_profile", "failure_majority_with_sufficient_count", "review_or_reject_by_specificity"

    if state == "restricted":
        return "conflict_profile", "restricted_state_without_clean_support", "review"

    return "sparse_profile", "posterior_uncertainty_or_weak_evidence", "rank_only_or_review"


def _collapse_conflict_or_sparse(
    profile_type: str,
    conflict_reason: str,
    routing: str,
    stats: dict[str, Any],
) -> tuple[str, str, str]:
    """Ablation helper: remove explicit conflict/sparse states.

    C8-minus-conflict-resolution keeps support/counter statistics available
    but does not expose conflict/sparse as first-class routing states. Ambiguous
    evidence is forced to the dominant polarity, which is exactly the behavior
    this ablation is meant to contrast with conflict-as-review.
    """
    if profile_type not in {"conflict_profile", "sparse_profile"}:
        return profile_type, conflict_reason, routing
    pass_n = _safe_int(stats.get("long_eval_pass_count"))
    fail_n = _safe_int(stats.get("long_eval_fail_count"))
    if fail_n > pass_n:
        return (
            "counter_profile",
            f"{conflict_reason}; conflict_resolution_disabled_forced_counter",
            "review_or_reject_by_specificity",
        )
    return (
        "support_profile",
        f"{conflict_reason}; conflict_resolution_disabled_forced_support",
        "support_rank_if_no_counter",
    )


def _key_family(memory: dict[str, Any]) -> tuple[str, dict[str, Any], list[str]]:
    memory_type = str(memory.get("memory_type") or "")
    content = memory.get("content") or {}
    app = memory.get("applicability") or {}
    fields = ["issue_type", "vendor", "system"]

    if memory_type == "strategy_memory":
        pattern = content.get("value_pattern") or {}
        key_values = {
            "issue_type": content.get("issue_type") or _first(app.get("issue_types")),
            "vendor": content.get("vendor"),
            "system": content.get("system"),
            "scheme_id": content.get("scheme_id"),
            "parameter_semantic_id": content.get("parameter_semantic_id"),
            "direction": pattern.get("direction"),
            "value_shape": pattern.get("normalized_shape_id") or pattern.get("delta_bucket") or pattern.get("pattern_id"),
        }
        fields.extend(["scheme_id", "parameter_semantic_id", "direction", "value_shape"])
        return "strategy_action_shape", key_values, fields

    if memory_type == "playbook_memory":
        key_values = {
            "issue_type": content.get("issue_type") or _first(app.get("issue_types")),
            "vendor": content.get("vendor"),
            "system": content.get("system"),
            "scheme_group": content.get("scheme_group") or _first(app.get("scheme_groups")),
            "component_count": content.get("action_count"),
        }
        fields.extend(["scheme_group", "component_count"])
        return "playbook_component_set", key_values, fields

    if memory_type == "counter_evidence_memory":
        key_values = {
            "issue_type": content.get("issue_type") or _first(app.get("issue_types")),
            "scheme_id": content.get("scheme_id"),
            "scheme_group": content.get("scheme_group") or _first(app.get("scheme_groups")),
            "aggregation": content.get("aggregation"),
        }
        fields.extend(["scheme_id", "scheme_group", "aggregation", "action_profiles"])
        return "counter_issue_scheme", key_values, fields

    key_values = {
        "issue_types": app.get("issue_types") or [],
        "scheme_ids": app.get("scheme_ids") or [],
        "scheme_groups": app.get("scheme_groups") or [],
    }
    return memory_type or "memory", key_values, fields


def _boundary_context(memory: dict[str, Any]) -> dict[str, Any]:
    app = memory.get("applicability") or {}
    content = memory.get("content") or {}
    context = content.get("context_profile") if isinstance(content.get("context_profile"), dict) else {}
    return {
        "issue_types": app.get("issue_types") or [],
        "root_causes": app.get("root_causes") or app.get("solution_proxy_root_causes") or [],
        "vendors": app.get("vendors") or [],
        "systems": app.get("systems") or [],
        "regions": app.get("regions") or context.get("regions") or [],
        "bands": app.get("bands") or context.get("bands") or [],
        "indoor_outdoor": app.get("indoor_outdoor") or context.get("indoor_outdoor") or [],
        "exclusions": app.get("exclusions") or [],
    }


def _action_semantics(memory: dict[str, Any]) -> dict[str, Any]:
    content = memory.get("content") or {}
    pattern = content.get("value_pattern") or {}
    if memory.get("memory_type") == "playbook_memory":
        components = content.get("components") or []
        return {
            "scheme_group": content.get("scheme_group"),
            "component_count": len(components),
            "component_action_semantics": [
                {
                    "scheme_id": comp.get("scheme_id"),
                    "parameter_semantic_id": comp.get("parameter_semantic_id"),
                    "canonical_action_id": comp.get("canonical_action_id"),
                    "operation_family": comp.get("operation_family"),
                    "direction": comp.get("direction"),
                    "value_shape": comp.get("normalized_shape_id") or comp.get("delta_bucket"),
                }
                for comp in components[:8]
            ],
        }
    if memory.get("memory_type") == "counter_evidence_memory":
        return {
            "scheme_id": content.get("scheme_id"),
            "scheme_group": content.get("scheme_group"),
            "action_profiles": _counter_action_profiles(memory)[:8],
        }
    return {
        "scheme_id": content.get("scheme_id"),
        "scheme_group": (memory.get("applicability") or {}).get("scheme_groups") or [],
        "parameter_semantic_id": content.get("parameter_semantic_id"),
        "param_cn_name": content.get("param_cn_name"),
        "param_object": content.get("param_object"),
        "canonical_action_ids": content.get("canonical_action_ids") or [],
        "parameter_concept_ids": content.get("parameter_concept_ids") or [],
        "operation_families": content.get("operation_families") or [],
        "direction": pattern.get("direction"),
        "value_type": pattern.get("value_type"),
        "value_shape": pattern.get("normalized_shape_id") or pattern.get("delta_bucket") or pattern.get("pattern_id"),
    }


def _value_delta_distribution(memory: dict[str, Any]) -> dict[str, Any]:
    content = memory.get("content") or {}
    pattern = content.get("value_pattern") or {}
    if memory.get("memory_type") == "counter_evidence_memory":
        return {
            "counter_action_profiles": _counter_action_profiles(memory)[:8],
            "broad_context_outcome_prior": content.get("broad_context_outcome_prior") or {},
        }
    return {
        "observed_changes": _top_list(content.get("observed_changes"), 8),
        "delta_distribution": _top_list(pattern.get("delta_distribution"), 8),
        "shape_distribution": _top_list(pattern.get("shape_distribution"), 8),
        "typical_change": content.get("typical_change"),
        "parameter_value_prior": content.get("parameter_value_prior") or {},
    }


def _child_profile_type(
    pass_n: int,
    fail_n: int,
    mixed_n: int,
    support: int,
) -> tuple[str, str]:
    evaluated = pass_n + fail_n
    effective = evaluated + mixed_n
    pass_lcb = _safe_float(credibility_from_counts(pass_n, fail_n).get("credibility_lcb"))
    fail_lcb = _safe_float(credibility_from_counts(fail_n, pass_n).get("credibility_lcb"))
    if effective < CHILD_MIN_EFFECTIVE_EVIDENCE or support < CHILD_MIN_EFFECTIVE_EVIDENCE:
        return "sparse_profile", "child_insufficient_evidence"
    if mixed_n > 0:
        return "conflict_profile", "child_mixed_outcome_evidence"
    if pass_n > 0 and fail_n > 0 and pass_lcb >= 0.20 and fail_lcb >= 0.20:
        return "conflict_profile", "child_positive_negative_compete"
    if fail_n >= 3 and fail_lcb >= 0.35:
        return "counter_profile", "child_failure_lcb"
    if pass_n >= 3 and fail_n == 0 and pass_lcb >= 0.35:
        return "support_profile", "child_clean_positive_lcb"
    return "sparse_profile", "child_weak_evidence"


def _child_profiles(
    memory: dict[str, Any],
    parent_profile_type: str,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    if parent_profile_type != "conflict_profile":
        return [], {
            "candidate_count": 0,
            "qualified_count": 0,
            "rejected_count": 0,
            "dimension_coverage": {},
        }
    content = memory.get("content") or {}
    pattern = content.get("value_pattern") or {}
    children: list[dict[str, Any]] = []
    audit: dict[str, Any] = {
        "candidate_count": 0,
        "qualified_count": 0,
        "rejected_count": 0,
        "rejected_by_reason": Counter(),
        "dimension_coverage": {},
        "qualification_policy": {
            "minimum_effective_evidence": CHILD_MIN_EFFECTIVE_EVIDENCE,
            "minimum_dimension_coverage": CHILD_MIN_DIMENSION_COVERAGE,
            "key_must_be_nonempty": True,
        },
    }
    parent_support = max(
        _safe_int((memory.get("metrics") or {}).get("support_count")),
        1,
    )

    def add_children(source_name: str, key_name: str, rows: Any, label_field: str) -> None:
        if not isinstance(rows, list):
            return
        valid_rows = [row for row in rows if isinstance(row, dict)]
        covered_support = sum(_safe_int(row.get("support_count")) for row in valid_rows)
        dimension_coverage = min(1.0, covered_support / parent_support)
        audit["dimension_coverage"][source_name] = round(dimension_coverage, 6)
        for row in valid_rows:
            audit["candidate_count"] += 1
            if not isinstance(row, dict):
                continue
            key_value = row.get(label_field)
            if not key_value:
                audit["rejected_count"] += 1
                audit["rejected_by_reason"]["invalid_key"] += 1
                continue
            pass_n = _safe_int(row.get("long_eval_pass_count"))
            fail_n = _safe_int(row.get("long_eval_fail_count"))
            mixed_n = _safe_int(row.get("long_eval_mixed_count"))
            unknown_n = _safe_int(row.get("long_eval_unknown_count"))
            support = _safe_int(row.get("support_count"))
            effective = pass_n + fail_n + mixed_n
            if effective < CHILD_MIN_EFFECTIVE_EVIDENCE:
                audit["rejected_count"] += 1
                audit["rejected_by_reason"]["insufficient_effective_evidence"] += 1
                continue
            if dimension_coverage < CHILD_MIN_DIMENSION_COVERAGE:
                audit["rejected_count"] += 1
                audit["rejected_by_reason"]["insufficient_dimension_coverage"] += 1
                continue
            child_type, reason = _child_profile_type(
                pass_n,
                fail_n,
                mixed_n,
                support,
            )
            children.append({
                "child_profile_id": _profile_id(memory.get("memory_id"), source_name, key_value),
                "profile_type": child_type,
                "key_family": key_name,
                "key_values": {label_field: key_value},
                "outcome_statistics": {
                    "support_count": support,
                    "long_eval_pass_count": pass_n,
                    "long_eval_fail_count": fail_n,
                    "long_eval_mixed_count": mixed_n,
                    "long_eval_unknown_count": unknown_n,
                    "pass_lcb": round(_safe_float(credibility_from_counts(pass_n, fail_n).get("credibility_lcb")), 6),
                    "failure_lcb": round(_safe_float(credibility_from_counts(fail_n, pass_n).get("credibility_lcb")), 6),
                },
                "conflict_reason": reason,
                "recommended_routing": _routing_for_profile(child_type),
                "qualification": {
                    "qualified": True,
                    "key_valid": True,
                    "effective_evidence_count": effective,
                    "minimum_effective_evidence": CHILD_MIN_EFFECTIVE_EVIDENCE,
                    "dimension_coverage": round(dimension_coverage, 6),
                    "minimum_dimension_coverage": CHILD_MIN_DIMENSION_COVERAGE,
                },
            })
            audit["qualified_count"] += 1

    add_children("observed_change", "strategy_action_observed_change", content.get("observed_changes"), "change")
    add_children("delta_bucket", "strategy_action_delta_bucket", pattern.get("delta_distribution"), "delta_bucket")
    add_children("shape", "strategy_action_shape", pattern.get("shape_distribution"), "shape_id")
    children.sort(
        key=lambda child: (
            str(child.get("key_family") or ""),
            str(child.get("child_profile_id") or ""),
        )
    )
    audit["rejected_by_reason"] = dict(sorted(audit["rejected_by_reason"].items()))
    return children, audit


def _routing_for_profile(profile_type: str) -> str:
    if profile_type == "support_profile":
        return "support_rank_if_no_counter"
    if profile_type == "counter_profile":
        return "review_or_reject_by_specificity"
    if profile_type == "conflict_profile":
        return "review"
    return "rank_only_or_review"


def _feature_manifest(
    memory: dict[str, Any],
    score: dict[str, Any] | None,
    stats: dict[str, Any],
    profile_type: str,
    conflict_reason: str,
    runtime_visible_fields: list[str],
    child_profiles: list[dict[str, Any]],
    refinement_audit: dict[str, Any],
) -> dict[str, Any]:
    support_strength = _safe_float(stats.get("pass_lcb"))
    counter_strength = _safe_float(stats.get("failure_lcb"))
    evaluated = _safe_int(stats.get("evaluated_count"))
    conflict_score = min(support_strength, counter_strength) * min(1.0, evaluated / 10.0)
    if profile_type == "conflict_profile" and conflict_score == 0.0:
        conflict_score = 0.25
    sparsity_score = max(0.0, 1.0 - min(1.0, evaluated / 5.0))
    return {
        "memory_state": memory.get("state"),
        "support_strength": round(support_strength, 6),
        "counter_strength": round(counter_strength, 6),
        "conflict_score": round(conflict_score, 6),
        "sparsity_score": round(sparsity_score, 6),
        "has_embedded_support_profile": bool(_support_profiles(memory)),
        "has_counter_action_profile": bool(_counter_action_profiles(memory)),
        "score_overall": (score or {}).get("overall"),
        "score_strategy_effectiveness": (score or {}).get("strategy_effectiveness"),
        "score_boundary_clarity": (score or {}).get("boundary_clarity"),
        "score_reusability": (score or {}).get("reusability"),
        "input_features": runtime_visible_fields,
        "conflict_reason": conflict_reason,
        "hierarchical_refinement": {
            "enabled": True,
            "child_profile_count": len(child_profiles),
            "candidate_count": refinement_audit.get("candidate_count", 0),
            "rejected_count": refinement_audit.get("rejected_count", 0),
            "rejected_by_reason": refinement_audit.get("rejected_by_reason", {}),
            "dimension_coverage": refinement_audit.get("dimension_coverage", {}),
            "qualification_policy": refinement_audit.get("qualification_policy", {}),
            "candidate_dimensions": ["observed_change", "delta_bucket", "shape_distribution"],
            "objective": "safe_decision_separability_not_purity",
        },
        "contract": "train_only_construction_sidecar; runtime may consume but evaluator-only fields are not introduced here",
    }


def build_profiles(
    memories: list[dict[str, Any]],
    *,
    scores_by_memory_id: dict[str, dict[str, Any]] | None = None,
    enable_conflict_resolution: bool = True,
    enable_hierarchical_refinement: bool = True,
) -> list[dict[str, Any]]:
    profiles: list[dict[str, Any]] = []
    for memory in memories:
        memory_type = str(memory.get("memory_type") or "")
        if memory_type not in {"strategy_memory", "playbook_memory", "counter_evidence_memory"}:
            continue
        stats = _outcome_statistics(memory)
        profile_type, conflict_reason, routing = _profile_type(memory, stats)
        if not enable_conflict_resolution:
            profile_type, conflict_reason, routing = _collapse_conflict_or_sparse(
                profile_type,
                conflict_reason,
                routing,
                stats,
            )
        key_family, key_values, runtime_fields = _key_family(memory)
        score = (scores_by_memory_id or {}).get(str(memory.get("memory_id") or ""))
        if enable_hierarchical_refinement:
            children, refinement_audit = _child_profiles(memory, profile_type)
        else:
            children, refinement_audit = [], {
                "candidate_count": 0,
                "qualified_count": 0,
                "rejected_count": 0,
                "dimension_coverage": {},
            }
        if children and profile_type == "conflict_profile":
            child_types = Counter(str(child.get("profile_type")) for child in children)
            if child_types.get("support_profile") or child_types.get("counter_profile"):
                conflict_reason = f"{conflict_reason}; hierarchical_refinement_candidates_present"
        profile = {
            "profile_id": _profile_id(memory.get("memory_id"), profile_type, key_family),
            "parent_memory_id": memory.get("memory_id"),
            "parent_memory_type": memory_type,
            "profile_type": profile_type,
            "key_family": key_family,
            "key_values": key_values,
            "runtime_visible_fields": runtime_fields,
            "outcome_statistics": stats,
            "boundary_context": _boundary_context(memory),
            "action_semantics": _action_semantics(memory),
            "value_delta_distribution": _value_delta_distribution(memory),
            "sample_evidence_refs": {
                "trace_count": len(memory.get("trace_ids") or []),
                "evidence_id_count": len(memory.get("evidence_ids") or []),
                "trace_ids_preview": (memory.get("trace_ids") or [])[:5],
                "sample_sidecar": "strategy_sample_links.jsonl",
            },
            "conflict_reason": conflict_reason,
            "recommended_routing": routing,
            "feature_manifest": _feature_manifest(
                memory,
                score,
                stats,
                profile_type,
                conflict_reason,
                runtime_fields,
                children,
                refinement_audit,
            ),
            "child_profiles": children,
            "produced_by": PRODUCER,
            "produced_at": cio.now_iso(),
            "schema_version": SCHEMA_VERSION,
        }
        profiles.append(profile)
    return profiles


def build_state_transition_manifest(
    *,
    memories: list[dict[str, Any]],
    transitions: list[dict[str, Any]],
    profiles: list[dict[str, Any]],
    source_files: dict[str, str],
) -> dict[str, Any]:
    state_dist = Counter(str(memory.get("state") or "unknown") for memory in memories)
    transition_rules = Counter(str(row.get("rule_id") or "unknown") for row in transitions)
    evidence_states = Counter(str(row.get("profile_type") or "unknown") for row in profiles)
    routing = Counter(str(row.get("recommended_routing") or "unknown") for row in profiles)
    profile_memory_types = Counter(str(row.get("parent_memory_type") or "unknown") for row in profiles)
    child_types = Counter(
        str(child.get("profile_type") or "unknown")
        for row in profiles
        for child in (row.get("child_profiles") or [])
        if isinstance(child, dict)
    )
    return {
        "schema_version": "state_transition_manifest.v1",
        "produced_by": PRODUCER,
        "produced_at": cio.now_iso(),
        "source_files": source_files,
        "memory_count": len(memories),
        "transition_count": len(transitions),
        "profile_count": len(profiles),
        "state_distribution": dict(state_dist),
        "transition_count_by_reason": dict(transition_rules),
        "evidence_state_distribution": dict(evidence_states),
        "recommended_routing_distribution": dict(routing),
        "profile_count_by_memory_type": dict(profile_memory_types),
        "hierarchical_refinement_child_distribution": dict(child_types),
        "conflict_profile_count": evidence_states.get("conflict_profile", 0),
        "sparse_profile_count": evidence_states.get("sparse_profile", 0),
        "support_profile_count": evidence_states.get("support_profile", 0),
        "counter_profile_count": evidence_states.get("counter_profile", 0),
        "capabilities": {
            "memory_evidence_state_inference": "completed",
            "conflict_detection": "completed_first_pass",
            "hierarchical_evidence_refinement": "completed_first_pass_value_delta_shape_children",
            "state_transition_manifest": "completed",
            "learned_evidence_calibrator": "not_used",
        },
        "routing_contract": {
            "support_profile": "support evidence only; do not bypass specific counter evidence",
            "counter_profile": "review/reject candidate depending on specificity",
            "conflict_profile": "default review until refinement proves safe separability",
            "sparse_profile": "rank-only or review; no hard allow",
        },
    }


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--memories", default=str(P.MEMORY_OBJECTS_JSONL))
    ap.add_argument("--transitions", default=str(P.STATE_TRANSITIONS_JSONL))
    ap.add_argument("--scores", default=str(P.MEMORY_SCORES_JSONL))
    ap.add_argument("--out-profiles", default=str(P.MEMORY_EVIDENCE_PROFILES_JSONL))
    ap.add_argument("--out-manifest", default=str(P.STATE_TRANSITION_MANIFEST_JSON))
    ap.add_argument(
        "--disable-conflict-resolution",
        action="store_true",
        help="Construction ablation: do not emit conflict/sparse profile states; force dominant support/counter polarity.",
    )
    ap.add_argument(
        "--disable-hierarchical-refinement",
        action="store_true",
        help="Construction ablation: emit parent profiles but no child refinement profiles.",
    )
    args = ap.parse_args()

    memories = list(cio.read_jsonl(args.memories))
    transitions = list(cio.read_jsonl(args.transitions))
    scores = list(cio.read_jsonl(args.scores))
    scores_by_id = {str(row.get("memory_id")): row for row in scores if row.get("memory_id")}
    profiles = build_profiles(
        memories,
        scores_by_memory_id=scores_by_id,
        enable_conflict_resolution=not args.disable_conflict_resolution,
        enable_hierarchical_refinement=not args.disable_hierarchical_refinement,
    )

    bad = 0
    for profile in profiles:
        errs = validate(profile, "memory_evidence_profile")
        if errs:
            bad += 1
            if bad <= 5:
                print(f"[memory-evidence-profiles] bad profile {profile.get('profile_id')}: {errs[:3]}", file=sys.stderr)

    cio.write_jsonl(args.out_profiles, profiles)
    manifest = build_state_transition_manifest(
        memories=memories,
        transitions=transitions,
        profiles=profiles,
        source_files={
            "memory_objects": str(args.memories),
            "state_transitions": str(args.transitions),
            "memory_scores": str(args.scores),
            "memory_evidence_profiles": str(args.out_profiles),
        },
    )
    Path(args.out_manifest).parent.mkdir(parents=True, exist_ok=True)
    Path(args.out_manifest).write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(
        f"[memory-evidence-profiles] profiles={len(profiles)} schema_bad={bad} "
        f"manifest={args.out_manifest}",
        file=sys.stderr,
    )


if __name__ == "__main__":
    main()

"""Compile static memory-object sample links for strategies, playbooks, and vetoes.

This stage keeps MemoryObject records lean and writes three sidecar indexes:

- strategy_sample_links.jsonl: one aggregate row per linked memory object.
- strategy_sample_episodes.jsonl: compact evidence cohorts per linked memory object.
- strategy_samples.jsonl: one row per memory-trace sample relation.

The input traces are the current compile batch. In the product full-compile
path that batch is train-only, so sample evidence cannot silently pull
dev/holdout traces into the offline knowledge package.
"""

from __future__ import annotations

import argparse
import hashlib
from collections import Counter, defaultdict
from datetime import datetime
from pathlib import Path
from typing import Any

from ..common import io as cio
from ..common import paths as P
from .compile_rules import (
    _action_template_entry,
    _action_template_signature,
    _is_effective_component,
    _pass_rate,
    _semantic_param_id,
    _trace_issue_type,
    _value_pattern,
)

PRODUCER = "strategy_sampleization_v1"

UNKNOWN_OUTCOMES = {"long_eval_unknown", "long_eval_mixed", "execution_blocked", "unknown", ""}
OUTCOME_ORDER = {
    "long_eval_pass": 0,
    "long_eval_fail": 1,
    "long_eval_mixed": 2,
    "long_eval_unknown": 3,
    "execution_blocked": 4,
}


def _sid(memory_id: str, trace_id: str) -> str:
    raw = f"{memory_id}|{trace_id}"
    return "strategy_sample_" + hashlib.md5(raw.encode("utf-8")).hexdigest()[:12]


def _eid(memory_id: str, dimension: str, key: str) -> str:
    raw = f"{memory_id}|{dimension}|{key}"
    return "strategy_sample_episode_" + hashlib.md5(raw.encode("utf-8")).hexdigest()[:12]


def _ticket(trace: dict[str, Any]) -> dict[str, Any]:
    return trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}


def _aggregate(trace: dict[str, Any]) -> dict[str, Any]:
    return trace.get("aggregate") if isinstance(trace.get("aggregate"), dict) else {}


def _ticket_outcome(trace: dict[str, Any]) -> str:
    return str(_aggregate(trace).get("ticket_outcome") or "long_eval_unknown")


def _content(memory: dict[str, Any]) -> dict[str, Any]:
    return memory.get("content") if isinstance(memory.get("content"), dict) else {}


def _metrics(memory: dict[str, Any]) -> dict[str, Any]:
    return memory.get("metrics") if isinstance(memory.get("metrics"), dict) else {}


def _strategy_action_matches(memory: dict[str, Any], trace: dict[str, Any], action: dict[str, Any]) -> bool:
    content = _content(memory)
    pattern = content.get("value_pattern") if isinstance(content.get("value_pattern"), dict) else {}
    ticket = _ticket(trace)
    value_pattern = _value_pattern(action, ticket)
    return (
        _trace_issue_type(trace) == str(content.get("issue_type") or "")
        and str(ticket.get("vendor") or "未知厂家") == str(content.get("vendor") or "")
        and str(ticket.get("system") or "未知制式") == str(content.get("system") or "")
        and str(action.get("scheme_id") or "unknown") == str(content.get("scheme_id") or "unknown")
        and str(_semantic_param_id(action, ticket)) == str(content.get("parameter_semantic_id") or "")
        and str(value_pattern.get("value_type") or "") == str(pattern.get("value_type") or "")
        and str(value_pattern.get("direction") or "") == str(pattern.get("direction") or "")
    )


def _playbook_signatures(memory: dict[str, Any]) -> set[str]:
    content = _content(memory)
    features = content.get("matching_features") if isinstance(content.get("matching_features"), dict) else {}
    soft = features.get("soft_signals") if isinstance(features.get("soft_signals"), dict) else {}
    signatures = soft.get("component_signatures") if isinstance(soft.get("component_signatures"), list) else []
    out = {str(sig) for sig in signatures if sig}
    if out:
        return out
    for component in content.get("components", []) or []:
        if not isinstance(component, dict):
            continue
        sig = component.get("action_signature")
        if sig:
            out.add(str(sig))
    return out


def _counter_evidence_action_matches(memory: dict[str, Any], trace: dict[str, Any], action: dict[str, Any]) -> bool:
    content = _content(memory)
    ticket = _ticket(trace)
    issue = str(content.get("issue_type") or "")
    scheme_id = str(content.get("scheme_id") or "")
    return (
        (not issue or _trace_issue_type(trace) == issue)
        and bool(scheme_id)
        and str(action.get("scheme_id") or "") == scheme_id
        and bool(ticket)
    )


def _matched_actions(memory: dict[str, Any], trace: dict[str, Any]) -> list[dict[str, Any]]:
    memory_type = memory.get("memory_type")
    matched: list[dict[str, Any]] = []
    signatures = _playbook_signatures(memory) if memory_type == "playbook_memory" else set()
    for action in trace.get("actions", []) or []:
        if not _is_effective_component(action):
            continue
        if memory_type == "strategy_memory":
            if not _strategy_action_matches(memory, trace, action):
                continue
        elif memory_type == "playbook_memory":
            if signatures and _action_template_signature(trace, action) not in signatures:
                continue
        elif memory_type == "counter_evidence_memory":
            if not _counter_evidence_action_matches(memory, trace, action):
                continue
        else:
            continue
        entry = _action_template_entry(trace, action)
        entry.update({
            "action_id": action.get("action_id"),
            "change": f"{action.get('before_value')}->{action.get('after_value')}",
            "before_value": action.get("before_value"),
            "after_value": action.get("after_value"),
            "action_signature": _action_template_signature(trace, action),
        })
        matched.append(entry)
    return matched


def _memory_context(memory: dict[str, Any]) -> dict[str, Any]:
    content = _content(memory)
    app = memory.get("applicability") if isinstance(memory.get("applicability"), dict) else {}
    pattern = content.get("value_pattern") if isinstance(content.get("value_pattern"), dict) else {}
    return {
        "issue_type": content.get("issue_type") or next(iter(app.get("issue_types", []) or []), None),
        "vendor": content.get("vendor") or next(iter(app.get("vendors", []) or []), None),
        "system": content.get("system") or next(iter(app.get("systems", []) or []), None),
        "scheme_group": content.get("scheme_group") or next(iter(app.get("scheme_groups", []) or []), None),
        "scheme_id": content.get("scheme_id"),
        "parameter_semantic_id": content.get("parameter_semantic_id"),
        "param_cn_name": content.get("param_cn_name") or content.get("param_en_name"),
        "direction": pattern.get("direction"),
        "value_type": pattern.get("value_type"),
    }


def _sample_sort_key(sample: dict[str, Any]) -> tuple[int, str, str]:
    return (
        OUTCOME_ORDER.get(str(sample.get("ticket_outcome") or ""), 9),
        str(sample.get("issued_at") or ""),
        str(sample.get("trace_id") or ""),
    )


def _parse_dt(value: Any) -> datetime | None:
    if not value:
        return None
    text = str(value)
    try:
        return datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        try:
            return datetime.fromisoformat(text[:10])
        except ValueError:
            return None


def _sample_action_signatures(sample: dict[str, Any]) -> list[str]:
    values = sample.get("action_signatures")
    if isinstance(values, list):
        out = [str(value) for value in values if value]
        if out:
            return out
    out = []
    for action in sample.get("actions", []) or []:
        if isinstance(action, dict) and action.get("action_signature"):
            out.append(str(action["action_signature"]))
    return sorted(set(out))


def _sample_value_buckets(sample: dict[str, Any]) -> list[str]:
    out: list[str] = []
    for action in sample.get("actions", []) or []:
        if not isinstance(action, dict):
            continue
        bucket = action.get("delta_bucket") or action.get("typical_change") or action.get("change")
        if bucket:
            out.append(str(bucket))
    return sorted(set(out)) or ["unknown_value"]


def _assign_recency_buckets(samples: list[dict[str, Any]]) -> None:
    dated = [
        (dt, sample)
        for sample in samples
        if (dt := _parse_dt(sample.get("issued_at"))) is not None
    ]
    if not dated:
        for sample in samples:
            sample["recency_bucket"] = "unknown"
        return
    dated.sort(key=lambda item: (item[0], str(item[1].get("trace_id") or "")))
    total = len(dated)
    for index, (_, sample) in enumerate(dated):
        if total <= 2:
            bucket = "recent" if index == total - 1 else "old"
        elif index < total / 3:
            bucket = "old"
        elif index < total * 2 / 3:
            bucket = "mid"
        else:
            bucket = "recent"
        sample["recency_bucket"] = bucket
    for sample in samples:
        sample.setdefault("recency_bucket", "unknown")


def _sample_utility(sample: dict[str, Any]) -> float:
    outcome = str(sample.get("ticket_outcome") or "")
    outcome_score = {
        "long_eval_pass": 4.0,
        "long_eval_fail": 3.5,
        "long_eval_mixed": 2.5,
        "long_eval_unknown": 1.0,
        "execution_blocked": 0.5,
    }.get(outcome, 0.5)
    action_score = min(2.0, float(sample.get("matched_action_count") or 0) * 0.5)
    fanout_penalty = min(1.0, max(0.0, float(sample.get("trace_fanout") or 1) - 1.0) * 0.05)
    recency_score = {"recent": 0.6, "mid": 0.3, "old": 0.1}.get(str(sample.get("recency_bucket") or ""), 0.0)
    return outcome_score + action_score + recency_score - fanout_penalty


def _diversity_features(sample: dict[str, Any]) -> set[str]:
    features = {
        f"outcome:{sample.get('ticket_outcome') or 'unknown'}",
        f"region:{sample.get('region') or 'unknown'}",
        f"recency:{sample.get('recency_bucket') or 'unknown'}",
    }
    features.update(f"action:{sig}" for sig in _sample_action_signatures(sample)[:3])
    features.update(f"value:{bucket}" for bucket in _sample_value_buckets(sample)[:3])
    return features


def _representative_sample_ids(samples: list[dict[str, Any]], limit: int) -> list[str]:
    if limit <= 0:
        return []
    selected: list[str] = []
    seen: set[str] = set()
    seen_features: set[str] = set()

    def add(sample: dict[str, Any]) -> bool:
        sid = sample.get("sample_id")
        if not sid or sid in seen:
            return False
        selected.append(str(sid))
        seen.add(str(sid))
        seen_features.update(_diversity_features(sample))
        return len(selected) >= limit

    by_utility = sorted(
        samples,
        key=lambda sample: (
            _sample_utility(sample),
            len(_diversity_features(sample)),
            str(sample.get("issued_at") or ""),
            str(sample.get("sample_id") or ""),
        ),
        reverse=True,
    )
    for wanted in ("long_eval_pass", "long_eval_fail", "long_eval_mixed", "long_eval_unknown"):
        for sample in by_utility:
            if sample.get("ticket_outcome") != wanted:
                continue
            if add(sample):
                return selected
            break
    while len(selected) < limit:
        best: tuple[float, dict[str, Any]] | None = None
        for sample in by_utility:
            if sample.get("sample_id") in seen:
                continue
            features = _diversity_features(sample)
            novelty = len(features - seen_features)
            score = _sample_utility(sample) + novelty * 0.75
            if best is None or score > best[0]:
                best = (score, sample)
        if best is None:
            break
        add(best[1])
    return selected


def _top_counter(counter: Counter[str], limit: int = 8) -> dict[str, int]:
    return {key: count for key, count in counter.most_common(limit)}


def _group_samples_by_dimension(samples: list[dict[str, Any]]) -> dict[tuple[str, str], list[dict[str, Any]]]:
    groups: dict[tuple[str, str], list[dict[str, Any]]] = defaultdict(list)
    for sample in samples:
        groups[("outcome", str(sample.get("ticket_outcome") or "unknown"))].append(sample)
        groups[("region", str(sample.get("region") or "unknown"))].append(sample)
        groups[("recency", str(sample.get("recency_bucket") or "unknown"))].append(sample)
        for signature in _sample_action_signatures(sample) or ["unknown_action"]:
            groups[("action", signature)].append(sample)
        for bucket in _sample_value_buckets(sample):
            groups[("value", bucket)].append(sample)
    return groups


def _episode_group_limit(dimension: str, max_groups_per_dimension: int) -> int:
    if dimension in {"outcome", "recency"}:
        return 8
    return max_groups_per_dimension


def _build_sample_episodes(
    memory: dict[str, Any],
    memory_samples: list[dict[str, Any]],
    *,
    max_episode_groups_per_dimension: int,
    max_episode_representatives: int,
) -> list[dict[str, Any]]:
    mid = str(memory.get("memory_id") or "")
    if not mid or not memory_samples:
        return []
    selected_groups: list[tuple[str, str, list[dict[str, Any]]]] = []
    grouped = _group_samples_by_dimension(memory_samples)
    by_dimension: dict[str, list[tuple[str, list[dict[str, Any]]]]] = defaultdict(list)
    for (dimension, key), rows in grouped.items():
        by_dimension[dimension].append((key, rows))
    for dimension in ("outcome", "action", "value", "region", "recency"):
        groups = by_dimension.get(dimension, [])
        groups.sort(
            key=lambda item: (
                len(item[1]),
                max((_sample_utility(sample) for sample in item[1]), default=0.0),
                item[0],
            ),
            reverse=True,
        )
        for key, rows in groups[: _episode_group_limit(dimension, max_episode_groups_per_dimension)]:
            selected_groups.append((dimension, key, rows))

    episodes: list[dict[str, Any]] = []
    for dimension, key, rows in selected_groups:
        representative_ids = _representative_sample_ids(rows, max_episode_representatives)
        representative_id_set = set(representative_ids)
        outcomes = Counter(str(row.get("ticket_outcome") or "unknown") for row in rows)
        action_counts = Counter(sig for row in rows for sig in _sample_action_signatures(row))
        value_counts = Counter(bucket for row in rows for bucket in _sample_value_buckets(row))
        region_counts = Counter(str(row.get("region") or "unknown") for row in rows)
        recency_counts = Counter(str(row.get("recency_bucket") or "unknown") for row in rows)
        pass_n = outcomes.get("long_eval_pass", 0)
        fail_n = outcomes.get("long_eval_fail", 0)
        episodes.append({
            "episode_id": _eid(mid, dimension, key),
            "episode_type": "strategy_sample_episode",
            "memory_id": mid,
            "memory_type": memory.get("memory_type"),
            "memory_title": memory.get("title"),
            "group_dimension": dimension,
            "group_key": key,
            "title": f"{dimension}: {key}",
            "sample_count": len(rows),
            "matched_action_sample_count": sum(1 for row in rows if row.get("matched_action_count")),
            "trace_fanout_mean": round(
                sum(float(row.get("trace_fanout") or 1) for row in rows) / max(1, len(rows)),
                4,
            ),
            "outcome_counts": dict(outcomes),
            "action_signature_counts": _top_counter(action_counts),
            "value_change_counts": _top_counter(value_counts),
            "region_counts": _top_counter(region_counts),
            "recency_counts": _top_counter(recency_counts),
            "representative_sample_ids": representative_ids,
            "representative_trace_ids": [
                str(row.get("trace_id"))
                for row in rows
                if row.get("sample_id") in representative_id_set and row.get("trace_id")
            ],
            "metrics": {
                "sample_count": len(rows),
                "long_eval_pass_count": pass_n,
                "long_eval_fail_count": fail_n,
                "long_eval_unknown_count": sum(
                    count for outcome, count in outcomes.items() if outcome in UNKNOWN_OUTCOMES
                ),
                "pass_rate": _pass_rate(pass_n, fail_n),
            },
            "produced_by": PRODUCER,
            "produced_at": cio.now_iso(),
            "schema_version": "0.1",
        })
    episodes.sort(
        key=lambda row: (
            str(row.get("memory_id") or ""),
            str(row.get("group_dimension") or ""),
            -int(row.get("sample_count") or 0),
            str(row.get("group_key") or ""),
        )
    )
    return episodes


def _compact_trace_fields(trace: dict[str, Any]) -> dict[str, Any]:
    ticket = _ticket(trace)
    aggregate = _aggregate(trace)
    return {
        "trace_id": trace.get("trace_id"),
        "ticket_id": ticket.get("id"),
        "cell_name": ticket.get("cell_name"),
        "site_name": ticket.get("site_name"),
        "issue_type": ticket.get("primary_issue_type"),
        "region": ticket.get("region"),
        "vendor": ticket.get("vendor"),
        "system": ticket.get("system"),
        "band": ticket.get("band"),
        "issued_at": ticket.get("issued_at"),
        "ticket_outcome": aggregate.get("ticket_outcome") or "long_eval_unknown",
        "action_count": aggregate.get("action_count", len(trace.get("actions", []) or [])),
    }


def build_strategy_sample_artifacts(
    traces: list[dict[str, Any]],
    memories: list[dict[str, Any]],
    episode_candidates: list[dict[str, Any]],
    *,
    max_representatives: int = 12,
    max_episode_groups_per_dimension: int = 8,
    max_episode_representatives: int = 3,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]]]:
    traces_by_id = {trace.get("trace_id"): trace for trace in traces if trace.get("trace_id")}
    case_memory_ids_by_trace: dict[str, list[str]] = defaultdict(list)
    for memory in memories:
        if memory.get("memory_type") != "case_memory":
            continue
        mid = memory.get("memory_id")
        if not mid:
            continue
        for tid in memory.get("trace_ids", []) or []:
            if tid:
                case_memory_ids_by_trace[str(tid)].append(str(mid))

    episode_ids_by_memory: dict[str, list[str]] = defaultdict(list)
    for candidate in episode_candidates:
        eid = candidate.get("episode_id")
        if not eid:
            continue
        for mid in candidate.get("linked_strategy_memory_ids", []) or []:
            episode_ids_by_memory[str(mid)].append(str(eid))
        for mid in candidate.get("linked_playbook_memory_ids", []) or []:
            episode_ids_by_memory[str(mid)].append(str(eid))

    sample_rows: list[dict[str, Any]] = []
    link_rows: list[dict[str, Any]] = []
    episode_rows: list[dict[str, Any]] = []
    target_memories = [
        memory
        for memory in memories
        if memory.get("memory_type") in {"strategy_memory", "playbook_memory", "counter_evidence_memory"}
    ]
    trace_fanout_counter: Counter[str] = Counter()
    for memory in target_memories:
        for tid in {str(tid) for tid in memory.get("trace_ids", []) or [] if tid}:
            trace_fanout_counter[tid] += 1

    for memory in target_memories:
        mid = str(memory.get("memory_id") or "")
        if not mid:
            continue
        raw_trace_ids = [str(tid) for tid in memory.get("trace_ids", []) or [] if tid]
        seen_trace_ids: set[str] = set()
        memory_samples: list[dict[str, Any]] = []
        memory_episode_ids = sorted(set(episode_ids_by_memory.get(mid, [])))
        for tid in raw_trace_ids:
            if tid in seen_trace_ids:
                continue
            seen_trace_ids.add(tid)
            trace = traces_by_id.get(tid)
            if not trace:
                continue
            matched_actions = _matched_actions(memory, trace)
            sample = {
                "sample_id": _sid(mid, tid),
                "memory_id": mid,
                "memory_type": memory.get("memory_type"),
                "memory_title": memory.get("title"),
                "case_memory_ids": sorted(set(case_memory_ids_by_trace.get(tid, []))),
                "episode_ids": memory_episode_ids[:12],
                "episode_count": len(memory_episode_ids),
                "matched_action_count": len(matched_actions),
                "actions": matched_actions[:12],
                "action_signatures": sorted({
                    str(action.get("action_signature"))
                    for action in matched_actions
                    if action.get("action_signature")
                }),
                **_compact_trace_fields(trace),
                "trace_fanout": trace_fanout_counter.get(tid, 0),
                "produced_by": PRODUCER,
                "produced_at": cio.now_iso(),
                "schema_version": "0.1",
            }
            memory_samples.append(sample)

        memory_samples.sort(key=_sample_sort_key)
        _assign_recency_buckets(memory_samples)
        for rank, sample in enumerate(memory_samples, start=1):
            sample["sample_rank"] = rank
        memory_episode_rows = _build_sample_episodes(
            memory,
            memory_samples,
            max_episode_groups_per_dimension=max_episode_groups_per_dimension,
            max_episode_representatives=max_episode_representatives,
        )
        episode_rows.extend(memory_episode_rows)
        representative_ids = set(_representative_sample_ids(memory_samples, max_representatives))
        for sample in memory_samples:
            sample["is_representative"] = sample.get("sample_id") in representative_ids
        sample_rows.extend(memory_samples)

        outcomes = Counter(str(sample.get("ticket_outcome") or "long_eval_unknown") for sample in memory_samples)
        pass_n = outcomes.get("long_eval_pass", 0)
        fail_n = outcomes.get("long_eval_fail", 0)
        unknown_n = sum(count for outcome, count in outcomes.items() if outcome in UNKNOWN_OUTCOMES)
        ctx = _memory_context(memory)
        metrics = _metrics(memory)
        link_rows.append({
            "memory_id": mid,
            "memory_type": memory.get("memory_type"),
            "title": memory.get("title"),
            **ctx,
            "trace_count_total": len(memory_samples),
            "sample_count": len(memory_samples),
            "matched_action_sample_count": sum(1 for sample in memory_samples if sample.get("matched_action_count")),
            "case_memory_count": len({
                cid
                for sample in memory_samples
                for cid in sample.get("case_memory_ids", [])
            }),
            "episode_ids": memory_episode_ids,
            "sample_episode_count": len(memory_episode_rows),
            "representative_episode_ids": [
                str(episode.get("episode_id"))
                for episode in sorted(
                    memory_episode_rows,
                    key=lambda row: (int(row.get("sample_count") or 0), str(row.get("episode_id") or "")),
                    reverse=True,
                )[:12]
                if episode.get("episode_id")
            ],
            "representative_sample_policy": "diversity_v1",
            "representative_sample_ids": [sid for sid in _representative_sample_ids(memory_samples, max_representatives)],
            "representative_trace_ids": [
                str(sample.get("trace_id"))
                for sample in memory_samples
                if sample.get("sample_id") in representative_ids and sample.get("trace_id")
            ],
            "outcome_counts": dict(outcomes),
            "metrics": {
                "sample_count": len(memory_samples),
                "support_count": metrics.get("support_count"),
                "long_eval_pass_count": pass_n,
                "long_eval_fail_count": fail_n,
                "long_eval_unknown_count": unknown_n,
                "pass_rate": _pass_rate(pass_n, fail_n),
            },
            "produced_by": PRODUCER,
            "produced_at": cio.now_iso(),
            "schema_version": "0.1",
        })

    link_rows.sort(
        key=lambda row: (
            int(row.get("sample_count") or 0),
            float(row.get("metrics", {}).get("pass_rate") or 0),
            str(row.get("memory_id") or ""),
        ),
        reverse=True,
    )
    sample_rows.sort(key=lambda row: (str(row.get("memory_id") or ""), int(row.get("sample_rank") or 0)))
    episode_rows.sort(
        key=lambda row: (
            str(row.get("memory_id") or ""),
            str(row.get("group_dimension") or ""),
            -int(row.get("sample_count") or 0),
            str(row.get("group_key") or ""),
        )
    )
    return link_rows, sample_rows, episode_rows


def build_strategy_sample_indexes(
    traces: list[dict[str, Any]],
    memories: list[dict[str, Any]],
    episode_candidates: list[dict[str, Any]],
    *,
    max_representatives: int = 12,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    links, samples, _episodes = build_strategy_sample_artifacts(
        traces,
        memories,
        episode_candidates,
        max_representatives=max_representatives,
    )
    return links, samples


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--traces", default=str(P.COMPILE_BATCH_JSONL))
    ap.add_argument("--memories", default=str(P.MEMORY_OBJECTS_JSONL))
    ap.add_argument("--episode-candidates", default=str(P.CASE_EPISODE_CANDIDATES_JSONL))
    ap.add_argument("--out-links", default=str(P.STRATEGY_SAMPLE_LINKS_JSONL))
    ap.add_argument("--out-samples", default=str(P.STRATEGY_SAMPLES_JSONL))
    ap.add_argument("--out-episodes", default=str(P.STRATEGY_SAMPLE_EPISODES_JSONL))
    ap.add_argument("--max-representatives", type=int, default=12)
    ap.add_argument("--max-episode-groups-per-dimension", type=int, default=8)
    ap.add_argument("--max-episode-representatives", type=int, default=3)
    args = ap.parse_args()

    traces = list(cio.read_jsonl(args.traces))
    memories = list(cio.read_jsonl(args.memories))
    episode_candidates = list(cio.read_jsonl(args.episode_candidates))
    links, samples, episodes = build_strategy_sample_artifacts(
        traces,
        memories,
        episode_candidates,
        max_representatives=args.max_representatives,
        max_episode_groups_per_dimension=args.max_episode_groups_per_dimension,
        max_episode_representatives=args.max_episode_representatives,
    )
    link_count = cio.write_jsonl(Path(args.out_links), links)
    sample_count = cio.write_jsonl(Path(args.out_samples), samples)
    episode_count = cio.write_jsonl(Path(args.out_episodes), episodes)
    print(
        f"[strategy-samples] traces={len(traces)} memories={len(memories)} "
        f"links={link_count} episodes={episode_count} samples={sample_count} "
        f"out_links={args.out_links} out_episodes={args.out_episodes} out_samples={args.out_samples}"
    )


if __name__ == "__main__":
    main()

"""Recommendation action contract helpers.

The contract keeps a single primary action backward-compatible while allowing
multi-parameter plan companions to travel with the candidate. These companion
fields must come from the candidate source (train case or train-only memory),
not from held-out gold rows.
"""

from __future__ import annotations

import re
from typing import Any


def _text(value: Any) -> str:
    return str(value if value is not None else "").strip()


def _add_companion(
    out: list[dict[str, Any]],
    seen: set[tuple[str, str]],
    *,
    name: str,
    value: Any,
    role: str,
    source: str,
) -> None:
    clean_name = _text(name)
    clean_value = _text(value)
    if not clean_name or not clean_value:
        return
    key = (clean_name.lower(), clean_value.lower())
    if key in seen:
        return
    seen.add(key)
    out.append({
        "name": clean_name,
        "value": clean_value,
        "role": role,
        "source": source,
    })


def operation_summary_assignments(action: dict[str, Any]) -> list[tuple[str, str]]:
    """Extract simple ``ParamName=value`` assignments from operation text."""
    text = _text(action.get("operation_summary") or action.get("operation_detail"))
    if not text:
        return []
    main_names = {
        _text(action.get("param_en_name")).lower(),
        _text(action.get("site_param_en_name")).lower(),
    } - {""}
    assignments: list[tuple[str, str]] = []
    for name, value in re.findall(r"([A-Za-z][A-Za-z0-9_]{1,80})\s*=\s*([^,\s，;；]+)", text):
        if name.lower() in main_names:
            continue
        assignments.append((name, value))
    return assignments


def plan_companion_parameters_from_action(
    action: dict[str, Any],
    *,
    source: str,
) -> list[dict[str, Any]]:
    """Return candidate-source companion parameters for a primary action."""
    out: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    _add_companion(
        out,
        seen,
        name="parameter_group",
        value=action.get("parameter_group"),
        role="parameter_group",
        source=source,
    )
    _add_companion(
        out,
        seen,
        name="final_ratio",
        value=action.get("final_ratio"),
        role="ratio_or_threshold",
        source=source,
    )
    for name, value in operation_summary_assignments(action):
        _add_companion(
            out,
            seen,
            name=name,
            value=value,
            role="operation_summary_assignment",
            source=source,
        )
    return out


def plan_companion_distribution_from_strategy(content: dict[str, Any]) -> list[dict[str, Any]]:
    """Expose train-only strategy-level companion hints without pretending they
    are target-specific exact values.
    """
    out: list[dict[str, Any]] = []
    for name, role, values in (
        ("parameter_group", "parameter_group_distribution", content.get("parameter_groups")),
        ("final_ratio", "ratio_or_threshold_distribution", content.get("final_ratio_top")),
    ):
        if not isinstance(values, list):
            continue
        for rank, value in enumerate(values[:5], start=1):
            clean = _text(value)
            if not clean:
                continue
            out.append({
                "name": name,
                "value": clean,
                "role": role,
                "source": "train_only_strategy_memory_distribution",
                "rank": rank,
            })
    assignment_counts: dict[tuple[str, str], int] = {}
    summaries = content.get("operation_summaries")
    if isinstance(summaries, list):
        for summary in summaries[:8]:
            fake_action = {
                "operation_summary": summary,
                "param_en_name": content.get("param_en_name"),
                "site_param_en_name": content.get("site_param_en_name"),
            }
            for name, value in operation_summary_assignments(fake_action):
                key = (name, value)
                assignment_counts[key] = assignment_counts.get(key, 0) + 1
    for rank, ((name, value), count) in enumerate(
        sorted(assignment_counts.items(), key=lambda item: (-item[1], item[0][0], item[0][1]))[:8],
        start=1,
    ):
        out.append({
            "name": name,
            "value": value,
            "role": "operation_summary_assignment_distribution",
            "source": "train_only_strategy_memory_distribution",
            "rank": rank,
            "support_count": count,
        })
    return out


def companion_signature(parameters: Any) -> str:
    if not isinstance(parameters, list):
        return ""
    pairs = []
    for item in parameters:
        if not isinstance(item, dict):
            continue
        name = _text(item.get("name")).lower()
        value = _text(item.get("value")).lower()
        if name and value:
            pairs.append((name, value))
    return "|".join(f"{name}={value}" for name, value in sorted(set(pairs)))

"""Canonical action projection and paper-level action equivalence."""

from __future__ import annotations

from typing import Any

EQUIVALENCE_LEVELS = {
    "strongly_verifiable",
    "weakly_verifiable",
    "unverifiable",
    "contradictory",
}

_OPPOSITE_DIRECTIONS = {
    ("increase", "decrease"),
    ("decrease", "increase"),
    ("enable", "disable"),
    ("disable", "enable"),
}


def _text(value: Any) -> str | None:
    text = str(value or "").strip()
    return text or None


def canonicalize_action(
    action: dict[str, Any] | None,
    *,
    ticket: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Project a recommendation or evaluator-only gold into CanonicalAction."""
    action = action if isinstance(action, dict) else {}
    ticket = ticket if isinstance(ticket, dict) else {}
    boundaries = action.get("boundary_conditions")
    if not isinstance(boundaries, dict):
        boundaries = action.get("effective_parameter_range")
    if not isinstance(boundaries, dict):
        boundaries = {}
    target = (
        action.get("target_value_or_delta")
        or action.get("suggested_delta")
        or action.get("delta_bucket")
        or action.get("target_value")
    )
    return {
        "object_type": _text(action.get("object_type") or ("cell" if ticket.get("cell_id") else None)),
        "object_id": _text(action.get("object_id") or ticket.get("cell_id")),
        "vendor": _text(action.get("vendor") or ticket.get("vendor")),
        "rat": _text(action.get("rat") or action.get("system") or ticket.get("system")),
        "scheme_group": _text(action.get("scheme_group")),
        "scheme_id": _text(action.get("scheme_id")),
        "parameter_semantic_key": _text(
            action.get("parameter_semantic_key") or action.get("parameter_semantic_id")
        ),
        "parameter_name": _text(action.get("parameter_name") or action.get("param_cn_name")),
        "action_type": _text(action.get("action_type") or action.get("value_type")),
        "direction": _text(action.get("direction")),
        "target_value_or_delta": _text(target),
        "value_semantics": _text(action.get("value_semantics") or action.get("value_type")),
        "scope": _text(action.get("scope") or ("cell" if ticket.get("cell_id") else None)),
        "time_window": _text(action.get("time_window")),
        "boundary_conditions": boundaries,
    }


def _same(left: Any, right: Any) -> bool:
    return bool(left and right and str(left).strip().lower() == str(right).strip().lower())


def _compatible_or_missing(left: Any, right: Any) -> bool:
    return not left or not right or _same(left, right)


def compare_canonical_actions(
    recommended: dict[str, Any],
    gold: dict[str, Any],
) -> dict[str, Any]:
    """Classify one recommendation/gold pair without treating missing data as failure."""
    scheme_match = _same(recommended.get("scheme_id"), gold.get("scheme_id"))
    semantic_match = _same(
        recommended.get("parameter_semantic_key"),
        gold.get("parameter_semantic_key"),
    )
    name_match = _same(recommended.get("parameter_name"), gold.get("parameter_name"))
    parameter_match = semantic_match or name_match
    parameter_match_kind = "semantic_key" if semantic_match else "parameter_name" if name_match else "none"
    direction_match = _same(recommended.get("direction"), gold.get("direction"))
    direction_pair = (
        str(recommended.get("direction") or "").lower(),
        str(gold.get("direction") or "").lower(),
    )
    direction_conflict = scheme_match and parameter_match and direction_pair in _OPPOSITE_DIRECTIONS
    target_match = _same(
        recommended.get("target_value_or_delta"),
        gold.get("target_value_or_delta"),
    )
    boundary_compatible = _compatible_or_missing(
        recommended.get("boundary_conditions"),
        gold.get("boundary_conditions"),
    )

    if direction_conflict:
        level = "contradictory"
    elif scheme_match and parameter_match and direction_match and target_match and boundary_compatible:
        level = "strongly_verifiable"
    elif scheme_match and parameter_match and not direction_conflict:
        level = "weakly_verifiable"
    else:
        level = "unverifiable"

    return {
        "level": level,
        "scheme_match": scheme_match,
        "parameter_match": parameter_match,
        "parameter_match_kind": parameter_match_kind,
        "direction_match": direction_match,
        "direction_conflict": direction_conflict,
        "target_match": target_match,
        "boundary_compatible": boundary_compatible,
        "recommended": recommended,
        "gold": gold,
    }


def best_action_equivalence(
    recommended: dict[str, Any] | None,
    gold_actions: list[dict[str, Any]],
    *,
    ticket: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    if not gold_actions:
        return None
    canonical_recommended = canonicalize_action(recommended, ticket=ticket)
    comparisons = [
        compare_canonical_actions(canonical_recommended, canonicalize_action(gold, ticket=ticket))
        for gold in gold_actions
    ]
    priority = {
        "strongly_verifiable": 3,
        "weakly_verifiable": 2,
        "contradictory": 1,
        "unverifiable": 0,
    }
    return max(comparisons, key=lambda item: priority[item["level"]])

"""Stable identity for executable candidate proposals.

Candidate identity is intentionally stricter than the paper's evaluator-side
weak/strong action equivalence.  The latter asks whether a frozen proposal
recovers an observed historical decision; it must never be reused to collapse
different values or executable proposal shapes before the evaluator runs.
"""
from __future__ import annotations

import hashlib
import json
from decimal import Decimal, InvalidOperation
from typing import Any

from .action_contract import companion_signature


CANDIDATE_ACTION_IDENTITY_VERSION = "candidate_action_identity.v1"


def _text(value: Any) -> str:
    return str(value if value is not None else "").strip().lower()


def _value(value: Any) -> str:
    text = _text(value)
    if not text:
        return ""
    try:
        number = Decimal(text)
    except InvalidOperation:
        return text.replace("→", "->")
    normalized = format(number.normalize(), "f")
    return "0" if normalized in {"-0", "+0"} else normalized


def _all(applicability: dict[str, Any], key: str) -> list[str]:
    value = applicability.get(key)
    if isinstance(value, list):
        return sorted({_text(item) for item in value if _text(item)})
    text = _text(value)
    return [text] if text else []


def _first_present(*values: Any) -> Any:
    for value in values:
        if value is not None and str(value).strip() != "":
            return value
    return None


def _parameter_identity(action: dict[str, Any]) -> dict[str, str]:
    semantic = _text(
        action.get("parameter_semantic_id")
        or action.get("parameter_semantic_key")
    )
    if semantic:
        return {"kind": "semantic", "key": semantic}
    for kind, key in (
        ("site_en", "site_param_en_name"),
        ("en", "param_en_name"),
        ("cn", "param_cn_name"),
        ("object", "param_object"),
    ):
        value = _text(action.get(key))
        if value:
            return {"kind": kind, "key": value}
    return {"kind": "missing", "key": ""}


def _value_identity(action: dict[str, Any]) -> dict[str, str]:
    before = _value(action.get("before_value"))
    after = _value(action.get("after_value"))
    if before or after:
        return {"kind": "transition", "before": before, "after": after}
    target = _value(_first_present(
        action.get("target_value"),
        action.get("target_value_or_delta"),
    ))
    if target:
        return {"kind": "target", "value": target}
    delta = _value(_first_present(action.get("suggested_delta"), action.get("delta_bucket")))
    if delta:
        return {"kind": "delta", "value": delta}
    change = _value(action.get("change"))
    if change:
        return {"kind": "change", "value": change}
    pattern = _text(action.get("value_pattern_id"))
    return {"kind": "pattern" if pattern else "missing", "value": pattern}


def candidate_action_identity(
    action: dict[str, Any],
    *,
    applicability: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Project a candidate onto its strong executable-proposal identity.

    Region, band, issue, source IDs, attribution scope, and Memory evidence are
    deliberately excluded.  They describe applicability/provenance for the
    feedback view, not a different proposal on the same target.  Vendor and
    system remain because parameter and command semantics are local to them.
    """
    applicability = applicability if isinstance(applicability, dict) else {}
    companions = action.get("plan_companion_parameters")
    return {
        "version": CANDIDATE_ACTION_IDENTITY_VERSION,
        "vendors": (
            [_text(action.get("vendor"))]
            if _text(action.get("vendor"))
            else _all(applicability, "vendors")
        ),
        "systems": (
            [_text(action.get("system") or action.get("rat"))]
            if _text(action.get("system") or action.get("rat"))
            else _all(applicability, "systems")
        ),
        "scheme_group": _text(action.get("scheme_group")),
        "scheme_id": _text(action.get("scheme_id")),
        "parameter": _parameter_identity(action),
        "param_object": _text(action.get("param_object")),
        "site_param_object": _text(action.get("site_param_object")),
        "value_type": _text(action.get("value_type") or action.get("action_type")),
        "direction": _text(action.get("direction")),
        "value": _value_identity(action),
        "scope": _text(action.get("scope") or action.get("object_type")),
        "companion_signature": companion_signature(companions),
    }


def candidate_action_id(
    action: dict[str, Any],
    *,
    applicability: dict[str, Any] | None = None,
) -> str:
    identity = candidate_action_identity(action, applicability=applicability)
    payload = json.dumps(
        identity,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )
    return "CAI-" + hashlib.sha256(payload.encode("utf-8")).hexdigest()[:20].upper()


def candidate_instance_id(target_trace_id: str, action_id: str) -> str:
    payload = f"{CANDIDATE_ACTION_IDENTITY_VERSION}|{target_trace_id}|{action_id}"
    return "CI-" + hashlib.sha256(payload.encode("utf-8")).hexdigest()[:20].upper()

"""Shared evaluation dataset registry for experiment and shadow workbench.

This module is the common layer above time-split and legacy Eval Set A data.
Both the experiment console and shadow workbench should use these dataset
roles instead of hard-coding `test.xlsx` / `source=eval` assumptions.
"""

from __future__ import annotations

import hashlib
import json
from typing import Any, Literal

from ..common import io as cio
