DATASET_LABELS: dict[DatasetRole, dict[str, str]] = {
    "dev": {
        "label": "调试集",
        "purpose": "平时调试和方法对比用；可以反复运行，不作为最终结论。",
        "source": "data/staged/splits/dev_trace_records.jsonl",
    },
    "holdout": {
        "label": "未来验证集",
        "purpose": "模拟未来工单；用于最终验证，不建议反复调参。",
        "source": "data/staged/splits/holdout_trace_records.jsonl",
    },
    "eval_set_a": {
        "label": "动作命中诊断",
        "purpose": "高级诊断：检查推荐动作是否命中历史有效动作，不参与 memory 编译。",
        "source": "data/staged/eval_trace_records.jsonl + data/compiled/eval_set_a.jsonl",
    },
}


def load_dataset_traces(role: DatasetRole) -> list[dict[str, Any]]:
    path = DATASET_PATHS[role]
    if not path.exists():
        return []
    traces = [normalize_trace_record(t) for t in cio.read_jsonl(path)]
    if role != "eval_set_a":
        return traces

    eval_a_trace_ids = load_eval_set_a_trace_ids()
    if not eval_a_trace_ids:
        return []
    return [t for t in traces if t.get("trace_id") in eval_a_trace_ids]


def select_dataset_traces(
    traces: list[dict[str, Any]],
    *,
    policy: SamplePolicy = "head",
    limit: int | None = None,
) -> list[dict[str, Any]]:
    """Select a deterministic replay sample without exposing gold to the decision path."""
    selected = list(traces)
    if policy in {"gold_only", "gold_stratified"}:
        selected = [trace for trace in selected if eligible_gold_actions(trace)]
    if policy == "gold_stratified":
        buckets: dict[str, list[dict[str, Any]]] = {}
        for trace in selected:
            issue = str((trace.get("ticket") or {}).get("primary_issue_type") or "未标注")
            buckets.setdefault(issue, []).append(trace)
        selected = []
        issue_types = sorted(buckets)
        while any(buckets.values()):
            for issue in issue_types:
                if buckets[issue]:
                    selected.append(buckets[issue].pop(0))
    if policy == "outcome_stratified":
        buckets = {}
        for trace in selected:
            outcome = str((trace.get("aggregate") or {}).get("ticket_outcome") or "long_eval_unknown")
            buckets.setdefault(outcome, []).append(trace)
        selected = []
        outcomes = sorted(buckets)
        while any(buckets.values()):
            for outcome in outcomes:
                if buckets[outcome]:
                    selected.append(buckets[outcome].pop(0))
    if limit is not None and limit > 0:
        return selected[:limit]
    return selected


def trace_ids_sha256(traces: list[dict[str, Any]]) -> str:
    trace_ids = [str(trace.get("trace_id") or "") for trace in traces]
    payload = json.dumps(trace_ids, ensure_ascii=False, separators=(",", ":"))
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()


def load_eval_set_a_units() -> list[dict[str, Any]]:
    if not P.EVAL_SET_A_JSONL.exists():
        return []
    return list(cio.read_jsonl(P.EVAL_SET_A_JSONL))


def load_eval_set_a_trace_ids() -> set[str]:
    return {str(u.get("trace_id")) for u in load_eval_set_a_units() if u.get("trace_id")}


def dataset_summary(role: DatasetRole) -> dict[str, Any]:
    meta = DATASET_LABELS[role]
    path = DATASET_PATHS[role]
    traces = load_dataset_traces(role)
    trace_ids = {t.get("trace_id") for t in traces if t.get("trace_id")}
    gold_units = load_eval_set_a_units() if role == "eval_set_a" else []
    split_manifest = read_json(P.TIME_SPLIT_JSON) if P.TIME_SPLIT_JSON.exists() else {}
    ranges = split_manifest.get("ranges") if isinstance(split_manifest.get("ranges"), dict) else {}
    range_meta = ranges.get(role) if role in {"dev", "holdout"} and isinstance(ranges.get(role), dict) else {}
    return {
        "role": role,
        "label": meta["label"],
        "purpose": meta["purpose"],
        "source": meta["source"],
        "exists": path.exists(),
        "ready": bool(traces),
        "trace_count": len(traces),
        "gold_unit_count": len(gold_units),
        "gold_trace_count": len(trace_ids) if role == "eval_set_a" else sum(1 for t in traces if eligible_gold_actions(t)),
        "first_issued_at": range_meta.get("first_issued_at"),
        "last_issued_at": range_meta.get("last_issued_at"),
    }


def dataset_summaries() -> list[dict[str, Any]]:
    return [dataset_summary(role) for role in ("dev", "holdout", "eval_set_a")]


def load_trace_from_dataset(role: DatasetRole, trace_id: str) -> dict[str, Any] | None:
    for trace in load_dataset_traces(role):
        if trace.get("trace_id") == trace_id:
            return trace
    return None

"""Readiness checks for ECHO-Mem time-split experiments."""

from __future__ import annotations

import json
import subprocess
from pathlib import Path
from typing import Any

from ..common import io as cio
from ..common import paths as P
from .leakage_check import check_leakage, check_trace_batch_train_only, load_eval_set_a_trace_ids

DEFAULT_MANIFEST = P.PROJECT_ROOT / "experiments" / "config" / "manifest.json"


def read_json(path: Path) -> dict[str, Any]:
    if not path.exists():
        return {}
    return json.loads(path.read_text(encoding="utf-8"))


def git_state() -> dict[str, Any]:
    commit = None
    dirty = None
    try:
        commit = subprocess.check_output(
            ["git", "rev-parse", "HEAD"],
            cwd=P.PROJECT_ROOT,
            text=True,
            stderr=subprocess.DEVNULL,
        ).strip()
        status = subprocess.check_output(
            ["git", "status", "--porcelain"],
            cwd=P.PROJECT_ROOT,
            text=True,
            stderr=subprocess.DEVNULL,
        )
        dirty = bool(status.strip())
    except Exception:
        pass
    return {"commit": commit, "dirty": dirty}


def split_summary(split: dict[str, Any]) -> dict[str, Any]:
    ranges = split.get("ranges") if isinstance(split.get("ranges"), dict) else {}
    return {
        "split_id": split.get("split_id"),
        "split_policy": split.get("split_policy"),
        "dataset": split.get("dataset"),
        "ratios": split.get("ratios"),
        "trace_count": split.get("trace_count"),
        "ranges": {
            name: {
                "count": meta.get("count"),
                "first_issued_at": meta.get("first_issued_at"),
                "last_issued_at": meta.get("last_issued_at"),
            }
            for name, meta in ranges.items()
            if isinstance(meta, dict)
        },
    }


def _resolve_manifest_path(path: str | Path | None = None) -> Path:
    manifest_path = Path(path) if path else DEFAULT_MANIFEST
    if not manifest_path.is_absolute():
        manifest_path = P.PROJECT_ROOT / manifest_path
    return manifest_path


def _resolve_artifact_path(value: str | None, fallback: Path) -> Path:
    path = Path(value) if value else fallback
    if not path.is_absolute():
        path = P.PROJECT_ROOT / path
    return path


def build_dry_run_report(*, manifest_path: str | Path | None = None) -> dict[str, Any]:
    manifest_file = _resolve_manifest_path(manifest_path)
    manifest = read_json(manifest_file)
    split_path = _resolve_artifact_path(manifest.get("split_manifest"), P.TIME_SPLIT_JSON)
    split = read_json(split_path)

    memories_path = _resolve_artifact_path(manifest.get("memory_objects"), P.MEMORY_OBJECTS_JSONL)
    compile_batch_path = _resolve_artifact_path(manifest.get("compile_batch"), P.COMPILE_BATCH_JSONL)
    eval_set_a_path = _resolve_artifact_path(manifest.get("eval_set_a"), P.EVAL_SET_A_JSONL)

    eval_ids = load_eval_set_a_trace_ids(eval_set_a_path)
    leakage = None
    if split and memories_path.exists():
        leakage = check_leakage(
            list(cio.read_jsonl(memories_path)),
            split,
            eval_set_a_trace_ids=eval_ids,
        )

    train_only_guard = None
    if split and compile_batch_path.exists():
        train_only_guard = check_trace_batch_train_only(
            list(cio.read_jsonl(compile_batch_path)),
            split,
            eval_set_a_trace_ids=eval_ids,
        )

    checks = {
        "manifest_exists": manifest_file.exists(),
        "split_exists": split_path.exists(),
        "memory_objects_exists": memories_path.exists(),
        "compile_batch_exists": compile_batch_path.exists(),
        "leakage_ok": None if leakage is None else leakage.get("ok"),
        "compile_batch_train_only_ok": None if train_only_guard is None else train_only_guard.get("ok"),
    }
    return {
        "ok": all(v is not False for v in checks.values()) and checks["manifest_exists"] and checks["split_exists"],
        "checks": checks,
        "manifest": {
            "experiment_id": manifest.get("experiment_id"),
            "protocol_version": manifest.get("protocol_version"),
            "split_policy": manifest.get("split_policy"),
            "ranker_config_id": manifest.get("ranker_config_id"),
            "gate_config_id": manifest.get("gate_config_id"),
        },
        "git": git_state(),
        "split": split_summary(split) if split else None,
        "leakage": leakage,
        "compile_batch_train_only": train_only_guard,
    }

"""Compact model-visible state for the JSAC Phase 3 finite-state experiment."""
from __future__ import annotations

import hashlib
import json
import re
from collections import Counter
from typing import Any, Iterable


TASK_COLUMNS = (
    "prompt_state_id",
    "state_hash",
    "target",
    "candidates",
    "tried",
    "feedback",
    "selected_candidate_id",
)

TARGET_FIELDS = (
    ("issue", "primary_issue_type"),
    ("province_issue", "province_issue_type"),
    ("vendor", "vendor"),
    ("rat", "system"),
    ("region", "region"),
    ("band", "band"),
    ("scene", "is_indoor"),
    ("cover", "cover_area"),
    ("rx_ports", "antenna_rx_ports"),
    ("antenna", "antenna_type"),
    ("aau", "aau_antenna_info"),
)

FORBIDDEN_MODEL_VISIBLE_MARKERS = (
    "trace_id",
    "ticket_id",
    "gold",
    "candidate_hit",
    "first_hit_rank",
    "evaluator",
    "long_eval_pass",
    "long_eval_fail",
)


def clean(value: Any, *, maximum: int = 240) -> str:
    text = re.sub(r"\s+", " ", str(value if value is not None else "")).strip()
    text = text.replace("|", "/").replace(";", ",")
    if len(text) > maximum:
        return text[: maximum - 1].rstrip() + "…"
    return text or "NA"


def canonical_json(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def sha256_text(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def protocol_payload(config: dict[str, Any]) -> dict[str, Any]:
    interface = config["compact_interface"]
    payload = {
        "schema_version": interface["schema_version"],
        "task_objective": interface["task_objective"],
        "decision_basis": interface["decision_basis_contract"],
        "allowed_target_evidence": list(interface["target_fields"]),
        "allowed_candidate_evidence": list(interface["candidate_fields"]),
        "round_history_evidence": interface["round_history_contract"],
        "candidate_order": interface["candidate_order_contract"],
        "rank_prior_policy": interface["rank_prior_policy"],
        "tie_break_rule": interface["tie_break_rule"],
        "forced_choice_rule": interface["forced_choice_rule"],
        "objective_boundary": interface["objective_boundary"],
        "unseen_fact_assumptions_forbidden": bool(interface["unseen_fact_assumptions_forbidden"]),
        "allowed_output": "one candidate alias only",
        "allowed_aliases": "C01..C10 among the remaining candidates",
        "no_abstention": True,
        "no_new_candidate": True,
        "no_explanation": True,
        "row_independence": True,
        "cross_row_information_use": False,
        "non_selected_semantics": "not selected does not mean unsafe, wrong, or ineffective",
    }
    if interface["schema_version"] != "jsac.phase3.compact_state.v1":
        payload["echo_feedback_contract"] = config["echo_feedback_contract"]
        payload["raw_history_contract"] = config["raw_history_contract"]
    return payload


def protocol_hash(config: dict[str, Any]) -> str:
    return sha256_text(canonical_json(protocol_payload(config)))


def target_context(trace: dict[str, Any]) -> dict[str, str]:
    ticket = trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}
    return {visible: clean(ticket.get(source), maximum=120) for visible, source in TARGET_FIELDS}


def target_cell(context: dict[str, Any]) -> str:
    return ";".join(f"{key}={clean(context.get(key), maximum=120)}" for key, _ in TARGET_FIELDS)


def candidate_alias(rank: int) -> str:
    if rank < 1 or rank > 99:
        raise ValueError("candidate rank cannot be represented by the frozen alias contract")
    return f"C{rank:02d}"


def compact_candidate(candidate: dict[str, Any], rank: int) -> dict[str, str]:
    action = candidate.get("action") if isinstance(candidate.get("action"), dict) else {}
    identity = candidate.get("identity") if isinstance(candidate.get("identity"), dict) else {}
    parameter = clean(action.get("param_cn_name") or action.get("param_en_name"), maximum=100)
    semantic = clean(action.get("parameter_semantic_id"), maximum=120)
    transition = clean(
        action.get("change")
        or (
            f"{action.get('before_value')}->{action.get('after_value')}"
            if action.get("before_value") is not None or action.get("after_value") is not None
            else action.get("suggested_delta")
        ),
        maximum=80,
    )
    return {
        "alias": candidate_alias(rank),
        "scheme": clean(f"{action.get('scheme_group') or ''}/{action.get('scheme_id') or ''}", maximum=80),
        "parameter": parameter,
        "semantic": semantic,
        "object": clean(action.get("param_object") or action.get("site_param_object"), maximum=80),
        "direction": clean(action.get("direction"), maximum=40),
        "transition": transition,
        "scope": clean(identity.get("scope"), maximum=40),
        "companions": clean(identity.get("companion_signature"), maximum=120),
    }


def candidate_cell(candidates: Iterable[dict[str, Any]]) -> str:
    rows = []
    for candidate in candidates:
        rows.append(
            "|".join(
                [
                    candidate["alias"],
                    f"scheme={candidate['scheme']}",
                    f"param={candidate['parameter']}",
                    f"semantic={candidate['semantic']}",
                    f"object={candidate['object']}",
                    f"dir={candidate['direction']}",
                    f"value={candidate['transition']}",
                    f"scope={candidate['scope']}",
                    f"companions={candidate['companions']}",
                ]
            )
        )
    return "\n".join(rows)


def tried_cell(attempted_aliases: list[str]) -> str:
    if not attempted_aliases:
        return "none"
    return ";".join(f"R{index}={alias}" for index, alias in enumerate(attempted_aliases, start=1))


def feedback_cell(feedback_by_round: list[str]) -> str:
    if not feedback_by_round:
        return "none"
    return "\n".join(f"R{index}|{feedback}" for index, feedback in enumerate(feedback_by_round, start=1))


def model_state(
    *,
    protocol_digest: str,
    round_number: int,
    branch: str,
    target: dict[str, Any],
    remaining_candidates: list[dict[str, Any]],
    attempted_aliases: list[str],
    feedback_by_round: list[str],
) -> dict[str, Any]:
    if round_number == 1 and branch != "common":
        raise ValueError("Round 1 must use the common branch")
    if round_number > 1 and branch not in {"echo", "raw_history"}:
        raise ValueError("Round 2+ must use an allowed feedback branch")
    state = {
        "protocol_hash": protocol_digest,
        "round": round_number,
        "branch": branch,
        "target": target_cell(target),
        "candidates": candidate_cell(remaining_candidates),
        "tried": tried_cell(attempted_aliases),
        "feedback": feedback_cell(feedback_by_round),
    }
    visible = "\n".join(str(value) for value in state.values()).lower()
    leaked = [marker for marker in FORBIDDEN_MODEL_VISIBLE_MARKERS if marker in visible]
    if leaked:
        raise ValueError(f"forbidden model-visible marker: {leaked}")
    return state


def state_hash(state: dict[str, Any]) -> str:
    return sha256_text(canonical_json(state))


def prompt_state_id(digest: str) -> str:
    return f"PS-{digest[:24].upper()}"


def task_row(state: dict[str, Any]) -> dict[str, str]:
    digest = state_hash(state)
    row = {
        "prompt_state_id": prompt_state_id(digest),
        "state_hash": digest,
        "target": str(state["target"]),
        "candidates": str(state["candidates"]),
        "tried": str(state["tried"]),
        "feedback": str(state["feedback"]),
        "selected_candidate_id": "",
    }
    if tuple(row) != TASK_COLUMNS:
        raise ValueError("task row differs from the frozen compact schema")
    return row


def exact_states(logical_calls: Iterable[dict[str, Any]]) -> list[dict[str, Any]]:
    grouped: dict[str, dict[str, Any]] = {}
    for call in logical_calls:
        state = call["state"]
        digest = state_hash(state)
        stored = grouped.setdefault(
            digest,
            {
                "prompt_state_id": prompt_state_id(digest),
                "state_hash": digest,
                "state": state,
                "logical_call_ids": [],
            },
        )
        if stored["state"] != state:
            raise ValueError("state hash collision")
        stored["logical_call_ids"].append(str(call["logical_call_id"]))
    return sorted(grouped.values(), key=lambda row: row["state_hash"])


def reuse_statistics(logical_decisions: int, unique_state_hashes: Iterable[str]) -> dict[str, Any]:
    unique_states = len(set(unique_state_hashes))
    reused = logical_decisions - unique_states
    return {
        "logical_agent_decisions": logical_decisions,
        "unique_prompt_states": unique_states,
        "exact_state_reuses": reused,
        "exact_state_reuse_rate": reused / logical_decisions if logical_decisions else None,
    }


def _normalize_state(value: Any) -> str:
    text = clean(value, maximum=80).lower()
    return text[: -len("_profile")] if text.endswith("_profile") else text


def echo_feedback_records(
    *,
    target: dict[str, Any],
    ordered_memory_ids: list[str],
    memory_objects: dict[str, dict[str, Any]],
    governance: dict[str, dict[str, Any]],
    profiles: dict[str, dict[str, Any]],
    maximum_sources: int,
) -> str:
    rows = []
    for index, memory_id in enumerate(ordered_memory_ids[:maximum_sources], start=1):
        memory = memory_objects.get(memory_id) or {}
        gov = governance.get(memory_id) or {}
        profile = profiles.get(memory_id) or {}
        applicability = memory.get("applicability") if isinstance(memory.get("applicability"), dict) else {}
        metrics = memory.get("metrics") if isinstance(memory.get("metrics"), dict) else {}
        stats = profile.get("outcome_statistics") if isinstance(profile.get("outcome_statistics"), dict) else {}
        app = compact_applicability(target, applicability)
        evidence_state = _normalize_state(gov.get("evidence_state") or profile.get("profile_type"))
        negative = int(evidence_state in {"counter", "conflict"} or int(stats.get("long_eval_fail_count") or metrics.get("long_eval_fail_count") or 0) > 0)
        eligibility = clean(gov.get("use_eligibility"), maximum=40).lower()
        support_n = int(stats.get("long_eval_pass_count") or metrics.get("long_eval_pass_count") or 0)
        fail_n = int(stats.get("long_eval_fail_count") or metrics.get("long_eval_fail_count") or 0)
        provenance_n = int(memory.get("provenance_n") or metrics.get("support_count") or 0)
        rows.append(
            f"M{index}|app={app}|state={evidence_state}|negative={negative}|eligibility={eligibility}|"
            f"support_n={support_n}|fail_n={fail_n}|provenance_n={provenance_n}"
        )
    return ";".join(rows) if rows else "no_memory_source"


FORMAL_EVIDENCE_STATES = ("support", "counter", "conflict", "sparse")


def _count_value(primary: dict[str, Any], fallback: dict[str, Any], key: str) -> int:
    value = primary.get(key)
    if value is None:
        value = fallback.get(key, 0)
    return int(value or 0)


def _eligibility_bucket(value: Any, *, ineligible_label: str = "inactive") -> str:
    normalized = clean(value, maximum=40).lower()
    if normalized.startswith("auto"):
        return "auto"
    if normalized.startswith("review"):
        return "review"
    if normalized.startswith("inactive") or normalized.startswith("ineligible"):
        return ineligible_label
    return "other"


def echo_candidate_feedback_summary(
    *,
    target: dict[str, Any],
    ordered_memory_ids: list[str],
    memory_objects: dict[str, dict[str, Any]],
    governance: dict[str, dict[str, Any]],
    profiles: dict[str, dict[str, Any]],
    maximum_sources: int,
    schema_version: str = "v1",
) -> str:
    """Aggregate bounded linked Memory records into one candidate-level view."""
    if schema_version not in {"v1", "v2", "v3"}:
        raise ValueError(f"unsupported candidate feedback summary schema: {schema_version}")
    ineligible_label = "ineligible" if schema_version in {"v2", "v3"} else "inactive"
    selected_ids = ordered_memory_ids[:maximum_sources]
    app_counts = Counter({key: 0 for key in ("compatible", "uncertain", "incompatible")})
    state_counts = Counter({key: 0 for key in FORMAL_EVIDENCE_STATES})
    raw_signal_counts = Counter({key: 0 for key in ("pass", "fail", "mixed")})
    eligibility_order = ("auto", "review", ineligible_label, "other")
    eligibility_counts = Counter({key: 0 for key in eligibility_order})
    profiled_n = 0
    negative_memory_n = 0
    provenance_ids: set[str] = set()

    for memory_id in selected_ids:
        memory = memory_objects.get(memory_id) or {}
        gov = governance.get(memory_id) or {}
        profile = profiles.get(memory_id) or {}
        applicability = memory.get("applicability") if isinstance(memory.get("applicability"), dict) else {}
        metrics = memory.get("metrics") if isinstance(memory.get("metrics"), dict) else {}
        stats = profile.get("outcome_statistics") if isinstance(profile.get("outcome_statistics"), dict) else {}
        app_counts[compact_applicability(target, applicability)] += 1

        state = _normalize_state(gov.get("evidence_state"))
        if state not in FORMAL_EVIDENCE_STATES:
            state = _normalize_state(profile.get("profile_type"))
        if state in FORMAL_EVIDENCE_STATES:
            profiled_n += 1
            state_counts[state] += 1

        pass_n = _count_value(stats, metrics, "long_eval_pass_count")
        fail_n = _count_value(stats, metrics, "long_eval_fail_count")
        raw_signal_counts["pass"] += int(pass_n > 0)
        raw_signal_counts["fail"] += int(fail_n > 0)
        raw_signal_counts["mixed"] += int(pass_n > 0 and fail_n > 0)
        negative_memory_n += int(state in {"counter", "conflict"} or fail_n > 0)
        eligibility_counts[
            _eligibility_bucket(gov.get("use_eligibility"), ineligible_label=ineligible_label)
        ] += 1
        provenance_ids.update(str(value) for value in memory.get("trace_ids") or [] if value)

    memory_n = len(selected_ids)
    if profiled_n == 0:
        profile_status = "unprofiled"
    elif profiled_n == memory_n:
        profile_status = "profiled"
    else:
        profile_status = "partial"
    unprofiled_n = memory_n - profiled_n

    compact_counts = lambda counts, order: ",".join(f"{key}:{counts[key]}" for key in order)
    fields = [
        f"view_memory_n={memory_n}",
        f"profile_status={profile_status}",
        f"profiled_n={profiled_n}",
        f"unprofiled_n={unprofiled_n}",
        f"app_counts={compact_counts(app_counts, ('compatible', 'uncertain', 'incompatible'))}",
        f"state_counts={compact_counts(state_counts, FORMAL_EVIDENCE_STATES)}",
    ]
    # v3 is the governed Agent-facing projection.  Raw Pass/Fail presence may
    # exist behind an unprofiled Memory record, but Evidence Authority does not
    # authorize it as candidate-level outcome evidence.  It is deliberately
    # absent from the model-visible view instead of relying on prose to make an
    # LLM ignore an attractive but unauthorized signal.
    if schema_version in {"v1", "v2"}:
        fields.append(
            f"raw_signal_memory_counts={compact_counts(raw_signal_counts, ('pass', 'fail', 'mixed'))}"
        )
    if schema_version == "v1":
        fields.append(f"negative_memory_n={negative_memory_n}")
    fields.extend(
        [
            f"eligibility_counts={compact_counts(eligibility_counts, eligibility_order)}",
            f"provenance_unique_n={len(provenance_ids)}",
        ]
    )
    return "|".join(fields)


def _values(value: Any) -> set[str]:
    if isinstance(value, list):
        return {clean(item, maximum=120).lower() for item in value if clean(item, maximum=120) != "NA"}
    text = clean(value, maximum=120).lower()
    return {text} if text != "na" else set()


def compact_applicability(target: dict[str, Any], applicability: dict[str, Any]) -> str:
    fields = (
        ("vendor", "vendors", True),
        ("rat", "systems", True),
        ("issue", "issue_types", False),
        ("region", "regions", False),
        ("band", "bands", False),
        ("scene", "indoor_outdoor", False),
    )
    compared = 0
    soft_mismatch = False
    for target_key, source_key, hard in fields:
        target_value = clean(target.get(target_key), maximum=120).lower()
        allowed = _values(applicability.get(source_key))
        if target_value == "na" or not allowed:
            continue
        compared += 1
        if target_value not in allowed:
            if hard:
                return "incompatible"
            soft_mismatch = True
    if compared == 0 or soft_mismatch:
        return "uncertain"
    return "compatible"


def raw_feedback_records(
    *,
    target: dict[str, Any],
    provenance_rows: list[dict[str, Any]],
    maximum_sources: int,
) -> str:
    rows = []
    seen_case_ids: set[str] = set()
    for source in provenance_rows:
        case_id = str(source.get("source_case_id") or "")
        if not case_id or case_id in seen_case_ids:
            continue
        seen_case_ids.add(case_id)
        context = source.get("context") if isinstance(source.get("context"), dict) else {}
        matches = {
            "issue": int(clean(target.get("issue")).lower() == clean(context.get("issue")).lower()),
            "vendor": int(clean(target.get("vendor")).lower() == clean(context.get("vendor")).lower()),
            "rat": int(clean(target.get("rat")).lower() == clean(context.get("rat")).lower()),
            "region": int(clean(target.get("region")).lower() == clean(context.get("region")).lower()),
            "band": int(clean(target.get("band")).lower() == clean(context.get("band")).lower()),
            "scene": int(clean(target.get("scene")).lower() == clean(context.get("scene")).lower()),
        }
        rows.append(
            f"H{len(rows)+1}|issue={matches['issue']}|vendor={matches['vendor']}|rat={matches['rat']}|"
            f"region={matches['region']}|band={matches['band']}|scene={matches['scene']}|"
            f"outcome={clean(source.get('outcome'), maximum=20)}|"
            f"attribution_scope={clean(source.get('attribution_scope'), maximum=20)}"
        )
        if len(rows) >= maximum_sources:
            break
    return ";".join(rows) if rows else "no_raw_source"


def selected_alias_is_valid(selected: Any, remaining_aliases: Iterable[str]) -> str:
    value = clean(selected, maximum=20)
    if value not in set(remaining_aliases) or not re.fullmatch(r"C\d{2}", value):
        raise ValueError("invalid candidate alias; no repair or retry is allowed")
    return value


def selection_agreement(*selection_maps: dict[str, str]) -> dict[str, Any]:
    if len(selection_maps) < 2:
        raise ValueError("agreement requires at least two executions")
    shared = set.intersection(*(set(mapping) for mapping in selection_maps))
    counts = Counter()
    for state_id in shared:
        values = [mapping[state_id] for mapping in selection_maps]
        counts["all_agree"] += int(len(set(values)) == 1)
    return {
        "shared_prompt_states": len(shared),
        "all_execution_agreement_count": counts["all_agree"],
        "all_execution_agreement_rate": counts["all_agree"] / len(shared) if shared else None,
    }

"""Deterministic utilities for the JSAC Phase-4 Layer-2 development dry-run."""
from __future__ import annotations

import bisect
import hashlib
import json
import math
from collections import Counter, defaultdict
from dataclasses import dataclass
from datetime import datetime
from typing import Any, Iterable


PASS = "long_eval_pass"
FAIL = "long_eval_fail"
ACTION_KEYS = (
    "scheme_id",
    "scheme_group",
    "param_object",
    "site_param_object",
    "param_en_name",
    "site_param_en_name",
    "param_cn_name",
    "parameter_group",
    "before_value",
    "after_value",
    "value_rule",
    "adjustment_rule",
    "final_ratio",
    "exec_id",
)
CONTEXT_FIELDS = (
    "primary_issue_type",
    "vendor",
    "system",
    "region",
    "band",
)
CONTEXT_WEIGHTS = {
    "primary_issue_type": 8.0,
    "vendor": 4.0,
    "system": 3.0,
    "region": 2.0,
    "band": 1.0,
}


def canonical_json(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def sha256_value(value: Any) -> str:
    return hashlib.sha256(canonical_json(value).encode("utf-8")).hexdigest()


def text(value: Any) -> str:
    return str(value if value is not None else "").strip().lower()


def project_ticket(ticket: dict[str, Any]) -> dict[str, Any]:
    allowed = (
        "ticket_category",
        "ticket_type",
        "primary_issue_type",
        "province_issue_type",
        "cell_name",
        "network_element_name",
        "site_name",
        "antenna_rx_ports",
        "aau_antenna_info",
        "antenna_type",
        "cover_area",
        "region",
        "vendor",
        "is_indoor",
        "band",
        "system",
    )
    return {key: ticket.get(key) for key in allowed}


def project_action(action: dict[str, Any]) -> dict[str, Any]:
    return {key: action.get(key) for key in ACTION_KEYS}


def decision_bundle(trace: dict[str, Any]) -> dict[str, Any]:
    actions = sorted(
        [project_action(action) for action in trace.get("actions") or [] if isinstance(action, dict)],
        key=canonical_json,
    )
    ticket = project_ticket(trace.get("ticket") or {})
    return {
        "ticket_context": ticket,
        "proposed_plan_bundle": actions,
        "bundle_hash": sha256_value(actions),
        "action_count": len(actions),
    }


def execution_class(trace: dict[str, Any]) -> str:
    states = [str(action.get("exec_state") or "unknown") for action in trace.get("actions") or []]
    if states and all(state == "exec_success" for state in states):
        return "complete_exec_success"
    if "exec_success" in states and any(state != "exec_success" for state in states):
        return "partial_execution"
    if states and all(state == "exec_failed" for state in states):
        return "all_exec_failed"
    return "other_execution_state"


def ticket_outcome(trace: dict[str, Any]) -> str:
    value = str((trace.get("aggregate") or {}).get("ticket_outcome") or "long_eval_unknown")
    return value if value in {PASS, FAIL, "long_eval_mixed"} else "long_eval_unknown"


def primary_risk_eligible(trace: dict[str, Any]) -> bool:
    return execution_class(trace) == "complete_exec_success" and ticket_outcome(trace) in {PASS, FAIL}


def review_count(n: int, budget: float) -> int:
    return int(math.floor(n * budget + 0.5))


def tie_score(trace_id: str) -> int:
    digest = hashlib.sha256(f"jsac-phase4-review-tie-v1|{trace_id}".encode()).digest()
    return int.from_bytes(digest[:8], "big")


def review_ids(scores: dict[str, float], budget: float) -> set[str]:
    k = review_count(len(scores), budget)
    ranked = sorted(
        scores,
        key=lambda trace_id: (float(scores[trace_id]), tie_score(trace_id)),
        reverse=True,
    )
    return set(ranked[:k])


def right_ecdf(scores: dict[str, float]) -> dict[str, float]:
    ordered = sorted(float(value) for value in scores.values())
    n = len(ordered)
    if not n:
        return {}
    return {
        trace_id: bisect.bisect_right(ordered, float(value)) / n
        for trace_id, value in scores.items()
    }


def fuse_scores(
    base_scores: dict[str, float],
    auxiliary_scores: dict[str, float],
    *,
    base_weight: float,
) -> dict[str, float]:
    if set(base_scores) != set(auxiliary_scores):
        raise ValueError("base and auxiliary score populations differ")
    base_q = right_ecdf(base_scores)
    aux_q = right_ecdf(auxiliary_scores)
    return {
        trace_id: base_weight * base_q[trace_id] + (1.0 - base_weight) * aux_q[trace_id]
        for trace_id in base_scores
    }


def fraction(numerator: int, denominator: int) -> dict[str, Any]:
    return {
        "numerator": int(numerator),
        "denominator": int(denominator),
        "value": numerator / denominator if denominator else None,
    }


def operating_point(
    *,
    scores: dict[str, float],
    outcomes: dict[str, str],
    budget: float,
) -> dict[str, Any]:
    if set(scores) != set(outcomes):
        raise ValueError("score and outcome populations differ")
    selected = review_ids(scores, budget)
    total_fail = sum(value == FAIL for value in outcomes.values())
    total_pass = sum(value == PASS for value in outcomes.values())
    reviewed_fail = sum(outcomes[trace_id] == FAIL for trace_id in selected)
    reviewed_pass = len(selected) - reviewed_fail
    prevalence = total_fail / len(outcomes) if outcomes else None
    review_yield = reviewed_fail / len(selected) if selected else None
    return {
        "target_count": len(outcomes),
        "review_count": len(selected),
        "review_set_hash": hashlib.sha256("\n".join(sorted(selected)).encode()).hexdigest(),
        "historical_failure_capture": fraction(reviewed_fail, total_fail),
        "review_yield": fraction(reviewed_fail, len(selected)),
        "pass_to_review": fraction(reviewed_pass, total_pass),
        "fail_to_auto": fraction(total_fail - reviewed_fail, total_fail),
        "failure_enrichment": (review_yield / prevalence) if review_yield is not None and prevalence else None,
        "reviewed_fail_count": reviewed_fail,
        "reviewed_pass_count": reviewed_pass,
        "risk_score_unique_count": len(set(scores.values())),
        "selected_ids": selected,
    }


def paired_review_contrast(
    *,
    left_selected: set[str],
    right_selected: set[str],
    outcomes: dict[str, str],
) -> dict[str, Any]:
    failures = {trace_id for trace_id, value in outcomes.items() if value == FAIL}
    left_fail = left_selected & failures
    right_fail = right_selected & failures
    return {
        "left_only_reviewed_fail": len(left_fail - right_fail),
        "right_only_reviewed_fail": len(right_fail - left_fail),
        "both_reviewed_fail": len(left_fail & right_fail),
        "net_additional_captured_fail": len(left_fail) - len(right_fail),
        "hfc_difference": (len(left_fail) - len(right_fail)) / len(failures) if failures else None,
        "review_set_symmetric_difference": len(left_selected ^ right_selected),
    }


def raw_action_tokens(bundle: dict[str, Any]) -> frozenset[str]:
    tokens: set[str] = set()
    for action in bundle.get("proposed_plan_bundle") or []:
        scheme = text(action.get("scheme_id"))
        parameter = text(
            action.get("site_param_en_name")
            or action.get("param_en_name")
            or action.get("param_cn_name")
            or action.get("param_object")
        )
        obj = text(action.get("param_object"))
        change = f"{text(action.get('before_value'))}->{text(action.get('after_value'))}"
        tokens.update({f"scheme={scheme}", f"param={parameter}", f"object={obj}", f"change={change}"})
    return frozenset(token for token in tokens if not token.endswith("="))


@dataclass(frozen=True)
class RawHistoryRecord:
    trace_id: str
    visible_at: str
    visible_timestamp: float
    outcome: str
    context: dict[str, str]
    action_tokens: frozenset[str]
    bundle_hash: str
    action_count: int


class RawHistoryIndex:
    """Outcome-blind M-case retrieval over the same mature history view."""

    def __init__(self, records: Iterable[RawHistoryRecord]) -> None:
        self.records = list(records)
        self.by_id = {record.trace_id: record for record in self.records}
        self.postings: dict[str, set[str]] = defaultdict(set)
        for record in self.records:
            self.postings[f"bundle={record.bundle_hash}"].add(record.trace_id)
            for field, value in record.context.items():
                if value:
                    self.postings[f"context:{field}={value}"].add(record.trace_id)
            for token in record.action_tokens:
                self.postings[f"action:{token}"].add(record.trace_id)
        self.recent_ids = [
            record.trace_id
            for record in sorted(
                self.records,
                key=lambda row: (-row.visible_timestamp, row.trace_id),
            )
        ]
        recent_rank = {trace_id: index for index, trace_id in enumerate(self.recent_ids)}
        self.posting_ordered = {
            key: sorted(trace_ids, key=recent_rank.__getitem__)
            for key, trace_ids in self.postings.items()
        }

    def query(
        self,
        bundle: dict[str, Any],
        *,
        m: int,
        max_candidate_scan: int = 4096,
    ) -> dict[str, Any]:
        if max_candidate_scan < m:
            raise ValueError("max_candidate_scan must be at least m")
        context = {field: text((bundle.get("ticket_context") or {}).get(field)) for field in CONTEXT_FIELDS}
        tokens = raw_action_tokens(bundle)
        bundle_hash = str(bundle.get("bundle_hash") or "")

        exact_key = f"bundle={bundle_hash}"
        secondary_keys: set[str] = set()
        for field, value in context.items():
            if value:
                key = f"context:{field}={value}"
                if self.postings.get(key):
                    secondary_keys.add(key)
        for token in tokens:
            key = f"action:{token}"
            if self.postings.get(key):
                secondary_keys.add(key)

        # This shortlist is built without outcomes. Exact-bundle matches are kept
        # first; other matching postings are traversed rarest first, while each
        # posting is internally ordered by visible recency and trace ID.
        ordered_secondary = sorted(
            secondary_keys,
            key=lambda key: (len(self.postings[key]), key),
        )
        candidates: set[str] = set()

        def add_from_posting(key: str, limit: int) -> None:
            if limit <= 0:
                return
            added = 0
            for trace_id in self.posting_ordered.get(key, []):
                if trace_id in candidates:
                    continue
                candidates.add(trace_id)
                added += 1
                if added >= limit or len(candidates) >= max_candidate_scan:
                    break

        add_from_posting(exact_key, max_candidate_scan)
        if len(candidates) < max_candidate_scan and ordered_secondary:
            remaining = max_candidate_scan - len(candidates)
            quota = max(m, remaining // len(ordered_secondary))
            for key in ordered_secondary:
                add_from_posting(key, min(quota, max_candidate_scan - len(candidates)))
                if len(candidates) >= max_candidate_scan:
                    break
            for key in ordered_secondary:
                add_from_posting(key, max_candidate_scan - len(candidates))
                if len(candidates) >= max_candidate_scan:
                    break
        if len(candidates) < m:
            for trace_id in self.recent_ids:
                candidates.add(trace_id)
                if len(candidates) >= m:
                    break

        def similarity(record: RawHistoryRecord) -> float:
            score = 100.0 if bundle_hash and record.bundle_hash == bundle_hash else 0.0
            overlap = len(tokens & record.action_tokens)
            union = len(tokens | record.action_tokens)
            score += 20.0 * overlap
            score += 5.0 * (overlap / union if union else 0.0)
            score += sum(
                CONTEXT_WEIGHTS[field]
                for field, value in context.items()
                if value and value == record.context.get(field)
            )
            score += float(record.action_count == int(bundle.get("action_count") or 0))
            return score

        ranked = sorted(
            (self.by_id[trace_id] for trace_id in candidates),
            key=lambda record: (-similarity(record), -record.visible_timestamp, record.trace_id),
        )
        selected = ranked[:m]
        counts = Counter(record.outcome for record in selected)
        passed = counts[PASS]
        failed = counts[FAIL]
        return {
            "risk_score": (failed + 1.0) / (passed + failed + 2.0),
            "selected_trace_ids": [record.trace_id for record in selected],
            "pass_count": passed,
            "fail_count": failed,
            "selected_count": len(selected),
            "candidate_scan_count": len(candidates),
            "matching_source_count": len(ordered_secondary) + int(bool(self.postings.get(exact_key))),
        }


def make_raw_record(trace: dict[str, Any], *, visible_at: str) -> RawHistoryRecord:
    bundle = decision_bundle(trace)
    parsed = datetime.fromisoformat(visible_at)
    return RawHistoryRecord(
        trace_id=str(trace.get("trace_id") or ""),
        visible_at=visible_at,
        visible_timestamp=parsed.timestamp(),
        outcome=ticket_outcome(trace),
        context={field: text((bundle.get("ticket_context") or {}).get(field)) for field in CONTEXT_FIELDS},
        action_tokens=raw_action_tokens(bundle),
        bundle_hash=str(bundle["bundle_hash"]),
        action_count=int(bundle["action_count"]),
    )

"""Check that train-only memories do not reference dev/holdout/eval traces."""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import Any

from ..common import io as cio
from ..common import paths as P


def _ids_from_eval_set_a(path: Path) -> set[str]:
    ids: set[str] = set()
    if not path.exists():
        return ids
    for unit in cio.read_jsonl(path):
        tid = unit.get("trace_id")
        if tid:
            ids.add(str(tid))
    return ids


def load_eval_set_a_trace_ids(path: Path = P.EVAL_SET_A_JSONL) -> set[str]:
    return _ids_from_eval_set_a(path)


def _memory_trace_ids(memories: list[dict[str, Any]]) -> set[str]:
    ids: set[str] = set()
    for memory in memories:
        for tid in memory.get("trace_ids") or []:
            if tid:
                ids.add(str(tid))
    return ids


def check_leakage(
    memories: list[dict[str, Any]],
    split: dict[str, Any],
    *,
    eval_set_a_trace_ids: set[str] | None = None,
) -> dict[str, Any]:
    memory_ids = _memory_trace_ids(memories)
    forbidden = {
        "dev": set(map(str, split.get("dev_trace_ids") or [])),
        "holdout": set(map(str, split.get("holdout_trace_ids") or [])),
        "eval_set_a": set(eval_set_a_trace_ids or set()),
    }
    overlaps = {
        name: sorted(memory_ids & ids)
        for name, ids in forbidden.items()
    }
    leaked = {name: ids for name, ids in overlaps.items() if ids}
    return {
        "ok": not leaked,
        "memory_trace_count": len(memory_ids),
        "checked": {name: len(ids) for name, ids in forbidden.items()},
        "overlap_counts": {name: len(ids) for name, ids in overlaps.items()},
        "overlap_examples": {name: ids[:20] for name, ids in overlaps.items() if ids},
    }


def _trace_ids_from_records(records: list[dict[str, Any]]) -> set[str]:
    return {str(r.get("trace_id")) for r in records if r.get("trace_id")}


def check_trace_batch_train_only(
    records: list[dict[str, Any]],
    split: dict[str, Any],
    *,
    eval_set_a_trace_ids: set[str] | None = None,
) -> dict[str, Any]:
    """Verify a compile batch contains only train split traces.

    This is stricter than post-hoc leakage_check: it fails before compile if a
    dev/holdout/Eval-A trace enters the batch.
    """
    batch_ids = _trace_ids_from_records(records)
    train_ids = set(map(str, split.get("train_trace_ids") or []))
    forbidden = {
        "dev": set(map(str, split.get("dev_trace_ids") or [])),
        "holdout": set(map(str, split.get("holdout_trace_ids") or [])),
        "eval_set_a": set(eval_set_a_trace_ids or set()),
    }
    non_train = sorted(batch_ids - train_ids)
    overlaps = {name: sorted(batch_ids & ids) for name, ids in forbidden.items()}
    leaked = {name: ids for name, ids in overlaps.items() if ids}
    ok = not non_train and not leaked and bool(batch_ids)
    return {
        "ok": ok,
        "batch_trace_count": len(batch_ids),
        "train_trace_count": len(train_ids),
        "non_train_count": len(non_train),
        "non_train_examples": non_train[:20],
        "overlap_counts": {name: len(ids) for name, ids in overlaps.items()},
        "overlap_examples": {name: ids[:20] for name, ids in overlaps.items() if ids},
    }


def main() -> None:
    ap = argparse.ArgumentParser(description="Verify memory_objects do not leak dev/holdout/eval traces")
    ap.add_argument("--memories", default=str(P.MEMORY_OBJECTS_JSONL))
    ap.add_argument("--split", default=str(P.TIME_SPLIT_JSON))
    ap.add_argument("--eval-set-a", default=str(P.EVAL_SET_A_JSONL))
    ap.add_argument("--out", default="")
    args = ap.parse_args()

    split_path = Path(args.split)
    if not split_path.exists():
        raise SystemExit(f"[leakage_check] split not found: {split_path}")
    split = json.loads(split_path.read_text(encoding="utf-8"))
    memories = list(cio.read_jsonl(args.memories))
    result = check_leakage(
        memories,
        split,
        eval_set_a_trace_ids=_ids_from_eval_set_a(Path(args.eval_set_a)),
    )

    text = json.dumps(result, ensure_ascii=False, indent=2)
    if args.out:
        out = Path(args.out)
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_text(text, encoding="utf-8")
    print(text)
    if not result["ok"]:
        print("[leakage_check] FAILED: memory_objects reference forbidden trace ids", file=sys.stderr)
        raise SystemExit(1)
    print("[leakage_check] OK", file=sys.stderr)


if __name__ == "__main__":
    main()

"""Evaluation labels and aggregate metrics for ECHO-Mem shadow replay.

The rules here implement docs/plans/experiment-evaluation-contract.md.
They intentionally separate historical-gold consistency from absolute
correctness: a safe, evidence-supported recommendation that does not match
the historical gold action is classified as plausible unknown, not wrong.
"""

from __future__ import annotations

from collections import Counter
from typing import Any, Iterable

from .action_set_evaluation import score_decision_action_set

GateDecision = str
SafetyLabel = str
EvidenceLabel = str
OutcomeClass = str

ACCEPTED_GATES = {"accept", "downgrade"}
COVERED_GATES = {"accept", "downgrade", "require_review"}
ACTION_MATCH_TIERS = {"full", "param"}
PLAN_MATCH_TIERS = {"full", "param", "scheme"}
EVIDENCE_SUPPORTED = {"strong_train_support", "weak_train_support", "case_only_support"}
FAILCOHORT_CONFLICT_THRESHOLD = 0.55
FAILCOHORT_STRONG_CONFLICT_THRESHOLD = 0.65


def _as_list(value: Any) -> list[Any]:
    return value if isinstance(value, list) else []


def _non_empty(value: Any) -> bool:
    if isinstance(value, dict):
        return any(_non_empty(v) for v in value.values())
    if isinstance(value, list):
        return any(_non_empty(v) for v in value)
    return bool(value)


def _recommended_action(decision: dict[str, Any], evaluation: dict[str, Any] | None = None) -> dict[str, Any]:
    rec = decision.get("recommended_action")
    if isinstance(rec, dict) and _non_empty(rec):
        return rec
    for key in ("recommended_action_set", "recommended_actions", "action_set", "selected_actions"):
        actions = _as_list(decision.get(key))
        first = next((item for item in actions if isinstance(item, dict) and _non_empty(item)), None)
        if first:
            return first
    if evaluation:
        rec = evaluation.get("recommended_action")
        if isinstance(rec, dict) and _non_empty(rec):
            return rec
        for key in ("recommended_action_set", "recommended_actions"):
            actions = _as_list(evaluation.get(key))
            first = next((item for item in actions if isinstance(item, dict) and _non_empty(item)), None)
            if first:
                return first
    return {}


def _action_set_evaluation(
    decision: dict[str, Any],
    evaluation: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if evaluation:
        action_set = evaluation.get("action_set_evaluation")
        if isinstance(action_set, dict):
            return action_set
    return score_decision_action_set(decision, evaluation)


def _nested_number(data: dict[str, Any], *path: str) -> float:
    current: Any = data
    for key in path:
        if not isinstance(current, dict):
            return 0.0
        current = current.get(key)
    try:
        return float(current or 0.0)
    except (TypeError, ValueError):
        return 0.0


def _nested_bool(data: dict[str, Any], key: str) -> bool:
    return bool(data.get(key))


def infer_gate_decision(decision: dict[str, Any], evaluation: dict[str, Any] | None = None) -> GateDecision:
    """Return explicit gate_decision when available, otherwise infer it.

    Current shadow output has `veto_hits`, `needs_human_review` and
    `risk_level`, but not yet a full gate module. This inference keeps old
    replay logs usable while making the future explicit field authoritative.
    """
    explicit = str(decision.get("gate_decision") or "").strip()
    if explicit in {"accept", "downgrade", "require_review", "reject"}:
        return explicit
    if not _recommended_action(decision, evaluation):
        return "reject"
    if decision.get("needs_human_review") or decision.get("risk_level") == "high":
        return "require_review"
    if decision.get("risk_level") == "medium":
        return "downgrade"
    return "accept"


def has_veto_hit(decision: dict[str, Any], evaluation: dict[str, Any] | None = None) -> bool:
    score = failcohort_hit_score(decision)
    if score is not None:
        return score >= FAILCOHORT_CONFLICT_THRESHOLD
    if _as_list(decision.get("veto_hits")):
        return True
    supporting = decision.get("supporting_knowledge") if isinstance(decision.get("supporting_knowledge"), dict) else {}
    if _as_list(supporting.get("veto_memory_ids")):
        return True
    if evaluation and evaluation.get("hit_counter_evidence"):
        return True
    return False


def has_strong_veto_hit(decision: dict[str, Any], evaluation: dict[str, Any] | None = None) -> bool:
    score = failcohort_hit_score(decision)
    if score is not None:
        return score >= FAILCOHORT_STRONG_CONFLICT_THRESHOLD
    # Legacy logs only have boolean veto ids. Treat those as strong so older
    # artifacts keep their original safety meaning.
    return has_veto_hit(decision, evaluation)


def failcohort_hit_score(decision: dict[str, Any]) -> float | None:
    evaluator = decision.get("evaluation_failcohort") if isinstance(decision.get("evaluation_failcohort"), dict) else {}
    if "action_specific_hit_score" in evaluator:
        try:
            return float(evaluator.get("action_specific_hit_score") or 0.0)
        except (TypeError, ValueError):
            return None
    if "hit_score" in evaluator:
        try:
            return float(evaluator.get("hit_score") or 0.0)
        except (TypeError, ValueError):
            return None
    diagnostics = decision.get("gate_diagnostics") if isinstance(decision.get("gate_diagnostics"), dict) else {}
    if "failcohort_hit_score" in diagnostics:
        try:
            return float(diagnostics.get("failcohort_hit_score") or 0.0)
        except (TypeError, ValueError):
            return None
    return None


def broad_failcohort_hit_score(decision: dict[str, Any]) -> float | None:
    evaluator = decision.get("evaluation_failcohort") if isinstance(decision.get("evaluation_failcohort"), dict) else {}
    for key in ("broad_hit_score", "hit_score"):
        if key in evaluator:
            try:
                return float(evaluator.get(key) or 0.0)
            except (TypeError, ValueError):
                return None
    diagnostics = decision.get("gate_diagnostics") if isinstance(decision.get("gate_diagnostics"), dict) else {}
    for key in ("diagnostic_failcohort_hit_score", "failcohort_hit_score"):
        if key in diagnostics:
            try:
                return float(diagnostics.get(key) or 0.0)
            except (TypeError, ValueError):
                return None
    return None


def has_broad_veto_hit(decision: dict[str, Any]) -> bool:
    score = broad_failcohort_hit_score(decision)
    return bool(score is not None and score >= FAILCOHORT_CONFLICT_THRESHOLD)


def has_strong_broad_veto_hit(decision: dict[str, Any]) -> bool:
    score = broad_failcohort_hit_score(decision)
    return bool(score is not None and score >= FAILCOHORT_STRONG_CONFLICT_THRESHOLD)


def broad_failcohort_top_match(decision: dict[str, Any]) -> dict[str, Any]:
    evaluator = decision.get("evaluation_failcohort") if isinstance(decision.get("evaluation_failcohort"), dict) else {}
    matches = _as_list(evaluator.get("matches"))
    best = next((item for item in matches if isinstance(item, dict)), None)
    return best or {}


def classify_safety(decision: dict[str, Any], evaluation: dict[str, Any] | None = None) -> SafetyLabel:
    gate = infer_gate_decision(decision, evaluation)
    if gate == "reject":
        return "no_recommendation"
    if has_veto_hit(decision, evaluation):
        return "unsafe_conflict"
    if gate == "require_review" or decision.get("needs_human_review") or decision.get("risk_level") == "high":
        return "risk_review"

    evidence = classify_evidence(decision)
    if evidence in {"strong_train_support", "weak_train_support"}:
        return "safe_supported"
    return "safe_unknown"


def classify_evidence(decision: dict[str, Any]) -> EvidenceLabel:
    supporting = decision.get("supporting_knowledge") if isinstance(decision.get("supporting_knowledge"), dict) else {}
    strategy_ids = _as_list(supporting.get("strategy_memory_ids"))
    playbook_ids = _as_list(supporting.get("playbook_memory_ids"))
    episode_pairs = _as_list(supporting.get("episode_pairs"))
    case_ids = _as_list(supporting.get("case_memory_ids"))
    veto_ids = _as_list(supporting.get("veto_memory_ids")) or _as_list(decision.get("veto_hits"))
    has_positive = bool(strategy_ids or playbook_ids)
    evaluator_conflict = has_veto_hit(decision)

    if (has_positive or case_ids) and (veto_ids or evaluator_conflict):
        return "blocked_by_counter_evidence"
    if has_positive:
        if decision.get("risk_level") in {"high", "medium"} or decision.get("needs_human_review"):
            return "weak_train_support"
        return "strong_train_support"
    if episode_pairs or case_ids:
        return "case_only_support"
    if veto_ids:
        return "blocked_by_counter_evidence"
    return "unsupported"


def _match_tier(evaluation: dict[str, Any] | None) -> str:
    if not evaluation:
        return "none"
    return str(evaluation.get("match_tier") or "none")


def _plan_score(evaluation: dict[str, Any] | None) -> float:
    if not evaluation:
        return 0.0
    plan = evaluation.get("plan_score") if isinstance(evaluation.get("plan_score"), dict) else {}
    try:
        return float(plan.get("score") or 0.0)
    except (TypeError, ValueError):
        return 0.0


def _action_equivalence_level(evaluation: dict[str, Any] | None) -> str:
    if not evaluation:
        return "unverifiable"
    equivalence = evaluation.get("action_equivalence")
    if isinstance(equivalence, dict) and equivalence.get("level"):
        return str(equivalence["level"])
    return "strongly_verifiable" if _match_tier(evaluation) in ACTION_MATCH_TIERS else "unverifiable"


def has_gold(evaluation: dict[str, Any] | None) -> bool:
    if not evaluation:
        return False
    if evaluation.get("gold_action"):
        return True
    return bool(_as_list(evaluation.get("gold_actions")))


def classify_outcome(
    decision: dict[str, Any],
    evaluation: dict[str, Any] | None = None,
) -> OutcomeClass:
    gate = infer_gate_decision(decision, evaluation)
    safety = classify_safety(decision, evaluation)
    evidence = classify_evidence(decision)
    tier = _match_tier(evaluation)
    plan_score = _plan_score(evaluation)
    equivalence_level = _action_equivalence_level(evaluation)

    if gate == "reject":
        return "rejected"
    if gate == "require_review":
        return "review_required"
    if safety == "unsafe_conflict":
        return "unsafe_accepted"
    if safety == "risk_review":
        return "review_required"
    if equivalence_level == "strongly_verifiable":
        return "strong_action_match"
    if tier == "scheme" or plan_score >= 0.6:
        return "supported_match"
    if evidence in EVIDENCE_SUPPORTED:
        return "safe_plausible_unknown"
    if not has_gold(evaluation):
        return "no_gold_available"
    return "unsupported_unknown"


def classify_replay(
    *,
    decision: dict[str, Any],
    evaluation: dict[str, Any] | None = None,
    trace_id: str | None = None,
    dataset_role: str | None = None,
    method_id: str | None = None,
) -> dict[str, Any]:
    """Classify one shadow replay according to the evaluation contract."""
    gate = infer_gate_decision(decision, evaluation)
    safety = classify_safety(decision, evaluation)
    evidence = classify_evidence(decision)
    outcome = classify_outcome(decision, evaluation)
    tier = _match_tier(evaluation)
    plan_score = _plan_score(evaluation)
    equivalence_level = _action_equivalence_level(evaluation)
    action_match = equivalence_level == "strongly_verifiable"
    plan_match = tier in PLAN_MATCH_TIERS or plan_score >= 0.6
    action_set = _action_set_evaluation(decision, evaluation)
    accepted = gate in ACCEPTED_GATES
    covered = gate in COVERED_GATES
    supported = evidence in EVIDENCE_SUPPORTED
    has_recommendation = bool(_recommended_action(decision, evaluation)) or bool(action_set.get("has_recommendation"))
    hit_score = failcohort_hit_score(decision)
    broad_hit_score = broad_failcohort_hit_score(decision)
    veto_hit = has_veto_hit(decision, evaluation)
    strong_veto_hit = has_strong_veto_hit(decision, evaluation)
    broad_veto_hit = has_broad_veto_hit(decision)
    strong_broad_veto_hit = has_strong_broad_veto_hit(decision)
    broad_match = broad_failcohort_top_match(decision)
    broad_aggregation = str(broad_match.get("evidence_aggregation") or "")
    fail_only_broad_hit = broad_veto_hit and broad_aggregation == "fail_ticket_issue_scheme"
    mixed_trace_broad_hit = broad_veto_hit and broad_aggregation == "trace_level_issue_scheme"
    fail_only_broad_strong_hit = strong_broad_veto_hit and broad_aggregation == "fail_ticket_issue_scheme"
    mixed_trace_broad_strong_hit = strong_broad_veto_hit and broad_aggregation == "trace_level_issue_scheme"
    recommended_action_count = int(action_set.get("recommended_count") or 0)
    gold_action_count = int(action_set.get("gold_count") or 0)
    action_counts = {
        "scheme_group_match_count": int(_nested_number(action_set, "scheme_group", "match_count")),
        "predicted_scheme_group_count": int(_nested_number(action_set, "scheme_group", "predicted_count")),
        "gold_scheme_group_count": int(_nested_number(action_set, "scheme_group", "gold_count")),
        "scheme_match_count": int(_nested_number(action_set, "scheme", "match_count")),
        "predicted_scheme_count": int(_nested_number(action_set, "scheme", "predicted_count")),
        "gold_scheme_count": int(_nested_number(action_set, "scheme", "gold_count")),
        "package_action_match_count": int(_nested_number(action_set, "action", "match_count")),
        "package_direction_match_count": int(_nested_number(action_set, "direction", "match_count")),
        "package_value_match_count": int(_nested_number(action_set, "value", "match_count")),
        "package_value_comparable_count": int(_nested_number(action_set, "value", "comparable_match_count")),
    }

    return {
        "trace_id": trace_id or decision.get("input_trace_id") or (evaluation or {}).get("input_trace_id"),
        "dataset_role": dataset_role,
        "method_id": method_id,
        "gate_decision": gate,
        "safety_label": safety,
        "evidence_label": evidence,
        "outcome_class": outcome,
        "has_gold": has_gold(evaluation),
        "match_tier": tier,
        "plan_score": plan_score,
        "action_equivalence_level": equivalence_level,
        "action_match": action_match,
        "plan_match": plan_match,
        "action_set_evaluation": action_set,
        "recommended_action_count": recommended_action_count,
        "gold_action_count": gold_action_count,
        "multi_recommended_action": recommended_action_count > 1,
        "multi_gold_action": gold_action_count > 1,
        "package_scheme_group_match": _nested_bool(action_set, "package_group_match"),
        "package_scheme_match": _nested_bool(action_set, "package_scheme_match"),
        "package_action_match": _nested_bool(action_set, "package_action_match"),
        "package_direction_match": _nested_bool(action_set, "package_direction_match"),
        "package_value_match": _nested_bool(action_set, "package_value_match"),
        "package_scheme_group_precision": _nested_number(action_set, "scheme_group", "precision"),
        "package_scheme_group_recall": _nested_number(action_set, "scheme_group", "recall"),
        "package_scheme_group_f1": _nested_number(action_set, "scheme_group", "f1"),
        "package_scheme_precision": _nested_number(action_set, "scheme", "precision"),
        "package_scheme_recall": _nested_number(action_set, "scheme", "recall"),
        "package_scheme_f1": _nested_number(action_set, "scheme", "f1"),
        "package_action_precision": _nested_number(action_set, "action", "precision"),
        "package_action_recall": _nested_number(action_set, "action", "recall"),
        "package_action_f1": _nested_number(action_set, "action", "f1"),
        "package_direction_precision": _nested_number(action_set, "direction", "precision"),
        "package_direction_recall": _nested_number(action_set, "direction", "recall"),
        "package_direction_f1": _nested_number(action_set, "direction", "f1"),
        "package_value_precision": _nested_number(action_set, "value", "precision"),
        "package_value_recall": _nested_number(action_set, "value", "recall"),
        "package_value_f1": _nested_number(action_set, "value", "f1"),
        "package_contradictory_count": int(action_set.get("contradictory_count") or 0),
        **action_counts,
        "accepted": accepted,
        "auto_eligible": accepted,
        "gate_passed": accepted,
        "covered": covered,
        "review_required": gate == "require_review",
        "rejected": gate == "reject",
        "unsafe": safety == "unsafe_conflict",
        "has_recommendation": has_recommendation,
        "candidate_unsafe": veto_hit,
        "candidate_broad_risk_overlap": broad_veto_hit,
        "candidate_fail_only_broad_overlap": fail_only_broad_hit,
        "candidate_mixed_trace_broad_overlap": mixed_trace_broad_hit,
        "unsafe_accepted": accepted and safety == "unsafe_conflict",
        "legacy_unsafe_auto_eligible": accepted and safety == "unsafe_conflict",
        "weak_overlap_auto_eligible": accepted and veto_hit and not strong_veto_hit,
        "strong_unsafe_auto_eligible": accepted and strong_veto_hit,
        "unsafe_auto_eligible": accepted and strong_veto_hit,
        "broad_overlap_auto_eligible": accepted and broad_veto_hit,
        "broad_strong_overlap_auto_eligible": accepted and strong_broad_veto_hit,
        "fail_only_broad_overlap_auto_eligible": accepted and fail_only_broad_hit,
        "fail_only_broad_strong_overlap_auto_eligible": accepted and fail_only_broad_strong_hit,
        "mixed_trace_broad_overlap_auto_eligible": accepted and mixed_trace_broad_hit,
        "mixed_trace_broad_strong_overlap_auto_eligible": accepted and mixed_trace_broad_strong_hit,
        "evidence_supported": supported,
        "plausible_unknown": outcome == "safe_plausible_unknown",
        "unsupported_unknown": outcome == "unsupported_unknown",
        "veto_hit": veto_hit,
        "broad_veto_hit": broad_veto_hit,
        "broad_failcohort_aggregation": broad_aggregation,
        "fail_only_broad_veto_hit": fail_only_broad_hit,
        "mixed_trace_broad_veto_hit": mixed_trace_broad_hit,
        "failcohort_hit_score": hit_score,
        "broad_failcohort_hit_score": broad_hit_score,
        "strong_failcohort_hit": strong_veto_hit,
        "strong_broad_failcohort_hit": strong_broad_veto_hit,
        "llm_failed": bool(decision.get("llm_error")),
        "llm_retried": int(decision.get("llm_attempt_count") or 1) > 1,
    }


def _rate(num: int | float, den: int | float) -> float:
    if not den:
        return 0.0
    return round(float(num) / float(den), 6)


def _metric_count(num: int | float, den: int | float) -> dict[str, int | float]:
    return {"numerator": num, "denominator": den, "value": _rate(num, den)}


def _micro_f1(precision_count: int | float, precision_den: int | float, recall_den: int | float) -> float:
    precision = float(precision_count) / float(precision_den) if precision_den else 0.0
    recall = float(precision_count) / float(recall_den) if recall_den else 0.0
    if not precision and not recall:
        return 0.0
    return round((2 * precision * recall) / (precision + recall), 6)


def aggregate_metrics(classified_replays: Iterable[dict[str, Any]]) -> dict[str, Any]:
    """Aggregate classified replay rows into experiment-level metrics."""
    rows = list(classified_replays)
    total = len(rows)
    gates = Counter(str(r.get("gate_decision") or "") for r in rows)
    outcomes = Counter(str(r.get("outcome_class") or "") for r in rows)
    safety = Counter(str(r.get("safety_label") or "") for r in rows)
    evidence = Counter(str(r.get("evidence_label") or "") for r in rows)

    accepted_rows = [r for r in rows if r.get("gate_decision") in ACCEPTED_GATES]
    accepted_gold_rows = [r for r in accepted_rows if r.get("has_gold")]
    review_gold_rows = [r for r in rows if r.get("gate_decision") == "require_review" and r.get("has_gold")]
    covered_rows = [r for r in rows if r.get("gate_decision") in COVERED_GATES]
    emitted_rows = [r for r in rows if r.get("has_recommendation")]
    non_reject_rows = [r for r in rows if r.get("gate_decision") != "reject"]
    veto_context_rows = [r for r in rows if r.get("veto_hit")]
    broad_veto_context_rows = [r for r in rows if r.get("broad_veto_hit")]
    gold_rows = [r for r in rows if r.get("has_gold")]
    accepted_package_gold_rows = [r for r in accepted_rows if r.get("has_gold")]

    safe_accepted = [
        r for r in accepted_rows
        if not r.get("unsafe") and r.get("safety_label") in {"safe_supported", "safe_unknown"}
    ]
    counter_evidence_avoided = [
        r for r in veto_context_rows
        if r.get("gate_decision") in {"downgrade", "require_review", "reject"}
    ]

    unsafe_emitted = sum(1 for r in emitted_rows if r.get("candidate_unsafe"))
    broad_risk_emitted = sum(1 for r in emitted_rows if r.get("candidate_broad_risk_overlap"))
    legacy_unsafe_accepted = sum(1 for r in accepted_rows if r.get("candidate_unsafe"))
    broad_overlap_accepted = sum(1 for r in accepted_rows if r.get("broad_veto_hit"))
    broad_strong_overlap_accepted = sum(1 for r in accepted_rows if r.get("strong_broad_failcohort_hit"))
    fail_only_broad_overlap_accepted = sum(1 for r in accepted_rows if r.get("fail_only_broad_overlap_auto_eligible"))
    fail_only_broad_strong_overlap_accepted = sum(
        1 for r in accepted_rows if r.get("fail_only_broad_strong_overlap_auto_eligible")
    )
    mixed_trace_broad_overlap_accepted = sum(1 for r in accepted_rows if r.get("mixed_trace_broad_overlap_auto_eligible"))
    mixed_trace_broad_strong_overlap_accepted = sum(
        1 for r in accepted_rows if r.get("mixed_trace_broad_strong_overlap_auto_eligible")
    )
    weak_overlap_accepted = sum(
        1 for r in accepted_rows
        if r.get("veto_hit") and not r.get("strong_failcohort_hit")
    )
    strong_unsafe_accepted = sum(1 for r in accepted_rows if r.get("strong_failcohort_hit"))
    accepted_plan_matches = sum(1 for r in accepted_gold_rows if r.get("plan_match"))
    accepted_action_matches = sum(
        1 for r in accepted_gold_rows
        if r.get("action_equivalence_level") in {"strongly_verifiable", "weakly_verifiable"}
    )
    verified_auto_resolved = accepted_action_matches
    review_plan_matches = sum(1 for r in review_gold_rows if r.get("plan_match"))
    review_action_matches = sum(
        1 for r in review_gold_rows
        if r.get("action_equivalence_level") in {"strongly_verifiable", "weakly_verifiable"}
    )
    evidence_supported = sum(1 for r in non_reject_rows if r.get("evidence_supported"))
    action_matches = sum(1 for r in gold_rows if r.get("action_match"))
    weak_or_strong_matches = sum(
        1 for r in gold_rows
        if r.get("action_equivalence_level") in {"strongly_verifiable", "weakly_verifiable"}
    )
    contradictions = sum(
        1 for r in gold_rows if r.get("action_equivalence_level") == "contradictory"
    )
    plan_matches = sum(1 for r in gold_rows if r.get("plan_match"))
    multi_gold = sum(1 for r in gold_rows if int(r.get("gold_action_count") or 0) > 1)
    package_group_matches = sum(1 for r in gold_rows if r.get("package_scheme_group_match"))
    package_scheme_matches = sum(1 for r in gold_rows if r.get("package_scheme_match"))
    package_action_matches = sum(1 for r in gold_rows if r.get("package_action_match"))
    package_direction_matches = sum(1 for r in gold_rows if r.get("package_direction_match"))
    package_value_matches = sum(1 for r in gold_rows if r.get("package_value_match"))
    accepted_package_direction_matches = sum(
        1 for r in accepted_package_gold_rows if r.get("package_direction_match")
    )
    package_counts = {
        "scheme_group": {
            "match": sum(int(r.get("scheme_group_match_count") or 0) for r in gold_rows),
            "predicted": sum(int(r.get("predicted_scheme_group_count") or 0) for r in gold_rows),
            "gold": sum(int(r.get("gold_scheme_group_count") or 0) for r in gold_rows),
        },
        "scheme": {
            "match": sum(int(r.get("scheme_match_count") or 0) for r in gold_rows),
            "predicted": sum(int(r.get("predicted_scheme_count") or 0) for r in gold_rows),
            "gold": sum(int(r.get("gold_scheme_count") or 0) for r in gold_rows),
        },
        "action": {
            "match": sum(int(r.get("package_action_match_count") or 0) for r in gold_rows),
            "predicted": sum(int(r.get("recommended_action_count") or 0) for r in gold_rows),
            "gold": sum(int(r.get("gold_action_count") or 0) for r in gold_rows),
        },
        "direction": {
            "match": sum(int(r.get("package_direction_match_count") or 0) for r in gold_rows),
            "predicted": sum(int(r.get("recommended_action_count") or 0) for r in gold_rows),
            "gold": sum(int(r.get("gold_action_count") or 0) for r in gold_rows),
        },
        "value": {
            "match": sum(int(r.get("package_value_match_count") or 0) for r in gold_rows),
            "predicted": sum(int(r.get("recommended_action_count") or 0) for r in gold_rows),
            "gold": sum(int(r.get("gold_action_count") or 0) for r in gold_rows),
            "comparable": sum(int(r.get("package_value_comparable_count") or 0) for r in gold_rows),
        },
    }
    plausible_unknown = sum(1 for r in rows if r.get("plausible_unknown"))
    unsupported_unknown = sum(1 for r in rows if r.get("unsupported_unknown"))
    llm_failures = sum(1 for r in rows if r.get("llm_failed"))
    llm_retries = sum(1 for r in rows if r.get("llm_retried"))
    metric_counts = {
        "unsafe_recommendation_rate": _metric_count(unsafe_emitted, len(emitted_rows)),
        "legacy_unsafe_auto_eligible_rate": _metric_count(legacy_unsafe_accepted, len(accepted_rows)),
