def _artifact_cache_key(artifacts: dict[str, Any], *list_fields: str) -> tuple[Any, ...]:
    parts: list[Any] = [id(artifacts)]
    for field in list_fields:
        value = artifacts.get(field)
        parts.append(id(value))
        parts.append(len(value) if isinstance(value, list) else None)
    return tuple(parts)
