def _values(value: Any) -> set[str]:
    if isinstance(value, list):
        return {str(item).strip().lower() for item in value if str(item or "").strip()}
    if str(value or "").strip():
        return {str(value).strip().lower()}
    return set()


def _case_score(memory: dict[str, Any], query: dict[str, Any]) -> float:
    app = memory.get("applicability") if isinstance(memory.get("applicability"), dict) else {}
    norm_app = memory.get("_retrieval_norm_app")
    if not isinstance(norm_app, dict):
        norm_app = {
            key: _values(app.get(key))
            for key in ("issue_types", "vendors", "systems", "regions", "bands")
        }
        memory["_retrieval_norm_app"] = norm_app
    fields = [
        ("issue_type", "issue_types", 8.0),
        ("vendor", "vendors", 4.0),
        ("system", "systems", 3.0),
        ("region", "regions", 2.0),
        ("band", "bands", 1.0),
    ]
    score = 0.0
    for query_key, app_key, weight in fields:
        query_value = str(query.get(query_key) or "").strip().lower()
        if query_value and query_value in norm_app.get(app_key, set()):
            score += weight
    return score


def _case_query(trace: dict[str, Any]) -> dict[str, Any]:
    query = trace_query(trace)
    ticket = trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}
    query["band"] = ticket.get("band")
    return query


def _text_parts(*values: Any) -> str:
    parts: list[str] = []
    for value in values:
        if isinstance(value, list):
            parts.extend(str(item) for item in value if str(item or "").strip())
        elif str(value or "").strip():
            parts.append(str(value))
    return " ".join(parts)


