        ticket.get("region"),
        ticket.get("vendor"),
        ticket.get("is_indoor"),
        ticket.get("band"),
        ticket.get("system"),
    )


def _case_pass_rate(memory: dict[str, Any]) -> float:
    metrics = memory.get("metrics") if isinstance(memory.get("metrics"), dict) else {}
    content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
    aggregate = content.get("aggregate") if isinstance(content.get("aggregate"), dict) else {}
    for value in (metrics.get("pass_rate"), aggregate.get("pass_rate")):
        if isinstance(value, (int, float)):
            return max(0.0, min(1.0, float(value)))
    passed = aggregate.get("long_eval_pass")
    failed = aggregate.get("long_eval_fail")
    if isinstance(passed, int) and isinstance(failed, int) and passed + failed > 0:
        return passed / (passed + failed)
    return 0.0


def _case_action_count(memory: dict[str, Any]) -> int:
    content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
    aggregate = content.get("aggregate") if isinstance(content.get("aggregate"), dict) else {}
    count = aggregate.get("action_count")
    if isinstance(count, (int, float)) and int(count) > 0:
        return int(count)
    actions = content.get("actions") if isinstance(content.get("actions"), list) else []
    return max(1, len(actions))


def _package_size_prior_cases(memories: list[dict[str, Any]]) -> list[tuple[dict[str, Any], int]]:
    cache_key = id(memories)
    if cache_key in _PACKAGE_SIZE_PRIOR_CACHE:
        return _PACKAGE_SIZE_PRIOR_CACHE[cache_key]
    rows = [
        (memory, _case_action_count(memory))
        for memory in memories
        if memory.get("memory_type") == "case_memory"
    ]
    _PACKAGE_SIZE_PRIOR_CACHE[cache_key] = rows
    return rows


def _train_package_size_prior(trace: dict[str, Any], memories: list[dict[str, Any]] | None) -> dict[str, Any]:
    if not memories:
        return {"available": False, "reason": "no_train_case_memories"}
    query = trace_query(trace)
    scored: list[tuple[float, int]] = []
    for memory, count in _package_size_prior_cases(memories):
        score = _case_score(memory, query)
        if score > 0:
            scored.append((score, count))
    if not scored:
        return {"available": False, "reason": "no_matching_train_case_memories"}
    scored.sort(reverse=True)
    max_score = scored[0][0]
    matched = [count for score, count in scored if score >= max(1.0, max_score * 0.75)][:80]
    if len(matched) < 8:
        return {
            "available": False,
            "reason": "insufficient_matching_train_cases",
            "matched_case_count": len(matched),
            "max_match_score": round(max_score, 6),
        }
    multi_count = sum(1 for count in matched if count >= 2)
    multi_rate = multi_count / len(matched)
    mean_size = sum(matched) / len(matched)
    return {
        "available": True,
        "matched_case_count": len(matched),
        "multi_action_rate": round(multi_rate, 6),
        "mean_action_count": round(mean_size, 6),
        "p50_action_count": sorted(matched)[len(matched) // 2],
        "suggested_multi_action": multi_rate >= 0.55 or mean_size >= 1.75,
        "max_match_score": round(max_score, 6),
    }


def _case_echo_rank_score(memory: dict[str, Any], trace: dict[str, Any]) -> dict[str, Any]:
    query = trace_query(trace)
    context_score = _case_score(memory, query)
    context_term = min(1.0, context_score / 18.0)
    outcome_term = _case_pass_rate(memory)
    total = 0.70 * context_term + 0.30 * outcome_term
    return {
        "context_similarity": round(context_term, 6),
        "outcome_pass_rate": round(outcome_term, 6),
        "total": round(total, 6),
        "policy": "case_echo_rank_v1",
    }


def _bounded(value: float) -> float:
    return max(0.0, min(1.0, value))


def _support_term(support: int) -> float:
    if support <= 0:
        return 0.0
    # Saturate around 100 supporting rows so large-volume strategies do not
    # swamp context similarity by sheer frequency.
    return _bounded(support / 100.0)


def _lcb(pass_rate: float, support: int) -> float:
    if support <= 0:
        return 0.0
    variance = pass_rate * (1.0 - pass_rate) / support
    return _bounded(pass_rate - 1.96 * (variance ** 0.5))


def _wilson_lcb(passed: int, evaluated: int, *, z: float = 1.96) -> float:
    if evaluated <= 0:
        return 0.0
    phat = passed / evaluated
    denom = 1.0 + (z * z / evaluated)
    center = phat + (z * z / (2 * evaluated))
    margin = z * ((phat * (1.0 - phat) / evaluated) + (z * z / (4 * evaluated * evaluated))) ** 0.5
    return _bounded((center - margin) / denom)


def _list_contains(values: Any, needle: Any) -> bool:
    norm = str(needle or "").strip().lower()
    if not norm:
        return False
    if isinstance(values, list):
        return norm in {str(item or "").strip().lower() for item in values}
    return norm == str(values or "").strip().lower()


def _memory_boundary_score(memory: dict[str, Any], trace: dict[str, Any]) -> float:
    app = memory.get("applicability") if isinstance(memory.get("applicability"), dict) else {}
    query = trace_query(trace)
    ticket = trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}
    checks = [
        ("issue_types", query.get("issue_type")),
        ("vendors", query.get("vendor")),
        ("systems", query.get("system")),
        ("regions", query.get("region")),
        ("bands", ticket.get("band")),
    ]
    present = [(key, value) for key, value in checks if value]
    if not present:
        return 0.0
    return sum(1 for key, value in present if _list_contains(app.get(key), value)) / len(present)


def _memory_action_shape_score(memory: dict[str, Any], action: dict[str, Any]) -> float:
    content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
    score = 0.0
    total = 0
    for key in ("scheme_id", "param_cn_name"):
        total += 1
        if str(content.get(key) or "").strip().lower() == str(action.get(key) or "").strip().lower():
            score += 1.0
    value_pattern = content.get("value_pattern") if isinstance(content.get("value_pattern"), dict) else {}
    total += 1
    if str(value_pattern.get("direction") or "").strip().lower() == str(action.get("direction") or "").strip().lower():
        score += 1.0
    if content.get("parameter_semantic_id") and action.get("parameter_semantic_id"):
        total += 1
        if str(content.get("parameter_semantic_id")) == str(action.get("parameter_semantic_id")):
            score += 1.0
    return score / total if total else 0.0


def _state_term(memory: dict[str, Any]) -> float:
    state = str(memory.get("state") or "").strip()
    return {
        "reusable": 1.0,
        "validated": 0.85,
        "restricted": 0.45,
        "unverified": 0.25,
        "counter_evidence": 0.0,
    }.get(state, 0.25)


_STRUCTURAL_STRATEGY_SELECTION_VARIANTS = {
    "no_outcome_counts",
    "no_outcome_counts_plus_shape",
    "no_outcome_counts_bundle_participation_prior",
    "no_outcome_counts_no_component_relations",
    "no_outcome_counts_no_source_support",
    "no_outcome_counts_structural_identity_only",
}

_STRUCTURAL_SELECTION_POLICY_BY_VARIANT = {
    "no_outcome_counts_no_component_relations": "structural_no_component_relations_v1",
    "no_outcome_counts_no_source_support": "structural_no_source_support_v1",
    "no_outcome_counts_structural_identity_only": "structural_identity_v1",
}

_STRUCTURAL_READ_POLICY = {
    "structural_relation_v1": {
        "include_component_relations": True,
        "include_source_support": True,
    },
    "structural_no_component_relations_v1": {
        "include_component_relations": False,
        "include_source_support": True,
    },
    "structural_no_source_support_v1": {
        "include_component_relations": True,
        "include_source_support": False,
    },
    "structural_identity_v1": {
        "include_component_relations": False,
        "include_source_support": False,
    },
}

_STRUCTURAL_ACTION_ADMISSION_POLICY = "realized_action_scope_v1"
_STRUCTURAL_ACTION_SCOPES = {
    "action_direct",
    "component_associated",
}


def _structural_candidate_action_admissible(action: dict[str, Any]) -> bool:
    """Return whether a Case action may enter the outcome-free candidate plane.

    Case Memory preserves the complete historical plan, including actions that
    were not realized.  Structural retrieval may reuse only actions that were
    actually executed and whose maximum action attribution scope is explicit.
    This check uses execution/attribution metadata, never historical outcomes.
    """
    return (
        str(action.get("exec_state") or "") == "exec_success"
        and str(action.get("maximum_attribution_scope") or "")
        in _STRUCTURAL_ACTION_SCOPES
    )


def _structural_strategy_match(
    memory: dict[str, Any],
    action: dict[str, Any],
    trace: dict[str, Any],
    *,
    include_component_relations: bool = True,
    include_source_support: bool = True,
) -> dict[str, Any]:
    """Describe outcome-free action/Memory compatibility for structural retrieval."""
    content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
    value_pattern = content.get("value_pattern") if isinstance(content.get("value_pattern"), dict) else {}
    relations = (
        content.get("component_of_relations")
        if isinstance(content.get("component_of_relations"), dict)
        else {}
    )

    def same(left: Any, right: Any) -> bool:
        left_key = str(left or "").strip().lower().replace("→", "->")
        right_key = str(right or "").strip().lower().replace("→", "->")
        return bool(left_key) and left_key == right_key

    canonical_ids = {
        str(item or "").strip().lower()
        for item in content.get("canonical_action_ids") or []
        if item
    }
    action_canonical = str(action.get("canonical_action_id") or "").strip().lower()
    observed_changes = {
        str(item.get("change") or "").strip().lower().replace("→", "->")
        for item in content.get("observed_changes") or []
        if isinstance(item, dict) and item.get("change")
    }
    action_change = str(action.get("change") or "").strip().lower().replace("→", "->")
    delta_buckets = {
        str(item.get("delta_bucket") or "").strip().lower()
        for item in value_pattern.get("delta_distribution") or []
        if isinstance(item, dict) and item.get("delta_bucket")
    }
    if value_pattern.get("delta_bucket"):
        delta_buckets.add(str(value_pattern.get("delta_bucket")).strip().lower())
    action_delta = str(action.get("delta_bucket") or "").strip().lower()

    scheme_exact = same(content.get("scheme_id"), action.get("scheme_id"))
    semantic_parameter_exact = same(
        content.get("parameter_semantic_id"),
        action.get("parameter_semantic_id"),
    )
    parameter_name_exact = same(
        content.get("param_cn_name"),
        action.get("param_cn_name"),
    ) or same(content.get("param_en_name"), action.get("param_en_name"))
    canonical_action_exact = bool(action_canonical and action_canonical in canonical_ids)
    direction_exact = same(value_pattern.get("direction"), action.get("direction"))
    exact_change = bool(action_change and action_change in observed_changes)
    delta_bucket_exact = bool(action_delta and action_delta in delta_buckets)
    bundle_trace_ids = (
        relations.get("realized_bundle_trace_ids") or []
        if include_component_relations
        else []
    )
    playbook_ids = (
        relations.get("playbook_memory_ids") or []
        if include_component_relations
        else []
    )
    boundary_match = _memory_boundary_score(memory, trace)
    action_shape_match = _memory_action_shape_score(memory, action)

    # Lexicographic structural specificity, not a dev-fitted weighted score.
    # The vector intentionally contains no outcome count, pass rate, LCB, or
    # Lifecycle state.
    relation_available = bool(bundle_trace_ids or playbook_ids)
    relation_support_term = (
        _support_term(len(memory.get("trace_ids") or []))
        if include_source_support
        else 0.0
    )
    selection_key = (
        int(canonical_action_exact),
        int(scheme_exact),
        int(semantic_parameter_exact),
        int(parameter_name_exact),
        int(exact_change),
        int(delta_bucket_exact),
        int(direction_exact),
        boundary_match,
        action_shape_match,
        int(relation_available),
        relation_support_term,
    )
    return {
        "canonical_action_exact": canonical_action_exact,
        "scheme_exact": scheme_exact,
        "semantic_parameter_exact": semantic_parameter_exact,
        "parameter_name_exact": parameter_name_exact,
        "exact_change": exact_change,
        "delta_bucket_exact": delta_bucket_exact,
        "direction_exact": direction_exact,
        "boundary_match": boundary_match,
        "action_shape_match": action_shape_match,
        "component_of_relation_available": relation_available,
        "component_of_bundle_count": len(bundle_trace_ids),
        "component_of_playbook_count": len(playbook_ids),
        "source_trace_count": (
            len(memory.get("trace_ids") or [])
            if include_source_support
            else 0
        ),
        "selection_key": selection_key,
    }


def _candidate_strategy_evidence(
    action: dict[str, Any],
    trace: dict[str, Any],
    memories: list[dict[str, Any]],
    *,
    selection_policy: str = "outcome_calibrated_v1",
) -> list[dict[str, Any]]:
    evidence: list[dict[str, Any]] = []
    structural_selection = selection_policy in _STRUCTURAL_READ_POLICY
    structural_read_policy = _STRUCTURAL_READ_POLICY.get(selection_policy, {})
    index = _strategy_evidence_index(memories)
    candidates: list[dict[str, Any]] = []
    seen: set[str] = set()
    for index_key, action_key in (("scheme_ids", "scheme_id"), ("scheme_groups", "scheme_group")):
        value = str(action.get(action_key) or "").strip().lower()
        if not value:
            continue
        for memory in index.get(index_key, {}).get(value, []):
            memory_id = str(memory.get("memory_id") or id(memory))
            if memory_id in seen:
                continue
            seen.add(memory_id)
            candidates.append(memory)
    for memory in candidates:
        memory_type = memory.get("memory_type")
        shape = _memory_action_shape_score(memory, action)
        boundary = _memory_boundary_score(memory, trace)
        if shape <= 0.0 and boundary <= 0.0:
            continue
        content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
        if structural_selection:
            # The structural plane does not read result aggregates. Source
            # cardinality and component-of relations are exposed separately
            # by _structural_strategy_match.
            support = 0
            pass_rate = 0.0
            bundle_prior = None
        else:
            metrics = (
                memory.get("metrics")
                if isinstance(memory.get("metrics"), dict)
                else {}
            )
            support = int(metrics.get("support_count") or 0)
            pass_rate = float(metrics.get("pass_rate") or 0.0)
            bundle_prior = (
                content.get("bundle_participation_prior")
                if isinstance(content.get("bundle_participation_prior"), dict)
                else None
            )
        if not structural_selection and memory_type == "playbook_memory":
            matched_component_priors = []
            for component in content.get("components") or []:
                if not isinstance(component, dict):
                    continue
                component_shape = 0
                for key in ("scheme_id", "parameter_semantic_id", "direction"):
                    expected = str(action.get(key) or "").strip().lower()
                    observed = str(component.get(key) or "").strip().lower()
                    component_shape += int(bool(expected) and expected == observed)
                prior = component.get("bundle_participation_prior")
                if component_shape >= 2 and isinstance(prior, dict):
                    matched_component_priors.append((component_shape, prior))
            if matched_component_priors:
                matched_component_priors.sort(
                    key=lambda row: (row[0], int(row[1].get("support_count") or 0)),
                    reverse=True,
                )
                bundle_prior = matched_component_priors[0][1]
        prior_support = int((bundle_prior or {}).get("support_count") or 0)
        prior_rate = float((bundle_prior or {}).get("bundle_pass_participation_rate") or 0.0)
        structural_match = _structural_strategy_match(
            memory,
            action,
            trace,
            include_component_relations=bool(
                structural_read_policy.get("include_component_relations", True)
            ),
            include_source_support=bool(
                structural_read_policy.get("include_source_support", True)
            ),
        )
        item = {
            "memory_id": memory.get("memory_id"),
            "memory_type": memory_type,
            "state": memory.get("state"),
            "support_count": support,
            "pass_rate": _bounded(pass_rate),
            "lcb": _lcb(_bounded(pass_rate), support),
            "support_term": _support_term(support),
            "boundary_match": boundary,
            "action_shape_match": shape,
            "state_term": _state_term(memory),
            "bundle_participation_prior_available": bool(bundle_prior),
            "bundle_participation_support": prior_support,
            "bundle_participation_pass_rate": _bounded(prior_rate),
            "bundle_participation_contract": (bundle_prior or {}).get("routing_eligibility"),
            "structural_match": {
                key: value
                for key, value in structural_match.items()
                if key != "selection_key"
            },
            "selection_policy": selection_policy,
        }
        item["evidence_score"] = (
            0.35 * item["lcb"]
            + 0.20 * item["pass_rate"]
            + 0.15 * item["support_term"]
            + 0.15 * item["boundary_match"]
            + 0.10 * item["action_shape_match"]
            + 0.05 * item["state_term"]
        )
        if structural_selection:
            content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
            item.update({
                "state": None,
                "pass_rate": 0.0,
                "lcb": 0.0,
                "state_term": 0.0,
                "maximum_attribution_scope": content.get("maximum_attribution_scope"),
                "action_memory_role": content.get("action_memory_role"),
                "evidence_score": None,
                "_structural_selection_key": structural_match["selection_key"],
            })
        evidence.append(item)
    if structural_selection:
        evidence.sort(
            key=lambda item: (
                tuple(-float(value) for value in item["_structural_selection_key"]),
                str(item.get("memory_id") or ""),
            )
        )
        for item in evidence:
            item.pop("_structural_selection_key", None)
    else:
        evidence.sort(
            key=lambda item: (
                item["evidence_score"],
                item["support_count"],
                item["memory_id"] or "",
            ),
            reverse=True,
        )
    return evidence[:5]


def _strategy_evidence_index(memories: list[dict[str, Any]]) -> dict[str, dict[str, list[dict[str, Any]]]]:
    cache_key = id(memories)
    cached = _STRATEGY_EVIDENCE_INDEX_CACHE.get(cache_key)
    if cached is not None:
        return cached
    index: dict[str, dict[str, list[dict[str, Any]]]] = {
        "scheme_ids": defaultdict(list),
        "scheme_groups": defaultdict(list),
    }
    for memory in memories:
        if memory.get("memory_type") not in {"strategy_memory", "playbook_memory"}:
            continue
        app = memory.get("applicability") if isinstance(memory.get("applicability"), dict) else {}
        for key in ("scheme_ids", "scheme_groups"):
            for value in _values(app.get(key)):
                index[key][value].append(memory)
    _STRATEGY_EVIDENCE_INDEX_CACHE.clear()
    _STRATEGY_EVIDENCE_INDEX_CACHE[cache_key] = index
    return index


def _profile_consumption_enabled(policy: str | None) -> bool:
    return str(policy or "").strip().lower() not in {"", "off", "none", "disabled"}


def _profile_consumes_conflict(policy: str | None) -> bool:
    policy_key = str(policy or "").strip().lower()
    return _profile_consumption_enabled(policy_key) and "no_conflict" not in policy_key


def _profile_uses_arbitration(policy: str | None) -> bool:
    key = str(policy or "").strip().lower()
    return "arbitrated" in key or key.startswith("table4_")


def _table4_support_rescue_only(policy: str | None) -> bool:
    return _policy_key(policy) == "table4_support_rescue_only_v1"


def _table4_support_conflict_sparse(policy: str | None) -> bool:
    return _policy_key(policy) == "table4_support_rescue_conflict_sparse_v1"


def _table4_cumulative_stage(policy: str | None) -> str:
    key = _policy_key(policy)
    prefix = "table4_cumulative_"
    return key[len(prefix):-len("_v1")] if key.startswith(prefix) and key.endswith("_v1") else ""


def _policy_key(policy: str | None) -> str:
    return str(policy or "").strip().lower()


def _gate_reviews_high_no_action_specificity(policy: str | None) -> bool:
    return "high_no_action_specificity_review" in _policy_key(policy)


def _profile_reviews_action_specific_counter_only(policy: str | None) -> bool:
    key = _policy_key(policy)
    return "counter_action_specific_review" in key or "counter_specific_review" in key


def _profile_review_only_policy(policy: str | None) -> bool:
    return _gate_reviews_high_no_action_specificity(policy) or _profile_reviews_action_specific_counter_only(policy)


def _arbitration_counter_lcb_max(policy: str | None) -> float:
    policy_key = str(policy or "").strip().lower()
    if "lcb030" in policy_key or "prior030" in policy_key:
        return 0.30
    return 0.25


def _profile_values(value: Any) -> set[str]:
    if isinstance(value, list):
        return {str(item or "").strip().lower() for item in value if str(item or "").strip()}
    if str(value or "").strip():
        return {str(value).strip().lower()}
    return set()


def _profile_value_match(expected: Any, observed: Any) -> bool:
    expected_values = _profile_values(expected)
    observed_values = _profile_values(observed)
    if not expected_values or not observed_values:
        return True
    return bool(expected_values & observed_values)


def _profile_token(value: Any) -> str:
    return str(value or "").strip().lower()


def _trace_issue_token(trace: dict[str, Any]) -> str:
    query = trace_query(trace)
    return _profile_token(query.get("issue_type"))


def _trace_vendor_token(trace: dict[str, Any]) -> str:
    query = trace_query(trace)
    return _profile_token(query.get("vendor"))


def _trace_system_token(trace: dict[str, Any]) -> str:
    query = trace_query(trace)
    return _profile_token(query.get("system"))


def _trace_region_token(trace: dict[str, Any]) -> str:
    query = trace_query(trace)
    return _profile_token(query.get("region"))


def _trace_band_token(trace: dict[str, Any]) -> str:
