def _action_param_tokens(action: dict[str, Any]) -> set[str]:
    return {
        token
        for token in (
            _profile_token(action.get("parameter_semantic_id") or action.get("parameter_semantic_key")),
            _profile_token(action.get("param_cn_name")),
        )
        if token
    }


def _action_value_tokens(action: dict[str, Any]) -> set[str]:
    return {
        token
        for token in (
            _profile_token(action.get("delta_bucket")),
            _profile_token(action.get("suggested_delta")),
            _profile_token(action.get("normalized_shape_id")),
            _profile_token(action.get("value_shape")),
            _profile_token(action.get("value_pattern_id")),
            _profile_token(action.get("change")),
        )
        if token
    }


def _action_canonical_tokens(action: dict[str, Any]) -> set[str]:
    ontology = action.get("action_ontology") if isinstance(action.get("action_ontology"), dict) else {}
    return {
        token
        for token in (
            _profile_token(action.get("canonical_action_id")),
            _profile_token(ontology.get("canonical_action_id")),
        )
        if token
    }


def _support_routing_profile_index(artifacts: dict[str, Any]) -> dict[tuple[str, ...], list[dict[str, Any]]]:
    cache_key = _artifact_cache_key(artifacts, "support_routing_profiles")
    cached = _SUPPORT_ROUTING_PROFILE_INDEX_CACHE.get(cache_key)
    if cached is not None:
        return cached
    index: dict[tuple[str, ...], list[dict[str, Any]]] = defaultdict(list)
    allowed_profile_sets = {
        "hard_zero_fail_specific_v1",
        "recovery_zero_fail_specific_v1",
        "value_shape_balanced_v1",
    }
    for profile in artifacts.get("support_routing_profiles") or []:
        if not isinstance(profile, dict):
            continue
        if _profile_token(profile.get("profile_set_id")) not in allowed_profile_sets:
            continue
        key_family = _profile_token(profile.get("key_family"))
        key_values = profile.get("key_values")
        if not key_family or not isinstance(key_values, list):
            continue
        key = (key_family, *[_profile_token(value) for value in key_values])
        if any(not value for value in key):
            continue
        index[key].append(profile)
    for profiles in index.values():
        profiles.sort(
            key=lambda item: (
                float(item.get("pass_lcb") or 0.0),
                int(item.get("support_count") or 0),
                str(item.get("profile_id") or ""),
            ),
            reverse=True,
        )
    _SUPPORT_ROUTING_PROFILE_INDEX_CACHE.clear()
    _SUPPORT_ROUTING_PROFILE_INDEX_CACHE[cache_key] = index
    return index


def _support_routing_candidate_keys(action: dict[str, Any], trace: dict[str, Any]) -> set[tuple[str, ...]]:
    issue = _trace_issue_token(trace)
    vendor = _trace_vendor_token(trace)
    system = _trace_system_token(trace)
    region = _trace_region_token(trace)
    band = _trace_band_token(trace)
    indoor = _trace_indoor_token(trace)
    scheme = _profile_token(action.get("scheme_id"))
    group = _profile_token(action.get("scheme_group"))
    direction = _profile_token(action.get("direction"))
    values = _action_value_tokens(action)
    params = _action_param_tokens(action)
    keys: set[tuple[str, ...]] = set()
    for param in params:
        if scheme and direction:
            keys.add(("scheme_param_direction", scheme, param, direction))
        if group and direction:
            keys.add(("group_param_direction", group, param, direction))
        if issue and scheme and direction:
            keys.add(("issue_scheme_param_direction", issue, scheme, param, direction))
        if issue and vendor and system and scheme and direction:
            keys.add(("env_issue_scheme_param_direction", issue, vendor, system, scheme, param, direction))
        if region and band and indoor and scheme and direction:
            keys.add(("boundary_region_scheme_param_direction", region, band, indoor, scheme, param, direction))
        for value in values:
            if issue and scheme and direction:
                keys.add(("issue_scheme_param_direction_value", issue, scheme, param, direction, value))
            if issue and vendor and system and scheme and direction:
                keys.add(("env_issue_scheme_param_direction_value", issue, vendor, system, scheme, param, direction, value))
            if region and band and indoor and scheme and direction:
                keys.add(("boundary_region_scheme_param_direction_value", region, band, indoor, scheme, param, direction, value))
            if scheme and direction:
                keys.add(("scheme_param_direction_value", scheme, param, direction, value))
            if group and direction:
                keys.add(("group_param_direction_value", group, param, direction, value))
    for canonical in _action_canonical_tokens(action):
        keys.add(("canonical_action", canonical))
        for value in values:
            keys.add(("canonical_action_value", canonical, value))
    return keys


def _support_routing_profile_hits(
    action: dict[str, Any],
    trace: dict[str, Any],
    artifacts: dict[str, Any],
) -> list[dict[str, Any]]:
    index = _support_routing_profile_index(artifacts)
    hits: list[dict[str, Any]] = []
    seen: set[str] = set()
    for key in _support_routing_candidate_keys(action, trace):
        for profile in index.get(key, []):
            profile_id = str(profile.get("profile_id") or key)
            if profile_id in seen:
                continue
            seen.add(profile_id)
            hits.append({
                "profile_id": profile.get("profile_id"),
                "profile_set_id": profile.get("profile_set_id"),
                "profile_type": "support_routing_profile",
                "key_family": profile.get("key_family"),
                "key_values": profile.get("key_values") or [],
                "support_count": int(profile.get("support_count") or 0),
                "pass_lcb": round(float(profile.get("pass_lcb") or 0.0), 6),
                "fail_rate": round(float(profile.get("fail_rate") or 0.0), 6),
                "matched_from": "support_routing_profiles",
            })
    hits.sort(
        key=lambda item: (
            float(item.get("pass_lcb") or 0.0),
            int(item.get("support_count") or 0),
            str(item.get("profile_id") or ""),
        ),
        reverse=True,
    )
    return hits[:12]


def _counter_memory_broad_failure_lcb(memory: dict[str, Any]) -> float:
    content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
    prior = content.get("broad_context_outcome_prior") if isinstance(content.get("broad_context_outcome_prior"), dict) else {}
    try:
        return round(float(prior.get("failure_lcb") or 0.0), 6)
    except (TypeError, ValueError):
        return 0.0


def _counter_action_prior_failure_lcb(entry: dict[str, Any]) -> float:
    prior = entry.get("prior") if isinstance(entry.get("prior"), dict) else {}
    try:
        return round(float(prior.get("failure_lcb") or 0.0), 6)
    except (TypeError, ValueError):
        return _counter_memory_broad_failure_lcb(entry.get("memory") or {})


def _counter_routing_prior_index(artifacts: dict[str, Any]) -> dict[str, dict[tuple[str, ...], list[dict[str, Any]]]]:
    cache_key = _artifact_cache_key(artifacts, "memories")
    cached = _COUNTER_ROUTING_PRIOR_INDEX_CACHE.get(cache_key)
    if cached is not None:
        return cached
    index: dict[str, dict[tuple[str, ...], list[dict[str, Any]]]] = defaultdict(lambda: defaultdict(list))

    seen_index_entries: set[tuple[str, str, tuple[str, ...], str]] = set()

    def add_prior(
        *,
        memory: dict[str, Any],
        action_profile: dict[str, Any],
        prior: dict[str, Any],
        fallback_family: str,
        fallback_key_values: list[Any],
    ) -> None:
        prior_key_values = prior.get("key_values") if isinstance(prior.get("key_values"), list) else None
        family = (_profile_token(prior.get("aggregation")) if prior_key_values else "") or fallback_family
        key_values_raw = prior_key_values or fallback_key_values
        key_values = tuple(_profile_token(value) for value in key_values_raw)
        if not family or not key_values or any(not value for value in key_values):
            return
        entry_key = (
            str(memory.get("memory_id") or id(memory)),
            family,
            key_values,
            str(prior.get("aggregation") or fallback_family),
        )
        if entry_key in seen_index_entries:
            return
        seen_index_entries.add(entry_key)
        index[family][key_values].append({
            "memory": memory,
            "action_profile": action_profile,
            "prior": prior,
            "prior_scope": family,
            "key_values": list(key_values),
        })

    memories = artifacts.get("memories") if isinstance(artifacts.get("memories"), list) else []
    for memory in memories:
        if memory.get("memory_type") != "counter_evidence_memory":
            continue
        content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
        issue = _profile_token(content.get("issue_type"))
        broad_prior = content.get("broad_context_outcome_prior") if isinstance(content.get("broad_context_outcome_prior"), dict) else {}
        for action_profile in content.get("action_profiles") or []:
            if not isinstance(action_profile, dict):
                continue
            scheme = _profile_token(action_profile.get("scheme_id"))
            direction = _profile_token(action_profile.get("direction"))
            if not issue or not scheme or not direction:
                continue
            direction_prior = (
                action_profile.get("direction_outcome_prior")
                if isinstance(action_profile.get("direction_outcome_prior"), dict)
                else {}
            ) or broad_prior
            value_prior = (
                action_profile.get("value_shape_outcome_prior")
                if isinstance(action_profile.get("value_shape_outcome_prior"), dict)
                else {}
            ) or direction_prior
            env_direction_prior = (
                action_profile.get("env_direction_outcome_prior")
                if isinstance(action_profile.get("env_direction_outcome_prior"), dict)
                else {}
            )
            env_value_prior = (
                action_profile.get("env_value_shape_outcome_prior")
                if isinstance(action_profile.get("env_value_shape_outcome_prior"), dict)
                else {}
            )
            boundary_direction_prior = (
                action_profile.get("boundary_direction_outcome_prior")
                if isinstance(action_profile.get("boundary_direction_outcome_prior"), dict)
                else {}
            )
            boundary_value_prior = (
                action_profile.get("boundary_value_shape_outcome_prior")
                if isinstance(action_profile.get("boundary_value_shape_outcome_prior"), dict)
                else {}
            )
            context_direction_prior = (
                action_profile.get("context_direction_outcome_prior")
                if isinstance(action_profile.get("context_direction_outcome_prior"), dict)
                else {}
            )
            context_value_prior = (
                action_profile.get("context_value_shape_outcome_prior")
                if isinstance(action_profile.get("context_value_shape_outcome_prior"), dict)
                else {}
            )
            for param in _action_param_tokens(action_profile):
                add_prior(
                    memory=memory,
                    action_profile=action_profile,
                    prior=direction_prior,
                    fallback_family="issue_scheme_param_direction",
                    fallback_key_values=[issue, scheme, param, direction],
                )
                for value in _action_value_tokens(action_profile):
                    add_prior(
                        memory=memory,
                        action_profile=action_profile,
                        prior=value_prior,
                        fallback_family="issue_scheme_param_direction_value",
                        fallback_key_values=[issue, scheme, param, direction, value],
                    )
                for prior, fallback_family in (
                    (env_direction_prior, "env_issue_scheme_param_direction"),
                    (boundary_direction_prior, "boundary_region_scheme_param_direction"),
                    (context_direction_prior, "context_issue_scheme_param_direction"),
                ):
                    if prior:
                        add_prior(
                            memory=memory,
                            action_profile=action_profile,
                            prior=prior,
                            fallback_family=fallback_family,
                            fallback_key_values=[],
                        )
                for value in _action_value_tokens(action_profile):
                    for prior, fallback_family in (
                        (env_value_prior, "env_issue_scheme_param_direction_value"),
                        (boundary_value_prior, "boundary_region_scheme_param_direction_value"),
                        (context_value_prior, "context_issue_scheme_param_direction_value"),
                    ):
                        if prior:
                            add_prior(
                                memory=memory,
                                action_profile=action_profile,
                                prior=prior,
                                fallback_family=fallback_family,
                                fallback_key_values=[],
                            )
    for family_index in index.values():
        for matches in family_index.values():
            matches.sort(
                key=lambda item: (
                    _counter_action_prior_failure_lcb(item),
                    int((((item.get("memory") or {}).get("metrics") or {}).get("long_eval_fail_count") or 0)),
                    str((item.get("memory") or {}).get("memory_id") or ""),
                ),
                reverse=True,
            )
    _COUNTER_ROUTING_PRIOR_INDEX_CACHE.clear()
    _COUNTER_ROUTING_PRIOR_INDEX_CACHE[cache_key] = index
    return index


def _counter_routing_candidate_layers(action: dict[str, Any], trace: dict[str, Any]) -> list[dict[str, Any]]:
    issue = _trace_issue_token(trace)
    vendor = _trace_vendor_token(trace)
    system = _trace_system_token(trace)
    region = _trace_region_token(trace)
    band = _trace_band_token(trace)
    indoor = _trace_indoor_token(trace)
    scheme = _profile_token(action.get("scheme_id"))
    direction = _profile_token(action.get("direction"))
    values = _action_value_tokens(action)
    params = _action_param_tokens(action)
    layer_specs = [
        (
            "L1",
            "issue_scheme_param_direction",
            "issue+scheme+param+direction",
            60,
            10,
        ),
        (
            "L2",
            "issue_scheme_param_direction_value",
            "issue+scheme+param+direction+value",
            30,
            20,
        ),
        (
            "L3",
            "env_issue_scheme_param_direction",
            "issue+vendor+system+scheme+param+direction",
            50,
            30,
        ),
        (
            "L3",
            "env_issue_scheme_param_direction_value",
            "issue+vendor+system+scheme+param+direction+value",
            20,
            40,
        ),
        (
            "L3",
            "boundary_region_scheme_param_direction",
            "region+band+indoor+scheme+param+direction",
            55,
            50,
        ),
        (
            "L3",
            "boundary_region_scheme_param_direction_value",
            "region+band+indoor+scheme+param+direction+value",
            25,
            60,
        ),
        (
            "L3",
            "context_issue_scheme_param_direction",
            "issue+vendor+system+region+band+indoor+scheme+param+direction",
            40,
            70,
        ),
        (
            "L3",
            "context_issue_scheme_param_direction_value",
            "issue+vendor+system+region+band+indoor+scheme+param+direction+value",
            10,
            80,
        ),
    ]

    def keys_for_family(family: str) -> set[tuple[str, ...]]:
        keys: set[tuple[str, ...]] = set()
        for param in params:
            if family == "issue_scheme_param_direction" and issue and scheme and direction:
                keys.add((issue, scheme, param, direction))
            elif family == "issue_scheme_param_direction_value" and issue and scheme and direction:
                for value in values:
                    keys.add((issue, scheme, param, direction, value))
            elif family == "env_issue_scheme_param_direction" and issue and vendor and system and scheme and direction:
                keys.add((issue, vendor, system, scheme, param, direction))
            elif family == "env_issue_scheme_param_direction_value" and issue and vendor and system and scheme and direction:
                for value in values:
                    keys.add((issue, vendor, system, scheme, param, direction, value))
            elif family == "boundary_region_scheme_param_direction" and region and band and indoor and scheme and direction:
                keys.add((region, band, indoor, scheme, param, direction))
            elif family == "boundary_region_scheme_param_direction_value" and region and band and indoor and scheme and direction:
                for value in values:
                    keys.add((region, band, indoor, scheme, param, direction, value))
            elif (
                family == "context_issue_scheme_param_direction"
                and issue
                and vendor
                and system
                and region
                and band
                and indoor
                and scheme
                and direction
            ):
                keys.add((issue, vendor, system, region, band, indoor, scheme, param, direction))
            elif (
                family == "context_issue_scheme_param_direction_value"
                and issue
                and vendor
                and system
                and region
                and band
                and indoor
                and scheme
                and direction
            ):
                for value in values:
                    keys.add((issue, vendor, system, region, band, indoor, scheme, param, direction, value))
        return keys

    layers: list[dict[str, Any]] = []
    for level, family, label, selection_rank, path_rank in layer_specs:
        keys = keys_for_family(family)
        layers.append({
            "level": level,
            "key_family": family,
            "label": label,
            "selection_rank": selection_rank,
            "path_rank": path_rank,
            "keys": keys,
        })
    return layers


def _counter_routing_prior(
    action: dict[str, Any],
    trace: dict[str, Any],
    artifacts: dict[str, Any],
) -> dict[str, Any]:
    index = _counter_routing_prior_index(artifacts)
    layers = _counter_routing_candidate_layers(action, trace)
    layer_matches: list[dict[str, Any]] = []
    for layer in layers:
        family = str(layer.get("key_family") or "")
        matches: list[dict[str, Any]] = []
        for key_values in layer.get("keys") or []:
            matches.extend(index.get(family, {}).get(tuple(key_values), []))
        layer_matches.append({
            "level": layer.get("level"),
            "key_family": family,
            "label": layer.get("label"),
            "selection_rank": layer.get("selection_rank"),
            "path_rank": layer.get("path_rank"),
            "candidate_key_count": len(layer.get("keys") or []),
            "hit_count": len(matches),
            "max_failure_lcb": max((_counter_action_prior_failure_lcb(entry) for entry in matches), default=None),
        })
    selected_layer = next(
        (row for row in sorted(layer_matches, key=lambda item: int(item.get("selection_rank") or 999)) if row["hit_count"]),
        None,
    )
    matched_family = str(selected_layer.get("key_family") or "") if selected_layer else ""
    matches = []
    if selected_layer:
        selected_family = str(selected_layer.get("key_family") or "")
        selected_template = next((layer for layer in layers if layer.get("key_family") == selected_family), {})
        for key_values in selected_template.get("keys") or []:
            matches.extend(index.get(selected_family, {}).get(tuple(key_values), []))
    seen: set[str] = set()
    unique: list[dict[str, Any]] = []
    for entry in matches:
        memory = entry.get("memory") if isinstance(entry.get("memory"), dict) else {}
        action_profile = entry.get("action_profile") if isinstance(entry.get("action_profile"), dict) else {}
        memory_id = str(memory.get("memory_id") or id(memory))
        entry_id = "|".join([
            memory_id,
            str(entry.get("prior_scope") or ""),
            _profile_token(action_profile.get("parameter_semantic_id") or action_profile.get("param_cn_name")),
            _profile_token(action_profile.get("direction")),
            _profile_token(
                action_profile.get("value_shape")
                or action_profile.get("normalized_shape_id")
                or action_profile.get("delta_bucket")
                or action_profile.get("change")
            ),
        ])
        if entry_id in seen:
            continue
        seen.add(entry_id)
        unique.append(entry)
    lcbs = [_counter_action_prior_failure_lcb(entry) for entry in unique]
    return {
        "hit": bool(unique),
        "hit_count": len(unique),
        "matched_key_family": matched_family,
        "max_broad_failure_lcb": max(lcbs) if lcbs else None,
        "max_failure_lcb": max(lcbs) if lcbs else None,
        "selected_layer": selected_layer.get("level") if selected_layer else None,
        "selected_layer_label": selected_layer.get("label") if selected_layer else None,
        "selection_policy": "most_specific_nonempty_counter_prior_layer",
        "hierarchical_match_path": [
            {
                "level": row.get("level"),
                "key_family": row.get("key_family"),
                "label": row.get("label"),
                "candidate_key_count": row.get("candidate_key_count"),
                "hit_count": row.get("hit_count"),
                "max_failure_lcb": row.get("max_failure_lcb"),
                "selected": bool(selected_layer and row.get("key_family") == selected_layer.get("key_family")),
            }
            for row in sorted(layer_matches, key=lambda item: int(item.get("path_rank") or 999))
        ],
        "top_memory_ids": [
            (entry.get("memory") or {}).get("memory_id")
            for entry in unique[:5]
            if (entry.get("memory") or {}).get("memory_id")
        ],
        "top_broad_failure_lcbs": lcbs[:5],
        "top_failure_lcbs": lcbs[:5],
        "top_prior_scopes": [entry.get("prior_scope") for entry in unique[:5] if entry.get("prior_scope")],
    }


def _counter_routing_prior_layer_rank(counter_routing_prior: dict[str, Any]) -> int:
    layer = str(counter_routing_prior.get("selected_layer") or "").strip().upper()
    if layer.startswith("L3"):
        return 3
    if layer.startswith("L2"):
        return 2
    if layer.startswith("L1"):
        return 1
    return 0


def _counter_routing_prior_key_family(counter_routing_prior: dict[str, Any]) -> str:
    return str(counter_routing_prior.get("matched_key_family") or "").strip().lower()


def _counter_routing_prior_is_value_specific(counter_routing_prior: dict[str, Any]) -> bool:
    family = _counter_routing_prior_key_family(counter_routing_prior)
    return bool(counter_routing_prior.get("hit")) and family.endswith("_value")


def _counter_routing_prior_is_direction_only(counter_routing_prior: dict[str, Any]) -> bool:
    family = _counter_routing_prior_key_family(counter_routing_prior)
    return bool(counter_routing_prior.get("hit")) and family.endswith("_direction")


def _counter_routing_prior_lcb(counter_routing_prior: dict[str, Any]) -> float | None:
    value = counter_routing_prior.get("max_broad_failure_lcb")
    if isinstance(value, (int, float)):
        return float(value)
    return None


def _counter_direction_hard_review_lcb_min(policy: str) -> float:
    return 0.50


def _counter_routing_prior_review_reason(counter_routing_prior: dict[str, Any]) -> str:
    if _counter_routing_prior_is_direction_only(counter_routing_prior):
        return "counter_direction_high_risk_review"
    layer_rank = _counter_routing_prior_layer_rank(counter_routing_prior)
    if layer_rank >= 3:
        return "counter_l3_value_boundary_review"
    if layer_rank == 2:
        return "counter_l2_action_value_review"
    return "counter_l1_broad_review"


def _action_transition_key(action: dict[str, Any]) -> str:
    before = str(action.get("before_value") or "").strip()
    after = str(action.get("after_value") or "").strip()
    if before or after:
        raw = f"{before}->{after}"
    else:
        raw = str(action.get("change") or action.get("suggested_delta") or action.get("delta_bucket") or "").strip()
    return raw.replace("→", "->").replace(" ", "").lower()


def _action_bundle_param_key(action: dict[str, Any]) -> str:
    return _profile_token(
        action.get("parameter_semantic_id")
        or action.get("param_cn_name")
        or action.get("param_en_name")
        or action.get("site_param_en_name")
    )


def _action_bundle_param_keys(action: dict[str, Any]) -> list[str]:
    keys: list[str] = []
    for value in (
        action.get("parameter_semantic_id"),
        action.get("param_cn_name"),
        action.get("param_en_name"),
        action.get("site_param_en_name"),
    ):
        token = _profile_token(value)
        if token and token not in keys:
            keys.append(token)
    return keys


def _action_companion_signature(action: dict[str, Any]) -> str:
    companions = action.get("plan_companion_parameters")
    if not isinstance(companions, list):
        companions = plan_companion_parameters_from_action(action, source="train_or_candidate_action")
    return companion_signature(companions)


def _action_source_bundle_id(action: dict[str, Any]) -> str:
    return _profile_token(
        action.get("source_action_id")
        or action.get("action_id")
        or action.get("source_memory_id")
    )


def _source_bundle_key(action: dict[str, Any]) -> tuple[str, str, str, str, str, str]:
    return (
        _action_source_bundle_id(action),
        _profile_token(action.get("scheme_id")),
        _action_bundle_param_key(action),
        _profile_token(action.get("direction")),
        _action_transition_key(action),
        _action_companion_signature(action),
    )


def _source_cluster_key(action: dict[str, Any]) -> tuple[str, str, str, str]:
    return (
        _profile_token(action.get("scheme_id")),
        _action_bundle_param_key(action),
        _profile_token(action.get("direction")),
        _action_transition_key(action),
    )


def _source_bundle_keys(action: dict[str, Any]) -> list[tuple[str, str, str, str, str, str]]:
    source_id = _action_source_bundle_id(action)
    if not source_id:
        return []
    scheme = _profile_token(action.get("scheme_id"))
    direction = _profile_token(action.get("direction"))
    transition = _action_transition_key(action)
    companion = _action_companion_signature(action)
    return [
        (source_id, scheme, param_key, direction, transition, companion)
        for param_key in _action_bundle_param_keys(action)
    ]


def _source_cluster_keys(action: dict[str, Any]) -> list[tuple[str, str, str, str]]:
    scheme = _profile_token(action.get("scheme_id"))
    direction = _profile_token(action.get("direction"))
    transition = _action_transition_key(action)
    return [
        (scheme, param_key, direction, transition)
        for param_key in _action_bundle_param_keys(action)
    ]


def _source_bundle_empty_stats() -> dict[str, Any]:
    return {
        "pass_count": 0,
        "fail_count": 0,
        "unknown_count": 0,
        "support_count": 0,
        "trace_ids": [],
        "action_ids": [],
    }


def _source_bundle_profile_index(path: Path | None = None) -> dict[str, Any]:
    source = path or P.TRAIN_TRACE_RECORDS_JSONL
    if not source.exists():
        return {
            "available": False,
            "reason": "train_trace_records_missing",
            "path": str(source),
            "by_bundle": {},
            "by_cluster": {},
        }
    stat = source.stat()
    key = (str(source.resolve()), stat.st_mtime_ns, stat.st_size)
    cached = _SOURCE_BUNDLE_PROFILE_CACHE.get(key)
    if cached is not None:
        return cached

    by_bundle: dict[tuple[str, str, str, str, str], dict[str, Any]] = defaultdict(_source_bundle_empty_stats)
    by_cluster: dict[tuple[str, str, str, str], dict[str, Any]] = defaultdict(_source_bundle_empty_stats)
    trace_count = 0
    action_count = 0
    for trace in cio.read_jsonl(source):
        trace_count += 1
        trace_id = str(trace.get("trace_id") or "")
        for raw_action in trace.get("actions") or []:
            if not isinstance(raw_action, dict):
                continue
            if not raw_action.get("scheme_id"):
                continue
            action = _raw_trace_case_action(raw_action)
            bundle_keys = _source_bundle_keys(action)
            cluster_keys = _source_cluster_keys(action)
            if not bundle_keys or not cluster_keys:
                continue
            outcome = str(raw_action.get("long_eval_result") or "")
            target_stats = [
                by_bundle[bundle_key]
                for bundle_key in bundle_keys
                if all(bundle_key[:5])
            ] + [
                by_cluster[cluster_key]
                for cluster_key in cluster_keys
                if all(cluster_key)
            ]
            for stats in target_stats:
                if outcome == "long_eval_pass":
                    stats["pass_count"] += 1
                elif outcome == "long_eval_fail":
                    stats["fail_count"] += 1
                else:
                    stats["unknown_count"] += 1
                stats["support_count"] = stats["pass_count"] + stats["fail_count"]
                if trace_id and len(stats["trace_ids"]) < 8:
                    stats["trace_ids"].append(trace_id)
                action_id = str(raw_action.get("action_id") or "")
                if action_id and len(stats["action_ids"]) < 8:
                    stats["action_ids"].append(action_id)
            action_count += 1

    payload = {
        "available": True,
        "reason": "ok",
        "path": str(source.resolve()),
        "trace_count": trace_count,
        "action_count": action_count,
        "by_bundle": dict(by_bundle),
        "by_cluster": dict(by_cluster),
    }
    _SOURCE_BUNDLE_PROFILE_CACHE.clear()
    _SOURCE_BUNDLE_PROFILE_CACHE[key] = payload
    return payload


def _source_bundle_support(stats: dict[str, Any]) -> int:
    return int(stats.get("support_count") or 0)


def _source_bundle_best_stats(index: dict[Any, dict[str, Any]], keys: list[tuple[Any, ...]]) -> tuple[tuple[Any, ...], dict[str, Any]]:
    best_key: tuple[Any, ...] = tuple(keys[0]) if keys else tuple()
    best_stats = _source_bundle_empty_stats()
    for key in keys:
        stats = index.get(key)
        if not stats:
            continue
        if _source_bundle_support(stats) > _source_bundle_support(best_stats):
            best_key = key
            best_stats = stats
    return best_key, dict(best_stats)


def _source_bundle_arbitration(action: dict[str, Any]) -> dict[str, Any]:
    index = _source_bundle_profile_index()
    if not index.get("available"):
        return {
            "enabled": True,
            "available": False,
            "reason": index.get("reason") or "source_bundle_profile_unavailable",
            "review": False,
        }
    bundle_keys = _source_bundle_keys(action)
    cluster_keys = _source_cluster_keys(action)
    bundle_key, bundle_stats = _source_bundle_best_stats(index.get("by_bundle") or {}, bundle_keys)
    cluster_key, cluster_stats = _source_bundle_best_stats(index.get("by_cluster") or {}, cluster_keys)
    bundle_pass = int(bundle_stats.get("pass_count") or 0)
    bundle_fail = int(bundle_stats.get("fail_count") or 0)
    cluster_pass = int(cluster_stats.get("pass_count") or 0)
    cluster_fail = int(cluster_stats.get("fail_count") or 0)
    supported_no_exact_fail = bundle_pass > 0 and bundle_fail == 0
    if bundle_fail > 0 and bundle_pass > 0:
        bucket = "true_mixed_source_bundle_pass_and_exact_fail"
        review = True
        reason = "source_bundle_mixed_exact_review"
    elif bundle_fail > 0:
        bucket = "source_bundle_exact_fail_no_pass_support"
        review = True
        reason = "source_bundle_exact_fail_review"
    elif supported_no_exact_fail:
        bucket = "source_bundle_supported_no_exact_fail"
        review = False
        reason = "source_bundle_keep_auto_supported_no_exact_fail"
    elif cluster_fail > 0:
        bucket = "source_cluster_has_exact_fail"
        review = True
        reason = "source_cluster_exact_fail_review"
    elif cluster_pass > 0:
        bucket = "source_cluster_supported_no_exact_fail"
        review = False
        reason = "source_cluster_keep_auto_supported_no_exact_fail"
    else:
        bucket = "source_bundle_unseen_or_unsupported"
        review = False
        reason = "source_bundle_no_decision"
    return {
        "enabled": True,
        "available": True,
        "policy": "source_bundle_arbitration_train_only_v1",
        "review": review,
        "review_reason": reason if review else "",
        "release_reason": reason if not review and reason.startswith("source_") else "",
        "bucket": bucket,
        "source_bundle_key": list(bundle_key),
        "source_cluster_key": list(cluster_key),
        "bundle_pass_count": bundle_pass,
        "bundle_fail_count": bundle_fail,
        "bundle_unknown_count": int(bundle_stats.get("unknown_count") or 0),
        "cluster_pass_count": cluster_pass,
        "cluster_fail_count": cluster_fail,
        "cluster_unknown_count": int(cluster_stats.get("unknown_count") or 0),
        "supported_no_exact_fail": supported_no_exact_fail,
        "bundle_trace_ids": bundle_stats.get("trace_ids") or [],
        "cluster_trace_ids": cluster_stats.get("trace_ids") or [],
    }


def _memory_evidence_profile_index(artifacts: dict[str, Any]) -> dict[str, Any]:
    cache_key = _artifact_cache_key(artifacts, "memory_evidence_profiles")
    cached = _MEMORY_EVIDENCE_PROFILE_INDEX_CACHE.get(cache_key)
    if cached is not None:
        return cached
    profiles = [
        profile
        for profile in (artifacts.get("memory_evidence_profiles") or [])
        if isinstance(profile, dict)
    ]
    by_parent: dict[str, list[dict[str, Any]]] = defaultdict(list)
    counter_profiles: list[dict[str, Any]] = []
    for profile in profiles:
        parent_id = str(profile.get("parent_memory_id") or "").strip()
        if parent_id:
            by_parent[parent_id].append(profile)
        if profile.get("profile_type") == "counter_profile":
            counter_profiles.append(profile)
    index = {
        "all": profiles,
        "by_parent": by_parent,
        "counter_profiles": counter_profiles,
    }
    _MEMORY_EVIDENCE_PROFILE_INDEX_CACHE.clear()
    _MEMORY_EVIDENCE_PROFILE_INDEX_CACHE[cache_key] = index
    return index


def _profile_context_matches(profile: dict[str, Any], trace: dict[str, Any]) -> bool:
    keys = profile.get("key_values") if isinstance(profile.get("key_values"), dict) else {}
    boundary = profile.get("boundary_context") if isinstance(profile.get("boundary_context"), dict) else {}
    query = trace_query(trace)
    ticket = trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}
    checks = [
        (keys.get("issue_type") or boundary.get("issue_types"), query.get("issue_type")),
        (keys.get("vendor") or boundary.get("vendors"), query.get("vendor")),
        (keys.get("system") or boundary.get("systems"), query.get("system")),
        (keys.get("region") or boundary.get("regions"), query.get("region")),
        (keys.get("band") or boundary.get("bands"), ticket.get("band")),
    ]
    return all(_profile_value_match(expected, observed) for expected, observed in checks)


def _action_shape_values(action: dict[str, Any]) -> set[str]:
    return {
        str(value or "").strip().lower()
        for value in (
            action.get("normalized_shape_id"),
            action.get("value_shape"),
            action.get("value_pattern_id"),
        )
        if str(value or "").strip()
    }


def _profile_action_candidate_matches(candidate: dict[str, Any], action: dict[str, Any]) -> bool:
    if not isinstance(candidate, dict):
        return False
    matched = 0
    comparisons = [
        ("scheme_id", action.get("scheme_id")),
        ("scheme_group", action.get("scheme_group")),
        ("parameter_semantic_id", action.get("parameter_semantic_id")),
        ("param_cn_name", action.get("param_cn_name")),
    ]
    for key, observed in comparisons:
        expected = candidate.get(key)
        if expected and observed:
            if not _profile_value_match(expected, observed):
                return False
            matched += 1
    expected_direction = str(candidate.get("direction") or "").strip().lower()
    observed_direction = str(action.get("direction") or "").strip().lower()
    if expected_direction and observed_direction:
        if not _direction_compatible(
            expected_direction,
            observed_direction,
            param_name=str(action.get("param_cn_name") or candidate.get("param_cn_name") or ""),
        ):
            return False
        matched += 1
    expected_shape = (
        candidate.get("value_shape")
        or candidate.get("shape_id")
        or candidate.get("normalized_shape_id")
    )
    action_shapes = _action_shape_values(action)
    if expected_shape and action_shapes:
        if str(expected_shape).strip().lower() not in action_shapes:
            return False
        matched += 1
    return matched > 0


def _profile_action_candidate_is_specific(candidate: dict[str, Any]) -> bool:
    if not isinstance(candidate, dict):
        return False
    parameter = candidate.get("parameter_semantic_id") or candidate.get("param_cn_name")
    direction = candidate.get("direction")
    value_shape = (
        candidate.get("value_shape")
        or candidate.get("shape_id")
        or candidate.get("normalized_shape_id")
        or candidate.get("delta_bucket")
        or candidate.get("change")
    )
    return bool((parameter and direction) or value_shape)


def _profile_action_match_detail(
    profile: dict[str, Any],
    action: dict[str, Any],
    trace: dict[str, Any],
) -> tuple[bool, bool]:
    if not _profile_context_matches(profile, trace):
        return False, False
    keys = profile.get("key_values") if isinstance(profile.get("key_values"), dict) else {}
    semantics = profile.get("action_semantics") if isinstance(profile.get("action_semantics"), dict) else {}
    value_distribution = (
        profile.get("value_delta_distribution")
        if isinstance(profile.get("value_delta_distribution"), dict)
        else {}
    )
    candidates: list[dict[str, Any]] = [keys, semantics]
    for field in ("action_profiles", "counter_action_profiles"):
        values = semantics.get(field)
        if isinstance(values, list):
            candidates.extend(item for item in values if isinstance(item, dict))
        values = value_distribution.get(field)
        if isinstance(values, list):
            candidates.extend(item for item in values if isinstance(item, dict))
    matched = False
    action_specific = False
    for candidate in candidates:
        if not _profile_action_candidate_matches(candidate, action):
            continue
        matched = True
        action_specific = action_specific or _profile_action_candidate_is_specific(candidate)
    key_family = str(profile.get("key_family") or "").strip().lower()
    if matched and key_family in {"strategy_action_shape"}:
        action_specific = True
    return matched, action_specific


def _child_profile_matches_action(child: dict[str, Any], action: dict[str, Any]) -> bool:
    keys = child.get("key_values") if isinstance(child.get("key_values"), dict) else {}
    if not keys:
        return False
    matched = 0
    if keys.get("change"):
        observed_change = str(action.get("change") or "").strip().lower()
        if not observed_change or str(keys["change"]).strip().lower() != observed_change:
            return False
        matched += 1
    if keys.get("delta_bucket"):
        observed_deltas = _profile_values([
            action.get("delta_bucket"),
            action.get("suggested_delta"),
        ])
        if not observed_deltas or str(keys["delta_bucket"]).strip().lower() not in observed_deltas:
            return False
        matched += 1
    expected_shape = keys.get("shape_id") or keys.get("value_shape")
    if expected_shape:
        action_shapes = _action_shape_values(action)
        if not action_shapes or str(expected_shape).strip().lower() not in action_shapes:
            return False
        matched += 1
    if keys.get("direction"):
        expected_direction = str(keys.get("direction") or "").strip().lower()
        observed_direction = str(action.get("direction") or "").strip().lower()
        if not observed_direction or not _direction_compatible(
            expected_direction,
            observed_direction,
            param_name=str(action.get("param_cn_name") or ""),
        ):
            return False
        matched += 1
    return matched > 0


def _profile_hit_summary(
    profile: dict[str, Any],
    *,
    matched_from: str,
    child: dict[str, Any] | None = None,
    action_specific_match: bool = False,
) -> dict[str, Any]:
    source = child if isinstance(child, dict) else profile
    stats = source.get("outcome_statistics") if isinstance(source.get("outcome_statistics"), dict) else {}
    profile_type = str(source.get("profile_type") or profile.get("profile_type") or "")
    return {
        "profile_id": (
            source.get("child_profile_id")
            or source.get("profile_id")
            or profile.get("profile_id")
        ),
        "parent_profile_id": profile.get("profile_id"),
        "parent_memory_id": profile.get("parent_memory_id"),
        "profile_type": profile_type,
        "key_family": source.get("key_family") or profile.get("key_family"),
        "recommended_routing": source.get("recommended_routing") or profile.get("recommended_routing"),
        "support_count": int(stats.get("support_count") or 0),
        "pass_lcb": round(float(stats.get("pass_lcb") or 0.0), 6),
        "failure_lcb": round(float(stats.get("failure_lcb") or 0.0), 6),
        "conflict_reason": source.get("conflict_reason") or profile.get("conflict_reason"),
        "matched_from": matched_from,
        "action_specific_match": bool(action_specific_match),
    }


def _strategy_positive_hit_summary(strategy_evidence: list[dict[str, Any]]) -> list[dict[str, Any]]:
    hits: list[dict[str, Any]] = []
    for evidence in strategy_evidence:
        if not isinstance(evidence, dict):
            continue
        lcb = float(evidence.get("lcb") or 0.0)
        action_shape = float(evidence.get("action_shape_match") or 0.0)
        support_count = int(evidence.get("support_count") or 0)
        state = str(evidence.get("state") or "").strip()
        if state == "counter_evidence":
            continue
        if lcb < 0.55 or action_shape < 0.75 or support_count < 5:
            continue
        hits.append({
            "memory_id": evidence.get("memory_id"),
            "memory_type": evidence.get("memory_type"),
            "state": evidence.get("state"),
            "support_count": support_count,
            "pass_lcb": round(lcb, 6),
            "pass_rate": round(float(evidence.get("pass_rate") or 0.0), 6),
            "action_shape_match": round(action_shape, 6),
            "boundary_match": round(float(evidence.get("boundary_match") or 0.0), 6),
            "matched_from": "strategy_evidence",
        })
    hits.sort(key=lambda item: (item["pass_lcb"], item["support_count"], str(item.get("memory_id") or "")), reverse=True)
    return hits[:5]


def _strategy_value_transition_support(
    action: dict[str, Any],
    strategy_evidence: list[dict[str, Any]],
    artifacts: dict[str, Any],
) -> dict[str, Any]:
    value_type = str(action.get("value_type") or "").strip().lower()
    if value_type not in {"enum", "switch", "switch_enum"}:
        return {"applicable": False, "supported": None, "reason": "not_enum_switch"}
    action_change = _profile_token(action.get("change"))
    action_values = _action_value_tokens(action)
    if action_change:
        action_values.add(action_change)
    if not action_values:
        return {"applicable": True, "supported": None, "reason": "no_candidate_transition_value"}

    memories_by_id = _artifact_memory_by_id(artifacts)
    matched_rows: list[dict[str, Any]] = []
    inspected_memory_ids: list[str] = []
    for evidence in strategy_evidence:
        if not isinstance(evidence, dict):
            continue
        memory_id = str(evidence.get("memory_id") or "")
        memory = memories_by_id.get(memory_id) if memory_id else None
        if not isinstance(memory, dict):
            continue
        if _memory_action_shape_score(memory, action) < 0.50:
            continue
        inspected_memory_ids.append(memory_id)
        content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
        pattern = content.get("value_pattern") if isinstance(content.get("value_pattern"), dict) else {}
        rows: list[dict[str, Any]] = []
        for row in pattern.get("delta_distribution") or []:
            if isinstance(row, dict):
                rows.append(row)
        for row in content.get("observed_changes") or []:
            if isinstance(row, dict):
                rows.append(row)
        for row in pattern.get("observed_changes") or []:
            if isinstance(row, dict):
                rows.append(row)
        for row in rows:
            row_values = {
                _profile_token(row.get("change")),
                _profile_token(row.get("delta_bucket")),
                _profile_token(row.get("suggested_delta")),
                _profile_token(row.get("normalized_shape_id")),
                _profile_token(row.get("shape_id")),
            }
            row_values = {value for value in row_values if value}
            if row_values & action_values:
                matched_rows.append({
                    "memory_id": memory_id,
                    "source": row.get("source") or "",
                    "change": row.get("change") or "",
                    "delta_bucket": row.get("delta_bucket") or "",
                    "support_count": int(row.get("support_count") or 0),
                    "pass_rate": row.get("pass_rate"),
                })
    matched_rows.sort(
        key=lambda item: (
            int(item.get("support_count") or 0),
            str(item.get("memory_id") or ""),
            str(item.get("change") or item.get("delta_bucket") or ""),
        ),
        reverse=True,
    )
    return {
        "applicable": True,
        "supported": bool(matched_rows),
        "reason": "matched_strategy_transition_distribution" if matched_rows else "enum_switch_transition_not_in_strategy_distribution",
        "candidate_change": action.get("change") or "",
        "candidate_values": sorted(action_values)[:8],
        "inspected_memory_ids": inspected_memory_ids[:8],
        "hit_count": len(matched_rows),
        "top_hits": matched_rows[:5],
    }


def _summarize_profile_consumption(
    hits: list[dict[str, Any]],
    *,
    policy: str,
    support_routing_hits: list[dict[str, Any]] | None = None,
    counter_routing_prior: dict[str, Any] | None = None,
    strategy_positive_hits: list[dict[str, Any]] | None = None,
    strategy_value_transition_support: dict[str, Any] | None = None,
    source_bundle_arbitration: dict[str, Any] | None = None,
) -> dict[str, Any]:
    support_routing_hits = support_routing_hits or []
    counter_routing_prior = counter_routing_prior or {}
    strategy_positive_hits = strategy_positive_hits or []
    strategy_value_transition_support = strategy_value_transition_support or {
        "applicable": False,
        "supported": None,
        "reason": "not_evaluated",
    }
    source_bundle_arbitration = source_bundle_arbitration or {
        "enabled": True,
        "available": False,
        "review": False,
        "reason": "not_evaluated",
    }
    counts = Counter(str(hit.get("profile_type") or "unknown") for hit in hits)
    support_strength = max(
        (float(hit.get("pass_lcb") or 0.0) for hit in hits if hit.get("profile_type") == "support_profile"),
        default=0.0,
    )
    conflict_support_strength = max(
        (float(hit.get("pass_lcb") or 0.0) for hit in hits if hit.get("profile_type") == "conflict_profile"),
        default=0.0,
    )
    counter_strength = max(
        (float(hit.get("failure_lcb") or 0.0) for hit in hits if hit.get("profile_type") == "counter_profile"),
        default=0.0,
    )
    conflict_strength = max(
        (float(hit.get("failure_lcb") or 0.0) for hit in hits if hit.get("profile_type") == "conflict_profile"),
        default=0.0,
    )
    sparse_strength = max(
        (float(hit.get("failure_lcb") or 0.0) for hit in hits if hit.get("profile_type") == "sparse_profile"),
        default=0.0,
    )
    support_routing_strength = max(
        (float(hit.get("pass_lcb") or 0.0) for hit in support_routing_hits),
        default=0.0,
    )
    strategy_positive_strength = max(
        (float(hit.get("pass_lcb") or 0.0) for hit in strategy_positive_hits),
        default=0.0,
    )
    direction_positive_strength = max(
        support_strength,
        conflict_support_strength,
        support_routing_strength,
        strategy_positive_strength,
    )
    consume_conflict = _profile_consumes_conflict(policy)
    arbitrated = _profile_uses_arbitration(policy)
    rank_adjustment = 0.0 if arbitrated or _profile_review_only_policy(policy) else (
        0.06 * support_strength
        - 0.08 * counter_strength
        - (0.06 * conflict_strength if consume_conflict else 0.0)
        - (0.01 if counts.get("sparse_profile") else 0.0)
    )
    review_reasons: list[str] = []
    release_reasons: list[str] = []
    diagnostic_reasons: list[str] = []
    counter_prior_lcb = _counter_routing_prior_lcb(counter_routing_prior)
    counter_lcb_max = _arbitration_counter_lcb_max(policy)
    low_counter_prior = (
        counter_prior_lcb is not None
        and counter_prior_lcb <= counter_lcb_max
        and bool(counter_routing_prior.get("hit"))
    )
    direction_hard_lcb_min = _counter_direction_hard_review_lcb_min(policy)
    counter_prior_hit = bool(counter_routing_prior.get("hit"))
    counter_prior_layer_rank = _counter_routing_prior_layer_rank(counter_routing_prior)
    counter_prior_value_specific_hit = _counter_routing_prior_is_value_specific(counter_routing_prior)
    counter_prior_direction_only_hit = _counter_routing_prior_is_direction_only(counter_routing_prior)
    counter_prior_direction_high_risk_hit = (
        counter_prior_direction_only_hit
        and counter_prior_layer_rank >= 3
        and counter_prior_lcb is not None
        and counter_prior_lcb >= direction_hard_lcb_min
    )
    counter_prior_hard_review_hit = (
        (counter_prior_value_specific_hit and not low_counter_prior)
        or counter_prior_direction_high_risk_hit
    )
    counter_prior_high_risk_hit = (
        counter_prior_hard_review_hit
        and counter_prior_lcb is not None
        and counter_prior_lcb >= direction_hard_lcb_min
    )
    strong_support_routing = bool(support_routing_hits) and support_routing_strength >= 0.60
    specific_positive_channel = (
        bool(support_routing_hits)
        or counts.get("support_profile", 0) > 0
        or counts.get("conflict_profile", 0) > 0
    )
    direction_positive_support = (
        direction_positive_strength >= 0.55
        and specific_positive_channel
    )
    support_counter_margin = (
        round(direction_positive_strength - counter_prior_lcb, 6)
        if counter_prior_lcb is not None
        else None
    )
    counter_outweighs_direction_positive = (
        counter_prior_hard_review_hit
        and (
            counter_prior_high_risk_hit
            or counter_prior_lcb is None
            or direction_positive_strength < counter_prior_lcb + 0.10
        )
    )
    if counter_prior_direction_only_hit and not counter_prior_direction_high_risk_hit:
        diagnostic_reasons.append("counter_direction_only_diagnostic")
    if counter_prior_value_specific_hit and low_counter_prior:
        diagnostic_reasons.append("counter_value_low_risk_diagnostic")
    support_protect = direction_positive_support and not counter_outweighs_direction_positive
    unsupported_enum_switch_transition_review = (
        bool(strategy_value_transition_support.get("applicable"))
        and strategy_value_transition_support.get("supported") is False
        and direction_positive_support
        and counter_prior_value_specific_hit
        and not low_counter_prior
    )
    source_bundle_review = bool(source_bundle_arbitration.get("review"))
    source_bundle_review_reason = str(
        source_bundle_arbitration.get("review_reason")
        or "source_bundle_exact_fail_review"
    )
    counter_action_specific_hits = [
        hit
        for hit in hits
        if hit.get("profile_type") == "counter_profile" and hit.get("action_specific_match")
    ]
    counter_action_specific_only = _profile_reviews_action_specific_counter_only(policy)
    table4_stage = _table4_cumulative_stage(policy)
    if _table4_support_rescue_only(policy) or table4_stage == "support":
        if support_protect:
            release_reasons.append("table4_support_rescue")
        elif counter_action_specific_hits:
            review_reasons.append("profile_counter_action_specific_review")
    elif _table4_support_conflict_sparse(policy):
        if support_protect:
            release_reasons.append("table4_support_rescue")
        elif counter_action_specific_hits:
            review_reasons.append("profile_counter_action_specific_review")
        elif consume_conflict and counts.get("conflict_profile"):
            review_reasons.append("profile_conflict_review")
        elif counts.get("sparse_profile") and not counts.get("support_profile") and not counts.get("counter_profile") and not counts.get("conflict_profile"):
            review_reasons.append("profile_sparse_review")
    elif table4_stage:
        stages = ["source", "enum", "counter_value", "counter_direction"]
        upto = stages.index(table4_stage) if table4_stage in stages else -1
        if upto >= 0 and source_bundle_review:
            review_reasons.append(source_bundle_review_reason)
        elif upto >= 1 and unsupported_enum_switch_transition_review:
            review_reasons.append("unsupported_enum_switch_transition_review")
        elif support_protect:
            release_reasons.append("table4_support_rescue")
        elif upto >= 2 and counter_prior_value_specific_hit and not low_counter_prior:
            review_reasons.append("counter_l3_value_boundary_review")
        elif upto >= 3 and counter_prior_direction_high_risk_hit:
            review_reasons.append("counter_direction_high_risk_review")
        elif counter_action_specific_hits:
            review_reasons.append("profile_counter_action_specific_review")
        elif consume_conflict and counts.get("conflict_profile"):
            review_reasons.append("profile_conflict_review")
        elif counts.get("sparse_profile") and not counts.get("support_profile") and not counts.get("counter_profile") and not counts.get("conflict_profile"):
            review_reasons.append("profile_sparse_review")
    elif arbitrated:
        if source_bundle_review:
            review_reasons.append(source_bundle_review_reason)
        elif unsupported_enum_switch_transition_review:
            review_reasons.append("unsupported_enum_switch_transition_review")
        elif support_protect:
            if not counter_prior_hit:
                release_reasons.append("support_release_no_specific_counter")
            elif counter_prior_layer_rank <= 1:
                release_reasons.append("support_release_l1_counter_only")
            elif counter_prior_direction_only_hit and not counter_prior_direction_high_risk_hit:
                release_reasons.append("support_release_direction_only_counter")
            elif counter_prior_value_specific_hit and not low_counter_prior:
                release_reasons.append("direction_positive_release_counter_below_support_margin")
            else:
                release_reasons.append("support_release_low_specific_counter_prior")
        elif direction_positive_support and counter_prior_hard_review_hit:
            review_reasons.append("support_counter_specific_conflict_review")
        elif counter_prior_hard_review_hit:
            review_reasons.append(_counter_routing_prior_review_reason(counter_routing_prior))
        elif consume_conflict and counts.get("conflict_profile"):
            review_reasons.append("profile_conflict_review")
        elif counts.get("sparse_profile") and not counts.get("support_profile") and not counts.get("counter_profile") and not counts.get("conflict_profile"):
            review_reasons.append("profile_sparse_review")
    elif _gate_reviews_high_no_action_specificity(policy):
        pass
    elif counter_action_specific_only:
        if counter_action_specific_hits:
            review_reasons.append("profile_counter_action_specific_review")
    else:
        if counts.get("counter_profile"):
            review_reasons.append("profile_counter_review")
        if consume_conflict and counts.get("conflict_profile"):
            review_reasons.append("profile_conflict_review")
        if counts.get("sparse_profile") and not counts.get("support_profile") and not counts.get("counter_profile") and not counts.get("conflict_profile"):
            review_reasons.append("profile_sparse_review")
    return {
        "enabled": True,
        "policy": policy,
        "consume_conflict": consume_conflict,
        "arbitrated": arbitrated,
        "profile_hit_count": len(hits),
        "profile_count_by_type": dict(counts),
        "support_profile_count": counts.get("support_profile", 0),
        "counter_profile_count": counts.get("counter_profile", 0),
        "counter_action_specific_profile_count": len(counter_action_specific_hits),
        "conflict_profile_count": counts.get("conflict_profile", 0),
        "sparse_profile_count": counts.get("sparse_profile", 0),
        "support_strength": round(support_strength, 6),
        "conflict_support_strength": round(conflict_support_strength, 6),
        "counter_strength": round(counter_strength, 6),
        "conflict_strength": round(conflict_strength, 6),
        "sparse_strength": round(sparse_strength, 6),
        "support_routing_profile_count": len(support_routing_hits),
        "support_routing_strength": round(support_routing_strength, 6),
        "strategy_positive_evidence_count": len(strategy_positive_hits),
        "strategy_positive_strength": round(strategy_positive_strength, 6),
        "direction_positive_strength": round(direction_positive_strength, 6),
        "specific_positive_channel": specific_positive_channel,
        "direction_positive_support": direction_positive_support,
        "support_counter_margin": support_counter_margin,
        "counter_routing_prior": counter_routing_prior,
        "counter_routing_lcb_max": counter_lcb_max,
        "counter_direction_hard_lcb_min": direction_hard_lcb_min,
        "counter_routing_layer_rank": counter_prior_layer_rank,
        "counter_routing_layer_specific_hit": counter_prior_hit and counter_prior_layer_rank >= 2,
        "counter_routing_value_specific_hit": counter_prior_value_specific_hit,
        "counter_routing_direction_only_hit": counter_prior_direction_only_hit,
        "counter_routing_direction_high_risk_hit": counter_prior_direction_high_risk_hit,
        "counter_routing_high_risk_hit": counter_prior_high_risk_hit,
        "counter_outweighs_direction_positive": counter_outweighs_direction_positive,
        "counter_routing_hard_review_hit": counter_prior_hard_review_hit,
        "counter_routing_specific_hit": counter_prior_hard_review_hit,
        "counter_routing_diagnostic_reasons": diagnostic_reasons,
        "strategy_value_transition_support": strategy_value_transition_support,
        "unsupported_enum_switch_transition_review": unsupported_enum_switch_transition_review,
        "source_bundle_arbitration": source_bundle_arbitration,
        "source_bundle_review": source_bundle_review,
        "strong_support_routing": strong_support_routing,
        "support_protect": support_protect,
        "rank_adjustment": round(rank_adjustment, 6),
        "gate_review_reasons": review_reasons,
        "gate_release_reasons": release_reasons,
        "hits": hits[:12],
        "support_routing_hits": support_routing_hits[:12],
        "strategy_positive_hits": strategy_positive_hits[:5],
    }


def _memory_evidence_profile_consumption(
    action: dict[str, Any],
    trace: dict[str, Any],
    strategy_evidence: list[dict[str, Any]],
    artifacts: dict[str, Any],
    *,
    policy: str,
) -> dict[str, Any]:
    if not _profile_consumption_enabled(policy):
        return {"enabled": False, "policy": "off"}
    profile_index = _memory_evidence_profile_index(artifacts)
    by_parent = profile_index.get("by_parent") if isinstance(profile_index.get("by_parent"), dict) else {}
    candidate_profiles: list[tuple[dict[str, Any], str]] = []
    seen_profile_ids: set[str] = set()

    def add_profile(profile: dict[str, Any], matched_from: str) -> None:
        profile_id = str(profile.get("profile_id") or id(profile))
        if profile_id in seen_profile_ids:
            return
        seen_profile_ids.add(profile_id)
        candidate_profiles.append((profile, matched_from))

    for evidence in strategy_evidence:
        parent_id = str(evidence.get("memory_id") or "").strip()
        for profile in by_parent.get(parent_id, []):
            add_profile(profile, "strategy_evidence_parent")
    for profile in profile_index.get("counter_profiles") or []:
        add_profile(profile, "counter_profile_global")

    hits: list[dict[str, Any]] = []
    for profile, matched_from in candidate_profiles:
        profile_matched, action_specific_match = _profile_action_match_detail(profile, action, trace)
        if not profile_matched:
            continue
        hits.append(
            _profile_hit_summary(
                profile,
                matched_from=matched_from,
                action_specific_match=action_specific_match,
            )
        )
        child_profiles = profile.get("child_profiles") if isinstance(profile.get("child_profiles"), list) else []
        for child in child_profiles:
            if isinstance(child, dict) and _child_profile_matches_action(child, action):
                hits.append(
                    _profile_hit_summary(
                        profile,
                        matched_from="matched_child_profile",
                        child=child,
                        action_specific_match=True,
                    )
                )
    support_routing_hits: list[dict[str, Any]] = []
    counter_prior: dict[str, Any] = {}
    if _profile_uses_arbitration(policy):
        support_routing_hits = _support_routing_profile_hits(action, trace, artifacts)
        counter_prior = _counter_routing_prior(action, trace, artifacts)
    strategy_positive_hits = _strategy_positive_hit_summary(strategy_evidence)
    strategy_transition_support = _strategy_value_transition_support(action, strategy_evidence, artifacts)
    source_bundle_gate = _source_bundle_arbitration(action) if _profile_uses_arbitration(policy) else {
        "enabled": False,
        "available": False,
        "review": False,
        "reason": "arbitration_policy_off",
    }
    return _summarize_profile_consumption(
        hits,
        policy=policy,
        support_routing_hits=support_routing_hits,
        counter_routing_prior=counter_prior,
        strategy_positive_hits=strategy_positive_hits,
        strategy_value_transition_support=strategy_transition_support,
        source_bundle_arbitration=source_bundle_gate,
    )


def _apply_memory_evidence_profile_gate(
    gate: dict[str, Any],
    profile_consumption: dict[str, Any],
    *,
    policy: str,
) -> dict[str, Any]:
    high_no_action_review = _gate_reviews_high_no_action_specificity(policy)
    current_decision = str(gate.get("gate_decision") or "")
    current_reason = str(gate.get("gate_reason") or "")
    if high_no_action_review and current_decision in {"accept", "downgrade"} and current_reason == "failcohort_hit_high_no_action_specificity_diagnostic":
        out = dict(gate)
        out["profile_gate_policy"] = "runtime_gate_review_policy_v1"
        out["profile_routing_hit"] = True
        out["profile_review_reasons"] = ["high_no_action_specificity_review"]
        out["profile_release_reasons"] = []
        out["memory_evidence_profile_consumption"] = profile_consumption
        out["gate_decision"] = "require_review"
        out["needs_human_review"] = True
        out["risk_level"] = "medium" if str(out.get("risk_level") or "low") == "low" else out.get("risk_level")
        out["gate_reason"] = "high_no_action_specificity_review"
        out["threshold_band"] = "runtime_review_high_no_action_specificity"
        return out
    if not _profile_consumption_enabled(policy) or not profile_consumption.get("enabled"):
        return gate
    out = dict(gate)
    review_reasons = list(profile_consumption.get("gate_review_reasons") or [])
    release_reasons = list(profile_consumption.get("gate_release_reasons") or [])
    out["profile_gate_policy"] = "memory_evidence_profile_consumption_v1"
    out["profile_routing_hit"] = bool(review_reasons or release_reasons)
    out["profile_review_reasons"] = review_reasons
    out["profile_release_reasons"] = release_reasons
    out["memory_evidence_profile_consumption"] = profile_consumption
    if not review_reasons and not release_reasons:
        return out
    current_decision = str(out.get("gate_decision") or "")
    if release_reasons and not review_reasons and current_decision == "require_review":
        out["gate_decision"] = "accept"
        out["needs_human_review"] = False
        out["risk_level"] = "low"
        out["gate_reason"] = "+".join(release_reasons)
        out["threshold_band"] = "profile_support_release"
    elif current_decision in {"accept", "downgrade"} and review_reasons:
        out["gate_decision"] = "require_review"
        out["needs_human_review"] = True
        out["risk_level"] = "medium" if str(out.get("risk_level") or "low") == "low" else out.get("risk_level")
        out["gate_reason"] = "+".join(review_reasons)
        out["threshold_band"] = "profile_review"
    elif current_decision == "require_review" and review_reasons:
        reason = str(out.get("gate_reason") or "require_review")
        out["gate_reason"] = reason + "+" + "+".join(review_reasons)
    return out


def _compiled_knowledge_rank_score(
    memory: dict[str, Any],
    trace: dict[str, Any],
    artifacts: dict[str, Any],
    *,
    variant: str,
    profile_consumption_policy: str = "off",
    candidate_action: dict[str, Any] | None = None,
) -> dict[str, Any]:
    structural_selection = variant in _STRUCTURAL_STRATEGY_SELECTION_VARIANTS
    action = (
        candidate_action
        if isinstance(candidate_action, dict)
        else _case_action(
            memory,
            action_admission_policy=(
                _STRUCTURAL_ACTION_ADMISSION_POLICY
                if structural_selection
                else "all_case_actions_v1"
            ),
        )
    )
    query = trace_query(trace)
    context_score = _case_score(memory, query)
    context_term = min(1.0, context_score / 18.0)
    all_memories = artifacts.get("memories") if isinstance(artifacts.get("memories"), list) else []
    case_pass_rate = 0.0 if structural_selection else _case_pass_rate(memory)
    structural_selection_policy = _STRUCTURAL_SELECTION_POLICY_BY_VARIANT.get(
        variant,
        "structural_relation_v1",
    )
    evidence = _candidate_strategy_evidence(
        action,
        trace,
        all_memories,
        selection_policy=(
            structural_selection_policy
            if structural_selection
            else "outcome_calibrated_v1"
        ),
    )
    best = evidence[0] if evidence else {}
    terms = {
        "context_similarity": context_term,
        "case_outcome_pass_rate": case_pass_rate,
        "strategy_pass_rate": float(best.get("pass_rate") or 0.0),
        "strategy_lcb": float(best.get("lcb") or 0.0),
        "strategy_support": float(best.get("support_term") or 0.0),
        "related_case": case_pass_rate,
        "boundary_match": float(best.get("boundary_match") or 0.0),
        "action_shape_match": float(best.get("action_shape_match") or 0.0),
        "memory_state": float(best.get("state_term") or 0.0),
    }
    if variant == "similarity_only":
        weights = {"context_similarity": 1.0}
    else:
        weights = {
            "context_similarity": 0.35,
            "strategy_lcb": 0.20,
            "strategy_pass_rate": 0.15,
            "strategy_support": 0.10,
            "related_case": 0.08,
            "boundary_match": 0.05,
            "action_shape_match": 0.05,
            "memory_state": 0.02,
        }
        if variant == "no_outcome_counts":
            for key in ("strategy_lcb", "strategy_pass_rate", "memory_state"):
                weights[key] = 0.0
        elif variant == "no_lcb":
            weights["strategy_lcb"] = 0.0
            weights["strategy_pass_rate"] += 0.10
        elif variant == "no_related_cases":
            weights["related_case"] = 0.0
        elif variant == "no_boundary":
            weights["boundary_match"] = 0.0
        elif variant == "no_action_shape":
            weights["action_shape_match"] = 0.0
        elif variant == "no_memory_state":
            weights["memory_state"] = 0.0
        elif variant == "outcome_lcb_light":
            weights = {
                "context_similarity": 0.45,
                "strategy_lcb": 0.08,
                "strategy_pass_rate": 0.05,
                "strategy_support": 0.08,
                "related_case": 0.06,
                "boundary_match": 0.06,
                "action_shape_match": 0.20,
                "memory_state": 0.02,
            }
        elif variant == "action_shape_strong":
            weights = {
                "context_similarity": 0.35,
                "strategy_lcb": 0.12,
                "strategy_pass_rate": 0.08,
                "strategy_support": 0.08,
                "related_case": 0.05,
                "boundary_match": 0.07,
                "action_shape_match": 0.23,
                "memory_state": 0.02,
            }
        elif variant == "context_shape_balanced":
            weights = {
                "context_similarity": 0.50,
                "strategy_lcb": 0.08,
                "strategy_pass_rate": 0.05,
                "strategy_support": 0.06,
                "related_case": 0.04,
                "boundary_match": 0.07,
                "action_shape_match": 0.18,
                "memory_state": 0.02,
            }
        elif variant == "no_outcome_counts_plus_shape":
            weights = {
                "context_similarity": 0.60,
                "strategy_lcb": 0.0,
                "strategy_pass_rate": 0.0,
                "strategy_support": 0.08,
                "related_case": 0.0,
                "boundary_match": 0.10,
                "action_shape_match": 0.20,
                "memory_state": 0.0,
            }
    if structural_selection:
        for key in (
            "strategy_lcb",
            "strategy_pass_rate",
            "strategy_support",
            "related_case",
            "memory_state",
        ):
            weights[key] = 0.0
    weight_sum = sum(weight for weight in weights.values() if weight > 0) or sum(abs(weight) for weight in weights.values()) or 1.0
    base_total = sum(terms[key] * weight for key, weight in weights.items()) / weight_sum
    bundle_prior_adjustment = 0.0
    if variant == "no_outcome_counts_bundle_participation_prior" and best.get("bundle_participation_prior_available"):
        prior_support = int(best.get("bundle_participation_support") or 0)
        prior_rate = float(best.get("bundle_participation_pass_rate") or 0.0)
        reliability = min(1.0, math.log1p(prior_support) / math.log1p(20.0))
        # Pre-registered weak centered prior: max absolute rank movement 0.015.
        # It is rank-only and is never passed to the fail-cohort gate.
        bundle_prior_adjustment = 0.03 * (prior_rate - 0.5) * reliability
    # Runtime outcome/profile arbitration stays on its own attribution-checked
    # evidence view. Structural retrieval never upgrades component-associated
    # facts into action outcomes, and the Gate does not inherit the structural
    # selector's outcome-free truncation.
    profile_evidence = (
        _candidate_strategy_evidence(
            action,
            trace,
            all_memories,
            selection_policy="outcome_calibrated_v1",
        )
        if structural_selection and _profile_consumption_enabled(profile_consumption_policy)
        else evidence
    )
    profile_consumption = _memory_evidence_profile_consumption(
        action,
        trace,
        profile_evidence,
        artifacts,
        policy=profile_consumption_policy,
    )
    profile_adjustment = (
        float(profile_consumption.get("rank_adjustment") or 0.0)
        if profile_consumption.get("enabled")
        else 0.0
    )
    total = _bounded(base_total + profile_adjustment + bundle_prior_adjustment)
    result = {
        "context_similarity": round(context_term, 6),
        "case_outcome_pass_rate": round(case_pass_rate, 6),
        "strategy_evidence": evidence,
        "terms": {key: round(value, 6) for key, value in terms.items()},
        "weights": {key: round(value, 6) for key, value in weights.items()},
        "base_total": round(base_total, 6),
        "profile_rank_adjustment": round(profile_adjustment, 6),
        "bundle_participation_rank_adjustment": round(bundle_prior_adjustment, 6),
        "bundle_participation_policy": (
            "weak_centered_rank_only_v1:max_abs_0.015;gate_ineligible"
            if variant == "no_outcome_counts_bundle_participation_prior"
            else "off"
        ),
        "total": round(total, 6),
        "policy": f"compiled_strategy_knowledge_rank_v1:{variant}",
        "strategy_evidence_selection_policy": (
            structural_selection_policy
            if structural_selection
            else "outcome_calibrated_v1"
        ),
        "candidate_action_admission_policy": (
            _STRUCTURAL_ACTION_ADMISSION_POLICY
            if structural_selection
            else "all_case_actions_v1"
        ),
    }
    if structural_selection:
        structural_match = (
            best.get("structural_match")
            if isinstance(best.get("structural_match"), dict)
            else {}
        )
        read_policy = _STRUCTURAL_READ_POLICY[structural_selection_policy]
        enabled_tie_breaks = []
        if read_policy["include_component_relations"]:
            enabled_tie_breaks.append("component_of_bundle_count")
        if read_policy["include_source_support"]:
            enabled_tie_breaks.append("source_trace_count")
        enabled_tie_breaks.append("case_id")
        tie_break_policy = (
            "equal_rank_memory_id_v1"
            if enabled_tie_breaks == ["case_id"]
            else "equal_rank_" + "_then_".join(enabled_tie_breaks) + "_v1"
        )
        result["structural_relation_tie_break"] = {
            "policy": tie_break_policy,
            "component_of_bundle_count": int(
                structural_match.get("component_of_bundle_count") or 0
            ),
            "source_trace_count": int(
                structural_match.get("source_trace_count") or 0
            ),
        }
    if profile_consumption.get("enabled"):
        result["memory_evidence_profile_consumption"] = profile_consumption
    return result


def retrieve_cases(memories: list[dict[str, Any]], trace: dict[str, Any], *, limit: int = 5) -> list[dict[str, Any]]:
    query = _case_query(trace)
    retrieval_key = (
        id(memories),
        limit,
        str(query.get("issue_type") or "").strip().lower(),
        str(query.get("vendor") or "").strip().lower(),
        str(query.get("system") or "").strip().lower(),
        str(query.get("region") or "").strip().lower(),
        str(query.get("band") or "").strip().lower(),
    )
    cached = _CASE_RETRIEVAL_CACHE.get(retrieval_key)
    if cached is not None and cached.get("source_ref") is memories:
        return cached["cases"]
    index = _case_index(memories)
    cases = index["cases"]
    fields = [
        ("issue_type", "issue_types", 8.0),
        ("vendor", "vendors", 4.0),
        ("system", "systems", 3.0),
        ("region", "regions", 2.0),
        ("band", "bands", 1.0),
    ]
    scores: dict[int, float] = defaultdict(float)
    for query_key, app_key, weight in fields:
        query_value = str(query.get(query_key) or "").strip().lower()
        if not query_value:
            continue
        for idx in index["by_field"].get(app_key, {}).get(query_value, []):
            scores[idx] += weight
    key = lambda idx: (-scores[idx], index["ids"][idx])
    ranked = nsmallest(limit, scores, key=key) if len(scores) > limit else sorted(scores, key=key)
    if len(ranked) < limit:
        seen = set(ranked)
        for idx in index["zero_order"]:
            if idx not in seen:
                ranked.append(idx)
                if len(ranked) >= limit:
                    break
    result = [cases[idx] for idx in ranked[:limit]]
    _CASE_RETRIEVAL_CACHE[retrieval_key] = {"source_ref": memories, "cases": result}
    return result


def _case_index(memories: list[dict[str, Any]]) -> dict[str, Any]:
    cache_key = id(memories)
    cached = _CASE_INDEX_CACHE.get(cache_key)
    if cached is not None and cached.get("source_ref") is memories:
        return cached
    cases = [memory for memory in memories if memory.get("memory_type") == "case_memory"]
    ids = [str(memory.get("memory_id") or "") for memory in cases]
    by_field: dict[str, dict[str, list[int]]] = {
        key: defaultdict(list)
        for key in ("issue_types", "vendors", "systems", "regions", "bands")
    }
    for idx, memory in enumerate(cases):
        app = memory.get("applicability") if isinstance(memory.get("applicability"), dict) else {}
        for app_key in by_field:
            for value in _values(app.get(app_key)):
                by_field[app_key][value].append(idx)
    index = {
        "source_ref": memories,
        "cases": cases,
        "ids": ids,
        "by_field": by_field,
        "zero_order": sorted(range(len(cases)), key=lambda idx: ids[idx]),
    }
    _CASE_INDEX_CACHE.clear()
    _CASE_RETRIEVAL_CACHE.clear()
    _CASE_INDEX_CACHE[cache_key] = index
    return index


def _direction(change: str) -> tuple[str, str]:
    if "→" not in change:
        return "", ""
    before, after = (part.strip() for part in change.split("→", 1))
    try:
        delta = float(after) - float(before)
    except (TypeError, ValueError):
        if before == after:
            return "keep", ""
        return "switch", f"{before}->{after}"
    if delta > 0:
        return "increase", f"+{delta:g}"
    if delta < 0:
        return "decrease", f"{delta:g}"
    return "keep", "0"


def _case_actions(
    memory: dict[str, Any],
    *,
    action_admission_policy: str = "all_case_actions_v1",
) -> list[dict[str, Any]]:
    content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
    actions = content.get("actions") if isinstance(content.get("actions"), list) else []
    app = memory.get("applicability") if isinstance(memory.get("applicability"), dict) else {}
    scheme_groups = app.get("scheme_groups") if isinstance(app.get("scheme_groups"), list) else []
    out: list[dict[str, Any]] = []
    for action in actions:
        if not isinstance(action, dict):
            continue
        if (
            action_admission_policy == _STRUCTURAL_ACTION_ADMISSION_POLICY
            and not _structural_candidate_action_admissible(action)
        ):
            continue
        derived_direction, derived_delta = _direction(str(action.get("change") or ""))
        direction = str(action.get("direction") or derived_direction)
        delta = str(action.get("suggested_delta") or action.get("delta_bucket") or action.get("adjustment_rule") or derived_delta)
        value_type = str(
            action.get("value_type")
            or ("numeric" if direction in {"increase", "decrease", "keep"} else "enum")
        )
        action_contract_source = str(action.get("action_contract_source") or "case_memory_action")
        companion_parameters = (
            action.get("plan_companion_parameters")
            if isinstance(action.get("plan_companion_parameters"), list)
            else plan_companion_parameters_from_action(action, source=action_contract_source)
        )
        out.append({
            "source_action_id": str(action.get("action_id") or ""),
            "exec_state": str(action.get("exec_state") or ""),
            "maximum_attribution_scope": str(
                action.get("maximum_attribution_scope") or ""
            ),
            "outcome_role": str(action.get("outcome_role") or ""),
            "result_evidence_eligible": bool(
                action.get("result_evidence_eligible", False)
            ),
            "scheme_group": str(action.get("scheme_group") or (scheme_groups[0] if scheme_groups else "")),
            "scheme_id": str(action.get("scheme_id") or ""),
            "parameter_semantic_id": str(action.get("parameter_semantic_id") or ""),
            "param_object": str(action.get("param_object") or ""),
            "site_param_object": str(action.get("site_param_object") or ""),
            "param_en_name": str(action.get("param_en_name") or ""),
            "site_param_en_name": str(action.get("site_param_en_name") or ""),
            "param_cn_name": str(action.get("param_cn_name") or ""),
            "parameter_group": str(action.get("parameter_group") or ""),
            "final_ratio": str(action.get("final_ratio") or ""),
            "value_type": value_type,
            "direction": direction,
            "suggested_delta": delta,
            "delta_bucket": str(action.get("delta_bucket") or delta),
            "value_pattern_id": str(action.get("value_pattern_id") or ""),
            "canonical_action_id": str(action.get("canonical_action_id") or ""),
            "action_ontology_status": str(action.get("action_ontology_status") or ""),
            "action_ontology_policy": str(action.get("action_ontology_policy") or ""),
            "action_ontology": action.get("action_ontology") if isinstance(action.get("action_ontology"), dict) else {},
            "value_rule": str(action.get("value_rule") or ""),
            "scheme_desc": str(action.get("scheme_desc") or ""),
            "before_value": str(action.get("before_value") or ""),
            "after_value": str(action.get("after_value") or ""),
            "change": str(action.get("change") or ""),
            "operation_summary": str(action.get("operation_summary") or ""),
            "plan_companion_parameters": companion_parameters,
            "plan_companion_parameter_distribution": action.get("plan_companion_parameter_distribution") or [],
            "action_contract_version": "action_contract.v2.companion_parameters",
            "action_contract_source": action_contract_source,
        })
    return out


def _case_action(
