def _format_action_number(value: float | None) -> str:
    if value is None:
        return ""
    rounded = round(value, 6)
    if rounded == int(rounded):
        return str(int(rounded))
    return f"{rounded:g}"


def _action_number(value: Any) -> float | None:
    try:
        if value is None:
            return None
        text = str(value).strip()
        if not text:
            return None
        return float(text)
    except (TypeError, ValueError):
        return None


def _snapshot_lookup_token(value: Any) -> str:
    return str(value or "").strip().lower()


def _action_snapshot_lookup_keys(action: dict[str, Any]) -> list[str]:
    keys: list[str] = []
    for value in (
        action.get("parameter_semantic_id"),
        action.get("param_en_name"),
        action.get("site_param_en_name"),
        action.get("param_cn_name"),
        action.get("param_object"),
        action.get("site_param_object"),
    ):
        text = str(value or "").strip()
        if text and text not in keys:
            keys.append(text)
        token = _snapshot_lookup_token(text)
        if token and token not in keys:
            keys.append(token)
    return keys


def _snapshot_parameter_lookup(
    trace: dict[str, Any],
    action: dict[str, Any],
) -> tuple[dict[str, Any] | None, str]:
    snapshots = (
        trace.get("pre_decision_parameter_snapshot")
        or trace.get("parameter_snapshot")
        or trace.get("current_parameter_snapshot")
    )
    if not isinstance(snapshots, dict):
        return None, "unavailable"

    scope = str(snapshots.get("coverage_scope") or "")
    parameters = snapshots.get("parameters")
    if not isinstance(parameters, dict):
        return None, "ambiguous"

    if scope == "candidate_parameter_set":
        declared = snapshots.get("candidate_parameter_semantic_ids")
        if isinstance(declared, list):
            declared_ids = {str(item) for item in declared if item}
            if not declared_ids or not declared_ids.issubset(set(parameters)):
                return None, "ambiguous"

    allowed_scopes = {
        "candidate_parameter_set",
        "train_only_time_prior_cell_parameter_state",
    }
    if scope not in allowed_scopes:
        return None, "ambiguous"

    for key in _action_snapshot_lookup_keys(action):
        snapshot = parameters.get(key)
        if isinstance(snapshot, dict):
            return {
                **snapshot,
                "snapshot_policy": snapshot.get("snapshot_policy") or snapshots.get("snapshot_policy") or scope,
                "coverage_scope": scope,
                "matched_parameter_key": key,
            }, "exact" if key == str(action.get("parameter_semantic_id") or "") else "alias"
    return None, "missing_predicted_parameter"


def _action_signature_for_bundle(action: dict[str, Any]) -> dict[str, Any]:
    before = str(action.get("before_value") or "").strip()
    after = str(action.get("after_value") or "").strip()
    change = str(action.get("change") or "").strip() or (f"{before}→{after}" if before or after else "")
    return {
        "source_action_id": str(action.get("source_action_id") or ""),
        "scheme_id": str(action.get("scheme_id") or ""),
        "parameter_semantic_id": str(action.get("parameter_semantic_id") or ""),
        "param_cn_name": str(action.get("param_cn_name") or ""),
        "direction": str(action.get("direction") or ""),
        "change": change,
        "companion_key": companion_signature(action.get("plan_companion_parameters")),
    }


def _case_source_plan_bundle_evidence(
    case: dict[str, Any],
    selected_action: dict[str, Any],
) -> dict[str, Any]:
    actions = _case_actions(case)
    selected_signature = _action_signature_for_bundle(selected_action)
    selected_key = json.dumps(selected_signature, sort_keys=True, ensure_ascii=False)
    siblings = []
    for action in actions:
        signature = _action_signature_for_bundle(action)
        if json.dumps(signature, sort_keys=True, ensure_ascii=False) != selected_key:
            siblings.append(signature)
    return {
        "policy": "source_plan_sibling_action_bundle_evidence_v1",
        "source_case_memory_id": str(case.get("memory_id") or ""),
        "source_plan_action_count": len(actions),
        "has_sibling_actions": bool(siblings),
        "selected_action_signature": selected_signature,
        "sibling_actions": siblings[:8],
        "sibling_action_count": len(siblings),
    }


def _case_current_value_selected_action(
    action: dict[str, Any],
    trace: dict[str, Any],
    *,
    value_selection_policy: str = "case_current_snapshot_rebase",
) -> dict[str, Any]:
    """Rebase a retrieved case action onto a clean target current snapshot.

    This never reads ``trace.actions``. It only uses the explicit
    ``pre_decision_parameter_snapshot`` candidate-parameter contract. When that
    contract is absent or ambiguous, the action is left unchanged and the
    diagnostic explains why.
    """
    out = dict(action)
    snapshot, snapshot_match = _snapshot_parameter_lookup(trace, out)
    source_before = str(out.get("before_value") or "")
    source_after = str(out.get("after_value") or "")
    selection = {
        "selected": False,
        "selection_policy": value_selection_policy,
        "reason": "current_snapshot_unavailable",
        "current_parameter_snapshot_used": False,
        "current_value_source": "unavailable",
        "current_value_confidence": "unavailable",
        "target_value_confidence": "unavailable",
        "parameter_snapshot_match": snapshot_match,
        "source_before_value": source_before,
        "source_after_value": source_after,
        "rebase_applied": False,
    }
    if not isinstance(snapshot, dict):
        out["value_selection"] = selection
        return out

    current = None
    for key in ("current_value", "before_value", "value"):
        current = _action_number(snapshot.get(key))
        if current is not None:
            break
    selection.update({
        "current_parameter_snapshot_used": True,
        "current_value_source": snapshot.get("current_value_source") or "observed_snapshot",
        "current_value_confidence": snapshot.get("current_value_confidence") or "observed",
        "current_value": _format_action_number(current),
    })
    if current is None:
        selection["reason"] = "current_snapshot_value_not_numeric"
        out["value_selection"] = selection
        return out

    delta = _action_number(out.get("suggested_delta") or out.get("delta_bucket"))
    value_type = str(out.get("value_type") or "").lower()
    if delta is None or value_type in {"enum", "switch", "enum_switch"}:
        selection["reason"] = "non_numeric_or_missing_delta_not_rebased"
        out["value_selection"] = selection
        return out

    target = current + delta
    parameter_range = snapshot.get("parameter_range") if isinstance(snapshot.get("parameter_range"), dict) else {}
    lo = _action_number(parameter_range.get("min"))
    hi = _action_number(parameter_range.get("max"))
    if lo is not None and hi is not None:
        target = max(min(target, max(lo, hi)), min(lo, hi))

    before_text = _format_action_number(current)
    target_text = _format_action_number(target)
    out["before_value"] = before_text
    out["after_value"] = target_text
    out["target_value"] = target_text
    out["change"] = f"{before_text}→{target_text}"
    selection.update({
        "selected": True,
        "reason": "rebased_case_delta_on_target_current_snapshot",
        "suggested_delta": out.get("suggested_delta") or out.get("delta_bucket") or "",
        "target_value": target_text,
        "target_value_confidence": snapshot.get("target_value_confidence") or "observed",
        "rebase_applied": True,
    })
    out["value_selection"] = selection
    return out


def _raw_trace_case_action(action: dict[str, Any]) -> dict[str, Any]:
    before = str(action.get("before_value") or "").strip()
    after = str(action.get("after_value") or "").strip()
    raw_change = str(action.get("change") or action.get("verbal_desc") or "").strip()
    change = f"{before}→{after}" if before or after else raw_change
    derived_direction, derived_delta = _direction(change)
    adjustment_rule = str(action.get("adjustment_rule") or "").strip()
    return {
        "source_action_id": str(action.get("action_id") or ""),
        "scheme_group": str(action.get("scheme_group") or ""),
        "scheme_id": str(action.get("scheme_id") or ""),
        "parameter_semantic_id": str(action.get("parameter_semantic_id") or ""),
        "param_object": str(action.get("param_object") or ""),
        "site_param_object": str(action.get("site_param_object") or ""),
        "param_en_name": str(action.get("param_en_name") or ""),
        "site_param_en_name": str(action.get("site_param_en_name") or ""),
        "param_cn_name": str(action.get("param_cn_name") or ""),
        "parameter_group": str(action.get("parameter_group") or ""),
        "final_ratio": str(action.get("final_ratio") or ""),
        "value_type": "numeric" if derived_direction in {"increase", "decrease", "keep"} else "enum",
        "direction": derived_direction,
        "suggested_delta": adjustment_rule or derived_delta,
        "delta_bucket": adjustment_rule or derived_delta,
        "value_pattern_id": "",
        "canonical_action_id": "",
        "action_ontology_status": "raw_trace",
        "action_ontology_policy": "traditional_case_retrieval_no_echo_compile",
        "action_ontology": {},
        "value_rule": str(action.get("value_rule") or ""),
        "scheme_desc": str(action.get("scheme_desc") or ""),
        "before_value": before,
        "after_value": after,
        "change": change,
        "operation_summary": str(action.get("operation_summary") or ""),
        "plan_companion_parameters": plan_companion_parameters_from_action(action, source="raw_train_trace_action"),
        "plan_companion_parameter_distribution": [],
        "action_contract_version": "action_contract.v2.companion_parameters",
        "action_contract_source": "raw_train_trace_action",
    }


def _traditional_case_memory_from_trace(trace: dict[str, Any]) -> dict[str, Any] | None:
    actions = trace.get("actions") if isinstance(trace.get("actions"), list) else []
    action_rows = [
        _raw_trace_case_action(action)
        for action in actions
        if isinstance(action, dict) and (action.get("scheme_id") or action.get("param_cn_name"))
    ]
    if not action_rows:
        return None
    ticket = trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}
    trace_id = str(trace.get("trace_id") or ticket.get("id") or "")
    return {
        "memory_id": f"raw_case::{trace_id}",
        "memory_type": "case_memory",
        "case_source": "raw_train_trace_with_actions",
        "trace_ids": [trace_id] if trace_id else [],
        "applicability": {
            "issue_types": [ticket.get("primary_issue_type")] if ticket.get("primary_issue_type") else [],
            "vendors": [ticket.get("vendor")] if ticket.get("vendor") else [],
            "systems": [ticket.get("system")] if ticket.get("system") else [],
            "regions": [ticket.get("region")] if ticket.get("region") else [],
            "bands": [ticket.get("band")] if ticket.get("band") else [],
            "indoor_outdoor": [ticket.get("is_indoor")] if ticket.get("is_indoor") else [],
            "scheme_groups": sorted({row.get("scheme_group") for row in action_rows if row.get("scheme_group")}),
            "scheme_ids": sorted({row.get("scheme_id") for row in action_rows if row.get("scheme_id")}),
        },
        "content": {
            "ticket_id": ticket.get("id"),
            "ticket_summary": " / ".join(
                str(item)
                for item in (ticket.get("primary_issue_type"), ticket.get("region"), ticket.get("cell_name"))
                if item
            ),
            "safe_retrieval_text": _safe_ticket_retrieval_text(ticket),
            "actions": action_rows,
            "source_contract": (
                "raw train trace actions only; no long_eval filtering, no ECHO-Mem memory package fields"
            ),
        },
    }


def load_traditional_case_memories(path: Path | None = None) -> list[dict[str, Any]]:
    """Build a traditional case index from raw train traces, not ECHO-Mem memory objects."""
    source = path or P.TRAIN_TRACE_RECORDS_JSONL
    stat = source.stat()
    key = (str(source.resolve()), stat.st_mtime_ns, stat.st_size)
    cached = _TRADITIONAL_CASE_MEMORY_CACHE.get(key)
    if cached is not None:
        return cached
    cases = [
        case
        for trace in cio.read_jsonl(source)
        if (case := _traditional_case_memory_from_trace(trace))
    ]
    _TRADITIONAL_CASE_MEMORY_CACHE.clear()
    _TRADITIONAL_CASE_MEMORY_CACHE[key] = cases
    return cases


def traditional_case_retrieval_decide(
    trace: dict[str, Any],
    cases: list[dict[str, Any]] | None = None,
    *,
    limit: int = 5,
) -> dict[str, Any]:
    case_pool = cases if cases is not None else load_traditional_case_memories()
    retrieved = retrieve_cases(case_pool, trace, limit=limit)
    action = _case_action(retrieved[0]) if retrieved else {}
    top_score = _case_score(retrieved[0], _case_query(trace)) if retrieved else 0.0
    decision = _base_decision(
        trace,
        "case_retrieval",
        retrieved,
        action,
        reason=(
            "Top-1 traditional raw train case action; no long-eval filtering, "
            "ECHO-Mem memory package, outcome calibration, profiles, or gate are used."
        ),
    )
    decision["pipeline"] = {
        "recall": "traditional_raw_trace_case_retrieval_top1",
        "rank": "none",
        "gate": "none",
    }
    decision["selected_score_breakdown"] = {
        "policy": "traditional_structured_case_similarity",
        "raw_similarity_score": round(top_score, 6),
        "max_similarity_score": TRADITIONAL_CASE_MAX_SCORE,
        "normalized_similarity": round(top_score / TRADITIONAL_CASE_MAX_SCORE, 6),
        "abstain_threshold": None,
        "abstained": False,
    }
    decision["baseline_contract"] = {
        "case_source": "data/staged/splits/train_trace_records.jsonl",
        "case_filter": "raw train traces with at least one historical action; long_eval is not read",
        "forbidden_sources": [
            "memory_package",
            "case_memory",
            "strategy_memory",
            "counter_evidence",
            "support_profile",
            "failcohort_gate",
        ],
    }
    return decision


def _lexical_basic_tokens(text: str) -> list[str]:
    tokens: list[str] = []
    for match in re.findall(r"[A-Za-z0-9_]+|[\u4e00-\u9fff]+", text.lower()):
        if not match:
            continue
        tokens.append(match)
        if re.fullmatch(r"[\u4e00-\u9fff]+", match):
            for n in (2, 3):
                if len(match) >= n:
                    tokens.extend(match[i : i + n] for i in range(0, len(match) - n + 1))
    return tokens


def _lexical_field_tokens(prefix: str, values: Any) -> list[str]:
    out: list[str] = []
    for value in _values(values):
        out.append(f"{prefix}:{value}")
    return out


def _lexical_case_tokens(memory: dict[str, Any]) -> list[str]:
    app = memory.get("applicability") if isinstance(memory.get("applicability"), dict) else {}
    content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
    tokens = []
    tokens.extend(_lexical_field_tokens("issue", app.get("issue_types")))
    tokens.extend(_lexical_field_tokens("vendor", app.get("vendors")))
    tokens.extend(_lexical_field_tokens("system", app.get("systems")))
    tokens.extend(_lexical_field_tokens("region", app.get("regions")))
    tokens.extend(_lexical_field_tokens("band", app.get("bands")))
    tokens.extend(_lexical_basic_tokens(_text_parts(content.get("ticket_summary"), content.get("safe_retrieval_text"))))
    return tokens


def _lexical_query_tokens(trace: dict[str, Any]) -> list[str]:
    query = _case_query(trace)
    ticket = trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}
    tokens = []
    tokens.extend(_lexical_field_tokens("issue", query.get("issue_type")))
    tokens.extend(_lexical_field_tokens("vendor", query.get("vendor")))
    tokens.extend(_lexical_field_tokens("system", query.get("system")))
    tokens.extend(_lexical_field_tokens("region", query.get("region")))
    tokens.extend(_lexical_field_tokens("band", query.get("band")))
    tokens.extend(_lexical_basic_tokens(_safe_ticket_retrieval_text(ticket)))
    return tokens


def _traditional_lexical_case_index(cases: list[dict[str, Any]]) -> dict[str, Any]:
    cache_key = id(cases)
    cached = _TRADITIONAL_LEXICAL_CASE_INDEX_CACHE.get(cache_key)
    if cached is not None and cached.get("source_ref") is cases:
        return cached
    postings: dict[str, list[tuple[int, int]]] = defaultdict(list)
    doc_lengths: list[int] = []
    term_counts: list[Counter[str]] = []
    memory_id_to_index: dict[str, int] = {}
    for idx, case in enumerate(cases):
        counts = Counter(_lexical_case_tokens(case))
        term_counts.append(counts)
        doc_lengths.append(sum(counts.values()))
        memory_id = str(case.get("memory_id") or "")
        if memory_id:
            memory_id_to_index[memory_id] = idx
        for token, count in counts.items():
            postings[token].append((idx, int(count)))
    index = {
        "source_ref": cases,
        "postings": dict(postings),
        "term_counts": term_counts,
        "memory_id_to_index": memory_id_to_index,
        "doc_freq": {token: len(rows) for token, rows in postings.items()},
        "doc_lengths": doc_lengths,
        "avg_doc_length": (sum(doc_lengths) / len(doc_lengths)) if doc_lengths else 1.0,
        "doc_count": len(cases),
    }
    _TRADITIONAL_LEXICAL_CASE_INDEX_CACHE.clear()
    _TRADITIONAL_LEXICAL_CASE_INDEX_CACHE[cache_key] = index
    return index


def retrieve_cases_bm25_tfidf(
    cases: list[dict[str, Any]],
    trace: dict[str, Any],
    *,
    limit: int = 5,
) -> list[dict[str, Any]]:
    """Retrieve raw train cases with a leakage-safe BM25/TF-IDF lexical index."""
    if not cases:
        return []
    index = _traditional_lexical_case_index(cases)
    query_counts = Counter(_lexical_query_tokens(trace))
    if not query_counts:
        return []
    n_docs = max(1, int(index["doc_count"]))
    avgdl = float(index["avg_doc_length"] or 1.0)
    doc_lengths = index["doc_lengths"]
    postings = index["postings"]
    doc_freq = index["doc_freq"]
    k1 = 1.2
    b = 0.75
    candidate_cases = retrieve_cases(cases, trace, limit=max(limit, BM25_STRUCTURED_CANDIDATE_LIMIT))
    memory_id_to_index = index["memory_id_to_index"]
    candidate_indices = [
        memory_id_to_index[str(case.get("memory_id") or "")]
        for case in candidate_cases
        if str(case.get("memory_id") or "") in memory_id_to_index
    ]
    if not candidate_indices:
        return []
    term_counts = index["term_counts"]
    scores: dict[int, float] = defaultdict(float)
    max_postings = max(5000, int(n_docs * BM25_MAX_POSTINGS_FRACTION))
    usable_terms: list[tuple[str, int, int]] = []
    for token, qtf in query_counts.items():
        rows = postings.get(token)
        if not rows:
            continue
        df = int(doc_freq.get(token) or len(rows))
        if df > max_postings:
            continue
        usable_terms.append((token, int(qtf), df))
    usable_terms.sort(key=lambda item: (item[2], item[0]))
    selected_terms = usable_terms[:BM25_MAX_QUERY_TERMS]
    for token, qtf, df in selected_terms:
        idf = math.log(1.0 + ((n_docs - df + 0.5) / (df + 0.5)))
        query_weight = 1.0 + math.log(float(qtf)) if qtf > 1 else 1.0
        for idx in candidate_indices:
            tf = int(term_counts[idx].get(token) or 0)
            if tf <= 0:
                continue
            dl = float(doc_lengths[idx] or 1)
            denom = tf + k1 * (1.0 - b + b * (dl / avgdl))
            scores[idx] += idf * ((tf * (k1 + 1.0)) / denom) * query_weight
    if not scores:
        return [dict(case, _lexical_retrieval_score=0.0) for case in candidate_cases[:limit]]
    ranked = sorted(scores.items(), key=lambda item: (-item[1], -_case_score(cases[item[0]], _case_query(trace)), item[0]))
    out: list[dict[str, Any]] = []
    for idx, score in ranked[:limit]:
        case = dict(cases[idx])
        case["_lexical_retrieval_score"] = round(float(score), 6)
        out.append(case)
    return out


def traditional_case_retrieval_bm25_tfidf_decide(
    trace: dict[str, Any],
    cases: list[dict[str, Any]] | None = None,
    *,
    limit: int = 5,
) -> dict[str, Any]:
    case_pool = cases if cases is not None else load_traditional_case_memories()
    retrieved = retrieve_cases_bm25_tfidf(case_pool, trace, limit=limit)
    action = _case_action(retrieved[0]) if retrieved else {}
    top_score = float((retrieved[0] if retrieved else {}).get("_lexical_retrieval_score") or 0.0)
    decision = _base_decision(
        trace,
        "case_retrieval_bm25_tfidf",
        retrieved,
        action,
        reason=(
            "Top-1 raw train case selected by BM25/TF-IDF over recommendation-time-visible ticket context; "
            "no long-eval filtering, ECHO-Mem memory package, outcome calibration, profiles, or gate are used."
        ),
    )
    decision["pipeline"] = {
        "recall": "raw_trace_bm25_tfidf_case_retrieval_top1",
        "rank": "bm25_tfidf_lexical_similarity",
        "gate": "none",
    }
    decision["supporting_knowledge"]["candidate_scores"] = [
        {
            "memory_id": case.get("memory_id"),
            "memory_type": "case_memory",
            "rank_score": float(case.get("_lexical_retrieval_score") or 0.0),
            "credibility_mode": "not_used",
        }
        for case in retrieved
    ]
    decision["selected_score_breakdown"] = {
        "policy": "traditional_bm25_tfidf_case_retrieval",
        "bm25_tfidf_score": round(top_score, 6),
        "abstained": False,
    }
    decision["baseline_contract"] = {
        "case_source": "data/staged/splits/train_trace_records.jsonl",
        "case_filter": "raw train traces with at least one historical action; long_eval is not read",
        "retrieval_fields": "recommendation-time-visible ticket context only",
        "forbidden_sources": [
            "memory_package",
            "case_memory",
            "strategy_memory",
            "counter_evidence",
            "support_profile",
            "failcohort_gate",
            "long_eval",
            "gold",
            "holdout_actions",
        ],
    }
    return decision


def traditional_case_retrieval_similarity_abstention_decide(
    trace: dict[str, Any],
    cases: list[dict[str, Any]] | None = None,
    *,
    limit: int = 5,
    threshold: float = TRADITIONAL_CASE_ABSTAIN_THRESHOLD,
) -> dict[str, Any]:
    case_pool = cases if cases is not None else load_traditional_case_memories()
    retrieved = retrieve_cases(case_pool, trace, limit=limit)
    action = _case_action(retrieved[0]) if retrieved else {}
    top_score = _case_score(retrieved[0], _case_query(trace)) if retrieved else 0.0
    abstained = bool((not retrieved) or top_score < threshold)
    decision = _base_decision(
        trace,
        "case_retrieval_similarity_abstention",
        retrieved,
        action,
        reason=(
            "Traditional raw case retrieval with similarity abstention; "
            "low structured retrieval confidence routes to manual review without ECHO-Mem evidence."
        ),
        needs_review=abstained,
    )
    decision["pipeline"] = {
        "recall": "traditional_raw_trace_case_retrieval_top1",
        "rank": "retrieval_similarity_threshold_abstention",
        "gate": "manual_fallback_on_low_similarity",
    }
    decision["gate_diagnostics"] = {
        "gate_policy": "traditional_similarity_abstention_v1",
        "gate_reason": "low_similarity_abstention" if abstained else "similarity_confident_auto",
        "matched_veto_ids": [],
        "similarity_score": round(top_score, 6),
        "similarity_threshold": threshold,
    }
    decision["risk_level"] = "medium" if abstained else "low"
    decision["needs_human_review"] = abstained
    decision["selected_score_breakdown"] = {
        "policy": "traditional_structured_case_similarity_abstention",
        "raw_similarity_score": round(top_score, 6),
        "max_similarity_score": TRADITIONAL_CASE_MAX_SCORE,
        "normalized_similarity": round(top_score / TRADITIONAL_CASE_MAX_SCORE, 6),
        "abstain_threshold": threshold,
        "abstained": abstained,
    }
    decision["baseline_contract"] = {
        "case_source": "data/staged/splits/train_trace_records.jsonl",
        "case_filter": "raw train traces with at least one historical action; long_eval is not read",
        "abstention_policy": f"manual fallback if top1 structured similarity < {threshold:g}",
        "forbidden_sources": [
            "memory_package",
            "case_memory",
            "strategy_memory",
            "counter_evidence",
            "support_profile",
            "failcohort_gate",
            "action_ontology",
            "memory_state",
            "bayesian_lcb",
        ],
    }
    return decision


def safe_decision_context(trace: dict[str, Any]) -> dict[str, Any]:
    ticket = trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}
    return {
        "trace_id": trace.get("trace_id"),
        "issue_type": ticket.get("primary_issue_type"),
        "vendor": ticket.get("vendor"),
        "system": ticket.get("system"),
        "region": ticket.get("region"),
        "band": ticket.get("band"),
        "is_indoor": ticket.get("is_indoor"),
    }


def safe_case_document(memory: dict[str, Any]) -> dict[str, Any]:
    app = memory.get("applicability") if isinstance(memory.get("applicability"), dict) else {}
    content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
    actions = content.get("actions") if isinstance(content.get("actions"), list) else []
    return {
        "case_id": memory.get("memory_id"),
        "issue_types": app.get("issue_types") or [],
        "vendors": app.get("vendors") or [],
        "systems": app.get("systems") or [],
        "regions": app.get("regions") or [],
        "bands": app.get("bands") or [],
        "scheme_groups": app.get("scheme_groups") or [],
        "actions": [
            {
                "scheme_id": action.get("scheme_id"),
                "param_cn_name": action.get("param_cn_name"),
            }
            for action in actions
            if isinstance(action, dict)
        ],
    }


def _decision_id(trace: dict[str, Any], method_id: str) -> str:
    payload = f"{method_id}|{trace.get('trace_id') or ''}"
    return "baseline_" + hashlib.sha256(payload.encode("utf-8")).hexdigest()[:12]


def _base_decision(
    trace: dict[str, Any],
    method_id: str,
    cases: list[dict[str, Any]],
    recommended_action: dict[str, Any],
    *,
    reason: str,
    needs_review: bool = False,
) -> dict[str, Any]:
    return {
        "decision_id": _decision_id(trace, method_id),
        "input_trace_id": trace.get("trace_id"),
        "query": safe_decision_context(trace),
        "recommended_action": recommended_action,
        "supporting_knowledge": {
            "case_memory_ids": [case.get("memory_id") for case in cases if case.get("memory_id")],
            "strategy_memory_ids": [],
            "playbook_memory_ids": [],
            "episode_pairs": [],
            "veto_memory_ids": [],
            "candidate_scores": [
                {
                    "memory_id": case.get("memory_id"),
                    "memory_type": "case_memory",
                    "rank_score": _case_score(case, _case_query(trace)),
                    "credibility_mode": "not_used",
                }
                for case in cases
            ],
        },
        "veto_hits": [],
        "veto_checked": False,
        "gate_decision": "reject" if not recommended_action else ("require_review" if needs_review else "accept"),
        "gate_diagnostics": {
            "gate_policy": "not_available_in_baseline",
            "gate_reason": (
                "no_recommendation"
                if not recommended_action
                else ("llm_requested_review" if needs_review else "baseline_without_gate")
            ),
            "matched_veto_ids": [],
        },
        "risk_level": "high" if not recommended_action else ("medium" if needs_review else "low"),
        "needs_human_review": needs_review or not bool(recommended_action),
        "decision_reason": reason,
        "produced_by": method_id,
    }


def _veto_candidates_for_trace(trace: dict[str, Any], artifacts: dict[str, Any]) -> list[dict[str, Any]]:
    query = trace_query(trace)
    navigation_map = artifacts.get("navigation_map") if isinstance(artifacts.get("navigation_map"), dict) else {}
    issue = next(
        (
            item for item in navigation_map.get("issues") or []
            if str(item.get("issue_type") or "") == str(query.get("issue_type") or "")
        ),
        None,
    )
    memories_by_id = artifacts.get("memories_by_id")
    if not isinstance(memories_by_id, dict):
        memories_by_id = {
            memory.get("memory_id"): memory
            for memory in artifacts.get("memories") or []
            if memory.get("memory_id")
        }
    return [
        memories_by_id.get(node.get("memory_id") or node.get("id"), node)
        for node in ((issue or {}).get("vetoes") or [])
    ]


def _gate_case_candidate(
    trace: dict[str, Any],
    action: dict[str, Any],
    artifacts: dict[str, Any],
    *,
    gate_config: dict[str, Any] | None,
    confidence: float,
) -> dict[str, Any]:
    query = trace_query(trace)
    veto_candidates = _veto_candidates_for_trace(trace, artifacts)
    family = {"scheme_group": action.get("scheme_group")}
    return apply_veto_gate(
        recommended=action,
        veto_candidates=veto_candidates,
        family=family,
        base_risk_level="low",
        base_needs_review=False,
        recommendation_confidence=confidence,
        gate_config=gate_config,
        query={**query, "veto_issue_routed": bool(veto_candidates)},
    )


def _disabled_gate_for_action(action: dict[str, Any]) -> dict[str, Any]:
    has_action = bool(action)
    return {
        "gate_decision": "accept" if has_action else "reject",
        "gate_policy": "disabled_by_method_variant",
        "gate_reason": "veto_gate_disabled" if has_action else "no_candidate_action",
        "veto_hit": False,
        "veto_background_count": 0,
        "veto_ids": [],
        "risk_level": "low" if has_action else "high",
        "needs_human_review": not has_action,
        "tau_low": None,
        "tau_high": None,
        "recommendation_confidence": None,
        "threshold_band": "gate_disabled",
        "gate_config_version": None,
        "failcohort_hit_score": 0.0,
        "failcohort_matches": [],
        "veto_risk_calibration": {"available": False, "score": None},
        "gray_zone_review": {},
        "hard_veto_eligible": False,
        "strong_action_veto_match": False,
    }


def _branch_score(decision: dict[str, Any]) -> tuple[int, float]:
    score = decision.get("selected_score_breakdown")
    total = 0.0
    if isinstance(score, dict):
        try:
            total = float(score.get("total") or 0.0)
        except (TypeError, ValueError):
            total = 0.0
    usable = 0 if not decision.get("recommended_action") else 1
    return usable, total


def _branch_summary(branch: str, decision: dict[str, Any]) -> dict[str, Any]:
    supporting = decision.get("supporting_knowledge") if isinstance(decision.get("supporting_knowledge"), dict) else {}
    score = decision.get("selected_score_breakdown")
    return {
        "branch": branch,
        "gate_decision": decision.get("gate_decision"),
        "gate_reason": (decision.get("gate_diagnostics") or {}).get("gate_reason") if isinstance(decision.get("gate_diagnostics"), dict) else None,
        "failcohort_hit_score": (decision.get("gate_diagnostics") or {}).get("failcohort_hit_score") if isinstance(decision.get("gate_diagnostics"), dict) else None,
        "recommended_action": decision.get("recommended_action") or {},
        "selected_score_total": (score or {}).get("total") if isinstance(score, dict) else None,
        "case_memory_ids": supporting.get("case_memory_ids") or [],
        "strategy_memory_ids": supporting.get("strategy_memory_ids") or [],
        "playbook_memory_ids": supporting.get("playbook_memory_ids") or [],
        "veto_memory_ids": supporting.get("veto_memory_ids") or [],
    }


def hybrid_recall_echo_rank_gate_decide(
    trace: dict[str, Any],
    memories: list[dict[str, Any]],
    *,
    artifacts: dict[str, Any],
    episode_candidates: list[dict[str, Any]],
    episodes_by_id: dict[str, dict[str, Any]],
    navigation_map: dict[str, Any] | None,
    use_bayesian_credibility: bool,
    ranker_config: dict[str, Any] | None = None,
    gate_config: dict[str, Any] | None = None,
    method_id: str = "pipeline_hybrid_recall_echo_rank_echo_gate",
) -> dict[str, Any]:
    """Select between ECHO strategy/playbook recall and case recall branches.

    The selector is gold-free and gate-decoupled: first choose the stronger
    branch by internal candidate confidence, then apply/report the selected
    branch's gate result.
    """
    echo_decision = shadow_decide(
        trace,
        memories=memories,
        episode_candidates=episode_candidates,
        episodes_by_id=episodes_by_id,
        navigation_map=navigation_map,
        use_bayesian_credibility=use_bayesian_credibility,
        ranker_config=ranker_config,
        gate_config=gate_config,
    )
    case_decision = case_retrieval_echo_rank_gate_decide(
        trace,
        memories,
        artifacts=artifacts,
        gate_config=gate_config,
        method_id="pipeline_case_recall_echo_rank_echo_gate",
    )
    branches = [
        ("echo_strategy_playbook", echo_decision),
        ("case_retrieval", case_decision),
    ]
    selected_branch, selected_decision = max(
        branches,
        key=lambda item: (_branch_score(item[1]), 1 if item[0] == "echo_strategy_playbook" else 0),
    )
    out = dict(selected_decision)
    supporting = dict(out.get("supporting_knowledge") if isinstance(out.get("supporting_knowledge"), dict) else {})
    supporting["hybrid_candidates"] = [
        _branch_summary(branch, decision)
        for branch, decision in branches
    ]
    supporting["selected_hybrid_branch"] = selected_branch
    out["supporting_knowledge"] = supporting
    out["produced_by"] = method_id
    out["decision_id"] = _decision_id(trace, method_id)
    out["decision_reason"] = (
        f"Hybrid recall selected {selected_branch} by internal confidence; gate is applied after branch selection. "
        + str(out.get("decision_reason") or "")
    ).strip()
    out["hybrid_selection"] = {
        "selected_branch": selected_branch,
        "policy": "internal_confidence_then_gate_v2",
        "branches": [
            {
                "branch": branch,
                "usable": _branch_score(decision)[0],
                "internal_confidence": _branch_score(decision)[1],
                "gate_decision_post_selection": decision.get("gate_decision"),
            }
            for branch, decision in branches
        ],
    }
    out["pipeline"] = {
        "recall": "hybrid_case_strategy_recall",
        "evidence": "echo_hybrid_memory_evidence",
        "rank": "echo_hybrid_candidate_rank_v1",
        "gate": "echo_failcohort_gate_v4",
    }
    return out


def case_retrieval_echo_gate_decide(
    trace: dict[str, Any],
    memories: list[dict[str, Any]],
    *,
    artifacts: dict[str, Any],
    gate_config: dict[str, Any] | None = None,
    limit: int = 5,
    method_id: str = "pipeline_case_recall_top1_echo_gate",
) -> dict[str, Any]:
    cases = retrieve_cases(memories, trace, limit=limit)
    action = _case_action(cases[0]) if cases else {}
    rank = _case_echo_rank_score(cases[0], trace) if cases else {"total": 0.0}
    gate = _gate_case_candidate(
        trace,
        action,
        artifacts,
        gate_config=gate_config,
        confidence=float(rank.get("total") or 0.0),
    )
    decision = _base_decision(
        trace,
        method_id,
        cases,
        action,
        reason="Top-1 case-retrieval action with ECHO fail-cohort gate applied.",
        needs_review=bool(gate["needs_human_review"]),
    )
    decision["gate_decision"] = gate["gate_decision"]
    decision["gate_diagnostics"] = {
        "gate_policy": gate["gate_policy"],
        "gate_reason": gate["gate_reason"],
        "veto_hit": gate["veto_hit"],
        "veto_background_count": gate["veto_background_count"],
        "matched_veto_ids": gate["veto_ids"],
        "tau_low": gate.get("tau_low"),
        "tau_high": gate.get("tau_high"),
        "recommendation_confidence": gate.get("recommendation_confidence"),
        "threshold_band": gate.get("threshold_band"),
        "gate_config_version": gate.get("gate_config_version"),
        "failcohort_hit_score": gate.get("failcohort_hit_score", 0.0),
        "diagnostic_failcohort_hit_score": gate.get("diagnostic_failcohort_hit_score"),
        "diagnostic_veto_ids": gate.get("diagnostic_veto_ids") or [],
        "failcohort_matches": gate.get("failcohort_matches") or [],
        "veto_risk_calibration": gate.get("veto_risk_calibration") or {},
        "gray_zone_review": gate.get("gray_zone_review") or {},
        "hard_veto_eligible": gate.get("hard_veto_eligible"),
        "strong_action_veto_match": gate.get("strong_action_veto_match"),
    }
    decision["veto_hits"] = gate["veto_ids"]
    decision["veto_checked"] = True
    decision["risk_level"] = gate["risk_level"]
    decision["needs_human_review"] = gate["needs_human_review"]
    decision["selected_score_breakdown"] = rank
    decision["supporting_knowledge"]["veto_memory_ids"] = gate["veto_ids"]
    decision["produced_by"] = method_id
    decision["pipeline"] = {
        "recall": "case_retrieval_top1",
        "rank": "none",
        "gate": "echo_failcohort_gate_v4",
    }
    return decision


def case_retrieval_echo_rank_gate_decide(
    trace: dict[str, Any],
    memories: list[dict[str, Any]],
    *,
    artifacts: dict[str, Any],
    gate_config: dict[str, Any] | None = None,
    limit: int = 5,
    method_id: str = "pipeline_case_recall_echo_rank_echo_gate",
) -> dict[str, Any]:
    cases = retrieve_cases(memories, trace, limit=limit)
    scored: list[dict[str, Any]] = []
    for case in cases:
        action = _case_action(case)
        rank = _case_echo_rank_score(case, trace)
        gate = _gate_case_candidate(
            trace,
            action,
            artifacts,
            gate_config=gate_config,
            confidence=float(rank.get("total") or 0.0),
        )
        scored.append({
            "case": case,
            "action": action,
            "rank": rank,
            "gate": gate,
            "selection_score": float(rank.get("total") or 0.0),
        })
    scored.sort(
        key=lambda item: (
            item["selection_score"],
            item["rank"]["total"],
            item["gate"].get("gate_decision") in {"accept", "downgrade"},
        ),
        reverse=True,
    )
    best = scored[0] if scored else {"case": {}, "action": {}, "rank": {"total": 0.0}, "gate": _gate_case_candidate(trace, {}, artifacts, gate_config=gate_config, confidence=0.0)}
    ordered_cases = [item["case"] for item in scored]
    decision = _base_decision(
        trace,
        method_id,
        ordered_cases,
        best["action"],
        reason="Case Top-K recalled first, re-ranked by ECHO-style case outcome score, then fail-cohort gate is applied.",
        needs_review=bool(best["gate"]["needs_human_review"]),
    )
    gate = best["gate"]
    decision["gate_decision"] = gate["gate_decision"]
    decision["gate_diagnostics"] = {
        "gate_policy": gate["gate_policy"],
        "gate_reason": gate["gate_reason"],
        "veto_hit": gate["veto_hit"],
        "veto_background_count": gate["veto_background_count"],
        "matched_veto_ids": gate["veto_ids"],
        "tau_low": gate.get("tau_low"),
        "tau_high": gate.get("tau_high"),
        "recommendation_confidence": gate.get("recommendation_confidence"),
        "threshold_band": gate.get("threshold_band"),
        "gate_config_version": gate.get("gate_config_version"),
        "failcohort_hit_score": gate.get("failcohort_hit_score", 0.0),
        "diagnostic_failcohort_hit_score": gate.get("diagnostic_failcohort_hit_score"),
        "diagnostic_veto_ids": gate.get("diagnostic_veto_ids") or [],
        "failcohort_matches": gate.get("failcohort_matches") or [],
        "veto_risk_calibration": gate.get("veto_risk_calibration") or {},
        "gray_zone_review": gate.get("gray_zone_review") or {},
        "hard_veto_eligible": gate.get("hard_veto_eligible"),
        "strong_action_veto_match": gate.get("strong_action_veto_match"),
    }
    decision["veto_hits"] = gate["veto_ids"]
    decision["veto_checked"] = True
    decision["risk_level"] = gate["risk_level"]
    decision["needs_human_review"] = gate["needs_human_review"]
    decision["selected_score_breakdown"] = best["rank"]
    decision["supporting_knowledge"]["veto_memory_ids"] = gate["veto_ids"]
    decision["supporting_knowledge"]["candidate_scores"] = [
        {
            "memory_id": item["case"].get("memory_id"),
            "memory_type": "case_memory",
            "rank_score": item["rank"]["total"],
            "score_breakdown": item["rank"],
            "gate_decision": item["gate"].get("gate_decision"),
            "gate_reason": item["gate"].get("gate_reason"),
            "failcohort_hit_score": item["gate"].get("failcohort_hit_score", 0.0),
            "credibility_mode": "case_outcome_pass_rate",
        }
        for item in scored
    ]
    decision["produced_by"] = method_id
    decision["pipeline"] = {
        "recall": "case_retrieval_topk",
        "rank": "echo_case_outcome_rank_v1",
        "gate": "echo_failcohort_gate_v4",
    }
    return decision


def case_retrieval_compiled_knowledge_gate_decide(
    trace: dict[str, Any],
    memories: list[dict[str, Any]],
    *,
    artifacts: dict[str, Any],
    gate_config: dict[str, Any] | None = None,
    limit: int = 5,
    method_id: str = "pipeline_case_recall_echo_evidence_rank_echo_gate",
    rank_variant: str = "full",
    profile_consumption_policy: str = "off",
    use_action_value_selector: bool = False,
    value_selection_policy: str = "case_current_snapshot_rebase",
    temporal_action_selection_policy: str = "",
    apply_safety_arbitration: bool = True,
) -> dict[str, Any]:
    cases = retrieve_cases(memories, trace, limit=limit)
    structural_selection = rank_variant in _STRUCTURAL_STRATEGY_SELECTION_VARIANTS
    action_admission_policy = (
        _STRUCTURAL_ACTION_ADMISSION_POLICY
        if structural_selection
        else "all_case_actions_v1"
    )
    trace_id = str(trace.get("trace_id") or "")
    selection_record = (artifacts.get("temporal_action_selections_by_trace_id") or {}).get(trace_id) or {}
    selected_contract = (selection_record.get("variants") or {}).get(temporal_action_selection_policy) or {}

    def selected_action_from_case(case: dict[str, Any]) -> dict[str, Any] | None:
        if not selected_contract or str(case.get("memory_id") or "") != str(selected_contract.get("memory_id") or ""):
            return None
        content = case.get("content") if isinstance(case.get("content"), dict) else {}
        for raw in content.get("actions") or []:
            if not isinstance(raw, dict):
                continue
            if (
                structural_selection
                and not _structural_candidate_action_admissible(raw)
            ):
                continue
            parameter = str(raw.get("parameter_semantic_id") or raw.get("param_cn_name") or "")
            if (
                str(raw.get("scheme_id") or "") == str(selected_contract.get("scheme_id") or "")
                and parameter == str(selected_contract.get("parameter_key") or "")
                and str(raw.get("direction") or "") == str(selected_contract.get("direction") or "")
                and str(raw.get("before_value") or "") == str(selected_contract.get("before_value") or "")
                and str(raw.get("after_value") or "") == str(selected_contract.get("after_value") or "")
            ):
                action = dict(raw)
                action["temporal_revalidation_certificate"] = {
                    "policy": temporal_action_selection_policy,
                    "certificate": selected_contract.get("certificate"),
                    "support_rate": selected_contract.get("temporal_support_rate"),
                    "effective_mass": selected_contract.get("temporal_effective_mass"),
                    "source_package_id": selection_record.get("source_package_id"),
                }
                if temporal_action_selection_policy == "recency_exact_revalidated" and use_action_value_selector:
                    preview = _case_current_value_selected_action(
                        action,
                        trace,
                        value_selection_policy=value_selection_policy,
                    )
                    preview_before = str((preview.get("value_selection") or {}).get("current_value") or preview.get("before_value") or "")
                    preview_after = str(preview.get("target_value") or preview.get("after_value") or "")
                    if (
                        preview_before != str(selected_contract.get("before_value") or "")
                        or preview_after != str(selected_contract.get("after_value") or "")
                    ):
                        return None
                return action
        return None
    scored: list[dict[str, Any]] = []
    for case in cases:
        action = selected_action_from_case(case) or _case_action(
            case,
            action_admission_policy=action_admission_policy,
        )
        if structural_selection and not action:
            continue
        source_plan_bundle = _case_source_plan_bundle_evidence(case, action)
        if use_action_value_selector:
            action = _case_current_value_selected_action(
                action,
                trace,
                value_selection_policy=value_selection_policy,
            )
        else:
            action = dict(action)
            action["value_selection"] = {
                "selected": False,
                "selection_policy": "disabled",
                "reason": "case_action_value_selector_disabled",
                "current_parameter_snapshot_used": False,
                "rebase_applied": False,
            }
        action["source_plan_bundle"] = source_plan_bundle
        rank = _compiled_knowledge_rank_score(
            case,
            trace,
            artifacts,
            variant=rank_variant,
            profile_consumption_policy=profile_consumption_policy,
            candidate_action=action,
        )
        if apply_safety_arbitration:
            gate = _gate_case_candidate(
                trace,
                action,
                artifacts,
                gate_config=gate_config,
                confidence=float(rank.get("total") or 0.0),
            )
            gate = _apply_memory_evidence_profile_gate(
                gate,
                rank.get("memory_evidence_profile_consumption") or {},
                policy=profile_consumption_policy,
            )
        else:
            gate = {
                "gate_decision": "accept", "risk_level": "low", "needs_human_review": False,
                "gate_policy": "disabled_table4_selection_block", "gate_reason": "selection_block_no_safety_arbitration",
                "veto_hit": False, "veto_background_count": 0, "veto_ids": [], "failcohort_matches": [],
                "strong_action_veto_match": False, "threshold_band": "disabled",
            }
        scored.append({
            "case": case,
            "action": action,
            "rank": rank,
            "gate": gate,
            "source_plan_bundle": source_plan_bundle,
            "selection_score": float(rank.get("total") or 0.0),
        })
    if rank_variant in _STRUCTURAL_STRATEGY_SELECTION_VARIANTS:
        def structural_case_order(item: dict[str, Any]) -> tuple[float, float, int, int, str]:
            tie_break = item["rank"].get("structural_relation_tie_break") or {}
            return (
                -float(item["selection_score"]),
                -float(item["rank"]["total"]),
                -int(tie_break.get("component_of_bundle_count") or 0),
                -int(tie_break.get("source_trace_count") or 0),
                str(item["case"].get("memory_id") or ""),
            )

        scored.sort(key=structural_case_order)
    else:
        scored.sort(key=lambda item: (item["selection_score"], item["rank"]["total"]), reverse=True)
    if selected_contract:
        matched = [item for item in scored if str(item["case"].get("memory_id") or "") == str(selected_contract.get("memory_id") or "") and (item["action"].get("temporal_revalidation_certificate") or {}).get("policy") == temporal_action_selection_policy]
        if matched:
            chosen = matched[0]
            scored = [chosen, *[item for item in scored if item is not chosen]]
    best = scored[0] if scored else {"case": {}, "action": {}, "rank": {"total": 0.0}, "gate": _gate_case_candidate(trace, {}, artifacts, gate_config=gate_config, confidence=0.0)}
    ordered_cases = [item["case"] for item in scored]
    profile_clause = (
        f"; memory evidence profiles consumed by {profile_consumption_policy}"
        if _profile_consumption_enabled(profile_consumption_policy)
        else ""
    )
    decision = _base_decision(
        trace,
        method_id,
        ordered_cases,
        best["action"],
        reason=f"Case Top-K recall ranked by compiled strategy knowledge evidence ({rank_variant}){profile_clause}; ECHO fail-cohort gate is applied after ranking.",
        needs_review=bool(best["gate"]["needs_human_review"]),
    )
    gate = best["gate"]
    decision["gate_decision"] = gate["gate_decision"]
    decision["gate_diagnostics"] = {
        "gate_policy": gate["gate_policy"],
        "gate_reason": gate["gate_reason"],
        "veto_hit": gate["veto_hit"],
        "veto_background_count": gate["veto_background_count"],
        "matched_veto_ids": gate["veto_ids"],
        "tau_low": gate.get("tau_low"),
        "tau_high": gate.get("tau_high"),
        "recommendation_confidence": gate.get("recommendation_confidence"),
        "threshold_band": gate.get("threshold_band"),
        "gate_config_version": gate.get("gate_config_version"),
        "failcohort_hit_score": gate.get("failcohort_hit_score", 0.0),
        "diagnostic_failcohort_hit_score": gate.get("diagnostic_failcohort_hit_score"),
        "diagnostic_veto_ids": gate.get("diagnostic_veto_ids") or [],
        "failcohort_matches": gate.get("failcohort_matches") or [],
        "veto_risk_calibration": gate.get("veto_risk_calibration") or {},
        "gray_zone_review": gate.get("gray_zone_review") or {},
        "hard_veto_eligible": gate.get("hard_veto_eligible"),
        "strong_action_veto_match": gate.get("strong_action_veto_match"),
        "profile_gate_policy": gate.get("profile_gate_policy"),
        "profile_routing_hit": gate.get("profile_routing_hit"),
        "profile_review_reasons": gate.get("profile_review_reasons") or [],
        "profile_release_reasons": gate.get("profile_release_reasons") or [],
        "memory_evidence_profile_consumption": gate.get("memory_evidence_profile_consumption") or {},
    }
    evidence_ids: list[str] = []
    profile_ids: list[str] = []
    for item in scored:
        for evidence in item["rank"].get("strategy_evidence") or []:
            memory_id = evidence.get("memory_id")
            if memory_id and memory_id not in evidence_ids:
                evidence_ids.append(memory_id)
        profile_consumption = item["rank"].get("memory_evidence_profile_consumption")
        if isinstance(profile_consumption, dict):
            for hit in profile_consumption.get("hits") or []:
                profile_id = hit.get("profile_id")
                if profile_id and profile_id not in profile_ids:
                    profile_ids.append(profile_id)
    decision["veto_hits"] = gate["veto_ids"]
    decision["veto_checked"] = True
    decision["risk_level"] = gate["risk_level"]
    decision["needs_human_review"] = gate["needs_human_review"]
    decision["selected_score_breakdown"] = best["rank"]
    decision["supporting_knowledge"]["strategy_memory_ids"] = evidence_ids
    decision["supporting_knowledge"]["memory_evidence_profile_ids"] = profile_ids
    decision["supporting_knowledge"]["veto_memory_ids"] = gate["veto_ids"]
    decision["supporting_knowledge"]["candidate_scores"] = [
        {
            "memory_id": item["case"].get("memory_id"),
            "memory_type": "case_memory",
            "rank_score": item["rank"]["total"],
            "score_breakdown": item["rank"],
            "gate_decision": item["gate"].get("gate_decision"),
            "gate_reason": item["gate"].get("gate_reason"),
            "failcohort_hit_score": item["gate"].get("failcohort_hit_score", 0.0),
            "profile_review_reasons": item["gate"].get("profile_review_reasons") or [],
            "profile_release_reasons": item["gate"].get("profile_release_reasons") or [],
            "memory_evidence_profile_consumption": item["rank"].get("memory_evidence_profile_consumption") or {},
            "source_plan_bundle": item.get("source_plan_bundle") or {},
            "value_selection": item["action"].get("value_selection") or {},
            "credibility_mode": f"compiled_strategy_knowledge:{rank_variant}",
        }
        for item in scored
    ]
    decision["memory_evidence_profile_consumption"] = best["rank"].get("memory_evidence_profile_consumption") or {}
    decision["produced_by"] = method_id
    decision["pipeline"] = {
        "recall": "case_retrieval_topk",
        "evidence": (
            "memory_evidence_profile_arbitration_v1"
            if _profile_uses_arbitration(profile_consumption_policy)
            else "memory_evidence_profile_consumption_v1"
            if _profile_consumption_enabled(profile_consumption_policy)
            else "compiled_strategy_knowledge_evidence"
        ),
        "rank": (
            f"compiled_strategy_knowledge_rank_v1:{rank_variant}+profile_arbitration"
            if _profile_uses_arbitration(profile_consumption_policy)
            else f"compiled_strategy_knowledge_rank_v1:{rank_variant}+profiles"
            if _profile_consumption_enabled(profile_consumption_policy)
            else f"compiled_strategy_knowledge_rank_v1:{rank_variant}"
        ),
        "gate": (
            "echo_failcohort_gate_v4+profile_arbitration"
            if _profile_uses_arbitration(profile_consumption_policy)
            else "echo_failcohort_gate_v4+profile_review"
            if _profile_consumption_enabled(profile_consumption_policy)
            else "echo_failcohort_gate_v4"
        ),
        "value_selection": (
            "case_current_snapshot_value_rebase"
            if use_action_value_selector
            else "none"
        ),
    }
    return decision


def _artifact_memory_by_id(artifacts: dict[str, Any]) -> dict[str, dict[str, Any]]:
    memories_by_id = artifacts.get("memories_by_id")
    if isinstance(memories_by_id, dict):
        return {
            str(memory_id): memory
            for memory_id, memory in memories_by_id.items()
            if isinstance(memory, dict)
        }
    memories = artifacts.get("memories") if isinstance(artifacts.get("memories"), list) else []
    return {
        str(memory.get("memory_id")): memory
        for memory in memories
        if isinstance(memory, dict) and memory.get("memory_id")
    }


def _strategy_action(memory: dict[str, Any]) -> dict[str, Any]:
    content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
    app = memory.get("applicability") if isinstance(memory.get("applicability"), dict) else {}
    component: dict[str, Any] = {}
    components = content.get("components") if isinstance(content.get("components"), list) else []
    if components:
        component = max(
            (item for item in components if isinstance(item, dict)),
            key=lambda item: int(item.get("support_count") or 0),
            default={},
        )
    value_pattern = content.get("value_pattern") if isinstance(content.get("value_pattern"), dict) else {}
    scheme_groups = app.get("scheme_groups") if isinstance(app.get("scheme_groups"), list) else []
    scheme_ids = app.get("scheme_ids") if isinstance(app.get("scheme_ids"), list) else []
    delta = (
        component.get("delta_bucket")
        or value_pattern.get("delta_bucket")
        or content.get("adjustment")
        or value_pattern.get("delta")
        or ""
    )
    typical_change = (
        component.get("typical_change")
        or content.get("typical_change")
        or value_pattern.get("typical_change")
        or ""
    )
    companion_distribution = plan_companion_distribution_from_strategy(content)
    return {
        "scheme_group": str(component.get("scheme_group") or content.get("scheme_group") or (scheme_groups[0] if scheme_groups else "")),
        "scheme_id": str(component.get("scheme_id") or content.get("scheme_id") or (scheme_ids[0] if scheme_ids else "")),
        "parameter_semantic_id": str(component.get("parameter_semantic_id") or content.get("parameter_semantic_id") or ""),
        "param_object": str(component.get("param_object") or content.get("param_object") or ""),
        "site_param_object": str(component.get("site_param_object") or content.get("site_param_object") or ""),
        "param_en_name": str(component.get("param_en_name") or content.get("param_en_name") or ""),
        "site_param_en_name": str(component.get("site_param_en_name") or content.get("site_param_en_name") or ""),
        "param_cn_name": str(component.get("param_cn_name") or content.get("param_cn_name") or ""),
        "value_type": str(component.get("value_type") or value_pattern.get("value_type") or ""),
        "direction": str(component.get("direction") or value_pattern.get("direction") or ""),
        "suggested_delta": str(delta) if delta is not None else "",
        "delta_bucket": str(delta) if delta is not None else "",
        "typical_change": str(typical_change),
        "action_signature": str(component.get("action_signature") or content.get("action_signature") or ""),
        "normalized_shape_id": str(
            component.get("normalized_shape_id")
            or value_pattern.get("normalized_shape_id")
            or ""
        ),
        "value_pattern_id": str(value_pattern.get("pattern_id") or component.get("action_signature") or ""),
        "plan_companion_parameters": [],
        "plan_companion_parameter_distribution": companion_distribution,
        "action_contract_version": "action_contract.v2.companion_parameters",
        "action_contract_source": "train_only_strategy_memory_distribution",
    }


def _action_key(action: dict[str, Any]) -> tuple[str, str, str, str]:
    return (
        str(action.get("scheme_id") or "").strip().lower(),
        str(action.get("parameter_semantic_id") or "").strip().lower(),
        str(action.get("param_cn_name") or "").strip().lower(),
        str(action.get("direction") or "").strip().lower(),
    )


def _norm_action_value(action: dict[str, Any], key: str) -> str:
    return str(action.get(key) or "").strip().lower()


def _direction_compatible(source: str, candidate: str, *, param_name: str = "") -> bool:
    source = source.strip().lower()
    candidate = candidate.strip().lower()
    if not source or not candidate or source == candidate:
        return True
    if {source, candidate} <= {"switch", "switch_enum"}:
        return True
    if "开关" in param_name:
        if source == "increase" and candidate in {"enable", "switch", "switch_enum"}:
            return True
        if source == "decrease" and candidate in {"disable", "switch", "switch_enum"}:
            return True
    return False


def _source_action_match(source_action: dict[str, Any], candidate_action: dict[str, Any]) -> dict[str, Any]:
    """Measure whether a strategy candidate can safely emit a source case action."""
    source_scheme = _norm_action_value(source_action, "scheme_id")
    candidate_scheme = _norm_action_value(candidate_action, "scheme_id")
    source_semantic = _norm_action_value(source_action, "parameter_semantic_id")
    candidate_semantic = _norm_action_value(candidate_action, "parameter_semantic_id")
    source_param = _norm_action_value(source_action, "param_cn_name")
    candidate_param = _norm_action_value(candidate_action, "param_cn_name")
    source_direction = _norm_action_value(source_action, "direction")
    candidate_direction = _norm_action_value(candidate_action, "direction")
    param_name = str(source_action.get("param_cn_name") or candidate_action.get("param_cn_name") or "")

    mismatches: list[str] = []
    matches: list[str] = []
    score = 0.0
    possible = 0.0

    if source_scheme and candidate_scheme:
        possible += 0.45
        if source_scheme == candidate_scheme:
            matches.append("scheme_id")
            score += 0.45
        else:
            mismatches.append("scheme_id")
    if source_param and candidate_param:
        possible += 0.35
        if source_param == candidate_param:
            matches.append("param_cn_name")
            score += 0.35
        else:
            mismatches.append("param_cn_name")
    if source_semantic and candidate_semantic:
        possible += 0.10
        if source_semantic == candidate_semantic:
            matches.append("parameter_semantic_id")
            score += 0.10
        else:
            mismatches.append("parameter_semantic_id")
    if source_direction and candidate_direction:
        possible += 0.20
        if _direction_compatible(source_direction, candidate_direction, param_name=param_name):
            matches.append("direction")
            score += 0.20
        else:
            mismatches.append("direction")

    normalized = score / possible if possible else 0.0
    exact_action = bool(source_scheme and candidate_scheme and source_scheme == candidate_scheme) and (
        bool(source_semantic and candidate_semantic and source_semantic == candidate_semantic)
        or bool(source_param and candidate_param and source_param == candidate_param)
    )
    return {
        "compatible": exact_action and not mismatches,
        "score": _bounded(normalized),
        "matches": matches,
        "mismatches": mismatches,
    }


def _case_best_action_match(
    case: dict[str, Any],
    candidate_action: dict[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    best_action: dict[str, Any] = {}
    best_match: dict[str, Any] = {"compatible": False, "score": 0.0, "matches": [], "mismatches": []}
    for action in _case_actions(case):
        match = _source_action_match(action, candidate_action)
        if float(match.get("score") or 0.0) > float(best_match.get("score") or 0.0):
            best_action = action
            best_match = match
    return best_action, best_match


def _strategy_related_evidence_index(artifacts: dict[str, Any]) -> dict[str, dict[str, list[dict[str, Any]]]]:
    cache_key = id(artifacts)
    cached = _STRATEGY_RELATED_EVIDENCE_INDEX_CACHE.get(cache_key)
    if cached is not None:
        return cached

    memories = artifacts.get("memories") if isinstance(artifacts.get("memories"), list) else []
    case_by_trace_id: dict[str, dict[str, Any]] = {}
    by_memory_id: dict[str, dict[str, list[dict[str, Any]]]] = defaultdict(lambda: {"cases": [], "episodes": []})

    for memory in memories:
        if memory.get("memory_type") != "case_memory":
            continue
        for trace_id in memory.get("trace_ids") or []:
            if trace_id:
                case_by_trace_id[str(trace_id)] = memory

    max_cases_per_memory = 80
    for memory in memories:
        if memory.get("memory_type") not in {"strategy_memory", "playbook_memory"}:
            continue
        memory_id = str(memory.get("memory_id") or "")
        if not memory_id:
            continue
        seen_cases: set[str] = set()
        for trace_id in memory.get("trace_ids") or []:
            if len(by_memory_id[memory_id]["cases"]) >= max_cases_per_memory:
                break
            case = case_by_trace_id.get(str(trace_id))
            case_id = str(case.get("memory_id") or "") if case else ""
            if case and case_id and case_id not in seen_cases:
                by_memory_id[memory_id]["cases"].append(case)
                seen_cases.add(case_id)

    episode_candidates = (
        artifacts.get("episode_candidates")
        if isinstance(artifacts.get("episode_candidates"), list)
        else []
    )
    for episode in episode_candidates:
        if not isinstance(episode, dict):
            continue
        linked_ids = [
            *(episode.get("linked_strategy_memory_ids") or []),
            *(episode.get("linked_playbook_memory_ids") or []),
        ]
        for memory_id in linked_ids:
            if memory_id:
                by_memory_id[str(memory_id)]["episodes"].append(episode)

    index = dict(by_memory_id)
    _STRATEGY_RELATED_EVIDENCE_INDEX_CACHE.clear()
    _STRATEGY_RELATED_EVIDENCE_INDEX_CACHE[cache_key] = index
    return index


def _sample_to_case_memory(sample: dict[str, Any]) -> dict[str, Any]:
    actions = []
    for action in sample.get("actions", []) or []:
        if not isinstance(action, dict):
            continue
        before = action.get("before_value")
        after = action.get("after_value")
        change = action.get("change") or (f"{before}→{after}" if before is not None and after is not None else "")
        actions.append({
            "scheme_group": action.get("scheme_group"),
            "scheme_id": action.get("scheme_id"),
            "parameter_semantic_id": action.get("parameter_semantic_id"),
            "param_cn_name": action.get("param_cn_name") or action.get("param_en_name"),
            "value_type": action.get("value_type"),
            "direction": action.get("direction"),
            "delta_bucket": action.get("delta_bucket"),
            "suggested_delta": action.get("suggested_delta"),
            "change": str(change).replace("->", "→"),
        })
    outcome = str(sample.get("ticket_outcome") or "")
    pass_rate = 1.0 if outcome == "long_eval_pass" else 0.0
    return {
        "memory_id": (sample.get("case_memory_ids") or [sample.get("sample_id")])[0],
        "memory_type": "case_memory",
        "trace_ids": [sample.get("trace_id")] if sample.get("trace_id") else [],
        "applicability": {
            "issue_types": [sample.get("issue_type")] if sample.get("issue_type") else [],
            "vendors": [sample.get("vendor")] if sample.get("vendor") else [],
            "systems": [sample.get("system")] if sample.get("system") else [],
            "regions": [sample.get("region")] if sample.get("region") else [],
            "bands": [sample.get("band")] if sample.get("band") else [],
        },
        "content": {
            "actions": actions,
            "aggregate": {
                "pass_rate": pass_rate,
                "long_eval_pass": 1 if outcome == "long_eval_pass" else 0,
                "long_eval_fail": 1 if outcome == "long_eval_fail" else 0,
            },
            "sample_id": sample.get("sample_id"),
            "ticket_outcome": outcome,
        },
        "metrics": {"pass_rate": pass_rate},
    }


def _sample_evidence_index(artifacts: dict[str, Any]) -> dict[str, dict[str, Any]]:
    cache_key = id(artifacts)
    cached = _STRATEGY_SAMPLE_EVIDENCE_INDEX_CACHE.get(cache_key)
    if cached is not None:
        return cached
    sample_rows = artifacts.get("strategy_samples") if isinstance(artifacts.get("strategy_samples"), list) else []
    episode_rows = (
        artifacts.get("strategy_sample_episodes")
        if isinstance(artifacts.get("strategy_sample_episodes"), list)
        else []
    )
    samples_by_memory: dict[str, list[dict[str, Any]]] = defaultdict(list)
    samples_by_id: dict[str, dict[str, Any]] = {}
    episodes_by_memory: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for sample in sample_rows:
        mid = sample.get("memory_id")
        sid = sample.get("sample_id")
        if mid:
            samples_by_memory[str(mid)].append(sample)
        if sid:
            samples_by_id[str(sid)] = sample
    for rows in samples_by_memory.values():
        rows.sort(key=lambda row: int(row.get("sample_rank") or 0))
    for episode in episode_rows:
        mid = episode.get("memory_id")
        if mid:
            episodes_by_memory[str(mid)].append(episode)
    for rows in episodes_by_memory.values():
        rows.sort(
            key=lambda row: (
                str(row.get("group_dimension") or ""),
                -int(row.get("sample_count") or 0),
                str(row.get("group_key") or ""),
            )
        )
    index = {
        "samples_by_memory": samples_by_memory,
        "samples_by_id": samples_by_id,
        "episodes_by_memory": episodes_by_memory,
    }
    _STRATEGY_SAMPLE_EVIDENCE_INDEX_CACHE.clear()
    _STRATEGY_SAMPLE_EVIDENCE_INDEX_CACHE[cache_key] = index
    return index


def _sample_cases_for_policy(
    memory_id: str,
    artifacts: dict[str, Any],
    *,
    policy: str,
    limit: int,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    if policy in {"", "no_samples"}:
        return [], []
    index = _sample_evidence_index(artifacts)
    samples = list(index["samples_by_memory"].get(memory_id, []))
    episodes = list(index["episodes_by_memory"].get(memory_id, []))
    selected_samples: list[dict[str, Any]] = []
    seen_sample_ids: set[str] = set()

    def add_sample(sample: dict[str, Any]) -> None:
        sid = str(sample.get("sample_id") or "")
        if sid and sid not in seen_sample_ids:
            selected_samples.append(sample)
            seen_sample_ids.add(sid)

    if policy == "episode_stats":
        return [], episodes[: max(0, limit)]
    if policy == "episode_evidence":
        for episode in episodes[: max(4, limit * 2)]:
            for sample_id in episode.get("representative_sample_ids", []) or []:
                sample = index["samples_by_id"].get(str(sample_id))
                if sample:
                    add_sample(sample)
                if len(selected_samples) >= limit:
                    break
            if len(selected_samples) >= limit:
                break
    elif policy == "diverse_representatives":
        for sample in samples:
            if sample.get("is_representative"):
                add_sample(sample)
            if len(selected_samples) >= limit:
                break
    else:
        for sample in samples:
            add_sample(sample)
            if len(selected_samples) >= limit:
                break

    return [_sample_to_case_memory(sample) for sample in selected_samples[:limit]], episodes[: max(0, limit)]


def _episode_outcome_counts(episode: dict[str, Any]) -> dict[str, int]:
    counts = episode.get("outcome_counts") if isinstance(episode.get("outcome_counts"), dict) else {}
    metrics = episode.get("metrics") if isinstance(episode.get("metrics"), dict) else {}
    passed = int(counts.get("long_eval_pass") or metrics.get("long_eval_pass_count") or 0)
    failed = int(counts.get("long_eval_fail") or metrics.get("long_eval_fail_count") or 0)
    unknown = int(
        counts.get("long_eval_unknown")
        or counts.get("long_eval_mixed")
        or counts.get("execution_blocked")
        or metrics.get("long_eval_unknown_count")
        or 0
    )
    sample_count = int(episode.get("sample_count") or metrics.get("sample_count") or passed + failed + unknown)
    return {
        "pass": max(0, passed),
        "fail": max(0, failed),
        "unknown": max(0, unknown),
        "sample_count": max(0, sample_count),
    }


def _episode_action_match_score(episode: dict[str, Any], action: dict[str, Any]) -> float:
    scheme_id = str(action.get("scheme_id") or "").strip().lower()
    semantic_id = str(action.get("parameter_semantic_id") or "").strip().lower()
    value_type = str(action.get("value_type") or "").strip().lower()
    direction = str(action.get("direction") or "").strip().lower()
    signatures = []
    if isinstance(episode.get("action_signature_counts"), dict):
        signatures.extend(str(key) for key in episode["action_signature_counts"].keys())
    if episode.get("group_dimension") == "action" and episode.get("group_key"):
        signatures.append(str(episode.get("group_key")))
    best = 0.0
    for signature in signatures:
        parts = [part.strip().lower() for part in signature.split("|")]
        score = 0.0
        possible = 0.0
        checks = [
            (scheme_id, parts[0] if len(parts) > 0 else "", 0.35),
            (semantic_id, parts[1] if len(parts) > 1 else "", 0.35),
            (value_type, parts[2] if len(parts) > 2 else "", 0.10),
            (direction, parts[3] if len(parts) > 3 else "", 0.20),
        ]
        for expected, observed, weight in checks:
            if expected:
                possible += weight
                if expected == observed:
                    score += weight
        if possible:
            best = max(best, score / possible)
    return _bounded(best)


def _episode_region_fit(episode: dict[str, Any], trace: dict[str, Any]) -> float:
    ticket = trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}
    region = str(ticket.get("region") or "").strip()
    counts = episode.get("region_counts") if isinstance(episode.get("region_counts"), dict) else {}
    if not region or not counts:
        return 0.0
    total = sum(int(value or 0) for value in counts.values())
    if total <= 0:
        return 0.0
    return _bounded(int(counts.get(region) or 0) / total)


def _episode_recency_fit(episode: dict[str, Any]) -> float:
    counts = episode.get("recency_counts") if isinstance(episode.get("recency_counts"), dict) else {}
    total = sum(int(value or 0) for value in counts.values())
    if total <= 0:
        return 0.0
    recent = int(counts.get("recent") or 0)
    mid = int(counts.get("mid") or 0)
    return _bounded((recent + 0.5 * mid) / total)


def _episode_aggregate_features(candidate: dict[str, Any], trace: dict[str, Any]) -> dict[str, Any]:
    action = candidate.get("action") if isinstance(candidate.get("action"), dict) else {}
    episodes = candidate.get("related_sample_episodes") if isinstance(candidate.get("related_sample_episodes"), list) else []
    if not episodes:
        return {
            "available": False,
            "episode_count": 0,
            "matched_episode_count": 0,
            "sample_count": 0,
            "matched_sample_count": 0,
            "pass_rate": 0.0,
            "lcb": 0.0,
            "support": 0.0,
            "action_match": 0.0,
            "region_fit": 0.0,
            "recency_fit": 0.0,
            "failure_pressure": 0.0,
            "value_bucket_count": 0,
            "top_value_bucket": "",
        }
    matched: list[tuple[dict[str, Any], float]] = []
    for episode in episodes:
        match = _episode_action_match_score(episode, action)
        if match >= 0.70:
            matched.append((episode, match))
    selected = matched or [(episode, _episode_action_match_score(episode, action)) for episode in episodes]
    total_samples = 0
    matched_samples = 0
    passed = 0
    failed = 0
    weighted_match = 0.0
    weighted_region = 0.0
    weighted_recency = 0.0
    value_counts: Counter[str] = Counter()
    for episode, match in selected:
        counts = _episode_outcome_counts(episode)
        support = int(counts["sample_count"] or episode.get("sample_count") or 0)
        total_samples += support
        matched_samples += int(episode.get("matched_action_sample_count") or support)
        passed += counts["pass"]
        failed += counts["fail"]
        weighted_match += match * support
        weighted_region += _episode_region_fit(episode, trace) * support
        weighted_recency += _episode_recency_fit(episode) * support
        if isinstance(episode.get("value_change_counts"), dict):
            for bucket, count in episode["value_change_counts"].items():
                if bucket:
                    value_counts[str(bucket)] += int(count or 0)
    denom = passed + failed
    pass_rate = passed / denom if denom > 0 else 0.0
    top_value_bucket = value_counts.most_common(1)[0][0] if value_counts else ""
    return {
        "available": True,
        "episode_count": len(episodes),
        "matched_episode_count": len(matched),
        "sample_count": total_samples,
        "matched_sample_count": matched_samples,
        "pass_count": passed,
        "fail_count": failed,
        "pass_rate": _bounded(pass_rate),
        "lcb": _lcb(pass_rate, denom),
        "support": _support_term(total_samples),
        "action_match": _bounded(weighted_match / total_samples) if total_samples else 0.0,
        "region_fit": _bounded(weighted_region / total_samples) if total_samples else 0.0,
        "recency_fit": _bounded(weighted_recency / total_samples) if total_samples else 0.0,
        "failure_pressure": _bounded(failed / denom) if denom else 0.0,
        "value_bucket_count": len(value_counts),
        "top_value_bucket": top_value_bucket,
        "value_counts": dict(value_counts.most_common(8)),
    }


def _value_key_aliases(raw: Any) -> set[str]:
    text = str(raw or "").replace("->", "→").strip()
    if not text:
        return set()
    aliases = {text.lower()}
    if re.fullmatch(r"[+-]?\d+(?:\.0+)?", text):
        value = float(text)
        if value == 0:
            aliases.add("0")
        else:
            aliases.add(f"{value:+g}".lower())
    return aliases


def _candidate_value_keys(action: dict[str, Any]) -> set[str]:
    keys: set[str] = set()
    for field in ("suggested_delta", "delta_bucket", "typical_change", "target_value", "change"):
        keys.update(_value_key_aliases(action.get(field)))
    return keys


def _episode_summary(episodes: list[dict[str, Any]]) -> dict[str, Any]:
    sample_count = 0
    passed = 0
    failed = 0
    unknown = 0
    for episode in episodes:
        counts = _episode_outcome_counts(episode)
        sample_count += int(counts["sample_count"] or 0)
        passed += int(counts["pass"] or 0)
        failed += int(counts["fail"] or 0)
        unknown += int(counts["unknown"] or 0)
    evaluated = passed + failed
    pass_rate = passed / evaluated if evaluated > 0 else 0.0
    return {
        "available": bool(episodes),
        "episode_count": len(episodes),
        "sample_count": sample_count,
        "pass_count": passed,
        "fail_count": failed,
        "unknown_count": unknown,
        "pass_rate": _bounded(pass_rate),
        "lcb": _wilson_lcb(passed, evaluated),
        "support": _support_term(sample_count),
        "failure_pressure": _bounded(failed / evaluated) if evaluated else 0.0,
        "unknown_pressure": _bounded(unknown / sample_count) if sample_count else 0.0,
    }


def _episode_value_key_match(episode: dict[str, Any], value_keys: set[str]) -> bool:
    if not value_keys:
        return False
    if str(episode.get("group_dimension") or "") == "value":
        if _value_key_aliases(episode.get("group_key")) & value_keys:
            return True
    value_counts = episode.get("value_change_counts") if isinstance(episode.get("value_change_counts"), dict) else {}
    return any(_value_key_aliases(key) & value_keys for key in value_counts.keys())


def _episode_action_value_outcome_features(candidate: dict[str, Any], trace: dict[str, Any]) -> dict[str, Any]:
    action = candidate.get("action") if isinstance(candidate.get("action"), dict) else {}
    episodes = candidate.get("related_sample_episodes") if isinstance(candidate.get("related_sample_episodes"), list) else []
    if not episodes:
        empty = _episode_summary([])
        return {
            "available": False,
            "episode_count": 0,
            "matched_episode_count": 0,
            "candidate_value_keys": [],
            "action": empty,
            "value": empty,
            "region": empty,
            "recent": empty,
            "value_coverage": 0.0,
            "region_coverage": 0.0,
        }

    matched = [
        (episode, _episode_action_match_score(episode, action))
        for episode in episodes
    ]
    matched = [(episode, score) for episode, score in matched if score >= 0.70]
    action_eps = [
        episode
        for episode, score in matched
        if str(episode.get("group_dimension") or "") == "action" and score >= 0.85
    ]
    if not action_eps:
        action_eps = [
            episode
            for episode, _score in matched
            if str(episode.get("group_dimension") or "") == "action"
        ]
    action_summary = _episode_summary(action_eps)

    value_keys = _candidate_value_keys(action)
    value_eps = [
        episode
        for episode, _score in matched
        if str(episode.get("group_dimension") or "") == "value"
        and _episode_value_key_match(episode, value_keys)
    ]
    value_summary = _episode_summary(value_eps)

    ticket = trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}
    region = str(ticket.get("region") or "").strip()
    region_eps = [
        episode
        for episode, _score in matched
        if region
        and str(episode.get("group_dimension") or "") == "region"
        and str(episode.get("group_key") or "").strip() == region
    ]
    region_summary = _episode_summary(region_eps)

    recent_eps = [
        episode
        for episode, _score in matched
        if str(episode.get("group_dimension") or "") == "recency"
        and str(episode.get("group_key") or "").strip().lower() == "recent"
    ]
    recent_summary = _episode_summary(recent_eps)

    action_sample_count = max(1, int(action_summary.get("sample_count") or 0))
    value_support = 0
    region_support = 0
    for episode in action_eps:
        value_counts = episode.get("value_change_counts") if isinstance(episode.get("value_change_counts"), dict) else {}
        for key, count in value_counts.items():
            if _value_key_aliases(key) & value_keys:
                value_support += int(count or 0)
        region_counts = episode.get("region_counts") if isinstance(episode.get("region_counts"), dict) else {}
        region_support += int(region_counts.get(region) or 0) if region else 0

    return {
        "available": bool(matched),
        "episode_count": len(episodes),
        "matched_episode_count": len(matched),
        "candidate_value_keys": sorted(value_keys)[:8],
        "action": action_summary,
        "value": value_summary,
        "region": region_summary,
        "recent": recent_summary,
        "value_coverage": _bounded(value_support / action_sample_count) if action_summary.get("sample_count") else 0.0,
        "region_coverage": _bounded(region_support / action_sample_count) if action_summary.get("sample_count") else 0.0,
    }


def _episode_value_selector_rows(candidate: dict[str, Any], trace: dict[str, Any]) -> list[dict[str, Any]]:
    episodes = candidate.get("related_sample_episodes") if isinstance(candidate.get("related_sample_episodes"), list) else []
    action = candidate.get("action") if isinstance(candidate.get("action"), dict) else {}
    if not episodes:
        return []
    rows_by_delta: dict[str, dict[str, Any]] = {}
    for episode in episodes:
        if _episode_action_match_score(episode, action) < 0.70:
            continue
        value_counts = episode.get("value_change_counts") if isinstance(episode.get("value_change_counts"), dict) else {}
        if not value_counts:
            continue
        counts = _episode_outcome_counts(episode)
        evaluated = counts["pass"] + counts["fail"]
        pass_rate = counts["pass"] / evaluated if evaluated > 0 else 0.0
        fail_rate = counts["fail"] / evaluated if evaluated > 0 else 0.0
        region_fit = _episode_region_fit(episode, trace)
        recency_fit = _episode_recency_fit(episode)
        for delta_bucket, raw_count in value_counts.items():
            if delta_bucket is None:
                continue
            bucket = str(delta_bucket)
            support = int(raw_count or 0)
            if support <= 0:
                continue
            row = rows_by_delta.setdefault(
                bucket,
                {
                    "source": "episode_value_distribution",
                    "delta_bucket": bucket,
                    "suggested_delta": bucket,
                    "support_count": 0,
                    "long_eval_pass_count": 0,
                    "long_eval_fail_count": 0,
                    "region_fit": 0.0,
                    "recency_fit": 0.0,
                },
            )
            row["support_count"] += support
            row["long_eval_pass_count"] += int(round(support * pass_rate))
            row["long_eval_fail_count"] += int(round(support * fail_rate))
            row["region_fit"] += region_fit * support
            row["recency_fit"] += recency_fit * support
    rows: list[dict[str, Any]] = []
    for row in rows_by_delta.values():
        support = int(row.get("support_count") or 0)
        if support <= 0:
            continue
        row["region_fit"] = round(float(row.get("region_fit") or 0.0) / support, 6)
        row["recency_fit"] = round(float(row.get("recency_fit") or 0.0) / support, 6)
        passed = int(row.get("long_eval_pass_count") or 0)
        failed = int(row.get("long_eval_fail_count") or 0)
        row["pass_rate"] = round(passed / (passed + failed), 6) if passed + failed else 0.0
        rows.append(row)
    rows.sort(
        key=lambda row: (
            float(row.get("pass_rate") or 0.0),
            int(row.get("support_count") or 0),
            str(row.get("delta_bucket") or ""),
        ),
        reverse=True,
    )
    return rows


def _attach_strategy_related_evidence(
    candidate: dict[str, Any],
    trace: dict[str, Any],
    artifacts: dict[str, Any] | None,
    *,
    limit: int = 3,
    sample_evidence_policy: str = "raw_topn_samples",
) -> None:
    if not isinstance(artifacts, dict):
        return
    memory = candidate.get("memory") if isinstance(candidate.get("memory"), dict) else {}
    memory_id = str(memory.get("memory_id") or "")
    if not memory_id:
        return
    if sample_evidence_policy == "no_samples":
        cases: list[dict[str, Any]] = []
        episodes: list[dict[str, Any]] = []
        sample_episodes: list[dict[str, Any]] = []
    elif sample_evidence_policy in {"episode_stats", "episode_evidence", "diverse_representatives", "raw_topn_samples"}:
        cases, sample_episodes = _sample_cases_for_policy(
            memory_id,
            artifacts,
            policy=sample_evidence_policy,
            limit=max(3, limit),
        )
        related = _strategy_related_evidence_index(artifacts).get(memory_id) or {}
        if not cases and sample_evidence_policy == "raw_topn_samples":
            cases = related.get("cases") if isinstance(related.get("cases"), list) else []
        episodes = related.get("episodes") if isinstance(related.get("episodes"), list) else []
    else:
        related = _strategy_related_evidence_index(artifacts).get(memory_id) or {}
        cases = related.get("cases") if isinstance(related.get("cases"), list) else []
        episodes = related.get("episodes") if isinstance(related.get("episodes"), list) else []
        sample_episodes = []
    action = candidate.get("action") if isinstance(candidate.get("action"), dict) else {}

    scored_cases: list[tuple[float, dict[str, Any], dict[str, Any], dict[str, Any]]] = []
    query = trace_query(trace)
    ticket = trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}
    query["band"] = ticket.get("band")
    for case in cases:
        source_action, match = _case_best_action_match(case, action)
        if not match.get("compatible"):
            continue
        context = min(1.0, _case_score(case, query) / 18.0)
        score = 0.50 * context + 0.25 * _case_pass_rate(case) + 0.25 * float(match.get("score") or 0.0)
        scored_cases.append((score, case, source_action, match))
    scored_cases.sort(
        key=lambda item: (
            item[0],
            _case_pass_rate(item[1]),
            str(item[1].get("memory_id") or ""),
        ),
        reverse=True,
    )
    selected_cases = scored_cases[:limit]
    if selected_cases:
        candidate["source_cases"] = [item[1] for item in selected_cases]
        candidate["source_actions"] = [item[2] for item in selected_cases]
        candidate["source_action_match"] = max(
            (item[3] for item in selected_cases),
            key=lambda match: float(match.get("score") or 0.0),
        )
    if episodes:
        candidate["related_episodes"] = sorted(
            episodes,
            key=lambda episode: (
                int(((episode.get("metrics") or {}).get("long_eval_pass_count") or 0)),
                int(((episode.get("metrics") or {}).get("trace_count") or 0)),
                str(episode.get("episode_id") or ""),
            ),
            reverse=True,
        )[:limit]
    if sample_episodes:
        candidate["related_sample_episodes"] = sample_episodes[:limit]
    candidate["evidence_assembly"] = {
        "policy": f"strategy_static_sample_links_v1:{sample_evidence_policy}",
        "linked_case_count": len(cases),
        "selected_case_count": len(candidate.get("source_cases") or []),
        "linked_episode_count": len(episodes),
        "selected_episode_count": len(candidate.get("related_episodes") or []),
        "linked_sample_episode_count": len(sample_episodes),
        "selected_sample_episode_count": len(candidate.get("related_sample_episodes") or []),
    }


def _strategy_memory_candidates(memories: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [
        memory
        for memory in memories
        if memory.get("memory_type") in {"strategy_memory", "playbook_memory"}
        and str(memory.get("state") or "") != "counter_evidence"
    ]


def _strategy_recall_index(memories: list[dict[str, Any]]) -> dict[str, Any]:
    cache_key = id(memories)
    cached = _STRATEGY_RECALL_INDEX_CACHE.get(cache_key)
    if cached is not None:
        return cached
    candidates = _strategy_memory_candidates(memories)
    ids = [str(memory.get("memory_id") or "") for memory in candidates]
    by_field: dict[str, dict[str, list[int]]] = {
        key: defaultdict(list)
        for key in ("issue_types", "vendors", "systems", "regions", "bands")
    }
    for idx, memory in enumerate(candidates):
        app = memory.get("applicability") if isinstance(memory.get("applicability"), dict) else {}
        for app_key in by_field:
            for value in _values(app.get(app_key)):
                by_field[app_key][value].append(idx)
    index = {
        "candidates": candidates,
        "ids": ids,
        "by_field": by_field,
        "zero_order": sorted(range(len(candidates)), key=lambda idx: ids[idx]),
    }
    _STRATEGY_RECALL_INDEX_CACHE.clear()
    _STRATEGY_RECALL_INDEX_CACHE[cache_key] = index
    return index


def _strategy_candidate(
    memory: dict[str, Any],
    trace: dict[str, Any],
    *,
    recall_mode: str,
    source_cases: list[dict[str, Any]] | None = None,
    source_actions: list[dict[str, Any]] | None = None,
    source_action_match: dict[str, Any] | None = None,
    related_episodes: list[dict[str, Any]] | None = None,
    evidence_assembly: dict[str, Any] | None = None,
    recall_score: float | None = None,
) -> dict[str, Any] | None:
    action = _strategy_action(memory)
    if not any(action.get(key) for key in ("scheme_group", "scheme_id", "parameter_semantic_id", "param_cn_name")):
        return None
    context = min(1.0, _case_score(memory, trace_query(trace)) / 18.0)
    return {
        "memory": memory,
        "action": action,
        "source_cases": source_cases or [],
        "source_actions": source_actions or [],
        "source_action_match": source_action_match or {},
        "related_episodes": related_episodes or [],
        "evidence_assembly": evidence_assembly or {},
        "recall_mode": recall_mode,
        "context_similarity": context,
        "recall_score": float(recall_score if recall_score is not None else context),
    }


def _candidate_merge_key(candidate: dict[str, Any]) -> str:
    memory = candidate.get("memory") if isinstance(candidate.get("memory"), dict) else {}
    memory_id = str(memory.get("memory_id") or "")
    return memory_id or "|".join(_action_key(candidate.get("action") if isinstance(candidate.get("action"), dict) else {}))


def _add_recall_route(candidate: dict[str, Any], route: str, *, rank: int) -> None:
    route_score = _bounded(float(candidate.get("recall_score") or 0.0))
    routes = candidate.setdefault("recall_routes", [])
    if isinstance(routes, list):
        routes.append({
            "route": route,
            "score": round(route_score, 6),
            "rank": rank,
        })
    route_scores = candidate.setdefault("route_scores", {})
    if isinstance(route_scores, dict):
        route_scores[route] = max(float(route_scores.get(route) or 0.0), route_score)


def _route_scores(candidate: dict[str, Any]) -> dict[str, float]:
    scores = candidate.get("route_scores") if isinstance(candidate.get("route_scores"), dict) else {}
    out = {
        str(route): _bounded(float(score or 0.0))
        for route, score in scores.items()
        if str(route or "")
    }
    if out:
        return out
    route = str(candidate.get("recall_mode") or "")
    if route:
        out[route] = _bounded(float(candidate.get("recall_score") or 0.0))
    return out


def _route_priority_score(candidate: dict[str, Any]) -> float:
    scores = _route_scores(candidate)
    case_score = scores.get("case_to_strategy_recall", 0.0)
    direct_score = scores.get("strategy_first_recall", 0.0)
    route_count = len(scores)
    return _bounded(max(case_score, direct_score * 0.78) + 0.08 * max(0, route_count - 1))


def _route_rank_score(candidate: dict[str, Any], route: str) -> float:
    routes = candidate.get("recall_routes") if isinstance(candidate.get("recall_routes"), list) else []
    ranks = [
        int(item.get("rank") or 0)
        for item in routes
        if isinstance(item, dict) and str(item.get("route") or "") == route and int(item.get("rank") or 0) > 0
    ]
    if not ranks:
        return 0.0
    return 1.0 / float(min(ranks))


def _strategy_first_candidates(
    memories: list[dict[str, Any]],
    trace: dict[str, Any],
    *,
    artifacts: dict[str, Any] | None = None,
    sample_evidence_policy: str = "raw_topn_samples",
    sample_evidence_limit: int = 3,
    limit: int,
) -> list[dict[str, Any]]:
    query = trace_query(trace)
    ticket = trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}
    query["band"] = ticket.get("band")
    index = _strategy_recall_index(memories)
    memory_candidates = index["candidates"]
    fields = [
        ("issue_type", "issue_types", 8.0),
        ("vendor", "vendors", 4.0),
        ("system", "systems", 3.0),
        ("region", "regions", 2.0),
        ("band", "bands", 1.0),
    ]
    scores: dict[int, float] = defaultdict(float)
    for query_key, app_key, weight in fields:
        query_value = str(query.get(query_key) or "").strip().lower()
        if not query_value:
            continue
        for idx in index["by_field"].get(app_key, {}).get(query_value, []):
            scores[idx] += weight
    ranked = sorted(
        scores,
        key=lambda idx: (
            -scores[idx],
            -_state_term(memory_candidates[idx]),
            -int((memory_candidates[idx].get("metrics") or {}).get("support_count") or 0),
            index["ids"][idx],
        ),
    )
    if len(ranked) < limit:
        seen = set(ranked)
        for idx in index["zero_order"]:
            if idx not in seen:
                ranked.append(idx)
                if len(ranked) >= limit:
                    break
    shortlist = ranked[: max(limit * 25, limit)]
    candidates: list[dict[str, Any]] = []
    for idx in shortlist:
        memory = memory_candidates[idx]
        candidate = _strategy_candidate(
            memory,
            trace,
            recall_mode="strategy_first_recall",
            recall_score=min(1.0, scores.get(idx, _case_score(memory, query)) / 18.0),
        )
        if candidate is not None:
            _attach_strategy_related_evidence(
                candidate,
                trace,
                artifacts,
                limit=sample_evidence_limit,
                sample_evidence_policy=sample_evidence_policy,
            )
            candidates.append(candidate)
    candidates.sort(
        key=lambda item: (
            item["recall_score"],
            _state_term(item["memory"]),
            int((item["memory"].get("metrics") or {}).get("support_count") or 0),
            str(item["memory"].get("memory_id") or ""),
        ),
        reverse=True,
    )
    return candidates[:limit]


def _case_to_strategy_candidates(
    cases: list[dict[str, Any]],
    trace: dict[str, Any],
    artifacts: dict[str, Any],
    *,
    limit: int,
) -> list[dict[str, Any]]:
    memories = artifacts.get("memories") if isinstance(artifacts.get("memories"), list) else []
    memory_by_id = _artifact_memory_by_id(artifacts)
    candidates: dict[str, dict[str, Any]] = {}
    for case in cases:
        case_action = _case_action(case)
        case_context = min(1.0, _case_score(case, trace_query(trace)) / 18.0)
        for evidence in _candidate_strategy_evidence(case_action, trace, memories):
            memory_id = str(evidence.get("memory_id") or "")
            memory = memory_by_id.get(memory_id)
            if not memory:
                continue
            candidate = _strategy_candidate(
                memory,
                trace,
                recall_mode="case_to_strategy_recall",
                source_cases=[case],
                source_actions=[case_action],
                recall_score=max(case_context, float(evidence.get("evidence_score") or 0.0)),
            )
            if candidate is None:
                continue
            source_match = _source_action_match(case_action, candidate["action"])
            if not source_match["compatible"]:
                continue
            candidate["source_action_match"] = source_match
            key = memory_id or "|".join(_action_key(candidate["action"]))
            existing = candidates.get(key)
            if existing is None:
                candidates[key] = candidate
                continue
            existing["recall_score"] = max(float(existing.get("recall_score") or 0.0), float(candidate["recall_score"]))
            seen_cases = {str(item.get("memory_id") or "") for item in existing.get("source_cases") or []}
            for source_case in candidate.get("source_cases") or []:
                case_id = str(source_case.get("memory_id") or "")
                if case_id and case_id not in seen_cases:
                    existing.setdefault("source_cases", []).append(source_case)
                    seen_cases.add(case_id)
            existing.setdefault("source_actions", []).extend(candidate.get("source_actions") or [])
            existing_match = existing.get("source_action_match") if isinstance(existing.get("source_action_match"), dict) else {}
            if float(source_match.get("score") or 0.0) > float(existing_match.get("score") or 0.0):
                existing["source_action_match"] = source_match
    out = list(candidates.values())
    out.sort(
        key=lambda item: (
            item["recall_score"],
            int((item["memory"].get("metrics") or {}).get("support_count") or 0),
            str(item["memory"].get("memory_id") or ""),
        ),
        reverse=True,
    )
    return out[:limit]


def _merge_strategy_candidates(*groups: list[dict[str, Any]], limit: int) -> list[dict[str, Any]]:
    merged: dict[str, dict[str, Any]] = {}
    for group in groups:
        for candidate in group:
            key = _candidate_merge_key(candidate)
            existing = merged.get(key)
            if existing is None:
                merged[key] = dict(candidate)
                continue
            existing["recall_score"] = max(float(existing.get("recall_score") or 0.0), float(candidate.get("recall_score") or 0.0))
            existing_scores = existing.setdefault("route_scores", {})
            candidate_scores = candidate.get("route_scores") if isinstance(candidate.get("route_scores"), dict) else {}
            if isinstance(existing_scores, dict):
                for route, score in candidate_scores.items():
                    route_key = str(route or "")
                    if route_key:
                        existing_scores[route_key] = max(float(existing_scores.get(route_key) or 0.0), float(score or 0.0))
            existing_routes = existing.setdefault("recall_routes", [])
            candidate_routes = candidate.get("recall_routes") if isinstance(candidate.get("recall_routes"), list) else []
            if isinstance(existing_routes, list):
                seen_route_keys = {
                    (str(item.get("route") or ""), int(item.get("rank") or 0))
                    for item in existing_routes
                    if isinstance(item, dict)
                }
                for route_row in candidate_routes:
                    if not isinstance(route_row, dict):
                        continue
                    route_key = (str(route_row.get("route") or ""), int(route_row.get("rank") or 0))
                    if route_key not in seen_route_keys:
                        existing_routes.append(route_row)
                        seen_route_keys.add(route_key)
            modes = set(str(existing.get("recall_mode") or "").split("+"))
            modes.add(str(candidate.get("recall_mode") or ""))
            existing["recall_mode"] = "+".join(sorted(mode for mode in modes if mode))
            seen_cases = {str(item.get("memory_id") or "") for item in existing.get("source_cases") or []}
            for source_case in candidate.get("source_cases") or []:
                case_id = str(source_case.get("memory_id") or "")
                if case_id and case_id not in seen_cases:
                    existing.setdefault("source_cases", []).append(source_case)
                    seen_cases.add(case_id)
            existing.setdefault("source_actions", []).extend(candidate.get("source_actions") or [])
            seen_episodes = {str(item.get("episode_id") or "") for item in existing.get("related_episodes") or []}
            for episode in candidate.get("related_episodes") or []:
                episode_id = str(episode.get("episode_id") or "")
                if episode_id and episode_id not in seen_episodes:
                    existing.setdefault("related_episodes", []).append(episode)
                    seen_episodes.add(episode_id)
            existing_assembly = existing.get("evidence_assembly") if isinstance(existing.get("evidence_assembly"), dict) else {}
            candidate_assembly = candidate.get("evidence_assembly") if isinstance(candidate.get("evidence_assembly"), dict) else {}
            if candidate_assembly:
                policies = {
                    str(existing_assembly.get("policy") or ""),
                    str(candidate_assembly.get("policy") or ""),
                } - {""}
                existing["evidence_assembly"] = {
                    "policy": "+".join(sorted(policies)),
                    "linked_case_count": max(
                        int(existing_assembly.get("linked_case_count") or 0),
                        int(candidate_assembly.get("linked_case_count") or 0),
                    ),
                    "selected_case_count": len(existing.get("source_cases") or []),
                    "linked_episode_count": max(
                        int(existing_assembly.get("linked_episode_count") or 0),
                        int(candidate_assembly.get("linked_episode_count") or 0),
                    ),
                    "selected_episode_count": len(existing.get("related_episodes") or []),
                }
            existing_match = existing.get("source_action_match") if isinstance(existing.get("source_action_match"), dict) else {}
            candidate_match = candidate.get("source_action_match") if isinstance(candidate.get("source_action_match"), dict) else {}
            if float(candidate_match.get("score") or 0.0) > float(existing_match.get("score") or 0.0):
                existing["source_action_match"] = candidate_match
    out = list(merged.values())
    out.sort(
        key=lambda item: (
            float(item.get("recall_score") or 0.0),
            _state_term(item["memory"]),
            int((item["memory"].get("metrics") or {}).get("support_count") or 0),
            str(item["memory"].get("memory_id") or ""),
        ),
        reverse=True,
    )
    return out[:limit]


def _multi_route_strategy_candidates(
    cases: list[dict[str, Any]],
    memories: list[dict[str, Any]],
    trace: dict[str, Any],
    artifacts: dict[str, Any],
    *,
    limit: int,
    case_route_limit: int,
    strategy_route_limit: int,
    sample_evidence_policy: str = "no_samples",
    sample_evidence_limit: int = 3,
) -> list[dict[str, Any]]:
    case_candidates = _case_to_strategy_candidates(
        cases,
        trace,
        artifacts,
        limit=max(1, case_route_limit),
    )
    strategy_candidates = _strategy_first_candidates(
        memories,
        trace,
        artifacts=artifacts if sample_evidence_policy != "no_samples" else None,
        sample_evidence_policy=sample_evidence_policy,
        sample_evidence_limit=sample_evidence_limit,
        limit=max(1, strategy_route_limit),
    )
    for idx, candidate in enumerate(case_candidates, start=1):
        _add_recall_route(candidate, "case_to_strategy_recall", rank=idx)
    for idx, candidate in enumerate(strategy_candidates, start=1):
        _add_recall_route(candidate, "strategy_first_recall", rank=idx)
    merged = _merge_strategy_candidates(
        case_candidates,
        strategy_candidates,
        limit=max(limit, case_route_limit + strategy_route_limit),
    )
    merged.sort(
        key=lambda item: (
            _route_priority_score(item),
            len(_route_scores(item)),
            float(item.get("recall_score") or 0.0),
            _state_term(item["memory"]),
            int((item["memory"].get("metrics") or {}).get("support_count") or 0),
            str(item["memory"].get("memory_id") or ""),
        ),
        reverse=True,
    )
    return merged[:limit]


