    }
    return {
        "context_similarity": round(terms["context_similarity"], 6),
        "case_outcome_pass_rate": round(related_case, 6),
        "strategy_evidence": [evidence],
        "terms": {key: round(value, 6) for key, value in terms.items()},
        "weights": {key: round(value, 6) for key, value in weights.items()},
        "total": round(total, 6),
        "policy": f"compiled_strategy_knowledge_rank_v1:{variant}",
    }


def _parameter_snapshot_match_for(trace: dict[str, Any], parameter_semantic_id: Any) -> str:
    snapshots = (
        trace.get("pre_decision_parameter_snapshot")
        or trace.get("parameter_snapshot")
        or trace.get("current_parameter_snapshot")
    )
    if not isinstance(snapshots, dict):
        return "unavailable"
    if snapshots.get("coverage_scope") != "candidate_parameter_set":
        return "ambiguous"
    parameters = snapshots.get("parameters")
    if not isinstance(parameters, dict):
        return "ambiguous"
    declared = snapshots.get("candidate_parameter_semantic_ids")
    if isinstance(declared, list):
        declared_ids = {str(item) for item in declared if item}
        if not declared_ids or not declared_ids.issubset(set(parameters)):
            return "ambiguous"
    if parameter_semantic_id and isinstance(parameters.get(str(parameter_semantic_id)), dict):
        return "exact"
    return "missing_predicted_parameter"


def _strategy_value_selected_action(
    candidate: dict[str, Any],
    trace: dict[str, Any],
    *,
    value_selection_policy: str = "memory_child_statistics",
) -> tuple[dict[str, Any], dict[str, Any]]:
    memory = candidate.get("memory") if isinstance(candidate.get("memory"), dict) else {}
    content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
    value_pattern = content.get("value_pattern") if isinstance(content.get("value_pattern"), dict) else {}
    observed_changes = content.get("observed_changes") if isinstance(content.get("observed_changes"), list) else None
    selector_observed_changes = observed_changes
    if value_selection_policy == "episode_value_distribution":
        episode_rows = _episode_value_selector_rows(candidate, trace)
        if episode_rows:
            selector_observed_changes = episode_rows
    parameter_semantic_id = content.get("parameter_semantic_id") or candidate.get("action", {}).get("parameter_semantic_id")
    current_parameter_snapshot = _current_parameter_snapshot_for(trace, parameter_semantic_id)
    parameter_value_prior = (
        content.get("parameter_value_prior")
        if isinstance(content.get("parameter_value_prior"), dict)
        else None
    )
    selection = select_action_value(
        value_pattern,
        observed_changes=selector_observed_changes,
        current_parameter_snapshot=current_parameter_snapshot,
        parameter_value_prior=parameter_value_prior,
        parameter_snapshot_match=_parameter_snapshot_match_for(trace, parameter_semantic_id),
    )
    if value_selection_policy == "episode_value_distribution" and selector_observed_changes is not observed_changes:
        selection = {
            **selection,
            "selection_policy": "episode_value_distribution_lcb_v1",
            "reason": "selected_by_strategy_sample_episode_value_distribution",
        }
    action = dict(candidate.get("action") or {})
    if selection.get("suggested_delta"):
        action["suggested_delta"] = str(selection.get("suggested_delta") or "")
    if selection.get("target_value") and selection.get("target_value_confidence") == "observed":
        action["target_value"] = str(selection.get("target_value") or "")
    if selection.get("normalized_shape_id"):
        action["normalized_shape_id"] = str(selection.get("normalized_shape_id") or "")
    action["value_selection"] = selection
    return action, selection


def _unique_cases(candidates: list[dict[str, Any]]) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    seen: set[str] = set()
    for candidate in candidates:
        for case in candidate.get("source_cases") or []:
            case_id = str(case.get("memory_id") or "")
            if case_id and case_id not in seen:
                out.append(case)
                seen.add(case_id)
    return out


def _type3_texts(trace: dict[str, Any]) -> list[str]:
    texts: list[str] = []
    seen: set[str] = set()
    for key in ("pre_decision_type3_hints", "pre_decision_scheme_type3", "pre_decision_action_family_hints"):
        raw = trace.get(key)
        values = raw if isinstance(raw, list) else [raw]
        for value in values:
            text = str(value or "").strip()
            if text and text not in seen:
                texts.append(text)
                seen.add(text)
    return texts


def _parse_package_size_hint(trace: dict[str, Any]) -> dict[str, Any]:
    texts = _type3_texts(trace)
    item_counts: list[int] = []
    assignment_counts: list[int] = []
    has_multi_language = False
    for text in texts:
        item_count = len(_TYPE3_ITEM_RE.findall(text))
        assignment_count = len(_TYPE3_ASSIGNMENT_RE.findall(text))
        if item_count:
            item_counts.append(item_count)
        if assignment_count:
            assignment_counts.append(assignment_count)
        if _TYPE3_MULTI_RE.search(text):
            has_multi_language = True
    max_item_count = max(item_counts) if item_counts else 0
    max_assignment_count = max(assignment_counts) if assignment_counts else 0
    raw_size = max(max_item_count, max_assignment_count)
    if raw_size <= 0 and has_multi_language:
        raw_size = 2
    return {
        "type3_text_count": len(texts),
        "max_item_count": max_item_count,
        "max_assignment_count": max_assignment_count,
        "has_multi_language": has_multi_language,
        "raw_predicted_size": raw_size,
        "available": raw_size > 0,
    }


def _estimate_package_size(
    trace: dict[str, Any],
    scored: list[dict[str, Any]],
    *,
    max_actions: int,
    policy: str = "type3_soft_size_prior_v1",
    memories: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    hint = _parse_package_size_hint(trace)
    raw_size = int(hint.get("raw_predicted_size") or 0)
    estimated = 1
    reasons = ["default_single_action"]
    if raw_size >= 2:
        estimated = 2
        reasons.append("type3_multi_action_signal_capped_to_2")
    elif hint.get("has_multi_language"):
        estimated = 2
        reasons.append("type3_multi_action_language")

    unique_slots: set[tuple[str, str, str]] = set()
    ranked_unique: list[tuple[dict[str, Any], tuple[str, str, str]]] = []
    for item in scored:
        key = _action_slot_key(item.get("action") or {})
        if key[0] or key[1] or key[2]:
            unique_slots.add(key)
            if key not in {slot for _existing, slot in ranked_unique}:
                ranked_unique.append((item, key))
    train_prior = _train_package_size_prior(trace, memories) if ("ticket_only" in policy or "train_prior" in policy) else {}
    if raw_size <= 0 and ("ticket_only" in policy or "candidate_pool" in policy):
        def _score(candidate: dict[str, Any]) -> float:
            return float((candidate.get("rank") or {}).get("total") or 0.0)

        if len(ranked_unique) >= 2:
            first, second = ranked_unique[0][0], ranked_unique[1][0]
            first_score = _score(first)
            second_score = _score(second)
            ratio = second_score / first_score if first_score > 0 else 0.0
            first_group = _action_group_key(first.get("action") or {})
            second_group = _action_group_key(second.get("action") or {})
            same_group = bool(first_group and first_group == second_group)
            close_second = ratio >= 0.98 or (same_group and ratio >= 0.95)
            prior_multi = bool(train_prior.get("suggested_multi_action"))
            if close_second and prior_multi:
                estimated = 2
                reasons.append("train_prior_and_candidate_pool_second_action_close")
            hint.update({
                "candidate_pool_top2_score_ratio": round(ratio, 6),
                "candidate_pool_top2_same_group": same_group,
                "candidate_pool_close_second": close_second,
            })
    if estimated > len(unique_slots):
        reasons.append("limited_by_unique_candidate_slots")
    estimated = max(1, min(int(max_actions), estimated, max(1, len(unique_slots) or 1)))
    return {
        **hint,
        "policy": policy,
        "estimated_size": estimated,
        "max_actions": max_actions,
        "unique_candidate_slot_count": len(unique_slots),
        "train_package_size_prior": train_prior,
        "reasons": reasons,
    }


def _action_slot_key(action: dict[str, Any]) -> tuple[str, str, str]:
    return (
        str(action.get("scheme_id") or "").strip().lower(),
        str(action.get("parameter_semantic_id") or action.get("parameter_semantic_key") or "").strip().lower(),
        str(action.get("param_cn_name") or action.get("parameter_name") or action.get("param_object") or "").strip().lower(),
    )


def _action_group_key(action: dict[str, Any]) -> str:
    return str(action.get("scheme_group") or "").strip().lower()


def _action_direction(action: dict[str, Any]) -> str:
    return str(action.get("direction") or "").strip().lower()


def _norm_text(value: Any) -> str:
    return str(value or "").strip().lower()


def _trace_selector_context(trace: dict[str, Any]) -> dict[str, Any]:
    root_keys: set[str] = set()
    root_l2s: set[str] = set()
    ticket = trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}
    issue_texts = [
        ticket.get("primary_issue_type"),
        ticket.get("province_issue_type"),
        ticket.get("vendor"),
        ticket.get("system"),
        ticket.get("region"),
        ticket.get("band"),
    ]
    for value in issue_texts:
        norm = str(value or "").strip().lower()
        if norm:
            root_keys.add(norm)
    type3_texts = [text.lower() for text in _type3_texts(trace)]
    return {
        "root_keys": root_keys,
        "root_l2s": root_l2s,
        "type3_text": "\n".join(dict.fromkeys(type3_texts)),
    }


def _memory_root_fit(memory: dict[str, Any], action: dict[str, Any], selector_context: dict[str, Any]) -> float:
    root_keys = selector_context.get("root_keys") if isinstance(selector_context.get("root_keys"), set) else set()
    root_l2s = selector_context.get("root_l2s") if isinstance(selector_context.get("root_l2s"), set) else set()
    if not root_keys and not root_l2s:
        return 0.0
    content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
    scheme_group = _norm_text(action.get("scheme_group") or content.get("scheme_group"))
    values: set[str] = set()
    for key in ("root_causes", "solution_proxy_root_causes", "solution_proxy_root_cause", "primary_root_cause_inferred"):
        raw = content.get(key)
        if isinstance(raw, list):
            values.update(_norm_text(item) for item in raw if _norm_text(item))
        elif _norm_text(raw):
            values.add(_norm_text(raw))
    if scheme_group and scheme_group in root_l2s:
        return 1.0
    if values & root_keys:
        return 1.0
    if scheme_group and any(scheme_group in key for key in root_keys):
        return 0.8
    if values and any(value in key or key in value for value in values for key in root_keys):
        return 0.7
    return 0.0


def _type3_action_fit(action: dict[str, Any], selector_context: dict[str, Any]) -> float:
    text = str(selector_context.get("type3_text") or "")
    if not text:
        return 0.0
    fields = [
        action.get("scheme_group"),
        action.get("scheme_id"),
        action.get("param_cn_name"),
        action.get("parameter_semantic_id"),
        action.get("suggested_delta"),
        action.get("delta_bucket"),
        action.get("direction"),
    ]
    hits = 0
    possible = 0
    for value in fields:
        norm = _norm_text(value)
        if not norm:
            continue
        possible += 1
        if norm in text:
            hits += 1
    return _bounded(hits / possible) if possible else 0.0


def _package_selector_disabled_terms(policy: str) -> set[str]:
    if ":" not in policy:
        return set()
    raw_terms = policy.split(":", 1)[1]
    aliases = {
        "no_root": "root",
        "no_type3": "type3",
        "no_boundary": "boundary",
        "no_action_shape": "action_shape",
        "no_shape": "action_shape",
        "no_value": "value",
        "no_value_support": "value",
        "no_route": "route",
        "no_route_count": "route",
        "no_context": "context",
        "no_state": "state",
        "no_support": "support",
    }
    out: set[str] = set()
    for term in re.split(r"[,;+]", raw_terms):
        term = term.strip().lower()
        if not term:
            continue
        out.add(aliases.get(term, term))
    return out


def _package_candidate_features(
    item: dict[str, Any],
    trace: dict[str, Any],
    selector_context: dict[str, Any],
    *,
    disabled_terms: set[str] | None = None,
) -> dict[str, Any]:
    disabled_terms = disabled_terms or set()
    candidate = item.get("candidate") if isinstance(item.get("candidate"), dict) else {}
    memory = candidate.get("memory") if isinstance(candidate.get("memory"), dict) else {}
    action = item.get("action") if isinstance(item.get("action"), dict) else {}
    rank = item.get("rank") if isinstance(item.get("rank"), dict) else {}
    terms = rank.get("terms") if isinstance(rank.get("terms"), dict) else {}
    total = float(rank.get("total") or 0.0)
    route_count = float(terms.get("recall_route_count") or 0.0)
    value_support = max(
        float(terms.get("sample_value_lcb") or 0.0),
        float(terms.get("sample_value_coverage") or 0.0),
        float(terms.get("sample_action_lcb") or 0.0),
    )
    root_fit = _memory_root_fit(memory, action, selector_context)
    type3_fit = _type3_action_fit(action, selector_context)
    boundary = float(terms.get("boundary_match") or _memory_boundary_score(memory, trace))
    action_shape = float(terms.get("action_shape_match") or 0.0)
    context = float(terms.get("context_similarity") or 0.0)
    state = float(terms.get("memory_state") or _state_term(memory))
    support = float(terms.get("strategy_support") or 0.0)
    if "root" in disabled_terms:
        root_fit = 0.0
    if "type3" in disabled_terms:
        type3_fit = 0.0
    if "boundary" in disabled_terms:
        boundary = 0.0
    if "action_shape" in disabled_terms:
        action_shape = 0.0
    if "value" in disabled_terms:
        value_support = 0.0
    if "route" in disabled_terms:
        route_count = 0.0
    if "context" in disabled_terms:
        context = 0.0
    if "state" in disabled_terms:
        state = 0.0
    if "support" in disabled_terms:
        support = 0.0
    feature_score = (
        0.38 * total
        + 0.16 * context
        + 0.13 * root_fit
        + 0.10 * boundary
        + 0.10 * action_shape
        + 0.06 * value_support
        + 0.04 * route_count
        + 0.02 * state
        + 0.01 * support
        + 0.04 * type3_fit
    )
    return {
        "score": round(_bounded(feature_score), 6),
        "rank_total": round(total, 6),
        "context_similarity": round(context, 6),
        "root_fit": round(root_fit, 6),
        "type3_fit": round(type3_fit, 6),
        "boundary_match": round(boundary, 6),
        "action_shape_match": round(action_shape, 6),
        "value_support": round(value_support, 6),
        "route_count": round(route_count, 6),
        "memory_state": round(state, 6),
        "strategy_support": round(support, 6),
        "policy": "package_feature_selector_v2",
        "disabled_terms": sorted(disabled_terms),
    }


def _package_marginal_score(item: dict[str, Any], selected: list[dict[str, Any]]) -> float:
    features = item.get("package_selection_features") if isinstance(item.get("package_selection_features"), dict) else {}
    score = float(features.get("score") or 0.0)
    if not selected:
        return score
    action = item.get("action") if isinstance(item.get("action"), dict) else {}
    group = _action_group_key(action)
    slot = _action_slot_key(action)
    selected_groups = {
        _action_group_key(selected_item.get("action") or {})
        for selected_item in selected
        if _action_group_key(selected_item.get("action") or {})
    }
    selected_slots = {
        _action_slot_key(selected_item.get("action") or {})
        for selected_item in selected
    }
    if group and group in selected_groups:
        score += 0.05
    elif selected_groups and group:
        score -= 0.03
    if slot and slot not in selected_slots:
        score += 0.02
    if slot[1] and any(slot[1] != selected_slot[1] for selected_slot in selected_slots if selected_slot[1]):
        score += 0.02
    return score


def _select_complementary_actions(
    scored: list[dict[str, Any]],
    *,
    target_size: int,
    trace: dict[str, Any] | None = None,
    policy: str = "rank_order_unique_action_slot_v1",
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    selector_context = _trace_selector_context(trace or {})
    feature_enabled = "feature" in policy or policy.endswith("_v2")
    disabled_terms = _package_selector_disabled_terms(policy) if feature_enabled else set()
    if feature_enabled:
        scored = [
            {
                **item,
                "package_selection_features": _package_candidate_features(
                    item,
                    trace or {},
                    selector_context,
                    disabled_terms=disabled_terms,
                ),
            }
            for item in scored
        ]
        scored = sorted(
            scored,
            key=lambda item: (
                float((item.get("package_selection_features") or {}).get("score") or 0.0),
                float((item.get("rank") or {}).get("total") or 0.0),
            ),
            reverse=True,
        )
    selected: list[dict[str, Any]] = []
    seen_slots: set[tuple[str, str, str]] = set()
    seen_groups: set[str] = set()
    skipped: list[dict[str, Any]] = []
    remaining = list(enumerate(scored))
    skipped_indices: set[int] = set()
    while remaining and len(selected) < target_size:
        best_index: int | None = None
        best_item: dict[str, Any] | None = None
        best_score = -1.0
        for index, item in remaining:
            if index in skipped_indices:
                continue
            action = item.get("action") if isinstance(item.get("action"), dict) else {}
            if not action:
                skipped.append({"candidate_index": index, "reason": "empty_action"})
                skipped_indices.add(index)
                continue
            slot = _action_slot_key(action)
            if slot in seen_slots:
                skipped.append({"candidate_index": index, "reason": "duplicate_scheme_parameter_slot"})
                skipped_indices.add(index)
                continue
            marginal_score = (
                _package_marginal_score(item, selected)
                if feature_enabled
                else float((item.get("rank") or {}).get("total") or 0.0)
            )
            rank_total = float((item.get("rank") or {}).get("total") or 0.0)
            if (marginal_score, rank_total) > (
                best_score,
                float((best_item or {}).get("rank", {}).get("total") or -1.0),
            ):
                best_index = index
                best_item = item
                best_score = marginal_score
        if best_index is None or best_item is None:
            break
        item = best_item
        action = item.get("action") if isinstance(item.get("action"), dict) else {}
        slot = _action_slot_key(action)
        direction = _action_direction(action)
        conflict = False
        for selected_item in selected:
            selected_action = selected_item.get("action") or {}
            if slot != _action_slot_key(selected_action):
                continue
            pair = (_action_direction(selected_action), direction)
            if pair in _OPPOSITE_DIRECTIONS:
                conflict = True
                break
        if conflict:
            skipped.append({"candidate_index": best_index, "reason": "same_slot_opposite_direction"})
            skipped_indices.add(best_index)
            continue
        item = dict(item)
        item["package_selection_order"] = len(selected) + 1
        if feature_enabled:
            item["package_selection_marginal_score"] = round(best_score, 6)
        selected.append(item)
        seen_slots.add(slot)
        group = _action_group_key(action)
        if group:
            seen_groups.add(group)
        remaining = [(index, candidate) for index, candidate in remaining if index != best_index]
    if not selected and scored:
        fallback = dict(scored[0])
        fallback["package_selection_order"] = 1
        selected = [fallback]
    return selected, {
        "policy": policy if feature_enabled else "rank_order_unique_action_slot_v1",
        "feature_enabled": feature_enabled,
        "disabled_terms": sorted(disabled_terms),
        "target_size": target_size,
        "selected_count": len(selected),
        "selected_group_count": len(seen_groups),
        "skipped": skipped[:12],
        "candidate_features": [
            {
                "memory_id": ((item.get("candidate") or {}).get("memory") or {}).get("memory_id"),
                "scheme_id": (item.get("action") or {}).get("scheme_id"),
                "param_cn_name": (item.get("action") or {}).get("param_cn_name"),
                "features": item.get("package_selection_features") or {},
            }
            for item in scored[:12]
        ] if feature_enabled else [],
        "stop_reason": "target_size_reached" if len(selected) >= target_size else "candidate_pool_exhausted",
    }


def _aggregate_package_gate(
    selected: list[dict[str, Any]],
    *,
    use_gate_for_selection: bool,
) -> dict[str, Any]:
    if not selected:
        return _disabled_gate_for_action({})
    gates = [item.get("gate") if isinstance(item.get("gate"), dict) else {} for item in selected]
    if not use_gate_for_selection:
        return _disabled_gate_for_action(selected[0].get("action") or {})
    priority = {"reject": 4, "require_review": 3, "downgrade": 2, "accept": 1}
    worst = max(gates, key=lambda gate: priority.get(str(gate.get("gate_decision") or ""), 0))
    veto_ids: list[str] = []
    matches: list[dict[str, Any]] = []
    action_gate_decisions: list[dict[str, Any]] = []
    for item, gate in zip(selected, gates):
        for veto_id in gate.get("veto_ids") or []:
            if veto_id not in veto_ids:
                veto_ids.append(veto_id)
        matches.extend(gate.get("failcohort_matches") or [])
        action_gate_decisions.append({
            "selection_order": item.get("package_selection_order"),
            "memory_id": ((item.get("candidate") or {}).get("memory") or {}).get("memory_id"),
            "scheme_id": (item.get("action") or {}).get("scheme_id"),
            "param_cn_name": (item.get("action") or {}).get("param_cn_name"),
            "gate_decision": gate.get("gate_decision"),
            "gate_reason": gate.get("gate_reason"),
            "failcohort_hit_score": gate.get("failcohort_hit_score", 0.0),
        })
    hit_score = max((float(gate.get("failcohort_hit_score") or 0.0) for gate in gates), default=0.0)
    decision = str(worst.get("gate_decision") or "accept")
    out = dict(worst)
    out.update({
        "gate_decision": decision,
        "gate_reason": f"package_gate_worst_action:{decision}",
        "veto_hit": bool(veto_ids) or any(bool(gate.get("veto_hit")) for gate in gates),
        "veto_ids": veto_ids,
        "needs_human_review": any(bool(gate.get("needs_human_review")) for gate in gates),
        "risk_level": "high" if decision in {"reject", "require_review"} else "medium" if decision == "downgrade" else "low",
        "failcohort_hit_score": hit_score,
        "failcohort_matches": matches[:8],
        "package_gate": {
            "policy": "worst_selected_action_gate_v1",
            "selected_action_count": len(selected),
            "action_gate_decisions": action_gate_decisions,
        },
    })
    return out


def strategy_recall_compiled_knowledge_gate_decide(
    trace: dict[str, Any],
    memories: list[dict[str, Any]],
    *,
    artifacts: dict[str, Any],
    gate_config: dict[str, Any] | None = None,
    limit: int = 5,
    method_id: str = "pipeline_strategy_first_recall_compiled_rank_echo_gate",
    recall_mode: str = "strategy_first_recall",
    rank_variant: str = "no_outcome_counts",
    use_gate_for_selection: bool = True,
    use_action_value_selector: bool = False,
    use_sampled_strategy_evidence: bool = False,
    sample_evidence_policy: str = "raw_topn_samples",
    sample_evidence_limit: int = 3,
    multi_route_case_limit: int = 5,
    multi_route_strategy_limit: int = 5,
    value_selection_policy: str = "memory_child_statistics",
    gate_selection_policy: str = "rank_then_gate",
    use_package_selector: bool = False,
    package_selector_policy: str = "type3_soft_size_rank_unique_v1",
    package_selector_max_actions: int = 3,
) -> dict[str, Any]:
    cases = retrieve_cases(memories, trace, limit=limit)
    strategy_evidence_artifacts = artifacts if use_sampled_strategy_evidence else None
    if recall_mode == "case_to_strategy_recall":
        candidates = _case_to_strategy_candidates(cases, trace, artifacts, limit=limit)
    elif recall_mode == "strategy_first_recall":
        candidates = _strategy_first_candidates(
            memories,
            trace,
            artifacts=strategy_evidence_artifacts,
            sample_evidence_policy=sample_evidence_policy,
            sample_evidence_limit=sample_evidence_limit,
            limit=limit,
        )
    elif recall_mode == "hybrid_strategy_case_recall":
        candidates = _merge_strategy_candidates(
            _strategy_first_candidates(
                memories,
                trace,
                artifacts=strategy_evidence_artifacts,
                sample_evidence_policy=sample_evidence_policy,
                sample_evidence_limit=sample_evidence_limit,
                limit=limit,
            ),
            _case_to_strategy_candidates(cases, trace, artifacts, limit=limit),
            limit=limit,
        )
    elif recall_mode == "multi_route_strategy_recall":
        candidates = _multi_route_strategy_candidates(
            cases,
            memories,
            trace,
            artifacts,
            limit=limit,
            case_route_limit=multi_route_case_limit,
            strategy_route_limit=multi_route_strategy_limit,
            sample_evidence_policy=sample_evidence_policy,
            sample_evidence_limit=sample_evidence_limit,
        )
    else:
        raise ValueError(f"unknown strategy recall mode: {recall_mode}")

    scored: list[dict[str, Any]] = []
    gate_priority = {"accept": 3, "downgrade": 2, "require_review": 1, "reject": 0}
    for candidate in candidates:
        rank = _strategy_rank_score(candidate, trace, variant=rank_variant)
        action = candidate["action"]
        value_selection: dict[str, Any] = {
            "selected": False,
            "selection_policy": "disabled",
            "reason": "action_value_selector_disabled",
            "candidates": [],
        }
        if use_action_value_selector:
            action, value_selection = _strategy_value_selected_action(
                candidate,
                trace,
                value_selection_policy=value_selection_policy,
            )
        if use_gate_for_selection:
            gate = _gate_case_candidate(
                trace,
                action,
                artifacts,
                gate_config=gate_config,
                confidence=float(rank.get("total") or 0.0),
            )
            if gate_selection_policy != "gate_priority":
                selection_score = float(rank.get("total") or 0.0)
            else:
                selection_score = gate_priority.get(str(gate.get("gate_decision")), 0) + float(rank.get("total") or 0.0)
        else:
            gate = _disabled_gate_for_action(candidate["action"])
            selection_score = float(rank.get("total") or 0.0)
        scored.append({
            "candidate": candidate,
            "action": action,
            "rank": rank,
            "gate": gate,
            "value_selection": value_selection,
            "selection_score": selection_score,
        })
    if gate_selection_policy == "rank_then_gate":
        scored.sort(key=lambda item: (item["selection_score"], item["rank"]["total"]), reverse=True)
    else:
        scored.sort(key=lambda item: (item["selection_score"], item["rank"]["total"]), reverse=True)
    empty_gate = (
        _gate_case_candidate(trace, {}, artifacts, gate_config=gate_config, confidence=0.0)
        if use_gate_for_selection
        else _disabled_gate_for_action({})
    )
    fallback_selector: dict[str, Any] = {
        "enabled": False,
        "policy": gate_selection_policy,
        "selected_rank_index": 0,
        "top_rank_gate_decision": None,
        "fallback_used": False,
        "fallback_candidate_count": 0,
    }
    if scored and use_gate_for_selection and gate_selection_policy == "rank_then_safe_fallback":
        top = scored[0]
        accepted_gates = {"accept", "downgrade"}
        safe_candidates = [
            (idx, item)
            for idx, item in enumerate(scored)
            if str((item.get("gate") or {}).get("gate_decision") or "") in accepted_gates
        ]
        selected_idx, selected = safe_candidates[0] if safe_candidates else (0, top)
        best = selected
        fallback_selector = {
            "enabled": True,
            "policy": gate_selection_policy,
            "selected_rank_index": selected_idx,
            "top_rank_gate_decision": (top.get("gate") or {}).get("gate_decision"),
            "selected_gate_decision": (selected.get("gate") or {}).get("gate_decision"),
            "fallback_used": selected_idx != 0,
            "fallback_candidate_count": len(safe_candidates),
        }
    else:
        best = scored[0] if scored else {"candidate": {}, "action": {}, "rank": {"total": 0.0}, "gate": empty_gate}
    package_selector: dict[str, Any] = {
        "enabled": False,
        "policy": "none",
        "estimated_size": 1,
        "selected_action_count": 1 if best.get("action") else 0,
        "selected_memory_ids": [
            ((best.get("candidate") or {}).get("memory") or {}).get("memory_id")
        ] if best.get("action") else [],
    }
    selected_items = [best] if best.get("action") else []
    if use_package_selector:
        size_estimate = _estimate_package_size(
            trace,
            scored,
            max_actions=max(1, int(package_selector_max_actions or 1)),
            policy=package_selector_policy,
            memories=memories,
        )
        target_size = int(size_estimate.get("estimated_size") or 1)
        selected_items, selection_trace = _select_complementary_actions(
            scored,
            target_size=target_size,
            trace=trace,
            policy=package_selector_policy,
        )
        best = selected_items[0] if selected_items else best
        package_selector = {
            "enabled": True,
            "policy": package_selector_policy,
            "size_estimator": size_estimate,
            "selection": selection_trace,
            "estimated_size": target_size,
            "selected_action_count": len(selected_items),
            "selected_memory_ids": [
                ((item.get("candidate") or {}).get("memory") or {}).get("memory_id")
                for item in selected_items
                if ((item.get("candidate") or {}).get("memory") or {}).get("memory_id")
            ],
        }
    recommended_action_set = [item.get("action") or {} for item in selected_items if item.get("action")]
    package_gate = (
        _aggregate_package_gate(selected_items, use_gate_for_selection=use_gate_for_selection)
        if use_package_selector
        else best["gate"]
    )
    ordered_candidates = [item["candidate"] for item in scored]
    ordered_cases = _unique_cases(ordered_candidates)
    decision = _base_decision(
        trace,
        method_id,
        ordered_cases,
        best["action"],
        reason=(
            f"{recall_mode} ranked by compiled strategy knowledge ({rank_variant}); ECHO fail-cohort gate is applied after ranking."
            if use_gate_for_selection
            else f"{recall_mode} ranked by compiled strategy knowledge ({rank_variant}) with gate disabled."
        ),
        needs_review=bool(package_gate["needs_human_review"]),
    )
    gate = package_gate
    if recommended_action_set:
        decision["recommended_action_set"] = recommended_action_set
    decision["gate_decision"] = gate["gate_decision"]
    decision["gate_diagnostics"] = {
        "gate_policy": gate["gate_policy"],
        "gate_reason": gate["gate_reason"],
        "veto_hit": gate["veto_hit"],
        "veto_background_count": gate["veto_background_count"],
        "matched_veto_ids": gate["veto_ids"],
        "tau_low": gate.get("tau_low"),
        "tau_high": gate.get("tau_high"),
        "recommendation_confidence": gate.get("recommendation_confidence"),
        "threshold_band": gate.get("threshold_band"),
        "gate_config_version": gate.get("gate_config_version"),
        "failcohort_hit_score": gate.get("failcohort_hit_score", 0.0),
        "diagnostic_failcohort_hit_score": gate.get("diagnostic_failcohort_hit_score"),
        "diagnostic_veto_ids": gate.get("diagnostic_veto_ids") or [],
        "failcohort_matches": gate.get("failcohort_matches") or [],
        "veto_risk_calibration": gate.get("veto_risk_calibration") or {},
        "gray_zone_review": gate.get("gray_zone_review") or {},
        "hard_veto_eligible": gate.get("hard_veto_eligible"),
        "strong_action_veto_match": gate.get("strong_action_veto_match"),
        "package_gate": gate.get("package_gate") or {},
    }
    strategy_ids: list[str] = []
    playbook_ids: list[str] = []
    for item in scored:
        memory = item["candidate"]["memory"]
        memory_id = str(memory.get("memory_id") or "")
        if not memory_id:
            continue
        if memory.get("memory_type") == "playbook_memory" and memory_id not in playbook_ids:
            playbook_ids.append(memory_id)
        elif memory_id not in strategy_ids:
            strategy_ids.append(memory_id)
    decision["veto_hits"] = gate["veto_ids"]
    decision["veto_checked"] = True
    decision["risk_level"] = gate["risk_level"]
    decision["needs_human_review"] = gate["needs_human_review"]
    decision["selected_score_breakdown"] = best["rank"]
    decision["safe_fallback_selector"] = fallback_selector
    decision["package_selector"] = package_selector
    decision["supporting_knowledge"]["strategy_memory_ids"] = strategy_ids
    decision["supporting_knowledge"]["playbook_memory_ids"] = playbook_ids
    decision["supporting_knowledge"]["veto_memory_ids"] = gate["veto_ids"]
    decision["supporting_knowledge"]["strategy_recall_mode"] = recall_mode
    selected_order_by_memory_id = {
        str(((item.get("candidate") or {}).get("memory") or {}).get("memory_id") or ""): item.get("package_selection_order")
        for item in selected_items
    }
    decision["supporting_knowledge"]["candidate_scores"] = [
        {
            "memory_id": item["candidate"]["memory"].get("memory_id"),
            "memory_type": item["candidate"]["memory"].get("memory_type"),
            "rank_score": item["rank"]["total"],
            "score_breakdown": item["rank"],
            "gate_decision": item["gate"].get("gate_decision"),
            "gate_reason": item["gate"].get("gate_reason"),
            "failcohort_hit_score": item["gate"].get("failcohort_hit_score", 0.0),
            "credibility_mode": f"strategy_recall:{recall_mode}:{rank_variant}",
            "source_case_memory_ids": [
                case.get("memory_id")
                for case in item["candidate"].get("source_cases") or []
                if case.get("memory_id")
            ],
            "source_episode_ids": [
                episode.get("episode_id")
                for episode in item["candidate"].get("related_episodes") or []
                if episode.get("episode_id")
            ],
            "evidence_assembly": item["candidate"].get("evidence_assembly") or {},
            "value_selection": item.get("value_selection") or {},
            "selected_for_package": str(item["candidate"]["memory"].get("memory_id") or "") in selected_order_by_memory_id,
            "selected_by_safe_fallback": (
                fallback_selector.get("enabled")
                and str(item["candidate"]["memory"].get("memory_id") or "") == str(((best.get("candidate") or {}).get("memory") or {}).get("memory_id") or "")
            ),
            "package_selection_order": selected_order_by_memory_id.get(str(item["candidate"]["memory"].get("memory_id") or "")),
            "package_selection_features": item.get("package_selection_features") or {},
        }
        for item in scored
    ]
    decision["produced_by"] = method_id
    decision["pipeline"] = {
        "recall": recall_mode,
        "evidence": "strategy_case_episode_evidence",
        "rank": f"compiled_strategy_knowledge_rank_v1:{rank_variant}",
        "gate": "echo_failcohort_gate_v4" if use_gate_for_selection else "none",
        "gate_selection_policy": gate_selection_policy if use_gate_for_selection else "none",
        "value_selection": "echo_action_value_selector" if use_action_value_selector else "none",
        "value_selection_policy": value_selection_policy if use_action_value_selector else "none",
        "package_selection": package_selector_policy if use_package_selector else "none",
        "package_gate": "package_echo_failcohort_gate_v4" if use_package_selector and use_gate_for_selection else "none",
    }
    return decision


def _decision_rank_total(decision: dict[str, Any]) -> float:
    score = decision.get("selected_score_breakdown")
    if isinstance(score, dict):
        return float(score.get("total") or 0.0)
    return 0.0


def _decision_rank_term(decision: dict[str, Any], term: str) -> float:
    score = decision.get("selected_score_breakdown")
    if not isinstance(score, dict):
        return 0.0
    terms = score.get("terms")
    if not isinstance(terms, dict):
        return 0.0
    return float(terms.get(term) or 0.0)


def bridge_multi_route_guarded_selector_decide(
    trace: dict[str, Any],
    memories: list[dict[str, Any]],
    *,
    artifacts: dict[str, Any],
    gate_config: dict[str, Any] | None = None,
    method_id: str = "pipeline_bridge_multi_route_guarded_selector_echo_gate",
) -> dict[str, Any]:
    """Dev-only branch selector over the current bridge and guarded multi-route pipelines."""
    bridge = strategy_recall_compiled_knowledge_gate_decide(
        trace,
        memories,
        artifacts=artifacts,
        gate_config=gate_config,
        limit=5,
        method_id=f"{method_id}:bridge",
        recall_mode="case_to_strategy_recall",
        rank_variant="no_outcome_counts",
        use_gate_for_selection=True,
        gate_selection_policy="rank_then_gate",
    )
    guarded = strategy_recall_compiled_knowledge_gate_decide(
        trace,
        memories,
        artifacts=artifacts,
        gate_config=gate_config,
        limit=8,
        method_id=f"{method_id}:multi_route_guarded",
        recall_mode="multi_route_strategy_recall",
        rank_variant="multi_route_bridge_guarded",
        use_gate_for_selection=True,
        sample_evidence_policy="no_samples",
        multi_route_case_limit=5,
        multi_route_strategy_limit=5,
        gate_selection_policy="rank_then_gate",
    )
    bridge_rank = _decision_rank_total(bridge)
    guarded_rank = _decision_rank_total(guarded)
    guarded_action_shape = _decision_rank_term(guarded, "action_shape_match")
    use_guarded = (
        guarded_action_shape >= 1.0
        and guarded_rank >= bridge_rank + 0.05
    )
    selected_branch = "multi_route_guarded" if use_guarded else "bridge"
    selected = guarded if use_guarded else bridge
    decision = deepcopy(selected)
    decision["decision_id"] = _decision_id(trace, method_id)
    decision["produced_by"] = method_id
    decision["decision_reason"] = (
        "Bridge-vs-multi-route guarded selector: keep case->strategy bridge unless "
        "the multi-route guarded branch has complete action shape and is at least "
        "0.05 rank points stronger; gate is applied after branch selection."
    )
    supporting = decision.setdefault("supporting_knowledge", {})
    supporting["branch_selector"] = {
        "policy": "bridge_default_multi_route_guarded_rank_margin_v2",
        "selected_branch": selected_branch,
        "bridge": {
            "decision_id": bridge.get("decision_id"),
            "gate_decision": bridge.get("gate_decision"),
            "rank_total": round(bridge_rank, 6),
        },
        "multi_route_guarded": {
            "decision_id": guarded.get("decision_id"),
            "gate_decision": guarded.get("gate_decision"),
            "rank_total": round(guarded_rank, 6),
            "action_shape_match": round(guarded_action_shape, 6),
        },
        "margin": 0.05,
    }
    decision["pipeline"] = {
        "recall": "bridge_multi_route_guarded_selector",
        "evidence": "multi_route_strategy_evidence",
        "rank": "compiled_strategy_knowledge_rank_v1:bridge_multi_route_guarded_selector",
        "gate": "echo_failcohort_gate_v4",
        "gate_selection_policy": "rank_then_gate",
        "value_selection": "none",
        "value_selection_policy": "none",
    }
    return decision


def case_retrieval_decide(trace: dict[str, Any], memories: list[dict[str, Any]], *, limit: int = 5) -> dict[str, Any]:
    cases = retrieve_cases(memories, trace, limit=limit)
    action = _case_action(cases[0]) if cases else {}
    decision = _base_decision(
        trace,
        "case_retrieval",
        cases,
        action,
        reason="Top-1 context-similar train case action; outcome and veto signals are not used.",
    )
    decision["pipeline"] = {
        "recall": "case_retrieval_top1",
        "rank": "none",
        "gate": "none",
    }
    return decision


def _normalize_llm_action(payload: dict[str, Any]) -> dict[str, Any]:
    raw = payload.get("recommended_action") if isinstance(payload.get("recommended_action"), dict) else payload
    keys = (
        "scheme_group",
        "scheme_id",
        "parameter_semantic_id",
        "param_cn_name",
        "value_type",
        "direction",
        "suggested_delta",
        "value_pattern_id",
    )
    action = {key: str(raw.get(key) or "").strip() for key in keys}
    if not any(action[key] for key in ("scheme_group", "scheme_id", "parameter_semantic_id", "param_cn_name")):
        return {}
    return action


def _as_bool(value: Any) -> bool:
    if isinstance(value, bool):
        return value
    return str(value or "").strip().lower() in {"1", "true", "yes"}


def rag_llm_decide(
    trace: dict[str, Any],
    memories: list[dict[str, Any]],
    *,
    llm_client: Any,
    limit: int = 5,
) -> dict[str, Any]:
    if llm_client is None:
        raise RuntimeError("rag_llm requires an explicit LLM client")
    cases = retrieve_cases(memories, trace, limit=limit)
    system = RAG_PROMPT_PATH.read_text(encoding="utf-8")
    user_payload = {
        "current_context": safe_decision_context(trace),
        "retrieved_train_cases": [safe_case_document(case) for case in cases],
    }
    user = json.dumps(user_payload, ensure_ascii=False, sort_keys=True)
    lowered = user.lower()
    leaked = sorted(key for key in FORBIDDEN_RAG_KEYS if re.search(rf'"{re.escape(key.lower())}"\s*:', lowered))
    if leaked:
        raise ValueError(f"forbidden RAG fields leaked into prompt: {leaked}")
    try:
        response = llm_client.complete_json(system, user, response_schema=RAG_RESPONSE_SCHEMA)
    except Exception as exc:
        decision = _base_decision(
            trace,
            "rag_llm",
            cases,
            {},
            reason="RAG+LLM generation failed; no fallback action was emitted.",
            needs_review=True,
        )
        decision["llm_error"] = {
            "type": type(exc).__name__,
            "message": str(exc)[:300],
        }
        decision["llm_attempt_count"] = int(getattr(llm_client, "last_json_attempt_count", 1) or 1)
        decision["pipeline"] = {
            "recall": "case_retrieval_topk",
            "rank": "llm_selector",
            "gate": "none",
        }
        return decision
    action = _normalize_llm_action(response)
    needs_review = _as_bool(response.get("needs_human_review"))
    decision = _base_decision(
        trace,
        "rag_llm",
        cases,
        action,
        reason=str(response.get("rationale") or "RAG+LLM baseline response"),
        needs_review=needs_review,
    )
    decision["llm_error"] = None
    decision["llm_attempt_count"] = int(getattr(llm_client, "last_json_attempt_count", 1) or 1)
    decision["pipeline"] = {
        "recall": "case_retrieval_topk",
        "rank": "llm_selector",
        "gate": "none",
    }
    return decision


def llm_only_decide(
    trace: dict[str, Any],
    *,
    llm_client: Any,
) -> dict[str, Any]:
    if llm_client is None:
        raise RuntimeError("llm_only requires an explicit LLM client")
    system = LLM_ONLY_PROMPT_PATH.read_text(encoding="utf-8")
    user_payload = {
        "current_context": safe_decision_context(trace),
    }
    user = json.dumps(user_payload, ensure_ascii=False, sort_keys=True)
    lowered = user.lower()
    leaked = sorted(key for key in FORBIDDEN_RAG_KEYS if re.search(rf'"{re.escape(key.lower())}"\s*:', lowered))
    if leaked:
        raise ValueError(f"forbidden LLM-only fields leaked into prompt: {leaked}")
    try:
        response = llm_client.complete_json(system, user, response_schema=RAG_RESPONSE_SCHEMA)
    except Exception as exc:
        decision = _base_decision(
            trace,
            "llm_only",
            [],
            {},
            reason="LLM-only generation failed; no fallback action was emitted.",
            needs_review=True,
        )
        decision["llm_error"] = {
            "type": type(exc).__name__,
            "message": str(exc)[:300],
        }
        decision["llm_attempt_count"] = int(getattr(llm_client, "last_json_attempt_count", 1) or 1)
        decision["pipeline"] = {
            "recall": "none",
            "evidence": "llm_prompt_context",
            "rank": "llm_selector",
            "gate": "none",
        }
        return decision
    action = _normalize_llm_action(response)
    needs_review = _as_bool(response.get("needs_human_review"))
    decision = _base_decision(
        trace,
        "llm_only",
        [],
        action,
        reason=str(response.get("rationale") or "LLM-only baseline response"),
        needs_review=needs_review,
    )
    decision["llm_error"] = None
    decision["llm_attempt_count"] = int(getattr(llm_client, "last_json_attempt_count", 1) or 1)
    decision["pipeline"] = {
        "recall": "none",
        "evidence": "llm_prompt_context",
        "rank": "llm_selector",
        "gate": "none",
    }
    return decision

