def load_config_ref(ref: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(ref, dict) or not ref.get("path"):
        return None
    path = _project_path(str(ref["path"]))
    if path.suffix.lower() != ".json":
        return None
    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise ValueError(f"config must be a JSON object: {path}")
    return value


def _latest_memory_package(path: Path) -> Path:
    if path.resolve() != P.MEMORY_PKG_EXPORTS.resolve() or not path.exists():
        return path
    manifests = sorted(path.glob("*/manifest.json"), key=lambda item: item.stat().st_mtime, reverse=True)
    return manifests[0].parent if manifests else path


def _git_snapshot() -> tuple[str | None, bool]:
    try:
        commit = subprocess.run(
            ["git", "rev-parse", "HEAD"],
            cwd=P.PROJECT_ROOT,
            check=True,
            capture_output=True,
            text=True,
        ).stdout.strip()
        dirty = bool(subprocess.run(
            ["git", "status", "--porcelain"],
            cwd=P.PROJECT_ROOT,
            check=True,
            capture_output=True,
            text=True,
        ).stdout.strip())
        return commit or None, dirty
    except Exception:
        return None, True


def _code_tree_hash() -> str:
    digest = hashlib.sha256()
    roots = ["pipeline", "experiments", "schemas", "prompts"]
    files = []
    for root in roots:
        path = P.PROJECT_ROOT / root
        if path.exists():
            files.extend(
                item for item in path.rglob("*")
                if item.is_file()
                and "__pycache__" not in item.parts
                and not item.relative_to(P.PROJECT_ROOT).as_posix().startswith("experiments/results/")
            )
    dependency = P.PROJECT_ROOT / "api" / "requirements.txt"
    if dependency.exists():
        files.append(dependency)
    for path in sorted(set(files)):
        relative = path.relative_to(P.PROJECT_ROOT).as_posix()
        digest.update(relative.encode("utf-8"))
        digest.update(b"\0")
        digest.update(file_sha256(path).encode("ascii"))
        digest.update(b"\n")
    return digest.hexdigest()


def resolve_experiment_spec(spec: dict[str, Any]) -> dict[str, Any]:
    """Resolve paths and hashes before validation and execution."""
    resolved = deepcopy(spec)
    artifacts = resolved.get("artifacts") if isinstance(resolved.get("artifacts"), dict) else {}
    for name, ref in artifacts.items():
        if not isinstance(ref, dict) or not ref.get("path"):
            continue
        path = _project_path(str(ref["path"]))
        if name == "memory_package":
            path = _latest_memory_package(path)
            if path != _project_path(str(ref["path"])):
                ref["path"] = str(path.relative_to(P.PROJECT_ROOT))
                ref["id"] = ref.get("id") or path.name
        if path.exists():
            ref["sha256"] = path_sha256(path)

    configs = resolved.get("configs") if isinstance(resolved.get("configs"), dict) else {}
    for name in ("ranker", "gate"):
        ref = configs.get(name)
        if isinstance(ref, dict) and ref.get("path"):
            path = _project_path(str(ref["path"]))
            if path.exists():
                ref["sha256"] = path_sha256(path)
    llm = configs.get("llm")
    if isinstance(llm, dict) and llm.get("prompt_path"):
        prompt_path = _project_path(str(llm["prompt_path"]))
        if prompt_path.exists():
            llm["prompt_hash"] = path_sha256(prompt_path)

    reproducibility = resolved.get("reproducibility") if isinstance(resolved.get("reproducibility"), dict) else {}
    dependency_path = reproducibility.get("dependency_lock_path")
    if dependency_path:
        path = _project_path(str(dependency_path))
        if path.exists():
            reproducibility["dependency_lock_hash"] = path_sha256(path)
    commit, dirty = _git_snapshot()
    reproducibility["code_commit"] = commit
    reproducibility["code_dirty"] = dirty
    reproducibility["code_tree_hash"] = _code_tree_hash()
    sample = resolved.get("sample") if isinstance(resolved.get("sample"), dict) else {}
    dataset_role = resolved.get("dataset_role")
    if dataset_role in {"dev", "holdout", "eval_set_a"} and sample.get("policy"):
        traces = select_dataset_traces(
            load_dataset_traces(dataset_role),
            policy=sample["policy"],
            limit=int(sample.get("limit") or 0) or None,
        )
        sample["trace_ids_hash"] = trace_ids_sha256(traces)
    return resolved


def load_experiment_spec(path: Path | str) -> dict[str, Any]:
    spec = resolve_experiment_spec(json.loads(Path(path).read_text(encoding="utf-8")))
    errors = validate(spec, "experiment_spec")
    if errors:
        raise ValueError("invalid ExperimentSpec: " + "; ".join(errors))
    return spec


def _safe_run_id(spec: dict[str, Any], spec_hash: str, created_at: str) -> str:
    timestamp = created_at.replace("-", "").replace(":", "").replace("+00:00", "Z")
    raw = f"{spec['experiment_id']}_{spec['dataset_role']}_{spec_hash[:12]}_{timestamp}"
    return "".join(ch if ch.isalnum() or ch in {"-", "_", "."} else "_" for ch in raw)


def _write_json(path: Path, value: Any) -> None:
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2, default=str) + "\n", encoding="utf-8")


def _file_ref(path: Path, run_dir: Path) -> dict[str, Any]:
    return {
        "path": str(path.relative_to(run_dir)),
        "sha256": file_sha256(path),
        "bytes": path.stat().st_size,
    }


def _strip_volatile_replay_fields(value: Any) -> Any:
    if isinstance(value, dict):
        return {
            key: _strip_volatile_replay_fields(item)
            for key, item in value.items()
            if key not in VOLATILE_REPLAY_KEYS
        }
    if isinstance(value, list):
        return [_strip_volatile_replay_fields(item) for item in value]
    return value


def replay_semantic_sha256(replay_logs: list[dict[str, Any]]) -> str:
    return canonical_sha256(_strip_volatile_replay_fields(replay_logs))


def _method_result(result: dict[str, Any]) -> dict[str, Any]:
    summary = result.get("summary") if isinstance(result.get("summary"), dict) else {}
    return {
        "method_id": str(result.get("method_id") or ""),
        "trace_count": int(result.get("trace_count") or 0),
        "summary": summary,
        "metric_counts": summary.get("metric_counts") or {},
        "semantic_sha256": replay_semantic_sha256(result.get("replay_logs") or []),
    }


def _llm_client_for_spec(spec: dict[str, Any]) -> None:
    requires_llm = any(get_method_spec(method_id).get("requires_llm") for method_id in spec["method_ids"])
    if not requires_llm:
        return None
    raise ValueError(
        "LLM and non-ECHO methods are frozen references, not executable "
        "targets of this reproduction artifact"
    )


def _method_requires_shadow_artifacts(method_id: str) -> bool:
    """Return whether a method consumes ECHO-Mem package artifacts at decision time."""
    spec = get_method_spec(method_id)
    execution_kind = str(spec.get("execution_kind") or "")
    if execution_kind in {
        "case_retrieval",
        "case_retrieval_similarity_abstention",
        "case_retrieval_bm25_tfidf",
        "modern_neural_hybrid_retrieval_reranker",
        "supervised_ltr_selective_ranker_no_echo",
        "llm_only",
    }:
        return False
    return True


def _load_parameter_snapshot_sidecar(path: Path) -> dict[str, dict[str, Any]]:
    if not path.exists():
        return {}
    records: list[dict[str, Any]]
    if path.suffix.lower() == ".jsonl":
        records = list(cio.read_jsonl(path))
    else:
        payload = json.loads(path.read_text(encoding="utf-8"))
        if isinstance(payload, dict) and isinstance(payload.get("snapshots"), list):
            records = payload["snapshots"]
        elif isinstance(payload, list):
            records = payload
        else:
            records = []
    out: dict[str, dict[str, Any]] = {}
    for record in records:
        if not isinstance(record, dict):
            continue
        trace_id = str(record.get("trace_id") or "")
        snapshot = record.get("pre_decision_parameter_snapshot")
        if trace_id and isinstance(snapshot, dict):
            out[trace_id] = snapshot
    return out


def _attach_optional_artifacts(shared_artifacts: dict[str, Any], spec: dict[str, Any]) -> dict[str, Any]:
    artifacts = spec.get("artifacts") if isinstance(spec.get("artifacts"), dict) else {}
    snapshot_ref = artifacts.get("parameter_snapshots")
    if isinstance(snapshot_ref, dict) and snapshot_ref.get("path"):
        path = _project_path(str(snapshot_ref["path"]))
        snapshots = _load_parameter_snapshot_sidecar(path)
        shared_artifacts = dict(shared_artifacts)
        shared_artifacts["pre_decision_parameter_snapshots_by_trace_id"] = snapshots
        shared_artifacts["pre_decision_parameter_snapshot_artifact"] = {
            "path": str(path.relative_to(P.PROJECT_ROOT)) if path.is_absolute() and path.is_relative_to(P.PROJECT_ROOT) else str(path),
            "count": len(snapshots),
            "policy": "train_only_time_prior_cell_parameter_state",
        }
    return shared_artifacts


def compare_run_artifacts(left: dict[str, Any], right: dict[str, Any]) -> dict[str, Any]:
    """Compare paper-relevant deterministic outputs from two runs."""
    left_methods = {item["method_id"]: item for item in left.get("method_results") or []}
    right_methods = {item["method_id"]: item for item in right.get("method_results") or []}
    method_ids = sorted(set(left_methods) | set(right_methods))
    comparisons = []
    for method_id in method_ids:
        left_method = left_methods.get(method_id) or {}
        right_method = right_methods.get(method_id) or {}
        comparisons.append({
            "method_id": method_id,
            "present_in_both": bool(left_method and right_method),
            "trace_count_equal": left_method.get("trace_count") == right_method.get("trace_count"),
            "summary_equal": left_method.get("summary") == right_method.get("summary"),
            "semantic_replay_equal": left_method.get("semantic_sha256") == right_method.get("semantic_sha256"),
        })
    ok = bool(comparisons) and all(
        item["present_in_both"]
        and item["trace_count_equal"]
        and item["summary_equal"]
        and item["semantic_replay_equal"]
        for item in comparisons
    )
    return {
        "ok": ok,
        "same_experiment_spec": left.get("experiment_spec_hash") == right.get("experiment_spec_hash"),
        "methods": comparisons,
    }


def run_experiment(
    spec: dict[str, Any],
    *,
    manifest_path: Path | str = DEFAULT_MANIFEST,
    runs_dir: Path | str = DEFAULT_RUNS_DIR,
    artifacts: dict[str, Any] | None = None,
) -> tuple[dict[str, Any], Path]:
    """Run one ExperimentSpec and persist an immutable RunArtifact directory."""
    spec = resolve_experiment_spec(spec)
    spec_errors = validate(spec, "experiment_spec")
    if spec_errors:
        raise ValueError("invalid ExperimentSpec: " + "; ".join(spec_errors))

    readiness = build_dry_run_report(manifest_path=Path(manifest_path))
    if not readiness.get("ok"):
        raise RuntimeError("experiment readiness checks failed")

    created_at = datetime.now(timezone.utc).isoformat(timespec="seconds")
    spec_hash = canonical_sha256(spec)
    run_id = _safe_run_id(spec, spec_hash, created_at)
    runs_root = Path(runs_dir)
    final_dir = runs_root / run_id
    temp_dir = runs_root / f".{run_id}.tmp"
    if final_dir.exists() or temp_dir.exists():
        raise FileExistsError(f"run directory already exists: {final_dir}")

    temp_dir.mkdir(parents=True, exist_ok=False)
    try:
        package_path = _project_path(spec["artifacts"]["memory_package"]["path"])
        if artifacts is not None:
            shared_artifacts = artifacts
        elif any(_method_requires_shadow_artifacts(method_id) for method_id in spec["method_ids"]):
            shared_artifacts = load_shadow_artifacts(package_path)
        else:
            shared_artifacts = {}
        shared_artifacts = _attach_optional_artifacts(shared_artifacts, spec)
        llm_client = _llm_client_for_spec(spec)
        ranker_config = load_config_ref(spec["configs"].get("ranker"))
        gate_config = load_config_ref(spec["configs"].get("gate"))
        results = [
            replay_dataset(
                dataset_role=spec["dataset_role"],
                method_id=method_id,
                limit=int(spec["sample"]["limit"]) or None,
                sample_policy=spec["sample"]["policy"],
                artifacts=shared_artifacts,
                llm_client=llm_client,
                ranker_config=ranker_config,
                gate_config=gate_config,
            )
            for method_id in spec["method_ids"]
        ]

        spec_path = temp_dir / "spec.json"
        readiness_path = temp_dir / "readiness.json"
        summary_path = temp_dir / "summary.json"
        samples_path = temp_dir / "samples.jsonl"
        _write_json(spec_path, spec)
        _write_json(readiness_path, readiness)
        _write_json(summary_path, {"methods": [_method_result(result) for result in results]})
        cio.write_jsonl(
            samples_path,
            (
                {**sample, "method_id": result["method_id"]}
                for result in results
                for sample in result.get("replay_logs") or []
            ),
        )

        files = {
            "spec": _file_ref(spec_path, temp_dir),
            "readiness": _file_ref(readiness_path, temp_dir),
            "summary": _file_ref(summary_path, temp_dir),
            "samples": _file_ref(samples_path, temp_dir),
        }
        completed_at = datetime.now(timezone.utc).isoformat(timespec="seconds")
        artifact = {
            "schema_version": "run_artifact.v1",
            "run_id": run_id,
            "status": "completed",
            "created_at": created_at,
            "completed_at": completed_at,
            "experiment_spec_hash": spec_hash,
            "readiness": {
                "ok": bool(readiness.get("ok")),
                "checks": readiness.get("checks") or {},
            },
            "method_results": [_method_result(result) for result in results],
            "files": files,
            "failure": None,
        }
        artifact_errors = validate(artifact, "run_artifact")
        if artifact_errors:
            raise ValueError("invalid RunArtifact: " + "; ".join(artifact_errors))
        _write_json(temp_dir / "artifact_manifest.json", artifact)
        temp_dir.replace(final_dir)
        return artifact, final_dir
    except Exception:
        shutil.rmtree(temp_dir, ignore_errors=True)
        raise

"""Build or activate train/dev/holdout splits at TraceRecord granularity.

The legacy path can split raw source files by time/ratio. The current paper
data path activates fixed raw split files under data/raw/{train,dev,holdout}.csv
and writes TraceRecord caches under data/staged/splits/.
"""

from __future__ import annotations

import argparse
import json
import shutil
import subprocess
import sys
from datetime import datetime
from pathlib import Path
from typing import Any

from ..common import io as cio
from ..common import paths as P


DEFAULT_TRAIN_RATIO = 0.70
DEFAULT_DEV_RATIO = 0.10
DEFAULT_HOLDOUT_RATIO = 0.20


def _parse_time(value: Any) -> tuple[int, str]:
    if value in (None, ""):
        return (1, "")
    text = str(value).strip()
    if not text:
        return (1, "")
    normalized = text.replace("Z", "+00:00")
    try:
        return (0, datetime.fromisoformat(normalized).isoformat())
    except ValueError:
        return (0, text)


def trace_sort_key(trace: dict[str, Any]) -> tuple:
    ticket = trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}
    source = trace.get("source") if isinstance(trace.get("source"), dict) else {}
    issued_rank, issued_value = _parse_time(ticket.get("issued_at"))
    ingested_rank, ingested_value = _parse_time(source.get("ingested_at"))
    return (
        issued_rank,
        issued_value,
        ingested_rank,
        ingested_value,
        str(trace.get("trace_id") or ""),
    )


def _range_meta(traces: list[dict[str, Any]]) -> dict[str, Any]:
    if not traces:
        return {"count": 0, "first_trace_id": None, "last_trace_id": None, "first_issued_at": None, "last_issued_at": None}
    first = traces[0]
    last = traces[-1]
    first_ticket = first.get("ticket") if isinstance(first.get("ticket"), dict) else {}
    last_ticket = last.get("ticket") if isinstance(last.get("ticket"), dict) else {}
    return {
        "count": len(traces),
        "first_trace_id": first.get("trace_id"),
        "last_trace_id": last.get("trace_id"),
        "first_issued_at": first_ticket.get("issued_at"),
        "last_issued_at": last_ticket.get("issued_at"),
    }


def _range_meta_from_path(path: Path) -> tuple[list[str], dict[str, Any]]:
    ids: list[str] = []
    first: dict[str, Any] | None = None
    last: dict[str, Any] | None = None
    for trace in cio.read_jsonl(path):
        if first is None:
            first = trace
        last = trace
        if trace.get("trace_id"):
            ids.append(str(trace.get("trace_id")))
    if first is None or last is None:
        return ids, {
            "count": 0,
            "first_trace_id": None,
            "last_trace_id": None,
            "first_issued_at": None,
            "last_issued_at": None,
        }
    first_ticket = first.get("ticket") if isinstance(first.get("ticket"), dict) else {}
    last_ticket = last.get("ticket") if isinstance(last.get("ticket"), dict) else {}
    return ids, {
        "count": len(ids),
        "first_trace_id": first.get("trace_id"),
        "last_trace_id": last.get("trace_id"),
        "first_issued_at": first_ticket.get("issued_at"),
        "last_issued_at": last_ticket.get("issued_at"),
    }


def _validate_ratios(train_ratio: float, dev_ratio: float, holdout_ratio: float) -> None:
    vals = [train_ratio, dev_ratio, holdout_ratio]
    if any(v < 0 for v in vals):
        raise ValueError("split ratios must be non-negative")
    total = sum(vals)
    if abs(total - 1.0) > 1e-6:
        raise ValueError(f"split ratios must sum to 1.0, got {total:.6f}")
    if train_ratio <= 0 or holdout_ratio <= 0:
        raise ValueError("train and holdout ratios must be > 0")


def split_traces(
    traces: list[dict[str, Any]],
    *,
    train_ratio: float = DEFAULT_TRAIN_RATIO,
    dev_ratio: float = DEFAULT_DEV_RATIO,
    holdout_ratio: float = DEFAULT_HOLDOUT_RATIO,
) -> dict[str, list[dict[str, Any]]]:
    _validate_ratios(train_ratio, dev_ratio, holdout_ratio)
    ordered = sorted(traces, key=trace_sort_key)
    total = len(ordered)
    train_end = int(total * train_ratio)
    dev_end = train_end + int(total * dev_ratio)
    if total > 0:
        train_end = max(1, train_end)
        dev_end = max(train_end, dev_end)
        dev_end = min(dev_end, total)
    return {
        "train": ordered[:train_end],
        "dev": ordered[train_end:dev_end],
        "holdout": ordered[dev_end:],
    }


def build_split_manifest(
    splits: dict[str, list[dict[str, Any]]],
    *,
    split_policy: str,
    source_trace_path: Path,
    train_ratio: float,
    dev_ratio: float,
    holdout_ratio: float,
    dataset: str,
) -> dict[str, Any]:
    train_ids = [str(t.get("trace_id")) for t in splits["train"] if t.get("trace_id")]
    dev_ids = [str(t.get("trace_id")) for t in splits["dev"] if t.get("trace_id")]
    holdout_ids = [str(t.get("trace_id")) for t in splits["holdout"] if t.get("trace_id")]
    return {
        "split_id": f"time_v1_{int(train_ratio * 100)}_{int(dev_ratio * 100)}_{int(holdout_ratio * 100)}",
        "split_policy": split_policy,
        "dataset": dataset,
        "source_trace_path": str(source_trace_path),
        "ratios": {
            "train": train_ratio,
            "dev": dev_ratio,
            "holdout": holdout_ratio,
        },
        "trace_count": len(train_ids) + len(dev_ids) + len(holdout_ids),
        "train_trace_ids": train_ids,
        "dev_trace_ids": dev_ids,
        "holdout_trace_ids": holdout_ids,
        "ranges": {
            "train": _range_meta(splits["train"]),
            "dev": _range_meta(splits["dev"]),
            "holdout": _range_meta(splits["holdout"]),
        },
        "outputs": {
            "train": str(P.TRAIN_TRACE_RECORDS_JSONL),
            "dev": str(P.DEV_TRACE_RECORDS_JSONL),
            "holdout": str(P.HOLDOUT_TRACE_RECORDS_JSONL),
        },
        "leakage_policy": {
            "memory_compile_split": "train",
            "forbidden_memory_trace_splits": ["dev", "holdout", "eval_set_a"],
        },
        "created_at": cio.now_iso(),
    }


def write_split_outputs(
    splits: dict[str, list[dict[str, Any]]],
    manifest: dict[str, Any],
    *,
    out_split: Path = P.TIME_SPLIT_JSON,
) -> None:
    cio.write_jsonl(P.TRAIN_TRACE_RECORDS_JSONL, splits["train"])
    cio.write_jsonl(P.DEV_TRACE_RECORDS_JSONL, splits["dev"])
    cio.write_jsonl(P.HOLDOUT_TRACE_RECORDS_JSONL, splits["holdout"])
    out_split.parent.mkdir(parents=True, exist_ok=True)
    out_split.write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")


def refresh_source_traces(*, source: str, out: Path, dataset: str | None = None) -> None:
    cmd = [
        sys.executable,
        "-m",
        "pipeline.ingest.load_traces",
        "--xlsx",
        source,
        "--out",
        str(out),
    ]
    if dataset:
        cmd.extend(["--dataset", dataset])
    print(f"$ {' '.join(cmd)}", file=sys.stderr)
    result = subprocess.run(cmd)
    if result.returncode != 0:
        raise SystemExit(result.returncode)


def _run_ingest(source: Path, out: Path, *, dataset: str) -> None:
    cmd = [
        sys.executable,
        "-m",
        "pipeline.ingest.load_traces",
        "--xlsx",
        str(source),
        "--out",
        str(out),
        "--dataset",
        dataset,
    ]
    print(f"$ {' '.join(cmd)}", file=sys.stderr)
    result = subprocess.run(cmd)
    if result.returncode != 0:
        raise SystemExit(result.returncode)


def _read_raw_split_manifest() -> dict[str, Any]:
    if not P.DATA_RAW_SPLIT_MANIFEST.exists():
