    return json.loads(P.DATA_RAW_SPLIT_MANIFEST.read_text(encoding="utf-8"))


def _fixed_raw_split_files() -> dict[str, Path]:
    return {
        "train": P.DATA_RAW_TRAIN_CSV,
        "dev": P.DATA_RAW_DEV_CSV,
        "holdout": P.DATA_RAW_HOLDOUT_CSV,
    }


def _fixed_split_outputs() -> dict[str, Path]:
