def _raw_split_cache_stale_reason(*, out_split: Path, dataset: str) -> str | None:
    raw_files = _fixed_raw_split_files()
    outputs = _fixed_split_outputs()
    missing_raw = [str(path) for path in raw_files.values() if not path.exists()]
    if missing_raw:
        raise SystemExit(f"[time_split] fixed raw split file(s) missing: {missing_raw}")
    missing_outputs = [str(path) for path in outputs.values() if not path.exists()]
    if missing_outputs:
        return f"missing TraceRecord cache(s): {missing_outputs}"
    if not out_split.exists():
        return f"missing split manifest: {out_split}"

    try:
        manifest = json.loads(out_split.read_text(encoding="utf-8"))
    except Exception:
        return f"unreadable split manifest: {out_split}"
    if manifest.get("split_policy") != "fixed_raw_csv_splits_v1":
        return "split manifest is not fixed_raw_csv_splits_v1"
    if manifest.get("dataset") != dataset:
        return f"dataset changed: {manifest.get('dataset')} -> {dataset}"

    newest_source_mtime = max(path.stat().st_mtime for path in raw_files.values())
    if P.DATA_RAW_SPLIT_MANIFEST.exists():
        newest_source_mtime = max(newest_source_mtime, P.DATA_RAW_SPLIT_MANIFEST.stat().st_mtime)
    oldest_output_mtime = min(path.stat().st_mtime for path in [*outputs.values(), out_split])
    if newest_source_mtime > oldest_output_mtime + 1.0:
        return "raw split CSV/manifest is newer than staged split cache"
    return None


def _activate_train_cache_if_needed() -> bool:
    if (
        P.TRACE_RECORDS_JSONL.exists()
        and P.TRACE_RECORDS_JSONL.stat().st_size == P.TRAIN_TRACE_RECORDS_JSONL.stat().st_size
        and P.TRACE_RECORDS_JSONL.stat().st_mtime >= P.TRAIN_TRACE_RECORDS_JSONL.stat().st_mtime
    ):
        return False
    shutil.copyfile(P.TRAIN_TRACE_RECORDS_JSONL, P.TRACE_RECORDS_JSONL)
    return True


def activate_raw_split_files(*, out_split: Path, dataset: str) -> dict[str, Any]:
    """Ingest fixed data/raw train/dev/holdout CSV files and write a split manifest."""
    raw_files = _fixed_raw_split_files()
    missing = [str(path) for path in raw_files.values() if not path.exists()]
    if missing:
        raise SystemExit(f"[time_split] fixed raw split file(s) missing: {missing}")

    outputs = _fixed_split_outputs()
    for role, source in raw_files.items():
        _run_ingest(source, outputs[role], dataset=f"{dataset}_{role}")

    ids_by_role: dict[str, list[str]] = {}
    ranges: dict[str, dict[str, Any]] = {}
    for role, path in outputs.items():
        ids, meta = _range_meta_from_path(path)
        ids_by_role[role] = ids
        ranges[role] = meta

    raw_manifest = _read_raw_split_manifest()
    split_policy = "fixed_raw_csv_splits_v1"
    raw_split_policy = raw_manifest.get("split_policy") if isinstance(raw_manifest.get("split_policy"), dict) else {}
    split_id = (
        "fixed_raw_csv_v1_"
        f"{len(ids_by_role['train'])}_{len(ids_by_role['dev'])}_{len(ids_by_role['holdout'])}"
    )
    total = sum(len(ids) for ids in ids_by_role.values())
    ratios = {
        role: round(len(ids) / total, 6) if total else 0.0
        for role, ids in ids_by_role.items()
    }
    manifest = {
        "split_id": split_id,
        "split_policy": split_policy,
        "dataset": dataset,
        "source_trace_path": str(P.DATA_RAW),
        "source_files": {role: str(path) for role, path in raw_files.items()},
        "raw_manifest_path": str(P.DATA_RAW_SPLIT_MANIFEST) if P.DATA_RAW_SPLIT_MANIFEST.exists() else None,
        "raw_manifest": {
            "schema_version": raw_manifest.get("schema_version"),
            "source": raw_manifest.get("source"),
            "filter_policy": raw_manifest.get("filter_policy"),
            "split_policy": raw_split_policy,
            "included_ticket_count": raw_manifest.get("included_ticket_count"),
            "included_row_count": raw_manifest.get("included_row_count"),
        },
        "ratios": ratios,
        "trace_count": total,
        "train_trace_ids": ids_by_role["train"],
        "dev_trace_ids": ids_by_role["dev"],
        "holdout_trace_ids": ids_by_role["holdout"],
        "ranges": ranges,
        "outputs": {role: str(path) for role, path in outputs.items()},
        "leakage_policy": {
            "memory_compile_split": "train",
            "forbidden_memory_trace_splits": ["dev", "holdout", "eval_set_a"],
        },
        "created_at": cio.now_iso(),
    }
    out_split.parent.mkdir(parents=True, exist_ok=True)
    out_split.write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")
    return manifest


def main() -> None:
    ap = argparse.ArgumentParser(description="Build ECHO-Mem train/dev/holdout TraceRecord split caches")
    ap.add_argument("--source", default=str(P.DATA_RAW_SOURCE), help="Raw source file or directory for --refresh-source")
    ap.add_argument("--traces", default=str(P.TRACE_RECORDS_ALL_JSONL), help="Full TraceRecord cache to split")
    ap.add_argument("--out-split", default=str(P.TIME_SPLIT_JSON))
    ap.add_argument("--dataset", default="main_source")
    ap.add_argument("--train-ratio", type=float, default=DEFAULT_TRAIN_RATIO)
    ap.add_argument("--dev-ratio", type=float, default=DEFAULT_DEV_RATIO)
    ap.add_argument("--holdout-ratio", type=float, default=DEFAULT_HOLDOUT_RATIO)
    ap.add_argument("--refresh-source", action="store_true", help="Re-ingest data/raw/source/*.{csv,xlsx} before splitting")
    ap.add_argument(
        "--use-raw-splits",
        action="store_true",
        help="Ingest fixed data/raw/{train,dev,holdout}.csv instead of re-splitting source.",
    )
    ap.add_argument(
        "--activate-train",
        action="store_true",
        help="Copy train split cache to data/staged/trace_records.jsonl for existing compile commands",
    )
    ap.add_argument(
        "--reuse-existing",
        action="store_true",
        help="Reuse fixed split TraceRecord caches when raw CSV/manifest inputs have not changed.",
    )
    args = ap.parse_args()

    P.ensure_dirs()
    if args.use_raw_splits:
        out_split = Path(args.out_split)
        if args.reuse_existing:
            stale_reason = _raw_split_cache_stale_reason(out_split=out_split, dataset=args.dataset)
        else:
            stale_reason = "reuse disabled"
        if stale_reason:
            print(f"[time_split] rebuilding fixed raw splits: {stale_reason}", file=sys.stderr)
            manifest = activate_raw_split_files(out_split=out_split, dataset=args.dataset)
        else:
            manifest = json.loads(out_split.read_text(encoding="utf-8"))
            print(f"[time_split] reused fixed raw split caches -> {args.out_split}", file=sys.stderr)
        if args.activate_train:
            copied = _activate_train_cache_if_needed()
        print(
            "[time_split] activated fixed raw splits "
            f"train={len(manifest['train_trace_ids'])} "
            f"dev={len(manifest['dev_trace_ids'])} "
            f"holdout={len(manifest['holdout_trace_ids'])} "
            f"-> {args.out_split}",
            file=sys.stderr,
        )
        if args.activate_train:
            action = "activated" if copied else "train split already active"
            print(f"[time_split] {action} -> {P.TRACE_RECORDS_JSONL}", file=sys.stderr)
        return

    trace_path = Path(args.traces)
    if args.refresh_source:
        refresh_source_traces(source=args.source, out=trace_path, dataset=args.dataset)

    traces = list(cio.read_jsonl(trace_path))
    if not traces:
        raise SystemExit(
            "[time_split] no traces found. Run with --use-raw-splits for data/raw/{train,dev,holdout}.csv "
            "or with --refresh-source after placing raw files under "
            f"{P.DATA_RAW_SOURCE}/, or pass --traces <jsonl>."
        )

    splits = split_traces(
        traces,
        train_ratio=args.train_ratio,
        dev_ratio=args.dev_ratio,
        holdout_ratio=args.holdout_ratio,
    )
    manifest = build_split_manifest(
        splits,
        split_policy="time_order_v1",
        source_trace_path=trace_path,
        train_ratio=args.train_ratio,
        dev_ratio=args.dev_ratio,
        holdout_ratio=args.holdout_ratio,
        dataset=args.dataset,
    )
    write_split_outputs(splits, manifest, out_split=Path(args.out_split))

    if args.activate_train:
        shutil.copyfile(P.TRAIN_TRACE_RECORDS_JSONL, P.TRACE_RECORDS_JSONL)

    print(
        "[time_split] "
        f"train={len(splits['train'])} dev={len(splits['dev'])} holdout={len(splits['holdout'])} "
        f"-> {args.out_split}",
        file=sys.stderr,
    )
    if args.activate_train:
        print(f"[time_split] activated train split -> {P.TRACE_RECORDS_JSONL}", file=sys.stderr)


if __name__ == "__main__":
    main()

"""Deterministic semantic deltas for versioned Operational Memory artifacts.

This module implements packaging and reconstruction primitives only.  It does
not claim that the Trace-to-Memory compiler itself is incremental: callers may
full-compile cumulative history, project away volatile metadata, and persist
only the semantic difference.
"""
from __future__ import annotations

import copy
import hashlib
import json
from typing import Any, Iterable


DELTA_SCHEMA_VERSION = "echo_memory_semantic_delta.v1"
DEFAULT_VOLATILE_FIELDS = frozenset({
    "produced_at",
    "scored_at",
    "occurred_at",
    "extracted_at",
    "created_at",
    "updated_at",
    "runtime_seconds",
})


def canonical_json(value: Any) -> str:
    return json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )


def sha256_value(value: Any) -> str:
    return hashlib.sha256(canonical_json(value).encode("utf-8")).hexdigest()


def semantic_projection(
    value: Any,
    *,
    volatile_fields: frozenset[str] = DEFAULT_VOLATILE_FIELDS,
) -> Any:
    """Recursively remove non-semantic runtime metadata."""
    if isinstance(value, dict):
        return {
            key: semantic_projection(item, volatile_fields=volatile_fields)
            for key, item in sorted(value.items())
            if key not in volatile_fields
        }
    if isinstance(value, list):
        return [
            semantic_projection(item, volatile_fields=volatile_fields)
            for item in value
        ]
    return copy.deepcopy(value)


def index_rows(
    rows: Iterable[dict[str, Any]],
    *,
    id_field: str,
) -> dict[str, dict[str, Any]]:
    indexed: dict[str, dict[str, Any]] = {}
    for row in rows:
        projected = semantic_projection(row)
        row_id = str(projected.get(id_field) or "")
        if not row_id:
            raise ValueError(f"semantic artifact row missing {id_field}")
        previous = indexed.get(row_id)
        if previous is not None and previous != projected:
            raise ValueError(f"conflicting duplicate semantic row {id_field}={row_id}")
        indexed[row_id] = projected
    return indexed


def hash_index(rows_by_id: dict[str, dict[str, Any]]) -> dict[str, str]:
    return {
        row_id: sha256_value(row)
        for row_id, row in sorted(rows_by_id.items())
    }


def artifact_semantic_hash(row_hashes: dict[str, str]) -> str:
    return sha256_value([[row_id, digest] for row_id, digest in sorted(row_hashes.items())])


def diff_rows(
    previous_hashes: dict[str, str],
    current_rows: Iterable[dict[str, Any]],
    *,
    id_field: str,
) -> dict[str, Any]:
    """Return full semantic upserts, deletes, and the new hash index."""
    current_hashes: dict[str, str] = {}
    upserts_by_id: dict[str, dict[str, Any]] = {}
    semantic_bytes = 0
    for row in current_rows:
        projected = semantic_projection(row)
        row_id = str(projected.get(id_field) or "")
        if not row_id:
            raise ValueError(f"semantic artifact row missing {id_field}")
        serialized = canonical_json(projected)
        digest = hashlib.sha256(serialized.encode("utf-8")).hexdigest()
        previous_current = current_hashes.get(row_id)
        if previous_current is not None and previous_current != digest:
            raise ValueError(f"conflicting duplicate semantic row {id_field}={row_id}")
        if previous_current is not None:
            continue
        current_hashes[row_id] = digest
        semantic_bytes += len(serialized.encode("utf-8")) + 1
        if previous_hashes.get(row_id) != digest:
            upserts_by_id[row_id] = projected
    delete_ids = sorted(set(previous_hashes) - set(current_hashes))
    return {
        "schema_version": DELTA_SCHEMA_VERSION,
        "id_field": id_field,
        "upserts": [upserts_by_id[row_id] for row_id in sorted(upserts_by_id)],
        "deletes": delete_ids,
        "current_hashes": current_hashes,
        "counts": {
            "previous": len(previous_hashes),
            "current": len(current_hashes),
            "upserts": len(upserts_by_id),
            "deletes": len(delete_ids),
            "unchanged": len(current_hashes) - len(upserts_by_id),
        },
        "semantic_hash": artifact_semantic_hash(current_hashes),
        "full_snapshot_semantic_bytes": semantic_bytes,
    }


def apply_delta(
    base: dict[str, dict[str, Any]],
    *,
    upserts: Iterable[dict[str, Any]],
    deletes: Iterable[str],
    id_field: str,
) -> dict[str, dict[str, Any]]:
    """Materialize one artifact delta without mutating the caller's view."""
    out = {row_id: copy.deepcopy(row) for row_id, row in base.items()}
    for row_id in deletes:
        out.pop(str(row_id), None)
    for row_id, row in index_rows(upserts, id_field=id_field).items():
        out[row_id] = row
    return dict(sorted(out.items()))


def apply_delta_to_hashes(
    previous_hashes: dict[str, str],
    *,
    upserts: Iterable[dict[str, Any]],
    deletes: Iterable[str],
    id_field: str,
) -> dict[str, str]:
    """Hash-only replay used to audit large version chains efficiently."""
    out = dict(previous_hashes)
    for row_id in deletes:
        out.pop(str(row_id), None)
    for row_id, row in index_rows(upserts, id_field=id_field).items():
        out[row_id] = sha256_value(row)
    return dict(sorted(out.items()))


def package_semantic_hash(artifact_hashes: dict[str, str]) -> str:
    return sha256_value([[name, digest] for name, digest in sorted(artifact_hashes.items())])


def version_chain_hash(
    *,
    previous_version_hash: str,
    core_delta_hash: str,
    materialization_delta_hash: str,
    theta_hash: str,
    evidence_cutoff: str,
) -> str:
    return sha256_value({
        "previous_version_hash": previous_version_hash,
        "core_delta_hash": core_delta_hash,
        "materialization_delta_hash": materialization_delta_hash,
        "theta_hash": theta_hash,
        "evidence_cutoff": evidence_cutoff,
    })

"""Composable credibility scoring for long-eval pass/fail evidence.

The scorer keeps a conservative LCB blend as the default, while letting
experiments combine several credibility estimators with weights.
"""

from __future__ import annotations

import math
from dataclasses import dataclass
from typing import Any

from .bayesian_score import credibility_from_metrics, long_eval_success_fail, raw_pass_rate

DEFAULT_CREDIBILITY_WEIGHTS = {
    "bayesian_lcb": 0.7,
    "wilson_lcb": 0.3,
}
SUPPORTED_CREDIBILITY_COMPONENTS = {
    "bayesian_lcb",
    "wilson_lcb",
    "raw_pass_rate",
    "support_confidence",
}


@dataclass(frozen=True)
class CredibilityConfig:
    weights: dict[str, float]

    @classmethod
    def default(cls) -> "CredibilityConfig":
        return cls(dict(DEFAULT_CREDIBILITY_WEIGHTS))


def _clip01(x: float) -> float:
    return max(0.0, min(1.0, float(x)))


def normalize_weights(weights: dict[str, float], supported: set[str]) -> dict[str, float]:
    cleaned: dict[str, float] = {}
    for key, value in weights.items():
        if key not in supported:
            raise ValueError(f"unsupported weight key: {key}")
        weight = float(value)
        if weight < 0:
            raise ValueError(f"weight must be non-negative: {key}={value}")
        if weight > 0:
            cleaned[key] = weight
    total = sum(cleaned.values())
    if total <= 0:
        raise ValueError("at least one positive weight is required")
    return {key: value / total for key, value in cleaned.items()}


def parse_weight_spec(
    spec: str | None,
    *,
    default: dict[str, float],
    supported: set[str],
) -> dict[str, float]:
    """Parse ``a=0.7,b=0.3`` into normalized weights.

    A bare component name such as ``wilson_lcb`` is shorthand for
    ``wilson_lcb=1``. Empty spec returns the normalized default.
    """
    if not spec:
        return normalize_weights(default, supported)
    raw: dict[str, float] = {}
    for part in spec.split(","):
        part = part.strip()
        if not part:
            continue
        if "=" in part:
            key, value = part.split("=", 1)
            raw[key.strip()] = float(value.strip())
        else:
            raw[part] = 1.0
    return normalize_weights(raw, supported)


def wilson_lcb(success: int, failure: int, *, z: float = 1.6448536269514722) -> float:
    """Wilson lower confidence bound for a Bernoulli pass rate.

    Default z is approximately the one-sided 95% lower bound, matching the
    conservative spirit of the Bayesian 5% LCB already used by the project.
    """
    s = max(0, int(success))
    f = max(0, int(failure))
    n = s + f
    if n <= 0:
        return 0.5
    phat = s / n
    z2 = z * z
    denom = 1.0 + z2 / n
    centre = phat + z2 / (2.0 * n)
    margin = z * math.sqrt((phat * (1.0 - phat) + z2 / (4.0 * n)) / n)
    return _clip01((centre - margin) / denom)


def support_confidence(success: int, failure: int, *, saturation: int = 20) -> float:
    """Confidence from evidence volume only, independent of pass rate."""
    total = max(0, int(success)) + max(0, int(failure))
    return _clip01(math.log1p(total) / math.log1p(max(1, saturation)))


def credibility_from_metrics_weighted(
    metrics: dict[str, Any],
    config: CredibilityConfig | None = None,
) -> dict[str, Any]:
    cfg = config or CredibilityConfig.default()
    weights = normalize_weights(cfg.weights, SUPPORTED_CREDIBILITY_COMPONENTS)
    success, failure = long_eval_success_fail(metrics)
    total = success + failure
    bayesian = credibility_from_metrics(metrics)
    raw = raw_pass_rate(success, failure)

    components = {
        "bayesian_lcb": float(bayesian["credibility_lcb"]),
        "wilson_lcb": wilson_lcb(success, failure),
        "raw_pass_rate": 0.5 if raw is None else float(raw),
        "support_confidence": support_confidence(success, failure),
    }
    score = sum(weights[key] * components[key] for key in weights)
    method = "+".join(f"{key}:{weights[key]:.3f}" for key in sorted(weights))
    return {
        "method": method,
        "score": round(_clip01(score), 6),
        "weights": {key: round(value, 6) for key, value in weights.items()},
        "components": {key: round(_clip01(value), 6) for key, value in components.items()},
        "success_count": success,
        "failure_count": failure,
        "eval_total": total,
        "raw_pass_rate": round(raw, 6) if raw is not None else None,
        "bayesian": bayesian,
    }


def credibility_score_weighted(
    metrics: dict[str, Any],
    config: CredibilityConfig | None = None,
) -> float:
    return float(credibility_from_metrics_weighted(metrics, config)["score"])

"""Select a concrete action value from a strategy's child outcome statistics."""

from __future__ import annotations

import math
from typing import Any

from ..common.parameter_range import numeric_position, to_number
from ..scoring.bayesian_score import credibility_from_counts


def _count(row: dict[str, Any], key: str) -> int:
    try:
        return max(0, int(row.get(key) or 0))
    except (TypeError, ValueError):
        return 0


def _support_score(support: int) -> float:
    return min(1.0, math.log1p(max(0, support)) / math.log1p(200))


def _position_bucket(position: float | None) -> str | None:
    if position is None:
        return None
    if position < 0.05:
        return "p00_05"
    if position < 0.20:
        return "p05_20"
    if position < 0.40:
        return "p20_40"
    if position < 0.60:
        return "p40_60"
    if position < 0.80:
        return "p60_80"
    if position < 0.95:
        return "p80_95"
    return "p95_100"


def _snapshot_range(snapshot: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(snapshot, dict):
        return None
    for key in ("parameter_range", "effective_parameter_range", "range"):
        value = snapshot.get(key)
        if isinstance(value, dict) and value.get("min") is not None and value.get("max") is not None:
            return value
    if snapshot.get("min") is not None and snapshot.get("max") is not None:
        return {
            "min": snapshot.get("min"),
            "max": snapshot.get("max"),
            "step": snapshot.get("step"),
            "complete": True,
        }
    return None


def _range_midpoint(snapshot_range: dict[str, Any] | None) -> float | None:
    if not isinstance(snapshot_range, dict):
        return None
    lo = to_number(snapshot_range.get("min"))
    hi = to_number(snapshot_range.get("max"))
    if lo is None or hi is None:
        return None
    return round((lo + hi) / 2, 6)


def _current_value(snapshot: dict[str, Any] | None) -> float | None:
    if not isinstance(snapshot, dict):
        return None
    for key in ("current_value", "before_value", "value"):
        number = to_number(snapshot.get(key))
        if number is not None:
            return number
    return None


def _current_value_context(
    current_parameter_snapshot: dict[str, Any] | None,
    parameter_value_prior: dict[str, Any] | None = None,
    *,
    parameter_snapshot_match: str | None = None,
) -> dict[str, Any]:
    snapshot_range = _snapshot_range(current_parameter_snapshot)
    current = _current_value(current_parameter_snapshot)
    if snapshot_range and current is not None:
        return {
            "snapshot": current_parameter_snapshot,
            "current_value": current,
            "parameter_range": snapshot_range,
            "current_value_source": "observed_snapshot",
            "current_value_confidence": "observed",
            "target_value_confidence": "observed",
            "parameter_snapshot_match": "exact",
            "current_parameter_snapshot_used": True,
        }

    prior = parameter_value_prior if isinstance(parameter_value_prior, dict) else {}
    prior_range = _snapshot_range(prior)
    median_current = to_number(prior.get("median_current_value"))
    fallback_match = parameter_snapshot_match or (
        "ambiguous" if isinstance(current_parameter_snapshot, dict) else "missing_predicted_parameter"
    )
    if prior_range and median_current is not None:
        fallback_snapshot = {
            "current_value": median_current,
            "parameter_range": prior_range,
            "snapshot_policy": "train_median_fallback_v1",
        }
        return {
            "snapshot": fallback_snapshot,
            "current_value": median_current,
            "parameter_range": prior_range,
            "current_value_source": "train_median_fallback",
            "current_value_confidence": "imputed",
            "target_value_confidence": "imputed",
            "parameter_snapshot_match": fallback_match,
            "current_parameter_snapshot_used": False,
        }

    midpoint = _range_midpoint(prior_range)
    if prior_range and midpoint is not None:
        fallback_snapshot = {
            "current_value": midpoint,
            "parameter_range": prior_range,
            "snapshot_policy": "range_midpoint_fallback_v1",
        }
        return {
            "snapshot": fallback_snapshot,
            "current_value": midpoint,
            "parameter_range": prior_range,
            "current_value_source": "range_midpoint_fallback",
            "current_value_confidence": "imputed",
            "target_value_confidence": "imputed",
            "parameter_snapshot_match": fallback_match,
            "current_parameter_snapshot_used": False,
        }

    return {
        "snapshot": None,
        "current_value": None,
        "parameter_range": None,
        "current_value_source": "unavailable",
        "current_value_confidence": "unavailable",
        "target_value_confidence": "unavailable",
        "parameter_snapshot_match": parameter_snapshot_match or "unavailable",
        "current_parameter_snapshot_used": False,
    }


def _format_number(value: float | None) -> str:
    if value is None:
        return ""
    rounded = round(value, 6)
    if rounded == int(rounded):
        return str(int(rounded))
    return f"{rounded:g}"


def _round_to_step(value: float, step: object) -> float:
    step_num = to_number(step)
    if step_num is None or step_num <= 0:
        return round(value, 6)
    return round(round(value / step_num) * step_num, 6)


def _shape_candidate_row(
    row: dict[str, Any],
    current_parameter_snapshot: dict[str, Any] | None,
) -> dict[str, Any] | None:
    snapshot_range = _snapshot_range(current_parameter_snapshot)
    current = _current_value(current_parameter_snapshot)
    shape = row.get("example") if isinstance(row.get("example"), dict) else {}
    delta_ratio = to_number(shape.get("delta_ratio"))
    if not snapshot_range or current is None or delta_ratio is None:
        return None

    lo = to_number(snapshot_range.get("min"))
    hi = to_number(snapshot_range.get("max"))
    if lo is None or hi is None or hi == lo:
        return None

    span = hi - lo
    direction = str(shape.get("direction") or "")
    sign = -1 if direction == "decrease" else 1
    delta = _round_to_step(sign * abs(delta_ratio) * abs(span), snapshot_range.get("step"))
    if delta == 0:
        return None

    target = max(min(current + delta, max(lo, hi)), min(lo, hi))
    current_position = numeric_position(current, {**snapshot_range, "complete": True})
    current_bucket = _position_bucket(current_position)
    expected_bucket = shape.get("before_position_bucket")
    location_match = current_bucket is not None and current_bucket == expected_bucket
    return {
        "source": "shape_distribution",
        "suggested_delta": f"{delta:+g}",
        "target_value": _format_number(target),
        "normalized_shape_id": row.get("shape_id"),
        "current_position": current_position,
        "current_position_bucket": current_bucket,
        "shape_before_position_bucket": expected_bucket,
        "shape_location_match": location_match,
        **row,
    }


def _row_score(row: dict[str, Any]) -> dict[str, Any]:
    passed = _count(row, "long_eval_pass_count")
    failed = _count(row, "long_eval_fail_count")
    support = _count(row, "support_count")
    bayes = credibility_from_counts(passed, failed)
    lcb = float(bayes["credibility_lcb"])
    location_bonus = 0.05 if row.get("shape_location_match") else 0.0
    score = round(min(1.0, lcb * 0.8 + _support_score(support) * 0.2 + location_bonus), 6)
    return {
        "score": score,
        "credibility_lcb": lcb,
        "support_score": round(_support_score(support), 6),
        "support_count": support,
        "long_eval_pass_count": passed,
        "long_eval_fail_count": failed,
        "pass_rate": row.get("pass_rate"),
    }


def _candidate_rows(
    value_pattern: dict[str, Any],
    observed_changes: list[dict[str, Any]] | None = None,
    current_parameter_snapshot: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for row in value_pattern.get("shape_distribution") or []:
        if isinstance(row, dict):
            shape_row = _shape_candidate_row(row, current_parameter_snapshot)
            if shape_row:
                rows.append(shape_row)
    for row in value_pattern.get("delta_distribution") or []:
        if isinstance(row, dict) and row.get("delta_bucket") is not None:
            rows.append({
                "source": "delta_distribution",
                "suggested_delta": row.get("delta_bucket"),
                "normalized_shape_id": None,
                **row,
            })
    for row in observed_changes or value_pattern.get("observed_changes") or []:
        if isinstance(row, dict) and row.get("delta_bucket") is not None:
            rows.append({
                "source": "observed_changes",
                "suggested_delta": row.get("delta_bucket"),
                "normalized_shape_id": row.get("normalized_shape_id"),
                **row,
            })
    return rows


def select_action_value(
    value_pattern: dict[str, Any] | None,
    *,
    observed_changes: list[dict[str, Any]] | None = None,
    current_parameter_snapshot: dict[str, Any] | None = None,
    parameter_value_prior: dict[str, Any] | None = None,
    parameter_snapshot_match: str | None = None,
) -> dict[str, Any]:
    """Choose the suggested delta/value for a selected strategy memory.

    ``current_parameter_snapshot`` is reserved for clean pre-decision parameter
    state. The paper replay currently does not pass held-out action values into
    recommendation, so this selector falls back to child outcome statistics.
    """
    pattern = value_pattern if isinstance(value_pattern, dict) else {}
    current_context = _current_value_context(
        current_parameter_snapshot,
        parameter_value_prior,
        parameter_snapshot_match=parameter_snapshot_match,
    )
    rows = _candidate_rows(
        pattern,
        observed_changes=observed_changes,
        current_parameter_snapshot=current_context.get("snapshot"),
    )
    if not rows:
        return {
            "selected": False,
            "suggested_delta": pattern.get("delta_bucket") or "",
            "value_pattern_id": pattern.get("pattern_id") or "",
            "selection_policy": "pattern_default",
            "reason": "no_child_value_statistics",
            "current_parameter_snapshot_used": current_context["current_parameter_snapshot_used"],
            "current_value_source": current_context["current_value_source"],
            "current_value_confidence": current_context["current_value_confidence"],
            "target_value_confidence": "unavailable",
            "parameter_snapshot_match": current_context["parameter_snapshot_match"],
            "current_value": _format_number(current_context.get("current_value")),
            "candidates": [],
        }

    ranked = []
    for row in rows:
        scored = _row_score(row)
        ranked.append({
            **row,
            **scored,
        })
    ranked.sort(
        key=lambda item: (
            float(item.get("score") or 0.0),
            int(item.get("support_count") or 0),
            str(item.get("source") or ""),
        ),
        reverse=True,
    )
    best = ranked[0]
    return {
        "selected": True,
        "suggested_delta": best.get("suggested_delta") or "",
        "target_value": best.get("target_value") or best.get("after_value") or "",
        "value_pattern_id": pattern.get("pattern_id") or "",
        "normalized_shape_id": best.get("normalized_shape_id") or pattern.get("normalized_shape_id"),
        "selection_policy": "child_outcome_bayesian_lcb_v1",
        "score": best.get("score"),
        "credibility_lcb": best.get("credibility_lcb"),
        "support_count": best.get("support_count"),
        "source": best.get("source"),
        "reason": "selected_by_child_value_outcome_statistics",
        "current_parameter_snapshot_used": current_context["current_parameter_snapshot_used"],
        "current_value_source": current_context["current_value_source"],
        "current_value_confidence": current_context["current_value_confidence"],
        "target_value_confidence": current_context["target_value_confidence"] if best.get("target_value") else "unavailable",
        "parameter_snapshot_match": current_context["parameter_snapshot_match"],
        "current_value": _format_number(current_context.get("current_value")),
        "candidates": [
            {
                "source": item.get("source"),
                "suggested_delta": item.get("suggested_delta"),
                "target_value": item.get("target_value"),
                "normalized_shape_id": item.get("normalized_shape_id"),
                "current_position_bucket": item.get("current_position_bucket"),
                "shape_before_position_bucket": item.get("shape_before_position_bucket"),
                "shape_location_match": item.get("shape_location_match"),
                "score": item.get("score"),
                "credibility_lcb": item.get("credibility_lcb"),
                "support_count": item.get("support_count"),
                "long_eval_pass_count": item.get("long_eval_pass_count"),
                "long_eval_fail_count": item.get("long_eval_fail_count"),
                "pass_rate": item.get("pass_rate"),
            }
            for item in ranked[:5]
        ],
    }

