def _policy_name(config: dict[str, Any], fallback: str = "failcohort_veto_gate_v1") -> str:
    version = str(config.get("version") or "").strip()
    if version == "gate_v4_boundary_only_diagnostic":
        return "failcohort_veto_gate_v4_boundary_only_diagnostic"
    if version == "gate_v3_gray_zone_evidence":
        return "failcohort_veto_gate_v3_gray_zone_evidence"
    if version == "gate_v2_calibrated_review_first":
        return "failcohort_veto_gate_v2_calibrated_review_first"
    return fallback


def veto_id(veto: dict[str, Any]) -> str:
    return str(veto.get("memory_id") or veto.get("id") or "")


def veto_match_fields(veto: dict[str, Any]) -> dict[str, Any]:
    content = veto.get("content") if isinstance(veto.get("content"), dict) else {}
    app = veto.get("applicability") if isinstance(veto.get("applicability"), dict) else {}
    pattern = content.get("value_pattern") if isinstance(content.get("value_pattern"), dict) else {}
    return {
        "scheme_id": veto.get("scheme_id") or content.get("scheme_id") or (app.get("scheme_ids") or [None])[0],
        "scheme_group": veto.get("scheme_group") or content.get("scheme_group") or (app.get("scheme_groups") or [None])[0],
        "parameter_semantic_id": veto.get("parameter_semantic_id") or content.get("parameter_semantic_id"),
        "direction": veto.get("direction") or pattern.get("direction"),
        "component_signatures": veto.get("component_signatures")
        or (
            content.get("matching_features", {})
            .get("soft_signals", {})
            .get("component_signatures", [])
        ),
    }


def veto_knowledge_state_tier(veto: dict[str, Any]) -> str:
    """Map compiled memory state/type into the gate's evidence tier.

    This keeps the compile-time state machine and replay-time gate in one
    contract: counter-evidence is strong negative evidence; restricted is a
    review-only gray signal; validated/reusable are positive states and should
    not become hard veto evidence by state alone.
    """
    memory_type = str(veto.get("memory_type") or veto.get("node_type") or "")
    state = str(veto.get("state") or "")
    if memory_type == "counter_evidence_memory" or state == "counter_evidence":
        return "counter_evidence"
    if state == "restricted":
        return "restricted_gray"
    if state in {"validated", "reusable"}:
        return "positive_state"
    if state == "unverified":
        return "unverified"
    return "unknown"


def veto_matches_recommended(
    veto: dict[str, Any],
    recommended: dict[str, Any],
    family: dict[str, Any] | None,
) -> bool:
    if not recommended:
        return False
    fields = veto_match_fields(veto)
    rec_scheme = recommended.get("scheme_id")
    rec_param = recommended.get("parameter_semantic_id")
    rec_direction = recommended.get("direction")
    rec_signature = recommended.get("value_pattern_id")

    veto_scheme = fields.get("scheme_id")
    veto_group = fields.get("scheme_group")
    veto_param = fields.get("parameter_semantic_id")
    veto_direction = fields.get("direction")
    family_group = (family or {}).get("scheme_group")

    if veto_scheme and rec_scheme and veto_scheme != rec_scheme:
        return False
    if veto_group and family_group and veto_group != family_group:
        return False
    if veto_param and rec_param and veto_param != rec_param:
        return False
    if veto_direction and rec_direction and veto_direction != rec_direction:
        return False

    signatures = fields.get("component_signatures") or []
    if rec_signature and signatures and rec_signature in signatures:
        return True
    if veto_param:
        return bool(rec_param and veto_param == rec_param and (not veto_scheme or veto_scheme == rec_scheme))
    if veto_scheme:
        return bool(rec_scheme and veto_scheme == rec_scheme)
    if veto_group:
        return bool(family_group and veto_group == family_group)
    return False


def matched_vetoes(
    vetoes: list[dict[str, Any]],
    recommended: dict[str, Any],
    family: dict[str, Any] | None,
) -> list[dict[str, Any]]:
    return [v for v in vetoes if veto_matches_recommended(v, recommended, family)]


def _norm_values(value: Any) -> set[str]:
    if isinstance(value, list):
        return {str(item).strip().lower() for item in value if str(item or "").strip()}
    text = str(value or "").strip().lower()
    return {text} if text else set()


ENVIRONMENT_COMPONENTS = {
    "scenario_vendor",
    "scenario_system",
    "scenario_region",
    "scenario_band",
    "scenario_is_indoor",
}
BOUNDARY_COMPONENTS = {"boundary_region", "boundary_scenario"}
ACTION_SPECIFIC_COMPONENTS = {"action_parameter", "action_direction", "action_signature"}


def _bounded_score(
    components: dict[str, float],
    penalties: dict[str, float],
    *,
    excluded_components: set[str] | None = None,
) -> float:
    excluded_components = excluded_components or set()
    score = sum(
        value
        for key, value in components.items()
        if key not in excluded_components
    ) - sum(penalties.values())
    return max(0.0, min(1.0, score))


def _specificity_tier(components: dict[str, float]) -> str:
    if "action_signature" in components:
        return "signature_action"
    if "action_parameter" in components and "action_direction" in components:
        return "parameter_direction"
    if "action_parameter" in components:
        return "parameter_only"
    if "action_scheme" in components or "action_group" in components:
        return "scheme_context"
    return "scenario_context"


def _norm_text(value: Any) -> str:
    return str(value or "").strip().lower()


def _action_profile_match(veto: dict[str, Any], recommended: dict[str, Any]) -> dict[str, Any]:
    content = veto.get("content") if isinstance(veto.get("content"), dict) else {}
    profiles = content.get("action_profiles") if isinstance(content.get("action_profiles"), list) else []
    rec_param = _norm_text(recommended.get("parameter_semantic_id"))
    rec_direction = _norm_text(recommended.get("direction"))
    rec_canonical = _norm_text(recommended.get("canonical_action_id"))
    rec_delta = _norm_text(recommended.get("delta_bucket") or recommended.get("suggested_delta"))
    rec_change = _norm_text(recommended.get("typical_change") or recommended.get("change"))
    rec_param_cn = str(recommended.get("param_cn_name") or "").strip()

    summary = {
        "profile_count": len([item for item in profiles if isinstance(item, dict)]),
        "parameter_match": False,
        "direction_match": False,
        "parameter_direction_match": False,
        "canonical_action_match": False,
        "value_match": False,
        "param_cn_match": False,
        "matched_profile_count": 0,
        "match_tier": "none",
    }
    for profile in profiles:
        if not isinstance(profile, dict):
            continue
        action_ontology = profile.get("action_ontology") if isinstance(profile.get("action_ontology"), dict) else {}
        profile_param = _norm_text(profile.get("parameter_semantic_id"))
        profile_direction = _norm_text(profile.get("direction") or action_ontology.get("label_numeric_direction"))
        profile_canonical = _norm_text(profile.get("canonical_action_id") or action_ontology.get("canonical_action_id"))
        profile_param_cn = str(profile.get("param_cn_name") or "").strip()
        profile_value_text = " ".join(
            _norm_text(profile.get(key))
            for key in (
                "value_rule",
                "adjustment_rule",
                "before_value",
                "after_value",
                "change",
                "delta_bucket",
            )
        )

        param_match = bool(rec_param and profile_param and rec_param == profile_param)
        direction_match = bool(rec_direction and profile_direction and rec_direction == profile_direction)
        canonical_match = bool(rec_canonical and profile_canonical and rec_canonical == profile_canonical)
        value_match = bool(
            (rec_delta and rec_delta in profile_value_text)
            or (rec_change and rec_change in profile_value_text)
        )
        param_cn_match = bool(rec_param_cn and profile_param_cn and rec_param_cn == profile_param_cn)

        if param_match:
            summary["parameter_match"] = True
        if direction_match:
            summary["direction_match"] = True
        if param_match and direction_match:
            summary["parameter_direction_match"] = True
            summary["matched_profile_count"] += 1
        if canonical_match:
            summary["canonical_action_match"] = True
        if value_match:
            summary["value_match"] = True
        if param_cn_match:
            summary["param_cn_match"] = True

    if summary["parameter_direction_match"] and summary["value_match"]:
        summary["match_tier"] = "profile_parameter_direction_value"
    elif summary["parameter_direction_match"]:
        summary["match_tier"] = "profile_parameter_direction"
    elif summary["canonical_action_match"]:
        summary["match_tier"] = "profile_canonical_action"
    elif summary["parameter_match"]:
        summary["match_tier"] = "profile_parameter"
    elif summary["param_cn_match"]:
        summary["match_tier"] = "profile_param_cn"
    return summary


def veto_similarity(
    veto: dict[str, Any],
    recommended: dict[str, Any],
    family: dict[str, Any] | None,
    query: dict[str, Any] | None = None,
    *,
    use_boundary_match: bool = True,
) -> dict[str, Any]:
    """Compute FailCohortHit from scenario and canonical action fields."""
    query = query or {}
    fields = veto_match_fields(veto)
    app = veto.get("applicability") if isinstance(veto.get("applicability"), dict) else {}
    components: dict[str, float] = {}
    penalties: dict[str, float] = {}

    issue = str(query.get("issue_type") or "").strip().lower()
    if issue and issue in _norm_values(app.get("issue_types")):
        components["scenario_issue"] = 0.18
    elif issue and query.get("veto_issue_routed") and not _norm_values(app.get("issue_types")):
        components["scenario_issue"] = 0.18

    environment_fields = (
        ("vendor", "vendors", 0.05),
        ("system", "systems", 0.05),
        ("region", "regions", 0.04),
        ("band", "bands", 0.02),
        ("is_indoor", "indoor_outdoor", 0.02),
    )
    for query_key, app_key, weight in environment_fields:
        values = _norm_values(app.get(app_key))
        query_value = str(query.get(query_key) or "").strip().lower()
        if values and query_value and query_value in values:
            components[f"scenario_{query_key}"] = weight

    rec_scheme = str(recommended.get("scheme_id") or "").strip()
    veto_scheme = str(fields.get("scheme_id") or "").strip()
    if rec_scheme and veto_scheme and rec_scheme == veto_scheme:
        components["action_scheme"] = 0.25

    rec_group = str(recommended.get("scheme_group") or (family or {}).get("scheme_group") or "").strip()
    veto_group = str(fields.get("scheme_group") or "").strip()
    if rec_group and veto_group and rec_group == veto_group:
        components["action_group"] = 0.07

    rec_param = str(recommended.get("parameter_semantic_id") or "").strip()
    veto_param = str(fields.get("parameter_semantic_id") or "").strip()
    if rec_param and veto_param and rec_param == veto_param:
        components["action_parameter"] = 0.12

    rec_direction = str(recommended.get("direction") or "").strip()
    veto_direction = str(fields.get("direction") or "").strip()
    if rec_direction and veto_direction and rec_direction == veto_direction:
        components["action_direction"] = 0.08

    signatures = _norm_values(fields.get("component_signatures"))
    signature = "|".join([
        rec_scheme,
        rec_param,
        str(recommended.get("value_type") or "").strip(),
        rec_direction,
    ]).lower()
    if signature and signature in signatures:
        components["action_signature"] = max(components.get("action_scheme", 0.0), 0.25)
        components["action_parameter"] = max(components.get("action_parameter", 0.0), 0.12)
        components["action_direction"] = max(components.get("action_direction", 0.0), 0.08)

    exclusions = [str(item).strip() for item in app.get("exclusions") or [] if str(item or "").strip()]
    region_boundaries = {
        item.split(":", 1)[1].strip().lower()
        for item in exclusions
        if item.startswith("区域:") and ":" in item
    }
    scenario_boundaries = {
        item.split(":", 1)[1].strip().lower()
        for item in exclusions
        if item.startswith("场景:") and ":" in item
    }
    query_region = str(query.get("region") or "").strip().lower()
    query_scenario = str(query.get("scenario") or "").strip().lower()
    boundary = {
        "available": bool(region_boundaries or scenario_boundaries),
        "matched": [],
        "mismatched": [],
        "unknown": [],
    }
    if use_boundary_match and region_boundaries:
        if not query_region or query_region.startswith("未知"):
            boundary["unknown"].append("region")
        elif query_region in region_boundaries:
            components["boundary_region"] = 0.08
            boundary["matched"].append("region")
        else:
            penalties["boundary_region_mismatch"] = 0.08
            boundary["mismatched"].append("region")
    if use_boundary_match and scenario_boundaries:
        if not query_scenario:
            boundary["unknown"].append("scenario")
        elif query_scenario in scenario_boundaries:
            components["boundary_scenario"] = 0.04
            boundary["matched"].append("scenario")
        else:
            penalties["boundary_scenario_mismatch"] = 0.04
            boundary["mismatched"].append("scenario")

    score = _bounded_score(components, penalties)
    non_environment_score = _bounded_score(
        components,
        penalties,
        excluded_components=ENVIRONMENT_COMPONENTS,
    )
    action_specific_score = _bounded_score(
        components,
        penalties,
        excluded_components=ENVIRONMENT_COMPONENTS | BOUNDARY_COMPONENTS,
    )
    metrics = _metric_source(veto)
    content = veto.get("content") if isinstance(veto.get("content"), dict) else {}
    profile_match = _action_profile_match(veto, recommended)
    broad_context_prior = _broad_context_outcome_prior(veto)
    return {
        "veto_id": veto_id(veto),
        "score": round(score, 6),
        "broad_score": round(score, 6),
        "non_environment_score": round(non_environment_score, 6),
        "action_specific_score": round(action_specific_score, 6),
        "specificity_tier": _specificity_tier(components),
        "components": {key: round(value, 6) for key, value in components.items()},
        "penalties": {key: round(value, 6) for key, value in penalties.items()},
        "boundary": boundary,
        "evidence_aggregation": content.get("aggregation") or content.get("aggregation_level"),
        "evaluation_basis": content.get("evaluation_basis"),
        "evidence_category": content.get("evidence_category"),
        "action_profile_match": profile_match,
        "broad_context_outcome_prior": broad_context_prior,
        "knowledge_state": veto.get("state"),
        "knowledge_type": veto.get("memory_type") or veto.get("node_type"),
        "knowledge_state_tier": veto_knowledge_state_tier(veto),
        "knowledge_metrics": {
            "support_count": metrics.get("support_count"),
            "pass_rate": metrics.get("pass_rate"),
            "long_eval_pass_count": metrics.get("long_eval_pass_count"),
            "long_eval_fail_count": metrics.get("long_eval_fail_count"),
            "broad_context_outcome_prior": broad_context_prior,
        },
    }


def _sigmoid(value: float) -> float:
    if value < -40:
        return 0.0
    if value > 40:
        return 1.0
    return 1.0 / (1.0 + math.exp(-value))


def _resolve_profile_path(path_value: str | None) -> Path:
    if not path_value:
        return P.PROJECT_ROOT / "experiments" / "results" / "veto_risk_calibration_dev.json"
    path = Path(path_value)
    return path if path.is_absolute() else P.PROJECT_ROOT / path


@lru_cache(maxsize=8)
def _load_veto_risk_profile(path_text: str) -> dict[str, Any]:
    path = _resolve_profile_path(path_text)
    if not path.exists():
        return {"available": False, "path": str(path)}
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {"available": False, "path": str(path)}
    model = payload.get("model") if isinstance(payload.get("model"), dict) else {}
    if not model.get("coefficients") or not model.get("feature_stats"):
        return {"available": False, "path": str(path)}
    return {
        "available": True,
        "path": str(path),
        "schema_version": payload.get("schema_version"),
        "model": model,
        "config": payload.get("config") or {},
    }


def _num(value: Any) -> float:
    return float(value) if isinstance(value, (int, float)) else 0.0


def _metric_source(veto: dict[str, Any]) -> dict[str, Any]:
    metrics = veto.get("metrics") if isinstance(veto.get("metrics"), dict) else {}
    content = veto.get("content") if isinstance(veto.get("content"), dict) else {}
    content_metrics = content.get("metrics") if isinstance(content.get("metrics"), dict) else {}
    merged = {**content_metrics, **metrics}
    for key in ("support_count", "long_eval_pass_count", "long_eval_fail_count", "pass_rate"):
        if key not in merged and key in content:
            merged[key] = content.get(key)
    return merged


def _broad_context_outcome_prior(veto: dict[str, Any]) -> dict[str, Any]:
    content = veto.get("content") if isinstance(veto.get("content"), dict) else {}
    prior = content.get("broad_context_outcome_prior")
    return prior if isinstance(prior, dict) else {}


def _score_source(veto: dict[str, Any]) -> dict[str, Any]:
    for key in ("memory_score", "_score", "score_detail"):
        value = veto.get(key)
        if isinstance(value, dict):
            return value
    return {}


def _veto_feature_values(veto: dict[str, Any], similarity: dict[str, Any] | None = None) -> dict[str, float]:
    metrics = _metric_source(veto)
    score = _score_source(veto)
    bayes = score.get("bayesian_credibility") if isinstance(score.get("bayesian_credibility"), dict) else {}
    fields = veto_match_fields(veto)
    support = _num(metrics.get("support_count"))
    pass_n = _num(metrics.get("long_eval_pass_count"))
    fail_n = _num(metrics.get("long_eval_fail_count"))
    eval_total = pass_n + fail_n
    pass_rate = _num(metrics.get("pass_rate")) if metrics.get("pass_rate") is not None else (pass_n / eval_total if eval_total else 0.0)
    fail_rate = fail_n / eval_total if eval_total else 0.0
    raw = {
        "support_count": support,
        "pass_count": pass_n,
        "fail_count": fail_n,
        "pass_rate": pass_rate,
        "fail_rate": fail_rate,
        "log_support": math.log1p(max(0.0, support)),
        "bayes_fail_mean": (fail_n + 1.0) / (eval_total + 2.0) if eval_total else 0.5,
        "wilson_fail_lcb": fail_rate,
        "wilson_fail_ucb": fail_rate,
        "has_parameter": float(bool(fields.get("parameter_semantic_id"))),
        "has_direction": float(bool(fields.get("direction"))),
        "has_normalized_shape": 0.0,
        "distinct_vendor_count": 0.0,
        "distinct_system_count": 0.0,
        "distinct_region_count": 0.0,
        "recency_days": 0.0,
        "memory_match_count": 1.0,
        "memory_best_support_count": support,
        "memory_best_pass_count": pass_n,
        "memory_best_fail_count": fail_n,
        "memory_best_pass_rate": pass_rate,
        "memory_best_fail_pass_ratio": fail_n / (pass_n + 1.0),
        "memory_best_credibility_lcb": _num(bayes.get("credibility_lcb") or score.get("strategy_effectiveness")),
        "memory_best_posterior_mean": _num(bayes.get("posterior_mean")),
        "memory_best_overall": _num(score.get("overall")) if isinstance(score, dict) else 0.0,
        "memory_best_evidence_completeness": _num(score.get("evidence_completeness")),
        "memory_best_evaluation_credibility": _num(score.get("evaluation_credibility")),
        "memory_best_strategy_effectiveness": _num(score.get("strategy_effectiveness")),
        "memory_best_risk_intensity": _num(score.get("risk_intensity")),
        "memory_best_boundary_clarity": _num(score.get("boundary_clarity")),
        "memory_best_reusability": _num(score.get("reusability")),
        "memory_has_counter_evidence": float(veto.get("node_type") == "counter_evidence_memory" or veto.get("memory_type") == "counter_evidence_memory" or veto.get("state") == "counter_evidence"),
        "memory_has_reusable": float(veto.get("state") == "reusable"),
        "memory_has_restricted": float(veto.get("state") == "restricted"),
        "current_mixed_rule_veto": float(eval_total >= 3 and fail_n >= 3 and pass_rate < 0.45),
        "current_compile_rule_veto": float((eval_total >= 3 and fail_n >= 3 and pass_rate < 0.45) or fail_n >= 3),
        "strict_both_rule_veto": float(eval_total >= 5 and fail_n >= 5 and pass_rate < 0.30),
        "strict_compile_rule_veto": float((eval_total >= 5 and fail_n >= 5 and pass_rate < 0.30) or fail_n >= 5),
    }
    if similarity:
        components = similarity.get("components") if isinstance(similarity.get("components"), dict) else {}
        raw["has_parameter"] = max(raw["has_parameter"], float("action_parameter" in components))
        raw["has_direction"] = max(raw["has_direction"], float("action_direction" in components))
    return raw


def veto_risk_score(
    veto: dict[str, Any],
    similarity: dict[str, Any] | None,
    config: dict[str, Any],
) -> dict[str, Any]:
    if not config.get("use_veto_risk_calibration", True):
        return {"available": False, "score": None, "reason": "disabled"}
    profile = _load_veto_risk_profile(str(config.get("veto_risk_profile_path") or ""))
    if not profile.get("available"):
        return {"available": False, "score": None, "reason": "profile_unavailable", "path": profile.get("path")}
    model = profile.get("model") or {}
    coefficients = model.get("coefficients") or []
    stats = model.get("feature_stats") if isinstance(model.get("feature_stats"), dict) else {}
    weights = {str(row.get("feature")): _num(row.get("weight")) for row in coefficients if isinstance(row, dict)}
    raw = _veto_feature_values(veto, similarity)
    logit = weights.get("intercept", 0.0)
    for feature, meta in stats.items():
        if feature == "intercept":
            continue
        mean = _num((meta or {}).get("mean")) if isinstance(meta, dict) else 0.0
        std = _num((meta or {}).get("std")) if isinstance(meta, dict) else 1.0
        if std == 0:
            std = 1.0
        logit += weights.get(feature, 0.0) * ((_num(raw.get(feature)) - mean) / std)
    return {
        "available": True,
        "score": round(_sigmoid(logit), 6),
        "profile_path": profile.get("path"),
        "schema_version": profile.get("schema_version"),
    }


def _strong_action_match(similarity: dict[str, Any]) -> bool:
    components = similarity.get("components") if isinstance(similarity.get("components"), dict) else {}
    has_scheme = "action_scheme" in components or "action_signature" in components
    has_param = "action_parameter" in components or "action_signature" in components
    has_direction = "action_direction" in components or "action_signature" in components
    boundary = similarity.get("boundary") if isinstance(similarity.get("boundary"), dict) else {}
    has_boundary_mismatch = bool(boundary.get("mismatched"))
    return bool(has_scheme and has_param and has_direction and not has_boundary_mismatch)


def _specificity_aware_policy_enabled(config: dict[str, Any]) -> bool:
    return str(config.get("specificity_gate_policy") or "") == "action_specific_veto"


def _review_mixed_profile_counter_evidence(config: dict[str, Any], similarity: dict[str, Any]) -> bool:
    if str(config.get("profile_counter_evidence_policy") or "") != "review_mixed_trace_profile_match":
        return False
    if similarity.get("evidence_aggregation") != "trace_level_issue_scheme":
        return False
    profile_match = similarity.get("action_profile_match") if isinstance(similarity.get("action_profile_match"), dict) else {}
    if not profile_match.get("parameter_direction_match"):
        return False
    boundary = similarity.get("boundary") if isinstance(similarity.get("boundary"), dict) else {}
    return not bool(boundary.get("mismatched"))


def _review_high_failure_broad_context(config: dict[str, Any], similarity: dict[str, Any]) -> bool:
    if str(config.get("broad_context_prior_policy") or "") != "review_high_failure_lcb":
        return False
    if similarity.get("evidence_aggregation") != "fail_ticket_issue_scheme":
        return False
    prior = similarity.get("broad_context_outcome_prior")
    if not isinstance(prior, dict):
        return False
    evaluated = _num(prior.get("evaluated_count"))
    fail_n = _num(prior.get("long_eval_fail_count"))
    failure_lcb = _num(prior.get("failure_lcb"))
    min_evaluated = float(config.get("broad_context_min_evaluated", 30))
    min_fail = float(config.get("broad_context_min_fail_count", 10))
    threshold = float(config.get("broad_context_failure_lcb_review_threshold", 0.55))
    if evaluated < min_evaluated or fail_n < min_fail:
        return False
    boundary = similarity.get("boundary") if isinstance(similarity.get("boundary"), dict) else {}
    if boundary.get("mismatched"):
        return False
    return failure_lcb >= threshold


def _base_gate_decision(
    *,
    base_risk_level: str,
    base_needs_review: bool,
) -> tuple[str, str, bool, str]:
    risk_level = base_risk_level or "low"
    needs_review = bool(base_needs_review)
    if needs_review or risk_level == "high":
        return "require_review", risk_level, True, "base_risk_review_after_non_specific_veto"
    if risk_level == "medium":
        return "downgrade", risk_level, False, "base_medium_risk_after_non_specific_veto"
    return "accept", risk_level, False, "diagnostic_only_non_specific_veto"


def _gray_zone_review_evidence(
    similarity: dict[str, Any],
    risk_profile: dict[str, Any],
    config: dict[str, Any],
) -> dict[str, Any]:
    components = similarity.get("components") if isinstance(similarity.get("components"), dict) else {}
    boundary = similarity.get("boundary") if isinstance(similarity.get("boundary"), dict) else {}
    risk_score = risk_profile.get("score")
    review_min_risk = float(config.get("review_min_risk_score", 0.50))
    evidence = {
        "counter_evidence_state": similarity.get("knowledge_state_tier") == "counter_evidence",
        "restricted_gray_state": similarity.get("knowledge_state_tier") == "restricted_gray",
        "action_parameter": "action_parameter" in components or "action_signature" in components,
        "action_direction": "action_direction" in components or "action_signature" in components,
        "boundary_match": bool(boundary.get("matched")),
        "risk_calibration": bool(
            risk_profile.get("available")
            and risk_score is not None
            and float(risk_score) >= review_min_risk
        ),
    }
    required = [str(item) for item in config.get("gray_zone_review_requires") or []]
    if not required:
        should_review = any(evidence.values())
    else:
        should_review = any(evidence.get(item, False) for item in required)
    return {
        "policy": config.get("gray_zone_policy"),
        "should_review": bool(should_review),
        "evidence": evidence,
        "knowledge_state_tier": similarity.get("knowledge_state_tier"),
        "review_min_risk_score": review_min_risk,
    }


def _is_actionable_gate_similarity(similarity: dict[str, Any], config: dict[str, Any]) -> bool:
    if (
        similarity.get("knowledge_state_tier") == "restricted_gray"
        and config.get("restricted_gate_policy") == "diagnostic_only"
    ):
        return False
    return True


def apply_veto_gate(
    *,
    recommended: dict[str, Any],
    veto_candidates: list[dict[str, Any]],
    family: dict[str, Any] | None,
    base_risk_level: str,
    base_needs_review: bool,
    recommendation_confidence: float | None = None,
    gate_config: dict[str, Any] | None = None,
    query: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Return gate decision and diagnostics for one recommended action."""
    config = {**DEFAULT_GATE_CONFIG, **(gate_config or {})}
    tau_low = float(config["tau_low"])
    tau_high = float(config["tau_high"])
    if not 0 <= tau_low < tau_high <= 1:
        raise ValueError("gate thresholds must satisfy 0 <= tau_low < tau_high <= 1")
    confidence = max(0.0, min(1.0, float(recommendation_confidence or 0.0)))
    threshold_diagnostics = {
        "gate_config_version": config.get("version"),
        "tau_low": tau_low,
        "tau_high": tau_high,
        "recommendation_confidence": confidence,
    }
    if not recommended:
        return {
            "gate_decision": "reject",
            "risk_level": "high",
            "needs_human_review": True,
            "matched_vetoes": [],
            "veto_ids": [],
            "veto_hit": False,
            "veto_background_count": len(veto_candidates),
            "gate_reason": "no_recommendation",
            "gate_policy": "failcohort_veto_gate_v1",
            "threshold_band": "no_recommendation",
            **threshold_diagnostics,
        }

    scored = [
        veto_similarity(
            veto,
            recommended,
            family,
            query,
            use_boundary_match=bool(config.get("use_boundary_match", True)),
        )
        for veto in veto_candidates
    ]
    for item in scored:
        item["actionable_gate_evidence"] = _is_actionable_gate_similarity(item, config)
    scored.sort(key=lambda item: item["score"], reverse=True)
    actionable_scored = [item for item in scored if item.get("actionable_gate_evidence")]
    hit_score = float(actionable_scored[0]["score"]) if actionable_scored else 0.0
    matched_ids = [item["veto_id"] for item in actionable_scored if item["score"] >= tau_low and item["veto_id"]]
    matches = [veto for veto in veto_candidates if veto_id(veto) in set(matched_ids)]
    best_match = matches[0] if matches else None
    best_similarity = actionable_scored[0] if actionable_scored else {}
    risk_profile = veto_risk_score(best_match or {}, best_similarity, config) if best_match else {"available": False, "score": None}
    risk_score = risk_profile.get("score")
    hard_policy = str(config.get("hard_veto_policy") or "legacy")
    min_risk = float(config.get("hard_veto_min_risk_score", 0.95))
    strong_action = _strong_action_match(best_similarity)
    calibrated_hard_veto = (
        hard_policy == "calibrated_review_first"
        and hit_score >= tau_high
        and risk_profile.get("available")
        and risk_score is not None
        and float(risk_score) >= min_risk
        and (strong_action or not config.get("hard_veto_requires_strong_action", True))
    )
    if hit_score >= tau_high:
        if (
            _specificity_aware_policy_enabled(config)
            and not strong_action
            and _review_high_failure_broad_context(config, best_similarity)
        ):
            return {
                "gate_decision": "require_review",
                "risk_level": "high",
                "needs_human_review": True,
                "matched_vetoes": matches,
                "veto_ids": matched_ids,
                "veto_hit": True,
                "veto_background_count": len(veto_candidates),
                "gate_reason": "failcohort_hit_high_broad_context_failure_lcb_review",
                "gate_policy": _policy_name(config, "failcohort_veto_gate_specificity_broad_context_prior"),
                "threshold_band": "at_or_above_tau_high_broad_context_failure_lcb_review",
                "failcohort_hit_score": hit_score,
                "failcohort_matches": scored[:8],
                "veto_risk_calibration": risk_profile,
                "hard_veto_eligible": False,
                "strong_action_veto_match": False,
                "broad_context_prior_policy": config.get("broad_context_prior_policy"),
                **threshold_diagnostics,
            }
        if (
            _specificity_aware_policy_enabled(config)
            and not strong_action
            and _review_mixed_profile_counter_evidence(config, best_similarity)
        ):
            return {
                "gate_decision": "require_review",
                "risk_level": "high",
                "needs_human_review": True,
                "matched_vetoes": matches,
                "veto_ids": matched_ids,
                "veto_hit": True,
                "veto_background_count": len(veto_candidates),
                "gate_reason": "failcohort_hit_high_mixed_profile_review",
                "gate_policy": _policy_name(config, "failcohort_veto_gate_specificity_profile_review"),
                "threshold_band": "at_or_above_tau_high_profile_review",
                "failcohort_hit_score": hit_score,
                "failcohort_matches": scored[:8],
                "veto_risk_calibration": risk_profile,
                "hard_veto_eligible": False,
                "strong_action_veto_match": False,
                "profile_counter_evidence_policy": config.get("profile_counter_evidence_policy"),
                **threshold_diagnostics,
            }
        if _specificity_aware_policy_enabled(config) and not strong_action:
            gate_decision, risk_level, needs_review, threshold_band = _base_gate_decision(
                base_risk_level=base_risk_level,
                base_needs_review=base_needs_review,
            )
            return {
                "gate_decision": gate_decision,
                "risk_level": risk_level,
                "needs_human_review": needs_review,
                "matched_vetoes": [],
                "veto_ids": [],
                "veto_hit": False,
                "veto_background_count": len(veto_candidates),
                "gate_reason": "failcohort_hit_high_no_action_specificity_diagnostic",
                "gate_policy": _policy_name(config, "failcohort_veto_gate_specificity_aware"),
                "threshold_band": threshold_band,
                "failcohort_hit_score": 0.0,
                "diagnostic_failcohort_hit_score": hit_score,
                "diagnostic_veto_ids": matched_ids,
                "failcohort_matches": scored[:8],
                "veto_risk_calibration": risk_profile,
                "hard_veto_eligible": False,
                "strong_action_veto_match": False,
                **threshold_diagnostics,
            }
        if hard_policy == "calibrated_review_first" and not calibrated_hard_veto:
            return {
                "gate_decision": "require_review",
                "risk_level": "high",
                "needs_human_review": True,
                "matched_vetoes": matches,
                "veto_ids": matched_ids,
                "veto_hit": True,
                "veto_background_count": len(veto_candidates),
                "gate_reason": "failcohort_hit_high_review_calibrated",
                "gate_policy": _policy_name(config, "failcohort_veto_gate_v2_calibrated_review_first"),
                "threshold_band": "at_or_above_tau_high_review",
                "failcohort_hit_score": hit_score,
                "failcohort_matches": scored[:8],
                "veto_risk_calibration": risk_profile,
                "hard_veto_eligible": False,
                "strong_action_veto_match": strong_action,
                **threshold_diagnostics,
            }
        return {
            "gate_decision": "reject",
            "risk_level": "high",
            "needs_human_review": True,
            "matched_vetoes": matches,
            "veto_ids": matched_ids,
            "veto_hit": True,
            "veto_background_count": len(veto_candidates),
            "gate_reason": "failcohort_hit_high",
            "gate_policy": _policy_name(
                config,
                "failcohort_veto_gate_v2_calibrated_review_first" if calibrated_hard_veto else "failcohort_veto_gate_v1",
            ),
            "threshold_band": "at_or_above_tau_high",
            "failcohort_hit_score": hit_score,
            "failcohort_matches": scored[:8],
            "veto_risk_calibration": risk_profile,
            "hard_veto_eligible": calibrated_hard_veto or hard_policy != "calibrated_review_first",
            "strong_action_veto_match": strong_action,
            **threshold_diagnostics,
        }
    if hit_score >= tau_low:
        gray_zone = _gray_zone_review_evidence(best_similarity, risk_profile, config)
        if (
            hard_policy == "calibrated_review_first"
            and config.get("gray_zone_policy") == "evidence_required"
            and not gray_zone["should_review"]
        ):
            risk_level = base_risk_level or "low"
            needs_review = bool(base_needs_review)
            if needs_review or risk_level == "high":
                gate_decision = "require_review"
                threshold_band = "base_risk_review_after_weak_overlap"
            elif risk_level == "medium":
                gate_decision = "downgrade"
                threshold_band = "weak_overlap_downgrade"
            else:
                gate_decision = "accept"
                threshold_band = "weak_overlap_without_review_evidence"
            return {
                "gate_decision": gate_decision,
                "risk_level": risk_level,
                "needs_human_review": needs_review,
                "matched_vetoes": matches,
                "veto_ids": matched_ids,
                "veto_hit": False,
                "veto_background_count": len(veto_candidates),
                "gate_reason": "failcohort_hit_mid_weak_overlap_no_review_evidence",
                "gate_policy": _policy_name(config, "failcohort_veto_gate_v3_gray_zone_evidence"),
                "threshold_band": threshold_band,
                "failcohort_hit_score": hit_score,
                "failcohort_matches": scored[:8],
                "veto_risk_calibration": risk_profile,
                "gray_zone_review": gray_zone,
                "hard_veto_eligible": False,
                "strong_action_veto_match": strong_action,
                **threshold_diagnostics,
            }
        return {
            "gate_decision": "require_review",
            "risk_level": "high",
            "needs_human_review": True,
            "matched_vetoes": matches,
            "veto_ids": matched_ids,
            "veto_hit": True,
            "veto_background_count": len(veto_candidates),
            "gate_reason": "failcohort_hit_mid",
            "gate_policy": _policy_name(config, "failcohort_veto_gate_v1"),
            "threshold_band": "between_thresholds",
            "failcohort_hit_score": hit_score,
            "failcohort_matches": scored[:8],
            "veto_risk_calibration": risk_profile,
            "gray_zone_review": gray_zone,
            "hard_veto_eligible": False,
            "strong_action_veto_match": strong_action,
            **threshold_diagnostics,
        }

    risk_level = base_risk_level or "low"
    needs_review = bool(base_needs_review)
    if needs_review or risk_level == "high":
        gate_decision = "require_review"
        threshold_band = "base_risk_review"
    elif risk_level == "medium":
        gate_decision = "downgrade"
        threshold_band = "base_medium_risk"
    else:
        gate_decision = "accept"
        threshold_band = "below_tau_low"
    return {
        "gate_decision": gate_decision,
        "risk_level": risk_level,
        "needs_human_review": needs_review,
        "matched_vetoes": [],
        "veto_ids": [],
        "veto_hit": False,
        "veto_background_count": len(veto_candidates),
        "gate_reason": "risk_review" if needs_review or risk_level in {"high", "medium"} else "clear",
        "gate_policy": _policy_name(config, "failcohort_veto_gate_v1"),
        "threshold_band": threshold_band,
        "failcohort_hit_score": hit_score,
        "failcohort_matches": scored[:8],
        "veto_risk_calibration": risk_profile,
        "hard_veto_eligible": False,
        "strong_action_veto_match": strong_action,
        **threshold_diagnostics,
    }

"""Plan/memory ranking for ECHO-Mem shadow selection.

The current ranker scores memory candidates before the veto gate. Its main
controlled variable is the credibility term:

- full ECHO-Mem uses Beta-Binomial lower confidence bound (LCB)
- no-bayes ablation uses raw historical pass_rate

This keeps Bayesian calibration as a real ranking variable rather than a UI-only
score.
"""

from __future__ import annotations

import math
import json
from typing import Any

from ..scoring.bayesian_score import credibility_score


PARAM_CLUE_WEIGHTS = [
    ("parameter_semantic_id", 500),
    ("param_object", 220),
    ("param_en_name", 220),
    ("site_param_object", 120),
    ("site_param_en_name", 120),
]

DEFAULT_RANKER_CONFIG: dict[str, Any] = {
    "version": "ranker_v1",
    "weights": {
        "route_match": 0.35,
        "credibility": 0.45,
        "boundary_match": 0.10,
        "risk_penalty": 0.10,
    },
    "unknown_boundary_score": 0.5,
    "bayesian": {
        "alpha0": 1.0,
        "beta0": 1.0,
        "lcb_q": 0.05,
    },
}

_CREDIBILITY_CACHE: dict[tuple[int, float, float, float], float] = {}
_SCORE_BREAKDOWN_CACHE: dict[tuple[Any, ...], dict[str, Any]] = {}
_RANKED_MEMORIES_CACHE: dict[tuple[Any, ...], tuple[dict[str, Any], ...]] = {}


def _frozen_value(value: Any) -> Any:
    if isinstance(value, dict):
        return tuple(sorted((str(key), _frozen_value(item)) for key, item in value.items()))
    if isinstance(value, (list, tuple, set)):
        return tuple(_frozen_value(item) for item in value)
    return value


def _config_key(config: dict[str, Any]) -> str:
    return json.dumps(config, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def norm_values(*values: Any) -> set[str]:
    out = set()
    for value in values:
        if isinstance(value, list):
            out.update(str(v).strip().lower() for v in value if str(v or "").strip())
        elif str(value or "").strip():
            out.add(str(value).strip().lower())
    return out


def memory_credibility(
    memory: dict[str, Any],
    *,
    use_bayesian_credibility: bool,
    bayesian_config: dict[str, Any] | None = None,
) -> float:
    metrics = memory.get("metrics") if isinstance(memory.get("metrics"), dict) else {}
    content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
    if use_bayesian_credibility:
        config = bayesian_config or {}
        alpha0 = float(config.get("alpha0", 1.0))
        beta0 = float(config.get("beta0", 1.0))
        lcb_q = float(config.get("lcb_q", 0.05))
        cache_key = (id(memory), alpha0, beta0, lcb_q)
        if cache_key in _CREDIBILITY_CACHE:
            return _CREDIBILITY_CACHE[cache_key]
        value = float(credibility_score(
            metrics,
            alpha0=alpha0,
            beta0=beta0,
            lcb_q=lcb_q,
        ))
        _CREDIBILITY_CACHE[cache_key] = value
        return value
    return float(metrics.get("pass_rate") or content.get("pass_rate") or 0)


def memory_candidate_score(
    memory: dict[str, Any],
    root: dict[str, Any],
    param_clues: dict[str, set[str]],
    *,
    use_bayesian_credibility: bool = True,
    query: dict[str, Any] | None = None,
    ranker_config: dict[str, Any] | None = None,
) -> float:
    return memory_candidate_score_breakdown(
        memory,
        root,
        param_clues,
        use_bayesian_credibility=use_bayesian_credibility,
        query=query,
        ranker_config=ranker_config,
    )["total"]


def _config(ranker_config: dict[str, Any] | None) -> dict[str, Any]:
    config = dict(DEFAULT_RANKER_CONFIG)
    config["weights"] = dict(DEFAULT_RANKER_CONFIG["weights"])
    config["bayesian"] = dict(DEFAULT_RANKER_CONFIG["bayesian"])
    if isinstance(ranker_config, dict):
        config.update({key: value for key, value in ranker_config.items() if key not in {"weights", "bayesian"}})
        if isinstance(ranker_config.get("weights"), dict):
            config["weights"].update(ranker_config["weights"])
        if isinstance(ranker_config.get("bayesian"), dict):
            config["bayesian"].update(ranker_config["bayesian"])
    return config


def _route_match(memory: dict[str, Any], query: dict[str, Any]) -> tuple[float, dict[str, bool]]:
    app = memory.get("applicability") if isinstance(memory.get("applicability"), dict) else {}
    fields = [
        ("issue_type", "issue_types", 0.40),
        ("vendor", "vendors", 0.25),
        ("system", "systems", 0.20),
        ("region", "regions", 0.10),
        ("band", "bands", 0.05),
    ]
    matched: dict[str, bool] = {}
    score = 0.0
    denominator = 0.0
    for query_key, app_key, weight in fields:
        query_value = str(query.get(query_key) or "").strip().lower()
        if not query_value or query_value.startswith("未知") or query_value == "未标注":
            continue
        denominator += weight
        hit = query_value in norm_values(app.get(app_key))
        matched[query_key] = hit
        if hit:
            score += weight
    return (score / denominator if denominator else 0.0), matched


def _boundary_match(memory: dict[str, Any], unknown_score: float) -> tuple[float, bool, str]:
    content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
    pattern = content.get("value_pattern") if isinstance(content.get("value_pattern"), dict) else {}
    boundary = pattern.get("effective_parameter_range") or content.get("boundary_conditions")
    if not isinstance(boundary, dict) or not boundary:
        return unknown_score, False, "heldout_prechange_value_unavailable"
    confidence = str(boundary.get("confidence") or "").lower()
    if confidence in {"parsed", "direct"} or (boundary.get("min") is not None and boundary.get("max") is not None):
        return 1.0, True, "complete_candidate_boundary"
    return 0.7, True, "partial_candidate_boundary"


def _risk_penalty(memory: dict[str, Any]) -> tuple[float, list[str]]:
    content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
    metrics = memory.get("metrics") if isinstance(memory.get("metrics"), dict) else {}
    reasons: list[str] = []
    penalty = 0.0
    state = str(memory.get("state") or "")
    if state == "counter_evidence":
        penalty = max(penalty, 1.0)
        reasons.append("counter_evidence_state")
    elif state == "restricted":
        penalty = max(penalty, 0.7)
        reasons.append("restricted_state")
    failure_rate = metrics.get("execution_failure_rate", content.get("execution_failure_rate"))
    try:
        failure = max(0.0, min(1.0, float(failure_rate)))
    except (TypeError, ValueError):
        failure = 0.0
    if failure:
        penalty = max(penalty, failure)
        reasons.append("execution_failure_rate")
    return penalty, reasons


def memory_candidate_score_breakdown(
    memory: dict[str, Any],
    root: dict[str, Any],
    param_clues: dict[str, set[str]],
    *,
    use_bayesian_credibility: bool = True,
    query: dict[str, Any] | None = None,
    ranker_config: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Return the four paper terms and their weighted total in [approximately -1, 1]."""
    config = _config(ranker_config)
    cache_key = (
        id(memory),
        _frozen_value(root),
        _frozen_value(param_clues),
        bool(use_bayesian_credibility),
        _frozen_value(query or {}),
        _config_key(config),
    )
    cached = _SCORE_BREAKDOWN_CACHE.get(cache_key)
    if cached is not None:
        return cached
    weights = config["weights"]
    content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
    metrics = memory.get("metrics") if isinstance(memory.get("metrics"), dict) else {}
    support = float(metrics.get("support_count") or content.get("support_count") or 0)
    credibility = memory_credibility(
        memory,
        use_bayesian_credibility=use_bayesian_credibility,
        bayesian_config=config["bayesian"],
    )
    support_score = min(1.0, math.log1p(max(0.0, support)) / math.log1p(200.0))
    credibility_term = min(1.0, max(0.0, credibility * 0.8 + support_score * 0.2))

    route_term, route_fields = _route_match(memory, query or {})

    root_key = str(root.get("root_cause_key") or "").lower()
    root_l2 = str(root.get("root_cause_l2") or "").lower()
    root_values = norm_values(
        content.get("root_causes"),
        content.get("solution_proxy_root_causes"),
        content.get("solution_proxy_root_cause"),
    )
    if root_key and root_key in root_values:
        route_term = min(1.0, route_term + 0.15)
    elif root_l2 and str(content.get("scheme_group") or "").strip().lower() == root_l2:
        route_term = min(1.0, route_term + 0.10)

    clue_hits: list[str] = []
    for key, weight in PARAM_CLUE_WEIGHTS:
        values = param_clues.get(key) or set()
        if not values:
            continue
        candidate_value = str(content.get(key) or "").strip().lower()
        if candidate_value and candidate_value in values:
            clue_hits.append(key)
    if clue_hits:
        route_term = min(1.0, route_term + 0.10)

    if memory.get("state") == "reusable":
        credibility_term = min(1.0, credibility_term + 0.05)
    elif memory.get("state") == "validated":
        credibility_term = min(1.0, credibility_term + 0.03)

    boundary_term, boundary_available, boundary_reason = _boundary_match(
        memory,
        float(config.get("unknown_boundary_score", 0.5)),
    )
    risk_term, risk_reasons = _risk_penalty(memory)
    weighted = {
        "route_match": route_term * float(weights.get("route_match", 0.0)),
        "credibility": credibility_term * float(weights.get("credibility", 0.0)),
        "boundary_match": boundary_term * float(weights.get("boundary_match", 0.0)),
        "risk_penalty": risk_term * float(weights.get("risk_penalty", 0.0)),
    }
    total = weighted["route_match"] + weighted["credibility"] + weighted["boundary_match"] - weighted["risk_penalty"]
    result = {
        "route_match": round(route_term, 6),
        "credibility": round(credibility_term, 6),
        "boundary_match": round(boundary_term, 6),
        "risk_penalty": round(risk_term, 6),
        "weighted": {key: round(value, 6) for key, value in weighted.items()},
        "total": round(total, 6),
        "route_fields": route_fields,
        "parameter_clue_hits": clue_hits,
        "boundary_available": boundary_available,
        "boundary_reason": boundary_reason,
        "risk_reasons": risk_reasons,
        "credibility_mode": "echo_lcb" if use_bayesian_credibility else "raw_pass_rate",
        "bayesian_config": config["bayesian"] if use_bayesian_credibility else None,
        "config_version": config.get("version"),
    }
    _SCORE_BREAKDOWN_CACHE[cache_key] = result
    return result


def rank_memories(
    memories: list[dict[str, Any]],
    root: dict[str, Any],
    param_clues: dict[str, set[str]],
    *,
    use_bayesian_credibility: bool = True,
    query: dict[str, Any] | None = None,
    ranker_config: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    config = _config(ranker_config)
    cache_key = (
        tuple(id(memory) for memory in memories),
        _frozen_value(root),
        _frozen_value(param_clues),
        bool(use_bayesian_credibility),
        _frozen_value(query or {}),
        _config_key(config),
    )
    cached = _RANKED_MEMORIES_CACHE.get(cache_key)
    if cached is not None:
        return list(cached)
    ranked = sorted(
        memories,
        key=lambda m: memory_candidate_score(
            m,
            root,
            param_clues,
            use_bayesian_credibility=use_bayesian_credibility,
            query=query,
            ranker_config=ranker_config,
        ),
        reverse=True,
    )
    _RANKED_MEMORIES_CACHE[cache_key] = tuple(ranked)
    return ranked

"""Redact trace fields that must not appear in shadow decision inputs."""

from __future__ import annotations

from copy import deepcopy
from typing import Any


_REDACT_ACTION_KEYS = (
    "after_value",
    "long_eval_result",
    "long_eval",
    "exec_failure_reason",
)


def redact_trace_for_decision(trace: dict[str, Any]) -> dict[str, Any]:
    """Return a copy safe for shadow decide: hide labels and post-change values."""
    out = deepcopy(trace)
    agg = out.get("aggregate") or {}
    if "ticket_outcome" in agg:
        agg = dict(agg)
        agg["ticket_outcome"] = "withheld"
        out["aggregate"] = agg
    actions = []
    for action in out.get("actions") or []:
        a = dict(action)
        for key in _REDACT_ACTION_KEYS:
            if key in a:
                a[key] = "withheld"
        actions.append(a)
    out["actions"] = actions
    return out


def ticket_only_trace_for_decision(trace: dict[str, Any]) -> dict[str, Any]:
    """Return the paper-safe pre-decision context; held-out actions stay evaluator-only."""
    ticket = trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}
    return {
        "trace_id": trace.get("trace_id"),
        "ticket": deepcopy(ticket),
    }


def trace_query(trace: dict[str, Any]) -> dict[str, Any]:
    ticket = trace.get("ticket") or {}
    province_issue = str(ticket.get("province_issue_type") or "")
    scenario = ""
    if "{" in province_issue and "}" in province_issue:
        scenario = province_issue[province_issue.index("{") + 1 : province_issue.index("}")]
    return {
        "issue_type": ticket.get("primary_issue_type") or "未标注",
        "vendor": ticket.get("vendor") or "未知厂家",
        "system": ticket.get("system") or "未知制式",
        "region": ticket.get("region") or "未知",
        "band": ticket.get("band") or "",
        "is_indoor": ticket.get("is_indoor") or "",
        "scenario": scenario,
        "cell_name": ticket.get("cell_name") or "",
        "ticket_id": ticket.get("id") or "",
    }

