PARAM_CLUE_KEYS = (
    "param_object",
    "param_en_name",
    "site_param_object",
    "site_param_en_name",
    "parameter_semantic_id",
)

_MEMORY_ID_CACHE: dict[int, dict[str, dict[str, Any]]] = {}
_EPISODE_CANDIDATE_ID_CACHE: dict[int, dict[str, dict[str, Any]]] = {}


def _decision_id(trace_id: str) -> str:
    return "sd_" + hashlib.md5(f"{trace_id}|{cio.now_iso()}".encode()).hexdigest()[:12]


def _memories_by_id(memories: list[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    cache_key = id(memories)
    cached = _MEMORY_ID_CACHE.get(cache_key)
    if cached is not None:
        return cached
    indexed = {str(m.get("memory_id")): m for m in memories if m.get("memory_id")}
    _MEMORY_ID_CACHE[cache_key] = indexed
    return indexed


def _episode_candidates_by_id(candidates: list[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    cache_key = id(candidates)
    cached = _EPISODE_CANDIDATE_ID_CACHE.get(cache_key)
    if cached is not None:
        return cached
    indexed = {str(c.get("episode_id")): c for c in candidates if c.get("episode_id")}
    _EPISODE_CANDIDATE_ID_CACHE[cache_key] = indexed
    return indexed


def _node_metrics(node: dict[str, Any]) -> dict[str, Any]:
    return node.get("metrics") if isinstance(node.get("metrics"), dict) else {}


def _root_context(trace: dict[str, Any]) -> dict[str, Any]:
    roots = Counter()
    for action in trace.get("actions") or []:
        if not isinstance(action, dict):
            continue
        l1 = str(action.get("root_cause_l1") or action.get("param_kind") or "").strip()
        l2 = str(action.get("root_cause_l2") or action.get("scheme_group") or "").strip()
        key = str(action.get("root_cause_key") or " / ".join(x for x in [l1, l2] if x) or "").strip()
        if key:
            roots[(key, l1, l2)] += 1
    if not roots:
        return {"root_cause_key": "", "root_cause_l1": "", "root_cause_l2": ""}
    (key, l1, l2), count = roots.most_common(1)[0]
    return {"root_cause_key": key, "root_cause_l1": l1, "root_cause_l2": l2, "action_count": count}


def _param_clues(trace: dict[str, Any]) -> dict[str, set[str]]:
    keys = PARAM_CLUE_KEYS
    clues: dict[str, set[str]] = {key: set() for key in keys}
    ticket = trace.get("ticket") if isinstance(trace.get("ticket"), dict) else {}
    vendor = str(ticket.get("vendor") or "").lower()
    system = str(ticket.get("system") or "").lower()
    for action in trace.get("actions") or []:
        if not isinstance(action, dict):
            continue
        for key in keys:
            value = str(action.get(key) or "").strip()
            if value:
                clues[key].add(value.lower())
        if action.get("param_object") and (action.get("param_en_name") or action.get("param_cn_name")):
            semantic = ".".join(
                x
                for x in [
                    vendor,
                    system,
                    str(action.get("param_object") or "").strip().lower(),
                    str(action.get("param_en_name") or action.get("param_cn_name") or "").strip().lower(),
                ]
                if x
            )
            if semantic:
                clues["parameter_semantic_id"].add(semantic)
    return clues


def _family_score(family: dict[str, Any], query: dict[str, Any], root: dict[str, Any] | None = None) -> float:
    stats = family.get("stats") or {}
    support = float(stats.get("support_count") or 0)
    pass_rate = float(stats.get("best_pass_rate") or 0)
    score = support * 0.5 + pass_rate * 80
    root_l2 = (root or {}).get("root_cause_l2")
    root_key = (root or {}).get("root_cause_key") or ""
    scheme_group = family.get("scheme_group")
    if root_l2 and scheme_group and root_l2 == scheme_group:
        score += 900
    elif scheme_group and scheme_group in root_key:
        score += 450
    if query.get("vendor") and family.get("vendor") == query.get("vendor"):
        score += 500
    if query.get("system") and family.get("system") == query.get("system"):
        score += 300
    # Prefer a family that already has executable plans and semantic episodes.
    score += float(stats.get("playbook_count") or 0) * 8
    score += float(stats.get("strategy_count") or 0) * 4
    score += float(stats.get("semantic_episode_count") or 0) * 2
    return score


def _family_matches_root(family: dict[str, Any], root: dict[str, Any]) -> bool:
    scheme_group = str(family.get("scheme_group") or "").strip()
    root_l2 = str(root.get("root_cause_l2") or "").strip()
    root_key = str(root.get("root_cause_key") or "").strip()
    return bool(scheme_group and ((root_l2 and scheme_group == root_l2) or scheme_group in root_key))


def _best_node(nodes: list[dict[str, Any]]) -> dict[str, Any] | None:
    if not nodes:
        return None
    return sorted(nodes, key=lambda n: float(n.get("score") or 0), reverse=True)[0]


def _memory_matches_root(memory: dict[str, Any], root: dict[str, Any]) -> bool:
    content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
    root_key = str(root.get("root_cause_key") or "").strip().lower()
    root_l2 = str(root.get("root_cause_l2") or "").strip().lower()
    root_values = norm_values(content.get("root_causes"), content.get("solution_proxy_root_causes"), content.get("solution_proxy_root_cause"))
    scheme_group = str(content.get("scheme_group") or "").strip().lower()
    return bool((root_key and root_key in root_values) or (root_l2 and scheme_group == root_l2))


def _memory_matches_param_clues(memory: dict[str, Any], param_clues: dict[str, set[str]]) -> bool:
    content = memory.get("content") if isinstance(memory.get("content"), dict) else {}
    for key in ("parameter_semantic_id", "param_object", "param_en_name", "site_param_object", "site_param_en_name"):
        values = param_clues.get(key) or set()
        candidate_value = str(content.get(key) or "").strip().lower()
        if candidate_value and candidate_value in values:
            return True
    return False


def _memory_id(memory: dict[str, Any]) -> str:
    return str(memory.get("memory_id") or "")


def _merge_ranked_ids(primary: list[str], fallback: list[str], *, limit: int = 64) -> list[str]:
    """Put primary hits first, then keep fallback order without dropping non-matching candidates."""
    seen: set[str] = set()
    out: list[str] = []
    for mid in primary + fallback:
        if not mid or mid in seen:
            continue
        seen.add(mid)
        out.append(mid)
        if len(out) >= limit:
            break
    return out


def _walk_stage(name: str, input_value: str, before_ids: list[str], after_ids: list[str], note: str) -> dict[str, Any]:
    before_unique = list(dict.fromkeys([x for x in before_ids if x]))
    after_unique = list(dict.fromkeys([x for x in after_ids if x]))
    return {
        "stage": name,
        "input": input_value,
        "before_count": len(before_unique),
        "after_count": len(after_unique),
        "kept_candidate_ids": after_unique[:16],
        "dropped_count": max(0, len(before_unique) - len(after_unique)),
        "status": "hit" if after_unique else "miss",
        "note": note,
    }


def _node_is_positive_candidate(node: dict[str, Any]) -> bool:
    return node.get("state") in SHADOW_POSITIVE_CANDIDATE_STATES


def _family_leaf_ids(families: list[dict[str, Any]], *, positive_only: bool = True) -> list[str]:
    ids: list[str] = []
    for family in families:
        for node in (family.get("strategies") or []) + (family.get("playbooks") or []):
            if not node.get("id"):
                continue
            if positive_only and not _node_is_positive_candidate(node):
                continue
            ids.append(str(node["id"]))
    return list(dict.fromkeys(ids))


def _build_walk_funnel(
    *,
    navigation_map: dict[str, Any] | None,
    query: dict[str, Any],
    root: dict[str, Any],
    ranked_ids: list[str],
    root_boosted: list[str],
    param_boosted: list[str],
    final_ids: list[str],
) -> list[dict[str, Any]]:
    issues = (navigation_map or {}).get("issues") or []
    all_families = [family for issue in issues for family in (issue.get("families") or [])]
    all_leaf_ids = _family_leaf_ids(all_families)
    issue_families = [
        family for issue in issues
        if issue.get("issue_type") == query.get("issue_type")
        for family in (issue.get("families") or [])
    ]
    issue_leaf_ids = _family_leaf_ids(issue_families)
    root_families = [family for family in issue_families if _family_matches_root(family, root)]
    root_leaf_ids = _family_leaf_ids(root_families)
    env_families = [
        family for family in (root_families or issue_families)
        if (not query.get("vendor") or family.get("vendor") == query.get("vendor"))
        and (not query.get("system") or family.get("system") == query.get("system"))
    ]
    env_leaf_ids_raw = _family_leaf_ids(env_families, positive_only=False)
    env_leaf_ids = _family_leaf_ids(env_families, positive_only=True)

    stages = [
        _walk_stage("全量候选", "validated + reusable", all_leaf_ids, all_leaf_ids, "正向候选叶子全集（已验证/可复用）"),
        _walk_stage("问题类型", str(query.get("issue_type") or "—"), all_leaf_ids, issue_leaf_ids, "进入知识地图的问题节点"),
        _walk_stage("根因标签", str(root.get("root_cause_key") or "—"), issue_leaf_ids, root_leaf_ids or issue_leaf_ids, "type2 对齐方案族；无命中时保留同问题候选"),
        _walk_stage("厂家 / 制式", f"{query.get('vendor') or '—'} / {query.get('system') or '—'}", root_leaf_ids or issue_leaf_ids, env_leaf_ids_raw or root_leaf_ids or issue_leaf_ids, "同厂家同制式"),
        _walk_stage("可推荐态", "validated + reusable", env_leaf_ids_raw or root_leaf_ids or issue_leaf_ids, env_leaf_ids or env_leaf_ids_raw or root_leaf_ids or issue_leaf_ids, "剔除 restricted 等不可推荐态"),
        _walk_stage("候选排序", "support + pass_rate", env_leaf_ids or root_leaf_ids or issue_leaf_ids, ranked_ids, "映射到策略/组合记忆并排序"),
        _walk_stage("根因重排", str(root.get("root_cause_key") or "—"), ranked_ids, root_boosted, "根因命中排前，未命中仍保留"),
        _walk_stage("参数线索重排", "参数对象 / OMC", root_boosted, param_boosted, "参数线索命中排前，未命中仍保留"),
        _walk_stage("Top 候选", "排序后 Top 8", param_boosted, final_ids, "进入方案生成候选表"),
    ]
    return stages


def _recommended_from_strategy_node(node: dict[str, Any]) -> dict[str, Any]:
    delta_buckets = node.get("delta_buckets") if isinstance(node.get("delta_buckets"), list) else []
    return {
        "scheme_group": node.get("scheme_group") or "",
        "scheme_id": node.get("scheme_id") or "",
        "parameter_semantic_id": node.get("parameter_semantic_id") or "",
        "param_cn_name": node.get("param_cn_name") or "",
        "value_type": node.get("value_type") or "",
        "direction": node.get("direction") or "",
        "suggested_delta": delta_buckets[0] if delta_buckets else "",
        "value_pattern_id": "",
    }


def _recommended_from_playbook_memory(memory: dict[str, Any] | None) -> dict[str, Any]:
    if not memory:
        return {}
    content = memory.get("content") or {}
    comps = content.get("components") or []
    first = comps[0] if comps else {}
    return {
        "scheme_group": first.get("scheme_group") or content.get("scheme_group") or "",
        "scheme_id": first.get("scheme_id") or "",
        "parameter_semantic_id": first.get("parameter_semantic_id") or "",
        "param_cn_name": first.get("param_cn_name") or "",
        "value_type": first.get("value_type") or "",
        "direction": first.get("direction") or "",
        "suggested_delta": (first.get("delta_buckets") or [None])[0] or first.get("delta_bucket") or "",
        "value_pattern_id": first.get("signature") or "",
    }


def _episode_pairs_from_family(
    family: dict[str, Any],
    candidates_by_id: dict[str, dict[str, Any]],
    episodes_by_id: dict[str, dict[str, Any]],
    *,
    limit: int = 5,
) -> list[dict[str, Any]]:
    pairs: list[dict[str, Any]] = []
    for node in (family.get("episodes") or [])[:limit]:
        eid = node.get("id") or ""
        candidate = candidates_by_id.get(eid)
        if not candidate:
            continue
        episode = episodes_by_id.get(eid)
        pairs.append({
            "episode_id": eid,
            "candidate_id": eid,
            "has_semantic": episode is not None,
            "candidate": candidate,
            "episode": episode,
        })
    return pairs


def _select_navigation_path(
    navigation_map: dict[str, Any] | None,
    query: dict[str, Any],
    root: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    if not navigation_map:
        return None
    issues = navigation_map.get("issues") or []
    issue = next((x for x in issues if x.get("issue_type") == query.get("issue_type")), None)
    if not issue:
        return None
    families = issue.get("families") or []
    family_candidates = sorted(families, key=lambda f: _family_score(f, query, root), reverse=True)
    family = family_candidates[0] if family_candidates else None
    if not family:
        return {
            "issue": {"issue_id": issue.get("issue_id"), "issue_type": issue.get("issue_type")},
            "family": None,
            "selected_strategy": None,
            "selected_playbook": None,
            "supporting_episodes": [],
            "vetoes": issue.get("vetoes") or [],
            "veto_background_count": len(issue.get("vetoes") or []),
            "selection_policy": "navigation_rule_v1",
        }
    strategy = _best_node([n for n in (family.get("strategies") or []) if _node_is_positive_candidate(n)])
    playbook = _best_node([n for n in (family.get("playbooks") or []) if _node_is_positive_candidate(n)])
    episodes = (family.get("episodes") or [])[:5]
    return {
        "issue": {
            "issue_id": issue.get("issue_id"),
            "issue_type": issue.get("issue_type"),
            "stats": issue.get("stats") or {},
        },
        "family": {
            "family_id": family.get("family_id"),
            "issue_type": family.get("issue_type"),
            "vendor": family.get("vendor"),
            "system": family.get("system"),
            "scheme_group": family.get("scheme_group"),
            "stats": family.get("stats") or {},
        },
        "_family_nodes": family,
        "_candidate_family_nodes": family_candidates,
        "selected_strategy": strategy,
        "selected_playbook": playbook,
        "supporting_episodes": episodes,
        "vetoes": issue.get("vetoes") or [],
        "veto_background_count": len(issue.get("vetoes") or []),
        "selection_policy": "navigation_rule_v1",
    }


def _current_parameter_snapshot_for(
    trace: dict[str, Any],
    parameter_semantic_id: str | None,
) -> dict[str, Any] | None:
    snapshots = (
        trace.get("pre_decision_parameter_snapshot")
        or trace.get("parameter_snapshot")
        or trace.get("current_parameter_snapshot")
    )
    if not isinstance(snapshots, dict):
        return None
    if snapshots.get("coverage_scope") != "candidate_parameter_set":
        return None
    parameters = snapshots.get("parameters")
    if not isinstance(parameters, dict):
        return None
    declared = snapshots.get("candidate_parameter_semantic_ids")
    if isinstance(declared, list):
        declared_ids = {str(item) for item in declared if item}
        if not declared_ids or not declared_ids.issubset(set(parameters)):
            return None
    if parameter_semantic_id and isinstance(parameters.get(parameter_semantic_id), dict):
        return {
            **parameters[parameter_semantic_id],
            "snapshot_policy": "candidate_parameter_set_v1",
            "coverage_scope": snapshots.get("coverage_scope"),
        }
    return None


def shadow_decide(
    trace: dict[str, Any],
    *,
    memories: list[dict[str, Any]],
    episode_candidates: list[dict[str, Any]],
    episodes_by_id: dict[str, dict[str, Any]],
    navigation_map: dict[str, Any] | None = None,
    vetoes_from_retrieval: list[dict[str, Any]] | None = None,
    use_bayesian_credibility: bool = True,
    allow_heldout_action_context: bool = False,
    use_action_value_selector: bool = False,
    ranker_config: dict[str, Any] | None = None,
    gate_config: dict[str, Any] | None = None,
) -> dict[str, Any]:
    query = trace_query(trace)
    root = _root_context(trace) if allow_heldout_action_context else {
        "root_cause_key": "",
        "root_cause_l1": "",
        "root_cause_l2": "",
    }
    param_clues = _param_clues(trace) if allow_heldout_action_context else {
        key: set() for key in PARAM_CLUE_KEYS
    }
    memories_by_id = _memories_by_id(memories)
    candidates_by_id = _episode_candidates_by_id(episode_candidates)
    nav_path = _select_navigation_path(navigation_map, query, root)
    retrieved = retrieve_memories(memories, query, limit=8)
    family_nodes = (nav_path or {}).get("_family_nodes") or (nav_path or {}).get("family")
    if nav_path and family_nodes:
        veto_candidates = nav_path.get("vetoes") or []
        episode_pairs = _episode_pairs_from_family(family_nodes, candidates_by_id, episodes_by_id, limit=5)
        family_pool = (nav_path or {}).get("_candidate_family_nodes") or [family_nodes]
        rooted_family_pool = [fam for fam in family_pool if _family_matches_root(fam, root)] or family_pool
        env_family_pool = [
            fam for fam in rooted_family_pool
            if (not query.get("vendor") or fam.get("vendor") == query.get("vendor"))
            and (not query.get("system") or fam.get("system") == query.get("system"))
        ] or rooted_family_pool
        strategy_nodes: list[dict[str, Any]] = []
        playbook_nodes: list[dict[str, Any]] = []
        for fam in env_family_pool:
            strategy_nodes.extend(fam.get("strategies") or [])
            playbook_nodes.extend(fam.get("playbooks") or [])
        strategies = [
            memories_by_id[node.get("id")]
            for node in strategy_nodes
            if node.get("id") in memories_by_id
            and is_shadow_positive_candidate(memories_by_id[node.get("id")])
        ]
        playbooks = [
            memories_by_id[node.get("id")]
            for node in playbook_nodes
            if node.get("id") in memories_by_id
            and is_shadow_positive_candidate(memories_by_id[node.get("id")])
        ]
        strategies = rank_memories(
            strategies,
            root,
            param_clues,
            use_bayesian_credibility=use_bayesian_credibility,
            query=query,
            ranker_config=ranker_config,
        )
        playbooks = rank_memories(
            playbooks,
            root,
            param_clues,
            use_bayesian_credibility=use_bayesian_credibility,
            query=query,
            ranker_config=ranker_config,
        )
    else:
        veto_candidates = vetoes_from_retrieval if vetoes_from_retrieval is not None else retrieved["vetoes"]
        episode_pairs = retrieve_episode_pairs(episode_candidates, episodes_by_id, query, limit=5)
        strategies = rank_memories(
            retrieved["strategies"],
            root,
            param_clues,
            use_bayesian_credibility=use_bayesian_credibility,
            query=query,
            ranker_config=ranker_config,
        )
        playbooks = rank_memories(
            retrieved["playbooks"],
            root,
            param_clues,
            use_bayesian_credibility=use_bayesian_credibility,
            query=query,
            ranker_config=ranker_config,
        )

    recommended: dict[str, Any] = {}
    selected_memory: dict[str, Any] | None = None
    reason_parts: list[str] = []

    if strategies:
        top = strategies[0]
        selected_memory = top
        content = top.get("content") or {}
        pattern = content.get("value_pattern") or {}
        observed_changes = content.get("observed_changes") if isinstance(content.get("observed_changes"), list) else None
        current_parameter_snapshot = _current_parameter_snapshot_for(
            trace,
            content.get("parameter_semantic_id"),
        )
        value_selection = (
            select_action_value(
                pattern,
                observed_changes=observed_changes,
                current_parameter_snapshot=current_parameter_snapshot,
            )
            if use_action_value_selector
            else {
                "selected": False,
                "suggested_delta": pattern.get("delta_bucket") or "",
                "value_pattern_id": pattern.get("pattern_id") or "",
                "selection_policy": "pattern_default",
                "reason": "action_value_selector_disabled",
                "candidates": [],
            }
        )
        recommended = {
            "scheme_group": content.get("scheme_group") or "",
            "scheme_id": content.get("scheme_id") or "",
            "parameter_semantic_id": content.get("parameter_semantic_id") or "",
            "param_cn_name": content.get("param_cn_name") or "",
            "value_type": pattern.get("value_type") or content.get("value_type") or "",
            "direction": pattern.get("direction") or "",
            "suggested_delta": value_selection.get("suggested_delta") or pattern.get("delta_bucket") or "",
            "value_pattern_id": pattern.get("pattern_id") or "",
        }
        if use_action_value_selector:
            recommended["value_selection"] = value_selection
        content = top.get("content") or {}
        pr = content.get("pass_rate")
        reason_parts.append(
            f"沿知识地图选择策略记忆 {top.get('title') or top.get('memory_id')}；"
            f"历史动作级通过率约 {round((pr or 0) * 100)}%。",
        )
        if nav_path and nav_path.get("family"):
            reason_parts.append(
                f"路径：{nav_path['issue']['issue_type']} → "
                f"{nav_path['family']['vendor']}/{nav_path['family']['system']}/"
                f"{nav_path['family']['scheme_group']}。",
            )
        risk = "medium" if (pr or 0) < 0.7 else "low"
        needs_review = (pr or 0) < 0.5
    elif playbooks:
        if nav_path and nav_path.get("selected_playbook"):
            top_node = nav_path["selected_playbook"]
            top = memories_by_id.get(top_node.get("id"), playbooks[0])
            recommended = _recommended_from_playbook_memory(top)
        else:
            top = playbooks[0]
            recommended = _recommended_from_playbook_memory(top)
        selected_memory = top
        content = top.get("content") or {}
        pr = content.get("pass_rate")
        reason_parts.append(
            f"沿知识地图选择组合方案 {top.get('title') or top.get('memory_id')}；"
            f"工单级通过率约 {round((pr or 0) * 100)}%。",
        )
        risk = "medium"
        needs_review = True
    else:
        reason_parts.append("未检索到同问题类型的可用策略/组合记忆。")
        risk = "high"
        needs_review = True

    family_group = ((nav_path or {}).get("family") or {}).get("scheme_group")
    if recommended and not recommended.get("scheme_group") and family_group:
        recommended["scheme_group"] = family_group

    veto_candidates = [
        memories_by_id.get(veto.get("memory_id") or veto.get("id"), veto)
        for veto in veto_candidates
    ]

    selected_score = memory_candidate_score_breakdown(
        selected_memory or {},
        root,
        param_clues,
        use_bayesian_credibility=use_bayesian_credibility,
        query=query,
        ranker_config=ranker_config,
    ) if selected_memory else None
    gate = apply_veto_gate(
        recommended=recommended,
        veto_candidates=veto_candidates,
        family=(nav_path or {}).get("family"),
        base_risk_level=risk,
        base_needs_review=needs_review,
        recommendation_confidence=(selected_score or {}).get("total"),
        gate_config=gate_config,
        query={**query, "veto_issue_routed": bool(veto_candidates)},
    )
    matched_vetoes = gate["matched_vetoes"]
    veto_ids = gate["veto_ids"]
    if gate["veto_hit"]:
        reason_parts.insert(0, f"选定推荐后命中 fail-cohort {len(veto_ids)} 条，已触发安全门控。")
    elif veto_candidates:
        reason_parts.append(f"同问题类型有 {len(veto_candidates)} 条否决背景，但当前推荐未直接命中。")
    risk = gate["risk_level"]
    needs_review = gate["needs_human_review"]

    if episode_pairs:
        sem = sum(1 for p in episode_pairs if p.get("has_semantic"))
        reason_parts.append(f"参考 {len(episode_pairs)} 条案例 episode（{sem} 条含语义层）。")

    nav_path_public = dict(nav_path) if nav_path else None
    if nav_path_public:
        nav_path_public.pop("_family_nodes", None)
        nav_path_public.pop("_candidate_family_nodes", None)
        nav_path_public["vetoes"] = matched_vetoes
        nav_path_public["veto_background_count"] = len(veto_candidates)

    ranked_ids = [_memory_id(m) for m in strategies + playbooks if _memory_id(m)]
    root_candidate_ids = [_memory_id(m) for m in strategies + playbooks if _memory_id(m) and _memory_matches_root(m, root)]
    param_candidate_ids = [_memory_id(m) for m in strategies + playbooks if _memory_id(m) and _memory_matches_param_clues(m, param_clues)]
    root_boosted = _merge_ranked_ids(root_candidate_ids, ranked_ids)
    param_boosted = _merge_ranked_ids(param_candidate_ids, root_boosted)
    final_ids = param_boosted[:8]
    strategy_ids: list[str] = []
    playbook_ids: list[str] = []
    candidate_scores: list[dict[str, Any]] = []
    for mid in final_ids:
        memory = memories_by_id.get(mid)
        if not memory:
            continue
        score_breakdown = memory_candidate_score_breakdown(
            memory,
            root,
            param_clues,
            use_bayesian_credibility=use_bayesian_credibility,
            query=query,
            ranker_config=ranker_config,
        )
        candidate_scores.append({
            "memory_id": mid,
            "memory_type": memory.get("memory_type"),
            "state": memory.get("state"),
            "rank_score": score_breakdown["total"],
            "score_breakdown": score_breakdown,
            "credibility_mode": "echo_lcb" if use_bayesian_credibility else "raw_pass_rate",
        })
        if memory.get("memory_type") == "playbook_memory" and len(playbook_ids) < 3:
            playbook_ids.append(mid)
        elif memory.get("memory_type") == "strategy_memory" and len(strategy_ids) < 5:
            strategy_ids.append(mid)

    walk_funnel = _build_walk_funnel(
        navigation_map=navigation_map,
        query=query,
        root=root,
        ranked_ids=ranked_ids,
        root_boosted=root_boosted,
        param_boosted=param_boosted,
        final_ids=final_ids,
    )

    return {
        "decision_id": _decision_id(trace.get("trace_id") or ""),
        "input_trace_id": trace.get("trace_id"),
        "query": query,
        "input_trace_redacted": ticket_only_trace_for_decision(trace),
        "decision_context_policy": "legacy_action_context" if allow_heldout_action_context else "ticket_only_v1",
        "recommended_action": recommended,
        "supporting_knowledge": {
            "strategy_memory_ids": strategy_ids,
            "playbook_memory_ids": playbook_ids,
            "final_candidate_ids": final_ids,
            "candidate_scores": candidate_scores,
            "episode_pairs": [
                {
                    "episode_id": p.get("episode_id"),
                    "candidate_id": p.get("candidate_id"),
                    "has_semantic": p.get("has_semantic"),
                }
                for p in episode_pairs
            ],
            "veto_memory_ids": veto_ids,
        },
        "navigation_path": nav_path_public,
        "walk_funnel": walk_funnel,
        "retrieved_episode_pairs": episode_pairs,
        "veto_checked": True,
        "veto_hits": veto_ids,
        "gate_decision": gate["gate_decision"],
        "gate_diagnostics": {
            "gate_policy": gate["gate_policy"],
            "gate_reason": gate["gate_reason"],
            "veto_hit": gate["veto_hit"],
            "veto_background_count": gate["veto_background_count"],
            "matched_veto_ids": veto_ids,
            "tau_low": gate.get("tau_low"),
            "tau_high": gate.get("tau_high"),
            "recommendation_confidence": gate.get("recommendation_confidence"),
            "threshold_band": gate.get("threshold_band"),
            "gate_config_version": gate.get("gate_config_version"),
            "failcohort_hit_score": gate.get("failcohort_hit_score", 0.0),
            "diagnostic_failcohort_hit_score": gate.get("diagnostic_failcohort_hit_score"),
            "diagnostic_veto_ids": gate.get("diagnostic_veto_ids") or [],
            "failcohort_matches": gate.get("failcohort_matches") or [],
            "veto_risk_calibration": gate.get("veto_risk_calibration") or {},
            "gray_zone_review": gate.get("gray_zone_review") or {},
            "hard_veto_eligible": gate.get("hard_veto_eligible"),
            "strong_action_veto_match": gate.get("strong_action_veto_match"),
        },
        "selected_score_breakdown": selected_score,
        "risk_level": risk,
        "decision_reason": " ".join(reason_parts),
        "needs_human_review": needs_review,
        "retrieval_notes": [
            "规则第三版：按 navigation_map 分层选路；正向候选仅 validated/reusable 策略与组合。",
            "根因标签与参数对象字段用于重排；restricted/counter_evidence 不进正向候选池，只进入门控证据池。",
            f"候选可信度排序：{'ECHO LCB' if use_bayesian_credibility else 'raw pass_rate'}。",
            "语义 episode 已与 candidate 绑定返回。",
        ],
        "produced_by": "shadow_navigation_rule_v1" if nav_path else "shadow_rule_v1",
        "created_at": cio.now_iso(),
    }


def shadow_evaluate(
    decision: dict[str, Any],
    trace: dict[str, Any],
    *,
    gold_action: dict[str, Any] | None = None,
    eval_unit_id: str | None = None,
    eval_split_id: str | None = None,
) -> dict[str, Any]:
    """Offline scorer — compares recommended_action vs action-level gold (set A)."""
    agg = trace.get("aggregate") or {}
    ticket_label = agg.get("ticket_outcome") or "long_eval_unknown"
    veto_hits = decision.get("veto_hits") or []
    hit_veto = len(veto_hits) > 0
    rec = decision.get("recommended_action") or {}
    recommended_action_set = extract_recommended_action_set(decision)
    predicted_scheme_group = (
        ((decision.get("navigation_path") or {}).get("family") or {}).get("scheme_group")
        or rec.get("scheme_group")
        or ""
    )

    gold_actions = eligible_gold_actions(trace)
    gold = gold_action or (gold_actions[0] if gold_actions else None)

    notes: list[str] = []
    if not gold:
        return {
            "decision_id": decision.get("decision_id"),
            "input_trace_id": decision.get("input_trace_id"),
            "eval_mode": "action_gold_a",
            "eval_unit_id": eval_unit_id,
            "label": ticket_label,
            "action_label": None,
            "gold_action": None,
            "gold_actions": [],
            "recommended_action": rec,
            "recommended_action_set": recommended_action_set,
            "action_set_evaluation": score_action_sets(recommended_action_set, []),
            "plan_score": None,
            "action_equivalence": None,
            "match_tier": "none",
            "match_scheme": False,
            "match_param": False,
            "match_delta": False,
            "matched_historical_action": False,
            "hit_counter_evidence": hit_veto,
            "recommended_scheme_hit": False,
            "score": 0.0,
            "notes": ["no_gold_action: 工单内无 exec_success+long_eval_pass 动作"],
            "eval_split_id": eval_split_id,
            "created_at": cio.now_iso(),
        }

    match = compare_recommended_to_gold(rec, gold)
    plan_score = best_plan_score(rec, gold_actions or [gold], predicted_scheme_group=predicted_scheme_group)
    action_equivalence = best_action_equivalence(rec, gold_actions or [gold], ticket=trace.get("ticket"))
    action_set_evaluation = score_action_sets(recommended_action_set, gold_actions or [gold])
    score = float(match["score"])
    if hit_veto:
        score = round(max(0.0, score - 0.15), 4)
        notes.append("veto_hit_penalty")

    return {
        "decision_id": decision.get("decision_id"),
        "input_trace_id": decision.get("input_trace_id"),
        "eval_mode": "action_gold_a",
        "eval_unit_id": eval_unit_id,
        "label": ticket_label,
        "action_label": "long_eval_pass",
        "gold_action": gold,
        "gold_actions": gold_actions,
        "gold_action_id": gold.get("action_id"),
        "recommended_action": rec,
        "recommended_action_set": recommended_action_set,
        "action_set_evaluation": action_set_evaluation,
        "plan_score": plan_score,
        "action_equivalence": action_equivalence,
        "match_tier": match["match_tier"],
        "match_scheme": match["match_scheme"],
        "match_param": match["match_param"],
        "match_delta": match["match_delta"],
        "matched_historical_action": match["match_scheme"],
        "hit_counter_evidence": hit_veto,
        "recommended_scheme_hit": match["match_scheme"],
        "score": score,
        "notes": notes,
        "eval_split_id": eval_split_id,
        "created_at": cio.now_iso(),
    }

"""Retrieve shadow knowledge: memories + bound episode pairs + veto."""

from __future__ import annotations

from typing import Any

# 影子正向候选池：与产品「可复用知识」一致，不含 restricted / counter_evidence。
# 强否决池保持只含 counter_evidence，避免 restricted 挤占真正反证证据。
# restricted 属于同一套状态机里的灰区复核证据，走 review_evidence/诊断通道。
SHADOW_POSITIVE_CANDIDATE_STATES = frozenset({"validated", "reusable"})
_MEMORY_ISSUE_INDEX_CACHE: dict[int, dict[str, list[dict[str, Any]]]] = {}


def is_shadow_positive_candidate(memory: dict[str, Any]) -> bool:
    mtype = memory.get("memory_type")
    if mtype not in {"strategy_memory", "playbook_memory"}:
        return False
    return memory.get("state") in SHADOW_POSITIVE_CANDIDATE_STATES


def _is_veto_pool_memory(memory: dict[str, Any]) -> bool:
    memory_type = memory.get("memory_type")
    state = memory.get("state")
    if memory_type == "counter_evidence_memory":
        return True
    return memory_type in {"strategy_memory", "playbook_memory"} and state == "counter_evidence"


def _is_review_evidence_memory(memory: dict[str, Any]) -> bool:
    return (
        memory.get("memory_type") in {"strategy_memory", "playbook_memory"}
        and memory.get("state") == "restricted"
    )


def _issue_match(memory: dict[str, Any], issue_type: str) -> bool:
    issues = memory.get("applicability", {}).get("issue_types") or []
    return issue_type in issues


def retrieve_episode_pairs(
    candidates: list[dict[str, Any]],
    episodes_by_id: dict[str, dict[str, Any]],
    query: dict[str, Any],
    *,
    limit: int = 5,
) -> list[dict[str, Any]]:
    """Always return candidate; attach semantic only when episode_id matches."""
    issue = query.get("issue_type") or ""
    scored: list[tuple[float, dict]] = []
    for cand in candidates:
        key = cand.get("episode_key") or {}
        if issue and key.get("issue_type") != issue:
            continue
        if query.get("vendor") and key.get("vendor") not in (None, query["vendor"]):
            continue
        if query.get("system") and key.get("system") not in (None, query["system"]):
            continue
        metrics = cand.get("metrics") or {}
        support = float(metrics.get("trace_count") or 0)
        pr = float(metrics.get("pass_rate") or 0)
        scored.append((support * 0.6 + pr * 40, cand))
    scored.sort(key=lambda x: x[0], reverse=True)
    pairs = []
    for _, cand in scored[:limit]:
        eid = cand.get("episode_id") or ""
        episode = episodes_by_id.get(eid)
        pairs.append({
            "episode_id": eid,
            "candidate_id": eid,
            "has_semantic": episode is not None,
            "candidate": cand,
            "episode": episode,
        })
    return pairs


def retrieve_memories(
    memories: list[dict[str, Any]],
    query: dict[str, Any],
    *,
    limit: int = 8,
) -> dict[str, list[dict[str, Any]]]:
    issue = query.get("issue_type") or ""
    strategies: list[tuple[float, dict]] = []
    playbooks: list[tuple[float, dict]] = []
    vetoes: list[dict[str, Any]] = []
    review_evidence: list[dict[str, Any]] = []

    for memory in _issue_bucket(memories, issue):
        mtype = memory.get("memory_type")
        if _is_veto_pool_memory(memory):
            vetoes.append(memory)
            continue
        if _is_review_evidence_memory(memory):
            review_evidence.append(memory)
            continue
        metrics = memory.get("metrics") or {}
        support = float(metrics.get("support_count") or 0)
        pr = float(metrics.get("pass_rate") or 0)
        score = support * 0.5 + pr * 50
        if mtype == "strategy_memory" and is_shadow_positive_candidate(memory):
            strategies.append((score, memory))
        elif mtype == "playbook_memory" and is_shadow_positive_candidate(memory):
            playbooks.append((score, memory))

    strategies.sort(key=lambda x: x[0], reverse=True)
    playbooks.sort(key=lambda x: x[0], reverse=True)
    return {
        "strategies": [m for _, m in strategies[:limit]],
        "playbooks": [m for _, m in playbooks[:limit]],
        "vetoes": vetoes[:limit],
        "review_evidence": review_evidence[:limit],
    }


def _issue_bucket(memories: list[dict[str, Any]], issue: str) -> list[dict[str, Any]]:
    cache_key = id(memories)
    index = _MEMORY_ISSUE_INDEX_CACHE.get(cache_key)
    if index is None:
        index = {}
        for memory in memories:
            issues = memory.get("applicability", {}).get("issue_types") or []
            for issue_type in issues:
                index.setdefault(str(issue_type), []).append(memory)
        _MEMORY_ISSUE_INDEX_CACHE.clear()
        _MEMORY_ISSUE_INDEX_CACHE[cache_key] = index
    if not issue:
        return []
    return index.get(str(issue), [])

