    "experiment_spec_hash": {"type": "string", "pattern": "^[a-f0-9]{64}$"},
    "readiness": {
      "type": "object",
      "required": ["ok", "checks"],
      "properties": {
        "ok": {"type": "boolean"},
        "checks": {"type": "object"}
      }
